# ---- [v10.19] P2P transport security hooks (TLS 1.3) - implementation lives in nebula_p2p_secure.py ----
# NEBULA_P2P_TLS = off | optional | required (default since v10.23; set optional only for old plaintext nodes).
_P2P_SEC_MOD = None


def _nebula_p2p_security():
    """The transport-security object, or None when nebula_p2p_secure.py is missing."""
    global _P2P_SEC_MOD
    if _P2P_SEC_MOD is None:
        try:
            import importlib as _il
            _P2P_SEC_MOD = _il.import_module("nebula_p2p_secure")
        except Exception:
            _P2P_SEC_MOD = False
            log.warning("nebula_p2p_secure.py not found - P2P traffic is NOT encrypted")
    return _P2P_SEC_MOD.get_security() if _P2P_SEC_MOD else None


def _nebula_p2p_required() -> bool:
    return os.environ.get("NEBULA_P2P_TLS", "required").strip().lower() == "required"


def _nebula_p2p_configure(data_dir) -> None:
    """Keep node.key / node.crt / known_peers.json inside the node's own data dir."""
    if not data_dir or _P2P_SEC_MOD is False:
        return
    _nebula_p2p_security()
    if _P2P_SEC_MOD:
        _P2P_SEC_MOD.configure(os.path.join(str(data_dir), "p2p_tls"))


def _nebula_p2p_wrap_inbound(conn):
    """Accepted socket -> socket to use, or None to refuse the peer."""
    sec = _nebula_p2p_security()
    if sec is None:
        if _nebula_p2p_required():
            try:
                conn.close()
            except Exception:
                pass
            return None
        return conn
    return sec.wrap_inbound(conn)


def _nebula_p2p_wrap_outbound(sock, host, port):
    """Connected socket -> socket to use (TLS if possible). Raises OSError when it must not be used."""
    sec = _nebula_p2p_security()
    if sec is None:
        if _nebula_p2p_required():
            try:
                sock.close()
            except Exception:
                pass
            raise OSError("NEBULA_P2P_TLS=required but nebula_p2p_secure.py is missing")
        return sock
    return sec.wrap_outbound(sock, host, port)
