# ================================================================
#  SECP256K1 ACCELERATION — libsecp256k1 ctypes binding
#  Attempts to load the native C library (1000x faster).
#  Falls back transparently to pure-Python Secp256k1 if not present.
#  Install: pip install coincurve  OR  apt install libsecp256k1-dev
# ================================================================

_LIBSECP_LOADED = False
_libsecp        = None

def _try_load_libsecp256k1():
    """
    Attempt to bind libsecp256k1.so via ctypes.
    Returns True if loaded, False if unavailable.
    """
    global _LIBSECP_LOADED, _libsecp
    import ctypes, ctypes.util, os
    # Common library names on Linux/macOS/Windows
    candidates = [
        "libsecp256k1.so.0",
        "libsecp256k1.so",
        "libsecp256k1.dylib",
        "secp256k1.dll",
    ]
    for name in candidates:
        try:
            lib = ctypes.CDLL(name)
            # Verify the symbols we need exist
            lib.secp256k1_context_create.restype  = ctypes.c_void_p
            lib.secp256k1_context_create.argtypes = [ctypes.c_uint]
            _libsecp = lib
            _LIBSECP_LOADED = True
            print("⚡ libsecp256k1 loaded — ECDSA running at native speed")
            return True
        except OSError:
            continue
    return False

_try_load_libsecp256k1()

# ── Accelerated sign/verify using coincurve if available ──────────
try:
    import coincurve as _coincurve  # pip install coincurve
    _COINCURVE = True

    class _FastECDSA:
        """
        Drop-in fast ECDSA using coincurve (wraps libsecp256k1).
        ~800x faster than pure Python for sign/verify.
        """
        @staticmethod
        def sign_fast(privkey_int: int, msg_hash: bytes):
            pk_bytes = privkey_int.to_bytes(32, 'big')
            key  = _coincurve.PrivateKey(pk_bytes)
            sig  = key.sign(msg_hash, hasher=None)
            # validate DER structure before parsing r and s
            # DER format: 0x30 [total_len] 0x02 [r_len] [r] 0x02 [s_len] [s]
            if len(sig) < 8 or sig[0] != 0x30 or sig[2] != 0x02:
                raise ValueError(f"coincurve returned malformed DER signature (len={len(sig)})")
            r_len = sig[3]
            if 4 + r_len + 2 > len(sig):
                raise ValueError("DER signature r-field overflows buffer")
            if sig[4 + r_len] != 0x02:
                raise ValueError("DER signature missing 0x02 tag before s")
            s_len = sig[4 + r_len + 1]
            if 4 + r_len + 2 + s_len > len(sig):
                raise ValueError("DER signature s-field overflows buffer")
            r = int.from_bytes(sig[4:4+r_len], 'big')
            s_off = 4 + r_len + 2
            s = int.from_bytes(sig[s_off:s_off+s_len], 'big')
            return r, s

        @staticmethod
        def verify_fast(pubkey_bytes: bytes, msg_hash: bytes,
                        r: int, s: int) -> bool:
            try:
                pub = _coincurve.PublicKey(pubkey_bytes)
                # Re-encode r,s as DER for coincurve
                def _enc(n):
                    b = n.to_bytes((n.bit_length()+7)//8, 'big')
                    return (b'\x00' + b) if b[0] >= 0x80 else b
                rb, sb = _enc(r), _enc(s)
                der = (b'\x30' + bytes([4+len(rb)+len(sb)]) +
                       b'\x02' + bytes([len(rb)]) + rb +
                       b'\x02' + bytes([len(sb)]) + sb)
                return pub.verify(der, msg_hash, hasher=None)
            except Exception:
                return False

    print("⚡ coincurve loaded — sign/verify at libsecp256k1 speed")

except ImportError:
    _COINCURVE = False
    _FastECDSA = None
    print("ℹ️  coincurve not found — using pure-Python ECDSA (install: pip install coincurve)")

# ── Monkey-patch Secp256k1 to use fast path when available ────────
def _patch_secp256k1_fast():
    if not _COINCURVE:
        return
    _orig_sign   = Secp256k1.sign
    _orig_verify = Secp256k1.verify_bytes

    @classmethod  # type: ignore
    def _fast_sign(cls, privkey: int, msg_hash: bytes):
        try:
            return _FastECDSA.sign_fast(privkey, msg_hash)
        except Exception:
            return _orig_sign.__func__(cls, privkey, msg_hash)

    @classmethod  # type: ignore
    def _fast_verify_bytes(cls, pubkey_bytes: bytes, msg_hash: bytes,
                           r: int, s: int) -> bool:
        try:
            return _FastECDSA.verify_fast(pubkey_bytes, msg_hash, r, s)
        except Exception:
            return _orig_verify.__func__(cls, pubkey_bytes, msg_hash, r, s)

    Secp256k1.sign         = _fast_sign
    Secp256k1.verify_bytes = _fast_verify_bytes

# NOTE: _patch_secp256k1_fast() is called AFTER Secp256k1 class definition below.



