# ================================================================
#  SECP256K1 — Real Elliptic Curve Cryptography
#  (same curve as Bitcoin — production-grade)
# ================================================================

class Secp256k1:
    """
    secp256k1 elliptic curve — same as Bitcoin
    y² = x³ + 7  (mod p)
    """
    P  = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
    N  = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
    A  = 0
    B  = 7
    Gx = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798
    Gy = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8

    @classmethod
    def point_add(cls, P1, P2):
        if P1 is None: return P2
        if P2 is None: return P1
        x1, y1 = P1
        x2, y2 = P2
        if x1 == x2:
            if y1 != y2: return None
            if y1 == 0: return None   # point doubling at y=0 → point at infinity
            m = (3 * x1 * x1 + cls.A) * pow(2 * y1, cls.P - 2, cls.P) % cls.P
        else:
            m = (y2 - y1) * pow(x2 - x1, cls.P - 2, cls.P) % cls.P
        x3 = (m * m - x1 - x2) % cls.P
        y3 = (m * (x1 - x3) - y1) % cls.P
        return x3, y3

    @classmethod
    def point_mul(cls, k: int, P):
        """
        Constant-time scalar multiplication using Montgomery Ladder.
        Replaces variable-time double-and-add with Montgomery
        ladder — executes identical operations regardless of key bits,
        preventing timing side-channel attacks on private keys.
        Always iterates exactly 256 bits (secp256k1 field width)
        regardless of k value — previous version used k.bit_length() which
        leaked private key information via measurable timing differences.
        Reference: https://cr.yp.to/bib/2003/joye-ladder.pdf
        """
        if k == 0:
            return None
        k = k % cls.N  # Reduce mod N
        R0 = None   # point at infinity
        R1 = P
        # Always process all 256 bits — constant time regardless of key value
        for i in range(255, -1, -1):
            bit = (k >> i) & 1
            if bit == 0:
                R1 = cls.point_add(R0, R1)
                R0 = cls.point_add(R0, R0)
            else:
                R0 = cls.point_add(R0, R1)
                R1 = cls.point_add(R1, R1)
        return R0

    @classmethod
    def G(cls):
        return cls.Gx, cls.Gy

    @classmethod
    def generate_keypair(cls) -> Tuple[int, Tuple[int,int]]:
        """Generate private key and public key point"""
        privkey = secrets.randbelow(cls.N - 1) + 1
        pubkey  = cls.point_mul(privkey, cls.G())
        return privkey, pubkey

    @classmethod
    def pubkey_to_bytes(cls, pubkey: Tuple[int,int], compressed: bool = True) -> bytes:
        x, y = pubkey
        if compressed:
            prefix = b'\x02' if y % 2 == 0 else b'\x03'
            return prefix + x.to_bytes(32, 'big')
        return b'\x04' + x.to_bytes(32, 'big') + y.to_bytes(32, 'big')

    @classmethod
    def privkey_to_bytes(cls, privkey: int) -> bytes:
        return privkey.to_bytes(32, 'big')

    @classmethod
    def sign(cls, privkey: int, msg_hash: bytes) -> Tuple[int, int]:
        """ECDSA signature (deterministic RFC 6979)"""
        z = int.from_bytes(msg_hash, 'big')
        k = cls._rfc6979_k(privkey, msg_hash)
        R = cls.point_mul(k, cls.G())
        r = R[0] % cls.N
        s = pow(k, cls.N - 2, cls.N) * (z + r * privkey) % cls.N
        if s > cls.N // 2:
            s = cls.N - s
        return r, s

    @classmethod
    def verify(cls, pubkey: Tuple[int,int], msg_hash: bytes, sig: Tuple[int,int]) -> bool:
        """Verify ECDSA signature"""
        r, s = sig
        if not (1 <= r < cls.N and 1 <= s < cls.N):
            return False
        # reject high-S (malleable) signatures. libsecp256k1/coincurve
        # already rejects them, so without this nodes with and without coincurve
        # would disagree on validity (consensus split).
        if s > cls.N // 2:
            return False
        # public key must be a valid point on y^2 = x^3 + 7 (mod P).
        try:
            _px, _py = pubkey
        except (TypeError, ValueError):
            return False
        if not (0 <= _px < cls.P and 0 <= _py < cls.P):
            return False
        if (_py * _py - _px * _px * _px - cls.B) % cls.P != 0:
            return False
        z  = int.from_bytes(msg_hash, 'big')
        w  = pow(s, cls.N - 2, cls.N)
        u1 = z * w % cls.N
        u2 = r * w % cls.N
        point = cls.point_add(cls.point_mul(u1, cls.G()), cls.point_mul(u2, pubkey))
        if point is None:
            return False
        return point[0] % cls.N == r

    @classmethod
    def verify_sig(cls, pubkey, msg_hash: bytes, sig) -> bool:
        """
        Universal ECDSA verify: accepts pubkey as bytes OR tuple, sig as tuple OR (r,s).
        verify_sig(compressed_pubkey_bytes, msg32, (r,s)) -> bool   (33 bytes, 0x02/0x03)
        verify_sig(uncompressed_pubkey_bytes, msg32, (r,s)) -> bool (65 bytes, 0x04)
        verify_sig(pubkey_point_tuple, msg32, (r,s)) -> bool
        Correctly handles uncompressed pubkeys (0x04 prefix, 65 bytes).
        Previous code read pubkey[1:] for all byte keys, giving 64 bytes for uncompressed
        keys which computed a completely wrong x value.
        """
        # Decode pubkey
        if isinstance(pubkey, bytes):
            prefix = pubkey[0]
            P = cls.P
            if prefix == 0x04:
                # Uncompressed: 0x04 || x(32) || y(32)
                if len(pubkey) != 65:
                    return False
                x = int.from_bytes(pubkey[1:33], 'big')
                y = int.from_bytes(pubkey[33:65], 'big')
            elif prefix in (0x02, 0x03):
                # Compressed: 0x02/0x03 || x(32)
                if len(pubkey) != 33:
                    return False
                x    = int.from_bytes(pubkey[1:], 'big')
                y_sq = (pow(x, 3, P) + 7) % P
                y    = pow(y_sq, (P + 1) // 4, P)
                if (y % 2 == 0) != (prefix == 0x02):
                    y = P - y
            else:
                return False
            pubkey = (x, y)
        # Decode sig
        if isinstance(sig, (list, tuple)) and len(sig) == 2:
            r, s = sig
        else:
            return False
        return cls.verify(pubkey, msg_hash, (r, s))

    @classmethod
    def verify_bytes(cls, pubkey_bytes: bytes, msg_hash: bytes, r: int, s: int) -> bool:
        """Verify ECDSA signature from compressed pubkey bytes + r,s ints"""
        # reject uncompressed keys (65 bytes, prefix 0x04) and invalid lengths
        if len(pubkey_bytes) != 33 or pubkey_bytes[0] not in (0x02, 0x03):
            return False
        x = int.from_bytes(pubkey_bytes[1:], 'big')
        P = cls.P
        y_sq = (pow(x, 3, P) + 7) % P
        y = pow(y_sq, (P+1)//4, P)
        if (y % 2 == 0) != (pubkey_bytes[0] == 0x02):
            y = P - y
        return cls.verify((x, y), msg_hash, (r, s))


    @classmethod
    def _rfc6979_k(cls, privkey: int, msg_hash: bytes) -> int:
        """Deterministic k generation per RFC 6979"""
        x = privkey.to_bytes(32, 'big')
        h = msg_hash
        V = b'\x01' * 32
        K = b'\x00' * 32
        K = hmac.new(K, V + b'\x00' + x + h, hashlib.sha256).digest()
        V = hmac.new(K, V, hashlib.sha256).digest()
        K = hmac.new(K, V + b'\x01' + x + h, hashlib.sha256).digest()
        V = hmac.new(K, V, hashlib.sha256).digest()
        while True:
            V = hmac.new(K, V, hashlib.sha256).digest()
            k = int.from_bytes(V, 'big')
            if 1 <= k < cls.N:
                return k
            K = hmac.new(K, V + b'\x00', hashlib.sha256).digest()
            V = hmac.new(K, V, hashlib.sha256).digest()

    @classmethod
    def sig_to_der(cls, r: int, s: int) -> bytes:
        """Encode signature in DER format (used in scripts)"""
        def encode_int(n):
            b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
            if b[0] >= 0x80:
                b = b'\x00' + b
            return b
        rb = encode_int(r)
        sb = encode_int(s)
        return (b'\x30' + bytes([4 + len(rb) + len(sb)]) +
                b'\x02' + bytes([len(rb)]) + rb +
                b'\x02' + bytes([len(sb)]) + sb)

    @classmethod
    def sig_from_der(cls, der: bytes) -> Tuple[int, int]:
        """Decode DER-encoded signature.
        Replaced bare assert statements with proper ValueError
        raises so validation is never bypassed when Python runs with -O flag."""
        if not der or len(der) < 8:
            raise ValueError("DER signature too short")
        if der[0] != 0x30:
            raise ValueError(f"Invalid DER: expected sequence tag 0x30, got {hex(der[0])}")
        if der[2] != 0x02:
            raise ValueError(f"Invalid DER: expected integer tag 0x02 for r, got {hex(der[2])}")
        rlen = der[3]
        if len(der) < 4 + rlen + 2:
            raise ValueError("Invalid DER: r value truncated")
        r = int.from_bytes(der[4:4+rlen], 'big')
        if der[4+rlen] != 0x02:
            raise ValueError(f"Invalid DER: expected integer tag 0x02 for s, got {hex(der[4+rlen])}")
        slen = der[5+rlen]
        if len(der) < 6 + rlen + slen:
            raise ValueError("Invalid DER: s value truncated")
        s = int.from_bytes(der[6+rlen:6+rlen+slen], 'big')
        return r, s

# Secp256k1 class is now fully defined — safe to patch with fast path.
_patch_secp256k1_fast()

# ── ECDSA convenience wrapper ─────────────────────────────────────
# ECDSA.sign(msg_hash, privkey) -> DER bytes
# Used by wallet signing code that expects (msg_hash, privkey) argument order
# and a DER-encoded bytes return value (not an (r, s) tuple).
class ECDSA:
    @staticmethod
    def sign(msg_hash: bytes, privkey: int) -> bytes:
        """Sign msg_hash with privkey. Returns DER-encoded signature bytes."""
        r, s = Secp256k1.sign(privkey, msg_hash)
        return Secp256k1.sig_to_der(r, s)

    @staticmethod
    def verify(pubkey_bytes: bytes, msg_hash: bytes, sig_der: bytes) -> bool:
        """Verify a DER-encoded signature against a compressed pubkey."""
        try:
            r, s = Secp256k1.sig_from_der(sig_der)
            return Secp256k1.verify_bytes(pubkey_bytes, msg_hash, r, s)
        except Exception:
            return False

def sha256(data: bytes) -> bytes:
    return hashlib.sha256(data).digest()

def sha256d(data: bytes) -> bytes:
    """Double SHA-256 — used everywhere in Bitcoin/NEBULA"""
    return hashlib.sha256(hashlib.sha256(data).digest()).digest()

def sha256d_hex(data: bytes) -> str:
    return sha256d(data).hex()

def hash160(data: bytes) -> bytes:
    """RIPEMD160(SHA256(data)) — used for addresses"""
    h = hashlib.new('ripemd160')
    h.update(hashlib.sha256(data).digest())
    return h.digest()

def hash256(data: bytes) -> bytes:
    return sha256d(data)

# ================================================================
#  BASE58CHECK — address encoding
# ================================================================

BASE58_ALPHABET = b'123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'

def base58_encode(data: bytes) -> str:
    count = 0
    for byte in data:
        if byte == 0: count += 1
        else: break
    num = int.from_bytes(data, 'big')
    res = []
    while num > 0:
        num, rem = divmod(num, 58)
        res.append(chr(BASE58_ALPHABET[rem]))
    return '1' * count + ''.join(reversed(res))

def base58_decode(s: str) -> bytes:
    count = 0
    for c in s:
        if c == '1': count += 1
        else: break
    num = 0
    for c in s:
        num = num * 58 + BASE58_ALPHABET.index(ord(c))
    result = []
    while num > 0:
        num, rem = divmod(num, 256)
        result.append(rem)
    return bytes([0] * count + list(reversed(result)))

def base58check_encode(payload: bytes, version: int) -> str:
    versioned = bytes([version]) + payload
    checksum  = sha256d(versioned)[:4]
    return base58_encode(versioned + checksum)

def pubkey_to_address(pubkey: bytes) -> str:
    """P2PKH address (version PUBKEY_ADDRESS_VERSION) from a serialized public key."""
    if not isinstance(pubkey, (bytes, bytearray)):
        pubkey = Secp256k1.pubkey_to_bytes(pubkey)
    return base58check_encode(hash160(bytes(pubkey)), PUBKEY_ADDRESS_VERSION)

def base58check_decode(s: str) -> Tuple[int, bytes]:
    raw      = base58_decode(s)
    version  = raw[0]
    payload  = raw[1:-4]
    checksum = raw[-4:]
    if sha256d(raw[:-4])[:4] != checksum:
        raise ValueError("Invalid base58check checksum")
    return version, payload

# ================================================================
#  SCRIPT — locking / unlocking scripts
# ================================================================

class ScriptType(Enum):
    P2PKH   = "p2pkh"    # Pay to Public Key Hash (most common)
    P2PK    = "p2pk"     # Pay to Public Key
    P2SH    = "p2sh"     # Pay to Script Hash
    NULLDATA = "nulldata" # OP_RETURN data
    UNKNOWN = "unknown"

class Script:
    """Bitcoin-compatible script system"""

    @staticmethod
    def p2pkh_locking(pubkey_hash: bytes) -> bytes:
        """OP_DUP OP_HASH160 <pubKeyHash> OP_EQUALVERIFY OP_CHECKSIG"""
        return (bytes([OP_DUP, OP_HASH160, len(pubkey_hash)]) +
                pubkey_hash +
                bytes([OP_EQUALVERIFY, OP_CHECKSIG]))

    @staticmethod
    def p2pkh_unlocking(sig_der: bytes, pubkey_compressed: bytes) -> bytes:
        """<sig> <pubKey>"""
        return (bytes([len(sig_der)]) + sig_der +
                bytes([len(pubkey_compressed)]) + pubkey_compressed)

    @staticmethod
    def p2pkh_address(pubkey_bytes: bytes) -> str:
        """Generate NBL address from compressed public key"""
        h160 = hash160(pubkey_bytes)
        return base58check_encode(h160, PUBKEY_ADDRESS_VERSION)

    @staticmethod
    def address_to_hash160(address: str) -> bytes:
        version, payload = base58check_decode(address)
        return payload

    @staticmethod
    def p2pkh_locking_from_address(address: str) -> bytes:
        # [v10.24] version-aware: a script-address ("M...") now gets a real P2SH locking script
        # (OP_HASH160 <20> OP_EQUAL). Before, it got a P2PKH script around the SCRIPT hash = coins nobody could spend.
        version, payload = base58check_decode(address)
        if len(payload) != 20:
            raise ValueError("address payload must be 20 bytes")
        if version == SCRIPT_ADDRESS_VERSION:
            return bytes([OP_HASH160, 0x14]) + payload + bytes([OP_EQUAL])
        return Script.p2pkh_locking(payload)

    @staticmethod
    def nulldata(data: bytes) -> bytes:
        """OP_RETURN <data> — unspendable, stores data"""
        if len(data) > 80:  # assert disabled under python -O; use explicit raise
            raise ValueError(f"OP_RETURN data max 80 bytes, got {len(data)}")
        return bytes([OP_RETURN, len(data)]) + data

    @staticmethod
    def classify(script: bytes) -> ScriptType:
        if (len(script) == 25 and script[0] == OP_DUP and
                script[1] == OP_HASH160 and script[2] == 0x14 and
                script[23] == OP_EQUALVERIFY and script[24] == OP_CHECKSIG):
            return ScriptType.P2PKH
        # [v10.23] P2SH: OP_HASH160 <20 bytes> OP_EQUAL (23 bytes)
        if (len(script) == 23 and script[0] == OP_HASH160 and script[1] == 0x14 and
                script[22] == OP_EQUAL):
            return ScriptType.P2SH
        if len(script) >= 2 and script[0] == OP_RETURN:
            return ScriptType.NULLDATA
        return ScriptType.UNKNOWN

    @staticmethod
    def verify_p2pkh(locking: bytes, unlocking: bytes, tx_hash: bytes) -> bool:
        """Verify P2PKH script execution"""
        try:
            # Parse unlocking script
            sig_len = unlocking[0]
            sig_der = unlocking[1:1+sig_len]
            pub_len = unlocking[1+sig_len]
            pubkey  = unlocking[2+sig_len:2+sig_len+pub_len]

            # PATCH (malleability): third parties could change the txid without
            # invalidating the tx (junk after pubkey, any sighash byte, lax DER).
            def _strict_der(d):
                if len(d) < 8 or len(d) > 72 or d[0] != 0x30 or d[1] != len(d) - 2 or d[2] != 0x02:
                    return False
                rl = d[3]
                if rl == 0 or 5 + rl >= len(d) or d[4 + rl] != 0x02:
                    return False
                sl = d[5 + rl]
                if sl == 0 or 6 + rl + sl != len(d):
                    return False
                for off, ln in ((4, rl), (6 + rl, sl)):
                    b = d[off:off + ln]
                    if b[0] & 0x80 or (ln > 1 and b[0] == 0 and not (b[1] & 0x80)):
                        return False
                return True
            if len(unlocking) != 2 + sig_len + pub_len or pub_len != 33 or pubkey[0] not in (2, 3):
                return False
            if sig_der[-1] != 0x01 or not _strict_der(sig_der[:-1]):
                return False

            # Parse locking script
            pubkey_hash_from_script = locking[3:23]

            # Check pubkey hash matches
            if hash160(pubkey) != pubkey_hash_from_script:
                return False

            # Verify signature
            r, s   = Secp256k1.sig_from_der(sig_der[:-1])  # strip sighash byte
            x      = int.from_bytes(pubkey[1:33], 'big')
            prefix = pubkey[0]
            p      = Secp256k1.P
            y_sq   = (pow(x, 3, p) + 7) % p
            y      = pow(y_sq, (p+1)//4, p)
            if (y % 2 == 0) != (prefix == 0x02):
                y = p - y
            pub_point = (x, y)

            return Secp256k1.verify(pub_point, tx_hash, (r, s))
        except Exception:
            return False

# ================================================================
#  TRANSACTION INPUT / OUTPUT
# ================================================================

SIGHASH_ALL         = 0x01
SIGHASH_NONE        = 0x02
SIGHASH_SINGLE      = 0x03
SIGHASH_ANYONECANPAY = 0x80  # FIX added

@dataclass
class OutPoint:
    """Reference to a previous transaction output"""
    txid:  str   # 32-byte hex
    index: int   # output index (uint32)

    def serialize(self) -> bytes:
        return bytes.fromhex(self.txid)[::-1] + struct.pack('<I', self.index)

    @classmethod
    def null(cls) -> 'OutPoint':
        return cls(txid='0'*64, index=0xFFFFFFFF)

    def is_null(self) -> bool:
        return self.txid == '0'*64 and self.index == 0xFFFFFFFF

@dataclass
class TxInput:
    outpoint:   OutPoint
    script_sig: bytes = b''
    sequence:   int   = 0xFFFFFFFF

    def serialize(self) -> bytes:
        script_bytes = encode_varint(len(self.script_sig)) + self.script_sig
        return (self.outpoint.serialize() +
                script_bytes +
                struct.pack('<I', self.sequence))

    @property
    def is_coinbase(self) -> bool:
        return self.outpoint.is_null()

@dataclass
class TxOutput:
    value:        int    # amount in Neb (satoshi-equivalent)
    script_pubkey: bytes  # locking script

    def serialize(self) -> bytes:
        return (struct.pack('<q', self.value) +
                encode_varint(len(self.script_pubkey)) +
                self.script_pubkey)

    @property
    def address(self) -> Optional[str]:
        st = Script.classify(self.script_pubkey)
        if st == ScriptType.P2PKH:
            h160 = self.script_pubkey[3:23]
            return base58check_encode(h160, PUBKEY_ADDRESS_VERSION)
        if st == ScriptType.P2SH:   # [v10.23]
            return base58check_encode(self.script_pubkey[2:22], SCRIPT_ADDRESS_VERSION)
        return None

class TransactionOutput:
    """Extended transaction output with explicit address field."""
    def __init__(self, value: int, address: str = "",
                  script: bytes = b""):
        self.value        = value
        self.address      = address
        self.script_pubkey = script if script else (
            P2PKHScript.lock(address) if address else b"")

    def serialize(self) -> bytes:
        sp = self.script_pubkey
        return (struct.pack('<q', self.value) +
                encode_varint(len(sp)) + sp)

    def total_output(self) -> int:
        return self.value

# ================================================================
#  VARINT — variable-length integer encoding
# ================================================================

def encode_varint(n: int) -> bytes:
    if n < 0xfd:
        return bytes([n])
    elif n <= 0xffff:
        return b'\xfd' + struct.pack('<H', n)
    elif n <= 0xffffffff:
        return b'\xfe' + struct.pack('<I', n)
    else:
        return b'\xff' + struct.pack('<Q', n)

def decode_varint(data: bytes, offset: int = 0) -> Tuple[int, int]:
    first = data[offset]
    if first < 0xfd:
        return first, offset + 1
    elif first == 0xfd:
        return struct.unpack_from('<H', data, offset+1)[0], offset + 3
    elif first == 0xfe:
        return struct.unpack_from('<I', data, offset+1)[0], offset + 5
    else:
        return struct.unpack_from('<Q', data, offset+1)[0], offset + 9

# ================================================================
#  TRANSACTION
# ================================================================

class Transaction:
    """
    Full Bitcoin-compatible transaction.
    Supports P2PKH inputs/outputs, coinbase, multi-output.
    """

    def __init__(self,
                 version:  int = 1,
                 inputs:   List[TxInput]  = None,
                 outputs:  List[TxOutput] = None,
                 locktime: int = 0):
        self.version  = version
        self.inputs   = inputs  or []
        self.outputs  = outputs or []
        self.locktime = locktime
        self._txid    = None

    # ── Serialization ──────────────────────────────────────────
    def serialize(self) -> bytes:
        out  = struct.pack('<i', self.version)
        out += encode_varint(len(self.inputs))
        for inp in self.inputs:
            out += inp.serialize()
        out += encode_varint(len(self.outputs))
        for txout in self.outputs:
            out += txout.serialize()
        out += struct.pack('<I', self.locktime)
        return out

    @property
    def txid(self) -> str:
        if self._txid is None:
            self._txid = sha256d(self.serialize())[::-1].hex()
        return self._txid

    def invalidate_cache(self):
        self._txid = None

    # ── Signing hash ───────────────────────────────────────────
    def signature_hash(self, input_index: int, subscript: bytes,
                        sighash_type: int = SIGHASH_ALL) -> bytes:
        """
        Compute the hash that is signed for a specific input.
        FIX correctly implement SIGHASH_ALL, SIGHASH_NONE, SIGHASH_SINGLE.
        """
        base_type = sighash_type & 0x1f
        anyone_can_pay = bool(sighash_type & SIGHASH_ANYONECANPAY)

        # Build inputs
        if anyone_can_pay:
            # SIGHASH_ANYONECANPAY: only sign the one input
            inputs = [TxInput(self.inputs[input_index].outpoint,
                              subscript,
                              self.inputs[input_index].sequence)]
        else:
            inputs = []
            for i, inp in enumerate(self.inputs):
                script = subscript if i == input_index else b''
                # SIGHASH_NONE / SIGHASH_SINGLE: set sequence=0 for other inputs
                seq = inp.sequence if (i == input_index or base_type == SIGHASH_ALL) else 0
                inputs.append(TxInput(inp.outpoint, script, seq))

        # Build outputs
        if base_type == SIGHASH_ALL:
            outputs = list(self.outputs)
        elif base_type == SIGHASH_NONE:
            outputs = []
        elif base_type == SIGHASH_SINGLE:
            # Bitcoin SIGHASH_SINGLE bug: if input_index >= len(outputs), return hash of 1
            if input_index >= len(self.outputs):
                return b'\x01' + b'\x00' * 31   # known Bitcoin SIGHASH_SINGLE bug value
            # Only keep output at input_index; set others to value=-1, script=b''
            outputs = []
            for i in range(input_index + 1):
                if i == input_index:
                    outputs.append(self.outputs[input_index])
                else:
                    # Bitcoin standard requires value=-1 (signed int64).
                    # 0xFFFFFFFFFFFFFFFF overflows struct.pack('<q',...) → crash.
                    # 1 serializes correctly as 0xFFFFFFFFFFFFFFFF in little-endian.
                    outputs.append(TxOutput(value=-1, script_pubkey=b''))
        else:
            # Unknown sighash type — fall back to ALL
            outputs = list(self.outputs)

        tx_copy = Transaction(
            version  = self.version,
            inputs   = inputs,
            outputs  = outputs,
            locktime = self.locktime,
        )
        raw = tx_copy.serialize() + struct.pack('<I', sighash_type)
        return sha256d(raw)

    # ── Validation ─────────────────────────────────────────────
    @property
    def is_coinbase(self) -> bool:
        return (len(self.inputs) == 1 and
                self.inputs[0].outpoint.is_null())

    def total_output(self) -> int:
        return sum(o.value for o in self.outputs)

    def total_input(self, utxo_set: 'UTXOSet') -> int:
        if self.is_coinbase:
            return 0
        total = 0
        for inp in self.inputs:
            utxo = utxo_set.get(inp.outpoint.txid, inp.outpoint.index)
            if utxo:
                total += utxo.value
        return total

    def fee(self, utxo_set: 'UTXOSet') -> int:
        if self.is_coinbase:
            return 0
        return max(0, self.total_input(utxo_set) - self.total_output())

    def byte_size(self) -> int:
        return len(self.serialize())

    def to_dict(self) -> dict:
        return {
            "txid":     self.txid,
            "version":  self.version,
            "size":     self.byte_size(),
            "locktime": self.locktime,
            "coinbase": self.is_coinbase,
            "vin": [{
                "txid":           i.outpoint.txid,
                "vout":           i.outpoint.index,
                "sequence":       i.sequence,
                "coinbase":       i.is_coinbase,
                "script_sig_hex": i.script_sig.hex(),
            } for i in self.inputs],
            "vout": [{
                "value_neb":        o.value,
                "value_nbl":        f"{o.value / 10**DECIMALS:.{DECIMALS}f}",
                "address":          o.address,
                "n":                idx,
                "script_pubkey_hex": o.script_pubkey.hex(),
            } for idx, o in enumerate(self.outputs)],
        }

    # ── Factory: coinbase ──────────────────────────────────────
    @classmethod
    def coinbase(cls, height: int, reward: int, miner_address: str,
                 extra_data: bytes = b'') -> 'Transaction':
        """
        Build coinbase transaction.
        2% of block reward goes to FOUNDATION_ADDRESS (NEBULA Core Team),
        98% goes to the miner.  Both outputs are in the same coinbase tx
        so the split is transparent and verifiable on-chain.
        Genesis block (height 0) keeps 100% at foundation address.
        """
        height_script = (encode_varint(height.bit_length() // 8 + 1) +
                         height.to_bytes((height.bit_length() + 7) // 8, 'little'))
        cb_script = height_script + extra_data + GENESIS_MESSAGE[:40].encode()

        cb_input = TxInput(
            outpoint   = OutPoint.null(),
            script_sig = cb_script[:100],
            sequence   = 0xFFFFFFFF,
        )

        outputs = []

        # ── Foundation split ──────────────────────────────────
        foundation_share = int(reward * FOUNDATION_RATE)
        miner_share      = reward - foundation_share

        # Always pay miner first (output index 0)
        if miner_address and miner_address != FOUNDATION_ADDRESS:
            miner_out = TxOutput(
                value         = miner_share,
                script_pubkey = Script.p2pkh_locking_from_address(miner_address),
            )
            outputs.append(miner_out)
            if foundation_share >= DUST_THRESHOLD:
                foundation_out = TxOutput(
                    value         = foundation_share,
                    script_pubkey = Script.p2pkh_locking_from_address(FOUNDATION_ADDRESS),
                )
                outputs.append(foundation_out)
        else:
            outputs.append(TxOutput(
                value         = reward,
                script_pubkey = Script.p2pkh_locking_from_address(
                    miner_address if miner_address else FOUNDATION_ADDRESS),
            ))

        return cls(version=1, inputs=[cb_input], outputs=outputs)

# ================================================================
#  MERKLE TREE — Real Merkle Tree
# ================================================================

class MerkleTree:
    """Bitcoin-compatible Merkle tree"""

    @staticmethod
    def compute_root(txids: List[str]) -> str:
        if not txids:
            return '00' * 32
        layer = [bytes.fromhex(txid)[::-1] for txid in txids]
        while len(layer) > 1:
            if len(layer) % 2 == 1:
                layer.append(layer[-1])
            layer = [sha256d(layer[i] + layer[i+1])
                     for i in range(0, len(layer), 2)]
        return layer[0][::-1].hex()

    @staticmethod
    def build_proof(txids: List[str], target_txid: str) -> List[Tuple[str, str]]:
        """Build Merkle inclusion proof for a transaction"""
        if target_txid not in txids:
            return []
        layer  = [bytes.fromhex(t)[::-1] for t in txids]
        idx    = txids.index(target_txid)
        proof  = []
        while len(layer) > 1:
            if len(layer) % 2 == 1:
                layer.append(layer[-1])
            sibling_idx = idx ^ 1
            direction   = 'right' if idx % 2 == 0 else 'left'
            proof.append((direction, layer[sibling_idx][::-1].hex()))
            layer = [sha256d(layer[i] + layer[i+1]) for i in range(0, len(layer), 2)]
            idx //= 2
        return proof

    @staticmethod
    def verify_proof(root: str, txid: str, proof: List[Tuple[str, str]]) -> bool:
        """Verify a Merkle inclusion proof"""
        current = bytes.fromhex(txid)[::-1]
        for direction, sibling_hex in proof:
            sibling = bytes.fromhex(sibling_hex)[::-1]
            if direction == 'right':
                current = sha256d(current + sibling)
            else:
                current = sha256d(sibling + current)
        return current[::-1].hex() == root

# ================================================================
#  BLOCK HEADER
# ================================================================

class BlockHeader:
    """80-byte block header — identical structure to Bitcoin"""

    SIZE = 80

    def __init__(self,
                 version:     int,
                 prev_hash:   str,
                 merkle_root: str,
                 timestamp:   int,
                 bits:        int,
                 nonce:       int,
                 height:      int = 0):
        self.version     = version
        self.prev_hash   = prev_hash
        self.merkle_root = merkle_root
        self.timestamp   = timestamp
        self.bits        = bits
        self.nonce       = nonce
        self.height      = height   # stored separately (not in raw header)

    def serialize(self) -> bytes:
        """Serialize 80-byte header (without height, for hashing)"""  # was wrong "76-byte"; actual = 4+32+32+4+4+4 = 80
        return (struct.pack('<i', self.version) +
                bytes.fromhex(self.prev_hash)[::-1] +
                bytes.fromhex(self.merkle_root)[::-1] +
                struct.pack('<I', self.timestamp) +
                struct.pack('<I', self.bits) +
                struct.pack('<I', self.nonce))

    def hash(self) -> str:
        """Double SHA-256 of the 76-byte header"""
        return sha256d(self.serialize())[::-1].hex()

    @property
    def target(self) -> int:
        return bits_to_target(self.bits)

    def meets_target(self) -> bool:
        return int(self.hash(), 16) < self.target

    def to_dict(self) -> dict:
        return {
            "version":     self.version,
            "prev_hash":   self.prev_hash,
            "merkle_root": self.merkle_root,
            "timestamp":   self.timestamp,
            "bits":        hex(self.bits),
            "nonce":       self.nonce,
            "height":      self.height,
        }

# ================================================================
#  DIFFICULTY ENGINE
# ================================================================

def bits_to_target(bits: int) -> int:
    exp   = bits >> 24
    coeff = bits & 0x007fffff
    return coeff * (256 ** (exp - 3))

def target_to_bits(target: int) -> int:
    if target == 0:
        return 0
    nbytes = (target.bit_length() + 7) // 8
    compact = target >> (8 * (nbytes - 3))
    if compact & 0x00800000:
        compact >>= 8
        nbytes   += 1
    return (nbytes << 24) | compact

def compute_next_bits(old_bits: int, actual_timespan: int) -> int:
    """Retarget difficulty every DIFFICULTY_WINDOW blocks"""
    expected = DIFFICULTY_WINDOW * TARGET_BLOCK_TIME
    # Clamp to 4x range
    actual_timespan = max(expected // MAX_DIFFICULTY_CHANGE,
                          min(actual_timespan, expected * MAX_DIFFICULTY_CHANGE))
    new_target = bits_to_target(old_bits) * actual_timespan // expected
    # Never go below minimum difficulty
    max_target = bits_to_target(INITIAL_BITS)
    new_target = min(new_target, max_target)
    return target_to_bits(new_target)

def lwma_next_bits(chain, prev_height: int) -> int:
    """[v10.25e] Linearly Weighted Moving Average difficulty (per block, integer maths only, deterministic).
    Looks at the last LWMA_WINDOW blocks ending at chain[prev_height]; recent blocks weigh more.
        new_target = avg_target * sum(i * solvetime_i) / (T * n(n+1)/2)
    * solvetime is clamped to [1, 6*T] seconds (limits timestamp games);
    * the link from the genesis block is ignored (the genesis timestamp is fixed in the past);
    * the result may change at most 2x per block and never exceeds MAX_TARGET (easiest allowed difficulty)."""
    T = TARGET_BLOCK_TIME
    n = min(LWMA_WINDOW, prev_height)
    prev_bits = chain[prev_height].header.bits
    if n < 1:
        return prev_bits
    sum_target = 0
    weighted   = 0
    for i in range(1, n + 1):
        idx = prev_height - n + i
        blk = chain[idx]
        if idx - 1 == 0:
            st = T                                            # genesis link ignored
        else:
            st = blk.header.timestamp - chain[idx - 1].header.timestamp
            st = max(1, min(6 * T, st))
        weighted   += st * i
        sum_target += bits_to_target(blk.header.bits)
    avg_target = sum_target // n
    k          = n * (n + 1) // 2
    new_target = avg_target * weighted // (T * k)
    prev_target = bits_to_target(prev_bits)
    new_target  = max(prev_target // 2, min(new_target, prev_target * 2))
    new_target  = max(1, min(new_target, MAX_TARGET))
    return target_to_bits(new_target)

def mining_reward(height: int) -> int:
    """Block reward with halving schedule.
    FIX: negative height safely returns 0 instead of crashing."""
    if height < 0:
        return 0
    era = height // HALVING_INTERVAL
    if era >= 64:
        return 0
    return INITIAL_BLOCK_REWARD >> era

def halving_era(height: int) -> dict:
    """Return information about the current halving era for a given height"""
    era              = height // HALVING_INTERVAL
    blocks_this_era  = height % HALVING_INTERVAL
    blocks_remaining = HALVING_INTERVAL - blocks_this_era
    reward           = mining_reward(height)
    era_names = {
        0: "Era I — Genesis (2025–2029)",
        1: "Era II (2029–2033)",
        2: "Era III (2033–2037)",
        3: "Era IV (2037–2041)",
        4: "Era V (2041–2045)",
        5: "Era VI (2045–2049)",
    }
    return {
        "era":             era,
        "era_name":        era_names.get(era, f"Era {era+1}"),
        "reward_nbl":      f"{reward / 10**DECIMALS:.9f}",
        "blocks_mined":    blocks_this_era,
        "blocks_remaining":blocks_remaining,
        "next_halving_at": (era + 1) * HALVING_INTERVAL,
        "pct_complete":    f"{blocks_this_era / HALVING_INTERVAL * 100:.2f}%",
    }

def _encrypt_mnemonic(mnemonic: str, password: str) -> dict:
    """
    Encrypt mnemonic with PBKDF2-HMAC-SHA256 + XOR stream cipher.
    No external dependencies — uses only standard library.
    Format: {"salt": hex, "iv": hex, "ct": hex, "mac": hex}
    """
    salt    = secrets.token_bytes(16)
    iv      = secrets.token_bytes(16)
    # Derive 64-byte key via PBKDF2
    key     = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200_000, dklen=64)
    enc_key = key[:32]
    mac_key = key[32:]
    # XOR-stream encryption (deterministic, secure with random IV)
    data    = mnemonic.encode('utf-8')
    pad     = hashlib.pbkdf2_hmac('sha256', enc_key, iv, 1, dklen=len(data))
    ct      = bytes(a ^ b for a, b in zip(data, pad))
    # HMAC authentication tag
    mac     = hmac.new(mac_key, salt + iv + ct, hashlib.sha256).digest()
    return {
        "salt": salt.hex(),
        "iv":   iv.hex(),
        "ct":   ct.hex(),
        "mac":  mac.hex(),
        "kdf":  "pbkdf2-sha256-200000",
    }

def _decrypt_mnemonic(enc_dict: dict, password: str) -> str:
    """Decrypt mnemonic. Raises ValueError on wrong password or tampered data."""
    salt    = bytes.fromhex(enc_dict["salt"])
    iv      = bytes.fromhex(enc_dict["iv"])
    ct      = bytes.fromhex(enc_dict["ct"])
    mac_exp = bytes.fromhex(enc_dict["mac"])
    key     = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200_000, dklen=64)
    enc_key = key[:32]
    mac_key = key[32:]
    # Verify MAC first
    mac_got = hmac.new(mac_key, salt + iv + ct, hashlib.sha256).digest()
    if not hmac.compare_digest(mac_got, mac_exp):
        raise ValueError("Wrong password or corrupted wallet file")
    pad  = hashlib.pbkdf2_hmac('sha256', enc_key, iv, 1, dklen=len(ct))
    data = bytes(a ^ b for a, b in zip(ct, pad))
    return data.decode('utf-8')

def _mk_block(header, txs, height=None):
    """Block(header, txs) -- height lives in the header, not in Block()."""
    if height is not None and not getattr(header, 'height', 0):
        header.height = height
    return Block(header, txs)

# ================================================================
#  BLOCK
# ================================================================

class Block:
    """Full block = header + transactions"""

    def __init__(self, header: BlockHeader, transactions: List[Transaction]):
        self.header       = header
        self.transactions = transactions
        self._hash        = None

    @property
    def hash(self) -> str:
        if self._hash is None:
            self._hash = self.header.hash()
        return self._hash

    def compute_merkle_root(self) -> str:
        """Compute merkle root from current transactions.
        was a duplicate implementation using raw hashlib — now delegates
        to MerkleTree.compute_root() so there is exactly one canonical implementation."""
        return MerkleTree.compute_root([tx.txid for tx in self.transactions])

    @property
    def height(self) -> int:
        return self.header.height

    @property
    def tx_count(self) -> int:
        return len(self.transactions)

    def byte_size(self) -> int:
        return sum(tx.byte_size() for tx in self.transactions) + BlockHeader.SIZE

    def verify_merkle(self) -> bool:
        computed = MerkleTree.compute_root([tx.txid for tx in self.transactions])
        return computed == self.header.merkle_root

    def total_output(self) -> int:
        if not self.transactions:
            return 0
        return self.transactions[0].total_output()

    def to_dict(self) -> dict:
        return {
            "hash":         self.hash,
            "height":       self.height,
            "size":         self.byte_size(),
            "tx_count":     self.tx_count,
            "header":       self.header.to_dict(),
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

# ================================================================
#  UTXO SET
# ================================================================

@dataclass
class UTXOEntry:
    txid:         str
    index:        int
    value:        int
    script_pubkey: bytes
    height:       int
    is_coinbase:  bool = False

class UTXOSet:
    """Efficient UTXO set with address index"""

    def __init__(self):
        self._utxos:  Dict[str, UTXOEntry] = {}       # "txid:idx" -> entry
        self._addr_idx: Dict[str, Set[str]] = defaultdict(set)  # addr -> keys
        self._lock = threading.RLock()

    def _key(self, txid: str, index: int) -> str:
        return f"{txid}:{index}"

    def snapshot(self) -> tuple:
        """Return a deep-copyable snapshot of UTXO state for reorg rollback.
        Uses proper locking and encapsulation instead of direct _utxos access."""
        with self._lock:
            import copy
            utxos_copy = {k: copy.copy(v) for k, v in self._utxos.items()}
            addr_copy  = {k: set(v) for k, v in self._addr_idx.items()}
            return (utxos_copy, addr_copy)

    def restore(self, snapshot: tuple) -> None:
        """Restore UTXO state from a snapshot() result."""
        with self._lock:
            utxos_copy, addr_copy = snapshot
            self._utxos    = utxos_copy
            self._addr_idx = defaultdict(set, addr_copy)   # PATCH: snapshot() returns a plain dict; keep defaultdict semantics

    def add(self, entry: UTXOEntry):
        with self._lock:
            k = self._key(entry.txid, entry.index)
            self._utxos[k] = entry
            addr = entry_address(entry)
            if addr:
                self._addr_idx[addr].add(k)

    def spend(self, txid: str, index: int) -> Optional[UTXOEntry]:
        with self._lock:
            k = self._key(txid, index)
            entry = self._utxos.pop(k, None)
            if entry:
                addr = entry_address(entry)
                if addr and addr in self._addr_idx:
                    self._addr_idx[addr].discard(k)
            return entry

    def get(self, txid: str, index: int) -> Optional[UTXOEntry]:
        with self._lock:  # was missing lock — race condition with spend()
            return self._utxos.get(self._key(txid, index))

    def has(self, txid: str, index: int) -> bool:
        with self._lock:  # was missing lock — race condition with spend()
            return self._key(txid, index) in self._utxos

    def get_by_address(self, address: str) -> List[UTXOEntry]:
        with self._lock:
            keys = list(self._addr_idx.get(address, set()))
            return [self._utxos[k] for k in keys if k in self._utxos]

    def balance(self, address: str) -> int:
        return sum(e.value for e in self.get_by_address(address))

    def total_supply(self) -> int:
        return sum(e.value for e in self._utxos.values())

    def undo_block(self, block: 'Block') -> bool:
        """
        FIX Rollback a block's UTXO changes (for reorg).
        Reverses apply_block(): removes added outputs, restores spent inputs.
        """
        with self._lock:
            added_keys  = getattr(block, '_undo_added',  [])
            spent_utxos = getattr(block, '_undo_spent',  [])
            if not added_keys and not spent_utxos:
                return False   # No undo data — block was not applied via apply_block()
            # Remove outputs that were added by this block
            for k in added_keys:
                entry = self._utxos.pop(k, None)
                if entry:
                    addr = entry_address(entry)
                    if addr:
                        self._addr_idx.get(addr, set()).discard(k)
            # Restore inputs that were spent by this block
            for entry in spent_utxos:
                self.add(entry)
            # Clear undo data
            block._undo_added = []
            block._undo_spent = []
            return True

    def size(self) -> int:
        return len(self._utxos)

    def apply_block(self, block: Block) -> bool:
        """
        Apply all transactions in a block to UTXO set.
        FIX returns BlockUndo so reorg can rollback this block.
        """
        with self._lock:
            spent_utxos: List[UTXOEntry] = []   # FIX track spent UTXOs for undo
            added_keys:  List[str]       = []   # FIX track added keys for undo
            for tx in block.transactions:
                # Spend inputs
                if not tx.is_coinbase:
                    for inp in tx.inputs:
                        if not self.has(inp.outpoint.txid, inp.outpoint.index):
                            # Rollback partial changes before returning False
                            for k in reversed(added_keys):
                                # retrieve entry BEFORE popping to
                                # avoid use-after-pop (entry_address(None) crash)
                                entry_to_remove = self._utxos.pop(k, None)
                                if entry_to_remove:
                                    addr = entry_address(entry_to_remove)
                                    if addr and addr in self._addr_idx:
                                        self._addr_idx[addr].discard(k)
                            for u in reversed(spent_utxos):
                                self.add(u)
                            return False
                        spent = self.spend(inp.outpoint.txid, inp.outpoint.index)
                        if spent:
                            spent_utxos.append(spent)   # FIX save for undo
                # Add outputs
                for idx, out in enumerate(tx.outputs):
                    if Script.classify(out.script_pubkey) != ScriptType.NULLDATA:
                        entry = UTXOEntry(
                            txid         = tx.txid,
                            index        = idx,
                            value        = out.value,
                            script_pubkey = out.script_pubkey,
                            height       = block.height,
                            is_coinbase  = tx.is_coinbase,
                        )
                        self.add(entry)
                        added_keys.append(self._key(tx.txid, idx))  # FIX save for undo
            # FIX store undo data on block object for reorg rollback
            block._undo_spent = spent_utxos
            block._undo_added = added_keys
            return True

def entry_address(entry: UTXOEntry) -> Optional[str]:
    st = Script.classify(entry.script_pubkey)
    if st == ScriptType.P2PKH:
        h160 = entry.script_pubkey[3:23]
        return base58check_encode(h160, PUBKEY_ADDRESS_VERSION)
    if st == ScriptType.P2SH:   # [v10.23]
        return base58check_encode(entry.script_pubkey[2:22], SCRIPT_ADDRESS_VERSION)
    return None

# ================================================================
#  MEMPOOL
# ================================================================

# FIX v10.4: mempool limits (it used to grow without bound -> memory DoS)
MEMPOOL_MAX_TXS      = 50_000
MEMPOOL_MAX_BYTES    = 100 * 1024 * 1024
MEMPOOL_MAX_TX_BYTES = 100_000

class Mempool:
    """Transaction memory pool — pending transactions"""

    def __init__(self, utxo: UTXOSet):
        self._txs:       Dict[str, Transaction] = {}
        self._fee_index: List[Tuple[int, str]]  = []   # (fee_rate, txid)
        self._utxo       = utxo
        self._lock       = threading.RLock()
        self._spent_outpoints: Dict[str, str]   = {}   # "txid:idx" -> spending txid
        self._chain_height: int                 = 0    # updated by Blockchain
        self._meta:  Dict[str, Tuple[int, int]] = {}   # txid -> (fee_rate, size)  FIX v10.4
        self._bytes: int                        = 0    # total size of pooled txs  FIX v10.4

    def _make_room(self, fee_rate: int, size: int) -> bool:
        """FIX v10.4: evict the lowest-fee-rate txs to fit a new one. All-or-nothing:
        nothing is evicted unless the new tx strictly out-pays every tx it displaces."""
        count, total, victims = len(self._txs), self._bytes, []
        for txid, (rate, sz) in sorted(self._meta.items(), key=lambda kv: kv[1][0]):
            if count < MEMPOOL_MAX_TXS and total + size <= MEMPOOL_MAX_BYTES:
                break
            if rate >= fee_rate:
                return False
            victims.append(txid)
            count -= 1
            total -= sz
        if count >= MEMPOOL_MAX_TXS or total + size > MEMPOOL_MAX_BYTES:
            return False
        for txid in victims:
            self.remove(txid)
        return True

    def submit(self, tx: Transaction) -> Tuple[bool, str]:
        """Validate and add transaction to mempool"""
        with self._lock:
            if tx.txid in self._txs:
                return False, "Already in mempool"
            if tx.is_coinbase:
                return False, "Coinbase not accepted in mempool"
            tx_size = tx.byte_size()   # FIX v10.4: cheap size check BEFORE signature verification
            if tx_size > MEMPOOL_MAX_TX_BYTES:
                return False, f"Transaction too large: {tx_size} > {MEMPOOL_MAX_TX_BYTES}"
            # Basic validation
            ok, reason = self._validate(tx)
            if not ok:
                return False, reason
            fee      = tx.fee(self._utxo)
            fee_rate = fee // max(1, tx.byte_size())
            if fee < MIN_TX_FEE:
                return False, f"Fee too low: {fee} < {MIN_TX_FEE}"
            if len(self._txs) >= MEMPOOL_MAX_TXS or self._bytes + tx_size > MEMPOOL_MAX_BYTES:
                if not self._make_room(fee_rate, tx_size):
                    return False, "Mempool full: fee rate too low"
            self._txs[tx.txid] = tx
            self._meta[tx.txid] = (fee_rate, tx_size)
            self._bytes += tx_size
            heapq.heappush(self._fee_index, (-fee_rate, tx.txid))  # O(log n) vs O(n log n) sort
            # Register all inputs as spent in mempool
            for inp in tx.inputs:
                op_key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
                self._spent_outpoints[op_key] = tx.txid
            return True, "Accepted"

    def _validate(self, tx: Transaction) -> Tuple[bool, str]:
        if not tx.inputs or not tx.outputs:
            return False, "Empty inputs or outputs"
        for out in tx.outputs:
            # v10.9: OP_RETURN data outputs carry value 0 by design (ChainValidator already
            # exempts them) - the mempool used to reject every data-carrier transaction.
            if out.value < DUST_THRESHOLD and Script.classify(out.script_pubkey) != ScriptType.NULLDATA:
                return False, f"Output below dust: {out.value}"
            if out.value > MAX_SUPPLY:
                return False, "Output exceeds max supply"
        for inp in tx.inputs:
            if not self._utxo.has(inp.outpoint.txid, inp.outpoint.index):
                return False, f"UTXO not found: {inp.outpoint.txid}:{inp.outpoint.index}"
            op_key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
            if op_key in self._spent_outpoints:
                return False, f"Double-spend in mempool: {op_key} already spent by {self._spent_outpoints[op_key]}"
        # Verify scriptSig signatures before accepting into mempool.
        # Previously only UTXO existence and double-spend were checked — an attacker
        # could flood the mempool with invalid-signature transactions at zero cost,
        # causing DoS and wasting bandwidth.  ChainValidator.validate_tx() performs
        # the full P2PKH/P2SH script verification; reuse it here so the logic stays
        # in one place and future script types are covered automatically.
        _cv = ChainValidator(self._utxo)
        ok, reason = _cv.validate_tx(tx, current_height=self._chain_height if hasattr(self, '_chain_height') else 0)
        if not ok:
            return False, f"Script/signature invalid: {reason}"
        return True, "OK"

    def get_for_block(self, max_bytes: int = MAX_BLOCK_SIZE_BYTES) -> List[Transaction]:
        """Get highest-fee transactions that fit in a block"""
        with self._lock:
            selected = []
            total    = 0
            for neg_rate, txid in self._fee_index:  # heap stores (-fee_rate, txid)
                if txid not in self._txs:
                    continue
                tx = self._txs[txid]
                # PATCH: skip stale txs (inputs spent/rolled back since admission)
                if any(not self._utxo.has(i.outpoint.txid, i.outpoint.index) for i in tx.inputs):
                    continue
                tx_bytes = tx.byte_size()
                if total + tx_bytes > max_bytes:
                    continue
                selected.append(tx)
                total += tx_bytes
                if len(selected) >= MAX_TX_PER_BLOCK:
                    break
            return selected

    def remove(self, txid: str):
        with self._lock:
            tx = self._txs.pop(txid, None)
            _m = self._meta.pop(txid, None)   # FIX v10.4
            if _m:
                self._bytes = max(0, self._bytes - _m[1])
            self._fee_index = [(r, t) for r, t in self._fee_index if t != txid]
            heapq.heapify(self._fee_index)  # restore heap invariant after removal
            if tx is not None:
                for inp in tx.inputs:
                    op_key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
                    if self._spent_outpoints.get(op_key) == txid:
                        self._spent_outpoints.pop(op_key, None)

    def remove_block_txs(self, block: Block):
        with self._lock:
            for tx in block.transactions:
                self.remove(tx.txid)
                # PATCH: also evict mempool txs that spend the same outpoints
                # (e.g. a malleated twin confirmed by another miner); they can
                # never be mined and made our own miner build invalid blocks.
                if not tx.is_coinbase:
                    for inp in tx.inputs:
                        _k = f"{inp.outpoint.txid}:{inp.outpoint.index}"
                        _other = self._spent_outpoints.get(_k)
                        if _other and _other != tx.txid:
                            self.remove(_other)

    def size(self) -> int:
        return len(self._txs)

    def total_fees(self) -> int:
        return sum(tx.fee(self._utxo) for tx in self._txs.values())

# ================================================================
#  CHAIN VALIDATOR
# ================================================================

class ChainValidator:
    """Validates blocks and transactions against consensus rules"""

    def __init__(self, utxo: UTXOSet, chain: list = None):
        self._utxo  = utxo
        self._chain = chain   # reference to NEBULABlockchain._chain for maturity checks

    def expected_bits(self, prev: Block, chain: list = None) -> Optional[int]:
        """consensus-required `bits` for the block that follows `prev`.
        Mirrors NEBULABlockchain.get_next_bits() but works for any branch.
        Returns None if it cannot be determined (retarget needs ancestors)."""
        ph = prev.height
        if DIFF_ALGO == "lwma":                       # [v10.25e] per-block LWMA
            if ph == 0 or chain is None:
                return prev.header.bits
            if len(chain) <= ph or chain[ph].hash != prev.hash:
                return None
            return lwma_next_bits(chain, ph)
        if ph == 0 or ph % DIFFICULTY_WINDOW != 0:
            return prev.header.bits
        if chain is None or len(chain) <= ph or chain[ph].hash != prev.hash:
            return None
        first = chain[ph - DIFFICULTY_WINDOW + 1]
        return compute_next_bits(prev.header.bits,
                                 prev.header.timestamp - first.header.timestamp)

    def validate_block(self, block: Block, prev: Block,
                       chain: list = None) -> Tuple[bool, str]:
        h = block.header
        _chain = chain if chain is not None else self._chain   # branch-aware

        # 1. Hash meets target
        if not h.meets_target():
            return False, "Proof of work insufficient"

        # 2. Previous hash matches
        if h.prev_hash != prev.hash:
            return False, f"prev_hash mismatch"

        # 3. Height sequential
        if h.height != prev.height + 1:
            return False, "Non-sequential height"

        # 3b. header bits MUST equal the consensus difficulty.
        #     Without this an attacker sets an arbitrarily easy target and mines
        #     blocks instantly (PoW meant nothing).
        _exp_bits = self.expected_bits(prev, _chain)
        if _exp_bits is None:
            return False, "Cannot determine expected difficulty bits"
        if h.bits != _exp_bits:
            return False, f"Wrong difficulty bits {hex(h.bits)} (expected {hex(_exp_bits)})"

        # 4. Timestamp reasonable (within 2 hours of now, after median of last 11)
        # Bitcoin's Median-Time-Past rule — block timestamp MUST be strictly
        # greater than the median of the previous 11 block timestamps.
        # Without this lower-bound check an attacker can submit a block with a timestamp
        # far in the past, skewing difficulty retargets and enabling time-warp attacks.
        now = int(time.time())
        if h.timestamp > now + 7200:
            return False, "Timestamp too far in future"
        # MTP lower-bound: collect up to 11 ancestor timestamps via _chain reference
        if _chain is not None and len(_chain) >= 1:
            # Gather timestamps of the last min(11, chain_length) blocks ending at prev
            prev_height = prev.height
            sample_count = min(11, prev_height + 1)   # +1 because height is 0-indexed
            if sample_count > 0:
                # Walk backwards from prev using _chain list (O(1) index access)
                timestamps = []
                for i in range(sample_count):
                    idx = prev_height - i
                    if 0 <= idx < len(_chain):
                        timestamps.append(_chain[idx].header.timestamp)
                if timestamps:
                    timestamps.sort()
                    mtp = timestamps[len(timestamps) // 2]   # lower median
                    if h.timestamp <= mtp:
                        return False, (
                            f"Timestamp {h.timestamp} <= MTP {mtp}: "
                            f"time-warp attack rejected"
                        )

        # 5. Has at least one tx (coinbase)
        if not block.transactions:
            return False, "No transactions"

        # 6. First tx must be coinbase
        if not block.transactions[0].is_coinbase:
            return False, "First tx not coinbase"

        # 7. Only one coinbase
        for tx in block.transactions[1:]:
            if tx.is_coinbase:
                return False, "Multiple coinbase transactions"

        # 8. Merkle root
        if not block.verify_merkle():
            return False, "Merkle root mismatch"

        # 9. Block size
        if block.byte_size() > MAX_BLOCK_SIZE_BYTES:
            return False, "Block too large"

        # 10. Tx count
        if len(block.transactions) > MAX_TX_PER_BLOCK:
            return False, "Too many transactions"

        # 11. Coinbase reward
        expected = mining_reward(h.height)
        fees     = sum(tx.fee(self._utxo) for tx in block.transactions[1:])
        max_cb   = expected + fees
        if block.transactions[0].total_output() > max_cb:
            return False, f"Coinbase reward too high: {block.transactions[0].total_output()} > {max_cb}"
        # PATCH: every coinbase output must be individually in range.
        # Without this a negative output offsets a huge positive one and the
        # sum check above passes (unlimited inflation).
        for _cbo in block.transactions[0].outputs:
            if _cbo.value < 0 or _cbo.value > max_cb:
                return False, f"Coinbase output out of range: {_cbo.value}"
        # PATCH: enforce the documented 2% foundation share (computed on the subsidy,
        # exactly like Transaction.coinbase; fees are not part of the minimum)
        if h.height > 0:
            _fmin = int(expected * FOUNDATION_RATE)
            if _fmin >= DUST_THRESHOLD:
                _fscript = Script.p2pkh_locking_from_address(FOUNDATION_ADDRESS)
                _fpaid = sum(o.value for o in block.transactions[0].outputs if o.script_pubkey == _fscript)
                if _fpaid < _fmin:
                    return False, f"Coinbase foundation share too low: {_fpaid} < {_fmin}"

        # 12. Block-level double-spend detection ()
        seen_outpoints: Set[str] = set()
        for tx in block.transactions[1:]:
            for inp in tx.inputs:
                op_key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
                if op_key in seen_outpoints:
                    return False, f"Double-spend within block: {op_key}"
                seen_outpoints.add(op_key)

        # PATCH (BIP30): a block must not recreate a txid that still has unspent
        # outputs -- UTXOSet.add() silently overwrites, destroying the old coins
        # and corrupting undo data (identical coinbase txids were possible).
        for _tx in block.transactions:
            for _i in range(len(_tx.outputs)):
                if self._utxo.has(_tx.txid, _i):
                    return False, f"Duplicate txid with unspent outputs: {_tx.txid[:8]}"

        # 13. Validate each non-coinbase tx (with coinbase maturity)
        for tx in block.transactions[1:]:
            ok, reason = self.validate_tx(tx, current_height=h.height)
            if not ok:
                return False, f"Invalid tx {tx.txid[:8]}: {reason}"

        return True, "OK"

    def validate_tx(self, tx: Transaction,
                    current_height: int = 0) -> Tuple[bool, str]:
        if tx.is_coinbase:
            return True, "OK"
        if not tx.inputs:
            return False, "No inputs"
        if not tx.outputs:
            return False, "No outputs"

        total_in  = 0
        seen_outpoints: Set[str] = set()

        for i, inp in enumerate(tx.inputs):
            op_key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
            if op_key in seen_outpoints:
                return False, "Duplicate input"
            seen_outpoints.add(op_key)

            utxo = self._utxo.get(inp.outpoint.txid, inp.outpoint.index)
            if not utxo:
                return False, f"UTXO not found: {op_key}"

            # Coinbase maturity check
            if utxo.is_coinbase:
                if current_height - utxo.height < COINBASE_MATURITY:
                    return False, (
                        f"Coinbase UTXO not mature: "
                        f"mined at {utxo.height}, "
                        f"current {current_height}, "
                        f"need {COINBASE_MATURITY} confirmations"
                    )

            # every non-coinbase input MUST carry a scriptSig.
            # Previously an empty scriptSig skipped ALL verification below, so any
            # UTXO could be spent by anyone without a signature.
            if not inp.script_sig:
                return False, f"Missing scriptSig on input {i}"

            # Verify scriptSig unlocks the UTXO's scriptPubKey
            if inp.script_sig:
                script_type = Script.classify(utxo.script_pubkey)
                if script_type == ScriptType.P2PKH:
                    try:
                        sighash = tx.signature_hash(i, utxo.script_pubkey, SIGHASH_ALL)
                        if not Script.verify_p2pkh(utxo.script_pubkey,
                                                   inp.script_sig, sighash):
                            return False, f"Invalid P2PKH signature on input {i}"
                    except Exception as e:
                        return False, f"Script verification error on input {i}: {e}"
                elif script_type == ScriptType.NULLDATA:
                    # OP_RETURN outputs are unspendable — reject any attempt to spend them
                    return False, f"Cannot spend OP_RETURN (NULLDATA) output on input {i}"
                elif script_type == ScriptType.P2SH:
                    # [v10.23] real P2SH: hash160(redeem) must equal the locking hash, the
                    # scriptSig must be push-only, the redeem script is then executed with
                    # the pushed arguments and signatures cover the redeem script.
                    try:
                        _ok_p2sh, _why_p2sh = _verify_p2sh_input(tx, i, utxo.script_pubkey,
                                                                 inp.script_sig, current_height)
                    except Exception as e:
                        return False, f"P2SH verification error on input {i}: {e}"
                    if not _ok_p2sh:
                        return False, f"{_why_p2sh} on input {i}"
                elif script_type == ScriptType.UNKNOWN:
                    # reject UNKNOWN script types entirely — previously any
                    # non-empty scriptSig would pass, allowing theft of UNKNOWN UTXOs
                    return False, f"Cannot spend UNKNOWN script type on input {i}"

            total_in += utxo.value

        total_out = tx.total_output()
        if total_in < total_out:
            return False, f"Input ({total_in}) < Output ({total_out})"

        for out in tx.outputs:
            if out.value < 0:
                return False, "Negative output"
            if out.value > MAX_SUPPLY:
                return False, "Output > max supply"
            if out.value < DUST_THRESHOLD and Script.classify(out.script_pubkey) != ScriptType.NULLDATA:
                return False, f"Output below dust threshold: {out.value}"

        return True, "OK"

# ================================================================
#  BLOCKCHAIN MAIN
# ================================================================

def _enable_dev_mode(bc, who: str):
    """v10.9: classes that mint coins with fund_address() (faucet, dev tools, gaming) used to flip
    `_dev_mode = True` on WHATEVER chain they were given - on a real node that lets them create
    money from nothing. Now they may only run on a chain whose dev mode was switched on by the
    caller, or when the operator explicitly sets NEBULA_ALLOW_DEV_MODE=1 (test/regtest only)."""
    if getattr(bc, '_dev_mode', False):
        return
    if os.environ.get('NEBULA_ALLOW_DEV_MODE') == '1':
        bc._dev_mode = True
        return
    raise PermissionError(
        f"{who} needs coin-minting dev mode, which is disabled on real chains. "
        "Use a throw-away chain (bc._dev_mode = True) or set NEBULA_ALLOW_DEV_MODE=1 for tests.")


# ================================================================
#  v10.20  CRASH-SAFE STORAGE HELPERS  (used by NEBULABlockchain.save / load)
# ================================================================
_STORE_FORMAT     = 2
_STORE_NAMES      = ("nebula_chain.json", "nebula_utxo.json", "nebula_meta.json")   # meta = commit point (last)
_STORE_IO_LOCK    = threading.Lock()
_STORE_SEQ_LOCK   = threading.Lock()
_STORE_SEQ        = [0]
_STORE_LAST_WRITTEN: Dict[str, int] = {}
_STORE_LOG        = logging.getLogger("nebula.storage")

class _StoreForeignChain(Exception):
    """Saved data belongs to another chain id (not damage: never quarantined)."""

def _store_fsync_dir(dpath) -> None:
    if os.name == "nt":
        return
    try:
        fd = os.open(str(dpath), os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    except OSError:
        _STORE_LOG.debug("directory fsync not possible for %s", dpath, exc_info=True)

def _store_write_tmp(path: Path, data: bytes) -> Path:
    """Write data to <path>.tmp and fsync it. Returns the tmp path (caller does os.replace)."""
    tmp = path.with_name(path.name + ".tmp")
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
    except BaseException:
        try:
            os.unlink(str(tmp))
        except OSError:
            _STORE_LOG.debug("could not remove %s", tmp, exc_info=True)
        raise
    return tmp

def _store_keep_prev(path: Path) -> None:
    """Make <path>.prev a copy (hard link when possible) of the current file; the current file never disappears."""
    if not path.exists():
        return
    prev = path.with_name(path.name + ".prev")
    tmp  = path.with_name(path.name + ".prevtmp")
    try:
        if tmp.exists():
            tmp.unlink()
        try:
            os.link(str(path), str(tmp))
        except OSError:
            import shutil
            shutil.copy2(str(path), str(tmp))
        os.replace(str(tmp), str(prev))
    except OSError:
        _STORE_LOG.warning("could not refresh backup %s", prev, exc_info=True)

def _store_quarantine(dpath: Path, sfx: str) -> None:
    """Move a damaged generation aside as *.corrupt-<unix time> (evidence is kept, never deleted)."""
    ts = int(time.time())
    for n in _STORE_NAMES:
        p = dpath / (n + sfx)
        if p.exists():
            try:
                os.replace(str(p), str(dpath / f"{n}{sfx}.corrupt-{ts}"))
            except OSError:
                _STORE_LOG.error("could not quarantine %s", p, exc_info=True)


# ================================================================
#  v10.21  INCREMENTAL CHAIN STORE (SQLite, one transaction per block)
#  Used by NEBULABlockchain.save()/load(). File: <datadir>/nebula_chain.db
# ================================================================
import sqlite3 as _sqlite3

_DB_NAME   = "nebula_chain.db"
_DB_FORMAT = 3
_ACC_MOD   = 1 << 256
_DB_SCHEMA = """
CREATE TABLE IF NOT EXISTS meta  (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocks(height INTEGER PRIMARY KEY, hash TEXT NOT NULL UNIQUE, data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS undo  (height INTEGER PRIMARY KEY, data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS utxo  (k TEXT PRIMARY KEY, txid TEXT NOT NULL, idx INTEGER NOT NULL,
                                  value INTEGER NOT NULL, script BLOB NOT NULL,
                                  height INTEGER NOT NULL, cb INTEGER NOT NULL);
"""

def _env_int(name: str, default: int, lo: int, hi: int) -> int:
    """Integer from the environment, clamped to [lo, hi]; anything unparsable -> default."""
    try:
        v = int(os.environ.get(name, "") or default)
    except ValueError:
        return default
    return max(lo, min(hi, v))

class _NeedRebuild(Exception):
    """The incremental delta cannot be derived (no undo data): rebuild the tables by replay."""

def _utxo_h(k, value, script: bytes, height, cb) -> int:
    return int.from_bytes(hashlib.sha256(
        f"{k}|{value}|{bytes(script).hex()}|{height}|{int(bool(cb))}".encode()).digest(), "big")

def _blk_to_dict(blk) -> dict:
    hdr = blk.header
    return {
        "version": hdr.version, "prev_hash": hdr.prev_hash, "merkle_root": hdr.merkle_root,
        "timestamp": hdr.timestamp, "bits": hdr.bits, "nonce": hdr.nonce, "height": hdr.height,
        "transactions": [{
            "version": tx.version, "locktime": tx.locktime,
            "inputs":  [{"txid": i.outpoint.txid, "index": i.outpoint.index,
                         "script_sig": i.script_sig.hex(), "sequence": i.sequence} for i in tx.inputs],
            "outputs": [{"value": o.value, "script_pubkey": o.script_pubkey.hex()} for o in tx.outputs],
        } for tx in blk.transactions],
    }

def _blk_from_dict(bd: dict):
    txs = []
    for td in bd["transactions"]:
        txs.append(Transaction(
            version  = td["version"],
            inputs   = [TxInput(outpoint=OutPoint(txid=i["txid"], index=i["index"]),
                                script_sig=bytes.fromhex(i["script_sig"]), sequence=i["sequence"])
                        for i in td["inputs"]],
            outputs  = [TxOutput(value=o["value"], script_pubkey=bytes.fromhex(o["script_pubkey"]))
                        for o in td["outputs"]],
            locktime = td["locktime"]))
    hdr = BlockHeader(version=bd["version"], prev_hash=bd["prev_hash"], merkle_root=bd["merkle_root"],
                      timestamp=bd["timestamp"], bits=bd["bits"], nonce=bd["nonce"], height=bd["height"])
    return Block(header=hdr, transactions=txs)

def _entry_to_dict(e) -> dict:
    return {"txid": e.txid, "index": e.index, "value": e.value, "script_pubkey": e.script_pubkey.hex(),
            "height": e.height, "is_coinbase": bool(e.is_coinbase)}

def _entry_from_dict(d):
    return UTXOEntry(txid=d["txid"], index=d["index"], value=d["value"],
                     script_pubkey=bytes.fromhex(d["script_pubkey"]),
                     height=d["height"], is_coinbase=bool(d["is_coinbase"]))

def _block_new_entries(blk) -> list:
    """Spendable outputs a block creates - mirrors UTXOSet.apply_block exactly."""
    out = []
    for tx in blk.transactions:
        for idx, o in enumerate(tx.outputs):
            if Script.classify(o.script_pubkey) == ScriptType.NULLDATA:
                continue
            out.append(UTXOEntry(txid=tx.txid, index=idx, value=o.value, script_pubkey=o.script_pubkey,
                                 height=blk.height, is_coinbase=tx.is_coinbase))
    return out

class _ChainStore:
    """SQLite chain store. Writes are incremental (one transaction per block / reorg), WAL + synchronous=FULL."""

    def __init__(self, path):
        self.path  = str(path)
        self.lock  = threading.RLock()
        self.bc    = None
        self.stale = False
        self.con   = _sqlite3.connect(self.path, check_same_thread=False, isolation_level=None, timeout=30)
        self.con.execute("PRAGMA journal_mode=WAL")
        self.con.execute("PRAGMA synchronous=FULL")
        self.con.executescript(_DB_SCHEMA)
        self._load_meta()

    # ---- meta ----
    def _meta(self, k, default=None):
        r = self.con.execute("SELECT v FROM meta WHERE k=?", (k,)).fetchone()
        return default if r is None else r[0]

    def _set_meta(self, k, v):
        self.con.execute("INSERT OR REPLACE INTO meta(k,v) VALUES(?,?)", (k, str(v)))

    def _load_meta(self):
        self.tip_h    = int(self._meta("tip_height", -1))
        self.tip_hash = self._meta("tip_hash", None)
        self.acc      = int(self._meta("utxo_acc", "0"), 16) % _ACC_MOD
        self.count    = int(self._meta("utxo_count", 0))

    def _write_meta(self, dev_mode=False):
        self._set_meta("format", _DB_FORMAT)
        self._set_meta("chain_id", CHAIN_ID)
        self._set_meta("chain", CHAIN_NAME)
        self._set_meta("tip_height", self.tip_h)
        self._set_meta("tip_hash", self.tip_hash)
        self._set_meta("utxo_acc", format(self.acc, "064x"))
        self._set_meta("utxo_count", self.count)
        self._set_meta("dev_mode", int(bool(dev_mode)))
        self._set_meta("saved_at", int(time.time()))

    # ---- utxo table with running commitment ----
    @staticmethod
    def _key(txid, index): return f"{txid}:{index}"

    def _put(self, e):
        k = self._key(e.txid, e.index)
        old = self.con.execute("SELECT value,script,height,cb FROM utxo WHERE k=?", (k,)).fetchone()
        if old:
            self.acc = (self.acc - _utxo_h(k, old[0], old[1], old[2], old[3])) % _ACC_MOD
            self.count -= 1
        self.con.execute("INSERT OR REPLACE INTO utxo(k,txid,idx,value,script,height,cb) VALUES(?,?,?,?,?,?,?)",
                         (k, e.txid, e.index, e.value, bytes(e.script_pubkey), e.height, int(bool(e.is_coinbase))))
        self.acc = (self.acc + _utxo_h(k, e.value, e.script_pubkey, e.height, e.is_coinbase)) % _ACC_MOD
        self.count += 1

    def _del(self, k):
        old = self.con.execute("SELECT value,script,height,cb FROM utxo WHERE k=?", (k,)).fetchone()
        if old:
            self.con.execute("DELETE FROM utxo WHERE k=?", (k,))
            self.acc = (self.acc - _utxo_h(k, old[0], old[1], old[2], old[3])) % _ACC_MOD
            self.count -= 1

    def _replace_utxo(self, entries):
        self.con.execute("DELETE FROM utxo")
        self.acc, self.count, rows = 0, 0, []
        for e in entries:
            k = self._key(e.txid, e.index)
            rows.append((k, e.txid, e.index, e.value, bytes(e.script_pubkey), e.height, int(bool(e.is_coinbase))))
            self.acc = (self.acc + _utxo_h(k, e.value, e.script_pubkey, e.height, e.is_coinbase)) % _ACC_MOD
        self.count = len(rows)
        self.con.executemany("INSERT OR REPLACE INTO utxo(k,txid,idx,value,script,height,cb) VALUES(?,?,?,?,?,?,?)", rows)

    # ---- block level ----
    def _apply(self, blk):
        spent = list(getattr(blk, "_undo_spent", []) or [])
        if not spent and any(not tx.is_coinbase for tx in blk.transactions):
            raise _NeedRebuild(f"no undo data for block {blk.height}")
        added_keys = []
        for tx in blk.transactions:
            if not tx.is_coinbase:
                for i in tx.inputs:
                    self._del(self._key(i.outpoint.txid, i.outpoint.index))
            for idx, o in enumerate(tx.outputs):
                if Script.classify(o.script_pubkey) == ScriptType.NULLDATA:
                    continue
                self._put(UTXOEntry(txid=tx.txid, index=idx, value=o.value, script_pubkey=o.script_pubkey,
                                    height=blk.height, is_coinbase=tx.is_coinbase))
                added_keys.append(self._key(tx.txid, idx))
        self.con.execute("INSERT OR REPLACE INTO blocks(height,hash,data) VALUES(?,?,?)",
                         (blk.height, blk.hash, json.dumps(_blk_to_dict(blk), separators=(",", ":")).encode()))
        self.con.execute("INSERT OR REPLACE INTO undo(height,data) VALUES(?,?)",
                         (blk.height, json.dumps({"spent": [_entry_to_dict(e) for e in spent],
                                                  "added": added_keys}, separators=(",", ":")).encode()))
        self.tip_h, self.tip_hash = blk.height, blk.hash

    def _rollback_block(self, h):
        r = self.con.execute("SELECT data FROM undo WHERE height=?", (h,)).fetchone()
        if r is None:
            raise _NeedRebuild(f"no undo row for height {h}")
        u = json.loads(r[0])
        for k in u["added"]:
            self._del(k)
        for d in u["spent"]:
            self._put(_entry_from_dict(d))
        self.con.execute("DELETE FROM blocks WHERE height=?", (h,))
        self.con.execute("DELETE FROM undo WHERE height=?", (h,))
        prev = self.con.execute("SELECT hash FROM blocks WHERE height=?", (h - 1,)).fetchone()
        self.tip_h, self.tip_hash = h - 1, (prev[0] if prev else None)

    def _hash_at(self, h):
        r = self.con.execute("SELECT hash FROM blocks WHERE height=?", (h,)).fetchone()
        return r[0] if r else None

    # ---- sync (incremental, reorg-aware) ----
    def _sync_locked(self, bc, chain):
        self.con.execute("BEGIN IMMEDIATE")
        try:
            self._load_meta()              # state comes from the database, never from a stale cache
            h = self.tip_h
            while h >= 0 and not (h < len(chain) and self._hash_at(h) == chain[h].hash):
                h -= 1
            for hh in range(self.tip_h, h, -1):
                self._rollback_block(hh)
            for blk in chain[h + 1:]:
                self._apply(blk)
            dev = bool(getattr(bc, "_dev_mode", False))
            if dev:
                self._replace_utxo(list(bc.utxo._utxos.values()))
            self._write_meta(dev)
            self.con.execute("COMMIT")
        except BaseException:
            try:
                self.con.execute("ROLLBACK")
            except _sqlite3.Error:
                _STORE_LOG.debug("rollback after failed sync", exc_info=True)
            self._load_meta()
            raise

    def _rebuild(self, bc, chain):
        """Rewrite every table from the in-memory chain (migration / recovery). O(chain), rare."""
        scratch = UTXOSet()
        saved   = [(b, list(getattr(b, "_undo_spent", []) or []), list(getattr(b, "_undo_added", []) or []))
                   for b in chain]
        dev     = bool(getattr(bc, "_dev_mode", False))
        partial = False
        self.con.execute("BEGIN IMMEDIATE")
        try:
            for t in ("blocks", "undo", "utxo"):
                self.con.execute(f"DELETE FROM {t}")
            for blk in chain:
                ok = scratch.apply_block(blk)
                if not ok:
                    if not dev:
                        raise ValueError(f"chain replay failed at block {blk.height}")
                    partial = True
                spent = list(getattr(blk, "_undo_spent", []) or []) if ok else []
                self.con.execute("INSERT INTO blocks(height,hash,data) VALUES(?,?,?)",
                                 (blk.height, blk.hash, json.dumps(_blk_to_dict(blk), separators=(",", ":")).encode()))
                self.con.execute("INSERT INTO undo(height,data) VALUES(?,?)",
                                 (blk.height, json.dumps({"spent": [_entry_to_dict(e) for e in spent],
                                                          "added": [self._key(e.txid, e.index) for e in _block_new_entries(blk)]},
                                                         separators=(",", ":")).encode()))
            self._replace_utxo(list((bc.utxo if (dev or partial) else scratch)._utxos.values()))
            self.tip_h, self.tip_hash = chain[-1].height, chain[-1].hash
            self._write_meta(dev)
            self.con.execute("COMMIT")
        except BaseException:
            try:
                self.con.execute("ROLLBACK")
            except _sqlite3.Error:
                _STORE_LOG.debug("rollback after failed rebuild", exc_info=True)
            self._load_meta()
            raise
        finally:
            for b, s, a in saved:          # leave the live blocks exactly as they were
                b._undo_spent, b._undo_added = s, a

    def sync(self, bc=None) -> bool:
        bc = bc or self.bc
        with bc._lock:                      # lock order: chain lock -> store lock (same as on_connect)
            with self.lock:
                chain = list(bc._chain)
                try:
                    try:
                        self._sync_locked(bc, chain)
                    except _NeedRebuild as e:
                        _STORE_LOG.info("chain store: rebuilding from the in-memory chain (%s)", e)
                        self._rebuild(bc, chain)
                    self.stale = False
                    return True
                except Exception as e:
                    self.stale = True
                    _STORE_LOG.error("chain store sync FAILED: %s", e, exc_info=True)
                    return False

    # ---- live listener (called by NEBULABlockchain under its own lock) ----
    def on_connect(self, block):
        bc = self.bc
        try:
            if not self.stale:
                with self.lock:
                    self.con.execute("BEGIN IMMEDIATE")
                    try:
                        self._load_meta()
                        if not (self.tip_hash == block.header.prev_hash and self.tip_h + 1 == block.height):
                            raise _NeedRebuild("block does not extend the stored tip")
                        self._apply(block)
                        dev = bool(getattr(bc, "_dev_mode", False))
                        if dev:
                            self._replace_utxo(list(bc.utxo._utxos.values()))
                        self._write_meta(dev)
                        self.con.execute("COMMIT")
                        return
                    except BaseException:
                        try:
                            self.con.execute("ROLLBACK")
                        except _sqlite3.Error:
                            _STORE_LOG.debug("rollback after failed append", exc_info=True)
                        self._load_meta()
                        raise
        except _NeedRebuild:
            pass
        except Exception as e:
            self.stale = True
            _STORE_LOG.error("chain store append failed, will resync: %s", e, exc_info=True)
            return
        self.sync(bc)

    def on_reorg(self, old_blocks, new_blocks, ancestor_height):
        self.sync(self.bc)

    def hydrate_undo(self, blk) -> bool:
        """Give a block (loaded from disk, so without undo data) its undo data from the database.
        Only succeeds if the stored block at that height is exactly this block."""
        with self.lock:
            r = self.con.execute("SELECT b.hash, u.data FROM blocks b JOIN undo u ON u.height=b.height "
                                 "WHERE b.height=?", (blk.height,)).fetchone()
        if r is None or r[0] != blk.hash:
            return False
        u = json.loads(r[1])
        blk._undo_spent = [_entry_from_dict(d) for d in u["spent"]]
        blk._undo_added = list(u["added"])
        return True

    def close(self):
        with self.lock:
            try:
                self.con.close()
            except _sqlite3.Error:
                _STORE_LOG.debug("close failed", exc_info=True)

    _ATTACH_LOCK = threading.Lock()

    @classmethod
    def attach(cls, bc, dpath) -> "_ChainStore":
        key = str(Path(dpath).resolve())
        with cls._ATTACH_LOCK:             # exactly one store + listener per (chain, directory)
            stores = bc.__dict__.setdefault("_chain_stores", {})
            st = stores.get(key)
            if st is None:
                st = cls(Path(dpath) / _DB_NAME)
                st.bc = bc
                stores[key] = st
                bc.add_listener(st)
            return st

def _store_quarantine_db(dpath: Path) -> None:
    ts = int(time.time())
    for sfx in ("", "-wal", "-shm"):
        p = dpath / (_DB_NAME + sfx)
        if p.exists():
            try:
                os.replace(str(p), str(dpath / f"{_DB_NAME}{sfx}.corrupt-{ts}"))
            except OSError:
                _STORE_LOG.error("could not quarantine %s", p, exc_info=True)


def build_genesis_coinbase() -> 'Transaction':
    """[v10.25] The ONE place that builds the genesis coinbase transaction (used by NEBULABlockchain._init_genesis and
    by mine_genesis, so the mined nonce always matches the block the node builds).
    Output 0: the normal 50 NBL genesis reward (unspendable foundation address, like Bitcoin's genesis).
    Output 1: GENESIS_PREMINE_AMOUNT paid to GENESIS_PREMINE_ADDRESS (spendable after COINBASE_MATURITY blocks)."""
    base = Transaction.coinbase(0, mining_reward(0), NEBULABlockchain._GENESIS_ADDRESS_HARDCODED,
                                extra_data=GENESIS_MESSAGE[:40].encode())
    outputs = list(base.outputs)
    if GENESIS_PREMINE_AMOUNT > 0:
        base58check_decode(GENESIS_PREMINE_ADDRESS)   # raises on a bad checksum: never launch with a typo
        outputs.append(TxOutput(
            value         = GENESIS_PREMINE_AMOUNT,
            script_pubkey = Script.p2pkh_locking_from_address(GENESIS_PREMINE_ADDRESS),
        ))
    return Transaction(version=base.version, inputs=base.inputs, outputs=outputs, locktime=base.locktime)


class NEBULABlockchain:
    """
    Main blockchain — manages chain, UTXO, mempool, validation.
    Thread-safe. Supports reorgs.
    """

    # Hard limits to prevent memory exhaustion attacks via forged forks.
    # An attacker can send many blocks that each start a new fork, causing _fork_tips
    # to grow without bound and exhaust RAM.  Cap both the number of live fork tips
    # and the maximum depth (distance from main-chain tip) a fork may be.
    MAX_FORK_TIPS  = 32    # maximum concurrent fork tips stored
    # v10.22: MAX_FORK_DEPTH is the AUTOMATIC reorg limit (10-minute blocks: 100 blocks ~ 16.7 h of chain).
    # Deeper competing branches are not followed automatically; they raise an alert (deep_fork_alerts()) and an operator
    # may raise the limit (NEBULA_MAX_REORG_DEPTH at start, or set_max_reorg_depth()). Checkpoints are an absolute floor.
    MAX_FORK_DEPTH = _env_int("NEBULA_MAX_REORG_DEPTH", 100, 1, 1_000_000)
    # [v10.23] budget for side-chain block validation (each one copies the UTXO set). Token bucket: BURST blocks at once,
    # then PER_MIN per minute. A normal reorg (<= MAX_FORK_DEPTH blocks) fits in the burst.
    SIDE_BLOCK_BURST   = _env_int("NEBULA_SIDE_BLOCK_BURST", 300, 1, 1_000_000)
    SIDE_BLOCK_PER_MIN = _env_int("NEBULA_SIDE_BLOCK_PER_MIN", 30, 1, 1_000_000)

    def __init__(self):
        self._chain:    List[Block]   = []
        self.utxo       = UTXOSet()
        self.mempool    = Mempool(self.utxo)
        self.validator  = ChainValidator(self.utxo, self._chain)
        self._lock      = threading.RLock()
        self._hash_idx: Dict[str, int] = {}   # hash -> height
        # Side-chain storage — fork_tip_hash -> [Block, ...]
        # bounded by MAX_FORK_TIPS / MAX_FORK_DEPTH
        self._fork_tips: Dict[str, List[Block]] = {}
        # fund_address() is gated behind this flag — must be set
        #              explicitly in test/dev code; never set True in production
        self._dev_mode: bool = False
        # v10.9: objects with on_connect(block) / on_reorg(old, new, ancestor_height)
        self._listeners: list = []

        self._init_genesis()

    # Genesis private key must NOT be derivable from public data.
    #   The genesis address below is hardcoded (derived offline from a securely
    #   generated private key that is NOT stored in this file).
    #   The genesis coinbase is unspendable in practice because no one running
    #   this code has the matching private key — same as Bitcoin's genesis.
    _GENESIS_ADDRESS_HARDCODED = "NdoZxCWQfYDy4412S1Zqh8AWj9T5aKqmkx"

    def _init_genesis(self):
        # Use hardcoded genesis address — private key is NOT in this file.
        genesis_address = self._GENESIS_ADDRESS_HARDCODED

        cb = build_genesis_coinbase()   # [v10.25] 50 NBL genesis reward + public premine output

        merkle = MerkleTree.compute_root([cb.txid])
        header = BlockHeader(
            version     = CHAIN_VERSION,
            prev_hash   = '0' * 64,
            merkle_root = merkle,
            timestamp   = GENESIS_TIMESTAMP,
            bits        = GENESIS_BITS,
            nonce       = GENESIS_NONCE,
            height      = 0,
        )

        genesis = Block(header, [cb])
        self._chain.append(genesis)
        self._hash_idx[genesis.hash] = 0

        # Apply genesis to UTXO
        self.utxo.apply_block(genesis)

        print(f"\n🌌 NEBULA Genesis Block")
        print(f"   Hash    : {genesis.hash}")
        print(f"   Address : {genesis_address}")
        print(f"   Reward  : {mining_reward(0)/10**DECIMALS} NBL")
        if GENESIS_PREMINE_AMOUNT > 0:
            print(f"   Premine : {GENESIS_PREMINE_AMOUNT/10**DECIMALS:,.0f} NBL -> {GENESIS_PREMINE_ADDRESS}")
        print(f"   Message : {GENESIS_MESSAGE[:60]}...")

    @property
    def height(self) -> int:
        return len(self._chain) - 1

    @property
    def tip(self) -> Block:
        return self._chain[-1]

    def get_block(self, height: int) -> Optional[Block]:
        if 0 <= height < len(self._chain):
            return self._chain[height]
        return None

    def get_block_by_hash(self, h: str) -> Optional[Block]:
        idx = self._hash_idx.get(h)
        if idx is not None:
            return self._chain[idx]
        return None

    def get_next_bits(self) -> int:
        h = self.height
        if DIFF_ALGO == "lwma":                       # [v10.25e] per-block LWMA
            if h == 0:
                return self.tip.header.bits
            return lwma_next_bits(self._chain, h)
        if h == 0 or h % DIFFICULTY_WINDOW != 0:
            return self.tip.header.bits
        first = self._chain[h - DIFFICULTY_WINDOW + 1]
        last  = self.tip
        actual_timespan = last.header.timestamp - first.header.timestamp
        return compute_next_bits(last.header.bits, actual_timespan)

    def add_block(self, block: Block) -> Tuple[bool, str]:
        """
        Accept a new block, handling both main-chain extension and forks.
        Full fork detection + chain reorganization (reorg).

        Cases handled:
          1. Block extends main chain tip → normal append
          2. Block extends a known side-chain → store fork, check if longer
          3. Block's prev_hash unknown → orphan (rejected)
          4. Longer fork detected → execute reorg (switch main chain)
        """
        with self._lock:
            # v10.8: reject blocks we already have (main chain or side chain).
            # Previously a re-sent main-chain block was accepted as a "new fork",
            # letting a peer fill/evict the bounded fork-tip table for free.
            _bh = block.hash
            _ix = self._hash_idx.get(_bh)
            if _ix is not None and _ix < len(self._chain) and self._chain[_ix].hash == _bh:
                return False, "Duplicate block: already in main chain"
            for _fc in self._fork_tips.values():
                if any(_fb.hash == _bh for _fb in _fc[-(self.MAX_FORK_DEPTH + 2):]):
                    return False, "Duplicate block: already known on a side chain"
            _cpv = self._checkpoint_violation(block)
            if _cpv:
                return False, _cpv
            # ── Case 1: Normal extension of main tip ──────────────
            if block.header.prev_hash == self.tip.hash:
                ok, msg = self.validator.validate_block(block, self.tip)
                if not ok:
                    return False, msg
                self._chain.append(block)
                self._hash_idx[block.hash] = block.height
                self.utxo.apply_block(block)
                self.mempool._chain_height = block.height  # keep mempool height in sync
                self.mempool.remove_block_txs(block)
                self._notify_connect(block)   # v10.9 state layer
                return True, "OK"

            # ── Case 2: Block extends a known side-chain ──────────
            if block.header.prev_hash in self._fork_tips:
                fork_chain = self._fork_tips[block.header.prev_hash]
                prev_block = fork_chain[-1]
                # reject fork blocks that trail too far behind the tip
                fork_depth = self.height - prev_block.height
                if fork_depth > self.MAX_FORK_DEPTH:
                    self._deep_fork_alert(block, fork_depth, "side-chain extension")
                    return False, (f"Fork too deep: {fork_depth} blocks behind tip "
                                   f"(max {self.MAX_FORK_DEPTH})")
                _, _anc = self._branch_work_delta(fork_chain)
                _cpv = self._checkpoint_violation(block, branch_height=_anc)
                if _cpv:
                    return False, _cpv
                ok, msg = self._validate_on_branch(block, prev_block, fork_chain)   # PATCH
                if not ok:
                    return False, f"Fork block invalid: {msg}"
                # Remove old fork tip, add new
                del self._fork_tips[block.header.prev_hash]
                fork_chain.append(block)
                self._fork_tips[block.hash] = fork_chain

                # ── Reorg check: is this fork now longer? ─────────
                # heaviest chain wins (cumulative work), not longest.
                # v10.22: only the part above the common ancestor can differ -> O(depth), not O(chain)
                if self._branch_work_delta(fork_chain)[0] > 0:
                    ok2, msg2 = self._execute_reorg(fork_chain)
                    if ok2:
                        return True, f"REORG to fork height {block.height}"
                    return False, f"Reorg failed: {msg2}"
                return True, f"Fork extended (height {block.height}, depth {len(fork_chain)})"

            # ── Case 3: Block extends main chain at non-tip height ─
            # (this starts a new fork from somewhere in the main chain)
            if block.header.prev_hash in self._hash_idx:
                branch_height = self._hash_idx[block.header.prev_hash]
                branch_block  = self._chain[branch_height]
                # reject forks that branch too far back
                fork_depth = self.height - branch_height
                if fork_depth > self.MAX_FORK_DEPTH:
                    self._deep_fork_alert(block, fork_depth, "new branch")
                    return False, (f"Fork branch too deep: {fork_depth} blocks behind tip "
                                   f"(max {self.MAX_FORK_DEPTH})")
                _cpv = self._checkpoint_violation(block, branch_height=branch_height)
                if _cpv:
                    return False, _cpv
                # evict the shortest fork tip when at capacity
                if len(self._fork_tips) >= self.MAX_FORK_TIPS:
                    # Evict the fork with the fewest blocks (least work accumulated)
                    evict_hash = min(
                        self._fork_tips,
                        key=lambda h: len(self._fork_tips[h])
                    )
                    del self._fork_tips[evict_hash]
                    log.debug("evicted shortest fork tip to stay under limit")
                ok, msg = self._validate_on_branch(block, branch_block, self._chain[:branch_height + 1])   # PATCH
                if not ok:
                    return False, f"Fork start invalid: {msg}"
                # Seed new fork with all main chain blocks up to branch + new block
                fork_chain = list(self._chain[:branch_height + 1]) + [block]
                self._fork_tips[block.hash] = fork_chain
                return True, f"New fork started at height {branch_height + 1}"

            # ── Case 4: Orphan — prev_hash completely unknown ──────
            return False, f"Orphan block: prev_hash {block.header.prev_hash[:16]}... not found"

    # ── v10.9: listeners (state layer). A listener error NEVER affects consensus. ──
    def add_listener(self, listener):
        if listener not in self._listeners:
            self._listeners.append(listener)

    def _notify_connect(self, block):
        for _l in list(self._listeners):
            try:
                _l.on_connect(block)
            except Exception as _e:
                log.warning("listener on_connect failed: %s", _e)
                if hasattr(_l, '_stale'):
                    _l._stale = True

    def _notify_reorg(self, old_blocks, new_blocks, ancestor_height):
        for _l in list(self._listeners):
            try:
                _l.on_reorg(old_blocks, new_blocks, ancestor_height)
            except Exception as _e:
                log.warning("listener on_reorg failed: %s", _e)
                if hasattr(_l, '_stale'):
                    _l._stale = True

    def _validate_on_branch(self, block, prev_block, branch_chain):
        """PATCH: validate a side-chain block against the UTXO state at its
        PARENT, not against the main-chain tip (which made valid competing
        chains unacceptable and let invalid ones through the first check)."""
        import copy
        h = block.header
        # cheap header checks first: an unauthenticated block must not be able
        # to trigger the O(UTXO) state copy below without real PoW
        if not h.meets_target():
            return False, "Proof of work insufficient"
        exp = self.validator.expected_bits(prev_block, branch_chain)
        if exp is None or h.bits != exp:
            return False, "Wrong difficulty bits"
        # common ancestor of branch and main chain (walk back from the end)
        anc = min(len(branch_chain), len(self._chain)) - 1
        while anc > 0 and branch_chain[anc].hash != self._chain[anc].hash:
            anc -= 1
        main_tail = self._chain[anc + 1:]
        self._ensure_undo(main_tail)       # v10.22: blocks loaded from disk get their undo data from the DB
        if any(not (getattr(b, '_undo_added', None) or getattr(b, '_undo_spent', None))
               for b in main_tail):
            # no undo data available: keep the legacy behaviour
            return self.validator.validate_block(block, prev_block, chain=branch_chain)
        if not self._side_budget_take():            # [v10.23] bound the O(UTXO) work cheap side blocks can cause
            return False, "Side-chain validation rate limit reached (retry later)"
        tmp = UTXOSet()
        tmp.restore(self.utxo.snapshot())
        for b in reversed(main_tail):               # non-destructive undo
            for k in getattr(b, '_undo_added', []):
                e = tmp._utxos.pop(k, None)
                if e:
                    a = entry_address(e)
                    if a:
                        tmp._addr_idx.get(a, set()).discard(k)
            for e in getattr(b, '_undo_spent', []):
                tmp.add(copy.copy(e))
        for b in branch_chain[anc + 1:]:             # replay side-chain up to parent
            if not tmp.apply_block(b):
                return False, "Side-chain parent state inconsistent"
        return ChainValidator(tmp, branch_chain).validate_block(
            block, prev_block, chain=branch_chain)

    def _side_budget_take(self) -> bool:
        """[v10.23] token bucket for side-chain validations (called under the chain lock)."""
        now = time.monotonic()
        tokens, last = self.__dict__.get("_side_bucket", (float(self.SIDE_BLOCK_BURST), now))
        tokens = min(float(self.SIDE_BLOCK_BURST), tokens + (now - last) * self.SIDE_BLOCK_PER_MIN / 60.0)
        if tokens < 1.0:
            self.__dict__["_side_bucket"] = (tokens, now)
            last_log = self.__dict__.get("_side_limit_logged", 0.0)
            if now - last_log > 60:
                self.__dict__["_side_limit_logged"] = now
                log.warning("side-chain validation budget exhausted (burst %d, %d/min); blocks refused until it refills",
                            self.SIDE_BLOCK_BURST, self.SIDE_BLOCK_PER_MIN)
            return False
        self.__dict__["_side_bucket"] = (tokens - 1.0, now)
        return True

    @staticmethod
    def _chain_work(chain: List[Block]) -> int:
        """total expected hashes needed to produce `chain`."""
        total = 0
        for b in chain:
            t = bits_to_target(b.header.bits)
            if t > 0:
                total += (1 << 256) // (t + 1)
        return total

    # ── v10.22: reorg policy helpers ────────────────────────────────────────
    def set_max_reorg_depth(self, n: int) -> int:
        """Operator override of the automatic reorg limit (this chain object only)."""
        n = int(n)
        if n < 1:
            raise ValueError("max reorg depth must be >= 1")
        self.MAX_FORK_DEPTH = n
        log.warning("automatic reorg limit set to %d blocks", n)
        return n

    def deep_fork_alerts(self) -> List[dict]:
        """Competing branches (with valid proof of work) that were refused because they fork deeper than the limit."""
        return list(self.__dict__.get("_deep_alerts", []))

    def _deep_fork_alert(self, block: Block, depth: int, where: str) -> None:
        try:
            if not block.header.meets_target():
                return                      # junk without PoW: no alert, no state
            alerts = self.__dict__.setdefault("_deep_alerts", collections.deque(maxlen=20))
            seen   = self.__dict__.setdefault("_deep_alert_seen", {})
            now    = time.time()
            key    = block.header.prev_hash
            if len(seen) > 64:
                seen.clear()
            if now - seen.get(key, 0) < 600:
                return
            seen[key] = now
            alerts.append({"time": int(now), "hash": block.hash, "prev_hash": key, "height": block.height,
                           "depth": depth, "limit": self.MAX_FORK_DEPTH, "where": where})
            log.error("DEEP FORK refused: a competing branch with valid PoW forks %d blocks behind our tip "
                      "(limit %d). Not followed automatically. If you are sure, raise the limit "
                      "(NEBULA_MAX_REORG_DEPTH / set_max_reorg_depth). hash=%s", depth, self.MAX_FORK_DEPTH, block.hash[:20])
        except Exception:
            log.debug("deep-fork alert failed", exc_info=True)

    @staticmethod
    def _checkpoint_table() -> Dict[int, str]:
        cps: Dict[int, str] = {}
        for name in ("CHECKPOINTS", "NEBULA_CHECKPOINTS"):
            t = globals().get(name) or {}
            for h, hx in t.items():
                cps[int(h)] = str(hx)
        return cps

    def _checkpoint_violation(self, block: Block, branch_height: Optional[int] = None) -> Optional[str]:
        """Checkpoints are absolute: a block at a checkpoint height must have that hash, and no branch may
        replace a checkpointed block of our chain (not even with the operator override)."""
        cps = self._checkpoint_table()
        if not cps:
            return None
        want = cps.get(block.height)
        if want is not None and block.height > 0 and block.hash != want:
            return f"Block {block.height} violates the checkpoint for that height"
        if branch_height is not None:
            for ch, hx in cps.items():
                if ch > branch_height and ch < len(self._chain) and self._chain[ch].hash == hx:
                    return f"Fork would replace the checkpointed block at height {ch}"
        return None

    def _branch_work_delta(self, fork_chain: List[Block]) -> Tuple[int, int]:
        """(work(fork) - work(main), common-ancestor index). The shared prefix cancels, so only the blocks above
        the ancestor are summed: O(reorg depth) instead of O(chain length)."""
        anc = min(len(fork_chain), len(self._chain)) - 1
        while anc > 0 and fork_chain[anc].hash != self._chain[anc].hash:
            anc -= 1
        def _w(b):
            t = bits_to_target(b.header.bits)
            return (1 << 256) // (t + 1) if t > 0 else 0
        return (sum(_w(b) for b in fork_chain[anc + 1:]) - sum(_w(b) for b in self._chain[anc + 1:])), anc

    def _ensure_undo(self, blocks: List[Block]) -> None:
        """After a restart the blocks have no undo data in memory; fetch it from the chain database when needed."""
        need = [b for b in blocks if not (getattr(b, '_undo_added', None) or getattr(b, '_undo_spent', None))]
        if not need:
            return
        for st in list(self.__dict__.get("_chain_stores", {}).values()):
            for b in need:
                try:
                    st.hydrate_undo(b)
                except Exception:
                    log.debug("undo hydration failed at height %s", getattr(b, 'height', '?'), exc_info=True)
            need = [b for b in need if not (getattr(b, '_undo_added', None) or getattr(b, '_undo_spent', None))]
            if not need:
                return

    def _execute_reorg(self, new_chain: List[Block]) -> Tuple[bool, str]:
        """
        Reorganize: replace main chain with new_chain (fork that became longer).
        Uses undo_block() for O(reorg depth) rollback instead of
        rebuilding the entire UTXO set from genesis.

        Steps:
          1. Find common ancestor between current main chain and new_chain
          2. Roll back UTXO from tip down to common ancestor using undo_block()
          3. Re-apply blocks from new_chain on top of ancestor
          4. Swap chains
        """
        try:
            # 1. Find common ancestor
            new_hashes = {b.hash: i for i, b in enumerate(new_chain)}
            ancestor_height = 0
            for i, blk in enumerate(self._chain):
                if blk.hash in new_hashes:
                    ancestor_height = i

            old_fork_blocks = self._chain[ancestor_height + 1:]
            new_fork_blocks = new_chain[ancestor_height + 1:]
            if len(old_fork_blocks) > self.MAX_FORK_DEPTH:
                return False, (f"reorg of {len(old_fork_blocks)} blocks exceeds the automatic limit "
                               f"({self.MAX_FORK_DEPTH})")
            if new_fork_blocks and self._checkpoint_violation(new_fork_blocks[0], branch_height=ancestor_height):
                return False, "reorg would replace a checkpointed block"
            self._ensure_undo(old_fork_blocks)      # v10.22: reorg after a restart needs the stored undo data

            print(f"⚠️  REORG: rolling back {len(old_fork_blocks)} blocks, "
                  f"applying {len(new_fork_blocks)} new blocks "
                  f"(ancestor height {ancestor_height})")

            # 2. Snapshot current UTXO in case rollback fails
            # use snapshot()/restore() instead of direct _utxos access
            #             (was shallow copy — shared UTXOEntry refs could be corrupted)
            utxo_snapshot = self.utxo.snapshot()
            # PATCH: undo_block() clears undo data; keep a copy so a FAILED reorg
            # leaves the old chain able to reorg again later.
            _undo_backup = [(_b, list(getattr(_b, '_undo_added', [])), list(getattr(_b, '_undo_spent', [])))
                            for _b in old_fork_blocks]
            def _restore_undo():
                for _b, _a, _s in _undo_backup:
                    _b._undo_added = _a
                    _b._undo_spent = _s

            # 3. Rollback: use undo_block() on each old fork block in reverse order.
            #    This is O(reorg depth), NOT O(chain length).
            for blk in reversed(old_fork_blocks):
                ok_undo = self.utxo.undo_block(blk)
                if not ok_undo:
                    # undo data missing — fall back to full backup restore
                    self.utxo.restore(utxo_snapshot)
                    _restore_undo()   # PATCH
                    return False, f"undo_block() failed at height {blk.height} — no undo data"

            # 4. Apply new fork blocks
            for blk in new_fork_blocks:
                ok = self.utxo.apply_block(blk)
                if not ok:
                    # Rollback failed — restore backup
                    self.utxo.restore(utxo_snapshot)
                    _restore_undo()   # PATCH
                    return False, f"UTXO apply failed at height {blk.height}"

            # 5. Swap main chain
            old_chain   = self._chain[:]
            self._chain = list(new_chain)
            self.validator._chain = self._chain   # keep validator on the live chain list
            self._hash_idx = {b.hash: b.height for b in self._chain}

            # PATCH: mempool must follow the new chain (height + confirmed/conflicting txs)
            self.mempool._chain_height = self.height
            for blk in new_fork_blocks:
                self.mempool.remove_block_txs(blk)

            # 6. Return orphaned transactions to mempool
            orphaned_txids = {tx.txid for blk in new_fork_blocks
                              for tx in blk.transactions}
            for blk in old_fork_blocks:
                for tx in blk.transactions:
                    if tx.txid not in orphaned_txids and not tx.is_coinbase:
                        ok2, _ = self.mempool.submit(tx)
                        # Best-effort — ignore failures (UTXOs may conflict)

            # 7. Clean up fork storage
            self._fork_tips = {}
            self._notify_reorg(old_fork_blocks, new_fork_blocks, ancestor_height)   # v10.9

            print(f"✅ REORG complete — new tip: {self.tip.hash[:20]}... "
                  f"height {self.height}")
            return True, "OK"

        except Exception as e:
            return False, str(e)



    def get_locator(self) -> List[str]:
        """Block locator for syncing (exponential step-back)"""
        locator = []
        step    = 1
        idx     = self.height
        while idx >= 0:
            locator.append(self._chain[idx].hash)
            if len(locator) >= 10:
                step *= 2
            idx -= step
        locator.append(self._chain[0].hash)
        return list(dict.fromkeys(locator))

    def fund_address(self, address: str, amount_nbl: float,
                      fake_txid: str = None) -> 'UTXOEntry':
        """
        Fund an address directly by adding a spendable UTXO.
        Uses a non-coinbase UTXO so no maturity wait required.
        Useful for testing and development.
        only usable when _dev_mode=True to prevent production money creation.
        """
        # block this method in production — without this guard any caller
        #              (including an exposed REST endpoint) can mint coins from thin air
        if not getattr(self, '_dev_mode', False):
            raise RuntimeError(
                "fund_address() is only available in dev mode. "
                "Set blockchain._dev_mode = True explicitly in test/dev code."
            )
        import secrets as _s
        txid   = fake_txid or _s.token_hex(32)
        amount = int(amount_nbl * 10**DECIMALS)
        script = Script.p2pkh_locking_from_address(address)
        entry  = UTXOEntry(
            txid          = txid,
            index         = 0,
            value         = amount,
            script_pubkey = script,
            height        = self.height,
            is_coinbase   = False,  # not coinbase = immediately spendable
        )
        self.utxo.add(entry)
        return entry

    def chain_info(self) -> dict:
        tip = self.tip
        era = halving_era(tip.height)
        return {
            "chain":           CHAIN_NAME,
            "symbol":          CHAIN_SYMBOL,
            "chain_id":        CHAIN_ID,
            "height":          self.height,
            "best_hash":       tip.hash,
            "bits":            hex(tip.header.bits),
            "target":          hex(tip.header.target)[:20] + "...",
            "reward_nbl":      era["reward_nbl"],
            "era":             era["era_name"],
            "next_halving":    era["next_halving_at"],
            "max_supply":      f"{MAX_SUPPLY/10**DECIMALS:,.0f} NBL",
            "issued_supply":   f"{self.utxo.total_supply()/10**DECIMALS:.{DECIMALS}f} NBL",
            "utxo_set_size":   self.utxo.size(),
            "mempool_txs":     self.mempool.size(),
            "mempool_fees":    f"{self.mempool.total_fees()/10**DECIMALS:.9f} NBL",
            "available_worldwide": "Open to all humanity 🌍",
        }

    def export(self, path: str):
        data = {"info": self.chain_info(),
                "blocks": [b.to_dict() for b in self._chain]}
        with open(path, 'w') as f:
            json.dump(data, f, indent=2)
        print(f"✅ Chain exported → {path}")

    # ==============================================================
    #  PERSISTENCE  save / load  (Bitcoin-style resume)
    # ==============================================================

    def _save_json(self, data_dir: str) -> bool:
        """
        v10.20 crash-safe save (legacy JSON store, NEBULA_LEGACY_JSON=1 / migration source). Three files, same names/format as before:
          nebula_chain.json - every block (header + raw transactions)
          nebula_utxo.json  - UTXO snapshot (deterministic order)
          nebula_meta.json  - height, tip, sha256 of the two files above (written LAST)
        Every file is written to <name>.tmp, fsync'ed and moved in with os.replace().
        The previous good set is kept as <name>.prev, so a crash at any moment leaves
        at least one complete, hash-verified set on disk. Returns True on success.
        """
        try:
            dpath = Path(data_dir)
            dpath.mkdir(parents=True, exist_ok=True)
            skey = str(dpath.resolve())
            with self._lock:
                state = (skey, self.tip.hash, self.utxo.size())
                if (getattr(self, "_store_last_state", None) == state
                        and all((dpath / n).exists() for n in _STORE_NAMES)):
                    return True            # nothing changed since the last successful save
                height, tip_hash, n_blocks = self.height, self.tip.hash, len(self._chain)
                blocks_data = []
                for blk in self._chain:
                    hdr = blk.header
                    txs_raw = []
                    for tx in blk.transactions:
                        txs_raw.append({
                            "version" : tx.version,
                            "locktime": tx.locktime,
                            "inputs"  : [{"txid": i.outpoint.txid,
                                          "index": i.outpoint.index,
                                          "script_sig": i.script_sig.hex(),
                                          "sequence": i.sequence}
                                         for i in tx.inputs],
                            "outputs" : [{"value": o.value,
                                          "script_pubkey": o.script_pubkey.hex()}
                                         for o in tx.outputs],
                        })
                    blocks_data.append({
                        "version"     : hdr.version,
                        "prev_hash"   : hdr.prev_hash,
                        "merkle_root" : hdr.merkle_root,
                        "timestamp"   : hdr.timestamp,
                        "bits"        : hdr.bits,
                        "nonce"       : hdr.nonce,
                        "height"      : hdr.height,
                        "transactions": txs_raw,
                    })
                utxo_data = [{"txid": e.txid, "index": e.index,
                              "value": e.value,
                              "script_pubkey": e.script_pubkey.hex(),
                              "height": e.height,
                              "is_coinbase": e.is_coinbase}
                             for _k, e in sorted(self.utxo._utxos.items())]
                n_utxo   = len(utxo_data)
                dev_mode = bool(getattr(self, "_dev_mode", False))
                with _STORE_SEQ_LOCK:
                    _STORE_SEQ[0] += 1
                    seq = _STORE_SEQ[0]
            chain_raw = json.dumps(blocks_data, separators=(",", ":")).encode("utf-8")
            utxo_raw  = json.dumps(utxo_data,   separators=(",", ":")).encode("utf-8")
            meta = {
                "chain"      : CHAIN_NAME,
                "chain_id"   : CHAIN_ID,
                "version"    : CHAIN_VERSION,
                "format"     : _STORE_FORMAT,
                "height"     : height,
                "tip_hash"   : tip_hash,
                "saved_at"   : int(time.time()),
                "block_count": n_blocks,
                "utxo_count" : n_utxo,
                "dev_mode"   : dev_mode,
                "chain_sha256": hashlib.sha256(chain_raw).hexdigest(),
                "utxo_sha256" : hashlib.sha256(utxo_raw).hexdigest(),
            }
            meta_raw = json.dumps(meta, indent=2).encode("utf-8")
            payload = {"nebula_chain.json": chain_raw,
                       "nebula_utxo.json":  utxo_raw,
                       "nebula_meta.json":  meta_raw}
            with _STORE_IO_LOCK:
                if _STORE_LAST_WRITTEN.get(skey, 0) > seq:
                    return True            # a newer snapshot of this directory is already on disk
                tmps = {n: _store_write_tmp(dpath / n, payload[n]) for n in _STORE_NAMES}
                for n in _STORE_NAMES:     # 1) keep the last good set (hard link, never a gap)
                    _store_keep_prev(dpath / n)
                for n in _STORE_NAMES:     # 2) install; meta last = commit point
                    os.replace(str(tmps[n]), str(dpath / n))
                _store_fsync_dir(dpath)
                _STORE_LAST_WRITTEN[skey] = seq
            self._store_last_state = state
            print(f"💾 Chain saved  → height {height} | "
                  f"{n_blocks} blocks | {n_utxo} UTXOs")
            return True
        except Exception as e:
            _STORE_LOG.error("chain save FAILED: %s", e, exc_info=True)
            print(f"❌ Save failed: {e}")
            return False

    @classmethod
    def _load_set(cls, dpath: Path, sfx: str, label: str) -> "NEBULABlockchain":
        """Load + verify ONE generation (sfx '' = current, '.prev' = backup). Raises on any problem."""
        meta = json.loads((dpath / ("nebula_meta.json" + sfx)).read_text())
        if meta.get("chain_id") != CHAIN_ID:
            raise _StoreForeignChain(f"saved chain_id {meta.get('chain_id')} != {CHAIN_ID}")
        chain_raw = (dpath / ("nebula_chain.json" + sfx)).read_bytes()
        utxo_raw  = (dpath / ("nebula_utxo.json" + sfx)).read_bytes()
        fmt = int(meta.get("format", 1))
        utxo_hash_ok = True
        if fmt >= 2:
            if hashlib.sha256(chain_raw).hexdigest() != meta.get("chain_sha256"):
                raise ValueError("nebula_chain.json does not match its recorded sha256 (torn or damaged write)")
            utxo_hash_ok = hashlib.sha256(utxo_raw).hexdigest() == meta.get("utxo_sha256")
        else:
            _STORE_LOG.warning("legacy (pre-v10.20) save without checksums in %s: verifying by chain replay", dpath)
        dev_trust = bool(meta.get("dev_mode"))
        if dev_trust and not utxo_hash_ok:
            raise ValueError("nebula_utxo.json does not match its recorded sha256")
        blocks_json = json.loads(chain_raw)
        if not blocks_json:
            raise ValueError("empty chain file")
        if len(blocks_json) - 1 != meta.get("height", len(blocks_json) - 1):
            raise ValueError("meta height does not match the chain file")

        print(f"📂 Loading chain from disk  "
              f"(height {meta.get('height')}, tip {str(meta.get('tip_hash'))[:20]}...)")
        ref_genesis = cls()._chain[0].hash        # canonical genesis, built from the constants

        bc = cls._store_blank(cls)

        # 1) rebuild + structurally verify every block (no signatures here: see step 3)
        for n, bd in enumerate(blocks_json):
            cls._store_verify_append(bc, _blk_from_dict(bd), n, ref_genesis)
        if meta.get("tip_hash") and bc.tip.hash != meta["tip_hash"]:
            raise ValueError("tip hash does not match meta")

        # 2) UTXO set
        if dev_trust:
            _STORE_LOG.warning("dev-mode chain: UTXO snapshot trusted (it may hold coins not backed by blocks)")
            for ud in json.loads(utxo_raw):
                bc.utxo.add(UTXOEntry(
                    txid=ud["txid"], index=ud["index"], value=ud["value"],
                    script_pubkey=bytes.fromhex(ud["script_pubkey"]),
                    height=ud["height"], is_coinbase=ud["is_coinbase"]))
        else:
            # 3) authoritative state = replay of the verified blocks.
            #    NEBULA_VERIFY_ON_LOAD=full also re-validates every block incl. signatures (slow, pure-Python ECDSA).
            deep = os.environ.get("NEBULA_VERIFY_ON_LOAD", "").lower() == "full"
            for n, blk in enumerate(bc._chain):
                if deep and n > 0:
                    ok, why = bc.validator.validate_block(blk, bc._chain[n - 1], chain=bc._chain)
                    if not ok:
                        raise ValueError(f"block {n} failed full validation: {why}")
                if not bc.utxo.apply_block(blk):
                    raise ValueError(f"block {n}: UTXO replay failed (inputs missing)")
                # keep the pre-v10.20 behaviour: undo data is not kept across a restart
                blk._undo_spent = []
                blk._undo_added = []
            try:
                snap = {(u["txid"], u["index"], u["value"], u["script_pubkey"], u["height"], bool(u["is_coinbase"]))
                        for u in json.loads(utxo_raw)}
                real = {(e.txid, e.index, e.value, e.script_pubkey.hex(), e.height, bool(e.is_coinbase))
                        for e in bc.utxo._utxos.values()}
                if snap != real or not utxo_hash_ok:
                    _STORE_LOG.error("UTXO snapshot disagrees with chain replay (%d vs %d coins): using the replay",
                                     len(snap), len(real))
            except Exception as e:
                _STORE_LOG.error("UTXO snapshot unreadable (%s): using the replay", e)

        print(f"✅ Chain loaded  → height {bc.height} | "
              f"{len(bc._chain)} blocks | {bc.utxo.size()} UTXOs  [{label}]")
        return bc

    @classmethod
    def _load_json(cls, data_dir: str) -> "Optional['NEBULABlockchain']":
        """
        v10.20 (legacy JSON store): try the current set, then the .prev backup. Every candidate is hash-checked and the chain is
        re-verified (genesis, links, difficulty, PoW, merkle) with the UTXO set rebuilt by replay.
        A damaged set is moved aside as *.corrupt-<time> (never deleted, never silently overwritten).
        Returns None if no saved state exists or nothing usable is left (caller creates a fresh chain).
        """
        dpath = Path(data_dir)
        cands = [(lbl, sfx) for lbl, sfx in (("current", ""), ("backup", ".prev"))
                 if all((dpath / (n + sfx)).exists() for n in _STORE_NAMES)]
        if not cands:
            return None
        failed = []
        for lbl, sfx in cands:
            try:
                bc = cls._load_set(dpath, sfx, lbl)
            except _StoreForeignChain as e:
                print(f"⚠️  {e} — ignoring")
                return None
            except Exception as e:
                _STORE_LOG.error("saved chain (%s) is unusable: %s", lbl, e, exc_info=True)
                print(f"❌ Load failed ({lbl}): {e}")
                failed.append((lbl, sfx))
                continue
            for flbl, fsfx in failed:          # fell back to an older good set: park the bad one
                _store_quarantine(dpath, fsfx)
            if failed:
                _STORE_LOG.warning("recovered from the %s set (the newest save was damaged)", lbl)
                print(f"⚠️  Recovered from the {lbl} copy — the newest save was damaged")
            return bc
        for _lbl, sfx in failed:
            _store_quarantine(dpath, sfx)
        print("❌ No usable saved chain — damaged files were kept as *.corrupt-*; starting fresh chain")
        return None

    @staticmethod
    def _store_legacy_mode() -> bool:
        return os.environ.get("NEBULA_LEGACY_JSON", "") == "1"

    def save(self, data_dir: str) -> bool:
        """
        v10.21: incremental SQLite store (<data_dir>/nebula_chain.db). The first call attaches a live listener,
        so every later block/reorg is committed immediately in one transaction; save() itself only writes what is
        missing (O(new blocks), not O(chain)). NEBULA_LEGACY_JSON=1 keeps the v10.20 whole-chain JSON files.
        """
        if self._store_legacy_mode():
            return self._save_json(data_dir)
        try:
            dpath = Path(data_dir)
            dpath.mkdir(parents=True, exist_ok=True)
            st = _ChainStore.attach(self, dpath)
            if not st.sync(self):
                print("❌ Save failed: see log (nebula.storage)")
                return False
            print(f"💾 Chain saved  → height {st.tip_h} | {st.tip_h + 1} blocks | {st.count} UTXOs  [sqlite]")
            return True
        except Exception as e:
            _STORE_LOG.error("chain save FAILED: %s", e, exc_info=True)
            print(f"❌ Save failed: {e}")
            return False

    @staticmethod
    def _store_blank(cls_) -> "NEBULABlockchain":
        bc = cls_.__new__(cls_)
        bc._chain    = []
        bc.utxo      = UTXOSet()
        bc.mempool   = Mempool(bc.utxo)
        bc.validator = ChainValidator(bc.utxo, bc._chain)
        bc._lock     = threading.RLock()
        bc._hash_idx = {}
        # load() bypasses __init__, so the attributes add_block() needs must be set here.
        bc._fork_tips = {}
        bc._dev_mode  = False
        bc._listeners = []
        return bc

    @staticmethod
    def _store_verify_append(bc, blk, n: int, ref_genesis: str) -> None:
        """Structural checks for block n (genesis, link, height, difficulty, PoW, coinbase, merkle), then append."""
        hdr, txs = blk.header, blk.transactions
        if n == 0:
            if blk.hash != ref_genesis:
                raise ValueError("stored genesis block is not the NEBULA genesis block")
        else:
            prev = bc._chain[-1]
            if hdr.prev_hash != prev.hash or hdr.height != prev.height + 1:
                raise ValueError(f"block {n}: broken link / height")
            exp = bc.validator.expected_bits(prev, bc._chain)
            if exp is None or hdr.bits != exp:
                raise ValueError(f"block {n}: wrong difficulty bits")
            if not hdr.meets_target():
                raise ValueError(f"block {n}: proof of work insufficient")
            if not txs or not txs[0].is_coinbase:
                raise ValueError(f"block {n}: first tx is not a coinbase")
            if not blk.verify_merkle():
                raise ValueError(f"block {n}: merkle root mismatch")
        bc._chain.append(blk)
        bc._hash_idx[blk.hash] = blk.height

    @classmethod
    def _load_db(cls, dpath: Path) -> "NEBULABlockchain":
        st = _ChainStore(dpath / _DB_NAME)
        try:
            if st.con.execute("PRAGMA quick_check").fetchone()[0] != "ok":
                raise ValueError("sqlite quick_check failed (database file is damaged)")
            cid = st._meta("chain_id")
            if cid is None:
                raise ValueError("database has no chain metadata")
            if str(cid) != str(CHAIN_ID):
                raise _StoreForeignChain(f"saved chain_id {cid} != {CHAIN_ID}")
            if st.tip_h < 0:
                raise ValueError("database holds no blocks")
            print(f"📂 Loading chain from database  (height {st.tip_h}, tip {str(st.tip_hash)[:20]}...)")
            ref_genesis = cls()._chain[0].hash
            bc = cls._store_blank(cls)
            n = 0
            for h, data in st.con.execute("SELECT height, data FROM blocks ORDER BY height"):
                if h != n:
                    raise ValueError(f"block rows are not contiguous (expected {n}, found {h})")
                cls._store_verify_append(bc, _blk_from_dict(json.loads(data)), n, ref_genesis)
                n += 1
            if n - 1 != st.tip_h or bc.tip.hash != st.tip_hash:
                raise ValueError("block rows do not match the recorded tip")
            acc, cnt = 0, 0
            for k, txid, idx, value, script, height, cb in st.con.execute(
                    "SELECT k,txid,idx,value,script,height,cb FROM utxo"):
                bc.utxo.add(UTXOEntry(txid=txid, index=idx, value=value, script_pubkey=bytes(script),
                                      height=height, is_coinbase=bool(cb)))
                acc = (acc + _utxo_h(k, value, script, height, cb)) % _ACC_MOD
                cnt += 1
            if acc != st.acc or cnt != st.count:
                raise ValueError("UTXO table does not match its recorded commitment (damaged or edited)")
            mode = os.environ.get("NEBULA_VERIFY_ON_LOAD", "").lower()
            if mode in ("replay", "full") and not int(st._meta("dev_mode", 0)):
                scratch, chk = UTXOSet(), None
                if mode == "full":
                    chk = ChainValidator(scratch, bc._chain)
                saved = [(b, getattr(b, "_undo_spent", []), getattr(b, "_undo_added", [])) for b in bc._chain]
                try:
                    for i, b in enumerate(bc._chain):
                        if chk is not None and i > 0:
                            ok, why = chk.validate_block(b, bc._chain[i - 1], chain=bc._chain)
                            if not ok:
                                raise ValueError(f"block {i} failed full validation: {why}")
                        if not scratch.apply_block(b):
                            raise ValueError(f"block {i}: UTXO replay failed")
                finally:
                    for b, s, a in saved:
                        b._undo_spent, b._undo_added = s, a
                same = {(e.txid, e.index, e.value, e.script_pubkey, e.height, bool(e.is_coinbase))
                        for e in scratch._utxos.values()} == \
                       {(e.txid, e.index, e.value, e.script_pubkey, e.height, bool(e.is_coinbase))
                        for e in bc.utxo._utxos.values()}
                if not same:
                    raise ValueError("UTXO table disagrees with the replay of the stored blocks")
            st.bc = bc
            bc.__dict__.setdefault("_chain_stores", {})[str(dpath.resolve())] = st
            bc.add_listener(st)
            print(f"✅ Chain loaded  → height {bc.height} | {len(bc._chain)} blocks | "
                  f"{bc.utxo.size()} UTXOs  [sqlite]")
            return bc
        except BaseException:
            st.close()
            raise

    @classmethod
    def load(cls, data_dir: str) -> "Optional['NEBULABlockchain']":
        """[v10.25] Load the chain, then sync the mempool height. Before, a node restarted from disk kept
        mempool._chain_height == 0 until the next block arrived, so the mempool rejected every payment that
        spends a mature coinbase output ("Coinbase UTXO not mature ... current 0")."""
        bc = cls._load_impl(data_dir)
        if bc is not None:
            bc.mempool._chain_height = bc.height
        return bc

    @classmethod
    def _load_impl(cls, data_dir: str) -> "Optional['NEBULABlockchain']":
        """
        v10.21: prefer the SQLite store; a damaged database is moved aside (*.corrupt-<time>) and the v10.20 JSON
        files (if any) are tried next. A JSON-only data dir is migrated into the database automatically.
        NEBULA_LEGACY_JSON=1 -> v10.20 behaviour only.
        """
        if cls._store_legacy_mode():
            return cls._load_json(data_dir)
        dpath = Path(data_dir)
        if (dpath / _DB_NAME).exists():
            try:
                return cls._load_db(dpath)
            except _StoreForeignChain as e:
                print(f"⚠️  {e} — ignoring")
                return None
            except Exception as e:
                _STORE_LOG.error("chain database is unusable: %s", e, exc_info=True)
                print(f"❌ Database load failed: {e}")
                _store_quarantine_db(dpath)
        bc = cls._load_json(data_dir)
        if bc is not None:
            try:
                _ChainStore.attach(bc, dpath).sync(bc)
                print("📦 Migrated the JSON chain files into nebula_chain.db (JSON files left untouched)")
            except Exception as e:
                _STORE_LOG.error("migration to sqlite failed (JSON load still used): %s", e, exc_info=True)
        return bc

    # tip_hash - needed by API and BlockTemplateBuilder
    def tip_hash(self) -> str:
        return self.tip.hash

    # add_to_mempool - needed by API /api/wallet/send
    def add_to_mempool(self, tx) -> tuple:
        return self.mempool.submit(tx)

    # get_balance - needed by API /api/address/<addr>
    def get_balance(self, address: str) -> dict:
        bal = self.utxo.balance(address)
        utxos = self.utxo.get_by_address(address)
        return {
            "address":     address,
            "balance_nbl": bal / 10 ** DECIMALS,
            "balance_neb": bal,
            "balance_sat": bal,
            "utxo_count":  len(utxos),
            "tx_count":    len(set(u.txid for u in utxos)),
        }

    # build_coinbase() — required by mine_one_block_demo() and tests
    def build_coinbase(self, height: int, miner_address: str,
                       extra_data: bytes = b'') -> Transaction:
        """Build a coinbase transaction for the given height and miner address."""
        reward = mining_reward(height)
        return Transaction.coinbase(
            height        = height,
            reward        = reward,
            miner_address = miner_address,
            extra_data    = extra_data,
        )

    # next_bits alias - used by BlockTemplateBuilder
    def next_bits(self) -> int:
        return self.get_next_bits()

    # full address info for explorer
    def get_address_info(self, address: str) -> dict:
        info = self.get_balance(address)
        # v10.10: with the transaction index attached, tx_count is the real number of
        # transactions touching the address (before: number of distinct txids among UNSPENT outputs)
        _ti = getattr(self, "_tx_index", None)
        if _ti is not None:
            try:
                info["tx_count"] = _ti.address_tx_count(address)
                info["recent_txids"] = _ti.address_txids(address, 10)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULABlockchain.get_address_info", exc_info=True)
        info["utxos"] = [
            {"txid": u.txid, "index": u.index,
             "value_nbl": u.value / 10 ** DECIMALS,
             "height": u.height}
            for u in self.utxo.get_by_address(address)
        ]
        return info



# ================================================================
#  EXTENDED CHAIN ANALYTICS  (nebula_core.py extension)
# ================================================================

class ChainAnalytics:
    """
    In-memory analytics computed directly from the blockchain.
    Answers common questions without a separate indexer.
    """

    def __init__(self, chain: "NEBULABlockchain"):
        self.chain = chain

    # ── supply ──────────────────────────────────────────────────

    def circulating_supply(self) -> int:
        """Sum of all UTXO values = circulating supply in Neb.
        NEBULABlockchain uses self.utxo (UTXOSet), not self.utxo_set."""
        if hasattr(self.chain, 'utxo') and hasattr(self.chain.utxo, '_utxos'):
            return sum(e.value for e in self.chain.utxo._utxos.values())
        return 0

    def total_mined(self) -> int:
        """Total NBL emitted so far (block rewards only)."""
        total = 0
        for era in range(9):
            reward   = INITIAL_BLOCK_REWARD >> era
            era_start= era * HALVING_INTERVAL
            era_end  = (era + 1) * HALVING_INTERVAL
            blocks   = max(0, min(self.chain.height + 1, era_end) - era_start)
            total   += reward * blocks
        return total

    # ── block iteration ─────────────────────────────────────────

    def iter_blocks(self) -> _Iter["Block"]:
        """Iterate all blocks in order from genesis.
        NEBULABlockchain stores blocks in self._chain (a list),
        not self._blocks / self._height_index."""
        if hasattr(self.chain, '_chain'):
            for b in self.chain._chain:
                yield b

    def block_at(self, height: int) -> "Optional[Block]":
        """use self._chain list directly."""
        if hasattr(self.chain, '_chain'):
            if 0 <= height < len(self.chain._chain):
                return self.chain._chain[height]
        return None

    # ── tx throughput ────────────────────────────────────────────

    def avg_tx_per_block(self, last_n: int = 144) -> float:
        """Average TXs per block over last N blocks."""
        counts = []
        for b in self.iter_blocks():
            counts.append(len(b.transactions))
        if not counts:
            return 0.0
        sample = counts[-last_n:]
        return sum(sample) / len(sample)

    def tx_count_total(self) -> int:
        total = 0
        for b in self.iter_blocks():
            total += len(b.transactions)
        return total

    # ── difficulty ───────────────────────────────────────────────

    def difficulty_history(self, last_n: int = 20) -> list:
        result = []
        for b in self.iter_blocks():
            if hasattr(b.header, 'bits'):
                d = bits_to_target(b.header.bits) if hasattr(b.header,'bits') else 0
                result.append(d)
        return result[-last_n:]

    # ── mempool snapshot ─────────────────────────────────────────

    def mempool_snapshot(self) -> dict:
        # Mempool stores transactions in self._txs, not self._pool
        mp = self.chain.mempool
        pool = mp._txs if hasattr(mp, '_txs') else {}
        return {
            "count"       : len(pool),
            "txids"       : list(pool.keys())[:20],
        }

    # ── chain summary ────────────────────────────────────────────

    def summary(self) -> dict:
        return {
            "height"           : self.chain.height,
            "tip_hash"         : self.chain.tip_hash(),
            "circulating_supply": self.circulating_supply() / 10**DECIMALS,
            "total_mined"      : self.total_mined() / 10**DECIMALS,
            "avg_tx_per_block" : round(self.avg_tx_per_block(), 2),
            "tx_count_total"   : self.tx_count_total(),
            "mempool"          : self.mempool_snapshot(),
        }


