# ================================================================
#  BLOCK TEMPLATE BUILDER (standalone)
# ================================================================
class BlockTemplateBuilder:
    """
    Build a block template ready for mining.
    Selects transactions from the mempool by fee rate,
    builds the Merkle root, and prepares the header.
    """

    def __init__(self, chain: "NEBULABlockchain"):
        self.chain = chain

    def build(self, miner_address: str, extra_nonce: int = 0) -> dict:
        height       = self.chain.height + 1
        reward       = mining_reward(height)
        prev_hash    = self.chain.tip_hash()
        bits         = self.chain.next_bits()
        target       = bits_to_target(bits)
        ts           = int(time.time())

        # Select transactions
        # Mempool has get_for_block(), not top(). Using .top() always
        # fell through to txs=[] meaning zero fees were ever collected.
        mp       = self.chain.mempool
        txs      = mp.get_for_block(max_bytes=950_000)

        # Compute fees
        # FIX v10.5: real per-tx fees (were hard-coded 0 -> template under-paid the miner)
        total_fee = 0
        tx_data   = []
        for tx in txs:
            fee  = tx.fee(self.chain.utxo)
            total_fee += fee
            tx_data.append({"txid": tx.txid, "size": len(tx.serialize()), "fee": fee,
                            "data": tx.serialize().hex()})

        # Build the REAL coinbase (reward + fees). FIX v10.5: the txid used to be a
        # made-up hash, so the merkle root in the template never matched a valid block.
        coinbase_value = reward + total_fee
        cb_tx    = Transaction.coinbase(height=height, reward=coinbase_value,
                                        miner_address=miner_address,
                                        extra_data=extra_nonce.to_bytes(8, 'little'))
        cb_txid  = cb_tx.txid
        tx_hashes= [cb_txid] + [t["txid"] for t in tx_data]
        merkle   = MerkleTree.compute_root(tx_hashes)

        return {
            "version"          : 1,
            "previousblockhash": prev_hash,
            "transactions"     : tx_data,
            "coinbaseaux"      : {"flags": ""},
            "coinbasevalue"    : coinbase_value,
            "coinbasetxn"      : {"txid": cb_txid, "data": cb_tx.serialize().hex()},
            "target"           : f"{target:064x}",
            "mintime"          : ts - 600,
            "curtime"          : ts,
            "bits"             : f"{bits:08x}",
            "height"           : height,
            "merkleroot"       : merkle,
            "miner_address"    : miner_address,
        }



