# ================================================================
#  MESSAGE TYPES
# ================================================================

class MsgType(str, Enum):
    VERSION    = "version"
    VERACK     = "verack"
    PING       = "ping"
    PONG       = "pong"
    GETBLOCKS  = "getblocks"
    GETDATA    = "getdata"
    BLOCK      = "block"
    TX         = "tx"
    INV        = "inv"
    HEADERS    = "headers"
    GETHEADERS = "getheaders"
    GETADDR    = "getaddr"
    ADDR       = "addr"
    REJECT     = "reject"
    MEMPOOL    = "mempool"
    GETINFO    = "getinfo"
    INFO       = "info"

# ================================================================
#  PEER STATE
# ================================================================

class PeerState(Enum):
    CONNECTING   = "connecting"
    HANDSHAKING  = "handshaking"
    CONNECTED    = "connected"
    SYNCING      = "syncing"
    DISCONNECTED = "disconnected"
    BANNED       = "banned"

@dataclass
class PeerInfo:
    host:          str
    port:          int
    state:         PeerState    = PeerState.CONNECTING
    version:       int          = 0
    chain_id:      int          = 0
    height:        int          = 0
    user_agent:    str          = ""
    connected_at:  float        = field(default_factory=time.time)
    last_seen:     float        = field(default_factory=time.time)
    bytes_sent:    int          = 0
    bytes_recv:    int          = 0
    latency_ms:    float        = 0.0
    ping_nonce:    int          = 0
    ping_sent:     float        = 0.0
    failures:      int          = 0

    @property
    def addr(self) -> str:
        return f"{self.host}:{self.port}"

# ================================================================
#  MESSAGE CODEC
# ================================================================

class Message:
    """
    NEBULA network message:
    [ magic(4) | type(12) | length(4) | checksum(4) | payload ]
    """
    HEADER_SIZE = 24

    def __init__(self, msg_type: str, payload: dict = None):
        self.type    = msg_type
        self.payload = payload or {}

    def encode(self) -> bytes:
        body     = json.dumps(self.payload, separators=(',', ':')).encode('utf-8')
        checksum = sha256d(body)[:4]
        type_bytes = self.type.encode('utf-8').ljust(12, b'\x00')[:12]
        header = (
            MAINNET_MAGIC +
            type_bytes +
            struct.pack('<I', len(body)) +
            checksum
        )
        return header + body

    @classmethod
    def decode(cls, data: bytes) -> Optional['Message']:
        if len(data) < cls.HEADER_SIZE:
            return None
        magic    = data[:4]
        msg_type = data[4:16].rstrip(b'\x00').decode('utf-8')
        length   = struct.unpack_from('<I', data, 16)[0]
        checksum = data[20:24]
        body     = data[24:24+length]
        if sha256d(body)[:4] != checksum:
            return None
        payload = json.loads(body.decode('utf-8'))
        return cls(msg_type, payload)

    MAX_PAYLOAD_SIZE = 32 * 1024 * 1024   # 32 MB hard cap — prevents memory-exhaustion DoS

    @classmethod
    def peek_length(cls, data: bytes) -> Optional[int]:
        if len(data) < cls.HEADER_SIZE:
            return None
        length = struct.unpack_from('<I', data, 16)[0]
        if length > cls.MAX_PAYLOAD_SIZE:   # reject oversized messages immediately
            raise ValueError(f"P2P message too large: {length} bytes (max {cls.MAX_PAYLOAD_SIZE})")
        return length + cls.HEADER_SIZE

# ================================================================
#  PEER CONNECTION
# ================================================================

class PeerConnection:
    """Manages a single peer connection"""

    RECV_BUF = 1 << 20   # 1 MB receive buffer

    def __init__(self,
                 host:     str,
                 port:     int,
                 node:     'P2PNode',
                 sock:     socket.socket = None,
                 inbound:  bool = False):
        self.info    = PeerInfo(host=host, port=port)
        self.node    = node
        self._sock   = sock
        self.inbound = inbound
        self._buf    = b''
        self._lock   = threading.Lock()
        self._running = False

    def connect(self) -> bool:
        try:
            self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self._sock.settimeout(10)
            self._sock.connect((self.info.host, self.info.port))
            self._sock = _nebula_p2p_wrap_outbound(self._sock, self.info.host, self.info.port)   # v10.19: TLS 1.3
            self._sock.settimeout(None)
            return True
        except Exception as e:
            self.info.state = PeerState.DISCONNECTED
            return False

    def start(self):
        self._running = True
        t = threading.Thread(target=self._recv_loop, daemon=True,
                              name=f"Peer-{self.info.addr}")
        t.start()
        # Send version immediately
        self._send_version()

    def send(self, msg: Message) -> bool:
        try:
            with self._lock:
                data = msg.encode()
                self._sock.sendall(data)
                self.info.bytes_sent += len(data)
                return True
        except Exception:
            self.disconnect()
            return False

    def _recv_loop(self):
        self._sock.settimeout(30)
        while self._running:
            try:
                chunk = self._sock.recv(self.RECV_BUF)
                if not chunk:
                    break
                self.info.bytes_recv += len(chunk)
                self.info.last_seen   = time.time()
                self._buf += chunk
                self._process_buf()
            except socket.timeout:
                self._ping()
            except Exception:
                break
        self.disconnect()

    def _process_buf(self):
        while True:
            try:
                needed = Message.peek_length(self._buf)
            except ValueError:
                # peer sent an oversized message — disconnect immediately
                log.warning("Peer %s sent oversized message — disconnecting", self.info.addr)
                self.disconnect()
                return
            if needed is None or len(self._buf) < needed:
                break
            msg_data  = self._buf[:needed]
            self._buf = self._buf[needed:]
            msg = Message.decode(msg_data)
            if msg:
                self.node._handle_message(self, msg)

    def _send_version(self):
        self.send(Message(MsgType.VERSION, {
            "version":    PROTOCOL_VERSION,
            "chain_id":   CHAIN_ID,
            "height":     self.node.bc.height,
            "user_agent": f"/NEBULA:{CHAIN_ID}/",
            "timestamp":  int(time.time()),
            "addr_from":  f"{self.node.host}:{self.node.port}",
        }))
        self.info.state = PeerState.HANDSHAKING

    def _ping(self):
        nonce = int(time.time() * 1000) & 0xFFFFFFFF
        self.info.ping_nonce = nonce
        self.info.ping_sent  = time.time()
        self.send(Message(MsgType.PING, {"nonce": nonce}))

    def disconnect(self):
        self._running = False
        try:
            self._sock.close()
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in PeerConnection.disconnect", exc_info=True)
        self.info.state = PeerState.DISCONNECTED
        self.node._on_peer_disconnect(self)

