class P2PNode:
    """
    Full NEBULA P2P node.
    Handles peer discovery, handshake, block sync, tx relay.
    DoS protection and rate limiting integrated.
    """

    def __init__(self,
                 bc:    NEBULABlockchain,
                 host:  str = "0.0.0.0",
                 port:  int = DEFAULT_PORT,
                 data_dir: str = None):
        self.bc      = bc
        self.host    = host
        self.port    = port
        self._peers: Dict[str, PeerConnection] = {}
        self._banned: Set[str] = set()
        self._lock    = threading.RLock()
        self._running = False
        self._known_invs: Set[str] = set()   # avoid rebroadcast
        _nebula_p2p_configure(data_dir)      # v10.19: TLS identity + pins live in <data_dir>/p2p_tls
        self.orphan_pool = OrphanPool()      # v10.10: blocks that arrive before their parent
        self._orphan_sync_t: Dict[str, float] = {}   # v10.10: per-peer rate limit for re-sync
        # v10.11: peer address book (ADDR gossip, reconnect after restart; persisted to <data_dir>/peers.json)
        self.addr_book = PeerAddressBook()
        self._addr_file = os.path.join(str(data_dir), "peers.json") if data_dir else None
        if self._addr_file:
            self.addr_book.load(self._addr_file)
        self._addr_saved = time.time()
        self._book_busy = False
        # Manual peers ("host:port"), e.g. from `--peers` or NEBULA_PEERS. Dialled first and re-dialled while the
        # node has no connection. Network layer only: never touches consensus rules.
        self.extra_peers: List[Tuple[str, int]] = parse_peer_list(os.environ.get("NEBULA_PEERS", ""))

        # ── Security () ──────────────────────────────────
        self._dos      = DoSProtection()
        self._rate_lim = RateLimiter(rate_per_sec=20.0, burst=100)

        # Callbacks
        self.on_new_block: Optional[Callable] = None
        self.on_new_tx:    Optional[Callable] = None

    def start(self):
        self._running = True
        # Listen for inbound
        threading.Thread(target=self._listen, daemon=True, name="P2P-Listen").start()
        # Connect to seeds
        threading.Thread(target=self._seed_connect, daemon=True, name="P2P-Seeds").start()
        # Maintenance loop
        threading.Thread(target=self._maintenance, daemon=True, name="P2P-Maint").start()
        print(f"🌐 P2P Node listening on {self.host}:{self.port}")

    def stop(self):
        self._running = False
        with self._lock:
            for peer in list(self._peers.values()):
                peer.disconnect()
        if self._addr_file:                       # v10.11
            self.addr_book.save(self._addr_file)

    def connect_peer(self, host: str, port: int) -> bool:
        addr = f"{host}:{port}"
        if addr in self._banned:
            return False
        with self._lock:
            if addr in self._peers:
                return False
            if len(self._peers) >= MAX_PEERS:
                return False

        peer = PeerConnection(host, port, self)
        if not peer.connect():
            self.addr_book.mark_attempt(host, port)     # v10.11
            return False

        self.addr_book.add(host, port, source="outbound", trusted=True)   # v10.11: remember what we dialled
        with self._lock:
            self._peers[addr] = peer
        peer.start()
        return True

    def _connect_from_book(self, max_new: int = 8) -> int:
        """v10.11: dial remembered peers (best first). Used after DNS/static seeds and whenever the
        node is short of peers. Returns how many were tried."""
        with self._lock:
            have = set(self._peers)
        tried = 0
        for h, po in self.addr_book.candidates(max_new * 3, exclude=have | self._banned):
            if not self._running or tried >= max_new:
                break
            if h in self._banned or self._dos.is_banned(h):
                continue
            tried += 1
            try:
                self.connect_peer(h, po)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in P2PNode._connect_from_book", exc_info=True)
        return tried

    def broadcast_block(self, block: Block):
        """Broadcast new block to all peers"""
        inv_msg = Message(MsgType.INV, {
            "type":  "block",
            "items": [block.hash],
        })
        self._broadcast(inv_msg)

    def broadcast_tx(self, tx: Transaction):
        """Broadcast transaction to all peers"""
        inv_msg = Message(MsgType.INV, {
            "type":  "tx",
            "items": [tx.txid],
        })
        self._broadcast(inv_msg)

    def _broadcast(self, msg: Message):
        with self._lock:
            peers = list(self._peers.values())
        for peer in peers:
            if peer.info.state == PeerState.CONNECTED:
                peer.send(msg)

    def _listen(self):
        try:
            srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            srv.bind((self.host, self.port))
            srv.listen(50)
            srv.settimeout(1)
            while self._running:
                try:
                    conn, addr = srv.accept()
                    host, port = addr
                    # DoS / ban check ()
                    if host in self._banned or self._dos.is_banned(host):
                        conn.close()
                        continue
                    if not self._rate_lim.allow(host):
                        conn.close()
                        continue
                    conn = _nebula_p2p_wrap_inbound(conn)      # v10.19: TLS 1.3 (None = refused)
                    if conn is None:
                        continue
                    peer = PeerConnection(host, port, self, sock=conn, inbound=True)
                    with self._lock:
                        if len(self._peers) < MAX_PEERS:
                            key = f"{host}:{port}"
                            self._peers[key] = peer
                            peer.start()
                        else:
                            conn.close()
                except socket.timeout:
                    continue
        except Exception as e:
            print(f"Listen error: {e}")

    def _connect_extra_peers(self) -> int:
        """Dial the manually configured peers (see extra_peers). Returns how many connections succeeded."""
        ok = 0
        for host, port in list(self.extra_peers):
            if not self._running:
                break
            try:
                if self.connect_peer(host, port):
                    ok += 1
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in P2PNode._connect_extra_peers", exc_info=True)
        return ok

    def _seed_connect(self):
        time.sleep(1)
        self._connect_extra_peers()          # manual peers first
        try:                                  # community seed list (seeds.txt on GitHub)
            for _h, _p in fetch_seed_list():
                if not self._running:
                    return
                try:
                    self.connect_peer(_h, _p)
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in seed list dial", exc_info=True)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in fetch_seed_list", exc_info=True)
        # First try DNS seeds for dynamic peer discovery
        dns_peers = resolve_dns_seeds()
        for ip, port in dns_peers:
            if not self._running:
                return
            try:
                self.connect_peer(ip, port)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in P2PNode._seed_connect", exc_info=True)
        # Then try static seed nodes
        for host, port in SEED_NODES:
            if not self._running:
                break
            try:
                socket.setdefaulttimeout(5)
                addrs = socket.getaddrinfo(host, port,
                                           socket.AF_UNSPEC,
                                           socket.SOCK_STREAM)
                if addrs:
                    self.connect_peer(host, port)
            except Exception as e:
                # log seed connectivity failures so operator can diagnose
                log.debug(f"Seed node {host}:{port} not reachable: {e}")
        # v10.11: peers remembered from earlier runs / ADDR gossip
        if self._running:
            self._connect_from_book(8)

    def _maintenance(self):
        """Periodic: ping peers, drop stale, find new"""
        while self._running:
            time.sleep(30)
            now = time.time()
            with self._lock:
                stale = [addr for addr, p in self._peers.items()
                         if (p.info.state == PeerState.DISCONNECTED or
                             now - p.info.last_seen > 120)]
                for addr in stale:
                    self._peers.pop(addr, None)

            # Manual peers: if we are not connected to anyone, try them again (they may have been offline at start)
            if self.extra_peers:
                with self._lock:
                    _none = not any(p.info.state == PeerState.CONNECTED for p in self._peers.values())
                if _none:
                    self._connect_extra_peers()

            # Ask connected peers for more peers
            with self._lock:
                connected = [p for p in self._peers.values()
                             if p.info.state == PeerState.CONNECTED]
            for peer in connected:
                peer.send(Message(MsgType.GETADDR))

            # v10.11: short of peers -> redial remembered ones (background, never overlapping);
            # persist the address book every 5 minutes
            if len(connected) < 4 and not self._book_busy and self.addr_book.size():
                self._book_busy = True
                def _redial():
                    try:
                        self._connect_from_book(4)
                    finally:
                        self._book_busy = False
                threading.Thread(target=_redial, daemon=True, name="P2P-Redial").start()
            if self._addr_file and now - self._addr_saved > 300:
                self._addr_saved = now
                self.addr_book.save(self._addr_file)

    def _handle_message(self, peer: PeerConnection, msg: Message):
        """Route incoming messages"""
        t = msg.type
        p = msg.payload

        if t == MsgType.VERSION:
            peer.info.version    = p.get("version", 0)
            peer.info.chain_id   = p.get("chain_id", 0)
            peer.info.height     = p.get("height", 0)
            peer.info.user_agent = p.get("user_agent", "")
            if peer.info.chain_id != CHAIN_ID:
                # punish wrong chain
                if self._dos.punish(peer.info.host, "wrong_chain_id"):
                    self._banned.add(peer.info.host)
                if not peer.inbound:
                    self.addr_book.remove(peer.info.host, peer.info.port)   # v10.11
                peer.disconnect()
                return
            if not peer.inbound:
                self.addr_book.mark_good(peer.info.host, peer.info.port)    # v10.11: right chain, reachable
            peer.send(Message(MsgType.VERACK))
            peer.info.state = PeerState.CONNECTED
            # Ask for blocks if they're ahead
            if peer.info.height > self.bc.height:
                self._request_sync(peer)

        elif t == MsgType.VERACK:
            peer.info.state = PeerState.CONNECTED

        elif t == MsgType.PING:
            peer.send(Message(MsgType.PONG, {"nonce": p.get("nonce", 0)}))

        elif t == MsgType.PONG:
            if p.get("nonce") == peer.info.ping_nonce:
                peer.info.latency_ms = (time.time() - peer.info.ping_sent) * 1000

        elif t == MsgType.INV:
            self._handle_inv(peer, p)

        elif t == MsgType.GETDATA:
            self._handle_getdata(peer, p)

        elif t == MsgType.GETBLOCKS:
            self._handle_getblocks(peer, p)

        elif t == MsgType.BLOCK:
            self._handle_block(peer, p)

        elif t == MsgType.TX:
            self._handle_tx(peer, p)

        elif t == MsgType.GETADDR:
            # v10.11: advertise OUTBOUND peers (an inbound peer's source port is ephemeral and useless to
            # others) plus addresses from the book that we reached recently
            with self._lock:
                addrs = [{"host": c.info.host, "port": c.info.port}
                         for c in self._peers.values()
                         if c.info.state == PeerState.CONNECTED and not c.inbound]
            seen = {(a["host"], a["port"]) for a in addrs}
            for a in self.addr_book.gossip_list(100):
                if (a["host"], a["port"]) not in seen:
                    addrs.append(a)
            peer.send(Message(MsgType.ADDR, {"addrs": addrs[:100]}))

        elif t == MsgType.ADDR:
            # v10.11: validate + remember gossiped addresses (bounded), then dial only the NEW ones
            items = p.get("addrs", [])
            if not isinstance(items, list):
                return
            fresh = []
            for addr_info in items[:100]:
                if not isinstance(addr_info, dict):
                    continue
                h, po = addr_info.get("host"), addr_info.get("port", DEFAULT_PORT)
                if self.addr_book.add(h, po, source="gossip"):
                    fresh.append((h, po))
            for h, po in fresh[:20]:
                key = f"{h}:{po}"
                if (key not in self._peers and key not in self._banned and h not in self._banned
                        and not self._dos.is_banned(h)):
                    threading.Thread(target=self.connect_peer, args=(h, po),
                                     daemon=True).start()

        elif t == MsgType.GETINFO:
            peer.send(Message(MsgType.INFO, self.bc.chain_info()))

    def _handle_inv(self, peer: PeerConnection, p: dict):
        inv_type  = p.get("type")
        items     = p.get("items", [])
        needed    = [i for i in items if i not in self._known_invs]
        if inv_type == "block":   # FIX v10.2: skip blocks we already have (stops relay loops)
            needed = [i for i in needed if not self.bc.get_block_by_hash(i)]
        elif inv_type == "tx":    # FIX v10.3: skip txs we already have
            needed = [i for i in needed if i not in self.bc.mempool._txs]
        if needed:
            peer.send(Message(MsgType.GETDATA, {"type": inv_type, "items": needed}))

    def _handle_getdata(self, peer: PeerConnection, p: dict):
        """FIX v10.2: answer GETDATA for announced blocks (INV -> GETDATA -> BLOCK).
        Without this, new blocks never propagated after the initial sync."""
        items = p.get("items", [])
        if not isinstance(items, list):
            return
        if p.get("type") == "tx":   # FIX v10.3: serve transactions from our mempool
            for txid in items[:MAX_BLOCKS_AT_ONCE]:
                tx = self.bc.mempool._txs.get(txid) if isinstance(txid, str) else None
                if tx is not None:
                    peer.send(Message(MsgType.TX, {"tx": tx.to_dict()}))
            return
        if p.get("type") != "block":
            return
        blocks_to_send = []
        for h_str in items[:MAX_BLOCKS_AT_ONCE]:
            if not isinstance(h_str, str):
                continue
            blk = self.bc.get_block_by_hash(h_str)
            if blk:
                blocks_to_send.append(blk.to_dict())
        if blocks_to_send:
            peer.send(Message(MsgType.BLOCK, {"blocks": blocks_to_send}))

    def _handle_getblocks(self, peer: PeerConnection, p: dict):
        start_hash = p.get("hash_stop", "")
        start_h    = 0
        for h_str in p.get("locator", []):
            blk = self.bc.get_block_by_hash(h_str)
            if blk:
                start_h = blk.height + 1
                break

        blocks_to_send = []
        for i in range(start_h, min(start_h + MAX_BLOCKS_AT_ONCE, self.bc.height + 1)):
            blk = self.bc.get_block(i)
            if blk:
                blocks_to_send.append(blk.to_dict())

        if blocks_to_send:
            peer.send(Message(MsgType.BLOCK, {"blocks": blocks_to_send}))

    def _handle_block(self, peer: PeerConnection, p: dict):
        """Deserialize blocks from peer and add to chain"""
        for blk_dict in p.get("blocks", []):
            blk_hash = blk_dict.get("hash", "")
            if blk_hash in self._known_invs:
                continue
            self._known_invs.add(blk_hash)
            # Limit _known_invs memory growth
            if len(self._known_invs) > 50_000:
                # Remove oldest half
                items = list(self._known_invs)
                self._known_invs = set(items[len(items)//2:])
            try:
                block = self._deserialize_block(blk_dict)
                if block is not None:
                    ok, msg = self.bc.add_block(block)
                    if ok:
                        if self.on_new_block:
                            self.on_new_block(block)
                        self._adopt_orphans(block)          # v10.10
                    elif isinstance(msg, str) and msg.startswith("Orphan block"):
                        self._stash_orphan(peer, block, blk_hash)   # v10.10
                    # else: invalid block — ignore (peer may be banned externally)
            except Exception as e:
                logging.warning(f"Block deserialization error from {peer.info.addr}: {e}")

    # ── v10.10: orphan handling (consensus untouched: every orphan is fully validated by
    #    bc.add_block() when it is finally connected; the pool only remembers it until then) ──
    def _stash_orphan(self, peer, block, blk_hash: str):
        """Remember a block whose parent is unknown and ask the sender for the missing history."""
        try:
            h = block.header
            tgt = bits_to_target(h.bits)
            # cheap anti-spam: only blocks with real proof-of-work at a legal difficulty are kept
            if tgt <= 0 or tgt > MAX_TARGET or not h.meets_target():
                return
            if not self.orphan_pool.add(block):
                return
            # the hash must be re-processable once its parent is connected
            self._known_invs.discard(blk_hash)
            addr = getattr(getattr(peer, "info", None), "addr", "?")
            now = time.time()
            if now - self._orphan_sync_t.get(addr, 0.0) >= 5.0:
                self._orphan_sync_t[addr] = now
                if len(self._orphan_sync_t) > 1000:
                    self._orphan_sync_t.clear()
                self._request_sync(peer)
        except Exception as e:
            logging.warning(f"orphan stash failed: {e}")

    def _adopt_orphans(self, parent):
        """After `parent` was connected, connect every stored orphan that builds on it (iteratively,
        bounded by the pool size, so a crafted chain of orphans cannot recurse or loop)."""
        try:
            if self.orphan_pool.size() == 0:
                return
            queue = [parent.hash]
            budget = OrphanPool.MAX_ORPHANS + 1
            while queue and budget > 0:
                ph = queue.pop(0)
                for child in self.orphan_pool.get_children(ph):
                    budget -= 1
                    self.orphan_pool.remove(child.hash)
                    ok, msg = self.bc.add_block(child)
                    if ok:
                        if self.on_new_block:
                            self.on_new_block(child)
                        queue.append(child.hash)
        except Exception as e:
            logging.warning(f"orphan adopt failed: {e}")

    def _deserialize_block(self, blk_dict: dict) -> Optional[Block]:
        """Reconstruct a Block object from a dict received over the network"""
        try:
            hdr_dict = blk_dict.get("header", {})
            header = BlockHeader(
                version     = hdr_dict.get("version", 1),
                prev_hash   = hdr_dict.get("prev_hash", "0"*64),
                merkle_root = hdr_dict.get("merkle_root", "0"*64),
                timestamp   = hdr_dict.get("timestamp", 0),
                bits        = int(hdr_dict.get("bits", "0x1d00ffff"), 16)
                              if isinstance(hdr_dict.get("bits"), str)
                              else hdr_dict.get("bits", 0x1d00ffff),
                nonce       = hdr_dict.get("nonce", 0),
                height      = hdr_dict.get("height", 0),
            )
            txs = []
            for tx_dict in blk_dict.get("transactions", []):
                inputs = []
                for vin in tx_dict.get("vin", []):
                    outpoint = OutPoint(
                        txid  = vin.get("txid", "0"*64),
                        index = vin.get("vout", 0xFFFFFFFF),
                    )
                    inputs.append(TxInput(
                        outpoint   = outpoint,
                        script_sig = bytes.fromhex(vin.get("script_sig_hex", "")),
                        sequence   = vin.get("sequence", 0xFFFFFFFF),
                    ))
                outputs = []
                for vout in tx_dict.get("vout", []):
                    outputs.append(TxOutput(
                        value         = vout.get("value_neb", 0),
                        script_pubkey = bytes.fromhex(vout.get("script_pubkey_hex", "")),
                    ))
                tx = Transaction(
                    version  = tx_dict.get("version", 1),
                    inputs   = inputs,
                    outputs  = outputs,
                    locktime = tx_dict.get("locktime", 0),
                )
                txs.append(tx)
            if not txs:
                return None
            return Block(header, txs)
        except Exception as e:
            logging.warning(f"_deserialize_block error: {e}")
            return None

    def _deserialize_tx(self, tx_dict: dict) -> Optional[Transaction]:
        """FIX v10.3: rebuild a Transaction from a network dict (None if malformed)."""
        try:
            inputs = [TxInput(
                        outpoint   = OutPoint(txid=vin.get("txid", "0"*64),
                                              index=vin.get("vout", 0xFFFFFFFF)),
                        script_sig = bytes.fromhex(vin.get("script_sig_hex", "")),
                        sequence   = vin.get("sequence", 0xFFFFFFFF),
                      ) for vin in tx_dict.get("vin", [])]
            outputs = [TxOutput(
                        value         = int(vout.get("value_neb", 0)),
                        script_pubkey = bytes.fromhex(vout.get("script_pubkey_hex", "")),
                       ) for vout in tx_dict.get("vout", [])]
            return Transaction(version=tx_dict.get("version", 1), inputs=inputs,
                               outputs=outputs, locktime=tx_dict.get("locktime", 0))
        except Exception as e:
            logging.warning(f"_deserialize_tx error: {e}")
            return None

    def _handle_tx(self, peer: PeerConnection, p: dict):
        tx_dict = p.get("tx")
        if isinstance(tx_dict, dict):   # FIX v10.3: full tx received after GETDATA
            tx = self._deserialize_tx(tx_dict)
            if tx is not None and tx.txid not in self._known_invs:
                self._known_invs.add(tx.txid)
                ok, _msg = self.bc.mempool.submit(tx)   # full validation inside
                if ok:
                    if self.on_new_tx:
                        self.on_new_tx(tx)
                    self.broadcast_tx(tx)               # relay to other peers
            return
        txid = p.get("txid", "")
        if txid and txid not in self._known_invs:
            self._known_invs.add(txid)
            # Limit memory growth
            if len(self._known_invs) > 50_000:
                items = list(self._known_invs)
                self._known_invs = set(items[len(items)//2:])

    def _request_sync(self, peer: PeerConnection):
        locator = self.bc.get_locator()
        peer.send(Message(MsgType.GETBLOCKS, {"locator": locator}))
        peer.info.state = PeerState.SYNCING

    def _on_peer_disconnect(self, peer: PeerConnection):
        with self._lock:
            self._peers.pop(peer.info.addr, None)

    def peer_count(self) -> int:
        return sum(1 for p in self._peers.values()
                   if p.info.state == PeerState.CONNECTED)

    def all_peers(self) -> List[dict]:
        with self._lock:
            return [{
                "addr":       p.info.addr,
                "state":      p.info.state.value,
                "height":     p.info.height,
                "latency_ms": f"{p.info.latency_ms:.1f}",
                "inbound":    p.inbound,
                "agent":      p.info.user_agent,
            } for p in self._peers.values()]

    def network_info(self) -> dict:
        return {
            "listening":    f"{self.host}:{self.port}",
            "peers_total":  len(self._peers),
            "peers_connected": self.peer_count(),
            "chain_height": self.bc.height,
            "banned":       len(self._banned),
            "addr_book":    self.addr_book.stats(),     # v10.11
        }


