# ================================================================
#  BLOCK EXPLORER (in-memory)
# ================================================================

class BlockExplorer:
    """Simple block explorer — search blocks, txs, addresses"""

    def __init__(self, bc: NEBULABlockchain):
        self.bc = bc

    def block_info(self, height_or_hash: str) -> Optional[dict]:
        try:
            height = int(height_or_hash)
            blk = self.bc.get_block(height)
        except ValueError:
            blk = self.bc.get_block_by_hash(height_or_hash)
        return blk.to_dict() if blk else None

    def tx_info(self, txid: str) -> Optional[dict]:
        for blk in reversed(self.bc._chain[-100:]):
            for tx in blk.transactions:
                if tx.txid == txid:
                    d = tx.to_dict()
                    d["block_hash"]   = blk.hash
                    d["block_height"] = blk.height
                    d["confirmations"] = self.bc.height - blk.height + 1
                    return d
        # v10.10: older than 100 blocks -> ask the chain's transaction index
        idx = getattr(self.bc, "_tx_index", None)
        if idx is not None:
            try:
                loc = idx.locate(txid)
                if loc:
                    blk = self.bc.get_block(loc[0])
                    if blk and loc[1] < len(blk.transactions) and blk.transactions[loc[1]].txid == txid:
                        d = blk.transactions[loc[1]].to_dict()
                        d["block_hash"]    = blk.hash
                        d["block_height"]  = blk.height
                        d["confirmations"] = self.bc.height - blk.height + 1
                        return d
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in BlockExplorer.tx_info", exc_info=True)
        return None

    def address_info(self, address: str) -> dict:
        balance = self.bc.utxo.balance(address)
        utxos   = self.bc.utxo.get_by_address(address)
        return {
            "address":     address,
            "balance_nbl": f"{balance/10**DECIMALS:.{DECIMALS}f}",
            "balance_neb": balance,
            "utxo_count":  len(utxos),
            "utxos": [{
                "txid":   u.txid,
                "index":  u.index,
                "value_nbl": f"{u.value/10**DECIMALS:.{DECIMALS}f}",
                "height": u.height,
            } for u in utxos],
        }

    def recent_blocks(self, count: int = 10) -> List[dict]:
        start = max(0, self.bc.height - count + 1)
        result = []
        for h in range(self.bc.height, start - 1, -1):
            blk = self.bc.get_block(h)
            if blk:
                result.append({
                    "height":    blk.height,
                    "hash":      blk.hash[:16] + "...",
                    "txs":       blk.tx_count,
                    "size":      blk.byte_size(),
                    "timestamp": blk.header.timestamp,
                    "miner":     blk.transactions[0].outputs[0].address if blk.transactions else "?",
                })
        return result

    def supply_info(self) -> dict:
        issued = self.bc.utxo.total_supply()
        era    = halving_era(self.bc.height)
        return {
            "max_supply":      f"{MAX_SUPPLY/10**DECIMALS:,.0f} NBL",
            "issued":          f"{issued/10**DECIMALS:.{DECIMALS}f} NBL",
            "percentage":      f"{issued/MAX_SUPPLY*100:.4f}%",
            "current_reward":  era["reward_nbl"] + " NBL",
            "era":             era["era_name"],
            "next_halving":    era["next_halving_at"],
            "blocks_remaining":era["blocks_remaining"],
        }

    def print_dashboard(self):
        info  = self.bc.chain_info()
        sup   = self.supply_info()
        recnt = self.recent_blocks(5)

        print("\n" + "═"*60)
        print(f"  NEBULA Blockchain Dashboard")
        print("═"*60)
        print(f"  Height        : {info['height']:,}")
        print(f"  Best Block    : {info['best_hash'][:32]}...")
        print(f"  Difficulty    : {info['bits']}")
        print(f"  Block Reward  : {info['reward_nbl']} NBL")
        print(f"  Era           : {info['era']}")
        print(f"  Next Halving  : block #{info['next_halving']:,}")
        print(f"  Supply Issued : {sup['issued']}")
        print(f"  Max Supply    : {sup['max_supply']}")
        print(f"  UTXO Set      : {info['utxo_set_size']:,} entries")
        print(f"  Mempool       : {info['mempool_txs']} txs")
        print("\n  Recent Blocks:")
        for b in recnt:
            print(f"    #{b['height']:>6} | {b['hash']} | {b['txs']} txs | {b['size']} bytes")
        print("═"*60)

# ================================================================
#  NEBULA FULL NODE
# ================================================================

class NEBULAFullNode:
    """
    Complete NEBULA full node.
    Runs blockchain + P2P + optional miner + wallet.
    """

    def __init__(self,
                 data_dir:      str  = "./nebula_data",
                 port:          int  = DEFAULT_PORT,
                 mine:          bool = False,
                 miner_address: str  = None,
                 threads:       int  = None,
                 rpc_port:      int  = None):        # v10.17: opt-in JSON-RPC (loopback + cookie auth)

        self.data_dir = Path(data_dir)
        self.data_dir.mkdir(exist_ok=True)

        print(BANNER)

        # Core blockchain — try to resume from saved state first
        loaded = NEBULABlockchain.load(str(self.data_dir))
        if loaded is not None:
            self.bc = loaded
            print(f"▶️  Resumed from saved chain (height {self.bc.height})")
        else:
            self.bc = NEBULABlockchain()
            print("🌌 Starting fresh NEBULA chain")
        self.explorer = BlockExplorer(self.bc)
        # v10.9: consensus-connected state layer (tokens/NFT/DEX/governance/staking)
        self.state = NEBULAStateLayer(self.bc).attach()
        # v10.10: txid/address index (reorg-safe) -> API /api/tx, BlockExplorer, address tx_count
        self.tx_index = TxIndexLayer.for_chain(self.bc)
        # v10.11: real fee statistics from confirmed blocks -> /api/fees, mempool.fee_estimates()
        self.fee_layer = FeeLayer.for_chain(self.bc)
        # v10.17: groups 1-4 on the live chain (spam/double-spend/checkpoints/finality, mempool policy/RBF/bans,
        # block store + chain state, compact blocks / headers / bloom / RPC). Never blocks consensus.
        self.groups = NodeGroupsLayer(
            self.bc, str(self.data_dir), snapshot_dir=str(self.data_dir / "groups" / "snapshots"),
            rpc=(dict(host="127.0.0.1", port=int(rpc_port), cookie_path=str(self.data_dir / ".rpc_cookie"))
                 if rpc_port else None)).attach()

        # P2P network
        self.p2p = P2PNode(self.bc, port=port, data_dir=str(self.data_dir))   # v10.11: peers.json
        self.p2p.on_new_block = self._on_new_block
        self.p2p.on_new_tx    = self._on_new_tx
        self.groups.attach_p2p(self.p2p)               # v10.17: g2 bans/eviction, g1 feefilter, g4 messages
        # v10.18: group 5 on the live chain/P2P/REST (merkle tries, wallet history, peer sync/discovery, time oracle,
        # staking/price/coin-control/mempool helpers, accumulator + key-value store). Observation only: it never
        # rejects a block or a message; weight limit = the host consensus value (block bytes <= MAX_BLOCK_SIZE_BYTES).
        self.group5_error = None
        try:
            attach_group5(self, str(self.data_dir), max_block_weight=4 * MAX_BLOCK_SIZE_BYTES)
        except Exception as e:                           # group 5 must never stop a node from starting
            self.group5_error = repr(e)
            log.exception("group 5 attach failed")

        # Miner
        self.miner = None
        if mine:
            addr = miner_address or self._load_or_create_miner_address()
            self.miner = NEBULAMiner(self.bc, addr, num_workers=threads,
                                     on_block=lambda blk, _st: self.p2p.broadcast_block(blk))   # FIX v10.2

        # Wallet
        self.wallet = None

        self._running = False

    def _load_or_create_miner_address(self) -> str:
        wallet_file = self.data_dir / "miner_wallet.json"
        if wallet_file.exists():
            data = json.loads(wallet_file.read_text())
            # Support both encrypted (new) and legacy (plain) format
            if "ct" in data:
                # Encrypted wallet
                try:
                    pw = getpass.getpass("  Enter wallet password (to unlock miner wallet): ")
                    mnemonic = _decrypt_mnemonic(data, pw)
                    w = NEBULAWallet.from_mnemonic(mnemonic)
                    return w.first_address
                except ValueError:
                    print("❌ Wrong password! Cannot unlock miner wallet.")
                    sys.exit(1)
            else:
                return data["address"]
        # Create new wallet with password encryption
        w  = NEBULAWallet.create_new()
        pw = getpass.getpass("  Set a password to encrypt your miner wallet: ")
        pw2 = getpass.getpass("  Confirm password: ")
        if pw != pw2:
            print("❌ Passwords do not match!")
            sys.exit(1)
        enc = _encrypt_mnemonic(w.mnemonic, pw)
        enc["address"] = w.first_address  # store address in plaintext for quick load
        wallet_file.write_text(json.dumps(enc, indent=2))
        os.chmod(str(wallet_file), 0o600)   # owner read/write only
        print(f"✅  Miner wallet saved (encrypted) → {wallet_file}")
        print(f"    Address  : {w.first_address}")
        print(f"    BACK UP YOUR MNEMONIC (shown only once):")
        print(f"    {w.mnemonic}")
        return w.first_address

    def start(self):
        """Start all node services"""
        self._running = True
        self.p2p.start()
        if self.groups.g4 is not None and self.groups.g4.rpc is not None:      # v10.17: only when rpc_port was given
            try:
                print(f"   RPC      : 127.0.0.1:{self.groups.start_rpc()} (cookie: {self.data_dir / '.rpc_cookie'})")
            except Exception as e:
                print(f"   RPC failed to start: {e}")

        if self.miner:
            self.miner.start()

        # Status thread
        threading.Thread(target=self._status_loop, daemon=True, name="Status").start()

        # Save chain periodically
        threading.Thread(target=self._save_loop, daemon=True, name="SaveChain").start()

        self.explorer.print_dashboard()
        print(f"\n✅ NEBULA Full Node running")
        print(f"   Data dir : {self.data_dir}")
        print(f"   Port     : {self.p2p.port}")
        print(f"   Mining   : {'yes' if self.miner else 'no'}")
        print(f"\n   Press Ctrl+C to stop\n")

    def stop(self):
        self._running = False
        if self.miner:
            self.miner.stop()
        self.p2p.stop()
        self.save_chain()
        try:
            detach_group5(self)                          # v10.18: undo group-5 wraps first (reverse of attach order)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULAFullNode.stop", exc_info=True)
        try:
            self.groups.close()                          # v10.17: stop RPC, undo wraps, close block store
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULAFullNode.stop", exc_info=True)
        print("\n🛑 NEBULA node stopped. Chain saved.")

    def _on_new_block(self, block):
        print(f"📦 New block #{block.height}: {block.hash[:16]}...")
        self.p2p.broadcast_block(block)   # FIX v10.2: relay accepted blocks

    def _on_new_tx(self, tx):
        print(f"📨 New tx: {tx.txid[:16]}...")

    def _status_loop(self):
        while self._running:
            time.sleep(60)
            self.explorer.print_dashboard()
            if self.miner:
                s = self.miner.get_stats()
                print(f"  ⛏️  Mining: {s['hash_rate_khs']:.1f} KH/s | {s['blocks_found']} found")   # PATCH: key was 'hash_rate' (KeyError killed the status thread)

    def _save_loop(self):
        while self._running:
            time.sleep(300)   # every 5 min
            self.save_chain()

    def save_chain(self):
        """Save full chain state so node can resume after restart."""
        self.bc.save(str(self.data_dir))
        self.bc.export(str(self.data_dir / "nebula_export.json"))  # human-readable backup

    def interactive_wallet(self):
        """Simple CLI wallet interface"""
        print("\n" + "─"*50)
        print("  NEBULA Wallet")
        print("─"*50)
        print("  1. Create new wallet")
        print("  2. Restore from mnemonic")
        print("  3. Check balance")
        print("  4. Send NBL")
        print("  5. Show address")
        print("─"*50)

        choice = input("  Choice: ").strip()

        if choice == "1":
            self.wallet = NEBULAWallet.create_new(self.bc.utxo)
            print(f"\n  ✅ Wallet created!")
            print(f"  Address : {self.wallet.first_address}")
            print(f"\n  ⚠️  WRITE DOWN YOUR 12-WORD MNEMONIC (shown only once — never stored in logs):")
            # Mnemonic shown only in interactive CLI — user explicitly requested wallet creation
            print(f"  {self.wallet.mnemonic}")
            print(f"\n  WIF Key : {self.wallet.master.derive_path(NBL_BIP44_PATH + '/0/0').wif}")
            print(f"  ─────────────────────────────────────────────")
            print(f"  Write these down and store in a SAFE place!")

        elif choice == "2":
            mnemonic = input("  Enter 12-word mnemonic: ").strip()
            self.wallet = NEBULAWallet.from_mnemonic(mnemonic, utxo_set=self.bc.utxo)
            print(f"  Restored: {self.wallet.first_address}")

        elif choice == "3":
            if not self.wallet:
                addr = input("  Enter address: ").strip()
                info = self.explorer.address_info(addr)
            else:
                info = self.explorer.address_info(self.wallet.first_address)
            print(f"\n  Balance: {info['balance_nbl']}")
            print(f"  UTXOs  : {info['utxo_count']}")

        elif choice == "4":
            if not self.wallet:
                print("  ❌ No wallet loaded")
                return
            to_addr  = input("  To address: ").strip()
            amount   = float(input("  Amount (NBL): ").strip())
            tx = self.wallet.build_transaction(to_addr, amount)
            if tx:
                ok, msg = self.bc.mempool.submit(tx)
                print(f"  {'✅' if ok else '❌'} {msg}: {tx.txid[:20]}...")
                if ok and getattr(self, "p2p", None):
                    self.p2p.broadcast_tx(tx)   # FIX v10.3

        elif choice == "5":
            if self.wallet:
                print(f"  Address: {self.wallet.first_address}")
            else:
                print("  No wallet loaded")

    def run_interactive(self):
        """Interactive CLI"""
        self.start()
        try:
            while True:
                try:
                    cmd = input("\nNBL> ").strip().lower()
                except EOFError:   # PATCH: no stdin (service/daemon): keep running until Ctrl+C
                    while True:
                        time.sleep(3600)
                if cmd in ("exit", "quit", "q"):
                    break
                elif cmd == "info":
                    self.explorer.print_dashboard()
                elif cmd == "wallet":
                    self.interactive_wallet()
                elif cmd.startswith("block "):
                    h = cmd[6:].strip()
                    info = self.explorer.block_info(h)
                    print(json.dumps(info, indent=2) if info else "Not found")
                elif cmd.startswith("tx "):
                    txid = cmd[3:].strip()
                    info = self.explorer.tx_info(txid)
                    print(json.dumps(info, indent=2) if info else "Not found")
                elif cmd.startswith("addr "):
                    addr = cmd[5:].strip()
                    info = self.explorer.address_info(addr)
                    print(json.dumps(info, indent=2))
                elif cmd == "peers":
                    peers = self.p2p.all_peers()
                    print(json.dumps(peers, indent=2))
                elif cmd.startswith("connect "):
                    for _h, _p in parse_peer_list(cmd[8:]):
                        _ok = self.p2p.connect_peer(_h, _p)
                        print(f"  {'connected to' if _ok else 'could not connect to'} {_h}:{_p}")
                elif cmd == "supply":
                    print(json.dumps(self.explorer.supply_info(), indent=2))
                elif cmd == "miner":
                    if self.miner:
                        print(json.dumps(self.miner.get_stats(), indent=2))
                    else:
                        print("Mining not enabled. Restart with --mine")
                elif cmd == "help":
                    print("  Commands: info, wallet, block <h|hash>, tx <txid>,")
                    print("            addr <address>, peers, connect <host:port>, supply, miner, help, quit")
                else:
                    print(f"  Unknown command: {cmd}. Type 'help'")
        except KeyboardInterrupt:
            pass
        finally:
            self.stop()


# ================================================================
