# ==============================================================================
# 1. DoubleSpendDetector
# ==============================================================================
class DoubleSpendDetector:
    """
    Tracks which mempool tx has reserved which outpoint.

    Improvements over the original:
      * reverse index txid -> keys, so release() is O(inputs) instead of O(mempool)
      * rejects a tx that spends the same outpoint twice (inflation-bug class)
      * replace()  : atomic replace-by-fee swap, only allowed to displace named txs
      * on_block() : a confirmed tx evicts every conflicting mempool tx and returns them
      * bounded forensic log of detected attempts
    """

    def __init__(self, history: int = 1000):
        self._spending: Dict[str, str] = {}
        self._by_tx: Dict[str, Set[str]] = {}
        self._lock = threading.RLock()
        self._attempts = collections.deque(maxlen=history)

    @staticmethod
    def _key(txid: str, index: int) -> str:
        return f"{txid}:{index}"

    def _keys_of(self, inputs: Iterable) -> List[str]:
        return [self._key(i.outpoint.txid, i.outpoint.index) for i in inputs]

    def check(self, inputs: Iterable, own_txid: Optional[str] = None) -> Set[str]:
        """Read-only: txids currently holding any of these outpoints."""
        with self._lock:
            out = set()
            for k in self._keys_of(inputs):
                owner = self._spending.get(k)
                if owner is not None and owner != own_txid:
                    out.add(owner)
            return out

    def register(self, txid: str, inputs: List) -> Tuple[bool, Optional[str]]:
        """Atomic reserve. Returns (ok, conflicting_txid | 'duplicate-input')."""
        with self._lock:
            keys = self._keys_of(inputs)
            if len(set(keys)) != len(keys):
                self._attempts.append((time.time(), txid, "duplicate-input"))
                return False, "duplicate-input"
            for k in keys:
                owner = self._spending.get(k)
                if owner is not None and owner != txid:
                    self._attempts.append((time.time(), txid, owner))
                    return False, owner
            for k in keys:
                self._spending[k] = txid
            self._by_tx.setdefault(txid, set()).update(keys)
            return True, None

    def replace(self, new_txid: str, inputs: List,
                replaced: Iterable[str]) -> Tuple[bool, Optional[str]]:
        """RBF swap. Fails if the new tx conflicts with anything NOT in `replaced`."""
        replaced = set(replaced)
        with self._lock:
            conflicts = self.check(inputs, own_txid=new_txid)
            stray = conflicts - replaced
            if stray:
                return False, sorted(stray)[0]
            keys = self._keys_of(inputs)
            if len(set(keys)) != len(keys):
                return False, "duplicate-input"
            for t in replaced:
                self._release_locked(t)
            for k in keys:
                self._spending[k] = new_txid
            self._by_tx.setdefault(new_txid, set()).update(keys)
            return True, None

    def _release_locked(self, txid: str):
        for k in self._by_tx.pop(txid, ()):
            if self._spending.get(k) == txid:
                del self._spending[k]

    def release(self, txid: str):
        with self._lock:
            self._release_locked(txid)

    def clear_block(self, inputs: List):
        """Back-compat with the original API."""
        with self._lock:
            for k in self._keys_of(inputs):
                owner = self._spending.pop(k, None)
                if owner is not None and owner in self._by_tx:
                    self._by_tx[owner].discard(k)

    def on_block(self, txs: Iterable[Tuple[str, List]]) -> List[str]:
        """
        txs = [(txid, inputs), ...] of a newly connected block.
        Returns mempool txids that are now invalid (they double-spend the block).
        """
        evicted: List[str] = []
        with self._lock:
            txs = list(txs)
            for txid, inputs in txs:
                for k in self._keys_of(inputs):
                    owner = self._spending.get(k)
                    if owner is not None and owner != txid:
                        evicted.append(owner)
            for txid, _ in txs:
                self._release_locked(txid)
            seen = []
            for e in evicted:
                if e not in seen:
                    seen.append(e)
                    self._release_locked(e)
            return seen

    def conflict_count(self) -> int:
        with self._lock:
            return len(self._spending)

    def recent_attempts(self, n: int = 20) -> List[dict]:
        with self._lock:
            return [{"time": t, "txid": a, "conflict": b}
                    for t, a, b in list(self._attempts)[-n:]]


# ==============================================================================
# 2. TransactionSpamFilter
# ==============================================================================
class TransactionSpamFilter:
    """
    Structural checks + per-sender token bucket.

    Improvements: token bucket (smooth, no list scans), LRU-bounded tracking so an
    attacker cannot grow memory with fresh addresses, bans EXPIRE (a permanent ban on a
    cheap identity is useless and punishes victims of address reuse), coinbase never
    enters the mempool, one OP_RETURN per tx, size and value sanity checks.
    """

    RATE_LIMIT_PER_MIN = 100
    MAX_OUTPUT_COUNT = 50
    MAX_OP_RETURN_SIZE = 80
    MAX_TX_BYTES = 100_000
    STRIKES_TO_BAN = 5
    BAN_SECONDS = 3600
    MAX_TRACKED = 100_000

    def __init__(self, op_return: int = OP_RETURN_DEFAULT,
                 dust_threshold: int = DUST_THRESHOLD_DEFAULT,
                 max_money: Optional[int] = None,
                 key_fn: Optional[Callable[[Any], str]] = None,
                 clock: Callable[[], float] = time.monotonic):
        self.op_return = op_return
        self.dust = dust_threshold
        self.max_money = max_money
        self.key_fn = key_fn or self.default_sender_key
        self._clock = clock
        self._buckets: "collections.OrderedDict[str, List[float]]" = collections.OrderedDict()
        self._strikes: Dict[str, int] = {}
        self._banned: Dict[str, float] = {}
        self._lock = threading.RLock()

    @staticmethod
    def default_sender_key(tx) -> str:
        for attr in ("sender", "from_addr", "from_address"):
            v = getattr(tx, attr, None)
            if v:
                return str(v)
        try:
            i0 = tx.inputs[0]
            a = getattr(i0, "address", None)
            return str(a) if a else str(i0.outpoint.txid)
        except Exception:
            return "unknown"

    # -- structure ---------------------------------------------------------
    def check_tx(self, tx) -> Tuple[bool, str]:
        if not tx.inputs or not tx.outputs:
            return False, "Empty inputs or outputs"
        if getattr(tx, "is_coinbase", False):
            return False, "Coinbase not allowed in mempool"
        if len(tx.outputs) > self.MAX_OUTPUT_COUNT:
            return False, f"Too many outputs: {len(tx.outputs)}"
        size = tx.byte_size() if hasattr(tx, "byte_size") else 0
        if size > self.MAX_TX_BYTES:
            return False, f"Transaction too large: {size}"
        op_returns, total = 0, 0
        for out in tx.outputs:
            if out.value < 0:
                return False, "Negative output value"
            total += out.value
            if self.max_money is not None and (out.value > self.max_money or total > self.max_money):
                return False, "Output value exceeds money supply"
            spk = out.script_pubkey
            if len(spk) > 0 and spk[0] == self.op_return:
                op_returns += 1
                if op_returns > 1:
                    return False, "More than one OP_RETURN"
                if len(spk) - 2 > self.MAX_OP_RETURN_SIZE:
                    return False, f"OP_RETURN too large: {len(spk) - 2}"
            elif len(spk) > 0 and out.value < self.dust:
                return False, f"Dust output: {out.value}"
        return True, "OK"

    # -- rate --------------------------------------------------------------
    def check_rate_limit(self, key: str) -> Tuple[bool, str]:
        with self._lock:
            now = self._clock()
            until = self._banned.get(key)
            if until is not None:
                if now < until:
                    return False, "Sender is banned"
                del self._banned[key]
                self._strikes.pop(key, None)
            cap = float(self.RATE_LIMIT_PER_MIN)
            b = self._buckets.pop(key, None)
            tokens, last = (cap, now) if b is None else b
            tokens = min(cap, tokens + (now - last) * cap / 60.0)
            if tokens < 1.0:
                self._buckets[key] = [tokens, now]
                n = self._strikes.get(key, 0) + 1
                self._strikes[key] = n
                if n >= self.STRIKES_TO_BAN:
                    self._banned[key] = now + self.BAN_SECONDS
                    return False, "Sender banned for repeated rate-limit violations"
                return False, "Rate limit exceeded"
            self._buckets[key] = [tokens - 1.0, now]
            while len(self._buckets) > self.MAX_TRACKED:
                old, _ = self._buckets.popitem(last=False)
                self._strikes.pop(old, None)
            return True, "OK"

    def check(self, tx) -> Tuple[bool, str]:
        ok, why = self.check_tx(tx)
        if not ok:
            return ok, why
        return self.check_rate_limit(self.key_fn(tx))

    def unban(self, key: str):
        with self._lock:
            self._banned.pop(key, None)
            self._strikes.pop(key, None)

    def filter_stats(self) -> dict:
        with self._lock:
            return {"banned": len(self._banned), "tracked": len(self._buckets),
                    "rate_limit": f"{self.RATE_LIMIT_PER_MIN}/min",
                    "max_outputs": self.MAX_OUTPUT_COUNT}


# ==============================================================================
# 3. CheckpointVerifier
# ==============================================================================
class CheckpointVerifier:
    """
    Hard-coded checkpoints. EMPTY list = no rule change at all.
    Adds allow_reorg(): a fork that would remove an already-passed checkpoint is refused.
    """

    def __init__(self, checkpoints: Optional[Dict[int, str]] = None):
        self._cp: Dict[int, str] = {}
        for h, bh in (checkpoints or {}).items():
            self._validate(h, bh)
            self._cp[int(h)] = bh.lower()
        self._lock = threading.RLock()

    @staticmethod
    def _validate(h, bh):
        if not isinstance(h, int) or h < 0:
            raise ValueError("checkpoint height must be a non-negative int")
        if not (isinstance(bh, str) and len(bh) == 64 and
                all(c in "0123456789abcdefABCDEF" for c in bh)):
            raise ValueError("checkpoint hash must be 64 hex chars")

    def verify_block(self, block) -> Tuple[bool, str]:
        exp = self._cp.get(block.height)
        if exp is not None and block.hash.lower() != exp:
            return False, (f"Checkpoint mismatch at height {block.height}: "
                           f"{block.hash[:16]} != {exp[:16]}")
        return True, "OK"

    def verify_header(self, header, height: Optional[int] = None) -> Tuple[bool, str]:
        h = height if height is not None else getattr(header, "height", None)
        exp = self._cp.get(h) if h is not None else None
        if exp is None:
            return True, "OK"
        got = header.hash() if callable(getattr(header, "hash", None)) else getattr(header, "hash", "")
        if got.lower() != exp:
            return False, f"Header checkpoint mismatch at {h}"
        return True, "OK"

    def allow_reorg(self, fork_height: int, tip_height: int) -> Tuple[bool, str]:
        """fork_height = height of the common ancestor. Refuse if a passed checkpoint would be undone."""
        for h in self._cp:
            if fork_height < h <= tip_height:
                return False, f"Reorg would undo checkpoint at height {h}"
        return True, "OK"

    def next_checkpoint(self, current_height: int) -> Optional[Tuple[int, str]]:
        for h in sorted(self._cp):
            if h > current_height:
                return h, self._cp[h]
        return None

    def is_safe_height(self, height: int) -> bool:
        return bool(self._cp) and height <= max(self._cp)

    def add_checkpoint(self, height: int, block_hash: str, force: bool = False):
        """Existing checkpoints are immutable unless force=True."""
        self._validate(height, block_hash)
        with self._lock:
            cur = self._cp.get(height)
            if cur is not None and cur != block_hash.lower() and not force:
                raise ValueError(f"checkpoint {height} already set to a different hash")
            self._cp[height] = block_hash.lower()

    def list_checkpoints(self) -> List[dict]:
        return [{"height": h, "hash": self._cp[h]} for h in sorted(self._cp)]


# ==============================================================================
# 4. FinalityEngine
# ==============================================================================
def double_spend_probability(z: int, q: float) -> float:
    """
    Nakamoto/Rosenfeld probability that an attacker with hash share q ever overtakes the
    honest chain from z confirmations behind.
    """
    if not 0 <= q < 1:
        raise ValueError("q must be in [0,1)")
    p = 1.0 - q
    if q >= p:
        return 1.0
    if z <= 0:
        return 1.0
    lam = z * q / p
    s = 1.0
    poisson = math.exp(-lam)
    for k in range(z + 1):
        if k > 0:
            poisson *= lam / k
        s -= poisson * (1.0 - (q / p) ** (z - k))
    return max(0.0, min(1.0, s))


class FinalityEngine:
    FINALITY_LEVELS = {"low": 1, "medium": 6, "high": 12, "full": 100}

    def __init__(self, blockchain,
                 target_block_time: int = TARGET_BLOCK_TIME_DEFAULT,
                 tx_locator: Optional[Callable[[str], Optional[int]]] = None,
                 mempool_has: Optional[Callable[[str], bool]] = None,
                 checkpoints: Optional[CheckpointVerifier] = None):
        self._bc = blockchain
        self._tbt = target_block_time
        self._locate = tx_locator
        self._in_pool = mempool_has
        self._cp = checkpoints

    def confirmations(self, tx_block: Optional[int]) -> int:
        if tx_block is None or tx_block < 0:
            return 0
        return max(0, self._bc.height - tx_block + 1)

    def finality_level(self, tx_block: Optional[int]) -> str:
        if self._cp is not None and tx_block is not None and self._cp.is_safe_height(tx_block):
            return "checkpointed"
        conf = self.confirmations(tx_block)
        for level, th in sorted(self.FINALITY_LEVELS.items(), key=lambda x: -x[1]):
            if conf >= th:
                return level
        return "unconfirmed"

    def is_final(self, tx_block: Optional[int], level: str = "medium") -> bool:
        if self._cp is not None and tx_block is not None and self._cp.is_safe_height(tx_block):
            return True
        return self.confirmations(tx_block) >= self.FINALITY_LEVELS.get(level, 6)

    def time_to_finality(self, level: str = "high") -> float:
        return self.FINALITY_LEVELS.get(level, 12) * self._tbt

    def reorg_risk(self, tx_block: Optional[int], attacker_share: float = 0.10) -> float:
        return double_spend_probability(self.confirmations(tx_block), attacker_share)

    def required_confirmations(self, risk: float = 0.001, attacker_share: float = 0.10,
                               max_z: int = 1000) -> int:
        for z in range(1, max_z + 1):
            if double_spend_probability(z, attacker_share) < risk:
                return z
        return max_z

    def tx_status(self, txid: str, attacker_share: float = 0.10) -> dict:
        """Ready for REST /api/tx. Needs tx_locator (txid -> block height or None)."""
        height = self._locate(txid) if self._locate else None
        if height is None:
            pending = bool(self._in_pool(txid)) if self._in_pool else False
            return {"txid": txid, "confirmations": 0, "finality": "unconfirmed",
                    "is_final": False, "in_mempool": pending, "reorg_risk": 1.0}
        return {"txid": txid, "block_height": height,
                "confirmations": self.confirmations(height),
                "finality": self.finality_level(height),
                "is_final": self.is_final(height),
                "in_mempool": False,
                "reorg_risk": self.reorg_risk(height, attacker_share)}

    def finality_stats(self) -> dict:
        return {"current_height": self._bc.height, "levels": self.FINALITY_LEVELS,
                "time_to_medium": f"{self.time_to_finality('medium') / 60:.0f}m",
                "time_to_high": f"{self.time_to_finality('high') / 60:.0f}m"}


# ==============================================================================
# 5. FeeFilter (BIP 133)
# ==============================================================================
class FeeFilter:
    """
    Fee rates are integers in units per 1000 bytes, as in BIP 133.
    A tx whose fee is unknown is relayed (we cannot judge it); the mempool already
    enforced its own minimum before relay.
    """

    MAX_RATE = 21_000_000 * 10 ** 8     # sanity bound for incoming values

    def __init__(self, min_fee_rate: int = MIN_TX_FEE_DEFAULT, max_peers: int = 10_000):
        self.min_fee_rate = int(min_fee_rate)
        self._peer: "collections.OrderedDict[str, int]" = collections.OrderedDict()
        self._max_peers = max_peers
        self._whitelist: Set[str] = set()
        self._last_sent = int(min_fee_rate)
        self._lock = threading.RLock()

    @staticmethod
    def fee_rate(fee: int, size: int) -> int:
        return (int(fee) * 1000) // max(1, int(size))

    def set_peer_filter(self, peer: str, rate: int) -> bool:
        if not isinstance(rate, int) or rate < 0 or rate > self.MAX_RATE:
            return False                      # invalid feefilter: caller may add misbehaviour points
        with self._lock:
            self._peer.pop(peer, None)
            self._peer[peer] = rate
            while len(self._peer) > self._max_peers:
                self._peer.popitem(last=False)
        return True

    def remove_peer(self, peer: str):
        with self._lock:
            self._peer.pop(peer, None)

    def whitelist(self, peer: str):
        self._whitelist.add(peer)

    def should_relay_to(self, peer: str, tx=None, fee: Optional[int] = None,
                        size: Optional[int] = None) -> bool:
        if peer in self._whitelist:
            return True
        floor = self._peer.get(peer, 0)
        if floor == 0:
            return True
        if size is None and tx is not None and hasattr(tx, "byte_size"):
            size = tx.byte_size()
        if fee is None and tx is not None:
            f = getattr(tx, "fee", None)
            fee = f if isinstance(f, int) else None
        if fee is None or not size:
            return True
        return self.fee_rate(fee, size) >= floor

    def update_own(self, mempool_min_rate: int) -> bool:
        """Call when mempool floor changes; True if a new feefilter should be sent (>=10% change)."""
        self.min_fee_rate = max(int(mempool_min_rate), 0)
        base = max(self._last_sent, 1)
        if abs(self.min_fee_rate - self._last_sent) * 10 >= base:
            return True
        return False

    def to_message(self) -> dict:
        self._last_sent = self.min_fee_rate
        return {"method": "feefilter", "feerate": self.min_fee_rate}


# ==============================================================================
# Wiring layer
# ==============================================================================
class Group1Wiring:
    """
    One object that owns the five components and attaches them to the real node.

        g1 = Group1Wiring.from_host(globals(), blockchain=chain, checkpoints={})
        g1.attach_mempool(node.mempool)       # wraps Mempool.submit
        g1.attach_blockchain(chain)           # wraps NEBULABlockchain.add_block
        # REST /api/tx   : return g1.finality.tx_status(txid)
        # P2P feefilter  : g1.on_feefilter(peer, rate)   /   g1.may_relay(peer, tx, fee, size)
        # shutdown/undo  : g1.detach()
    """

    def __init__(self, blockchain=None, checkpoints: Optional[Dict[int, str]] = None,
                 op_return=OP_RETURN_DEFAULT, dust=DUST_THRESHOLD_DEFAULT,
                 min_fee=MIN_TX_FEE_DEFAULT, target_block_time=TARGET_BLOCK_TIME_DEFAULT,
                 max_money=None, tx_locator=None, mempool_has=None,
                 reject: Callable[[str], Any] = lambda reason: (False, reason),
                 evict_fn: Optional[Callable[[str], None]] = None):
        self.doublespend = DoubleSpendDetector()
        self.spam = TransactionSpamFilter(op_return, dust, max_money)
        self.checkpoints = CheckpointVerifier(checkpoints or {})
        self.finality = FinalityEngine(blockchain, target_block_time, tx_locator,
                                       mempool_has, self.checkpoints) if blockchain is not None else None
        self.feefilter = FeeFilter(min_fee)
        self._reject = reject
        self._evict = evict_fn
        self._undo: List[Callable[[], None]] = []

    @classmethod
    def from_host(cls, host_globals: dict, **kw):
        g = host_globals
        kw.setdefault("op_return", g.get("OP_RETURN", OP_RETURN_DEFAULT))
        kw.setdefault("dust", g.get("DUST_THRESHOLD", DUST_THRESHOLD_DEFAULT))
        kw.setdefault("min_fee", g.get("MIN_TX_FEE", MIN_TX_FEE_DEFAULT))
        kw.setdefault("target_block_time", g.get("TARGET_BLOCK_TIME", TARGET_BLOCK_TIME_DEFAULT))
        if "checkpoints" not in kw:
            kw["checkpoints"] = dict(g.get("CHECKPOINTS", {}) or {})
        return cls(**kw)

    @staticmethod
    def _accepted(result) -> bool:
        if isinstance(result, tuple) and result:
            return bool(result[0])
        if result is None:
            return True            # method signals failure by raising
        return bool(result)

    # -- mempool -------------------------------------------------------------
    def admit(self, tx) -> Tuple[bool, str]:
        """Pre-accept policy. On success the tx's outpoints are RESERVED; release on failure."""
        ok, why = self.spam.check(tx)
        if not ok:
            return False, why
        ok, conflict = self.doublespend.register(tx.txid, tx.inputs)
        if not ok:
            return False, f"Double-spend conflict with {conflict}"
        return True, "OK"

    def attach_mempool(self, mempool):
        orig = mempool.submit

        def submit(tx, *a, **kw):
            ok, why = self.admit(tx)
            if not ok:
                return self._reject(why)
            try:
                res = orig(tx, *a, **kw)
            except Exception:
                self.doublespend.release(tx.txid)
                raise
            if not self._accepted(res):
                self.doublespend.release(tx.txid)
            return res

        mempool.submit = submit
        self._undo.append(lambda m=mempool, o=orig: self._restore(m, "submit", o))

    # -- blockchain ----------------------------------------------------------
    def on_block_connected(self, block) -> List[str]:
        txs = [(t.txid, t.inputs) for t in block.transactions
               if not getattr(t, "is_coinbase", False)]
        evicted = self.doublespend.on_block(txs)
        if self._evict:
            for txid in evicted:
                self._evict(txid)
        return evicted

    def attach_blockchain(self, chain):
        orig = chain.add_block

        def add_block(block, *a, **kw):
            ok, why = self.checkpoints.verify_block(block)
            if not ok:
                return self._reject(why)
            res = orig(block, *a, **kw)
            if self._accepted(res):
                self.on_block_connected(block)
            return res

        chain.add_block = add_block
        self._undo.append(lambda c=chain, o=orig: self._restore(c, "add_block", o))

    # -- P2P / REST helpers (explicit calls, no guessing of P2P method names) ---
    def on_feefilter(self, peer: str, rate: int) -> bool:
        return self.feefilter.set_peer_filter(peer, rate)

    def may_relay(self, peer: str, tx, fee=None, size=None) -> bool:
        return self.feefilter.should_relay_to(peer, tx, fee, size)

    def on_peer_disconnect(self, peer: str):
        self.feefilter.remove_peer(peer)

    @staticmethod
    def _restore(obj, name, orig):
        # if the method was a plain bound method (not an instance attribute) drop our wrapper
        if getattr(type(obj), name, None) is not None and getattr(orig, "__self__", None) is obj:
            try:
                delattr(obj, name)
                return
            except AttributeError:
                _NB_SWALLOW_LOG.warning("swallowed AttributeError in Group1Wiring._restore", exc_info=True)
        setattr(obj, name, orig)

    def detach(self):
        while self._undo:
            self._undo.pop()()

    def stats(self) -> dict:
        return {"double_spend_tracked": self.doublespend.conflict_count(),
                "spam": self.spam.filter_stats(),
                "checkpoints": self.checkpoints.list_checkpoints(),
                "finality": self.finality.finality_stats() if self.finality else None}

