def set_language(lang: str):
    global LANG
    LANG = "en" if lang == "en" else "ps"


def msg(code: str, **kw) -> str:
    ps, en = _M[code]
    return (en if LANG == "en" else ps).format(**kw)


def _ceil_div(a: int, b: int) -> int:
    return -(-a // b)


def _size_of(obj) -> int:
    """د tx یا MempoolEntry اندازه (بایټ)."""
    s = getattr(obj, "size", None)
    if isinstance(s, int) and s > 0:
        return s
    tx = getattr(obj, "tx", obj)
    return max(1, tx.byte_size())


# ==============================================================================
# 1. MempoolPolicyEnforcer
# ==============================================================================
@dataclass
class MempoolPolicy_G2:
    max_tx_size: int = 100_000
    dust_threshold: int = 546
    permit_op_return: bool = True
    max_op_return_size: int = 80
    require_standard_scripts: bool = True
    min_relay_fee_sat_kb: int = MIN_RELAY_FEE_SAT_KB_G2
    max_ancestors: int = 25
    max_descendants: int = 25
    max_ancestor_bytes: int = 101_000

    def to_dict(self) -> dict:
        return dict(self.__dict__)


def default_classify(script: bytes) -> str:
    """
    د سکریپټ ډول (Bitcoin-بڼه). که NEBULA خپل Script.classify لري، د
    Group2Wiring.from_host له لارې هغه کارول کیږي.
    """
    n = len(script)
    if n == 0:
        return "unknown"
    if script[0] == 0x6A:
        return "nulldata"
    if n == 25 and script[:3] == b"\x76\xa9\x14" and script[23:] == b"\x88\xac":
        return "p2pkh"
    if n == 23 and script[:2] == b"\xa9\x14" and script[22] == 0x87:
        return "p2sh"
    if n == 22 and script[:2] == b"\x00\x14":
        return "p2wpkh"
    if n == 34 and script[:2] == b"\x00\x20":
        return "p2wsh"
    if n == 34 and script[:2] == b"\x51\x20":
        return "p2tr"
    if n in (35, 67) and script[0] in (33, 65) and script[-1] == 0xAC:
        return "p2pk"
    return "unknown"


def op_return_data_len(script: bytes) -> int:
    """د OP_RETURN رښتینی معلومات (د push هدر پرته)."""
    if len(script) < 2:
        return 0
    b = script[1]
    if b <= 0x4B:
        return len(script) - 2
    if b == 0x4C:
        return max(0, len(script) - 3)
    if b == 0x4D:
        return max(0, len(script) - 4)
    return len(script) - 1


class MempoolPolicyEnforcer:
    """
    د میمپول پالیسي: اندازه، dust، OP_RETURN، معیاري سکریپټ، لږ تر لږه فیس.
    د کڅوړې (CPFP) لپاره: approve_package() د مور tx ته د لږ فیس معافیت ورکوي
    کله چې د ټولې کڅوړې فیس کچه کافي وي.
    """

    def __init__(self, policy: Optional[MempoolPolicy_G2] = None,
                 classify_fn: Optional[Callable[[bytes], str]] = None,
                 op_return: int = 0x6A, package_ttl: float = 120.0,
                 clock: Callable[[], float] = time.monotonic):
        self.policy = policy or MempoolPolicy_G2()
        self._classify = classify_fn or default_classify
        self._op_return = op_return
        self._ttl = package_ttl
        self._clock = clock
        self._pkg: Dict[str, float] = {}
        self._lock = threading.RLock()

    # -- د کڅوړې معافیت ------------------------------------------------
    def approve_package(self, txids: Iterable[str]):
        with self._lock:
            exp = self._clock() + self._ttl
            for t in txids:
                self._pkg[t] = exp

    def revoke_package(self, txids: Iterable[str]):
        with self._lock:
            for t in txids:
                self._pkg.pop(t, None)

    def is_package_approved(self, txid: str) -> bool:
        with self._lock:
            exp = self._pkg.get(txid)
            if exp is None:
                return False
            if self._clock() > exp:
                del self._pkg[txid]
                return False
            return True

    # -- اصلي ازموینه ---------------------------------------------------
    def check_transaction(self, tx, utxo=None, fee: Optional[int] = None,
                          ancestors: Optional[Tuple[int, int, int]] = None) -> Tuple[bool, str]:
        """
        fee      : په ساتوشي (که معلوم وي، لږ تر لږه فیس هم ازمول کیږي)
        ancestors: (د پلرونو شمېر، د اولادونو شمېر، د پلرونو بایټ) که میمپول یې ورکړي
        """
        p = self.policy
        size = tx.byte_size()
        if size > p.max_tx_size:
            return False, msg("tx_big", size=size, max=p.max_tx_size)

        for out in tx.outputs:
            script = out.script_pubkey
            if script and script[0] == self._op_return:
                if not p.permit_op_return:
                    return False, msg("opret_off")
                dl = op_return_data_len(script)
                if dl > p.max_op_return_size:
                    return False, msg("opret_big", size=dl, max=p.max_op_return_size)
                continue                       # OP_RETURN dust نه ګڼل کیږي
            if out.value < p.dust_threshold:   # ۰ هم dust دی (په اصلي کلاس کې تېروتنه وه)
                return False, msg("dust", value=out.value, min=p.dust_threshold)
            if p.require_standard_scripts and not self.is_standard_script(script):
                return False, msg("nonstd")

        if ancestors is not None:
            a, d, ab = ancestors
            if a > p.max_ancestors or d > p.max_descendants or ab > p.max_ancestor_bytes:
                return False, msg("limits")

        if fee is not None and not self.is_package_approved(tx.txid):
            need = self.compute_minimum_fee(tx)
            if fee < need:
                return False, msg("low_fee", fee=fee, min=need)
        return True, msg("pol_ok")

    def is_standard_script(self, script: bytes) -> bool:
        try:
            t = self._classify(script)
            t = getattr(t, "value", t)
            return t != "unknown"
        except Exception:
            return False

    def compute_minimum_fee(self, tx) -> int:
        return _ceil_div(self.policy.min_relay_fee_sat_kb * max(1, tx.byte_size()), 1000)

    def policy_summary(self) -> dict:
        return {"policy": self.policy.to_dict(), "active": True}


# ==============================================================================
# 2. RBFValidator (BIP125)
# ==============================================================================
class RBFValidator:
    """
    د BIP125 بشپړ تایید. د اصلي کلاس په پرتله:
      * د لرې کېدونکو اولادونو فیس هم شمېرل کیږي (پخوا یوازې مستقیم ټکرونه)
      * نوی tx د هغه tx محصول نه شي مصرفولای چې لرې کیږي
      * ۶ مه قاعده: د نوي فیس کچه باید د هر ټکر له کچې لوړه وي (عدد-ضربي، پرته له float)
      * full_rbf=True: د ټکر د سیګنال ازموینه پریږدي
    """

    @staticmethod
    def evicted_set(conflicting: List[Any],
                    entry_lookup: Optional[Callable[[str], Any]] = None) -> Set[str]:
        out: Set[str] = set()
        for e in conflicting:
            out.add(e.txid)
            out.update(getattr(e, "descendants", ()) or ())
        return out

    @staticmethod
    def validate(new_tx, conflicting: List[Any], new_fee: int, new_size: int, utxo_set,
                 *, entry_lookup: Optional[Callable[[str], Any]] = None,
                 full_rbf: bool = False, require_new_signal: bool = False,
                 min_relay_sat_kb: int = MIN_RELAY_FEE_SAT_KB_G2,
                 max_evictions: int = MAX_REPLACEMENT_ANCESTORS_G2,
                 seq_threshold: int = RBF_SEQUENCE_THRESHOLD_G2) -> Tuple[bool, str]:
        if not conflicting:
            return True, msg("no_conf")

        # قاعده ۱ (اختیاري سخته؛ BIP125 نوی tx ته سیګنال نه غواړي)
        if require_new_signal and not any(
                getattr(i, "sequence", 0xFFFFFFFF) < seq_threshold for i in new_tx.inputs):
            return False, msg("rbf1")

        # قاعده ۲
        if not full_rbf:
            for e in conflicting:
                if not e.signals_rbf():
                    return False, msg("rbf2", txid=e.txid[:8])

        evicted = RBFValidator.evicted_set(conflicting, entry_lookup)

        # قاعده ۳ (الف): نوی tx د لرې کېدونکي tx محصول نه مصرفوي
        for inp in new_tx.inputs:
            if inp.outpoint.txid in evicted:
                return False, msg("rbf3a")

        # قاعده ۳ (ب): نوي نامنل شوي input نشته
        known = set()
        for e in conflicting:
            for inp in e.tx.inputs:
                known.add((inp.outpoint.txid, inp.outpoint.index))
        for inp in new_tx.inputs:
            k = (inp.outpoint.txid, inp.outpoint.index)
            if k not in known and not utxo_set.has(*k):
                return False, msg("rbf3b", key=f"{k[0]}:{k[1]}")

        # قاعده ۴
        if len(evicted) > max_evictions:
            return False, msg("rbf4", n=len(evicted), max=max_evictions)

        # قاعده ۵: د ټولو لرې کېدونکو (اولادونو سره) فیس
        direct = {e.txid for e in conflicting}
        evicted_fee = 0
        for t in evicted:
            if t in direct:
                e = next(x for x in conflicting if x.txid == t)
            else:
                e = entry_lookup(t) if entry_lookup else None
                if e is None:
                    return False, msg("rbf_unk")
            evicted_fee += e.fee
        if new_fee <= evicted_fee:
            return False, msg("rbf5a", new=new_fee, old=evicted_fee)
        need = evicted_fee + _ceil_div(min_relay_sat_kb * new_size, 1000)
        if new_fee < need:
            return False, msg("rbf5b", new=new_fee, need=need)

        # قاعده ۶: new_fee/new_size > e.fee/e.size   (ضربي پرتله)
        for e in conflicting:
            if new_fee * _size_of(e) <= e.fee * new_size:
                return False, msg("rbf6", txid=e.txid[:8])

        return True, msg("rbf_ok")


# ==============================================================================
# 3. PackageRelay (CPFP)
# ==============================================================================
def topo_sort(txs: List[Any]) -> Optional[List[Any]]:
    """پلرونه مخکې، ماشومان وروسته. که دوره وي None."""
    m = {t.txid: t for t in txs}
    state: Dict[str, int] = {}
    out: List[Any] = []

    def visit(txid: str) -> bool:
        s = state.get(txid)
        if s == 2:
            return True
        if s == 1:
            return False
        state[txid] = 1
        for inp in m[txid].inputs:
            if inp.outpoint.txid in m and not visit(inp.outpoint.txid):
                return False
        state[txid] = 2
        out.append(m[txid])
        return True

    for t in txs:
        if not visit(t.txid):
            return None
    return out


class PackageRelay:
    """
    د مور+ماشوم کڅوړه. د اصلي کلاس ستونزه: هر tx جلا ټولول کیده، نو ټیټ-فیس مور
    رد کیده او CPFP کار نه کاوه. دلته: ټوله کڅوړه لومړی تایید کیږي، ګډ فیس کچه
    ازمول کیږي، مور ته د کڅوړې معافیت ورکول کیږي، او که یو tx ناکام شي هر څه بیرته
    لرې کیږي (اتومي).
    """

    MAX_PACKAGE_SIZE = 25
    MAX_PACKAGE_BYTES = 101_000

    def __init__(self, mempool, blockchain=None, enforcer: Optional[MempoolPolicyEnforcer] = None,
                 fee_fn: Optional[Callable[[Any], Optional[int]]] = None,
                 remove_fn: Optional[Callable[[str], None]] = None,
                 has_fn: Optional[Callable[[str], bool]] = None,
                 min_relay_sat_kb: int = MIN_RELAY_FEE_SAT_KB_G2):
        self._mp = mempool
        self._bc = blockchain
        self._enf = enforcer
        self._fee = fee_fn or self._default_fee
        self._remove = remove_fn
        self._has = has_fn
        self._min = min_relay_sat_kb

    def _default_fee(self, tx):
        try:
            return tx.fee(self._bc.utxo)
        except Exception:
            return None

    def validate_package(self, txs: List[Any]) -> Tuple[bool, str, Optional[List[Any]]]:
        if not txs:
            return False, msg("pkg_empty"), None
        if len(txs) > self.MAX_PACKAGE_SIZE:
            return False, msg("pkg_count", n=len(txs), max=self.MAX_PACKAGE_SIZE), None
        total = sum(t.byte_size() for t in txs)
        if total > self.MAX_PACKAGE_BYTES:
            return False, msg("pkg_bytes", n=total, max=self.MAX_PACKAGE_BYTES), None
        ids = [t.txid for t in txs]
        if len(set(ids)) != len(ids):
            return False, msg("pkg_dup"), None
        seen: Set[Tuple[str, int]] = set()
        for t in txs:
            for i in t.inputs:
                k = (i.outpoint.txid, i.outpoint.index)
                if k in seen:
                    return False, msg("pkg_conf"), None
                seen.add(k)
        ordered = topo_sort(txs)
        if ordered is None:
            return False, msg("pkg_cycle"), None
        spent_in_pkg = {i.outpoint.txid for t in txs for i in t.inputs if i.outpoint.txid in set(ids)}
        sinks = [t for t in txs if t.txid not in spent_in_pkg]
        if len(sinks) != 1:
            return False, msg("pkg_shape"), None
        return True, "OK", ordered

    def package_fee_rate(self, txs: List[Any]) -> float:
        fees = [self._fee(t) for t in txs]
        if any(f is None for f in fees):
            return 0.0
        size = sum(t.byte_size() for t in txs)
        return sum(fees) / size if size > 0 else 0.0

    def submit_package(self, txs: List[Any]) -> Tuple[int, List[str]]:
        ok, why, ordered = self.validate_package(txs)
        if not ok:
            return 0, [why]
        fees = [self._fee(t) for t in ordered]
        if any(f is None for f in fees):
            return 0, [msg("pkg_fee")]
        rate = (sum(fees) * 1000) // sum(t.byte_size() for t in ordered)   # په هر kB
        if rate < self._min:
            return 0, [msg("pkg_rate", rate=rate, min=self._min)]

        ids = [t.txid for t in ordered]
        if self._enf:
            self._enf.approve_package(ids)
        accepted: List[str] = []
        errors: List[str] = []
        try:
            for t in ordered:
                if self._has and self._has(t.txid):
                    continue
                res = self._mp.submit(t)
                good = res[0] if isinstance(res, tuple) and res else (True if res is None else bool(res))
                if good:
                    accepted.append(t.txid)
                else:
                    errors.append(f"{t.txid[:8]}: {res[1] if isinstance(res, tuple) and len(res) > 1 else ''}")
                    break
        except Exception as e:
            errors.append(f"{type(e).__name__}: {e}")
        finally:
            if self._enf:
                self._enf.revoke_package(ids)
        if errors:                                    # اتومي: هر څه بیرته
            if self._remove:
                for txid in reversed(accepted):
                    self._remove(txid)
            return 0, errors
        return len(accepted), []


# ==============================================================================
# 4. BanManager
# ==============================================================================
class Misbehavior_G2(enum.Enum):
    INVALID_BLOCK = 100
    BAD_HANDSHAKE = 50
    INVALID_HEADER = 50
    INVALID_MESSAGE = 20
    DOUBLE_SPEND_RELAY = 20
    INVALID_TX = 10
    BAD_FEEFILTER = 10
    UNREQUESTED_DATA = 5
    SPAM_MESSAGE = 5
    RATE_LIMIT = 5


@dataclass
class BanEntry_G2:
    ip: str
    banned_at: float
    expires_at: float
    reason: str = ""

    def is_expired(self, now: Optional[float] = None) -> bool:
        return (now if now is not None else time.time()) >= self.expires_at

    def time_remaining(self, now: Optional[float] = None) -> float:
        return max(0.0, self.expires_at - (now if now is not None else time.time()))


class PeerScoreEntry_G2:
    """د بد چلند نمره. په نمایي ډول زوال کوي (نیمایي عمر = HALF_LIFE ثانیې)."""
    HALF_LIFE = 6 * 3600.0
    MAX_EVENTS = 50

    def __init__(self, ip: str, now: Optional[float] = None):
        self.ip = ip
        self._score = 0.0
        self._t = now if now is not None else time.time()
        self.events: collections.deque = collections.deque(maxlen=self.MAX_EVENTS)

    @property
    def score(self) -> int:
        return int(round(self._score))

    def decay(self, now: Optional[float] = None):
        now = now if now is not None else time.time()
        dt = now - self._t
        if dt > 0:
            self._score *= 0.5 ** (dt / self.HALF_LIFE)
            self._t = now
        if self._score < 0.5:
            self._score = 0.0

    def add(self, points: int, reason: str = "", now: Optional[float] = None):
        self._score += points
        self.events.append((now if now is not None else time.time(), points, reason))


class BanManager:
    """
    د IP، subnet او بد چلند مدیریت.
    اصلاحات: پورت له پتې لرې کیږي (1.2.3.4:8333 ≠ بل IP نه دی)، IPv4-mapped IPv6 عادي کیږي،
    بند/سپین لیست د CIDR ملاتړ لري، thread-safe، د نمرو حافظه محدوده، ثبت اتومي (tmp+replace).
    """
    MAX_TRACKED = 50_000

    def __init__(self, ban_duration_hours: float = BAN_DURATION_HOURS_G2,
                 threshold: int = BAN_THRESHOLD_G2, clock: Callable[[], float] = time.time):
        self._scores: "collections.OrderedDict[str, PeerScoreEntry]" = collections.OrderedDict()
        self._bans: Dict[str, BanEntry_G2] = {}
        self._net_bans: Dict[str, BanEntry_G2] = {}
        self._ban_dur = ban_duration_hours
        self._thr = threshold
        self._clock = clock
        self._wl_ips: Set[str] = set()
        self._wl_nets: List[Any] = []
        self._lock = threading.RLock()

    # -- نورمال کول ----------------------------------------------------
    @staticmethod
    def _normalize_ip(addr: str) -> str:
        a = addr.strip()
        if a.startswith("["):                           # [v6]:port
            a = a[1:a.index("]")] if "]" in a else a[1:]
        elif a.count(":") == 1:                         # v4:port
            a = a.split(":")[0]
        try:
            ip = ipaddress.ip_address(a)
            if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped:
                ip = ip.ipv4_mapped
            return str(ip)
        except ValueError:
            return a

    @staticmethod
    def _addr(ip: str):
        try:
            return ipaddress.ip_address(ip)
        except ValueError:
            return None

    def _in_whitelist(self, ip: str) -> bool:
        if ip in self._wl_ips:
            return True
        a = self._addr(ip)
        return a is not None and any(a in n for n in self._wl_nets if a.version == n.version)

    def _net_ban_for(self, ip: str) -> Optional[BanEntry_G2]:
        a = self._addr(ip)
        if a is None:
            return None
        now = self._clock()
        for cidr in list(self._net_bans):
            b = self._net_bans[cidr]
            if b.is_expired(now):
                del self._net_bans[cidr]
                continue
            n = ipaddress.ip_network(cidr)
            if n.version == a.version and a in n:
                return b
        return None

    # -- اصلي API -------------------------------------------------------
    def misbehaving(self, ip: str, behavior, extra_reason: str = "") -> bool:
        """نمره زیاتوي. که ban شي True ورکوي. behavior: هر شی چې .name او .value (int) ولري."""
        ip = self._normalize_ip(ip)
        with self._lock:
            if self._in_whitelist(ip):
                return False
            now = self._clock()
            entry = self._scores.pop(ip, None) or PeerScoreEntry_G2(ip, now)
            entry.decay(now)
            reason = behavior.name + (f": {extra_reason}" if extra_reason else "")
            entry.add(int(behavior.value), reason, now)
            if entry.score >= self._thr:
                self._do_ban(ip, self._ban_dur, f"score={entry.score} ({reason})")
                return True                              # نمره د ban سره پاکیږي
            self._scores[ip] = entry
            while len(self._scores) > self.MAX_TRACKED:
                self._scores.popitem(last=False)
            return False

    def is_banned(self, ip: str) -> bool:
        ip = self._normalize_ip(ip)
        with self._lock:
            if self._in_whitelist(ip):
                return False
            b = self._bans.get(ip)
            if b is not None:
                if b.is_expired(self._clock()):
                    del self._bans[ip]
                else:
                    return True
            return self._net_ban_for(ip) is not None

    def peer_connected(self, ip: str) -> Tuple[bool, str]:
        ip = self._normalize_ip(ip)
        with self._lock:
            if self._in_whitelist(ip):
                return True, msg("ban_wl")
            if self.is_banned(ip):
                b = self._bans.get(ip) or self._net_ban_for(ip)
                return False, msg("ban_on", h=(b.time_remaining(self._clock()) / 3600) if b else 0)
            return True, msg("ban_ok")

    def ban(self, ip: str, duration_hours: Optional[float] = None, reason: str = "manual") -> BanEntry_G2:
        with self._lock:
            return self._do_ban(self._normalize_ip(ip),
                                self._ban_dur if duration_hours is None else duration_hours, reason)

    def ban_network(self, cidr: str, duration_hours: Optional[float] = None,
                    reason: str = "manual") -> BanEntry_G2:
        net = ipaddress.ip_network(cidr, strict=False)
        now = self._clock()
        hrs = self._ban_dur if duration_hours is None else duration_hours
        b = BanEntry_G2(str(net), now, now + hrs * 3600, reason)
        with self._lock:
            self._net_bans[str(net)] = b
        return b

    def unban(self, ip: str) -> bool:
        with self._lock:
            ip = self._normalize_ip(ip)
            hit = self._bans.pop(ip, None) is not None
            hit = (self._net_bans.pop(ip, None) is not None) or hit
            return hit

    def whitelist(self, ip_or_cidr: str):
        with self._lock:
            if "/" in ip_or_cidr:
                self._wl_nets.append(ipaddress.ip_network(ip_or_cidr, strict=False))
            else:
                self._wl_ips.add(self._normalize_ip(ip_or_cidr))

    def get_score(self, ip: str) -> int:
        with self._lock:
            e = self._scores.get(self._normalize_ip(ip))
            if not e:
                return 0
            e.decay(self._clock())
            return e.score

    def get_events(self, ip: str) -> list:
        with self._lock:
            e = self._scores.get(self._normalize_ip(ip))
            return list(e.events) if e else []

    def sweep(self) -> dict:
        with self._lock:
            now = self._clock()
            eb = 0
            for store in (self._bans, self._net_bans):
                for k in [k for k, b in store.items() if b.is_expired(now)]:
                    del store[k]
                    eb += 1
            cs = 0
            for ip, e in list(self._scores.items()):
                e.decay(now)
                if e.score == 0:
                    del self._scores[ip]
                    cs += 1
            return {"expired_bans": eb, "cleared_scores": cs}

    def banlist(self) -> List[dict]:
        with self._lock:
            self.sweep()
            now = self._clock()
            return [{"ip": k, "reason": b.reason, "expires": b.expires_at,
                     "hours_left": round(b.time_remaining(now) / 3600, 2)}
                    for store in (self._bans, self._net_bans) for k, b in store.items()]

    def score_report(self, n: int = 20) -> List[dict]:
        with self._lock:
            now = self._clock()
            for e in self._scores.values():
                e.decay(now)
            top = sorted(self._scores.values(), key=lambda e: e.score, reverse=True)[:n]
            return [{"ip": e.ip, "score": e.score, "events": len(e.events)} for e in top]

    def stats(self) -> dict:
        with self._lock:
            self.sweep()
            return {"banned_peers": len(self._bans), "banned_networks": len(self._net_bans),
                    "tracked_peers": len(self._scores),
                    "whitelisted": len(self._wl_ips) + len(self._wl_nets)}

    def save(self, path: str):
        with self._lock:
            now = self._clock()
            data = {"bans": {k: {"banned_at": b.banned_at, "expires_at": b.expires_at, "reason": b.reason}
                             for k, b in self._bans.items() if not b.is_expired(now)},
                    "networks": {k: {"banned_at": b.banned_at, "expires_at": b.expires_at, "reason": b.reason}
                                 for k, b in self._net_bans.items() if not b.is_expired(now)}}
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)                           # اتومي: خراب فایل نه پاتې کیږي

    def load(self, path: str) -> int:
        if not os.path.exists(path):
            return 0
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError):
            return 0
        n = 0
        now = self._clock()
        with self._lock:
            for key, store, kind in (("bans", self._bans, "ip"), ("networks", self._net_bans, "net")):
                for k, d in (data.get(key) or {}).items():
                    try:
                        b = BanEntry_G2(k, float(d["banned_at"]), float(d["expires_at"]), d.get("reason", ""))
                        if kind == "net":
                            ipaddress.ip_network(k)
                    except (KeyError, ValueError, TypeError):
                        continue
                    if not b.is_expired(now):
                        store[k] = b
                        n += 1
        return n

    def _do_ban(self, ip: str, hours: float, reason: str) -> BanEntry_G2:
        now = self._clock()
        b = BanEntry_G2(ip, now, now + hours * 3600, reason)
        self._bans[ip] = b
        self._scores.pop(ip, None)
        return b


# ==============================================================================
# 5. PeerEvictionManager (د Bitcoin Core SelectNodeToEvict بڼه)
# ==============================================================================
def netgroup(ip: str) -> str:
    """IPv4 → /16، IPv6 → /32، نور → پخپله تار."""
    try:
        a = ipaddress.ip_address(ip)
    except ValueError:
        return ip
    if isinstance(a, ipaddress.IPv6Address) and a.ipv4_mapped:
        a = a.ipv4_mapped
    plen = 16 if a.version == 4 else 32
    return str(ipaddress.ip_network(f"{a}/{plen}", strict=False))


class PeerScoreAdv_G2:
    def __init__(self, peer_id: str, ip: str = "", inbound: bool = True,
                 now: Optional[float] = None):
        self.peer_id = peer_id
        self.ip = ip
        self.netgroup = netgroup(ip) if ip else peer_id
        self.inbound = inbound
        self.noban = False
        self.connected_at = now if now is not None else time.time()
        self.ping_ms: Optional[float] = None
        self.last_tx_time = 0.0
        self.last_block_time = 0.0
        self.blocks_sent = 0
        self.score = 0
        self.events: collections.deque = collections.deque(maxlen=20)

    def punish(self, points: int, reason: str = "") -> bool:
        self.score += points
        self.events.append((points, reason))
        return self.score >= BAN_THRESHOLD_G2

    def reward(self, points: int = 1):
        self.score = max(0, self.score - points)

    def to_dict(self) -> dict:
        return {"peer_id": self.peer_id, "ip": self.ip, "netgroup": self.netgroup,
                "inbound": self.inbound, "score": self.score, "blocks_sent": self.blocks_sent,
                "ping_ms": self.ping_ms, "connected_at": self.connected_at}


class PeerEvictionManager:
    """
    کله چې peers ډک شي، یو بد inbound peer لرې کوي، خو ښه peers ساتي:
    ۴ د جلا netgroup، ۸ د لږ ping، ۴ وروستی tx، ۴ وروستی بلاک، او پاتې نیمایي د اوږدې اړیکې.
    وروسته: که یو punished peer وي هغه لومړی؛ بیا له لویې netgroup نه ځوانترین.
    Outbound او noban peers هېڅکله نه لرې کیږي.
    """
    PROTECT_NETGROUP = 4
    PROTECT_LATENCY = 8
    PROTECT_TX = 4
    PROTECT_NEWBLOCK = 4
    PUNISH_EVICT_SCORE = 20

    def __init__(self, max_peers: int = MAX_PEERS_G2, clock: Callable[[], float] = time.time):
        self.max_peers = max_peers
        self._peers: Dict[str, PeerScoreAdv_G2] = {}
        self._lock = threading.RLock()
        self._clock = clock

    def add_peer(self, peer_id: str, ip: str = "", inbound: bool = True) -> PeerScoreAdv_G2:
        with self._lock:
            p = PeerScoreAdv_G2(peer_id, ip, inbound, self._clock())
            self._peers[peer_id] = p
            return p

    def remove_peer(self, peer_id: str):
        with self._lock:
            self._peers.pop(peer_id, None)

    def get_score(self, peer_id: str) -> Optional[PeerScoreAdv_G2]:
        return self._peers.get(peer_id)

    def should_evict(self) -> bool:
        return len(self._peers) >= self.max_peers

    # د پیښو راپور
    def on_ping(self, peer_id: str, ms: float):
        p = self._peers.get(peer_id)
        if p:
            p.ping_ms = ms if p.ping_ms is None else min(p.ping_ms, ms)

    def on_tx(self, peer_id: str):
        p = self._peers.get(peer_id)
        if p:
            p.last_tx_time = self._clock()

    def on_block(self, peer_id: str):
        p = self._peers.get(peer_id)
        if p:
            p.last_block_time = self._clock()
            p.blocks_sent += 1

    def set_noban(self, peer_id: str, v: bool = True):
        p = self._peers.get(peer_id)
        if p:
            p.noban = v

    @staticmethod
    def _protect(cands: List[PeerScoreAdv_G2], key, n: int) -> List[PeerScoreAdv_G2]:
        if n <= 0 or not cands:
            return cands
        keep = {id(p) for p in sorted(cands, key=key)[:n]}
        return [p for p in cands if id(p) not in keep]

    def select_for_eviction(self) -> Optional[str]:
        with self._lock:
            c = [p for p in self._peers.values() if p.inbound and not p.noban]
            if not c:
                return None
            # ۱) د netgroup تنوع: له هر جلا netgroup یو، تر ۴ پورې (کوچنۍ netgroup لومړی)
            size: Dict[str, int] = collections.Counter(p.netgroup for p in c)
            firsts: Dict[str, PeerScoreAdv_G2] = {}
            for p in sorted(c, key=lambda p: (size[p.netgroup], p.connected_at)):
                firsts.setdefault(p.netgroup, p)
            keep = {id(p) for p in list(firsts.values())[:self.PROTECT_NETGROUP]}
            c = [p for p in c if id(p) not in keep]
            # ۲) ټیټ ping   ۳) وروستی tx   ۴) وروستی بلاک
            c = self._protect(c, lambda p: (p.ping_ms is None, p.ping_ms or 0.0), self.PROTECT_LATENCY)
            c = self._protect(c, lambda p: -p.last_tx_time, self.PROTECT_TX)
            c = self._protect(c, lambda p: -p.last_block_time, self.PROTECT_NEWBLOCK)
            # ۵) پاتې نیمایي: اوږدترین اړیکه
            c = self._protect(c, lambda p: p.connected_at, len(c) // 2)
            if not c:
                return None
            worst = max(c, key=lambda p: p.score)
            if worst.score >= self.PUNISH_EVICT_SCORE:
                return worst.peer_id
            groups: Dict[str, List[PeerScoreAdv_G2]] = collections.defaultdict(list)
            for p in c:
                groups[p.netgroup].append(p)
            big = max(groups.values(), key=lambda g: (len(g), max(x.connected_at for x in g)))
            return max(big, key=lambda p: p.connected_at).peer_id

    def punish_peer(self, peer_id: str, points: int, reason: str = "") -> bool:
        with self._lock:
            p = self._peers.get(peer_id)
            return p.punish(points, reason) if p else False

    def reward_peer(self, peer_id: str, points: int = 1):
        with self._lock:
            p = self._peers.get(peer_id)
            if p:
                p.reward(points)

    def active_count(self) -> int:
        return len(self._peers)

    def top_peers(self, n: int = 10) -> List[dict]:
        with self._lock:
            return [p.to_dict() for p in sorted(self._peers.values(),
                                                key=lambda p: p.blocks_sent, reverse=True)[:n]]


# ==============================================================================
# د وصلولو طبقه
# ==============================================================================
class Group2Wiring:
    """
        g2 = Group2Wiring.from_host(globals(), g1=g1, fee_fn=..., entry_lookup=..., remove_fn=...,
                                    has_fn=..., utxo_fn=lambda: chain.utxo)
        g2.attach_mempool(node.mempool)       # Mempool.submit wrapper (د g1 له wrapper نه بهر)
        g2.packages = PackageRelay(...)       # په attach_mempool کې جوړیږي
        P2P: g2.may_connect(addr) / g2.misbehaving(addr, Misbehavior.INVALID_TX)
             peers ډک → g2.eviction.select_for_eviction()
        بیرته: g2.detach()

    ترتیب مهم دی: لومړی g1.attach_mempool، بیا g2.attach_mempool. g2 بهرنی دی: پالیسي او RBF
    مخکې ازمول کیږي، لرې کېدونکي tx پاکیږي، بیا g1 (ټکر/سپیم) او اصلي submit.
    """

    def __init__(self, g1=None, policy: Optional[MempoolPolicy_G2] = None,
                 classify_fn=None, fee_fn: Optional[Callable[[Any], Optional[int]]] = None,
                 entry_lookup: Optional[Callable[[str], Any]] = None,
                 remove_fn: Optional[Callable[[str], None]] = None,
                 has_fn: Optional[Callable[[str], bool]] = None,
                 utxo_fn: Optional[Callable[[], Any]] = None,
                 conflicts_fn: Optional[Callable[[Any], Set[str]]] = None,
                 ancestry_fn: Optional[Callable[[Any], Tuple[int, int, int]]] = None,
                 full_rbf: bool = False, ban_hours: float = BAN_DURATION_HOURS_G2,
                 max_peers: int = MAX_PEERS_G2, op_return: int = 0x6A,
                 reject: Callable[[str], Any] = lambda r: (False, r)):
        self.g1 = g1
        self.enforcer = MempoolPolicyEnforcer(policy, classify_fn, op_return)
        self.bans = BanManager(ban_hours, BAN_THRESHOLD_G2)
        self.eviction = PeerEvictionManager(max_peers)
        self.packages: Optional[PackageRelay] = None
        self._fee, self._lookup, self._remove, self._has = fee_fn, entry_lookup, remove_fn, has_fn
        self._utxo_fn, self._ancestry = utxo_fn, ancestry_fn
        self._conflicts_fn = conflicts_fn
        self._full_rbf = full_rbf
        self._reject = reject
        self._undo: List[Callable[[], None]] = []
        self._min_relay = self.enforcer.policy.min_relay_fee_sat_kb

    @classmethod
    def from_host(cls, host_globals: dict, **kw):
        g = host_globals
        global RBF_SEQUENCE_THRESHOLD_G2, MAX_REPLACEMENT_ANCESTORS_G2, BAN_THRESHOLD_G2
        RBF_SEQUENCE_THRESHOLD_G2 = g.get("RBF_SEQUENCE_THRESHOLD", RBF_SEQUENCE_THRESHOLD_G2)
        MAX_REPLACEMENT_ANCESTORS_G2 = g.get("MAX_REPLACEMENT_ANCESTORS", MAX_REPLACEMENT_ANCESTORS_G2)
        BAN_THRESHOLD_G2 = g.get("BAN_THRESHOLD", BAN_THRESHOLD_G2)
        kw.setdefault("ban_hours", g.get("BAN_DURATION_HOURS", BAN_DURATION_HOURS_G2))
        kw.setdefault("max_peers", g.get("MAX_PEERS", MAX_PEERS_G2))
        kw.setdefault("op_return", g.get("OP_RETURN", 0x6A))
        script = g.get("Script")
        if script is not None and hasattr(script, "classify") and "classify_fn" not in kw:
            kw["classify_fn"] = script.classify
        if "policy" not in kw and g.get("MempoolPolicy") is not None:
            try:
                kw["policy"] = g["MempoolPolicy"]()
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in Group2Wiring.from_host", exc_info=True)
        return cls(**kw)

    @staticmethod
    def _accepted(r) -> bool:
        if isinstance(r, tuple) and r:
            return bool(r[0])
        return True if r is None else bool(r)

    def _conflicts(self, tx) -> Set[str]:
        if self._conflicts_fn:
            return set(self._conflicts_fn(tx))
        if self.g1 is not None:
            return set(self.g1.doublespend.check(tx.inputs, own_txid=tx.txid))
        return set()

    # -- میمپول ---------------------------------------------------------
    def attach_mempool(self, mempool):
        orig = mempool.submit
        def remove_all(txid: str):
            # د میمپول نه لرې کول + په g1 کې د محصولاتو ځای نیول خلاصول (نه نو پاتې کیږي)
            if self._remove:
                self._remove(txid)
            if self.g1 is not None:
                self.g1.doublespend.release(txid)

        self.packages = PackageRelay(mempool, None, self.enforcer, self._fee, remove_all,
                                     self._has, self._min_relay)

        def submit(tx, *a, **kw):
            fee = self._fee(tx) if self._fee else None
            ok, why = self.enforcer.check_transaction(
                tx, self._utxo_fn() if self._utxo_fn else None, fee,
                self._ancestry(tx) if self._ancestry else None)
            if not ok:
                return self._reject(why)

            snapshot: List[Any] = []
            conflicts = self._conflicts(tx)
            if conflicts:
                if fee is None:
                    return self._reject(msg("rbf_nofee"))
                if self._lookup is None:
                    return self._reject(msg("rbf_noent"))
                entries = [self._lookup(t) for t in sorted(conflicts)]
                if any(e is None for e in entries):
                    return self._reject(msg("rbf_noent"))
                utxo = self._utxo_fn() if self._utxo_fn else None
                ok, why = RBFValidator.validate(
                    tx, entries, fee, _size_of(tx), utxo, entry_lookup=self._lookup,
                    full_rbf=self._full_rbf, min_relay_sat_kb=self._min_relay,
                    max_evictions=MAX_REPLACEMENT_ANCESTORS_G2, seq_threshold=RBF_SEQUENCE_THRESHOLD_G2)
                if not ok:
                    return self._reject(why)
                evicted = RBFValidator.evicted_set(entries)
                snapshot = [self._lookup(t) for t in evicted]
                for t in evicted:
                    remove_all(t)

            def restore():
                if not snapshot:
                    return
                txs = [e.tx for e in snapshot if e is not None]
                for t in (topo_sort(txs) or txs):
                    try:
                        orig(t)
                    except Exception:
                        _NB_SWALLOW_LOG.debug("swallowed Exception in Group2Wiring.attach_mempool.submit.restore", exc_info=True)

            try:
                res = orig(tx, *a, **kw)
            except Exception:
                restore()
                raise
            if not self._accepted(res):
                restore()
            return res

        mempool.submit = submit
        self._undo.append(lambda m=mempool, o=orig: self._restore(m, "submit", o))

    @staticmethod
    def _restore(obj, name, orig):
        if getattr(type(obj), name, None) is not None and getattr(orig, "__self__", None) is obj:
            try:
                delattr(obj, name)
                return
            except AttributeError:
                _NB_SWALLOW_LOG.warning("swallowed AttributeError in Group2Wiring._restore", exc_info=True)
        setattr(obj, name, orig)

    def detach(self):
        while self._undo:
            self._undo.pop()()

    # -- P2P (څرګند هکونه) -------------------------------------------------
    def may_connect(self, addr: str) -> Tuple[bool, str]:
        return self.bans.peer_connected(addr)

    def misbehaving(self, addr: str, behavior, why: str = "") -> bool:
        return self.bans.misbehaving(addr, behavior, why)

    def misbehaving_named(self, addr: str, kind: str, why: str = "") -> bool:
        """v10.16: same as misbehaving() but the behaviour is given by NAME ('INVALID_HEADER' ...).
        Other groups (g4) use this so they never need `import nebula_group2` - the code keeps working
        when all groups are merged into one single file. Unknown name -> KeyError."""
        return self.bans.misbehaving(addr, Misbehavior_G2[kind], why)

    def peer_ip(self, peer_id: str) -> Optional[str]:
        """The IP g2 knows for this peer id (None if the peer was never registered via on_peer_connected)."""
        ps = self.eviction.get_score(peer_id)
        return ps.ip if ps is not None and ps.ip else None

    def on_peer_connected(self, peer_id: str, addr: str, inbound: bool = True):
        return self.eviction.add_peer(peer_id, BanManager._normalize_ip(addr), inbound)

    def on_peer_disconnected(self, peer_id: str):
        self.eviction.remove_peer(peer_id)

    def make_room(self) -> Optional[str]:
        """که peers ډک وي، د لرې کولو peer id ورکوي (تاسو یې disconnect کړئ)."""
        return self.eviction.select_for_eviction() if self.eviction.should_evict() else None

    def stats(self) -> dict:
        return {"policy": self.enforcer.policy_summary(), "bans": self.bans.stats(),
                "peers": self.eviction.active_count()}

# ============================================================================
# GROUP 3  (source: nebula_group3.py, v10.14)
# ============================================================================
# """
# NEBULA v10.14 - Group 3 (5 classes revived and hardened, plus the wiring layer)
#
#     PersistentBlockStore       -> NEBULABlockchain.add_block   (append-only blk files + SQLite index, crash recovery)
#     PersistentUTXOSet          -> NEBULABlockchain.add_block   (atomic connect/disconnect with undo data, SQLite/LevelDB)
#     UTXOSnapshot               -> RPC / start-up               (checksummed, hash-verified fast bootstrap)
#     PruningManager             -> after add_block              (whole-file pruning, reorg-safe window, undo pruning)
#     VersionBitsStateMachine    -> block template / RPC         (BIP9 state machine, SIGNAL ONLY, never rejects)
#
# Supporting classes (they are required by the five above): ChainDatabase (store + UTXO set + reorg engine),
# Coin, KVBackend / SQLiteBackend / LevelDBBackend / MemoryBackend, BlockAccess, JSONBlockCodec,
# Deployment, HeaderInfo, ThresholdState.
#
# Design rules (same as groups 1 and 2):
#   * surgical: nothing in nebula_v10_11.py is rewritten; everything attaches by wrapping add_block
#   * real: real file format with checksums, real fsync ordering, real BIP9 rules, real undo data
#   * reversible: Group3Wiring.detach() restores the original add_block exactly
#   * consensus-safe: this group never rejects a block. If persistence fails the node keeps running,
#     the error is recorded (g3.healthy == False) and strict=True turns it into an exception.
#
# Crash-safety order for every accepted block
#   1. block record appended to blkNNNNN.dat and fsync'ed          (store.put_block)
#   2. UTXO changes + undo record + best-block pointer committed in ONE atomic batch (utxo.connect_block)
#   3. 'main chain' flags in the index re-derived from the UTXO best block      (store.set_main_chain)
# A crash between any two steps is repaired by ChainDatabase.recover() on the next start.
# """












log_G3 = logging.getLogger("nebula.group3")

OP_RETURN_DEFAULT = 0x6A


class Group3Error(Exception):
    pass


class StoreCorruption(Group3Error):
    pass


class BlockPrunedError(Group3Error):
    pass


class MissingParent(Group3Error):
    pass


class InvalidChain(Group3Error):
    pass


class UTXOConsistencyError(Group3Error):
    pass


class HostDivergence(Group3Error):
    """strict=True: the host accepted a block the chain database cannot follow."""


class SnapshotError(Group3Error):
    pass


def _sha256d(b: bytes) -> bytes:
    return hashlib.sha256(hashlib.sha256(b).digest()).digest()


def _fsync_dir(path: str):
    try:
        fd = os.open(path, os.O_RDONLY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
    except OSError:
        _NB_SWALLOW_LOG.warning("swallowed OSError in _fsync_dir", exc_info=True)                      # not supported on this platform (e.g. Windows)


# ==============================================================================
# Host adaptation: how to read a block / encode it. Duck-typed, overridable.
# ==============================================================================
def _attr(obj, names: Sequence[str], default=None):
    for n in names:
        if hasattr(obj, n):
            v = getattr(obj, n)
            return v() if callable(v) else v
    return default


class BlockAccess:
    """Reads hash/height/prev/time/version from a block. Pass callables to override the guesses."""

    def __init__(self, hash_fn=None, height_fn=None, prev_fn=None, time_fn=None, version_fn=None):
        self._h, self._ht, self._p, self._t, self._v = hash_fn, height_fn, prev_fn, time_fn, version_fn

    def hash(self, b) -> str:
        v = self._h(b) if self._h else _attr(b, ("hash", "block_hash", "hash_hex"))
        if v is None:
            raise Group3Error("block has no hash")
        return v if isinstance(v, str) else v.hex()

    def height(self, b) -> int:
        v = self._ht(b) if self._ht else _attr(b, ("height", "index", "number"))
        if v is None:
            raise Group3Error("block has no height")
        return int(v)

    def prev(self, b) -> Optional[str]:
        v = self._p(b) if self._p else _attr(b, ("prev_hash", "previous_hash", "prev_block_hash", "parent_hash"))
        return v.hex() if isinstance(v, (bytes, bytearray)) else v

    def time(self, b) -> int:
        v = self._t(b) if self._t else _attr(b, ("timestamp", "time"))
        return int(v or 0)

    def version(self, b) -> int:
        v = self._v(b) if self._v else _attr(b, ("version",))
        return int(v or 0)


class JSONBlockCodec:
    """Block <-> bytes through the host's own to_dict()/from_dict(). JSON, never pickle (a tampered
    data directory must not be able to execute code)."""

    def __init__(self, to_dict: Callable[[Any], dict], from_dict: Callable[[dict], Any]):
        self._to, self._from = to_dict, from_dict

    def encode(self, block) -> bytes:
        return json.dumps(self._to(block), sort_keys=True, separators=(",", ":")).encode("utf-8")

    def decode(self, data: bytes):
        return self._from(json.loads(data.decode("utf-8")))


def _coerce_bytes_G3(v) -> bytes:
    if v is None:
        return b""
    if isinstance(v, (bytes, bytearray)):
        return bytes(v)
    if isinstance(v, str):
        try:
            return bytes.fromhex(v)
        except ValueError:
            return v.encode("utf-8")
    raise Group3Error(f"unsupported script type {type(v)}")


def default_ledger(block) -> List[Tuple[str, bool, List[Tuple[str, int]], List[Tuple[int, bytes, str]]]]:
    """block -> [(txid, is_coinbase, [(prev_txid, index)], [(value, script, address)])]"""
    out = []
    for tx in block.transactions:
        cb = bool(_attr(tx, ("is_coinbase",), False))
        ins = [] if cb else [(i.outpoint.txid, int(i.outpoint.index)) for i in tx.inputs]
        outs = []
        for o in tx.outputs:
            script = _coerce_bytes_G3(_attr(o, ("script_pubkey", "script", "pk_script"), b""))
            outs.append((int(o.value), script, str(_attr(o, ("address",), "") or "")))
        out.append((tx.txid, cb, ins, outs))
    return out


# ==============================================================================
# 1. PersistentBlockStore
# ==============================================================================
_REC = struct.Struct(">4sI")           # magic, payload length
_MAGIC = b"NBLK"


class PersistentBlockStore:
    """
    Append-only block files (blk00000.dat ...) + a SQLite index.

    Record = magic(4) | length(4) | payload | sha256d(payload)[:4]
    Index  = hash, height, prev, file, pos, size, main/pruned/invalid flags.

    Crash safety: the record is fsync'ed BEFORE it is indexed. On open every file is scanned from its
    last indexed byte: complete records are re-indexed, a torn tail is truncated, files that a crashed
    prune left behind are removed. get_block() re-verifies checksum and hash on every read.
    """

    def __init__(self, directory: str, codec, access: Optional[BlockAccess] = None,
                 max_file_size: int = 128 * 1024 * 1024, max_block_bytes: int = 64 * 1024 * 1024,
                 fsync: bool = True, genesis_height: int = 0):
        self.dir = directory
        os.makedirs(directory, exist_ok=True)
        self.codec = codec
        self.acc = access or BlockAccess()
        self.max_file_size = max_file_size
        self.max_block_bytes = max_block_bytes
        self.fsync = fsync
        self.genesis_height = genesis_height
        self._lock = threading.RLock()
        self._db = sqlite3.connect(os.path.join(directory, "index.db"), check_same_thread=False,
                                   isolation_level=None)
        self._db.execute("PRAGMA journal_mode=WAL")
        self._db.execute("PRAGMA synchronous=FULL")
        self._db.executescript("""
            CREATE TABLE IF NOT EXISTS blocks(
                hash TEXT PRIMARY KEY, height INTEGER NOT NULL, prev TEXT,
                file INTEGER NOT NULL, pos INTEGER NOT NULL, size INTEGER NOT NULL,
                main INTEGER NOT NULL DEFAULT 0, pruned INTEGER NOT NULL DEFAULT 0,
                invalid INTEGER NOT NULL DEFAULT 0);
            CREATE INDEX IF NOT EXISTS ix_blocks_height ON blocks(height);
            CREATE INDEX IF NOT EXISTS ix_blocks_prev ON blocks(prev);
            CREATE INDEX IF NOT EXISTS ix_blocks_file ON blocks(file);
            CREATE TABLE IF NOT EXISTS files(
                n INTEGER PRIMARY KEY, size INTEGER NOT NULL, pruned INTEGER NOT NULL DEFAULT 0);
        """)
        self.recovery = self._recover()
        row = self._db.execute("SELECT MAX(n) FROM files").fetchone()
        self._cur_file = row[0] if row and row[0] is not None else 0
        self._cur_size = self._file_size_db(self._cur_file)

    # -- helpers -------------------------------------------------------------
    def _path(self, n: int) -> str:
        return os.path.join(self.dir, f"blk{n:05d}.dat")

    def _file_size_db(self, n: int) -> int:
        r = self._db.execute("SELECT size FROM files WHERE n=?", (n,)).fetchone()
        return r[0] if r else 0

    class _Tx:
        def __init__(self, db):
            self.db = db

        def __enter__(self):
            self.db.execute("BEGIN IMMEDIATE")

        def __exit__(self, et, ev, tb):
            self.db.execute("COMMIT" if et is None else "ROLLBACK")
            return False

    def _tx(self):
        return self._Tx(self._db)

    def close(self):
        with self._lock:
            try:
                self._db.close()
            except sqlite3.Error:
                _NB_SWALLOW_LOG.warning("swallowed sqlite3.Error in PersistentBlockStore.close", exc_info=True)

    # -- recovery ------------------------------------------------------------
    def _recover(self) -> dict:
        rep = {"reindexed": 0, "truncated_bytes": 0, "dropped": [], "finished_prune": []}
        on_disk = sorted(int(f[3:8]) for f in os.listdir(self.dir)
                         if f.startswith("blk") and f.endswith(".dat") and len(f) == 12 and f[3:8].isdigit())
        known = {n: (s, p) for n, s, p in self._db.execute("SELECT n,size,pruned FROM files")}
        for n in on_disk:
            if n in known and known[n][1]:
                os.remove(self._path(n))                      # prune crashed after DB commit
                rep["finished_prune"].append(n)
                continue
            self._scan_file(n, known.get(n, (0, 0))[0], rep)
        for n, (size, pruned) in known.items():
            if not pruned and n not in on_disk:               # whole file vanished
                gone = [r[0] for r in self._db.execute("SELECT hash FROM blocks WHERE file=?", (n,))]
                with self._tx():
                    self._db.execute("DELETE FROM blocks WHERE file=?", (n,))
                    self._db.execute("DELETE FROM files WHERE n=?", (n,))
                rep["dropped"].extend(gone)
        return rep

    def _scan_file(self, n: int, start: int, rep: dict):
        path = self._path(n)
        actual = os.path.getsize(path)
        if actual < start:                                    # data lost behind the index
            gone = [r[0] for r in self._db.execute(
                "SELECT hash FROM blocks WHERE file=? AND pos+size>?", (n, actual))]
            with self._tx():
                self._db.execute("DELETE FROM blocks WHERE file=? AND pos+size>?", (n, actual))
            rep["dropped"].extend(gone)
            r = self._db.execute("SELECT MAX(pos+size) FROM blocks WHERE file=?", (n,)).fetchone()
            start = r[0] or 0
        rows, off = [], start
        with open(path, "r+b") as f:
            f.seek(start)
            while True:
                hdr = f.read(_REC.size)
                if len(hdr) < _REC.size:
                    break
                magic, ln = _REC.unpack(hdr)
                if magic != _MAGIC or ln > self.max_block_bytes:
                    break
                payload, ck = f.read(ln), f.read(4)
                if len(payload) < ln or len(ck) < 4 or _sha256d(payload)[:4] != ck:
                    break
                try:
                    blk = self.codec.decode(payload)
                    h, ht, pv = self.acc.hash(blk), self.acc.height(blk), self.acc.prev(blk)
                except Exception:
                    break
                total = _REC.size + ln + 4
                rows.append((h, ht, pv, n, off, total))
                off += total
            if off < actual:
                f.truncate(off)
                f.flush()
                os.fsync(f.fileno())
                rep["truncated_bytes"] += actual - off
        with self._tx():
            for r in rows:
                self._db.execute("INSERT OR IGNORE INTO blocks(hash,height,prev,file,pos,size) VALUES(?,?,?,?,?,?)", r)
            self._db.execute("INSERT OR REPLACE INTO files(n,size,pruned) VALUES(?,?,0)", (n, off))
        rep["reindexed"] += len(rows)

    # -- write / read --------------------------------------------------------
    def has_block(self, h: str) -> bool:
        with self._lock:
            return self._db.execute("SELECT 1 FROM blocks WHERE hash=?", (h,)).fetchone() is not None

    def put_block(self, block) -> bool:
        """Durably store a block. Returns False if it was already stored."""
        h, ht, pv = self.acc.hash(block), self.acc.height(block), self.acc.prev(block)
        with self._lock:
            if self.has_block(h):
                return False
            payload = self.codec.encode(block)
            if len(payload) > self.max_block_bytes:
                raise Group3Error("block larger than max_block_bytes")
            rec = _REC.pack(_MAGIC, len(payload)) + payload + _sha256d(payload)[:4]
            if self._cur_size > 0 and self._cur_size + len(rec) > self.max_file_size:
                self._cur_file += 1
                self._cur_size = 0
            n, new_file = self._cur_file, not os.path.exists(self._path(self._cur_file))
            with open(self._path(n), "ab") as f:
                f.seek(0, os.SEEK_END)
                pos = f.tell()
                f.write(rec)
                f.flush()
                if self.fsync:
                    os.fsync(f.fileno())
            if new_file and self.fsync:
                _fsync_dir(self.dir)
            end = pos + len(rec)
            with self._tx():
                self._db.execute("INSERT INTO blocks(hash,height,prev,file,pos,size) VALUES(?,?,?,?,?,?)",
                                 (h, ht, pv, n, pos, len(rec)))
                self._db.execute("INSERT OR REPLACE INTO files(n,size,pruned) VALUES(?,?,0)", (n, end))
            self._cur_size = end
            return True

    def get_raw(self, h: str) -> Optional[bytes]:
        with self._lock:
            r = self._db.execute("SELECT file,pos,size,pruned FROM blocks WHERE hash=?", (h,)).fetchone()
        if r is None:
            return None
        n, pos, size, pruned = r
        if pruned:
            raise BlockPrunedError(h)
        with open(self._path(n), "rb") as f:
            f.seek(pos)
            data = f.read(size)
        if len(data) != size:
            raise StoreCorruption(f"short read for block {h}")
        magic, ln = _REC.unpack(data[:_REC.size])
        payload, ck = data[_REC.size:_REC.size + ln], data[_REC.size + ln:]
        if magic != _MAGIC or len(payload) != ln or _sha256d(payload)[:4] != ck:
            raise StoreCorruption(f"checksum failure for block {h}")
        return payload

    def get_block(self, h: str):
        raw = self.get_raw(h)
        if raw is None:
            return None
        blk = self.codec.decode(raw)
        if self.acc.hash(blk) != h:
            raise StoreCorruption(f"block {h} decodes to a different hash")
        return blk

    # -- index queries -------------------------------------------------------
    def info(self, h: str) -> Optional[dict]:
        with self._lock:
            r = self._db.execute("SELECT hash,height,prev,file,main,pruned,invalid FROM blocks WHERE hash=?",
                                 (h,)).fetchone()
        return None if r is None else dict(zip(("hash", "height", "prev", "file", "main", "pruned", "invalid"), r))

    def is_pruned(self, h: str) -> bool:
        i = self.info(h)
        return bool(i and i["pruned"])

    def hash_at_height(self, height: int) -> Optional[str]:
        with self._lock:
            r = self._db.execute("SELECT hash FROM blocks WHERE main=1 AND height=?", (height,)).fetchone()
        return r[0] if r else None

    def tip(self) -> Optional[Tuple[str, int]]:
        with self._lock:
            r = self._db.execute("SELECT hash,height FROM blocks WHERE main=1 ORDER BY height DESC LIMIT 1").fetchone()
        return (r[0], r[1]) if r else None

    def count(self) -> int:
        with self._lock:
            return self._db.execute("SELECT COUNT(*) FROM blocks").fetchone()[0]

    def candidates(self) -> Iterator[Tuple[str, int]]:
        """Non-invalid blocks, highest first (ties: first stored)."""
        with self._lock:
            rows = self._db.execute(
                "SELECT hash,height FROM blocks WHERE invalid=0 ORDER BY height DESC, rowid ASC").fetchall()
        return iter(rows)

    def mark_invalid(self, h: str) -> int:
        """Flag a block and every stored descendant as invalid."""
        with self._lock:
            frontier, seen = [h], set()
            while frontier:
                cur = frontier.pop()
                if cur in seen:
                    continue
                seen.add(cur)
                frontier += [r[0] for r in self._db.execute("SELECT hash FROM blocks WHERE prev=?", (cur,))]
            with self._tx():
                for x in seen:
                    self._db.execute("UPDATE blocks SET invalid=1, main=0 WHERE hash=?", (x,))
            return len(seen)

    # -- main chain ----------------------------------------------------------
    def plan_chain(self, tip_hash: str, anchor: Optional[Tuple[str, int]] = None
                   ) -> Tuple[int, List[str], List[str]]:
        """Pure read. Returns (fork_height, hashes_to_disconnect (top first), hashes_to_connect (bottom first)).
        `anchor` = (hash,height) of a trusted base that is not in the store (snapshot start)."""
        with self._lock:
            chain, cur, fork_h = [], tip_hash, None
            while fork_h is None:
                r = self._db.execute("SELECT hash,height,prev,main,invalid FROM blocks WHERE hash=?",
                                     (cur,)).fetchone()
                if r is None:
                    raise MissingParent(cur)
                h, ht, pv, main, inv = r
                if inv:
                    raise InvalidChain(h)
                if main:
                    fork_h = ht
                    break
                chain.append(h)
                if anchor is not None and pv == anchor[0]:
                    fork_h = anchor[1]
                elif ht <= self.genesis_height:
                    fork_h = self.genesis_height - 1
                else:
                    cur = pv
            down = [x[0] for x in self._db.execute(
                "SELECT hash FROM blocks WHERE main=1 AND height>? ORDER BY height DESC", (fork_h,))]
            return fork_h, down, list(reversed(chain))

    def set_main_chain(self, tip_hash: str, anchor=None) -> Tuple[int, List[str], List[str]]:
        with self._lock:
            fork_h, down, up = self.plan_chain(tip_hash, anchor)
            with self._tx():
                self._db.execute("UPDATE blocks SET main=0 WHERE main=1 AND height>?", (fork_h,))
                for h in up:
                    self._db.execute("UPDATE blocks SET main=1 WHERE hash=?", (h,))
            return fork_h, down, up

    def iter_main_chain(self, start_height: int = 0) -> Iterator[Any]:
        """Yield main-chain blocks in order, skipping pruned ones. For host replay on restart."""
        with self._lock:
            hs = [r[0] for r in self._db.execute(
                "SELECT hash FROM blocks WHERE main=1 AND pruned=0 AND height>=? ORDER BY height", (start_height,))]
        for h in hs:
            yield self.get_block(h)

    # -- pruning primitives --------------------------------------------------
    def file_stats(self) -> List[dict]:
        with self._lock:
            rows = self._db.execute("""
                SELECT f.n, f.size, f.pruned, MIN(b.height), MAX(b.height), COUNT(b.hash)
                FROM files f LEFT JOIN blocks b ON b.file=f.n GROUP BY f.n ORDER BY f.n""").fetchall()
        return [dict(n=n, size=s, pruned=bool(p), min_height=mn, max_height=mx, blocks=c)
                for n, s, p, mn, mx, c in rows]

    def disk_usage(self) -> int:
        with self._lock:
            return self._db.execute("SELECT COALESCE(SUM(size),0) FROM files WHERE pruned=0").fetchone()[0]

    def prune_file(self, n: int) -> int:
        """Flag every block in the file as pruned (committed first), then delete it. Returns bytes freed."""
        with self._lock:
            if n == self._cur_file:
                raise Group3Error("refusing to prune the file currently being written")
            r = self._db.execute("SELECT size,pruned FROM files WHERE n=?", (n,)).fetchone()
            if r is None or r[1]:
                return 0
            with self._tx():
                self._db.execute("UPDATE blocks SET pruned=1 WHERE file=?", (n,))
                self._db.execute("UPDATE files SET pruned=1, size=0 WHERE n=?", (n,))
            try:
                os.remove(self._path(n))
            except FileNotFoundError:
                pass
            return r[0]

    def first_unpruned_main_height(self) -> Optional[int]:
        with self._lock:
            r = self._db.execute("SELECT MIN(height) FROM blocks WHERE main=1 AND pruned=0").fetchone()
        return r[0]


# ==============================================================================
# 2. PersistentUTXOSet  (+ key/value backends)
# ==============================================================================
class KVBackend:
    """write_batch(puts, deletes) is ATOMIC: deletes are applied first, then puts."""

    def get(self, k: bytes) -> Optional[bytes]:
        raise NotImplementedError

    def write_batch(self, puts: Dict[bytes, bytes], deletes: Iterable[bytes]):
        raise NotImplementedError

    def iter_prefix(self, prefix: bytes) -> Iterator[Tuple[bytes, bytes]]:
        raise NotImplementedError

    def close(self):
        pass


def _prefix_end(prefix: bytes) -> bytes:
    b = bytearray(prefix)
    while b and b[-1] == 0xFF:
        b.pop()
    if not b:
        return b"\xff" * 64
    b[-1] += 1
    return bytes(b)


class MemoryBackend(KVBackend):
    def __init__(self):
        self.d: Dict[bytes, bytes] = {}

    def get(self, k):
        return self.d.get(k)

    def write_batch(self, puts, deletes):
        snap = dict(self.d)
        try:
            for k in deletes:
                self.d.pop(k, None)
            self.d.update(puts)
        except Exception:
            self.d = snap
            raise

    def iter_prefix(self, prefix):
        for k in sorted(k for k in self.d if k.startswith(prefix)):
            yield k, self.d[k]


class SQLiteBackend_G3(KVBackend):
    """Durable KV store: one WITHOUT ROWID table, WAL, synchronous=FULL (commit = on disk)."""

    def __init__(self, path: str, synchronous: str = "FULL"):
        d = os.path.dirname(path)
        if d:
            os.makedirs(d, exist_ok=True)
        self._lock = threading.RLock()
        self._db = sqlite3.connect(path, check_same_thread=False, isolation_level=None)
        self._db.execute("PRAGMA journal_mode=WAL")
        self._db.execute(f"PRAGMA synchronous={synchronous}")
        self._db.execute("CREATE TABLE IF NOT EXISTS kv(k BLOB PRIMARY KEY, v BLOB NOT NULL) WITHOUT ROWID")

    def get(self, k):
        with self._lock:
            r = self._db.execute("SELECT v FROM kv WHERE k=?", (k,)).fetchone()
        return bytes(r[0]) if r else None

    def write_batch(self, puts, deletes):
        with self._lock:
            self._db.execute("BEGIN IMMEDIATE")
            try:
                self._db.executemany("DELETE FROM kv WHERE k=?", [(k,) for k in deletes])
                self._db.executemany("INSERT OR REPLACE INTO kv(k,v) VALUES(?,?)", list(puts.items()))
            except Exception:
                self._db.execute("ROLLBACK")
                raise
            self._db.execute("COMMIT")

    def iter_prefix(self, prefix):
        last, end = prefix, _prefix_end(prefix)
        first = True
        while True:                                         # keyset pagination: safe while others write
            with self._lock:
                op = ">=" if first else ">"
                rows = self._db.execute(f"SELECT k,v FROM kv WHERE k{op}? AND k<? ORDER BY k LIMIT 2000",
                                        (last, end)).fetchall()
            if not rows:
                return
            for k, v in rows:
                yield bytes(k), bytes(v)
            last, first = bytes(rows[-1][0]), False

    def close(self):
        with self._lock:
            self._db.close()


class LevelDBBackend_G3(KVBackend):
    """Adapter for `plyvel`. Needs `pip install plyvel`; raises a clear error if it is missing."""

    def __init__(self, path: str):
        try:
            import plyvel
        except ImportError as e:
            raise Group3Error("LevelDBBackend needs the 'plyvel' package (pip install plyvel)") from e
        os.makedirs(path, exist_ok=True)
        self._db = plyvel.DB(path, create_if_missing=True)

    def get(self, k):
        return self._db.get(k)

    def write_batch(self, puts, deletes):
        with self._db.write_batch(sync=True, transaction=True) as wb:
            for k in deletes:
                wb.delete(k)
            for k, v in puts.items():
                wb.put(k, v)

    def iter_prefix(self, prefix):
        yield from self._db.iterator(prefix=prefix)

    def close(self):
        self._db.close()


@dataclass(frozen=True)
class Coin:
    value: int
    script: bytes = b""
    height: int = 0
    coinbase: bool = False
    address: str = ""

    def to_bytes(self) -> bytes:
        if not 0 <= self.value < 2 ** 64:
            raise UTXOConsistencyError("coin value out of range")
        a = self.address.encode("utf-8")
        return (struct.pack(">QIBI", self.value, self.height, 1 if self.coinbase else 0, len(self.script))
                + self.script + struct.pack(">H", len(a)) + a)

    @staticmethod
    def from_bytes(b: bytes) -> "Coin":
        value, height, cb, sl = struct.unpack_from(">QIBI", b, 0)
        o = 17
        script = b[o:o + sl]
        (al,) = struct.unpack_from(">H", b, o + sl)
        addr = b[o + sl + 2:o + sl + 2 + al].decode("utf-8")
        return Coin(value, script, height, bool(cb), addr)


_K_COIN, _K_UNDO, _K_BEST, _K_LOADING = b"C", b"U", b"B", b"L"


def _ckey(txid: str, idx: int) -> bytes:
    return _K_COIN + txid.encode("utf-8") + b"\x00" + struct.pack(">I", idx)


def _ckey_parse(k: bytes) -> Tuple[str, int]:
    return k[1:-5].decode("utf-8"), struct.unpack(">I", k[-4:])[0]


def _ukey(height: int, h: str) -> bytes:
    return _K_UNDO + struct.pack(">Q", height) + h.encode("utf-8")


def _framed(k: bytes, v: bytes) -> bytes:
    return struct.pack(">H", len(k)) + k + struct.pack(">I", len(v)) + v


def _pb16(b: bytes) -> bytes:
    return struct.pack(">H", len(b)) + b


def _pb32(b: bytes) -> bytes:
    return struct.pack(">I", len(b)) + b


class PersistentUTXOSet:
    """
    Unspent outputs on disk, updated one block at a time in ONE atomic batch together with the undo
    record and the best-block pointer, so a crash can never leave coins and tip out of step.

    connect_block() enforces ledger integrity: tip continuity, spent coin must exist, no output
    overwrites an unspent one (BIP30), no double spend inside a block, optional coinbase maturity.
    (Value conservation / signatures stay with the consensus code of the host.)
    disconnect_block() reverses the tip block exactly from its undo record.
    """

    def __init__(self, backend: KVBackend, coinbase_maturity: int = 0, op_return: int = OP_RETURN_DEFAULT,
                 skip_unspendable: bool = True, cache_size: int = 100_000, genesis_height: int = 0):
        self.be = backend
        self.maturity = coinbase_maturity
        self.op_return = op_return
        self.skip_unspendable = skip_unspendable
        self.genesis_height = genesis_height
        self._cache: "collections.OrderedDict[bytes, Optional[Coin]]" = collections.OrderedDict()
        self._cache_size = cache_size
        self._lock = threading.RLock()
        self.recovered_partial_load = False
        if self.be.get(_K_LOADING) is not None:           # a snapshot load was interrupted
            log_G3.warning("interrupted snapshot load detected - clearing UTXO set")
            self.clear()
            self.recovered_partial_load = True

    # -- cache ---------------------------------------------------------------
    def _cache_put(self, k, coin):
        self._cache[k] = coin
        self._cache.move_to_end(k)
        while len(self._cache) > self._cache_size:
            self._cache.popitem(last=False)

    def _fetch(self, k: bytes) -> Optional[Coin]:
        if k in self._cache:
            self._cache.move_to_end(k)
            return self._cache[k]
        raw = self.be.get(k)
        coin = Coin.from_bytes(raw) if raw is not None else None
        self._cache_put(k, coin)
        return coin

    # -- reads ---------------------------------------------------------------
    def get_coin(self, txid: str, idx: int) -> Optional[Coin]:
        with self._lock:
            return self._fetch(_ckey(txid, idx))

    def have_coin(self, txid: str, idx: int) -> bool:
        return self.get_coin(txid, idx) is not None

    def best_block(self) -> Optional[Tuple[str, int]]:
        with self._lock:
            raw = self.be.get(_K_BEST)
        if raw is None:
            return None
        d = json.loads(raw.decode("utf-8"))
        return d["h"], d["n"]

    def iter_coins(self) -> Iterator[Tuple[str, int, Coin]]:
        for k, v in self.be.iter_prefix(_K_COIN):
            t, i = _ckey_parse(k)
            yield t, i, Coin.from_bytes(v)

    def stats(self) -> dict:
        with self._lock:
            n = total = 0
            for _, _, c in self.iter_coins():
                n += 1
                total += c.value
            return {"coins": n, "total_value": total, "best": self.best_block()}

    def compute_hash(self) -> str:
        """Deterministic hash of the whole set (order = key order). Same function snapshots use."""
        with self._lock:
            h = hashlib.sha256()
            for k, v in self.be.iter_prefix(_K_COIN):
                h.update(_framed(k, v))
            return h.hexdigest()

    # -- block connect / disconnect -----------------------------------------
    def connect_block(self, block_hash: str, prev_hash: Optional[str], height: int, txs) -> dict:
        with self._lock:
            best = self.best_block()
            if best is None:
                if height != self.genesis_height:
                    raise UTXOConsistencyError(f"first block must have height {self.genesis_height}, got {height}")
            elif prev_hash != best[0] or height != best[1] + 1:
                raise UTXOConsistencyError("block does not extend the UTXO tip")
            overlay: Dict[bytes, Optional[Coin]] = {}
            prior: List[Tuple[bytes, Coin]] = []
            spent = 0
            for txid, is_cb, ins, outs in txs:
                if not is_cb:
                    for itxid, idx in ins:
                        k = _ckey(itxid, idx)
                        coin = overlay[k] if k in overlay else self._fetch(k)
                        if coin is None:
                            raise UTXOConsistencyError(f"tx {txid} spends missing/spent output {itxid}:{idx}")
                        if self.maturity and coin.coinbase and height - coin.height < self.maturity:
                            raise UTXOConsistencyError(f"tx {txid} spends immature coinbase {itxid}:{idx}")
                        if k not in overlay:
                            prior.append((k, coin))
                        overlay[k] = None
                        spent += 1
                for n, (value, script, addr) in enumerate(outs):
                    if self.skip_unspendable and script[:1] == bytes([self.op_return]):
                        continue
                    k = _ckey(txid, n)
                    cur = overlay[k] if k in overlay else self._fetch(k)
                    if cur is not None:
                        raise UTXOConsistencyError(f"tx {txid} output {n} would overwrite an unspent output")
                    overlay[k] = Coin(value, script, height, bool(is_cb), addr)
            survivors = {k: c for k, c in overlay.items() if c is not None}
            undo = (_pb16((prev_hash or "").encode("utf-8")) + struct.pack(">I", len(prior))
                    + b"".join(_pb16(k) + _pb32(c.to_bytes()) for k, c in prior)
                    + struct.pack(">I", len(survivors)) + b"".join(_pb16(k) for k in survivors))
            puts = {k: c.to_bytes() for k, c in survivors.items()}
            puts[_ukey(height, block_hash)] = undo
            puts[_K_BEST] = json.dumps({"h": block_hash, "n": height}).encode("utf-8")
            self.be.write_batch(puts, [k for k, _ in prior])
            for k, _ in prior:
                self._cache.pop(k, None)
            for k, c in survivors.items():
                self._cache_put(k, c)
            return {"spent": spent, "created": len(survivors)}

    def disconnect_block(self, block_hash: str) -> dict:
        with self._lock:
            best = self.best_block()
            if best is None or best[0] != block_hash:
                raise UTXOConsistencyError("can only disconnect the current tip")
            height = best[1]
            raw = self.be.get(_ukey(height, block_hash))
            if raw is None:
                raise UTXOConsistencyError("undo data for tip is not available")
            o = 0
            (pl,) = struct.unpack_from(">H", raw, o)
            prev = raw[o + 2:o + 2 + pl].decode("utf-8")
            o += 2 + pl
            (np_,) = struct.unpack_from(">I", raw, o)
            o += 4
            restore: Dict[bytes, bytes] = {}
            for _ in range(np_):
                (kl,) = struct.unpack_from(">H", raw, o)
                k = raw[o + 2:o + 2 + kl]
                o += 2 + kl
                (vl,) = struct.unpack_from(">I", raw, o)
                restore[k] = raw[o + 4:o + 4 + vl]
                o += 4 + vl
            (nc,) = struct.unpack_from(">I", raw, o)
            o += 4
            created = []
            for _ in range(nc):
                (kl,) = struct.unpack_from(">H", raw, o)
                created.append(raw[o + 2:o + 2 + kl])
                o += 2 + kl
            deletes = created + [_ukey(height, block_hash)]
            if height - 1 < self.genesis_height:
                deletes.append(_K_BEST)
            else:
                restore[_K_BEST] = json.dumps({"h": prev, "n": height - 1}).encode("utf-8")
            self.be.write_batch(restore, deletes)
            for k in created:
                self._cache.pop(k, None)
            for k, v in restore.items():
                if k != _K_BEST:
                    self._cache_put(k, Coin.from_bytes(v))
            return {"restored": np_, "removed": nc}

    def prune_undo(self, below_height: int) -> int:
        """Drop undo records for blocks lower than `below_height` (they can no longer be reorged out)."""
        with self._lock:
            dead = []
            for k, _ in self.be.iter_prefix(_K_UNDO):
                if struct.unpack(">Q", k[1:9])[0] >= below_height:
                    break
                dead.append(k)
            if dead:
                self.be.write_batch({}, dead)
            return len(dead)

    # -- bulk (snapshot) ------------------------------------------------------
    def is_empty(self) -> bool:
        with self._lock:
            return self.best_block() is None and next(self.be.iter_prefix(_K_COIN), None) is None

    def clear(self):
        with self._lock:
            for p in (_K_COIN, _K_UNDO, _K_BEST, _K_LOADING):
                while True:
                    ks = [k for k, _ in zip((k for k, _ in self.be.iter_prefix(p)), range(5000))]
                    if not ks:
                        break
                    self.be.write_batch({}, ks)
            self._cache.clear()

    def bulk_begin(self):
        with self._lock:
            if not self.is_empty():
                raise SnapshotError("UTXO set must be empty before loading a snapshot")
            self.be.write_batch({_K_LOADING: b"1"}, [])

    def bulk_put(self, items: Dict[bytes, bytes]):
        with self._lock:
            self.be.write_batch(items, [])

    def bulk_finish(self, block_hash: str, height: int):
        with self._lock:
            self.be.write_batch({_K_BEST: json.dumps({"h": block_hash, "n": height}).encode("utf-8")}, [_K_LOADING])
            self._cache.clear()


# ==============================================================================
# 3. UTXOSnapshot
# ==============================================================================
@dataclass
class SnapshotHeader:
    version: int
    network: str
    height: int
    block_hash: str
    count: int
    utxo_hash: str


_SNAP_MAGIC = b"NBSN"
_SNAP_VERSION = 1


class UTXOSnapshot:
    """
    File = magic | ver | network | height | block hash | coin count | set hash | header-checksum
           body (txid, index, coin)* | sha256d(body)
    create() writes to a temp file, fsyncs, then renames (a half-written snapshot never has the real name).
    load() verifies the whole file (checksums AND recomputed set hash) before it touches the UTXO set, and
    verifies the set hash again afterwards; any failure leaves the UTXO set empty.
    `expected_hash` is the hard-coded trust anchor (assumeutxo style): a snapshot is only as trustworthy
    as the hash you ship in the node.
    """

    @staticmethod
    def _pack_header(h: SnapshotHeader) -> bytes:
        body = (_SNAP_MAGIC + struct.pack(">H", h.version) + _pb16(h.network.encode()) +
                struct.pack(">Q", h.height) + _pb16(h.block_hash.encode()) +
                struct.pack(">Q", h.count) + bytes.fromhex(h.utxo_hash))
        return body + _sha256d(body)[:4]

    @staticmethod
    def _read_header(f) -> SnapshotHeader:
        start = f.tell()
        try:
            if f.read(4) != _SNAP_MAGIC:
                raise SnapshotError("not a NEBULA snapshot")
            (ver,) = struct.unpack(">H", f.read(2))
            if ver != _SNAP_VERSION:
                raise SnapshotError(f"unsupported snapshot version {ver}")
            (nl,) = struct.unpack(">H", f.read(2))
            net = f.read(nl).decode()
            (height,) = struct.unpack(">Q", f.read(8))
            (bl,) = struct.unpack(">H", f.read(2))
            bh = f.read(bl).decode()
            (count,) = struct.unpack(">Q", f.read(8))
            uh = f.read(32)
            ck = f.read(4)
        except struct.error as e:
            raise SnapshotError("truncated snapshot header") from e
        end = f.tell()
        f.seek(start)
        raw = f.read(end - start - 4)
        f.read(4)                                         # leave the cursor after the checksum
        if len(uh) != 32 or _sha256d(raw)[:4] != ck:
            raise SnapshotError("snapshot header checksum mismatch")
        return SnapshotHeader(ver, net, height, bh, count, uh.hex())

    @staticmethod
    def create(utxo: PersistentUTXOSet, path: str, network: str = "nebula") -> SnapshotHeader:
        tmp = path + ".tmp"
        with utxo._lock:                                   # consistent view: no block may connect meanwhile
            best = utxo.best_block()
            if best is None:
                raise SnapshotError("UTXO set has no tip - nothing to snapshot")
            hdr = SnapshotHeader(_SNAP_VERSION, network, best[1], best[0], 0, "00" * 32)
            body_h, set_h, count = hashlib.sha256(), hashlib.sha256(), 0
            with open(tmp, "wb") as f:
                f.write(UTXOSnapshot._pack_header(hdr))
                for k, v in utxo.be.iter_prefix(_K_COIN):
                    t, i = _ckey_parse(k)
                    rec = _pb16(t.encode()) + struct.pack(">I", i) + _pb32(v)
                    f.write(rec)
                    body_h.update(rec)
                    set_h.update(_framed(k, v))
                    count += 1
                f.write(hashlib.sha256(body_h.digest()).digest())
                hdr.count, hdr.utxo_hash = count, set_h.hexdigest()
                f.seek(0)
                f.write(UTXOSnapshot._pack_header(hdr))
                f.flush()
                os.fsync(f.fileno())
        os.replace(tmp, path)
        _fsync_dir(os.path.dirname(os.path.abspath(path)))
        return hdr

    @staticmethod
    def _iter_records(f, header: SnapshotHeader, size: int):
        body_end = size - 32
        while f.tell() < body_end:
            (tl,) = struct.unpack(">H", f.read(2))
            t = f.read(tl).decode()
            (i,) = struct.unpack(">I", f.read(4))
            (vl,) = struct.unpack(">I", f.read(4))
            v = f.read(vl)
            if f.tell() > body_end or len(v) != vl:
                raise SnapshotError("snapshot body is truncated or corrupt")
            yield _ckey(t, i), v

    @staticmethod
    def verify(path: str, expected_hash: Optional[str] = None,
               expected_block: Optional[str] = None) -> SnapshotHeader:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            hdr = UTXOSnapshot._read_header(f)
            body_start = f.tell()
            if size < body_start + 32:
                raise SnapshotError("snapshot is truncated")
            body_h, set_h, n = hashlib.sha256(), hashlib.sha256(), 0
            try:
                for k, v in UTXOSnapshot._iter_records(f, hdr, size):
                    n += 1
                    set_h.update(_framed(k, v))
                f.seek(body_start)
                remaining = size - 32 - body_start
                while remaining:
                    chunk = f.read(min(1 << 20, remaining))
                    body_h.update(chunk)
                    remaining -= len(chunk)
                trailer = f.read(32)
            except (struct.error, UnicodeDecodeError) as e:
                raise SnapshotError("snapshot body is corrupt") from e
            if hashlib.sha256(body_h.digest()).digest() != trailer:
                raise SnapshotError("snapshot body checksum mismatch")
            if n != hdr.count:
                raise SnapshotError("snapshot coin count mismatch")
            if set_h.hexdigest() != hdr.utxo_hash:
                raise SnapshotError("snapshot UTXO hash mismatch")
        if expected_hash is not None and hdr.utxo_hash != expected_hash:
            raise SnapshotError("snapshot hash does not match the trusted hash")
        if expected_block is not None and hdr.block_hash != expected_block:
            raise SnapshotError("snapshot is for a different block than expected")
        return hdr

    @staticmethod
    def load(utxo: PersistentUTXOSet, path: str, expected_hash: Optional[str] = None,
             expected_block: Optional[str] = None, network: Optional[str] = None, batch: int = 5000) -> SnapshotHeader:
        hdr = UTXOSnapshot.verify(path, expected_hash, expected_block)
        if network is not None and hdr.network != network:
            raise SnapshotError(f"snapshot is for network '{hdr.network}', not '{network}'")
        size = os.path.getsize(path)
        utxo.bulk_begin()
        try:
            with open(path, "rb") as f:
                UTXOSnapshot._read_header(f)
                items: Dict[bytes, bytes] = {}
                for k, v in UTXOSnapshot._iter_records(f, hdr, size):
                    items[k] = v
                    if len(items) >= batch:
                        utxo.bulk_put(items)
                        items = {}
                if items:
                    utxo.bulk_put(items)
            utxo.bulk_finish(hdr.block_hash, hdr.height)
            if utxo.compute_hash() != hdr.utxo_hash:
                raise SnapshotError("UTXO set hash differs after load")
        except Exception:
            utxo.clear()
            raise
        return hdr


# ==============================================================================
# ChainDatabase - store + UTXO set + reorg engine (the class PruningManager and the wiring work with)
# ==============================================================================
class ChainDatabase_G3:
    def __init__(self, store: PersistentBlockStore, utxo: PersistentUTXOSet, ledger_fn=default_ledger,
                 access: Optional[BlockAccess] = None, better_fn: Optional[Callable[..., bool]] = None,
                 max_reorg_depth: Optional[int] = None):
        self.store, self.utxo = store, utxo
        self.ledger = ledger_fn
        self.acc = access or store.acc
        self.better = better_fn or (lambda c_hash, c_height, b_hash, b_height: c_height > b_height)
        self.max_reorg_depth = max_reorg_depth
        self._lock = threading.RLock()

    def best(self) -> Optional[Tuple[str, int]]:
        return self.utxo.best_block()

    def _connect(self, block):
        return self.utxo.connect_block(self.acc.hash(block), self.acc.prev(block), self.acc.height(block),
                                       self.ledger(block))

    def realign(self):
        """Re-derive the index's main-chain flags from the UTXO tip (the source of truth)."""
        b = self.utxo.best_block()
        if b is not None and self.store.has_block(b[0]):
            try:
                self.store.set_main_chain(b[0])
            except MissingParent:                        # chain starts at a snapshot base the store never saw
                log_G3.info("realign: chain below %s is not in the store (snapshot start)", b[0])

    def activate(self, target: str) -> dict:
        """Move the UTXO set + main chain to `target`, disconnecting/connecting blocks through undo data."""
        with self._lock:
            best = self.utxo.best_block()
            try:
                fork_h, down, up = self.store.plan_chain(target, anchor=best)
            except MissingParent as e:
                return {"status": "orphan", "missing": str(e)}
            except InvalidChain as e:
                return {"status": "invalid", "block": str(e)}
            if self.max_reorg_depth is not None and len(down) > self.max_reorg_depth:
                return {"status": "too-deep", "depth": len(down)}
            old_blocks, done_down, done_up = [], [], []
            phase = "disconnect"            # v10.16: who is to blame depends on the phase the error happened in
            try:
                for h in down:
                    old = self.store.get_block(h)               # needed only to roll back; may be pruned
                    self.utxo.disconnect_block(h)
                    done_down.append(h)
                    old_blocks.append(old)
                phase = "connect"
                for h in up:
                    blk = self.store.get_block(h)
                    if blk is None:
                        raise Group3Error(f"block {h} missing from store")
                    self._connect(blk)
                    done_up.append(h)
            except Exception as e:
                self._rollback(done_up, done_down)
                if isinstance(e, UTXOConsistencyError):
                    if phase == "connect":
                        # the NEW branch contains a block the ledger cannot accept: that block is bad
                        bad = up[len(done_up)]
                        n = self.store.mark_invalid(bad)
                        log_G3.warning("block %s rejected by UTXO set (%s); %d block(s) marked invalid", bad, e, n)
                        return {"status": "invalid", "block": bad, "reason": str(e)}
                    # the failure is in OUR OLD branch (e.g. undo data missing/damaged): the new branch
                    # is not at fault and must NOT be marked invalid. Nothing changed (rolled back).
                    stuck = down[len(done_down)] if len(done_down) < len(down) else None
                    log_G3.error("cannot reorg to %s: old-branch block %s cannot be disconnected (%s)",
                              target, stuck, e)
                    return {"status": "cannot-reorg", "block": stuck, "reason": str(e)}
                raise
            self.store.set_main_chain(target, anchor=best)
            return {"status": "reorg" if down else "connected", "fork_height": fork_h,
                    "disconnected": down, "connected": up}

    def _rollback(self, done_up: List[str], done_down: List[str]):
        for h in reversed(done_up):
            self.utxo.disconnect_block(h)
        for h in reversed(done_down):
            blk = self.store.get_block(h)
            if blk is None:
                raise Group3Error("rollback failed: old branch block unavailable")
            self._connect(blk)

    # statuses that mean "the host accepted this block but the chain database could not follow it"
    DIVERGED = ("invalid", "orphan", "too-deep", "cannot-reorg")

    def accept_block(self, block) -> dict:
        """Returns {"status": connected|reorg|side|duplicate|<one of DIVERGED>}.
        v10.16: a block that this database could NOT follow is reported (it used to come back as plain 'side',
        so a host/database divergence stayed completely silent)."""
        with self._lock:
            h = self.acc.hash(block)
            if not self.store.put_block(block):
                return {"status": "duplicate"}
            rejections: List[Tuple[str, dict]] = []
            res = self._activate_best(rejections)
            if res:
                return res
            for target, r in rejections:
                if target == h and r["status"] in self.DIVERGED:
                    return dict(r, target=h)
            info = self.store.info(h)
            if info is not None and info["invalid"]:
                return {"status": "invalid", "block": h, "target": h, "reason": "block flagged invalid"}
            return {"status": "side"}

    def _activate_best(self, rejections: Optional[List[Tuple[str, dict]]] = None) -> Optional[dict]:
        for h, ht in self.store.candidates():
            best = self.utxo.best_block()
            if best is not None and not self.better(h, ht, best[0], best[1]):
                return None
            if best is not None and h == best[0]:
                return None
            res = self.activate(h)
            if res["status"] in ("connected", "reorg"):
                return res
            if rejections is not None:
                rejections.append((h, res))
        return None

    def recover(self) -> dict:
        """Run once at start-up, before serving: repair flags after a crash and finish interrupted work."""
        with self._lock:
            self.realign()
            res = self._activate_best()
            return {"store": self.store.recovery, "resumed": res, "tip": self.utxo.best_block(),
                    "partial_snapshot_cleared": self.utxo.recovered_partial_load}


# ==============================================================================
# 4. PruningManager
# ==============================================================================
MIN_PRUNE_TARGET_BYTES = 550 * 1024 * 1024
MIN_BLOCKS_TO_KEEP = 288


class PruningManager:
    """
    Deletes the oldest whole block files once disk use exceeds the target.

    Safety rules: never touch the file being written; never prune a file holding any block within
    `min_keep` of the tip (that is the reorg window); pruned blocks stay in the index (headers/heights
    remain known) and raise BlockPrunedError on read; undo records older than the window are dropped too.
    """

    def __init__(self, db: ChainDatabase_G3, target_bytes: int = 0, min_keep: int = MIN_BLOCKS_TO_KEEP,
                 min_target_bytes: int = MIN_PRUNE_TARGET_BYTES):
        if target_bytes and target_bytes < min_target_bytes:
            raise Group3Error(f"prune target {target_bytes} is below the minimum {min_target_bytes}")
        self.db, self.target, self.min_keep = db, target_bytes, min_keep

    @property
    def enabled(self) -> bool:
        return self.target > 0

    def _tip_height(self) -> int:
        b = self.db.best()
        return b[1] if b else -1

    def prunable_files(self) -> List[int]:
        tip = self._tip_height()
        limit = tip - self.min_keep
        cur = self.db.store._cur_file
        return [f["n"] for f in self.db.store.file_stats()
                if not f["pruned"] and f["n"] != cur and f["max_height"] is not None and f["max_height"] <= limit]

    def prune_to_target(self) -> List[int]:
        if not self.enabled:
            return []
        pruned = []
        for n in self.prunable_files():
            if self.db.store.disk_usage() <= self.target:
                break
            self.db.store.prune_file(n)
            pruned.append(n)
        self.db.utxo.prune_undo(self._tip_height() - self.min_keep)
        return pruned

    def prune_to_height(self, height: int) -> List[int]:
        """Manual prune: every file whose blocks are all <= height (and still outside the reorg window)."""
        limit = min(height, self._tip_height() - self.min_keep)
        out = []
        for f in self.db.store.file_stats():
            if (not f["pruned"] and f["n"] != self.db.store._cur_file and f["max_height"] is not None
                    and f["max_height"] <= limit):
                self.db.store.prune_file(f["n"])
                out.append(f["n"])
        self.db.utxo.prune_undo(self._tip_height() - self.min_keep)
        return out

    def first_unpruned_height(self) -> Optional[int]:
        return self.db.store.first_unpruned_main_height()

    def stats(self) -> dict:
        return {"enabled": self.enabled, "target_bytes": self.target, "disk_usage": self.db.store.disk_usage(),
                "min_keep": self.min_keep, "first_unpruned_height": self.first_unpruned_height(),
                "pruned_files": sum(1 for f in self.db.store.file_stats() if f["pruned"])}


# ==============================================================================
# 5. VersionBitsStateMachine  (BIP9 - signalling only)
# ==============================================================================
class ThresholdState(enum.Enum):
    DEFINED = "defined"
    STARTED = "started"
    LOCKED_IN = "locked_in"
    ACTIVE = "active"
    FAILED = "failed"


ALWAYS_ACTIVE = -1
NEVER_ACTIVE = -2
TOP_BITS = 0x20000000
TOP_MASK = 0xE0000000


class HeaderInfo(NamedTuple):
    height: int
    hash: str
    version: int
    time: int


@dataclass(frozen=True)
class Deployment:
    name: str
    bit: int
    start_time: int
    timeout: int
    threshold: int = 1916           # 95 % of 2016
    period: int = 2016
    min_activation_height: int = 0


class VersionBitsStateMachine:
    """
    BIP9 state machine, evaluated per retarget period on the ACTIVE chain (header_fn(height)).
    It only reports state and computes the version a miner should signal; it never validates blocks,
    so it cannot split the chain. States are cached by boundary block hash, so reorgs are safe.
    """

    def __init__(self, deployments: Iterable[Deployment], header_fn: Callable[[int], Optional[HeaderInfo]],
                 cache_limit: int = 50_000):
        self._dep: Dict[str, Deployment] = {}
        bits = set()
        for d in deployments:
            if d.name in self._dep:
                raise ValueError(f"duplicate deployment {d.name}")
            if not 0 <= d.bit <= 28 or d.bit in bits:
                raise ValueError(f"deployment {d.name}: bit must be unique and in 0..28")
            if d.period < 1 or not 1 <= d.threshold <= d.period:
                raise ValueError(f"deployment {d.name}: threshold must be within 1..period")
            if d.start_time >= 0 and d.timeout <= d.start_time:
                raise ValueError(f"deployment {d.name}: timeout must be after start_time")
            self._dep[d.name] = d
            bits.add(d.bit)
        self._hdr = header_fn
        self._cache: "collections.OrderedDict[Tuple[str, str], ThresholdState]" = collections.OrderedDict()
        self._cache_limit = cache_limit
        self._lock = threading.RLock()

    # -- helpers -------------------------------------------------------------
    def _header(self, h: int) -> HeaderInfo:
        x = self._hdr(h)
        if x is None:
            raise Group3Error(f"no header at height {h}")
        return x

    def mtp(self, height: int) -> int:
        ts = sorted(self._header(h).time for h in range(max(0, height - 10), height + 1))
        return ts[len(ts) // 2]

    @staticmethod
    def signals(version: int, bit: int) -> bool:
        return (version & TOP_MASK) == TOP_BITS and bool((version >> bit) & 1)

    def _count(self, d: Deployment, first: int, last: int) -> int:
        return sum(1 for h in range(first, last + 1) if self.signals(self._header(h).version, d.bit))

    @staticmethod
    def _boundary(d: Deployment, prev_height: int) -> int:
        return prev_height - ((prev_height + 1) % d.period)

    def _after_boundary(self, d: Deployment, b: int) -> ThresholdState:
        """State of the period that begins right after boundary block b (b == -1: first period)."""
        if d.start_time == ALWAYS_ACTIVE:
            return ThresholdState.ACTIVE
        if d.start_time == NEVER_ACTIVE:
            return ThresholdState.FAILED
        todo, state = [], ThresholdState.DEFINED
        cur = b
        while True:
            if cur < 0:
                state = ThresholdState.DEFINED
                break
            key = (d.name, self._header(cur).hash)
            if key in self._cache:
                state = self._cache[key]
                break
            if self.mtp(cur) < d.start_time:
                state = ThresholdState.DEFINED
                self._remember(key, state)
                break
            todo.append(cur)
            cur -= d.period
        for cur in reversed(todo):
            nxt = state
            if state == ThresholdState.DEFINED:
                if self.mtp(cur) >= d.start_time:
                    nxt = ThresholdState.STARTED
            elif state == ThresholdState.STARTED:
                if self._count(d, cur - d.period + 1, cur) >= d.threshold:
                    nxt = ThresholdState.LOCKED_IN
                elif self.mtp(cur) >= d.timeout:
                    nxt = ThresholdState.FAILED
            elif state == ThresholdState.LOCKED_IN:
                if cur + 1 >= d.min_activation_height:
                    nxt = ThresholdState.ACTIVE
            state = nxt
            self._remember((d.name, self._header(cur).hash), state)
        return state

    def _remember(self, key, state):
        self._cache[key] = state
        while len(self._cache) > self._cache_limit:
            self._cache.popitem(last=False)

    # -- public API ----------------------------------------------------------
    def deployments(self) -> List[Deployment]:
        return list(self._dep.values())

    def state(self, name: str, prev_height: int) -> ThresholdState:
        """State that applies to the block AFTER prev_height."""
        d = self._dep[name]
        with self._lock:
            if prev_height < 0:
                return self._after_boundary(d, -1)
            return self._after_boundary(d, self._boundary(d, prev_height))

    def since_height(self, name: str, prev_height: int) -> int:
        d = self._dep[name]
        with self._lock:
            s = self.state(name, prev_height)
            if s == ThresholdState.DEFINED or d.start_time in (ALWAYS_ACTIVE, NEVER_ACTIVE):
                return 0
            lowest = self._boundary(d, prev_height)
            while lowest - d.period >= 0 and self._after_boundary(d, lowest - d.period) == s:
                lowest -= d.period
            return lowest + 1

    def statistics(self, name: str, prev_height: int) -> dict:
        d = self._dep[name]
        with self._lock:
            b = self._boundary(d, prev_height)
            elapsed = prev_height - b
            count = self._count(d, b + 1, prev_height) if elapsed > 0 else 0
            return {"period": d.period, "threshold": d.threshold, "elapsed": elapsed, "count": count,
                    "possible": (d.period - d.threshold) >= (elapsed - count)}

    def block_version(self, prev_height: int) -> int:
        """Version a miner should put in the block after prev_height."""
        v = TOP_BITS
        with self._lock:
            for d in self._dep.values():
                if self.state(d.name, prev_height) in (ThresholdState.STARTED, ThresholdState.LOCKED_IN):
                    v |= 1 << d.bit
        return v

    def info(self, prev_height: int) -> Dict[str, dict]:
        out = {}
        with self._lock:
            for d in self._dep.values():
                s = self.state(d.name, prev_height)
                out[d.name] = {"bit": d.bit, "state": s.value, "since": self.since_height(d.name, prev_height),
                               "start_time": d.start_time, "timeout": d.timeout,
                               "min_activation_height": d.min_activation_height,
                               "statistics": self.statistics(d.name, prev_height)
                               if s == ThresholdState.STARTED else None}
        return out

    def unknown_rules_warning(self, prev_height: int, window: int = 100, min_count: int = 51) -> Optional[str]:
        """Warn when most recent blocks signal a bit this node does not know (a softfork we lack)."""
        known = {d.bit for d in self._dep.values()}
        counts: Dict[int, int] = collections.Counter()
        with self._lock:
            for h in range(max(0, prev_height - window + 1), prev_height + 1):
                v = self._header(h).version
                if (v & TOP_MASK) != TOP_BITS:
                    continue
                for bit in range(29):
                    if (v >> bit) & 1 and bit not in known:
                        counts[bit] += 1
        bad = sorted(b for b, c in counts.items() if c >= min_count)
        if bad:
            return (f"Unknown new rules activated (versionbit(s) {', '.join(map(str, bad))}); "
                    f"this node may be outdated")
        return None


# ==============================================================================
# Wiring
# ==============================================================================
class Group3Wiring:
    """
        g3 = Group3Wiring.from_host(globals(), data_dir="./nebula_data", codec=<codec>, deployments=[...],
                                    header_fn=<height -> HeaderInfo>, prune_target_mb=0)
        report = g3.recover()                 # FIRST thing at start-up
        g3.attach_blockchain(chain)           # AFTER g1.attach_blockchain: wraps add_block
        # replay on restart : for blk in g3.store.iter_main_chain(): host.load(blk)
        # block template    : version = g3.block_version(prev_height)
        # RPC               : g3.create_snapshot(path) / g3.load_snapshot(path, expected_hash) /
        #                     g3.versionbits.info(h) / g3.stats()
        # shutdown          : g3.detach(); g3.close()
    """

    def __init__(self, data_dir: str, codec, network_id: str = "nebula", access: Optional[BlockAccess] = None,
                 ledger_fn=default_ledger, deployments: Iterable[Deployment] = (), header_fn=None,
                 backend: str = "sqlite", prune_target_bytes: int = 0, min_keep_blocks: int = MIN_BLOCKS_TO_KEEP,
                 min_prune_target_bytes: int = MIN_PRUNE_TARGET_BYTES, max_file_size: int = 128 * 1024 * 1024,
                 coinbase_maturity: int = 0, op_return: int = OP_RETURN_DEFAULT, better_fn=None,
                 max_reorg_depth: Optional[int] = None, strict: bool = False, fsync: bool = True,
                 genesis_height: int = 0, cache_size: int = 100_000):
        os.makedirs(data_dir, exist_ok=True)
        self.network_id, self.strict = network_id, strict
        self.store = PersistentBlockStore(os.path.join(data_dir, "blocks"), codec, access,
                                          max_file_size=max_file_size, fsync=fsync, genesis_height=genesis_height)
        if backend == "sqlite":
            be: KVBackend = SQLiteBackend_G3(os.path.join(data_dir, "chainstate.db"))
        elif backend == "leveldb":
            be = LevelDBBackend_G3(os.path.join(data_dir, "chainstate"))
        elif backend == "memory":
            be = MemoryBackend()
        else:
            raise ValueError("backend must be 'sqlite', 'leveldb' or 'memory'")
        self.utxo = PersistentUTXOSet(be, coinbase_maturity, op_return, True, cache_size, genesis_height)
        self.chaindb = ChainDatabase_G3(self.store, self.utxo, ledger_fn, self.store.acc, better_fn, max_reorg_depth)
        self.pruning = PruningManager(self.chaindb, prune_target_bytes, min_keep_blocks, min_prune_target_bytes)
        self.snapshots = UTXOSnapshot
        deployments = list(deployments)
        self.versionbits = VersionBitsStateMachine(deployments, header_fn) if (deployments and header_fn) else None
        self.errors: List[str] = []
        self.divergences = 0
        self._undo: List[Callable[[], None]] = []

    @classmethod
    def from_host(cls, host_globals: dict, **kw):
        g = host_globals
        kw.setdefault("op_return", g.get("OP_RETURN", OP_RETURN_DEFAULT))
        kw.setdefault("network_id", str(g.get("NETWORK_NAME", g.get("NETWORK", "nebula"))))
        if "codec" not in kw:
            blk = g.get("Block")
            if blk is not None and hasattr(blk, "from_dict") and hasattr(blk, "to_dict"):
                kw["codec"] = JSONBlockCodec(lambda b: b.to_dict(), blk.from_dict)
            else:
                raise Group3Error("pass codec=... (host Block has no to_dict()/from_dict())")
        return cls(**kw)

    @property
    def healthy(self) -> bool:
        return not self.errors

    def reset_errors(self) -> int:
        """Operator acknowledgement (e.g. after a resync). Returns how many errors were cleared."""
        n = len(self.errors)
        self.errors.clear()
        self.divergences = 0
        return n

    @staticmethod
    def _accepted(result) -> bool:
        if isinstance(result, tuple) and result:
            return bool(result[0])
        return True if result is None else bool(result)

    def recover(self) -> dict:
        return self.chaindb.recover()

    def on_block_accepted(self, block) -> Optional[dict]:
        try:
            res = self.chaindb.accept_block(block)
            if res.get("status") in ChainDatabase_G3.DIVERGED:
                # v10.16: the host accepted a block that the chain database cannot follow. Consensus is not
                # touched (we never reject), but this must NOT stay silent: g3.healthy -> False, and the
                # sync layer (g4) that reads the chain through g3 is now looking at a different chain.
                msg = (f"host/chaindb divergence: block {res.get('target')} status={res['status']}"
                       f" ({res.get('reason') or res.get('missing') or res.get('depth', '')})")
                log_G3.error(msg)
                self.errors.append(msg)
                self.divergences += 1
                if self.strict:
                    raise HostDivergence(msg)
            if self.pruning.enabled:
                self.pruning.prune_to_target()
            return res
        except HostDivergence:
            raise                                    # already recorded above
        except Exception as e:                       # never let persistence break consensus
            msg = f"persist failed: {type(e).__name__}: {e}"
            log_G3.error(msg)
            self.errors.append(msg)
            if self.strict:
                raise
            return None

    def attach_blockchain(self, chain):
        orig = chain.add_block

        def add_block(block, *a, **kw):
            res = orig(block, *a, **kw)
            if self._accepted(res):
                self.on_block_accepted(block)
            return res

        chain.add_block = add_block
        self._undo.append(lambda c=chain, o=orig: self._restore(c, "add_block", o))

    def block_version(self, prev_height: int) -> int:
        return self.versionbits.block_version(prev_height) if self.versionbits else TOP_BITS

    def create_snapshot(self, path: str) -> SnapshotHeader:
        return UTXOSnapshot.create(self.utxo, path, self.network_id)

    def load_snapshot(self, path: str, expected_hash: Optional[str] = None,
                      expected_block: Optional[str] = None) -> SnapshotHeader:
        return UTXOSnapshot.load(self.utxo, path, expected_hash, expected_block, self.network_id)

    def stats(self) -> dict:
        return {"healthy": self.healthy, "divergences": self.divergences, "errors": self.errors[-5:], "tip": self.utxo.best_block(),
                "blocks_stored": self.store.count(), "utxo": self.utxo.stats(), "pruning": self.pruning.stats(),
                "recovery": self.store.recovery}

    @staticmethod
    def _restore(obj, name, orig):
        if getattr(type(obj), name, None) is not None and getattr(orig, "__self__", None) is obj:
            try:
                delattr(obj, name)
                return
            except AttributeError:
                _NB_SWALLOW_LOG.warning("swallowed AttributeError in Group3Wiring._restore", exc_info=True)
        setattr(obj, name, orig)

    def detach(self):
        while self._undo:
            self._undo.pop()()

    def close(self):
        self.store.close()
        self.utxo.be.close()

