def run_all_tests(verbose: bool = True) -> TestResultAccumulator:
    print("\n" + "═"*50)
    print("  🧪 NEBULA BLOCKCHAIN TEST SUITE")
    print("═"*50)

    r = TestResultAccumulator()
    start = time.time()

    test_groups = [
        TestCrypto(),
        TestTransactions(),
        TestBlocks(),
        TestBlockchain(),
        TestWallet(),
        TestContracts(),
        TestNetwork(),
    ]

    for group in test_groups:
        try:
            group.run(r)
        except Exception as e:
            r.fail(type(group).__name__, f"Group crashed: {e}")
            if verbose:
                traceback.print_exc()

    elapsed = time.time() - start
    print(r.summary())
    print(f"  Time: {elapsed:.2f}s")

    if r.errors:
        print("\n  Failed tests:")
        for name, reason in r.errors:
            print(f"    ❌ {name}: {reason}")

    return r


