def write_server_setup(path: str = "./nebula_server_setup.sh"):
    """
    د NEBULA server د Ubuntu/Debian کې د نصب script لیکي.
    وروسته چلوئ: sudo bash nebula_server_setup.sh
    """
    with open(path, 'w', encoding='utf-8') as _f:
        _f.write(NEBULA_SERVER_SETUP_SH)
    import os as _os, stat as _stat
    _os.chmod(path, _stat.S_IRWXU | _stat.S_IRGRP | _stat.S_IXGRP | _stat.S_IROTH)
    print(f"  Written: {path}")
    print(f"  Run: sudo bash {path}")

def _nebula_main():
    import argparse
    ap = argparse.ArgumentParser(
        prog='python3 nebula_FINAL.py',
        description='NEBULA Blockchain - All modules in one file',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Commands:
  node           Start full P2P node  (add --peers host:port,... to connect to other nodes)
  node --mine    Start full node + miner
  wallet-new     Create new HD wallet
  wallet-restore Restore wallet from mnemonic
  balance ADDR   Check address balance
  info           Show chain info
  test           Run all 42 tests
  api            Start REST API on :8080
  demo           Quick demo
  genesis        Mine a genesis block for --bits 0x1d0fffff (choose launch difficulty)
  state          Show on-chain state (tokens/NFT/DEX/governance/staking) of --datadir
  install        Write nebula_server_setup.sh to disk
        """
    )
    ap.add_argument('command',  nargs='?', default='help')
    ap.add_argument('address',  nargs='?', default=None, help='Address for balance cmd')
    ap.add_argument('--mine',   action='store_true')
    ap.add_argument('--port',   type=int, default=8333)
    ap.add_argument('--addr',   type=str, default=None, help='Miner reward address')
    ap.add_argument('--threads',type=int, default=None)
    ap.add_argument('--datadir',type=str, default='./nebula_data')
    ap.add_argument('--bits',   type=str, default=None, help='genesis compact bits, e.g. 0x1d0fffff')
    ap.add_argument('--host',   type=str, default=_nbl_default_bind())
    ap.add_argument('--api-port',type=int, default=8080, dest='api_port')
    ap.add_argument('--peers',  type=str, default='', help='comma-separated peers to connect to: host:port,host:port')
    ap.add_argument('-v','--verbose', action='store_true')
    args = ap.parse_args()
    cmd  = args.command.lower()

    if cmd == 'install':
        write_server_setup()

    elif cmd == 'help':
        print(BANNER)
        ap.print_help()

    elif cmd == 'demo':
        run_demo()

    elif cmd == 'info':
        bc = NEBULABlockchain()
        for k, v in bc.chain_info().items():
            print(f'  {k:28}: {v}')

    elif cmd == 'wallet-new':
        w = NEBULAWallet.create_new()
        print(f'\n  Address : {w.first_address}')
        print(f'  Mnemonic: {w.mnemonic}')
        key = w.master.derive_path(NBL_BIP44_PATH + "/0/0")
        print(f'  WIF Key : {key.wif}')
        print(f'\n  WARNING: Write down your mnemonic - NEVER share it!')

    elif cmd == 'wallet-restore':
        phrase = input('Enter mnemonic (12 or 24 words): ').strip()
        pw     = input('BIP39 passphrase (blank if none): ').strip()
        w = NEBULAWallet.from_mnemonic(phrase, pw)
        print(f'  Restored: {w.first_address}')

    elif cmd == 'balance':
        addr = args.address or (sys.argv[2] if len(sys.argv) > 2 else None)
        if not addr:
            print('Usage: python3 nebula_FINAL.py balance <address>')
            return
        bc = NEBULABlockchain()
        info = bc.get_balance(addr)
        print(f'  Address : {info["address"]}')
        print(f'  Balance : {info["balance_nbl"]:.9f} NBL')
        print(f'  UTXOs   : {info["utxo_count"]}')

    elif cmd in ('node', 'mine'):
        node = NEBULAFullNode(
            data_dir      = args.datadir,
            port          = args.port,
            mine          = args.mine or cmd == 'mine',
            miner_address = args.addr,
            threads       = args.threads,
        )
        node.p2p.extra_peers = list(dict.fromkeys(list(node.p2p.extra_peers) + parse_peer_list(args.peers)))
        node.run_interactive()

    elif cmd == 'genesis':
        mine_genesis(int(getattr(args, 'bits', None) or hex(GENESIS_BITS), 16))

    elif cmd == 'state':
        _bc = NEBULABlockchain.load(args.datadir) or NEBULABlockchain()
        _sl = NEBULAStateLayer(_bc).attach()
        for k, v in _sl.stats().items():
            print(f'  {k:18}: {v}')
        for ev in _sl.events(10):
            print('  event', ev)
        for pr in _sl.check_invariants():
            print('  INVARIANT PROBLEM:', pr)

    elif cmd == 'test':
        print('Running NEBULA Test Suite...\n')
        # FIX: run_all_tests returns TestResult object, not a tuple
        r  = run_all_tests(verbose=args.verbose)
        p  = r.passed
        t  = r.passed + r.failed
        p2, t2, _ = run_extended_tests()
        total_p = p + p2
        total_t = t + t2
        pct = total_p / total_t * 100 if total_t else 0
        print(f'\n  Basic    : {p}/{t}')
        print(f'  Extended : {p2}/{t2}')
        print(f'  TOTAL    : {total_p}/{total_t}  ({pct:.1f}%)')

    elif cmd == 'api':
        server = NEBULAAPIServer(
            host    = args.host,
            port    = args.api_port,
            ws_port = args.api_port + 1,
        )
        server.print_routes()
        server.start()
        print(f'  API running: http://{args.host}:{args.api_port}')
        print('  Press Ctrl+C to stop\n')
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            server.stop()
            print('\n  Stopped.')

    else:
        print(f'  Unknown: {cmd}')
        ap.print_help()


# v10.9: the CLI entry point now lives at the very END of the file, so that every class
# (all 1,200+) is defined before `node` / `api` / `state` run. Before, it ran here with
# only ~80 classes defined.


# ================================================================
# MODULE 12  nebula_segwit.py  — SegWit + Taproot (BIP141/143/341/342)
# ================================================================
# SegWit v0: P2WPKH, P2WSH
# SegWit v1: P2TR (Taproot) with Schnorr signatures
# Full BIP143 sighash, witness serialization, script path spending
# ================================================================

import hashlib, struct, secrets, hmac as _hmac
from typing import List, Tuple, Optional, Dict

# ── SegWit constants ──────────────────────────────────────────────
SEGWIT_VERSION_0  = 0
SEGWIT_VERSION_1  = 1   # Taproot
WITNESS_SCALE     = 4   # witness bytes weigh 1/4
MAX_STANDARD_TX_WEIGHT = 400_000

# ── BIP141 witness program sizes ─────────────────────────────────
P2WPKH_SIZE  = 20   # hash160 of compressed pubkey
P2WSH_SIZE   = 32   # sha256 of witness script
P2TR_SIZE    = 32   # x-only pubkey (Taproot)

# ── Tagged hash (BIP340/341) ─────────────────────────────────────
def _tagged_hash(tag: str, data: bytes) -> bytes:
    """BIP340 tagged hash: SHA256(SHA256(tag) || SHA256(tag) || data)"""
    tag_hash = hashlib.sha256(tag.encode()).digest()
    return hashlib.sha256(tag_hash + tag_hash + data).digest()

# ── Schnorr signature (BIP340) ───────────────────────────────────
class Schnorr:
    """
    BIP340 Schnorr signatures on secp256k1.
    Used exclusively by Taproot (SegWit v1).
    Properties: linearity (key aggregation), provable security,
    batch verification, 64-byte compact format.
    """
    P  = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
    N  = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
    Gx = 0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798
    Gy = 0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8

    @classmethod
    def _point_add(cls, P1, P2):
        if P1 is None: return P2
        if P2 is None: return P1
        x1,y1 = P1; x2,y2 = P2
        if x1 == x2:
            if y1 != y2: return None
            m = (3*x1*x1) * pow(2*y1, cls.P-2, cls.P) % cls.P
        else:
            m = (y2-y1) * pow(x2-x1, cls.P-2, cls.P) % cls.P
        x3 = (m*m - x1 - x2) % cls.P
        y3 = (m*(x1-x3) - y1) % cls.P
        return x3, y3

    @classmethod
    def _point_mul(cls, k, P):
        R = None; Q = P
        while k:
            if k & 1: R = cls._point_add(R, Q)
            Q = cls._point_add(Q, Q); k >>= 1
        return R

    @classmethod
    def _G(cls): return cls.Gx, cls.Gy

    @classmethod
    def _lift_x(cls, x: int):
        """Lift x-coordinate to even-y point (BIP340)"""
        y_sq = (pow(x, 3, cls.P) + 7) % cls.P
        y    = pow(y_sq, (cls.P+1)//4, cls.P)
        if y*y % cls.P != y_sq: return None
        return (x, y if y % 2 == 0 else cls.P - y)

    @classmethod
    def xonly_pubkey(cls, privkey: int) -> bytes:
        """Return 32-byte x-only public key"""
        P = cls._point_mul(privkey, cls._G())
        return P[0].to_bytes(32, 'big')

    @classmethod
    def sign(cls, privkey: int, msg32: bytes, aux_rand: bytes = None) -> bytes:
        """
        BIP340 Schnorr sign.
        Returns 64-byte signature (R.x || s).
        """
        assert len(msg32) == 32
        if aux_rand is None:
            aux_rand = secrets.token_bytes(32)
        assert len(aux_rand) == 32

        # Negate privkey if public key y is odd
        P = cls._point_mul(privkey, cls._G())
        if P[1] % 2 != 0:
            privkey = cls.N - privkey

        # Deterministic nonce per BIP340
        t = privkey ^ int.from_bytes(_tagged_hash("BIP0340/aux", aux_rand), 'big')
        rand = _tagged_hash("BIP0340/nonce",
                            t.to_bytes(32,'big') + P[0].to_bytes(32,'big') + msg32)
        k0 = int.from_bytes(rand, 'big') % cls.N
        if k0 == 0: raise ValueError("k0 is zero — retry")

        R = cls._point_mul(k0, cls._G())
        k = k0 if R[1] % 2 == 0 else cls.N - k0

        e = int.from_bytes(
            _tagged_hash("BIP0340/challenge",
                         R[0].to_bytes(32,'big') +
                         P[0].to_bytes(32,'big') +
                         msg32), 'big') % cls.N

        s = (k + e * privkey) % cls.N
        sig = R[0].to_bytes(32,'big') + s.to_bytes(32,'big')
        assert cls.verify(P[0].to_bytes(32,'big'), msg32, sig), "Self-verify failed"
        return sig

    @classmethod
    def verify(cls, xonly_pub: bytes, msg32: bytes, sig64: bytes) -> bool:
        """BIP340 Schnorr verify. Returns True iff valid."""
        if len(sig64) != 64 or len(xonly_pub) != 32 or len(msg32) != 32:
            return False
        try:
            r   = int.from_bytes(sig64[:32], 'big')
            s   = int.from_bytes(sig64[32:], 'big')
            px  = int.from_bytes(xonly_pub, 'big')
            if r >= cls.P or s >= cls.N or px >= cls.P:
                return False
            P   = cls._lift_x(px)
            if P is None: return False
            e   = int.from_bytes(
                    _tagged_hash("BIP0340/challenge",
                                 r.to_bytes(32,'big') + xonly_pub + msg32),
                    'big') % cls.N
            R   = cls._point_add(cls._point_mul(s, cls._G()),
                                  cls._point_mul(cls.N - e, P))
            if R is None or R[1] % 2 != 0 or R[0] != r:
                return False
            return True
        except Exception:
            return False

    @classmethod
    def batch_verify(cls, items: List[Tuple[bytes,bytes,bytes]]) -> bool:
        """
        Batch verify multiple (xonly_pub, msg32, sig64) tuples.
        More efficient than individual verify for block validation.
        Returns True only if ALL signatures are valid.
        """
        for xonly_pub, msg32, sig64 in items:
            if not cls.verify(xonly_pub, msg32, sig64):
                return False
        return True

# ── SegWit Script Types ───────────────────────────────────────────
class SegWitScript:
    """
    SegWit v0 and v1 (Taproot) script creation and parsing.
    P2WPKH: OP_0 <20-byte-hash>
    P2WSH:  OP_0 <32-byte-hash>
    P2TR:   OP_1 <32-byte-x-only-pubkey>
    """

    @staticmethod
    def p2wpkh(pubkey_bytes: bytes) -> bytes:
        """P2WPKH locking script: OP_0 <hash160(pubkey)>"""
        h = hashlib.new('ripemd160', hashlib.sha256(pubkey_bytes).digest()).digest()
        return bytes([0x00, 0x14]) + h   # OP_0 PUSH20

    @staticmethod
    def p2wsh(witness_script: bytes) -> bytes:
        """P2WSH locking script: OP_0 <sha256(witness_script)>"""
        h = hashlib.sha256(witness_script).digest()
        return bytes([0x00, 0x20]) + h   # OP_0 PUSH32

    @staticmethod
    def p2tr(xonly_pubkey: bytes) -> bytes:
        """P2TR locking script: OP_1 <32-byte-x-only-pubkey>"""
        assert len(xonly_pubkey) == 32
        return bytes([0x51, 0x20]) + xonly_pubkey   # OP_1 PUSH32

    @staticmethod
    def p2tr_from_privkey(privkey: int) -> Tuple[bytes, bytes]:
        """
        Derive Taproot output key and P2TR script from private key.
        Returns (xonly_pubkey, p2tr_script).
        Uses keypath-only spend (no script tree).
        """
        xonly = Schnorr.xonly_pubkey(privkey)
        # Tweak key with empty script tree hash (keypath only)
        tweak = _tagged_hash("TapTweak", xonly)
        t     = int.from_bytes(tweak, 'big')
        P     = Schnorr._point_mul(privkey, Schnorr._G())
        # If P.y is odd, negate privkey
        sk    = privkey if P[1] % 2 == 0 else Schnorr.N - privkey
        tweaked = (sk + t) % Schnorr.N
        xonly_out = Schnorr.xonly_pubkey(tweaked)
        return xonly_out, SegWitScript.p2tr(xonly_out)

    @staticmethod
    def p2wpkh_address(pubkey_bytes: bytes, hrp: str = "nbl") -> str:
        """Bech32 P2WPKH address"""
        h160 = hashlib.new('ripemd160', hashlib.sha256(pubkey_bytes).digest()).digest()
        return Bech32.encode(hrp, 0, h160)

    @staticmethod
    def p2tr_address(xonly_pubkey: bytes, hrp: str = "nbl") -> str:
        """Bech32m P2TR address"""
        return Bech32.encode(hrp, 1, xonly_pubkey)

    @staticmethod
    def classify(script: bytes) -> str:
        """Classify a SegWit script type"""
        if len(script) == 22 and script[0] == 0x00 and script[1] == 0x14:
            return "P2WPKH"
        if len(script) == 34 and script[0] == 0x00 and script[1] == 0x20:
            return "P2WSH"
        if len(script) == 34 and script[0] == 0x51 and script[1] == 0x20:
            return "P2TR"
        return "UNKNOWN"

# ── Bech32 / Bech32m ─────────────────────────────────────────────
class Bech32:
    """
    BIP173 Bech32 (SegWit v0) and BIP350 Bech32m (SegWit v1+) encoding.
    Produces native SegWit addresses: nbl1q... (P2WPKH/P2WSH)
                                      nbl1p... (P2TR)
    """
    CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
    BECH32M_CONST = 0x2bc830a3

    @classmethod
    def _polymod(cls, values):
        GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
        chk = 1
        for v in values:
            b = chk >> 25
            chk = (chk & 0x1ffffff) << 5 ^ v
            for i in range(5):
                chk ^= GEN[i] if ((b >> i) & 1) else 0
        return chk

    @classmethod
    def _hrp_expand(cls, hrp):
        return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

    @classmethod
    def _verify_checksum(cls, hrp, data):
        const = cls.BECH32M_CONST if data[0] == 1 else 1
        return cls._polymod(cls._hrp_expand(hrp) + list(data)) == const

    @classmethod
    def _create_checksum(cls, hrp, data, spec):
        values = cls._hrp_expand(hrp) + list(data)
        const  = cls.BECH32M_CONST if spec == "bech32m" else 1
        polymod = cls._polymod(values + [0,0,0,0,0,0]) ^ const
        return [(polymod >> 5*(5-i)) & 31 for i in range(6)]

    @classmethod
    def _convertbits(cls, data, frombits, tobits, pad=True):
        acc = 0; bits = 0; ret = []
        maxv = (1 << tobits) - 1
        for value in data:
            acc = ((acc << frombits) | value)
            bits += frombits
            while bits >= tobits:
                bits -= tobits
                ret.append((acc >> bits) & maxv)
        if pad:
            if bits: ret.append((acc << (tobits-bits)) & maxv)
        elif bits >= frombits or ((acc << (tobits-bits)) & maxv):
            return None
        return ret

    @classmethod
    def encode(cls, hrp: str, witver: int, witprog: bytes) -> str:
        """Encode witness program as bech32/bech32m address"""
        spec = "bech32m" if witver > 0 else "bech32"
        data = [witver] + cls._convertbits(witprog, 8, 5)
        checksum = cls._create_checksum(hrp, data, spec)
        return hrp + '1' + ''.join([cls.CHARSET[d] for d in data + checksum])

    @classmethod
    def decode(cls, hrp: str, addr: str) -> Tuple[Optional[int], Optional[bytes]]:
        """Decode bech32/bech32m address. Returns (witver, witprog) or (None,None)"""
        try:
            if addr.lower() != addr and addr.upper() != addr:
                return None, None
            addr = addr.lower()
            if not addr.startswith(hrp + '1'):
                return None, None
            data = [cls.CHARSET.find(c) for c in addr[len(hrp)+1:]]
            if any(d == -1 for d in data) or len(data) < 8:
                return None, None
            witver = data[0]
            witprog = cls._convertbits(data[1:-6], 5, 8, False)
            if witprog is None or len(witprog) < 2 or len(witprog) > 40:
                return None, None
            if witver == 0 and len(witprog) not in (20, 32):
                return None, None
            if witver > 0 and len(witprog) != 32:
                return None, None
            return witver, bytes(witprog)
        except Exception:
            return None, None

# ── BIP143 Sighash (SegWit v0) ────────────────────────────────────
class SighashSegWitV0:
    """
    BIP143 transaction digest for SegWit v0 inputs.
    Fixes quadratic sighash problem from legacy Bitcoin.
    Signs: version, hashPrevouts, hashSequence, outpoint,
           scriptCode, value, sequence, hashOutputs, locktime, sighash_type
    """

    @staticmethod
    def compute(tx, input_index: int, script_code: bytes,
                value: int, sighash_type: int = 1) -> bytes:
        """
        Compute BIP143 sighash for a single SegWit v0 input.
        tx: Transaction object
        script_code: for P2WPKH = P2PKH script; for P2WSH = witness script
        value: input value in satoshis/neb
        """
        def dsha(b): return hashlib.sha256(hashlib.sha256(b).digest()).digest()

        # hashPrevouts
        po_buf = b''.join(bytes.fromhex(i.outpoint.txid)[::-1] +
                          struct.pack('<I', i.outpoint.index)
                          for i in tx.inputs)
        hash_prevouts = dsha(po_buf)

        # hashSequence
        seq_buf = b''.join(struct.pack('<I', i.sequence) for i in tx.inputs)
        hash_sequence = dsha(seq_buf)

        # hashOutputs
        def _ser_out(o):
            spk = o.script_pubkey
            return struct.pack('<q', o.value) + _varint(len(spk)) + spk
        out_buf = b''.join(_ser_out(o) for o in tx.outputs)
        hash_outputs = dsha(out_buf)

        def _varint(n):
            if n < 0xfd:   return bytes([n])
            elif n <= 0xffff: return b'\xfd' + struct.pack('<H', n)
            else:             return b'\xfe' + struct.pack('<I', n)

        inp = tx.inputs[input_index]
        preimage = (
            struct.pack('<i', tx.version) +
            hash_prevouts +
            hash_sequence +
            bytes.fromhex(inp.outpoint.txid)[::-1] +
            struct.pack('<I', inp.outpoint.index) +
            _varint(len(script_code)) + script_code +
            struct.pack('<q', value) +
            struct.pack('<I', inp.sequence) +
            hash_outputs +
            struct.pack('<I', tx.locktime) +
            struct.pack('<I', sighash_type)
        )
        return dsha(preimage)

