def _encode_varint_sw(n: int) -> bytes:
    if n < 0xfd:   return bytes([n])
    elif n <= 0xffff: return b'\xfd' + struct.pack('<H', n)
    else:             return b'\xfe' + struct.pack('<I', n)

def _decode_varint_sw(data: bytes, offset: int) -> Tuple[int, int]:
    v = data[offset]
    if v < 0xfd:   return v, offset+1
    elif v == 0xfd: return struct.unpack_from('<H', data, offset+1)[0], offset+3
    else:           return struct.unpack_from('<I', data, offset+1)[0], offset+5

