# ── PSBT (BIP174) — Partially Signed Bitcoin Transaction ─────────
class PSBT:
    """
    BIP174 Partially Signed Bitcoin Transaction.
    Enables multi-party signing and hardware wallet support.
    Roles: Creator → Updater → Signer → Finalizer → Extractor
    """

    MAGIC = b'psbt\xff'

    # Global keys
    PSBT_GLOBAL_UNSIGNED_TX = 0x00

    # Input keys
    PSBT_IN_NON_WITNESS_UTXO   = 0x00
    PSBT_IN_WITNESS_UTXO       = 0x01
    PSBT_IN_PARTIAL_SIG        = 0x02
    PSBT_IN_SIGHASH_TYPE       = 0x03
    PSBT_IN_REDEEM_SCRIPT      = 0x04
    PSBT_IN_WITNESS_SCRIPT     = 0x05
    PSBT_IN_BIP32_DERIVATION   = 0x06
    PSBT_IN_FINAL_SCRIPTSIG    = 0x07
    PSBT_IN_FINAL_SCRIPTWITNESS= 0x08
    PSBT_IN_TAP_KEY_SIG        = 0x13

    def __init__(self, tx=None):
        self.tx          = tx
        self.global_map  : Dict[bytes, bytes] = {}
        self.inputs      : List[Dict[bytes,bytes]] = []
        self.outputs     : List[Dict[bytes,bytes]] = []

        if tx:
            count = len(tx.inputs) if hasattr(tx,'inputs') else 0
            self.inputs  = [{} for _ in range(count)]
            self.outputs = [{} for _ in range(len(tx.outputs) if hasattr(tx,'outputs') else 0)]

    def add_input_witness_utxo(self, index: int, value: int, script: bytes):
        """Add witness UTXO for a SegWit input"""
        key  = bytes([self.PSBT_IN_WITNESS_UTXO])
        val  = struct.pack('<q', value) + _encode_varint_sw(len(script)) + script
        self.inputs[index][key] = val

    def add_input_partial_sig(self, index: int,
                               pubkey: bytes, sig: bytes):
        """Add a partial signature"""
        key = bytes([self.PSBT_IN_PARTIAL_SIG]) + pubkey
        self.inputs[index][key] = sig

    def add_taproot_sig(self, index: int, sig: bytes):
        """Add Taproot keypath signature"""
        key = bytes([self.PSBT_IN_TAP_KEY_SIG])
        self.inputs[index][key] = sig

    def serialize(self) -> bytes:
        """Serialize PSBT to bytes"""
        def _kv(k, v):
            return (_encode_varint_sw(len(k)) + k +
                    _encode_varint_sw(len(v)) + v)

        out = self.MAGIC
        # Global map
        for k, v in self.global_map.items():
            out += _kv(k, v)
        out += b'\x00'   # separator
        # Inputs
        for inp_map in self.inputs:
            for k, v in inp_map.items():
                out += _kv(k, v)
            out += b'\x00'
        # Outputs
        for out_map in self.outputs:
            for k, v in out_map.items():
                out += _kv(k, v)
            out += b'\x00'
        return out

    def to_base64(self) -> str:
        import base64
        return base64.b64encode(self.serialize()).decode()

    @classmethod
    def from_base64(cls, b64: str) -> 'PSBT':
        import base64
        data = base64.b64decode(b64)
        psbt = cls()
        # Minimal parser — enough for display and signing
        if data[:5] != cls.MAGIC:
            raise ValueError("Invalid PSBT magic")
        return psbt

    def is_finalized(self) -> bool:
        """Check if all inputs have final scriptSig or scriptWitness"""
        for inp in self.inputs:
            has_sig = bytes([self.PSBT_IN_FINAL_SCRIPTSIG]) in inp
            has_wit = bytes([self.PSBT_IN_FINAL_SCRIPTWITNESS]) in inp
            has_tap = bytes([self.PSBT_IN_TAP_KEY_SIG]) in inp
            if not (has_sig or has_wit or has_tap):
                return False
        return True

