# ── Tapscript (BIP342) ────────────────────────────────────────────
class TapLeaf:
    """A single leaf in a Taproot script tree (BIP341/342)"""
    TAPSCRIPT_LEAF_VERSION = 0xC0

    def __init__(self, script: bytes, leaf_version: int = TAPSCRIPT_LEAF_VERSION):
        self.script       = script
        self.leaf_version = leaf_version

    def hash(self) -> bytes:
        """TapLeaf hash"""
        data = bytes([self.leaf_version]) + _encode_varint_sw(len(self.script)) + self.script
        return _tagged_hash("TapLeaf", data)

class TapBranch:
    """Internal node in a Taproot script tree"""
    def __init__(self, left, right):
        self.left  = left
        self.right = right

    def hash(self) -> bytes:
        lh = self.left.hash()
        rh = self.right.hash()
        # Sort lexicographically per BIP341
        if lh > rh: lh, rh = rh, lh
        return _tagged_hash("TapBranch", lh + rh)

