# ── BOLT Constants ────────────────────────────────────────────────
DUST_LIMIT_SAT          = 546
MAX_HTLC_VALUE_SAT      = 21_000_000 * 10**9
MAX_ACCEPTED_HTLCS      = 483
CLTV_EXPIRY_DELTA       = 40        # blocks
MIN_CLTV_EXPIRY         = 9
MAX_CLTV_EXPIRY         = 500
FEERATE_PER_KW          = 253       # satoshis per 1000 weight units
CHANNEL_RESERVE_PERCENT = 0.01      # 1% of channel capacity
HTLC_TIMEOUT_WEIGHT     = 663
HTLC_SUCCESS_WEIGHT     = 703
OFFERED_HTLC_WEIGHT     = 172
RECEIVED_HTLC_WEIGHT    = 173

# ── Channel States ────────────────────────────────────────────────
class ChannelState(Enum):
    OPENING          = "opening"
    FUNDED           = "funded"
    NORMAL           = "normal"
    LOCAL_SHUTDOWN   = "local_shutdown"
    REMOTE_SHUTDOWN  = "remote_shutdown"
    CLOSING          = "closing"
    CLOSED           = "closed"
    FORCE_CLOSED     = "force_closed"
    WAITING_LOCKIN   = "waiting_lockin"

class HTLCState(Enum):
    OFFERED          = "offered"
    RECEIVED         = "received"
    SETTLED          = "settled"
    FAILED           = "failed"
    PENDING_REMOVE   = "pending_remove"

# ── Payment Hash / Preimage ───────────────────────────────────────
def generate_payment_preimage() -> bytes:
    """Generate cryptographically random 32-byte payment preimage"""
    return secrets.token_bytes(32)

def payment_hash(preimage: bytes) -> bytes:
    """SHA256 of preimage = payment hash (R-hash)"""
    return hashlib.sha256(preimage).digest()

def verify_preimage(preimage: bytes, phash: bytes) -> bool:
    """Verify SHA256(preimage) == payment_hash"""
    return hashlib.sha256(preimage).digest() == phash

# ── HTLC ──────────────────────────────────────────────────────────
@dataclass
class HTLC:
    """
    Hash Time-Locked Contract.
    Core primitive of Lightning Network payment channels.
    Enables trustless routing: payment only released when preimage revealed.
    """
    htlc_id      : int
    amount_msat  : int            # millisatoshis
    payment_hash : bytes          # 32 bytes
    cltv_expiry  : int            # absolute block height
    state        : HTLCState = HTLCState.OFFERED
    preimage     : Optional[bytes] = None
    routing_info : bytes = b''    # onion blob

    @property
    def amount_sat(self) -> float:
        return self.amount_msat / 1000

    @property
    def amount_nbl(self) -> float:
        return self.amount_msat / 1000 / 10**DECIMALS

    def settle(self, preimage: bytes) -> bool:
        """Settle HTLC by revealing preimage"""
        if not verify_preimage(preimage, self.payment_hash):
            return False
        self.preimage = preimage
        self.state    = HTLCState.SETTLED
        return True

    def fail(self):
        """Fail the HTLC (timeout or route failure)"""
        self.state = HTLCState.FAILED

    def is_expired(self, current_height: int) -> bool:
        return current_height >= self.cltv_expiry

    def to_dict(self) -> dict:
        return {
            "htlc_id"       : self.htlc_id,
            "amount_msat"   : self.amount_msat,
            "amount_nbl"    : f"{self.amount_nbl:.9f}",
            "payment_hash"  : self.payment_hash.hex(),
            "cltv_expiry"   : self.cltv_expiry,
            "state"         : self.state.value,
            "settled"       : self.state == HTLCState.SETTLED,
        }

# ── Channel Keys ─────────────────────────────────────────────────
@dataclass
class ChannelKeys:
    """
    Per-channel key material (BOLT #3).
    Derived from channel seed for deterministic recovery.
    """
    funding_key        : int    # privkey for 2-of-2 multisig funding output
    revocation_basepoint: int   # for revocation keys
    payment_basepoint  : int    # for payment keys
    delayed_basepoint  : int    # for delayed outputs
    htlc_basepoint     : int    # for HTLC keys

    @classmethod
    def from_seed(cls, seed: bytes) -> 'ChannelKeys':
        """Derive all channel keys from a 32-byte seed"""
        def _key(seed, index):
            return int.from_bytes(
                hashlib.sha256(seed + index.to_bytes(4,'big')).digest(), 'big'
            ) % Secp256k1.N
        return cls(
            funding_key         = _key(seed, 0),
            revocation_basepoint= _key(seed, 1),
            payment_basepoint   = _key(seed, 2),
            delayed_basepoint   = _key(seed, 3),
            htlc_basepoint      = _key(seed, 4),
        )

    def pubkey(self, privkey: int) -> bytes:
        return Secp256k1.pubkey_to_bytes(
            Secp256k1.point_mul(privkey, Secp256k1.G()))

    @property
    def funding_pubkey(self) -> bytes:
        return self.pubkey(self.funding_key)

    @property
    def payment_pubkey(self) -> bytes:
        return self.pubkey(self.payment_basepoint)

# ── Commitment Transaction Builder ───────────────────────────────
class CommitmentTxBuilder:
    """
    BOLT #3 Commitment Transaction.
    Encodes the current channel balance + HTLCs as a Bitcoin/NEBULA tx.
    Can be broadcast to chain if channel closes unilaterally.
    """

    def __init__(self,
                 local_keys   : ChannelKeys,
                 remote_keys  : ChannelKeys,
                 local_dust   : int = DUST_LIMIT_SAT,
                 feerate_kw   : int = FEERATE_PER_KW):
        self.local_keys  = local_keys
        self.remote_keys = remote_keys
        self.local_dust  = local_dust
        self.feerate_kw  = feerate_kw

    def build(self,
              funding_txid  : str,
              funding_vout  : int,
              local_msats   : int,
              remote_msats  : int,
              htlcs         : List[HTLC],
              commitment_number: int,
              local_to_self_delay: int = 144) -> dict:
        """
        Build commitment transaction dict (simplified BOLT #3).
        Returns serializable representation with all outputs.
        """
        fee_msat     = self._fee(htlcs) * 1000
        local_out    = max(0, local_msats - fee_msat)
        remote_out   = remote_msats

        outputs = []

        # Local output (with CSV delay)
        if local_out >= self.local_dust * 1000:
            local_pk = self.local_keys.payment_pubkey
            outputs.append({
                "type"  : "to_local",
                "value" : local_out // 1000,
                "delay" : local_to_self_delay,
                "pubkey": local_pk.hex(),
            })

        # Remote output (immediately spendable by remote)
        if remote_out >= self.local_dust * 1000:
            remote_pk = self.remote_keys.payment_pubkey
            outputs.append({
                "type"  : "to_remote",
                "value" : remote_out // 1000,
                "pubkey": remote_pk.hex(),
            })

        # HTLC outputs
        for htlc in htlcs:
            if htlc.state not in (HTLCState.OFFERED, HTLCState.RECEIVED):
                continue
            if htlc.amount_msat < self.local_dust * 1000:
                continue
            outputs.append({
                "type"        : f"htlc_{htlc.state.value}",
                "value"       : htlc.amount_msat // 1000,
                "payment_hash": htlc.payment_hash.hex(),
                "cltv_expiry" : htlc.cltv_expiry,
                "htlc_id"     : htlc.htlc_id,
            })

        return {
            "version"          : 2,
            "funding_txid"     : funding_txid,
            "funding_vout"     : funding_vout,
            "commitment_number": commitment_number,
            "local_msats"      : local_msats,
            "remote_msats"     : remote_msats,
            "fee_sat"          : fee_msat // 1000,
            "outputs"          : outputs,
            "htlc_count"       : len(htlcs),
        }

    def _fee(self, htlcs: List[HTLC]) -> int:
        """Estimate commitment tx fee in satoshis (BOLT #3 fee formula)"""
        num_htlcs  = len([h for h in htlcs
                          if h.state in (HTLCState.OFFERED, HTLCState.RECEIVED)])
        weight     = (724 +
                      num_htlcs * (OFFERED_HTLC_WEIGHT + RECEIVED_HTLC_WEIGHT))
        return (weight * self.feerate_kw + 999) // 1000

# ── Payment Channel ───────────────────────────────────────────────
class PaymentChannel:
    """
    BOLT #2 Payment Channel.
    Full lifecycle: open → normal → close.
    Manages commitment transactions and HTLC state machine.
    """

    def __init__(self,
                 channel_id       : bytes,
                 local_node_id    : bytes,
                 remote_node_id   : bytes,
                 local_keys       : ChannelKeys,
                 remote_keys      : ChannelKeys,
                 capacity_sat     : int,
                 local_reserve_sat: int = None,
                 is_initiator     : bool = True):

        self.channel_id        = channel_id
        self.local_node_id     = local_node_id
        self.remote_node_id    = remote_node_id
        self.local_keys        = local_keys
        self.remote_keys       = remote_keys
        self.capacity_sat      = capacity_sat
        self.local_reserve_sat = local_reserve_sat or int(capacity_sat * CHANNEL_RESERVE_PERCENT)
        self.is_initiator      = is_initiator

        self.state             = ChannelState.OPENING
        self.local_msats       = (capacity_sat * 1000) if is_initiator else 0
        self.remote_msats      = 0 if is_initiator else (capacity_sat * 1000)

        self.local_htlc_id     = 0
        self.htlcs             : Dict[int, HTLC] = {}
        self.commitment_number = 0
        self.funding_txid      : Optional[str] = None
        self.funding_vout      : int = 0

        self._lock             = threading.RLock()
        self._commit_builder   = CommitmentTxBuilder(local_keys, remote_keys)

        self.created_at        = time.time()
        self.last_updated      = time.time()

    # ── Channel Open ─────────────────────────────────────────────
    def on_funding_confirmed(self, txid: str, vout: int):
        """Called when funding transaction is confirmed on-chain"""
        with self._lock:
            self.funding_txid = txid
            self.funding_vout = vout
            self.state        = ChannelState.NORMAL
            self.last_updated = time.time()

    # ── Send HTLC ────────────────────────────────────────────────
    def offer_htlc(self, amount_msat: int,
                   phash: bytes,
                   cltv_expiry: int,
                   routing_info: bytes = b'') -> Tuple[bool, str, Optional[HTLC]]:
        """
        Offer a new HTLC on this channel (local → remote).
        Returns (success, reason, htlc).
        """
        with self._lock:
            if self.state != ChannelState.NORMAL:
                return False, f"Channel not active: {self.state.value}", None

            if amount_msat <= 0:
                return False, "Amount must be positive", None

            if amount_msat > MAX_HTLC_VALUE_SAT:
                return False, "Amount exceeds max HTLC value", None

            active_htlcs = [h for h in self.htlcs.values()
                            if h.state in (HTLCState.OFFERED, HTLCState.RECEIVED)]
            if len(active_htlcs) >= MAX_ACCEPTED_HTLCS:
                return False, "Too many pending HTLCs", None

            # Check local balance
            pending_out = sum(h.amount_msat for h in active_htlcs
                              if h.state == HTLCState.OFFERED)
            available = self.local_msats - pending_out - self.local_reserve_sat * 1000
            if amount_msat > available:
                return False, f"Insufficient balance: need {amount_msat}, have {available}", None

            htlc = HTLC(
                htlc_id      = self.local_htlc_id,
                amount_msat  = amount_msat,
                payment_hash = phash,
                cltv_expiry  = cltv_expiry,
                state        = HTLCState.OFFERED,
                routing_info = routing_info,
            )
            self.htlcs[self.local_htlc_id] = htlc
            self.local_htlc_id += 1
            self.last_updated   = time.time()
            return True, "HTLC offered", htlc

    def receive_htlc(self, htlc_id: int, amount_msat: int,
                     phash: bytes, cltv_expiry: int) -> Tuple[bool, str]:
        """Receive an HTLC from remote node"""
        with self._lock:
            if self.state != ChannelState.NORMAL:
                return False, "Channel not active"
            htlc = HTLC(
                htlc_id      = htlc_id,
                amount_msat  = amount_msat,
                payment_hash = phash,
                cltv_expiry  = cltv_expiry,
                state        = HTLCState.RECEIVED,
            )
            self.htlcs[htlc_id] = htlc
            self.last_updated   = time.time()
            return True, "HTLC received"

    # ── Settle / Fail HTLC ───────────────────────────────────────
    def settle_htlc(self, htlc_id: int, preimage: bytes) -> Tuple[bool, str]:
        """
        Settle an HTLC by revealing the payment preimage.
        Updates channel balances atomically.
        """
        with self._lock:
            htlc = self.htlcs.get(htlc_id)
            if htlc is None:
                return False, f"HTLC {htlc_id} not found"
            if htlc.state != HTLCState.RECEIVED:
                return False, f"Cannot settle HTLC in state {htlc.state.value}"
            if not htlc.settle(preimage):
                return False, "Invalid preimage"

            # Update balances
            self.local_msats  += htlc.amount_msat
            self.remote_msats -= htlc.amount_msat
            self.commitment_number += 1
            self.last_updated = time.time()
            return True, "HTLC settled"

    def fail_htlc(self, htlc_id: int, reason: str = "") -> Tuple[bool, str]:
        """Fail an HTLC and return funds to sender"""
        with self._lock:
            htlc = self.htlcs.get(htlc_id)
            if htlc is None:
                return False, f"HTLC {htlc_id} not found"
            htlc.fail()
            self.last_updated = time.time()
            return True, f"HTLC failed: {reason}"

    # ── Balance ──────────────────────────────────────────────────
    @property
    def local_balance_sat(self) -> int:
        return self.local_msats // 1000

    @property
    def remote_balance_sat(self) -> int:
        return self.remote_msats // 1000

    @property
    def pending_htlcs(self) -> List[HTLC]:
        return [h for h in self.htlcs.values()
                if h.state in (HTLCState.OFFERED, HTLCState.RECEIVED)]

    def pending_outgoing_msat(self) -> int:
        return sum(h.amount_msat for h in self.pending_htlcs
                   if h.state == HTLCState.OFFERED)

    def pending_incoming_msat(self) -> int:
        return sum(h.amount_msat for h in self.pending_htlcs
                   if h.state == HTLCState.RECEIVED)

    # ── Close ────────────────────────────────────────────────────
    def initiate_close(self) -> Tuple[bool, str]:
        """Initiate cooperative channel close"""
        with self._lock:
            if self.state != ChannelState.NORMAL:
                return False, f"Cannot close from state {self.state.value}"
            if self.pending_htlcs:
                return False, f"Cannot close with {len(self.pending_htlcs)} pending HTLCs"
            self.state = ChannelState.LOCAL_SHUTDOWN
            self.last_updated = time.time()
            return True, "Cooperative close initiated"

    def force_close(self) -> dict:
        """
        Force close channel by broadcasting commitment transaction.
        Returns commitment tx data for on-chain broadcast.
        """
        with self._lock:
            self.state = ChannelState.FORCE_CLOSED
            self.last_updated = time.time()
            return self._commit_builder.build(
                funding_txid     = self.funding_txid or '00'*32,
                funding_vout     = self.funding_vout,
                local_msats      = self.local_msats,
                remote_msats     = self.remote_msats,
                htlcs            = list(self.htlcs.values()),
                commitment_number= self.commitment_number,
            )

    def commitment_tx(self) -> dict:
        """Get current commitment transaction"""
        return self._commit_builder.build(
            funding_txid     = self.funding_txid or '00'*32,
            funding_vout     = self.funding_vout,
            local_msats      = self.local_msats,
            remote_msats     = self.remote_msats,
            htlcs            = list(self.htlcs.values()),
            commitment_number= self.commitment_number,
        )

    def to_dict(self) -> dict:
        return {
            "channel_id"       : self.channel_id.hex(),
            "state"            : self.state.value,
            "capacity_sat"     : self.capacity_sat,
            "local_balance_sat": self.local_balance_sat,
            "remote_balance_sat":self.remote_balance_sat,
            "local_balance_nbl": f"{self.local_balance_sat/10**DECIMALS:.9f}",
            "pending_htlcs"    : len(self.pending_htlcs),
            "commitment_number": self.commitment_number,
            "funding_txid"     : self.funding_txid,
            "is_initiator"     : self.is_initiator,
            "created_at"       : self.created_at,
        }

