# ── Channel Graph ─────────────────────────────────────────────────
@dataclass
class ChannelAnnouncement:
    """BOLT #7 channel announcement"""
    channel_id     : bytes
    node1_id       : bytes
    node2_id       : bytes
    capacity_sat   : int
    features       : int = 0
    timestamp      : float = field(default_factory=time.time)

@dataclass
class ChannelUpdate:
    """BOLT #7 channel update (routing policy)"""
    channel_id       : bytes
    direction        : int        # 0 = node1→node2, 1 = node2→node1
    fee_base_msat    : int = 1000
    fee_proportional : int = 1    # parts per million
    cltv_delta       : int = CLTV_EXPIRY_DELTA
    htlc_min_msat    : int = 1000
    htlc_max_msat    : int = 21_000_000 * 10**9
    timestamp        : float = field(default_factory=time.time)
    disabled         : bool = False

    def fee_for(self, amount_msat: int) -> int:
        """Calculate routing fee for given amount"""
        return self.fee_base_msat + (amount_msat * self.fee_proportional) // 1_000_000

class ChannelGraph:
    """
    BOLT #7 Lightning Network channel graph.
    Used for payment route finding (Dijkstra / modified Bellman-Ford).
    """

    def __init__(self):
        self._channels    : Dict[bytes, ChannelAnnouncement] = {}
        self._updates     : Dict[Tuple[bytes,int], ChannelUpdate] = {}
        self._node_chans  : Dict[bytes, List[bytes]] = {}
        self._lock        = threading.RLock()

    def add_channel(self, ann: ChannelAnnouncement):
        with self._lock:
            self._channels[ann.channel_id] = ann
            self._node_chans.setdefault(ann.node1_id, []).append(ann.channel_id)
            self._node_chans.setdefault(ann.node2_id, []).append(ann.channel_id)

    def update_channel(self, upd: ChannelUpdate):
        with self._lock:
            self._updates[(upd.channel_id, upd.direction)] = upd

    def find_route(self, source: bytes, dest: bytes,
                   amount_msat: int, max_hops: int = 20) -> List[dict]:
        """
        Dijkstra shortest-path route finding.
        Returns list of hop dicts: [{node_id, channel_id, fee_msat, cltv}]
        """
        with self._lock:
            import heapq
            dist   : Dict[bytes, int] = {source: 0}
            prev   : Dict[bytes, Tuple] = {}
            heap   = [(0, source)]

            while heap:
                cost, node = heapq.heappop(heap)
                if cost > dist.get(node, float('inf')):
                    continue
                if node == dest:
                    break
                for cid in self._node_chans.get(node, []):
                    ann = self._channels.get(cid)
                    if ann is None: continue
                    next_node = ann.node2_id if node == ann.node1_id else ann.node1_id
                    direction  = 0 if node == ann.node1_id else 1
                    upd = self._updates.get((cid, direction))
                    if upd is None or upd.disabled: continue
                    if amount_msat < upd.htlc_min_msat: continue
                    if amount_msat > upd.htlc_max_msat: continue
                    fee = upd.fee_for(amount_msat)
                    new_cost = cost + fee
                    if new_cost < dist.get(next_node, float('inf')):
                        dist[next_node]  = new_cost
                        prev[next_node]  = (node, cid, fee, upd.cltv_delta)
                        heapq.heappush(heap, (new_cost, next_node))

            if dest not in prev:
                return []   # no route

            # Reconstruct path
            path = []
            node = dest
            while node in prev:
                pnode, cid, fee, cltv = prev[node]
                path.append({
                    "node_id"   : node.hex(),
                    "channel_id": cid.hex(),
                    "fee_msat"  : fee,
                    "cltv_delta": cltv,
                })
                node = pnode
            path.reverse()
            return path[:max_hops]

    def channel_count(self) -> int: return len(self._channels)
    def node_count(self)    -> int: return len(self._node_chans)

