import json, socket, threading, time, hashlib, struct, secrets
from typing import Dict, List, Optional, Callable, Tuple
from dataclasses import dataclass, field
from enum import Enum

# ── Stratum Constants ─────────────────────────────────────────────
STRATUM_VERSION_V1    = "1.0"
STRATUM_VERSION_V2    = "2.0"
DEFAULT_POOL_PORT     = 3333
DEFAULT_POOL_PORT_SSL = 3334
MAX_POOL_WORKERS      = 10_000
SHARE_DIFFICULTY_MIN  = 1
SHARE_DIFFICULTY_MAX  = 0x7fffffff
VARDIFF_RETARGET_TIME = 30        # seconds between retargets
VARDIFF_TARGET_TIME   = 10        # target seconds per share
EXTRANONCE1_SIZE      = 4         # bytes
EXTRANONCE2_SIZE      = 4         # bytes

# ── Share Result ──────────────────────────────────────────────────
class ShareResult(Enum):
    ACCEPTED    = "accepted"
    REJECTED    = "rejected"
    DUPLICATE   = "duplicate"
    STALE       = "stale"
    LOW_DIFF    = "low_difficulty"
    INVALID_POW = "invalid_pow"

# ── Pool Statistics ───────────────────────────────────────────────
@dataclass
class PoolStats:
    shares_submitted  : int   = 0
    shares_accepted   : int   = 0
    shares_rejected   : int   = 0
    shares_stale      : int   = 0
    blocks_found      : int   = 0
    total_difficulty  : float = 0.0
    pool_hashrate     : float = 0.0
    active_workers    : int   = 0
    uptime_start      : float = field(default_factory=time.time)

    @property
    def accept_rate(self) -> float:
        return self.shares_accepted / max(1, self.shares_submitted)

    @property
    def uptime_secs(self) -> float:
        return time.time() - self.uptime_start

    def to_dict(self) -> dict:
        return {
            "shares_submitted" : self.shares_submitted,
            "shares_accepted"  : self.shares_accepted,
            "shares_rejected"  : self.shares_rejected,
            "shares_stale"     : self.shares_stale,
            "blocks_found"     : self.blocks_found,
            "accept_rate"      : f"{self.accept_rate*100:.2f}%",
            "pool_hashrate_mhs": f"{self.pool_hashrate/1e6:.2f}",
            "active_workers"   : self.active_workers,
            "uptime_hours"     : f"{self.uptime_secs/3600:.2f}",
        }

# ── Worker ────────────────────────────────────────────────────────
@dataclass
class PoolWorker:
    """Represents a connected mining worker"""
    worker_id       : str
    worker_name     : str
    address         : str           # payout address
    extranonce1     : bytes
    difficulty      : float = 1.0
    shares_accepted : int   = 0
    shares_rejected : int   = 0
    last_share_time : float = field(default_factory=time.time)
    connected_at    : float = field(default_factory=time.time)
    hashrate_mhs    : float = 0.0
    subscribed      : bool  = False
    authorized      : bool  = False
    recent_shares   : List[float] = field(default_factory=list)

    def update_hashrate(self):
        """Update estimated hashrate from recent share times"""
        now = time.time()
        self.recent_shares = [t for t in self.recent_shares if now - t < 60]
        if len(self.recent_shares) > 1:
            span = self.recent_shares[-1] - self.recent_shares[0]
            self.hashrate_mhs = (len(self.recent_shares) * self.difficulty *
                                  2**32) / max(1, span) / 1e6

    def to_dict(self) -> dict:
        return {
            "worker_id"       : self.worker_id,
            "worker_name"     : self.worker_name,
            "address"         : self.address,
            "difficulty"      : self.difficulty,
            "shares_accepted" : self.shares_accepted,
            "shares_rejected" : self.shares_rejected,
            "hashrate_mhs"    : f"{self.hashrate_mhs:.2f}",
            "connected_secs"  : int(time.time() - self.connected_at),
        }

# ── Variable Difficulty ───────────────────────────────────────────
class VarDiff:
    """
    Automatic difficulty adjustment per worker.
    Keeps share rate at TARGET_TIME seconds per share.
    Range: 1 – max_difficulty.
    """
    def __init__(self, target_time: float = VARDIFF_TARGET_TIME,
                 min_diff: float = 1.0, max_diff: float = 1_000_000.0):
        self.target_time = target_time
        self.min_diff    = min_diff
        self.max_diff    = max_diff
        self._last_retarget : Dict[str, float] = {}

    def retarget(self, worker: PoolWorker) -> Optional[float]:
        """
        Return new difficulty for worker, or None if no change needed.
        Called after each accepted share.
        """
        now = time.time()
        last = self._last_retarget.get(worker.worker_id, worker.connected_at)
        if now - last < VARDIFF_RETARGET_TIME:
            return None

        self._last_retarget[worker.worker_id] = now
        recent = worker.recent_shares
        if len(recent) < 2:
            return None

        span           = recent[-1] - recent[0]
        actual_time    = span / max(1, len(recent) - 1)
        ratio          = actual_time / self.target_time
        new_diff       = worker.difficulty / ratio
        new_diff       = max(self.min_diff, min(self.max_diff, new_diff))

        if abs(new_diff - worker.difficulty) / worker.difficulty > 0.1:
            return new_diff
        return None

# ── Block Template (Stratum) ──────────────────────────────────────
@dataclass
class StratumBlockTemplate:
    """Current block template distributed to all workers"""
    job_id          : str
    prev_hash       : str
    coinbase1       : bytes     # coinbase prefix (before extranonce)
    coinbase2       : bytes     # coinbase suffix (after extranonce)
    merkle_branches : List[str] # Merkle branch hashes
    version         : int
    bits            : str       # hex
    timestamp       : str       # hex
    height          : int
    clean_jobs      : bool = True
    created_at      : float = field(default_factory=time.time)

    def is_stale(self, max_age_secs: float = 120.0) -> bool:
        return time.time() - self.created_at > max_age_secs

    def to_notify_params(self) -> list:
        """Stratum mining.notify params"""
        return [
            self.job_id,
            self.prev_hash,
            self.coinbase1.hex(),
            self.coinbase2.hex(),
            self.merkle_branches,
            f"{self.version:08x}",
            self.bits,
            self.timestamp,
            self.clean_jobs,
        ]

# ── Stratum V1 Server ─────────────────────────────────────────────
class StratumV1Server:
    """
    Stratum v1 JSON-RPC mining pool server.
    Handles: subscribe, authorize, submit, set_difficulty, notify.
    Compatible with all major mining software (cgminer, bfgminer, etc).
    """

    def __init__(self,
                 blockchain   : 'NEBULABlockchain',
                 host         : str = _nbl_default_bind(),
                 port         : int = DEFAULT_POOL_PORT,
                 pool_address : str = FOUNDATION_ADDRESS,
                 pool_fee_pct : float = 1.0,
                 pool_password: str = ""):
        self.blockchain    = blockchain
        self.host          = host
        self.port          = port
        self.pool_address  = pool_address
        self.pool_fee_pct  = pool_fee_pct
        # pool_password read from env if not passed directly
        self.pool_password = pool_password or os.environ.get("NEBULA_POOL_PASSWORD", "")

        self._workers      : Dict[str, PoolWorker] = {}
        self._current_job  : Optional[StratumBlockTemplate] = None
        self._stats        = PoolStats()
        self._vardiff      = VarDiff()
        self._lock         = threading.RLock()
        self._running      = False
        self._server_sock  : Optional[socket.socket] = None
        self._job_counter  = 0
        self._submitted    : set = set()   # duplicate share detection

        self.on_block_found : Optional[Callable] = None

        # v10.18: ExtraNonceManager accounting + unique extranonce1 per worker (group 5)
        try:
            self.group5_pool = Group5Pool.for_server(self)
        except Exception as e:
            self.group5_error = repr(e)

    # ── Server lifecycle ─────────────────────────────────────────
    def start(self):
        """Start the Stratum pool server"""
        self._running = True
        threading.Thread(target=self._listen, daemon=True,
                         name="Stratum-Listen").start()
        threading.Thread(target=self._job_broadcaster, daemon=True,
                         name="Stratum-JobBroadcast").start()
        threading.Thread(target=self._stats_loop, daemon=True,
                         name="Stratum-Stats").start()
        print(f"⛏️  Stratum Pool listening on {self.host}:{self.port}")
        print(f"   Pool address : {self.pool_address}")
        print(f"   Pool fee     : {self.pool_fee_pct}%")

    def stop(self):
        self._running = False
        if self._server_sock:
            try: self._server_sock.close()
            except Exception: _NB_SWALLOW_LOG.debug("swallowed bare in StratumV1Server.stop", exc_info=True)

    def _listen(self):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        sock.bind((self.host, self.port))
        sock.listen(MAX_POOL_WORKERS)
        self._server_sock = sock
        while self._running:
            try:
                conn, addr = sock.accept()
                t = threading.Thread(
                    target=self._handle_worker,
                    args=(conn, addr), daemon=True,
                    name=f"Worker-{addr[0]}:{addr[1]}")
                t.start()
            except Exception:
                break

    # ── Worker handler ───────────────────────────────────────────
    def _handle_worker(self, conn: socket.socket, addr: Tuple):
        worker_id = f"{addr[0]}:{addr[1]}"
        extranonce1 = secrets.token_bytes(EXTRANONCE1_SIZE)
        worker = PoolWorker(
            worker_id   = worker_id,
            worker_name = "",
            address     = "",
            extranonce1 = extranonce1,
        )
        with self._lock:
            self._workers[worker_id] = worker
            self._stats.active_workers = len(self._workers)

        buf = b''
        try:
            conn.settimeout(120)
            while self._running:
                data = conn.recv(4096)
                if not data: break
                buf += data
                while b'\n' in buf:
                    line, buf = buf.split(b'\n', 1)
                    if line.strip():
                        try:
                            msg = json.loads(line.decode('utf-8'))
                            resp = self._handle_message(worker, msg)
                            if resp:
                                conn.sendall(json.dumps(resp).encode() + b'\n')
                        except Exception as e:
                            _NB_SWALLOW_LOG.debug("swallowed Exception in StratumV1Server._handle_worker", exc_info=True)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in StratumV1Server._handle_worker", exc_info=True)
        finally:
            conn.close()
            with self._lock:
                self._workers.pop(worker_id, None)
                self._stats.active_workers = len(self._workers)

    def _handle_message(self, worker: PoolWorker, msg: dict) -> Optional[dict]:
        """Dispatch Stratum method"""
        method = msg.get("method", "")
        mid    = msg.get("id")
        params = msg.get("params", [])

        if method == "mining.subscribe":
            return self._handle_subscribe(worker, mid, params)
        elif method == "mining.authorize":
            return self._handle_authorize(worker, mid, params)
        elif method == "mining.submit":
            return self._handle_submit(worker, mid, params)
        elif method == "mining.extranonce.subscribe":
            return {"id": mid, "result": True, "error": None}
        elif method == "mining.get_transactions":
            return {"id": mid, "result": [], "error": None}
        return None

    def _handle_subscribe(self, worker: PoolWorker,
                           mid, params: list) -> dict:
        worker.subscribed = True
        return {
            "id"    : mid,
            "result": [
                [["mining.set_difficulty", worker.worker_id],
                 ["mining.notify", worker.worker_id]],
                worker.extranonce1.hex(),
                EXTRANONCE2_SIZE,
            ],
            "error" : None,
        }

    def _handle_authorize(self, worker: PoolWorker,
                           mid, params: list) -> dict:
        if not params:
            return {"id": mid, "result": False, "error": [24, "Unauthorized", None]}
        worker_name     = params[0] if params else ""
        worker_password = params[1] if len(params) > 1 else ""
        parts           = worker_name.split('.')
        # Verify pool password if one is configured.
        if self.pool_password:
            _pw_b  = self.pool_password.encode() if isinstance(self.pool_password, str) else self.pool_password
            _sup_b = worker_password.encode()    if isinstance(worker_password,    str) else worker_password
            try:
                pw_ok = hmac.compare_digest(_sup_b, _pw_b)
            except Exception:
                pw_ok = False
            if not pw_ok:
                return {"id": mid, "result": False, "error": [24, "Unauthorized — wrong pool password", None]}
        worker.worker_name = worker_name
        worker.address     = parts[0] if parts else self.pool_address
        worker.authorized  = True
        return {"id": mid, "result": True, "error": None}

    def _handle_submit(self, worker: PoolWorker,
                        mid, params: list) -> dict:
        """Process share submission"""
        if not worker.authorized:
            return {"id": mid, "result": False, "error": [24, "Unauthorized", None]}
        if len(params) < 5:
            return {"id": mid, "result": False, "error": [20, "Invalid params", None]}

        _wname, job_id, extranonce2_hex, ntime_hex, nonce_hex = params[:5]

        with self._lock:
            self._stats.shares_submitted += 1

        # Duplicate detection — check+add must be atomic inside one lock
        share_key = f"{job_id}:{extranonce2_hex}:{ntime_hex}:{nonce_hex}"
        with self._lock:
            if share_key in self._submitted:
                self._stats.shares_rejected += 1
                return {"id": mid, "result": False,
                        "error": [22, "Duplicate share", None]}
            self._submitted.add(share_key)

        # Stale check
        if self._current_job and self._current_job.is_stale():
            with self._lock: self._stats.shares_stale += 1
            return {"id": mid, "result": False, "error": [21, "Stale", None]}

        # Verify PoW
        result = self._verify_share(worker, job_id, extranonce2_hex,
                                    ntime_hex, nonce_hex)

        with self._lock:
            if result == ShareResult.ACCEPTED:
                self._stats.shares_accepted += 1
                self._stats.total_difficulty += worker.difficulty
                worker.shares_accepted += 1
                worker.recent_shares.append(time.time())
                worker.last_share_time = time.time()
                worker.update_hashrate()

                # VarDiff retarget
                new_diff = self._vardiff.retarget(worker)
                if new_diff:
                    worker.difficulty = new_diff
                    return {
                        "id": mid, "result": True, "error": None,
                        "_difficulty_change": new_diff,
                    }
            else:
                self._stats.shares_rejected += 1
                worker.shares_rejected += 1

        accepted = result == ShareResult.ACCEPTED
        return {"id": mid, "result": accepted,
                "error": None if accepted else [20, result.value, None]}

    def _verify_share(self, worker: PoolWorker, job_id: str,
                      extranonce2_hex: str, ntime_hex: str,
                      nonce_hex: str) -> ShareResult:
        """Verify share difficulty and optionally full PoW"""
        if self._current_job is None:
            return ShareResult.STALE

        try:
            extranonce2 = bytes.fromhex(extranonce2_hex)
            ntime       = bytes.fromhex(ntime_hex)
            nonce_bytes = bytes.fromhex(nonce_hex)

            # Rebuild coinbase
            coinbase = (self._current_job.coinbase1 +
                        worker.extranonce1 + extranonce2 +
                        self._current_job.coinbase2)
            cb_hash  = hashlib.sha256(hashlib.sha256(coinbase).digest()).digest()

            # Build Merkle root from branches
            merkle = cb_hash
            for branch in self._current_job.merkle_branches:
                merkle = hashlib.sha256(
                    hashlib.sha256(merkle + bytes.fromhex(branch)).digest()
                ).digest()

            # Build block header
            prev = bytes.fromhex(self._current_job.prev_hash)
            bits = bytes.fromhex(self._current_job.bits)
            ver  = struct.pack('<I', self._current_job.version)
            header = ver + prev + merkle + ntime + bits + nonce_bytes

            # Compute hash
            h = hashlib.sha256(hashlib.sha256(header).digest()).digest()
            h_int = int.from_bytes(h[::-1], 'big')

            # Check worker difficulty
            worker_target = (2**256 - 1) // max(1, int(worker.difficulty))
            if h_int > worker_target:
                return ShareResult.LOW_DIFF

            # Check block difficulty
            block_target = bits_to_target(int(self._current_job.bits, 16))
            if h_int < block_target:
                print(f"🎉 BLOCK FOUND by {worker.worker_name}!")
                self._stats.blocks_found += 1
                if self.on_block_found:
                    self.on_block_found(worker, h[::-1].hex())

            return ShareResult.ACCEPTED
        except Exception as e:
            return ShareResult.REJECTED

    # ── Job broadcasting ─────────────────────────────────────────
    def _job_broadcaster(self):
        """Continuously broadcast new jobs when blockchain tip changes"""
        last_tip = None
        while self._running:
            try:
                tip = self.blockchain.tip.hash
                if tip != last_tip:
                    last_tip = tip
                    self._update_job()
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in StratumV1Server._job_broadcaster", exc_info=True)
            time.sleep(5)

    def _update_job(self):
        """Generate new block template and job"""
        try:
            chain   = self.blockchain
            height  = chain.height + 1
            bits    = chain.get_next_bits()
            ts      = int(time.time())

            # Build coinbase (pool fee → pool, rest → workers)
            pool_reward  = int(mining_reward(height) * self.pool_fee_pct / 100)
            miner_reward = mining_reward(height) - pool_reward

            # Coinbase script
            height_script = (b'\x03' + height.to_bytes(3, 'little'))
            extranonce_placeholder = b'\x00' * (EXTRANONCE1_SIZE + EXTRANONCE2_SIZE)

            coinbase1 = (struct.pack('<i', 1) +         # version
                         b'\x01' +                       # vin count
                         b'\x00'*32 + b'\xff\xff\xff\xff' +  # null outpoint
                         bytes([len(height_script)]) + height_script)
            coinbase2 = (extranonce_placeholder +
                         b'\xff\xff\xff\xff' +           # sequence
                         b'\x02' +                       # 2 outputs
                         struct.pack('<q', miner_reward) +
                         b'\x19' +                       # p2pkh script len
                         b'\x76\xa9\x14' + b'\x00'*20 + b'\x88\xac' +  # placeholder
                         struct.pack('<q', pool_reward) +
                         b'\x19' +
                         b'\x76\xa9\x14' + b'\x00'*20 + b'\x88\xac' +
                         b'\x00\x00\x00\x00')            # locktime

            self._job_counter += 1
            job = StratumBlockTemplate(
                job_id           = f"{self._job_counter:08x}",
                prev_hash        = chain.tip.hash,
                coinbase1        = coinbase1,
                coinbase2        = coinbase2,
                merkle_branches  = [],   # simplified (no mempool txs)
                version          = CHAIN_VERSION,
                bits             = f"{bits:08x}",
                timestamp        = f"{ts:08x}",
                height           = height,
                clean_jobs       = True,
            )
            with self._lock:
                self._current_job = job
        except Exception as e:
            _NB_SWALLOW_LOG.debug("swallowed Exception in StratumV1Server._update_job", exc_info=True)

    def _stats_loop(self):
        while self._running:
            time.sleep(60)
            with self._lock:
                workers = list(self._workers.values())
            hr = sum(w.hashrate_mhs for w in workers)
            with self._lock:
                self._stats.pool_hashrate = hr * 1e6

    # ── Public API ───────────────────────────────────────────────
    def get_stats(self) -> dict:
        with self._lock:
            return self._stats.to_dict()

    def get_workers(self) -> List[dict]:
        with self._lock:
            return [w.to_dict() for w in self._workers.values()]

    def worker_count(self) -> int:
        return len(self._workers)

    def pool_hashrate_mhs(self) -> float:
        return sum(w.hashrate_mhs for w in self._workers.values())

