# ================================================================
# MODULE 15  nebula_storage.py  — LevelDB / SQLite Persistent UTXO
# ================================================================
# Production-grade persistent storage for UTXO set, block index,
# chain state. Falls back to SQLite if LevelDB not available.
# ================================================================

import os, json, struct, hashlib, threading, time, sqlite3
from typing import Dict, List, Optional, Iterator, Tuple
from pathlib import Path
from dataclasses import dataclass

# ── Storage Backend Detection ─────────────────────────────────────
try:
    import plyvel                    # LevelDB Python bindings
    _LEVELDB_AVAILABLE = True
except ImportError:
    _LEVELDB_AVAILABLE = False

# ── Storage Constants ─────────────────────────────────────────────
STORAGE_VERSION         = 1
DB_UTXO_PREFIX          = b'u'     # UTXO entries
DB_BLOCK_PREFIX         = b'b'     # Block headers
DB_TX_PREFIX            = b't'     # Transaction index
DB_HEIGHT_PREFIX        = b'h'     # Height → hash
DB_META_KEY             = b'meta'
DB_BEST_BLOCK_KEY       = b'best_block'
BATCH_WRITE_SIZE        = 1000     # entries per batch
CACHE_SIZE_MB           = 8        # in-memory cache

# ── Serialization helpers ─────────────────────────────────────────
def _ser_int32(n: int)  -> bytes: return struct.pack('<i', n)
def _ser_uint32(n: int) -> bytes: return struct.pack('<I', n)
def _ser_int64(n: int)  -> bytes: return struct.pack('<q', n)
def _des_int64(b: bytes) -> int:  return struct.unpack('<q', b)[0]
def _des_uint32(b: bytes) -> int: return struct.unpack('<I', b)[0]

# ── UTXO Entry Serialization ──────────────────────────────────────
def _serialize_utxo_entry(entry: 'UTXOEntry') -> bytes:
    """
    Compact UTXO serialization (similar to Bitcoin Core's coins.cpp).
    Format: height(4) | is_coinbase(1) | value(8) | script_len(2) | script
    """
    flags = (1 if entry.is_coinbase else 0)
    return (struct.pack('<I', entry.height) +
            struct.pack('<B', flags) +
            struct.pack('<q', entry.value) +
            struct.pack('<H', len(entry.script_pubkey)) +
            entry.script_pubkey)

def _deserialize_utxo_entry(txid: str, index: int, data: bytes) -> 'UTXOEntry':
    """Deserialize compact UTXO entry"""
    height     = struct.unpack_from('<I', data, 0)[0]
    flags      = data[4]
    value      = struct.unpack_from('<q', data, 5)[0]
    script_len = struct.unpack_from('<H', data, 13)[0]
    script     = data[15:15+script_len]
    return UTXOEntry(
        txid          = txid,
        index         = index,
        value         = value,
        script_pubkey = script,
        height        = height,
        is_coinbase   = bool(flags & 1),
    )

def _utxo_key(txid: str, index: int) -> bytes:
    """UTXO database key: prefix + txid_bytes + vout"""
    return (DB_UTXO_PREFIX +
            bytes.fromhex(txid)[::-1] +
            struct.pack('<I', index))

# ── SQLite Backend ────────────────────────────────────────────────
class SQLiteBackend:
    """
    SQLite-based persistent storage backend.
    Used when LevelDB is not available.
    Single-file database with WAL mode for concurrent reads.
    Tables: utxos, blocks, transactions, meta
    """

    SCHEMA = """
    CREATE TABLE IF NOT EXISTS utxos (
        txid         TEXT NOT NULL,
        vout         INTEGER NOT NULL,
        value        INTEGER NOT NULL,
        script_pubkey BLOB NOT NULL,
        height       INTEGER NOT NULL,
        is_coinbase  INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (txid, vout)
    );
    CREATE INDEX IF NOT EXISTS idx_utxos_height ON utxos(height);

    CREATE TABLE IF NOT EXISTS blocks (
        hash         TEXT PRIMARY KEY,
        height       INTEGER NOT NULL UNIQUE,
        version      INTEGER NOT NULL,
        prev_hash    TEXT NOT NULL,
        merkle_root  TEXT NOT NULL,
        timestamp    INTEGER NOT NULL,
        bits         INTEGER NOT NULL,
        nonce        INTEGER NOT NULL,
        tx_count     INTEGER NOT NULL DEFAULT 0,
        size_bytes   INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_blocks_height ON blocks(height);

    CREATE TABLE IF NOT EXISTS transactions (
        txid         TEXT PRIMARY KEY,
        block_hash   TEXT NOT NULL,
        block_height INTEGER NOT NULL,
        tx_index     INTEGER NOT NULL,
        raw_size     INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS idx_txs_block ON transactions(block_hash);

    CREATE TABLE IF NOT EXISTS address_index (
        address      TEXT NOT NULL,
        txid         TEXT NOT NULL,
        vout         INTEGER NOT NULL,
        value        INTEGER NOT NULL,
        height       INTEGER NOT NULL,
        spent        INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (address, txid, vout)
    );
    CREATE INDEX IF NOT EXISTS idx_addr_idx ON address_index(address);

    CREATE TABLE IF NOT EXISTS meta (
        key   TEXT PRIMARY KEY,
        value TEXT NOT NULL
    );
    """

    def __init__(self, db_path: str):
        self.db_path = db_path
        self._conn   : Optional[sqlite3.Connection] = None
        self._lock   = threading.RLock()
        self._open()

    def _open(self):
        Path(self.db_path).parent.mkdir(parents=True, exist_ok=True)
        self._conn = sqlite3.connect(self.db_path, check_same_thread=False)
        self._conn.execute("PRAGMA journal_mode=WAL")
        self._conn.execute("PRAGMA synchronous=NORMAL")
        self._conn.execute(f"PRAGMA cache_size=-{CACHE_SIZE_MB * 1024}")
        self._conn.execute("PRAGMA temp_store=MEMORY")
        self._conn.executescript(self.SCHEMA)
        self._conn.commit()

    # ── UTXO operations ──────────────────────────────────────────
    def put_utxo(self, entry: 'UTXOEntry'):
        with self._lock:
            self._conn.execute(
                "INSERT OR REPLACE INTO utxos VALUES (?,?,?,?,?,?)",
                (entry.txid, entry.index, entry.value,
                 entry.script_pubkey, entry.height,
                 1 if entry.is_coinbase else 0))

    def delete_utxo(self, txid: str, index: int):
        with self._lock:
            self._conn.execute(
                "DELETE FROM utxos WHERE txid=? AND vout=?",
                (txid, index))

    def get_utxo(self, txid: str, index: int) -> Optional['UTXOEntry']:
        with self._lock:
            cur = self._conn.execute(
                "SELECT value,script_pubkey,height,is_coinbase FROM utxos WHERE txid=? AND vout=?",
                (txid, index))
            row = cur.fetchone()
            if row is None: return None
            return UTXOEntry(txid=txid, index=index, value=row[0],
                             script_pubkey=row[1], height=row[2],
                             is_coinbase=bool(row[3]))

    def get_utxos_by_address(self, address: str) -> List['UTXOEntry']:
        with self._lock:
            cur = self._conn.execute(
                "SELECT txid,vout,value,script_pubkey,height,is_coinbase "
                "FROM utxos JOIN address_index USING(txid,vout) "
                "WHERE address=? AND spent=0", (address,))
            return [UTXOEntry(txid=r[0], index=r[1], value=r[2],
                              script_pubkey=r[3], height=r[4],
                              is_coinbase=bool(r[5]))
                    for r in cur.fetchall()]

    def utxo_count(self) -> int:
        with self._lock:
            return self._conn.execute("SELECT COUNT(*) FROM utxos").fetchone()[0]

    def utxo_total_value(self) -> int:
        with self._lock:
            row = self._conn.execute("SELECT SUM(value) FROM utxos").fetchone()
            return row[0] or 0

    def batch_put_utxos(self, entries: List['UTXOEntry']):
        """Bulk insert UTXOs in a single transaction"""
        with self._lock:
            self._conn.executemany(
                "INSERT OR REPLACE INTO utxos VALUES (?,?,?,?,?,?)",
                [(e.txid, e.index, e.value, e.script_pubkey,
                  e.height, 1 if e.is_coinbase else 0)
                 for e in entries])
            self._conn.commit()

    # ── Block index ──────────────────────────────────────────────
    def put_block(self, block: 'Block'):
        with self._lock:
            h = block.header
            self._conn.execute(
                "INSERT OR REPLACE INTO blocks VALUES (?,?,?,?,?,?,?,?,?,?)",
                (block.hash, h.height, h.version, h.prev_hash,
                 h.merkle_root, h.timestamp, h.bits, h.nonce,
                 len(block.transactions), block.byte_size()))

    def get_block_hash_at_height(self, height: int) -> Optional[str]:
        with self._lock:
            cur = self._conn.execute(
                "SELECT hash FROM blocks WHERE height=?", (height,))
            row = cur.fetchone()
            return row[0] if row else None

    def get_block_height(self, block_hash: str) -> Optional[int]:
        with self._lock:
            cur = self._conn.execute(
                "SELECT height FROM blocks WHERE hash=?", (block_hash,))
            row = cur.fetchone()
            return row[0] if row else None

    def get_best_height(self) -> int:
        with self._lock:
            cur = self._conn.execute("SELECT MAX(height) FROM blocks")
            row = cur.fetchone()
            return row[0] if row and row[0] is not None else -1

    def block_count(self) -> int:
        with self._lock:
            return self._conn.execute("SELECT COUNT(*) FROM blocks").fetchone()[0]

    # ── Transaction index ─────────────────────────────────────────
    def put_tx(self, txid: str, block_hash: str,
               block_height: int, tx_index: int, size: int = 0):
        with self._lock:
            self._conn.execute(
                "INSERT OR REPLACE INTO transactions VALUES (?,?,?,?,?)",
                (txid, block_hash, block_height, tx_index, size))

    def get_tx_block(self, txid: str) -> Optional[Tuple[str,int]]:
        with self._lock:
            cur = self._conn.execute(
                "SELECT block_hash,block_height FROM transactions WHERE txid=?",
                (txid,))
            row = cur.fetchone()
            return (row[0], row[1]) if row else None

    # ── Address index ─────────────────────────────────────────────
    def index_address_output(self, address: str, txid: str,
                              vout: int, value: int, height: int):
        with self._lock:
            self._conn.execute(
                "INSERT OR IGNORE INTO address_index VALUES (?,?,?,?,?,0)",
                (address, txid, vout, value, height))

    def mark_utxo_spent(self, address: str, txid: str, vout: int):
        with self._lock:
            self._conn.execute(
                "UPDATE address_index SET spent=1 WHERE address=? AND txid=? AND vout=?",
                (address, txid, vout))

    def get_address_balance(self, address: str) -> int:
        with self._lock:
            cur = self._conn.execute(
                "SELECT SUM(value) FROM address_index WHERE address=? AND spent=0",
                (address,))
            row = cur.fetchone()
            return row[0] or 0

    # ── Meta ──────────────────────────────────────────────────────
    def set_meta(self, key: str, value: str):
        with self._lock:
            self._conn.execute(
                "INSERT OR REPLACE INTO meta VALUES (?,?)", (key, value))
            self._conn.commit()

    def get_meta(self, key: str, default: str = None) -> Optional[str]:
        with self._lock:
            cur = self._conn.execute(
                "SELECT value FROM meta WHERE key=?", (key,))
            row = cur.fetchone()
            return row[0] if row else default

    def commit(self):
        with self._lock:
            self._conn.commit()

    def close(self):
        if self._conn:
            self._conn.commit()
            self._conn.close()
            self._conn = None

    def stats(self) -> dict:
        return {
            "backend"         : "SQLite",
            "db_path"         : self.db_path,
            "db_size_mb"      : round(os.path.getsize(self.db_path)/1024/1024, 2)
                                if os.path.exists(self.db_path) else 0,
            "utxo_count"      : self.utxo_count(),
            "utxo_total_nbl"  : f"{self.utxo_total_value()/10**DECIMALS:.9f}",
            "block_count"     : self.block_count(),
            "best_height"     : self.get_best_height(),
        }

# ── LevelDB Backend (optional) ────────────────────────────────────
class LevelDBBackend:
    """
    LevelDB-based persistent storage (faster than SQLite for UTXO).
    Uses plyvel Python bindings. Falls back gracefully to SQLite.
    """

    def __init__(self, db_path: str):
        if not _LEVELDB_AVAILABLE:
            raise ImportError("plyvel not installed — use SQLiteBackend")
        import plyvel
        self.db_path = db_path
        Path(db_path).mkdir(parents=True, exist_ok=True)
        self._db = plyvel.DB(db_path, create_if_missing=True,
                              write_buffer_size=CACHE_SIZE_MB*1024*1024)
        self._lock = threading.RLock()

    def put_utxo(self, entry: 'UTXOEntry'):
        key = _utxo_key(entry.txid, entry.index)
        val = _serialize_utxo_entry(entry)
        with self._lock:
            self._db.put(key, val)

    def delete_utxo(self, txid: str, index: int):
        key = _utxo_key(txid, index)
        with self._lock:
            self._db.delete(key)

    def get_utxo(self, txid: str, index: int) -> Optional['UTXOEntry']:
        key = _utxo_key(txid, index)
        with self._lock:
            val = self._db.get(key)
        if val is None: return None
        return _deserialize_utxo_entry(txid, index, val)

    def batch_put_utxos(self, entries: List['UTXOEntry']):
        with self._lock:
            with self._db.write_batch() as wb:
                for e in entries:
                    wb.put(_utxo_key(e.txid, e.index),
                           _serialize_utxo_entry(e))

    def put_block_header(self, block: 'Block'):
        key = DB_BLOCK_PREFIX + bytes.fromhex(block.hash)[::-1]
        h   = block.header
        val = (struct.pack('<iI', h.version, h.height) +
               bytes.fromhex(h.prev_hash)[::-1] +
               bytes.fromhex(h.merkle_root)[::-1] +
               struct.pack('<III', h.timestamp, h.bits, h.nonce))
        with self._lock:
            self._db.put(key, val)
            # Height → hash index
            hk = DB_HEIGHT_PREFIX + struct.pack('<I', h.height)
            self._db.put(hk, bytes.fromhex(block.hash)[::-1])

    def set_best_block(self, block_hash: str):
        with self._lock:
            self._db.put(DB_BEST_BLOCK_KEY,
                         bytes.fromhex(block_hash)[::-1])

    def get_best_block(self) -> Optional[str]:
        with self._lock:
            val = self._db.get(DB_BEST_BLOCK_KEY)
        if val is None: return None
        return val[::-1].hex()

    def utxo_count(self) -> int:
        count = 0
        with self._lock:
            for _ in self._db.iterator(prefix=DB_UTXO_PREFIX):
                count += 1
        return count

    def close(self):
        self._db.close()

    def stats(self) -> dict:
        return {
            "backend"    : "LevelDB",
            "db_path"    : self.db_path,
            "utxo_count" : self.utxo_count(),
        }

# ── Persistent UTXO Set ───────────────────────────────────────────
class PersistentUTXOSetLegacy:
    """[v10.17] OLD implementation kept ONLY for old stand-alone callers (their API differs from the live PersistentUTXOSet)."""
    """
    UTXOSet backed by SQLite (or LevelDB if available).
    Drop-in replacement for in-memory UTXOSet with disk persistence.
    Survives node restarts — no need to replay all blocks.
    Maintains in-memory index for fast address lookups.
    """

    def __init__(self, data_dir: str):
        self.data_dir = Path(data_dir)
        self.data_dir.mkdir(parents=True, exist_ok=True)

        db_path = str(self.data_dir / "utxo.db")

        # Try LevelDB first, fall back to SQLite
        if _LEVELDB_AVAILABLE:
            try:
                self._db = LevelDBBackend(str(self.data_dir / "leveldb_utxo"))
                self._sql = SQLiteBackend(db_path)   # for address index
                self._backend = "LevelDB+SQLite"
            except Exception:
                self._db  = None
                self._sql = SQLiteBackend(db_path)
                self._backend = "SQLite"
        else:
            self._db  = None
            self._sql = SQLiteBackend(db_path)
            self._backend = "SQLite"

        self._lock   = threading.RLock()
        self._cache  : Dict[str, 'UTXOEntry'] = {}   # hot cache

    # ── Core operations ──────────────────────────────────────────
    def add(self, entry: 'UTXOEntry'):
        key = f"{entry.txid}:{entry.index}"
        with self._lock:
            self._cache[key] = entry
            self._sql.put_utxo(entry)
            if self._db:
                self._db.put_utxo(entry)
            # Address index
            addr = entry_address(entry)
            if addr:
                self._sql.index_address_output(
                    addr, entry.txid, entry.index, entry.value, entry.height)

    def spend(self, txid: str, index: int) -> Optional['UTXOEntry']:
        key = f"{txid}:{index}"
        with self._lock:
            entry = self._cache.pop(key, None) or self._sql.get_utxo(txid, index)
            if entry:
                self._sql.delete_utxo(txid, index)
                if self._db:
                    self._db.delete_utxo(txid, index)
                addr = entry_address(entry)
                if addr:
                    self._sql.mark_utxo_spent(addr, txid, index)
            return entry

    def get(self, txid: str, index: int) -> Optional['UTXOEntry']:
        key = f"{txid}:{index}"
        with self._lock:
            if key in self._cache:
                return self._cache[key]
            return self._sql.get_utxo(txid, index)

    def has(self, txid: str, index: int) -> bool:
        return self.get(txid, index) is not None

    def get_by_address(self, address: str) -> List['UTXOEntry']:
        return self._sql.get_utxos_by_address(address)

    def balance(self, address: str) -> int:
        return sum(e.value for e in self.get_by_address(address))

    def total_supply(self) -> int:
        return self._sql.utxo_total_value()

    def size(self) -> int:
        return self._sql.utxo_count()

    def apply_block(self, block: 'Block') -> bool:
        """Apply block to persistent UTXO set"""
        with self._lock:
            for tx in block.transactions:
                if not tx.is_coinbase:
                    for inp in tx.inputs:
                        if not self.has(inp.outpoint.txid, inp.outpoint.index):
                            return False
                        self.spend(inp.outpoint.txid, inp.outpoint.index)
                for idx, out in enumerate(tx.outputs):
                    if Script.classify(out.script_pubkey) != ScriptType.NULLDATA:
                        self.add(UTXOEntry(
                            txid         = tx.txid,
                            index        = idx,
                            value        = out.value,
                            script_pubkey= out.script_pubkey,
                            height       = block.height,
                            is_coinbase  = tx.is_coinbase,
                        ))
            self._sql.put_block(block)
            for i, tx in enumerate(block.transactions):
                self._sql.put_tx(tx.txid, block.hash, block.height, i,
                                  tx.byte_size())
            self._sql.commit()
            return True

    def flush(self):
        """Flush in-memory cache to disk"""
        with self._lock:
            if self._db:
                self._db.batch_put_utxos(list(self._cache.values()))
            self._sql.commit()

    def close(self):
        self.flush()
        self._sql.close()
        if self._db:
            self._db.close()

    def stats(self) -> dict:
        s = self._sql.stats()
        s["backend"]    = self._backend
        s["cache_size"] = len(self._cache)
        return s

# ── Block Index ───────────────────────────────────────────────────
def _pus_save_if_needed(self, height: int, every: int = 100):
    """Flush to disk every `every` blocks."""
    last = getattr(self, "_last_flush_height", None)
    if last is None or height - last >= every:
        self.flush()
        self._last_flush_height = height

def _pus_shutdown_save(self):
    self.flush()

def _pus_sync_from_chain(self, blockchain) -> int:
    """If the persistent set is empty, rebuild it by replaying the chain."""
    if self.size() > 0:
        return 0
    n = 0
    for blk in blockchain._chain:
        if self.apply_block(blk):
            n += 1
    self.flush()
    return n

PersistentUTXOSetLegacy.save_if_needed  = _pus_save_if_needed
PersistentUTXOSetLegacy.shutdown_save   = _pus_shutdown_save
PersistentUTXOSetLegacy.sync_from_chain = _pus_sync_from_chain

class BlockIndex:
    """
    Persistent block header index (SQLite).
    Fast lookup: height → hash, hash → height, best_height.
    Used by sync and IBD (Initial Block Download).
    """

    def __init__(self, data_dir: str):
        db_path    = str(Path(data_dir) / "blocks.db")
        self._sql  = SQLiteBackend(db_path)
        self._lock = threading.RLock()

    def add_block(self, block: 'Block'):
        with self._lock:
            self._sql.put_block(block)
            self._sql.set_meta("best_height", str(block.height))
            self._sql.set_meta("best_hash",   block.hash)
            self._sql.commit()

    def get_hash_at_height(self, height: int) -> Optional[str]:
        return self._sql.get_block_hash_at_height(height)

    def get_height_by_hash(self, block_hash: str) -> Optional[int]:
        return self._sql.get_block_height(block_hash)

    def best_height(self) -> int:
        return self._sql.get_best_height()

    def best_hash(self) -> Optional[str]:
        return self._sql.get_meta("best_hash")

    def block_count(self) -> int:
        return self._sql.block_count()

    def stats(self) -> dict:
        return {
            "best_height" : self.best_height(),
            "best_hash"   : (self.best_hash() or "")[:20] + "...",
            "block_count" : self.block_count(),
        }

# ── Chain Database (all-in-one) ───────────────────────────────────
class ChainDatabase:
    """
    Production chain database.
    Combines PersistentUTXOSet + BlockIndex + SQLite transaction index.
    Bitcoin Core equivalent: chainstate/ + blocks/index/
    """

    def __init__(self, data_dir: str):
        self.data_dir   = Path(data_dir)
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.utxo       = PersistentUTXOSetLegacy(str(self.data_dir / "chainstate"))
        self.block_index= BlockIndex(str(self.data_dir / "blocks_index"))
        self._lock      = threading.RLock()
        self._version   = STORAGE_VERSION

    def connect_block(self, block: 'Block') -> bool:
        """
        Connect a new block: update UTXO set + block index atomically.
        Returns False if block is invalid (UTXO not found etc).
        """
        with self._lock:
            ok = self.utxo.apply_block(block)
            if ok:
                self.block_index.add_block(block)
            return ok

    def disconnect_block(self, block: 'Block'):
        """
        Disconnect (undo) a block for reorg handling.
        Restores UTXO set to previous state.
        """
        with self._lock:
            # Undo in reverse order
            for tx in reversed(block.transactions):
                # Remove outputs
                for idx in range(len(tx.outputs)):
                    self.utxo.spend(tx.txid, idx)
            # Note: full undo requires undo data (rev*.dat equivalent)
            # Simplified: rebuild from previous blocks if needed

    def get_utxo(self, txid: str, vout: int) -> Optional['UTXOEntry']:
        return self.utxo.get(txid, vout)

    def get_address_balance(self, address: str) -> int:
        return self.utxo.balance(address)

    def is_synced(self, chain_height: int) -> bool:
        return self.block_index.best_height() >= chain_height

    def close(self):
        self.utxo.close()

    def stats(self) -> dict:
        return {
            "utxo"        : self.utxo.stats(),
            "block_index" : self.block_index.stats(),
            "data_dir"    : str(self.data_dir),
            "version"     : self._version,
        }

