# ── Transport Statistics ──────────────────────────────────────────
class TransportStats:
    """Network transport statistics"""
    def __init__(self):
        self.v2_connections    = 0
        self.v1_connections    = 0
        self.bytes_sent        = 0
        self.bytes_recv        = 0
        self.decoy_sent        = 0
        self.handshakes_ok     = 0
        self.handshakes_failed = 0
        self._lock = threading.Lock()

    def record_connection(self, v2: bool):
        with self._lock:
            if v2: self.v2_connections += 1
            else:  self.v1_connections += 1

    def record_handshake(self, ok: bool):
        with self._lock:
            if ok: self.handshakes_ok += 1
            else:  self.handshakes_failed += 1

    def record_bytes(self, sent: int, recv: int):
        with self._lock:
            self.bytes_sent += sent
            self.bytes_recv += recv

    def to_dict(self) -> dict:
        total = max(1, self.v2_connections + self.v1_connections)
        return {
            "v2_connections"    : self.v2_connections,
            "v1_connections"    : self.v1_connections,
            "v2_adoption"       : f"{self.v2_connections/total*100:.1f}%",
            "bytes_sent_mb"     : round(self.bytes_sent/1024/1024, 2),
            "bytes_recv_mb"     : round(self.bytes_recv/1024/1024, 2),
            "handshakes_ok"     : self.handshakes_ok,
            "handshakes_failed" : self.handshakes_failed,
        }

# Global transport stats
transport_stats = TransportStats()

