# MODULE 18  nebula_privacy.py  — Tor/I2P Privacy Network Layer
# ================================================================
# Tor SOCKS5 proxy integration, I2P SAM bridge, onion addresses,
# .onion peer connections, traffic analysis resistance.
# ================================================================

import socket, struct, threading, time, secrets, hashlib
from typing import Optional, List, Dict, Tuple
from dataclasses import dataclass, field
from enum import Enum

# ── Privacy Constants ─────────────────────────────────────────────
TOR_SOCKS5_HOST      = "127.0.0.1"
TOR_SOCKS5_PORT      = 9050
TOR_CONTROL_PORT     = 9051
I2P_SAM_HOST         = "127.0.0.1"
I2P_SAM_PORT         = 7656
ONION_V3_SIZE        = 56    # v3 .onion address length (without .onion)
I2P_B32_SIZE         = 52    # .b32.i2p address length
TOR_CONNECT_TIMEOUT  = 30
I2P_CONNECT_TIMEOUT  = 60
MAX_ONION_PEERS      = 40
PRIVACY_NET_PENALTY  = 0     # no penalty for onion peers in NEBULA

class NetworkType(Enum):
    IPV4   = "ipv4"
    IPV6   = "ipv6"
    ONION  = "onion"
    I2P    = "i2p"
    CJDNS  = "cjdns"

class PrivacyLevel(Enum):
    NONE     = 0   # clearnet only
    MIXED    = 1   # clearnet + Tor
    TOR_ONLY = 2   # Tor only (no clearnet leaks)
    I2P_ONLY = 3   # I2P only
    PARANOID = 4   # Tor + I2P, no clearnet

# ── Peer Address ──────────────────────────────────────────────────
@dataclass
class PeerAddress:
    """Network-agnostic peer address supporting Tor/I2P/IPv4/IPv6"""
    host        : str
    port        : int
    net_type    : NetworkType = NetworkType.IPV4
    services    : int = 0
    time_seen   : float = field(default_factory=time.time)
    attempts    : int = 0
    last_success: float = 0.0
    source      : str = "manual"

    @property
    def is_onion(self) -> bool:
        return self.net_type == NetworkType.ONION

    @property
    def is_i2p(self) -> bool:
        return self.net_type == NetworkType.I2P

    @property
    def is_clearnet(self) -> bool:
        return self.net_type in (NetworkType.IPV4, NetworkType.IPV6)

    @property
    def addr_str(self) -> str:
        if self.is_onion:
            return f"{self.host}.onion:{self.port}"
        if self.is_i2p:
            return f"{self.host}.b32.i2p:{self.port}"
        return f"{self.host}:{self.port}"

    def to_dict(self) -> dict:
        return {
            "addr"       : self.addr_str,
            "host"       : self.host,
            "port"       : self.port,
            "network"    : self.net_type.value,
            "attempts"   : self.attempts,
            "last_success": self.last_success,
            "source"     : self.source,
        }

    @classmethod
    def parse(cls, addr_str: str) -> 'PeerAddress':
        """Parse address string — auto-detects network type"""
        addr_str = addr_str.strip()
        if addr_str.endswith('.onion') or '.onion:' in addr_str:
            parts = addr_str.replace('.onion', '').rsplit(':', 1)
            host  = parts[0]
            port  = int(parts[1]) if len(parts) > 1 else DEFAULT_PORT
            return cls(host=host, port=port, net_type=NetworkType.ONION)
        elif '.b32.i2p' in addr_str:
            parts = addr_str.replace('.b32.i2p', '').rsplit(':', 1)
            host  = parts[0]
            port  = int(parts[1]) if len(parts) > 1 else DEFAULT_PORT
            return cls(host=host, port=port, net_type=NetworkType.I2P)
        else:
            parts = addr_str.rsplit(':', 1)
            host  = parts[0].strip('[]')
            port  = int(parts[1]) if len(parts) > 1 else DEFAULT_PORT
            net   = NetworkType.IPV6 if ':' in host else NetworkType.IPV4
            return cls(host=host, port=port, net_type=net)

# ── SOCKS5 Client ─────────────────────────────────────────────────
class SOCKS5Client:
    """
    SOCKS5 proxy client for Tor connections.
    Supports CONNECT method for TCP tunneling through Tor.
    Handles hostname resolution via SOCKS5 (prevents DNS leaks).
    """

    VERSION   = 0x05
    CMD_CONNECT = 0x01
    ATYP_IPV4 = 0x01
    ATYP_HOST = 0x03
    ATYP_IPV6 = 0x04
    AUTH_NONE = 0x00
    AUTH_USER = 0x02
    NO_ACCEPT = 0xFF
    REPLY_OK  = 0x00

    def __init__(self, proxy_host: str = TOR_SOCKS5_HOST,
                 proxy_port: int = TOR_SOCKS5_PORT,
                 username: str = None, password: str = None):
        self.proxy_host = proxy_host
        self.proxy_port = proxy_port
        self.username   = username
        self.password   = password

    def connect(self, dest_host: str, dest_port: int,
                timeout: float = TOR_CONNECT_TIMEOUT) -> Optional[socket.socket]:
        """
        Connect to dest_host:dest_port via SOCKS5 proxy.
        For .onion addresses, hostname is sent to proxy (no local DNS).
        Returns connected socket or None on failure.
        """
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(timeout)
            sock.connect((self.proxy_host, self.proxy_port))

            # Greeting
            methods = [self.AUTH_NONE]
            if self.username:
                methods.append(self.AUTH_USER)
            sock.sendall(bytes([self.VERSION, len(methods)] + methods))

            resp = sock.recv(2)
            if len(resp) < 2 or resp[0] != self.VERSION:
                sock.close(); return None
            chosen = resp[1]

            # Authentication if required
            if chosen == self.AUTH_USER:
                if not self.username or not self.password:
                    sock.close(); return None
                uname = self.username.encode()
                passwd = self.password.encode()
                auth_msg = bytes([0x01, len(uname)]) + uname + bytes([len(passwd)]) + passwd
                sock.sendall(auth_msg)
                auth_resp = sock.recv(2)
                if len(auth_resp) < 2 or auth_resp[1] != 0x00:
                    sock.close(); return None
            elif chosen == self.NO_ACCEPT:
                sock.close(); return None

            # CONNECT request
            host_bytes = dest_host.encode('idna')
            request = (bytes([self.VERSION, self.CMD_CONNECT, 0x00, self.ATYP_HOST,
                              len(host_bytes)]) +
                       host_bytes +
                       struct.pack('>H', dest_port))
            sock.sendall(request)

            # Response
            resp = sock.recv(4)
            if len(resp) < 4 or resp[0] != self.VERSION or resp[1] != self.REPLY_OK:
                sock.close(); return None

            # Skip bound address
            atyp = resp[3]
            if atyp == self.ATYP_IPV4:
                sock.recv(4 + 2)
            elif atyp == self.ATYP_HOST:
                n = sock.recv(1)[0]
                sock.recv(n + 2)
            elif atyp == self.ATYP_IPV6:
                sock.recv(16 + 2)

            sock.settimeout(None)
            return sock
        except Exception:
            return None

    def is_available(self) -> bool:
        """Check if Tor SOCKS5 proxy is reachable"""
        try:
            s = socket.create_connection((self.proxy_host, self.proxy_port), timeout=3)
            s.close()
            return True
        except Exception:
            return False

# ── Tor Control Protocol ──────────────────────────────────────────
class TorController:
    """
    Tor Control Protocol (TC) client.
    Used for: circuit management, hidden service creation,
    stream isolation, new identity requests.
    """

    def __init__(self, host: str = "127.0.0.1",
                 port: int = TOR_CONTROL_PORT,
                 password: str = ""):
        self.host     = host
        self.port     = port
        self.password = password
        self._sock    : Optional[socket.socket] = None
        self._lock    = threading.Lock()
        self._authenticated = False

    def connect(self) -> bool:
        """Connect and authenticate to Tor control port"""
        try:
            self._sock = socket.create_connection(
                (self.host, self.port), timeout=5)
            if self.password:
                self._send(f'AUTHENTICATE "{self.password}"')
            else:
                self._send("AUTHENTICATE")
            resp = self._recv()
            self._authenticated = resp.startswith("250")
            return self._authenticated
        except Exception:
            return False

    def _send(self, cmd: str):
        self._sock.sendall((cmd + "\r\n").encode())

    def _recv(self) -> str:
        buf = b''
        while not buf.endswith(b'\r\n'):
            chunk = self._sock.recv(4096)
            if not chunk: break
            buf += chunk
        return buf.decode(errors='replace').strip()

    def new_identity(self) -> bool:
        """Request new Tor circuit (new IP)"""
        try:
            with self._lock:
                self._send("SIGNAL NEWNYM")
                resp = self._recv()
                return resp.startswith("250")
        except Exception:
            return False

    def get_info(self, key: str) -> Optional[str]:
        """Query Tor for information"""
        try:
            with self._lock:
                self._send(f"GETINFO {key}")
                resp = self._recv()
                if resp.startswith("250"):
                    return resp.split("=", 1)[-1].split("\r\n")[0] if "=" in resp else resp
                return None
        except Exception:
            return None

    def create_hidden_service(self, local_port: int,
                               remote_port: int = None) -> Optional[str]:
        """
        Create ephemeral Tor hidden service (.onion).
        Returns .onion address or None on failure.
        """
        remote_port = remote_port or local_port
        try:
            with self._lock:
                self._send(f"ADD_ONION NEW:BEST Port={remote_port},{local_port}")
                resp = self._recv()
                if "ServiceID=" in resp:
                    for line in resp.split('\n'):
                        if "ServiceID=" in line:
                            onion_id = line.split("=")[1].strip()
                            return f"{onion_id}.onion"
            return None
        except Exception:
            return None

    def list_circuits(self) -> List[dict]:
        """List active Tor circuits"""
        try:
            info = self.get_info("circuit-status")
            circuits = []
            if info:
                for line in info.split('\n'):
                    parts = line.split()
                    if len(parts) >= 2:
                        circuits.append({
                            "id": parts[0],
                            "status": parts[1] if len(parts) > 1 else "UNKNOWN",
                        })
            return circuits
        except Exception:
            return []

    def tor_version(self) -> Optional[str]:
        return self.get_info("version")

    def is_connected(self) -> bool:
        return self._authenticated and self._sock is not None

    def disconnect(self):
        if self._sock:
            try: self._sock.close()
            except Exception: _NB_SWALLOW_LOG.debug("swallowed bare in TorController.disconnect", exc_info=True)
            self._sock = None
        self._authenticated = False

# ── I2P SAM Bridge ───────────────────────────────────────────────
class I2PSAMClient:
    """
    I2P SAM (Simple Anonymous Messaging) bridge client.
    Enables connections to I2P network (.b32.i2p addresses).
    SAM protocol v3.3 — pure TCP-based interface.
    """

    SAM_VERSION = "3.3"

    def __init__(self, host: str = I2P_SAM_HOST,
                 port: int = I2P_SAM_PORT):
        self.host      = host
        self.port      = port
        self._session  : Optional[socket.socket] = None
        self._session_id = f"NEBULA-{secrets.token_hex(8)}"
        self._lock     = threading.Lock()
        self._dest     : Optional[str] = None   # our I2P destination
        self._connected = False

    def connect(self) -> bool:
        """Connect to I2P SAM bridge and create streaming session"""
        try:
            sock = socket.create_connection((self.host, self.port), timeout=10)

            # Handshake
            sock.sendall(f"HELLO VERSION MIN={self.SAM_VERSION} MAX={self.SAM_VERSION}\n".encode())
            resp = sock.recv(256).decode()
            if "RESULT=OK" not in resp:
                sock.close(); return False

            # Create session
            sock.sendall(
                f"SESSION CREATE STYLE=STREAM ID={self._session_id} DESTINATION=TRANSIENT\n".encode())
            resp = sock.recv(1024).decode()
            if "RESULT=OK" not in resp:
                sock.close(); return False

            # Extract our destination
            if "DESTINATION=" in resp:
                for part in resp.split():
                    if part.startswith("DESTINATION="):
                        self._dest = part[12:]

            self._session   = sock
            self._connected = True
            return True
        except Exception:
            return False

    def stream_connect(self, dest_b32: str, port: int = 0) -> Optional[socket.socket]:
        """
        Connect to an I2P destination.
        dest_b32: 52-char base32 address (without .b32.i2p)
        Returns connected socket or None.
        """
        try:
            sock = socket.create_connection((self.host, self.port),
                                             timeout=I2P_CONNECT_TIMEOUT)
            # Handshake
            sock.sendall(f"HELLO VERSION MIN={self.SAM_VERSION} MAX={self.SAM_VERSION}\n".encode())
            resp = sock.recv(256).decode()
            if "RESULT=OK" not in resp:
                sock.close(); return None

            # Connect stream
            full_dest = f"{dest_b32}.b32.i2p" if not dest_b32.endswith('.b32.i2p') else dest_b32
            cmd = f"STREAM CONNECT ID={self._session_id} DESTINATION={full_dest} SILENT=false\n"
            sock.sendall(cmd.encode())
            resp = sock.recv(256).decode(errors='replace')
            if "RESULT=OK" not in resp:
                sock.close(); return None

            return sock
        except Exception:
            return None

    def is_available(self) -> bool:
        """Check if I2P SAM bridge is reachable"""
        try:
            s = socket.create_connection((self.host, self.port), timeout=3)
            s.close()
            return True
        except Exception:
            return False

    @property
    def local_address(self) -> Optional[str]:
        return self._dest

    def disconnect(self):
        if self._session:
            try: self._session.close()
            except Exception: _NB_SWALLOW_LOG.debug("swallowed bare in I2PSAMClient.disconnect", exc_info=True)
            self._session = None
        self._connected = False

# ── Privacy-Aware Connection Manager ──────────────────────────────
class PrivacyConnectionManager:
    """
    Manages connections across multiple networks (clearnet/Tor/I2P).
    Enforces privacy policy: blocks clearnet when TOR_ONLY selected.
    Implements stream isolation per destination.
    """

    def __init__(self, privacy_level: PrivacyLevel = PrivacyLevel.MIXED):
        self.privacy_level = privacy_level
        self.tor           = SOCKS5Client()
        self.tor_ctrl      = TorController()
        self.i2p           = I2PSAMClient()
        self._stats        = PrivacyStats()
        self._onion_addr   : Optional[str] = None
        self._lock         = threading.Lock()

        # Try to detect available networks
        self._tor_available = False
        self._i2p_available = False

    def initialize(self) -> dict:
        """Detect and initialize available privacy networks"""
        self._tor_available = self.tor.is_available()
        self._i2p_available = self.i2p.is_available()

        if self._tor_available:
            self.tor_ctrl.connect()
            # Try to create hidden service for inbound .onion connections
            if self.tor_ctrl.is_connected():
                self._onion_addr = self.tor_ctrl.create_hidden_service(DEFAULT_PORT)

        if self._i2p_available:
            self.i2p.connect()

        return {
            "tor_available"  : self._tor_available,
            "i2p_available"  : self._i2p_available,
            "tor_version"    : self.tor_ctrl.tor_version() if self._tor_available else None,
            "onion_address"  : self._onion_addr,
            "i2p_address"    : self.i2p.local_address,
            "privacy_level"  : self.privacy_level.name,
        }

    def connect_to_peer(self, peer: PeerAddress) -> Optional[socket.socket]:
        """
        Connect to a peer using the appropriate network.
        Respects privacy_level policy.
        """
        with self._lock:
            if peer.is_clearnet and self.privacy_level == PrivacyLevel.TOR_ONLY:
                self._stats.blocked_clearnet += 1
                return None

            if peer.is_onion:
                if not self._tor_available:
                    return None
                sock = self.tor.connect(peer.host + ".onion", peer.port)
                if sock:
                    self._stats.tor_connections += 1
                return sock

            elif peer.is_i2p:
                if not self._i2p_available:
                    return None
                sock = self.i2p.stream_connect(peer.host, peer.port)
                if sock:
                    self._stats.i2p_connections += 1
                return sock

            else:
                # Clearnet
                if self.privacy_level == PrivacyLevel.MIXED and self._tor_available:
                    # Route clearnet through Tor for extra privacy
                    sock = self.tor.connect(peer.host, peer.port)
                    if sock:
                        self._stats.tor_connections += 1
                        return sock
                # Direct connection
                try:
                    sock = socket.create_connection(
                        (peer.host, peer.port), timeout=10)
                    self._stats.clearnet_connections += 1
                    return sock
                except Exception:
                    return None

    def request_new_identity(self) -> bool:
        """Request new Tor circuit (new apparent IP)"""
        if self._tor_available and self.tor_ctrl.is_connected():
            ok = self.tor_ctrl.new_identity()
            if ok:
                self._stats.identity_rotations += 1
            return ok
        return False

    @property
    def onion_address(self) -> Optional[str]:
        return self._onion_addr

    def stats(self) -> dict:
        return self._stats.to_dict()

    def network_status(self) -> dict:
        return {
            "privacy_level"      : self.privacy_level.name,
            "tor_available"      : self._tor_available,
            "i2p_available"      : self._i2p_available,
            "onion_address"      : self._onion_addr,
            "i2p_local_address"  : self.i2p.local_address,
            "tor_circuits"       : len(self.tor_ctrl.list_circuits())
                                   if self.tor_ctrl.is_connected() else 0,
        }

# ── Privacy Statistics ────────────────────────────────────────────
@dataclass
class PrivacyStats:
    tor_connections     : int = 0
    i2p_connections     : int = 0
    clearnet_connections: int = 0
    blocked_clearnet    : int = 0
    identity_rotations  : int = 0
    onion_peers_seen    : int = 0
    i2p_peers_seen      : int = 0

    def to_dict(self) -> dict:
        total = max(1, self.tor_connections + self.i2p_connections + self.clearnet_connections)
        return {
            "tor_connections"      : self.tor_connections,
            "i2p_connections"      : self.i2p_connections,
            "clearnet_connections" : self.clearnet_connections,
            "blocked_clearnet"     : self.blocked_clearnet,
            "identity_rotations"   : self.identity_rotations,
            "tor_pct"              : f"{self.tor_connections/total*100:.1f}%",
            "i2p_pct"              : f"{self.i2p_connections/total*100:.1f}%",
        }

# ── Address Manager (Privacy-Aware) ───────────────────────────────
class PrivacyAwareAddrManager:
    """
    Bitcoin Core-style address manager with privacy network support.
    Separately tracks clearnet, Tor, and I2P peers.
    Implements bucketing to resist Sybil attacks.
    """

    TRIED_BUCKETS    = 256
    NEW_BUCKETS      = 1024
    BUCKET_SIZE      = 64
    MAX_ADDR_AGE     = 30 * 24 * 3600   # 30 days

    def __init__(self):
        self._tried  : Dict[NetworkType, Dict[str, PeerAddress]] = {
            nt: {} for nt in NetworkType}
        self._new    : Dict[NetworkType, Dict[str, PeerAddress]] = {
            nt: {} for nt in NetworkType}
        self._lock   = threading.RLock()
        self._key    = secrets.token_bytes(32)   # for bucket randomization

    def add_address(self, peer: PeerAddress):
        """Add or update a peer address"""
        with self._lock:
            key  = peer.addr_str
            pool = self._new[peer.net_type]
            if key not in pool:
                pool[key] = peer
            else:
                # Update time_seen
                pool[key].time_seen = max(pool[key].time_seen, peer.time_seen)

    def mark_tried(self, peer: PeerAddress):
        """Move peer to tried table after successful connection"""
        with self._lock:
            key = peer.addr_str
            nt  = peer.net_type
            self._new[nt].pop(key, None)
            self._tried[nt][key] = peer

    def select_peer(self, prefer_network: NetworkType = None,
                    tried_only: bool = False) -> Optional[PeerAddress]:
        """Select a peer address to connect to"""
        with self._lock:
            import random
            candidates = []
            nets = [prefer_network] if prefer_network else list(NetworkType)
            for nt in nets:
                pool = self._tried[nt] if tried_only else {
                    **self._tried[nt], **self._new[nt]}
                candidates.extend(pool.values())

            if not candidates:
                return None

            # Weight by recency
            now = time.time()
            weights = [1.0 / max(1, (now - p.time_seen) / 3600 + 1)
                       for p in candidates]
            total = sum(weights)
            r     = random.uniform(0, total)
            acc   = 0
            for p, w in zip(candidates, weights):
                acc += w
                if acc >= r:
                    return p
            return candidates[-1]

    def select_tor_peer(self) -> Optional[PeerAddress]:
        return self.select_peer(NetworkType.ONION)

    def select_i2p_peer(self) -> Optional[PeerAddress]:
        return self.select_peer(NetworkType.I2P)

    def expire_old(self):
        """Remove addresses older than MAX_ADDR_AGE"""
        cutoff = time.time() - self.MAX_ADDR_AGE
        with self._lock:
            for pool in list(self._new.values()) + list(self._tried.values()):
                to_del = [k for k, p in pool.items() if p.time_seen < cutoff]
                for k in to_del:
                    del pool[k]

    def stats(self) -> dict:
        with self._lock:
            return {
                "new_total"    : sum(len(p) for p in self._new.values()),
                "tried_total"  : sum(len(p) for p in self._tried.values()),
                "by_network"   : {
                    nt.value: {
                        "new"   : len(self._new[nt]),
                        "tried" : len(self._tried[nt]),
                    }
                    for nt in NetworkType
                },
            }

    def get_all_addresses(self) -> List[PeerAddress]:
        with self._lock:
            result = []
            for pool in list(self._new.values()) + list(self._tried.values()):
                result.extend(pool.values())
            return result

    def save(self, path: str):
        """Persist address book to disk"""
        addrs = [p.to_dict() for p in self.get_all_addresses()]
        try:
            import json
            with open(path, 'w') as f:
                json.dump(addrs, f, indent=2)
        except Exception:
            _NB_SWALLOW_LOG.warning("swallowed Exception in PrivacyAwareAddrManager.save", exc_info=True)

    def load(self, path: str):
        """Load address book from disk"""
        try:
            import json
            with open(path) as f:
                data = json.load(f)
            for d in data:
                try:
                    peer = PeerAddress.parse(d.get('addr', ''))
                    peer.attempts    = d.get('attempts', 0)
                    peer.last_success= d.get('last_success', 0)
                    peer.source      = d.get('source', 'disk')
                    self.add_address(peer)
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in PrivacyAwareAddrManager.load", exc_info=True)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in PrivacyAwareAddrManager.load", exc_info=True)

