# ================================================================
# MODULE 19  nebula_musig2.py  — Schnorr MuSig2 Multi-Signature
# ================================================================
# BIP327 MuSig2: multi-party Schnorr key aggregation + signing.
# N-of-N multisig with a single aggregated public key on-chain.
# Enables: threshold signatures, Lightning channel funding, privacy.
# ================================================================

import hashlib, secrets, threading
from typing import List, Tuple, Optional, Dict
from dataclasses import dataclass, field

# ── MuSig2 Constants ──────────────────────────────────────────────
MUSIG2_VERSION         = 1
MUSIG2_NONCES_PER_KEY  = 2       # two nonces per signer (R1, R2)
MAX_MUSIG2_SIGNERS     = 999     # practical limit

# ── MuSig2 Tagged Hash ────────────────────────────────────────────
def _musig2_hash(tag: str, data: bytes) -> bytes:
    tag_hash = hashlib.sha256(tag.encode()).digest()
    return hashlib.sha256(tag_hash + tag_hash + data).digest()

# ── Key Aggregation (BIP327 §Key Aggregation) ─────────────────────
class MuSig2KeyAgg:
    """
    MuSig2 key aggregation (BIP327).
    Aggregates N individual public keys into a single combined key.
    The combined key looks like a regular Schnorr key on-chain.
    Prevents rogue-key attacks via key-aggregation coefficient.
    """

    P  = Schnorr.P
    N  = Schnorr.N

    @classmethod
    def _key_agg_coeff(cls, pk_list: List[bytes], pk: bytes) -> int:
        """
        Compute key aggregation coefficient a_i for public key pk.
        a_i = H_agg(L || X_i) where L = hash of all sorted pubkeys.
        """
        L   = _musig2_hash("KeyAgg list", b''.join(sorted(pk_list)))
        h   = _musig2_hash("KeyAgg coefficient", L + pk)
        return int.from_bytes(h, 'big') % cls.N

    @classmethod
    def aggregate(cls, pubkeys: List[bytes]) -> Tuple[bytes, List[int]]:
        """
        Aggregate N public keys into one combined key.
        Returns (combined_xonly_pubkey_32bytes, [coefficients]).
        All pubkeys must be 33-byte compressed format.
        """
        if not pubkeys:
            raise ValueError("Need at least one public key")

        # Sort pubkeys for determinism
        sorted_pks = sorted(pubkeys)
        coeffs     = []
        Q          = None   # accumulated point

        for pk in sorted_pks:
            a_i = cls._key_agg_coeff(sorted_pks, pk)
            coeffs.append(a_i)

            # Decode pubkey to point
            x   = int.from_bytes(pk[1:33], 'big')
            P_  = cls.P
            y_sq = (pow(x, 3, P_) + 7) % P_
            y    = pow(y_sq, (P_+1)//4, P_)
            if (y % 2 == 0) != (pk[0] == 0x02):
                y = P_ - y
            point = (x, y)

            # Q = Q + a_i * P_i
            scaled = Schnorr._point_mul(a_i, point)
            Q      = Schnorr._point_add(Q, scaled)

        if Q is None:
            raise ValueError("Aggregated key is point at infinity")

        # Return x-only (32 bytes)
        combined = Q[0].to_bytes(32, 'big')
        return combined, coeffs

    @classmethod
    def aggregate_with_tweak(cls, pubkeys: List[bytes],
                              tweak: bytes) -> bytes:
        """
        Aggregate keys and apply a Taproot tweak.
        Used for Taproot key path spending with MuSig2.
        """
        combined, _  = cls.aggregate(pubkeys)
        # Apply tweak: Q' = Q + t*G
        t  = int.from_bytes(tweak, 'big') % cls.N
        tG = Schnorr._point_mul(t, Schnorr._G())
        Qx = int.from_bytes(combined, 'big')
        Q  = Schnorr._lift_x(Qx)
        if Q is None: raise ValueError("Invalid combined key")
        Q_tweaked = Schnorr._point_add(Q, tG)
        if Q_tweaked is None: raise ValueError("Tweaked key is infinity")
        return Q_tweaked[0].to_bytes(32, 'big')

