import time, threading, heapq
from typing import Dict, List, Optional, Set, Tuple
from dataclasses import dataclass, field

# ── RBF / CPFP Constants ─────────────────────────────────────────
RBF_SEQUENCE_THRESHOLD  = 0xFFFFFFFE   # signals RBF if sequence < this
MIN_RELAY_FEE_SAT_KB    = 1000         # 1 sat/byte minimum relay
MAX_REPLACEMENT_ANCESTORS = 100        # BIP125 rule 5
CPFP_ANCESTOR_LIMIT     = 25
CPFP_DESCENDANT_LIMIT   = 25
MAX_PACKAGE_SIZE        = 101_000      # bytes
MAX_PACKAGE_COUNT       = 25
MEMPOOL_EXPIRE_HOURS    = 336          # 14 days
FEE_ESTIMATION_BLOCKS   = [1, 2, 3, 6, 12, 24, 48, 144, 504, 1008]

# ── Mempool Transaction Entry ─────────────────────────────────────
@dataclass
class MempoolEntry:
    """
    Full mempool transaction entry with ancestor/descendant tracking.
    Mirrors Bitcoin Core's CTxMemPoolEntry.
    """
    tx            : 'Transaction'
    fee           : int              # absolute fee in neb
    fee_rate      : float            # fee per virtual byte
    time          : float = field(default_factory=time.time)
    height        : int   = 0        # block height when entered pool
    ancestors     : Set[str] = field(default_factory=set)   # ancestor txids
    descendants   : Set[str] = field(default_factory=set)   # descendant txids
    ancestor_fee  : int   = 0        # total ancestor fees
    ancestor_size : int   = 0        # total ancestor vbytes
    is_rbf        : bool  = False    # signals RBF replacement
    package_id    : Optional[str] = None

    @property
    def txid(self) -> str:
        return self.tx.txid

    @property
    def vsize(self) -> int:
        return self.tx.byte_size()   # simplified (no segwit discount)

    @property
    def ancestor_fee_rate(self) -> float:
        """CPFP: effective fee rate including ancestors"""
        total_fee  = self.fee + self.ancestor_fee
        total_size = self.vsize + self.ancestor_size
        return total_fee / max(1, total_size)

    def signals_rbf(self) -> bool:
        """BIP125: tx signals RBF if any input has sequence < 0xFFFFFFFE"""
        return any(inp.sequence < RBF_SEQUENCE_THRESHOLD
                   for inp in self.tx.inputs)

    def to_dict(self) -> dict:
        return {
            "txid"            : self.txid,
            "fee"             : self.fee,
            "fee_rate"        : round(self.fee_rate, 2),
            "ancestor_fee_rate": round(self.ancestor_fee_rate, 2),
            "vsize"           : self.vsize,
            "time"            : self.time,
            "ancestors"       : len(self.ancestors),
            "descendants"     : len(self.descendants),
            "is_rbf"          : self.signals_rbf(),
        }

# ── RBF Validator ────────────────────────────────────────────────
# [v10.17] old dead class RBFValidator removed - replaced by the live RBFValidator (v10.17 block)

# ── CPFP Detector ────────────────────────────────────────────────
class CPFPDetector:
    """
    Child-Pays-For-Parent (CPFP) detection and handling.
    When a low-fee parent tx has a high-fee child, the child
    "pays" for its parent — miners mine both together.
    """

    def __init__(self, pool: Dict[str, MempoolEntry]):
        self._pool = pool

    def find_cpfp_packages(self,
                            min_effective_rate: float = 1.0) -> List[List[str]]:
        """
        Find CPFP packages where child boosts parent above minimum rate.
        Returns list of [parent_txid, child_txid, ...] packages.
        """
        packages = []
        visited  = set()

        for txid, entry in self._pool.items():
            if txid in visited: continue
            if entry.fee_rate >= min_effective_rate: continue

            # This tx has low fee — check if children boost it
            children = entry.descendants
            for child_txid in children:
                child = self._pool.get(child_txid)
                if not child: continue

                # Compute effective rate if mined together
                combined_fee  = entry.fee + child.fee
                combined_size = entry.vsize + child.vsize
                effective     = combined_fee / max(1, combined_size)

                if effective >= min_effective_rate:
                    packages.append([txid, child_txid])
                    visited.update([txid, child_txid])

        return packages

    def compute_ancestor_set(self, txid: str,
                              max_depth: int = CPFP_ANCESTOR_LIMIT) -> Set[str]:
        """Compute full ancestor set for a transaction"""
        ancestors = set()
        queue     = [txid]
        depth     = 0

        while queue and depth < max_depth:
            current = queue.pop(0)
            entry   = self._pool.get(current)
            if not entry: continue
            for inp in entry.tx.inputs:
                parent_txid = inp.outpoint.txid
                if parent_txid in self._pool and parent_txid not in ancestors:
                    ancestors.add(parent_txid)
                    queue.append(parent_txid)
            depth += 1

        return ancestors

    def compute_descendant_set(self, txid: str,
                                max_depth: int = CPFP_DESCENDANT_LIMIT) -> Set[str]:
        """Compute full descendant set for a transaction"""
        descendants = set()
        # Scan all pool txs for those spending our outputs
        our_txid = txid
        for tid, entry in self._pool.items():
            for inp in entry.tx.inputs:
                if inp.outpoint.txid == our_txid:
                    descendants.add(tid)
        return descendants

    def effective_fee_rate(self, txid: str) -> float:
        """Compute effective fee rate including ancestors"""
        entry = self._pool.get(txid)
        if not entry: return 0.0

        ancestors  = self.compute_ancestor_set(txid)
        total_fee  = entry.fee + sum(
            self._pool[a].fee for a in ancestors if a in self._pool)
        total_size = entry.vsize + sum(
            self._pool[a].vsize for a in ancestors if a in self._pool)
        return total_fee / max(1, total_size)

# ── Fee Estimator ─────────────────────────────────────────────────
class FeeEstimator:
    """
    Block-based fee estimation (similar to Bitcoin Core's CBlockPolicyEstimator).
    Tracks fee rates of transactions confirmed in each block.
    Estimates required fee rate for confirmation in N blocks.
    Uses exponential moving average per fee bucket.
    """

    N_BUCKETS     = 50
    BUCKET_MIN    = 1.0     # sat/vbyte
    BUCKET_MAX    = 10_000.0
    DECAY         = 0.998   # per block
    SUCCESS_PCT   = 0.95    # 95% success rate target
    MIN_SAMPLES   = 5.0     # v10.11: fewer decayed samples than this -> "no estimate" (None)

    def __init__(self):
        # Log-scale fee buckets
        import math
        self._buckets = [
            self.BUCKET_MIN * (self.BUCKET_MAX / self.BUCKET_MIN) ** (i / self.N_BUCKETS)
            for i in range(self.N_BUCKETS + 1)
        ]
        # Per-bucket stats: (success_count, total_count, avg_fee_rate)
        self._confirmed : List[List[float]] = [
            [0.0, 0.0, 0.0] for _ in range(self.N_BUCKETS)
        ]
        self._unconfirmed: List[List[float]] = [
            [0.0, 0.0, 0.0] for _ in range(self.N_BUCKETS)
        ]
        # v10.11: per confirmation-target statistics (bucket -> confirmed-within-target / seen)
        self._tgt_ok : Dict[int, List[float]] = {
            t: [0.0] * self.N_BUCKETS for t in FEE_ESTIMATION_BLOCKS}
        self._tgt_tot: Dict[int, List[float]] = {
            t: [0.0] * self.N_BUCKETS for t in FEE_ESTIMATION_BLOCKS}
        self._lock  = threading.Lock()
        self._best_height = 0

    def _bucket_index(self, fee_rate: float) -> int:
        """Find which bucket a fee_rate falls into"""
        for i in range(self.N_BUCKETS - 1, -1, -1):
            if fee_rate >= self._buckets[i]:
                return i
        return 0

    def record_confirmed(self, fee_rate: float, blocks_waited: int = 1):
        """Record a confirmed transaction for fee estimation.
        v10.11: blocks_waited is now used - the tx counts as a success for every target >= blocks_waited."""
        idx = self._bucket_index(fee_rate)
        w = max(1, int(blocks_waited))
        with self._lock:
            self._confirmed[idx][0] += 1.0   # success
            self._confirmed[idx][1] += 1.0   # total
            self._confirmed[idx][2] = (
                self._confirmed[idx][2] * 0.9 + fee_rate * 0.1)
            for t in self._tgt_tot:
                if w <= t:
                    self._tgt_ok[t][idx]  += 1.0
                    self._tgt_tot[t][idx] += 1.0

    def record_unconfirmed(self, fee_rate: float, blocks_waited: int = 0):
        """Record a transaction that is STILL unconfirmed after `blocks_waited` blocks.
        v10.11: it counts as a miss for the target that equals blocks_waited (call it once per block
        of waiting; legacy callers pass nothing and only bump the old counter)."""
        idx = self._bucket_index(fee_rate)
        with self._lock:
            self._unconfirmed[idx][1] += 1.0
            w = int(blocks_waited)
            if w in self._tgt_tot:
                self._tgt_tot[w][idx] += 1.0

    def decay_all(self):
        """Apply per-block decay to all buckets"""
        with self._lock:
            for i in range(self.N_BUCKETS):
                self._confirmed[i][0]  *= self.DECAY
                self._confirmed[i][1]  *= self.DECAY
                self._unconfirmed[i][1] *= self.DECAY
            for t in self._tgt_tot:
                ok, tot = self._tgt_ok[t], self._tgt_tot[t]
                for i in range(self.N_BUCKETS):
                    ok[i]  *= self.DECAY
                    tot[i] *= self.DECAY

    def _pick_target(self, target_blocks: int) -> int:
        ts = sorted(self._tgt_tot)
        for t in ts:
            if t >= target_blocks:
                return t
        return ts[-1]

    def samples(self, target_blocks: int = 6) -> float:
        """v10.11: how many (decayed) observations back the estimate for this target."""
        with self._lock:
            return float(sum(self._tgt_tot[self._pick_target(target_blocks)]))

    def estimate_fee(self, target_blocks: int) -> Optional[float]:
        """
        Estimate fee rate (neb/byte) to confirm within target_blocks: the LOWEST fee-rate threshold
        such that transactions paying at least that much confirmed in time >= SUCCESS_PCT of the time.
        Returns None if there is not enough data.
        (v10.11: this used to return the HIGHEST bucket that had any data and ignored the target.)
        """
        with self._lock:
            t = self._pick_target(target_blocks)
            ok, tot = self._tgt_ok[t], self._tgt_tot[t]
            s_cum = n_cum = 0.0
            best = None
            for i in range(self.N_BUCKETS - 1, -1, -1):
                s_cum += ok[i]
                n_cum += tot[i]
                if n_cum >= self.MIN_SAMPLES:
                    if s_cum / n_cum >= self.SUCCESS_PCT:
                        if tot[i] > 0:          # only a rate we have actually OBSERVED can be the answer
                            best = i
                    else:
                        break
            return self._buckets[best] if best is not None else None

    def smart_fee(self, target_blocks: int, conservative: bool = False) -> int:
        """
        Smart fee estimate in sat/vbyte.
        conservative=True: uses higher percentile for reliability.
        Returns minimum relay fee if insufficient data.
        """
        rate = self.estimate_fee(target_blocks)
        if rate is None:
            return MIN_RELAY_FEE_SAT_KB // 1000

        if conservative:
            rate *= 1.2   # 20% safety margin

        return max(1, int(rate))

    def fee_table(self) -> dict:
        """Fee estimates for all standard confirmation targets"""
        return {
            f"{blocks} blocks": self.smart_fee(blocks)
            for blocks in FEE_ESTIMATION_BLOCKS
        }

# ── Advanced Mempool ─────────────────────────────────────────────
class AdvancedMempool:
    """
    Production-grade mempool with RBF, CPFP, fee estimation.
    Drop-in replacement for the basic Mempool class.
    Features:
    - BIP125 RBF replacement validation
    - CPFP ancestor/descendant tracking
    - Package relay (BIP331)
    - Fee market estimation
    - Mempool expiry (14 days)
    - Dynamic minimum fee based on mempool size
    """

    def __init__(self, utxo: 'UTXOSet',
                 max_size_mb: float = 300.0):
        self._txs          : Dict[str, MempoolEntry] = {}
        self._utxo         = utxo
        self._fee_estimator = FeeEstimator()
        self._cpfp         : Optional[CPFPDetector] = None
        self._lock         = threading.RLock()
        self._max_bytes    = int(max_size_mb * 1024 * 1024)
        self._current_bytes= 0
        self._dynamic_min_fee = MIN_TX_FEE
        self._last_expire  = time.time()

    # ── Submission ───────────────────────────────────────────────
    def submit(self, tx: 'Transaction') -> Tuple[bool, str]:
        """Submit transaction to mempool with full validation"""
        with self._lock:
            if tx.txid in self._txs:
                return False, "Already in mempool"
            if tx.is_coinbase:
                return False, "Coinbase not accepted"

            # Basic validation
            ok, reason = self._validate_basic(tx)
            if not ok:
                return False, reason

            fee  = tx.fee(self._utxo)
            vsize = tx.byte_size()
            fee_rate = fee / max(1, vsize)

            # Dynamic minimum fee
            if fee < self._dynamic_min_fee:
                return False, f"Fee too low: {fee} < {self._dynamic_min_fee}"

            # Check for RBF replacement
            conflicts = self._find_conflicts(tx)
            if conflicts:
                ok, reason = RBFValidator.validate(tx, conflicts, fee, vsize, self._utxo)
                if not ok:
                    return False, f"RBF rejected: {reason}"
                # Remove conflicting txs
                for entry in conflicts:
                    self._remove_entry(entry.txid)

            # Check mempool size limit
            if self._current_bytes + vsize > self._max_bytes:
                self._trim_to_size(vsize)
                if self._current_bytes + vsize > self._max_bytes:
                    return False, "Mempool full"

            # Compute ancestors/descendants
            cpfp = CPFPDetector(self._txs)
            ancestors   = cpfp.compute_ancestor_set(tx.txid)
            anc_fee     = sum(self._txs[a].fee for a in ancestors if a in self._txs)
            anc_size    = sum(self._txs[a].vsize for a in ancestors if a in self._txs)

            # Add entry
            entry = MempoolEntry(
                tx            = tx,
                fee           = fee,
                fee_rate      = fee_rate,
                height        = 0,
                ancestors     = ancestors,
                ancestor_fee  = anc_fee,
                ancestor_size = anc_size,
                is_rbf        = any(inp.sequence < RBF_SEQUENCE_THRESHOLD
                                    for inp in tx.inputs),
            )
            self._txs[tx.txid] = entry
            self._current_bytes += vsize

            # Update descendants of our ancestors
            for anc_txid in ancestors:
                if anc_txid in self._txs:
                    self._txs[anc_txid].descendants.add(tx.txid)

            # Record for fee estimation
            self._fee_estimator.record_unconfirmed(fee_rate)

            return True, "Accepted"

    def _validate_basic(self, tx: 'Transaction') -> Tuple[bool, str]:
        if not tx.inputs or not tx.outputs:
            return False, "Empty inputs or outputs"
        for out in tx.outputs:
            if out.value < DUST_THRESHOLD:
                return False, f"Dust output: {out.value}"
        for inp in tx.inputs:
            if not self._utxo.has(inp.outpoint.txid, inp.outpoint.index):
                if inp.outpoint.txid not in self._txs:
                    return False, f"UTXO not found: {inp.outpoint.txid[:8]}"
        return True, "OK"

    def _find_conflicts(self, tx: 'Transaction') -> List[MempoolEntry]:
        """Find mempool transactions spending the same inputs (conflicts)"""
        conflicts = []
        for inp in tx.inputs:
            key = f"{inp.outpoint.txid}:{inp.outpoint.index}"
            for entry in self._txs.values():
                for e_inp in entry.tx.inputs:
                    e_key = f"{e_inp.outpoint.txid}:{e_inp.outpoint.index}"
                    if key == e_key:
                        if entry not in conflicts:
                            conflicts.append(entry)
        return conflicts

    def _remove_entry(self, txid: str):
        entry = self._txs.pop(txid, None)
        if entry:
            self._current_bytes -= entry.vsize
            # Clean up descendant references
            for anc in entry.ancestors:
                if anc in self._txs:
                    self._txs[anc].descendants.discard(txid)

    def _trim_to_size(self, needed: int):
        """Evict lowest fee-rate transactions to make room"""
        sorted_entries = sorted(self._txs.values(), key=lambda e: e.fee_rate)
        for entry in sorted_entries:
            if self._current_bytes + needed <= self._max_bytes:
                break
            self._remove_entry(entry.txid)
            self._dynamic_min_fee = max(MIN_TX_FEE, int(entry.fee_rate))

    # ── Block processing ─────────────────────────────────────────
    def remove_block_txs(self, block: 'Block'):
        """Remove confirmed transactions and update fee estimator"""
        with self._lock:
            for tx in block.transactions:
                entry = self._txs.pop(tx.txid, None)
                if entry:
                    self._current_bytes -= entry.vsize
                    blocks_waited = 1   # simplified
                    self._fee_estimator.record_confirmed(
                        entry.fee_rate, blocks_waited)
            self._fee_estimator.decay_all()
            self._expire_old()

    def _expire_old(self):
        """Expire transactions older than MEMPOOL_EXPIRE_HOURS"""
        cutoff = time.time() - MEMPOOL_EXPIRE_HOURS * 3600
        to_remove = [txid for txid, e in self._txs.items()
                     if e.time < cutoff]
        for txid in to_remove:
            self._remove_entry(txid)

    # ── Queries ───────────────────────────────────────────────────
    def get_for_block(self, max_bytes: int = MAX_BLOCK_SIZE_BYTES) -> List['Transaction']:
        """Get highest effective-fee transactions for block template"""
        with self._lock:
            cpfp     = CPFPDetector(self._txs)
            entries  = sorted(self._txs.values(),
                              key=lambda e: cpfp.effective_fee_rate(e.txid),
                              reverse=True)
            selected = []
            total    = 0
            for entry in entries:
                if total + entry.vsize > max_bytes:
                    continue
                if len(selected) >= MAX_TX_PER_BLOCK:
                    break
                selected.append(entry.tx)
                total += entry.vsize
            return selected

    def size(self) -> int:
        return len(self._txs)

    def total_fees(self) -> int:
        return sum(e.fee for e in self._txs.values())

    def memory_usage_mb(self) -> float:
        return self._current_bytes / 1024 / 1024

    def get_entry(self, txid: str) -> Optional[MempoolEntry]:
        return self._txs.get(txid)

    def fee_estimates(self) -> dict:
        return self._fee_estimator.fee_table()

    def smart_fee(self, target_blocks: int = 6) -> int:
        return self._fee_estimator.smart_fee(target_blocks)

    def stats(self) -> dict:
        with self._lock:
            return {
                "count"          : len(self._txs),
                "size_mb"        : round(self.memory_usage_mb(), 3),
                "max_mb"         : self._max_bytes / 1024 / 1024,
                "total_fees_nbl" : f"{self.total_fees()/10**DECIMALS:.9f}",
                "min_fee_rate"   : self._dynamic_min_fee,
                "fee_estimates"  : self.fee_estimates(),
                "rbf_txs"        : sum(1 for e in self._txs.values() if e.is_rbf),
            }

    def get_all(self) -> List[MempoolEntry]:
        with self._lock:
            return list(self._txs.values())

# (Advanced Mempool — RBF/CPFP/Fee — MODULE 20)


# ================================================================
# MODULE 21  nebula_spv.py  — SPV + BIP37 Bloom Filters
# ================================================================
# Simplified Payment Verification: light clients verify payments
# without downloading full blockchain. Bloom filters for privacy.
# ================================================================

import hashlib, struct, math, threading, time
from typing import List, Optional, Set, Tuple, Dict

# ── SPV Constants ─────────────────────────────────────────────────
MAX_BLOOM_FILTER_SIZE  = 36_000   # bytes
MAX_HASH_FUNCS         = 50
BLOOM_UPDATE_NONE      = 0
BLOOM_UPDATE_ALL       = 1
BLOOM_UPDATE_P2PUBKEY_ONLY = 2
SPV_MAX_HEADERS        = 2000     # max headers per getblockheaders
MERKLE_PROOF_MAX_DEPTH = 30

# ── Bloom Filter (BIP37) ──────────────────────────────────────────
class BloomFilterLegacy:
    """[v10.17] OLD implementation kept ONLY for old stand-alone callers (their API differs from the live BloomFilter)."""
    """
    BIP37 Bloom filter for SPV transaction filtering.
    Allows SPV clients to receive only relevant transactions from full nodes.
    False positive rate is tunable — lower rate = larger filter.
    """

    LN2_SQUARED = math.log(2) ** 2
    LN2         = math.log(2)
    MAX_SIZE    = MAX_BLOOM_FILTER_SIZE
    MAX_FUNCS   = MAX_HASH_FUNCS

    def __init__(self, n_elements: int, fp_rate: float = 0.001,
                 tweak: int = 0, flags: int = BLOOM_UPDATE_ALL):
        """
        n_elements: expected number of elements to insert
        fp_rate:    desired false-positive rate (0.001 = 0.1%)
        tweak:      random nonce for hash function variation
        """
        # Optimal filter size
        filter_bytes = min(
            self.MAX_SIZE,
            int(-1.0 / self.LN2_SQUARED * n_elements * math.log(fp_rate) / 8) + 1
        )
        self.n_hash_funcs = min(
            self.MAX_FUNCS,
            int(filter_bytes * 8 / n_elements * self.LN2 + 0.5)
        )
        self.tweak   = tweak
        self.flags   = flags
        self._data   = bytearray(filter_bytes)
        self._lock   = threading.Lock()

    def _hash(self, seed: int, data: bytes) -> int:
        """MurmurHash3 (32-bit) used by BIP37"""
        c1, c2 = 0xcc9e2d51, 0x1b873593
        h = seed & 0xFFFFFFFF
        data = data + b'\x00' * ((-len(data)) % 4)
        for i in range(0, len(data), 4):
            k = struct.unpack_from('<I', data, i)[0]
            k = (k * c1) & 0xFFFFFFFF
            k = ((k << 15) | (k >> 17)) & 0xFFFFFFFF
            k = (k * c2) & 0xFFFFFFFF
            h ^= k
            h = ((h << 13) | (h >> 19)) & 0xFFFFFFFF
            h = (h * 5 + 0xe6546b64) & 0xFFFFFFFF
        h ^= len(data)
        h ^= h >> 16; h = (h * 0x85ebca6b) & 0xFFFFFFFF
        h ^= h >> 13; h = (h * 0xc2b2ae35) & 0xFFFFFFFF
        h ^= h >> 16
        return h

    def _bit_index(self, func_idx: int, data: bytes) -> int:
        seed = (func_idx * 0xFBA4C795 + self.tweak) & 0xFFFFFFFF
        return self._hash(seed, data) % (len(self._data) * 8)

    def insert(self, data: bytes):
        """Insert element into filter"""
        with self._lock:
            for i in range(self.n_hash_funcs):
                idx = self._bit_index(i, data)
                self._data[idx >> 3] |= (1 << (idx & 7))

    def contains(self, data: bytes) -> bool:
        """Test if element might be in filter (no false negatives)"""
        with self._lock:
            for i in range(self.n_hash_funcs):
                idx = self._bit_index(i, data)
                if not (self._data[idx >> 3] & (1 << (idx & 7))):
                    return False
            return True

    def insert_address(self, address: str):
        """Insert a NEBULA address into the filter"""
        try:
            _, h160 = base58check_decode(address)
            self.insert(h160)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in BloomFilterLegacy.insert_address", exc_info=True)

    def insert_txid(self, txid: str):
        """Insert transaction ID (big-endian bytes)"""
        self.insert(bytes.fromhex(txid)[::-1])

    def insert_outpoint(self, txid: str, vout: int):
        """Insert an outpoint (txid:vout)"""
        data = bytes.fromhex(txid)[::-1] + struct.pack('<I', vout)
        self.insert(data)

    def matches_tx(self, tx: 'Transaction') -> bool:
        """
        Check if transaction matches this bloom filter.
        Checks: txid, outputs (addresses), inputs (outpoints).
        """
        # Check txid
        if self.contains(bytes.fromhex(tx.txid)[::-1]):
            return True

        # Check outputs
        for out in tx.outputs:
            if self.contains(out.script_pubkey):
                return True
            if out.address:
                try:
                    _, h160 = base58check_decode(out.address)
                    if self.contains(h160):
                        return True
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in BloomFilterLegacy.matches_tx", exc_info=True)

        # Check inputs (outpoints)
        for inp in tx.inputs:
            op = (bytes.fromhex(inp.outpoint.txid)[::-1] +
                  struct.pack('<I', inp.outpoint.index))
            if self.contains(op):
                return True

        return False

    def serialize(self) -> bytes:
        """BIP37 filterload payload"""
        return (encode_varint(len(self._data)) +
                bytes(self._data) +
                struct.pack('<I', self.n_hash_funcs) +
                struct.pack('<I', self.tweak) +
                bytes([self.flags]))

    @classmethod
    def deserialize(cls, data: bytes) -> 'BloomFilter':
        """Deserialize BIP37 filterload payload"""
        n, offset   = decode_varint(data, 0)
        filter_data = data[offset:offset+n]
        offset     += n
        n_funcs     = struct.unpack_from('<I', data, offset)[0]
        tweak       = struct.unpack_from('<I', data, offset+4)[0]
        flags       = data[offset+8]
        bf          = cls.__new__(cls)
        bf._data    = bytearray(filter_data)
        bf.n_hash_funcs = n_funcs
        bf.tweak    = tweak
        bf.flags    = flags
        bf._lock    = threading.Lock()
        return bf

    def false_positive_rate(self, n_elements: int) -> float:
        """Estimated false positive rate for n_elements inserted"""
        n_bits = len(self._data) * 8
        p = (1 - math.exp(-self.n_hash_funcs * n_elements / n_bits)) ** self.n_hash_funcs
        return p

    def stats(self) -> dict:
        bits_set = sum(bin(b).count('1') for b in self._data)
        return {
            "size_bytes"     : len(self._data),
            "n_hash_funcs"   : self.n_hash_funcs,
            "tweak"          : self.tweak,
            "bits_set"       : bits_set,
            "saturation"     : f"{bits_set / (len(self._data)*8)*100:.1f}%",
        }

