# ── BIP157/158 Compact Block Filters ─────────────────────────────
class GCSFilter:
    """
    Golomb-Coded Set filter (BIP158).
    More efficient than BIP37 bloom filters.
    Used in BIP157 compact block filter protocol.
    """

    P = 19    # false positive rate = 1/(2^P) = 1 in 524288
    M = 784931  # chosen for ~1/(M) FP rate per element

    def __init__(self, key: bytes, elements: List[bytes]):
        self.key = key
        n        = len(elements)
        F        = n * self.M

        # Hash and sort elements
        hashes = sorted(set(self._siphash(key, e) % F for e in elements))
        self.n       = n
        self._hashes = hashes

        # Golomb-encode
        self._data   = self._encode(hashes)

    def _siphash(self, key: bytes, data: bytes) -> int:
        """SipHash-2-4 (simplified using SHA256 for portability)"""
        k0 = int.from_bytes(key[:8],  'little')
        k1 = int.from_bytes(key[8:16],'little') if len(key) >= 16 else 0
        h  = hashlib.sha256(key + data).digest()
        return int.from_bytes(h[:8], 'little') & 0xFFFFFFFFFFFFFFFF

    def _encode(self, hashes: List[int]) -> bytes:
        """Golomb-Rice encode sorted hash values"""
        bits = []
        prev = 0
        for h in hashes:
            delta = h - prev
            prev  = h
            q     = delta >> self.P
            r     = delta & ((1 << self.P) - 1)
            # Unary encode quotient
            bits.extend([1] * q + [0])
            # Binary encode remainder
            for i in range(self.P - 1, -1, -1):
                bits.append((r >> i) & 1)

        # Pack bits to bytes
        result = bytearray()
        for i in range(0, len(bits), 8):
            byte = 0
            for j, b in enumerate(bits[i:i+8]):
                byte |= b << (7 - j)
            result.append(byte)
        return bytes(result)

    def contains(self, key: bytes, element: bytes) -> bool:
        """Test if element is in filter"""
        F   = self.n * self.M
        h   = self._siphash(key, element) % F
        return h in self._hashes   # simplified linear scan

    @property
    def size_bytes(self) -> int:
        return len(self._data)

class CompactBlockFilter:
    """
    BIP157/158 compact block filter.
    Basic filter (type 0): contains all scriptPubKeys and input outpoints.
    Allows clients to determine if a block contains relevant transactions.
    """

    FILTER_TYPE_BASIC = 0

    @classmethod
    def build_basic(cls, block: 'Block') -> 'CompactBlockFilter':
        """Build basic block filter from block"""
        key = bytes.fromhex(block.hash)[:16]   # first 16 bytes of block hash

        elements = []
        for tx in block.transactions:
            # All scriptPubKeys
            for out in tx.outputs:
                if out.script_pubkey:
                    elements.append(out.script_pubkey)
            # All input outpoints (except coinbase)
            if not tx.is_coinbase:
                for inp in tx.inputs:
                    op = bytes.fromhex(inp.outpoint.txid)[::-1] + struct.pack('<I', inp.outpoint.index)
                    elements.append(op)

        gcs = GCSFilter(key, elements) if elements else None
        f   = cls.__new__(cls)
        f.block_hash   = block.hash
        f.block_height = block.height
        f.filter_type  = cls.FILTER_TYPE_BASIC
        f.gcs          = gcs
        f.key          = key
        return f

    def match(self, address: str) -> bool:
        """Check if filter matches an address"""
        if not self.gcs: return False
        try:
            script = Script.p2pkh_locking_from_address(address)
            return self.gcs.contains(self.key, script)
        except Exception:
            return False

    def match_outpoint(self, txid: str, vout: int) -> bool:
        """Check if filter matches an outpoint"""
        if not self.gcs: return False
        op = bytes.fromhex(txid)[::-1] + struct.pack('<I', vout)
        return self.gcs.contains(self.key, op)

    def to_dict(self) -> dict:
        return {
            "block_hash"  : self.block_hash,
            "block_height": self.block_height,
            "filter_type" : self.filter_type,
            "size_bytes"  : self.gcs.size_bytes if self.gcs else 0,
            "n_elements"  : self.gcs.n if self.gcs else 0,
        }

