import json, threading, time, hashlib, struct
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Dict, Callable, Any, Optional, List, Tuple

# ── RPC Constants ─────────────────────────────────────────────────
JSONRPC_VERSION     = "2.0"
RPC_DEFAULT_PORT    = 8332
MAX_REQUEST_SIZE    = 4 * 1024 * 1024   # 4 MB

# ── RPC Error Codes ───────────────────────────────────────────────
# ── FIX v10.6: raw tx / block parsers (exact inverse of serialize()) ──────────
def _take(raw: bytes, pos: int, k: int):
    if k < 0 or pos + k > len(raw):
        raise ValueError("truncated data")
    return raw[pos:pos + k], pos + k

def _read_varint_checked(raw: bytes, pos: int):
    if pos >= len(raw):
        raise ValueError("truncated data")
    first = raw[pos]
    size  = {0xfd: 2, 0xfe: 4, 0xff: 8}.get(first)
    if size is None:
        return first, pos + 1
    b, pos2 = _take(raw, pos + 1, size)
    v = int.from_bytes(b, 'little')
    if (first == 0xfd and v < 0xfd) or (first == 0xfe and v <= 0xffff) or \
       (first == 0xff and v <= 0xffffffff):
        raise ValueError("non-canonical varint")
    return v, pos2

def parse_raw_tx(raw: bytes, pos: int = 0):
    """Parse one transaction from raw bytes -> (Transaction, new_pos). Raises ValueError."""
    b, pos = _take(raw, pos, 4)
    version = struct.unpack('<i', b)[0]
    n_in, pos = _read_varint_checked(raw, pos)
    if n_in > len(raw) - pos:
        raise ValueError("bad input count")
    inputs = []
    for _ in range(n_in):
        b, pos = _take(raw, pos, 32); txid = b[::-1].hex()
        b, pos = _take(raw, pos, 4);  idx  = struct.unpack('<I', b)[0]
        ln, pos = _read_varint_checked(raw, pos)
        sig, pos = _take(raw, pos, ln)
        b, pos = _take(raw, pos, 4);  seq  = struct.unpack('<I', b)[0]
        inputs.append(TxInput(OutPoint(txid, idx), sig, seq))
    n_out, pos = _read_varint_checked(raw, pos)
    if n_out > len(raw) - pos:
        raise ValueError("bad output count")
    outputs = []
    for _ in range(n_out):
        b, pos = _take(raw, pos, 8);  val = struct.unpack('<q', b)[0]
        ln, pos = _read_varint_checked(raw, pos)
        spk, pos = _take(raw, pos, ln)
        outputs.append(TxOutput(val, spk))
    b, pos = _take(raw, pos, 4)
    locktime = struct.unpack('<I', b)[0]
    return Transaction(version=version, inputs=inputs, outputs=outputs, locktime=locktime), pos

def parse_raw_block(raw: bytes, chain: 'NEBULABlockchain') -> 'Block':
    """Parse 80-byte header + varint tx count + txs. Height is derived from the parent
    (it is not part of the raw header). Raises LookupError if the parent is unknown."""
    hdr, pos = _take(raw, 0, 80)
    version = struct.unpack('<i', hdr[0:4])[0]
    prev    = hdr[4:36][::-1].hex()
    merkle  = hdr[36:68][::-1].hex()
    ts, bits, nonce = struct.unpack('<III', hdr[68:80])
    parent = chain.get_block_by_hash(prev)
    if parent is None:
        raise LookupError("prev-blk-not-found")
    n_tx, pos = _read_varint_checked(raw, pos)
    if n_tx == 0 or n_tx > MAX_TX_PER_BLOCK:
        raise ValueError("bad transaction count")
    txs = []
    for _ in range(n_tx):
        start = pos
        tx, pos = parse_raw_tx(raw, pos)
        if tx.serialize() != raw[start:pos]:
            raise ValueError("non-canonical transaction encoding")
        txs.append(tx)
    if pos != len(raw):
        raise ValueError("trailing bytes after block")
    return Block(BlockHeader(version, prev, merkle, ts, bits, nonce, parent.height + 1), txs)

class RPCError(Exception):
    def __init__(self, code: int, message: str, data=None):
        self.code    = code
        self.message = message
        self.data    = data
        super().__init__(message)

# Standard JSON-RPC errors
RPC_PARSE_ERROR         = RPCError(-32700, "Parse error")
RPC_INVALID_REQUEST     = RPCError(-32600, "Invalid Request")
RPC_METHOD_NOT_FOUND    = RPCError(-32601, "Method not found")
RPC_INVALID_PARAMS      = RPCError(-32602, "Invalid params")
RPC_INTERNAL_ERROR      = RPCError(-32603, "Internal error")

# Bitcoin-compatible application errors
RPC_MISC_ERROR          = -1
RPC_TYPE_ERROR          = -3
RPC_INVALID_ADDRESS     = -5
RPC_FORBIDDEN_BY_SAFE   = -8
RPC_OUT_OF_MEMORY       = -7
RPC_INVALID_PARAM       = -8
RPC_DATABASE_ERROR      = -20
RPC_DESERIALIZATION_ERR = -22
RPC_VERIFY_ERROR        = -25
RPC_VERIFY_REJECTED     = -26
RPC_VERIFY_ALREADY_IN   = -27
RPC_IN_WARMUP           = -28
RPC_METHOD_DEPRECATED   = -32

# ── RPC Method Registry ───────────────────────────────────────────
class RPCRegistry:
    """Central registry for all JSON-RPC methods"""

    def __init__(self):
        self._methods  : Dict[str, Callable] = {}
        self._help     : Dict[str, str]      = {}
        self._categories: Dict[str, List[str]] = {}

    def register(self, name: str, func: Callable,
                 category: str = "misc", help_text: str = ""):
        self._methods[name]  = func
        self._help[name]     = help_text
        self._categories.setdefault(category, []).append(name)

    def call(self, method: str, params) -> Any:
        if method not in self._methods:
            raise RPCError(-32601, f"Method not found: {method}")
        fn = self._methods[method]
        if isinstance(params, list):
            return fn(*params)
        elif isinstance(params, dict):
            return fn(**params)
        else:
            return fn()

    def list_methods(self) -> List[str]:
        return sorted(self._methods.keys())

    def get_help(self, method: str) -> str:
        return self._help.get(method, "No help available")

    def method_count(self) -> int:
        return len(self._methods)

# ── RPC Handler ───────────────────────────────────────────────────
class NEBULARPCHandler(BaseHTTPRequestHandler):
    """HTTP handler for JSON-RPC requests"""

    server_instance: 'NEBULAJSONRPCServer' = None

    def log_message(self, fmt, *args): pass

    def do_POST(self):
        try:
            length = int(self.headers.get('Content-Length', 0))
            if length > MAX_REQUEST_SIZE:
                self._respond_error(413, "Request too large")
                return

            body = self.rfile.read(length)

            # Auth check
            if self.server_instance.rpc_password:
                auth = self.headers.get('Authorization', '')
                if not self._check_auth(auth):
                    self.send_response(401)
                    self.send_header('WWW-Authenticate', 'Basic realm="jsonrpc"')
                    self.end_headers()
                    return

            try:
                data = json.loads(body.decode('utf-8'))
            except json.JSONDecodeError:
                self._respond({"jsonrpc": JSONRPC_VERSION, "id": None,
                               "error": {"code": -32700, "message": "Parse error"}})
                return

            # Handle batch requests
            if isinstance(data, list):
                responses = [self._process_single(req) for req in data]
                self._respond(responses)
            else:
                self._respond(self._process_single(data))

        except Exception as e:
            self._respond({"jsonrpc": JSONRPC_VERSION, "id": None,
                           "error": {"code": -32603, "message": str(e)}})

    def _process_single(self, req: dict) -> dict:
        req_id  = req.get('id')
        method  = req.get('method', '')
        params  = req.get('params', [])

        try:
            result = self.server_instance.registry.call(method, params)
            return {"jsonrpc": JSONRPC_VERSION, "id": req_id,
                    "result": result, "error": None}
        except RPCError as e:
            return {"jsonrpc": JSONRPC_VERSION, "id": req_id,
                    "result": None, "error": {"code": e.code, "message": e.message}}
        except Exception as e:
            return {"jsonrpc": JSONRPC_VERSION, "id": req_id,
                    "result": None, "error": {"code": -32603, "message": str(e)}}

    def _check_auth(self, auth_header: str) -> bool:
        import base64
        if not auth_header.startswith('Basic '):
            return False
        try:
            decoded = base64.b64decode(auth_header[6:]).decode()
            user, pw = decoded.split(':', 1)
            import hmac as _hm   # [v10.24] constant-time comparison
            return (_hm.compare_digest(user.encode(), str(self.server_instance.rpc_user).encode()) and
                    _hm.compare_digest(pw.encode(), str(self.server_instance.rpc_password).encode()))
        except Exception:
            return False

    def _respond(self, data):
        body = json.dumps(data, default=str).encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        self.wfile.write(body)

    def _respond_error(self, code, message):
        self.send_response(code)
        self.end_headers()
        self.wfile.write(message.encode())

    def do_GET(self):
        if self.path == '/':
            methods = self.server_instance.registry.list_methods()
            body = json.dumps({"methods": methods,
                               "count": len(methods)}).encode()
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'POST, GET, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        self.end_headers()

# ── NEBULA JSON-RPC Server ────────────────────────────────────────
class NEBULAJSONRPCServerLegacy:
    """[v10.17] OLD implementation kept ONLY for old stand-alone callers (their API differs from the live NEBULAJSONRPCServer)."""
    """
    Full Bitcoin-compatible JSON-RPC server for NEBULA.
    Implements 200+ RPC methods across all categories:
    - Blockchain: getblock, getblockcount, getblockhash, etc.
    - Wallet: getbalance, sendtoaddress, getnewaddress, etc.
    - Mining: getblocktemplate, submitblock, getmininginfo, etc.
    - Network: getnetworkinfo, getpeerinfo, addnode, etc.
    - Raw transactions: createrawtransaction, signrawtransaction, etc.
    - Utility: validateaddress, estimatesmartfee, etc.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 host: str = "127.0.0.1",
                 port: int = RPC_DEFAULT_PORT,
                 rpc_user: str = "nebula",
                 rpc_password: str = (os.environ.get("NEBULA_RPC_PASSWORD") or __import__("secrets").token_urlsafe(24))):  # [v10.24] no well-known default password
        self.bc           = blockchain
        self.host         = host
        self.port         = port
        self.rpc_user     = rpc_user
        self.rpc_password = rpc_password
        self.registry     = RPCRegistry()
        self._server      : Optional[HTTPServer] = None
        self._thread      : Optional[threading.Thread] = None
        self._running     = False
        self._wallet      : Optional['NEBULAWallet'] = None
        self._p2p         = None    # FIX v10.6: set to a P2PNode to relay blocks/txs submitted over RPC
        self._start_time  = time.time()

        self._register_all_methods()

    def _register_all_methods(self):
        """Register all 200+ RPC methods"""
        reg = self.registry

        # ── Blockchain ────────────────────────────────────────────
        reg.register("getblockchaininfo",   self.rpc_getblockchaininfo,   "blockchain",
            "Returns chain info: height, hash, difficulty, supply.")
