    # ── Blockchain methods ────────────────────────────────────────
    def rpc_getblockchaininfo(self) -> dict:
        info = self.bc.chain_info()
        return {
            "chain"              : CHAIN_NAME,
            "chain_id"           : CHAIN_ID,
            "blocks"             : self.bc.height,
            "headers"            : self.bc.height,
            "bestblockhash"      : self.bc.tip.hash,
            "difficulty"         : bits_to_target(self.bc.tip.header.bits),
            "time"               : self.bc.tip.header.timestamp,
            "mediantime"         : self.bc.tip.header.timestamp,
            "verificationprogress":1.0,
            "chainwork"          : hex(sum((2**256) // max(1, bits_to_target(blk.header.bits)) for blk in self.bc._chain)),  # FIX
            "pruned"             : False,
            "softforks"          : {"segwit": {"type": "buried", "active": True},
                                    "taproot": {"type": "buried", "active": True}},
            "utxo_set_size"      : self.bc.utxo.size(),
            "issued_supply_nbl"  : info["issued_supply"],
            "max_supply_nbl"     : info["max_supply"],
        }

    def rpc_getblockcount(self) -> int:
        return self.bc.height

    def rpc_getblockhash(self, height: int) -> str:
        blk = self.bc.get_block(int(height))
        if blk is None:
            raise RPCError(RPC_INVALID_PARAM, f"Block at height {height} not found")
        return blk.hash

    def rpc_getblock(self, blockhash: str, verbosity: int = 1) -> Any:
        blk = self.bc.get_block_by_hash(blockhash)
        if not blk:
            try:
                blk = self.bc.get_block(int(blockhash))
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULAJSONRPCServerLegacy.rpc_getblock", exc_info=True)
        if blk is None:
            raise RPCError(RPC_INVALID_PARAM, "Block not found")
        if verbosity == 0:
            return blk.header.serialize().hex()
        d = blk.to_dict()
        d["confirmations"] = self.bc.height - blk.height + 1
        d["nextblockhash"] = (self.bc.get_block(blk.height + 1).hash
                              if blk.height < self.bc.height else None)
        return d

    def rpc_getblockheader(self, blockhash: str, verbose: bool = True) -> Any:
        blk = self.bc.get_block_by_hash(blockhash)
        if not blk:
            raise RPCError(RPC_INVALID_PARAM, "Block not found")
        if not verbose:
            return blk.header.serialize().hex()
        return blk.header.to_dict()

    def rpc_getbestblockhash(self) -> str:
        return self.bc.tip.hash

    def rpc_getdifficulty(self) -> float:
        target = bits_to_target(self.bc.tip.header.bits)
        max_target = bits_to_target(INITIAL_BITS)
        return max_target / target if target > 0 else 0

    def rpc_getchaintips(self) -> list:
        return [{"height": self.bc.height, "hash": self.bc.tip.hash,
                 "branchlen": 0, "status": "active"}]

    def rpc_getchainwork(self) -> str:
        return f"{self.bc.height * bits_to_target(INITIAL_BITS):064x}"

    def rpc_getblockstats(self, hash_or_height, stats: list = None) -> dict:
        try:
            blk = self.bc.get_block(int(hash_or_height))
        except (ValueError, TypeError):
            blk = self.bc.get_block_by_hash(str(hash_or_height))
        if not blk:
            raise RPCError(RPC_INVALID_PARAM, "Block not found")
        txs  = blk.transactions
        fees = [tx.total_output() for tx in txs[1:]]
        return {
            "blockhash"   : blk.hash,
            "height"      : blk.height,
            "time"        : blk.header.timestamp,
            "txs"         : len(txs),
            "total_size"  : blk.byte_size(),
            "total_weight": blk.byte_size() * 4,
            "totalfee"    : sum(fees),
            "minfeeRate"  : min((f // max(1, tx.byte_size())
                                 for f, tx in zip(fees, txs[1:])), default=0),
            "maxfeeRate"  : max((f // max(1, tx.byte_size())
                                 for f, tx in zip(fees, txs[1:])), default=0),
            "subsidy"     : mining_reward(blk.height),
        }

    def rpc_gettxout(self, txid: str, n: int, include_mempool: bool = True) -> Optional[dict]:
        utxo = self.bc.utxo.get(txid, int(n))
        if utxo is None:
            return None
        return {
            "bestblock"    : self.bc.tip.hash,
            "confirmations": self.bc.height - utxo.height + 1,
            "value"        : utxo.value / 10**DECIMALS,
            "scriptPubKey" : {"hex": utxo.script_pubkey.hex(),
                              "type": Script.classify(utxo.script_pubkey).value},
            "coinbase"     : utxo.is_coinbase,
        }

    def rpc_gettxoutsetinfo(self) -> dict:
        return {
            "height"        : self.bc.height,
            "bestblock"     : self.bc.tip.hash,
            "txouts"        : self.bc.utxo.size(),
            "bogosize"      : self.bc.utxo.size() * 100,
            "total_amount"  : self.bc.utxo.total_supply() / 10**DECIMALS,
            "disk_size"     : 0,
        }

    def rpc_verifychain(self, checklevel: int = 3, nblocks: int = 6) -> bool:
        return True

    def rpc_getmempoolinfo(self) -> dict:
        return {
            "loaded"        : True,
            "size"          : self.bc.mempool.size(),
            "bytes"         : sum(tx.byte_size() for tx in self.bc.mempool._txs.values())
                              if hasattr(self.bc.mempool, '_txs') else 0,
            "usage"         : 0,
            "maxmempool"    : 300 * 1024 * 1024,
            "mempoolminfee" : MIN_TX_FEE / 10**DECIMALS,
            "minrelaytxfee" : MIN_TX_FEE / 10**DECIMALS,
            "fees"          : {
                "base"    : MIN_TX_FEE / 10**DECIMALS,
                "modified": MIN_TX_FEE / 10**DECIMALS,
            },
        }

    def rpc_getrawmempool(self, verbose: bool = False) -> Any:
        txids = list(self.bc.mempool._txs.keys()) if hasattr(self.bc.mempool, '_txs') else []
        if not verbose:
            return txids
        result = {}
        for txid in txids:
            entry = self.bc.mempool._txs.get(txid)
            if entry:
                result[txid] = {
                    "fee"    : entry.fee / 10**DECIMALS if hasattr(entry, 'fee') else 0,
                    "size"   : entry.tx.byte_size() if hasattr(entry, 'tx') else 0,
                    "time"   : entry.time if hasattr(entry, 'time') else time.time(),
                }
        return result

    def rpc_getmempoolentry(self, txid: str) -> dict:
        entry = self.bc.mempool._txs.get(txid) if hasattr(self.bc.mempool, '_txs') else None
        if entry is None:
            raise RPCError(RPC_INVALID_PARAM, "Transaction not in mempool")
        return {"txid": txid, "fee": getattr(entry, 'fee', 0) / 10**DECIMALS}

    def rpc_getmempoolancestors(self, txid: str, verbose: bool = False) -> Any:
        return [] if not verbose else {}

    def rpc_getmempooldescendants(self, txid: str, verbose: bool = False) -> Any:
        return [] if not verbose else {}

