    # ── Mining methods ────────────────────────────────────────────
    def rpc_getblocktemplate(self, template_request: dict = None) -> dict:
        builder = BlockTemplateBuilder(self.bc)
        addr    = FOUNDATION_ADDRESS
        if self._wallet:
            addr = self._wallet.first_address
        return builder.build(addr)

    def rpc_submitblock(self, hexdata: str, dummy: str = None) -> Optional[str]:
        """FIX v10.6: real implementation. Returns None on success (Bitcoin convention),
        otherwise a short reason string."""
        try:
            raw = bytes.fromhex(hexdata)
        except (ValueError, TypeError):
            raise RPCError(RPC_DESERIALIZATION_ERR, "Block decode failed: not hex")
        if len(raw) > MAX_BLOCK_SIZE_BYTES:
            raise RPCError(RPC_DESERIALIZATION_ERR, "Block decode failed: too large")
        try:
            block = parse_raw_block(raw, self.bc)
        except LookupError:
            return "prev-blk-not-found"
        except Exception as e:
            raise RPCError(RPC_DESERIALIZATION_ERR, f"Block decode failed: {e}")
        if self.bc.get_block_by_hash(block.hash):
            return "duplicate"
        ok, msg = self.bc.add_block(block)
        if not ok:
            return f"rejected: {msg}"
        if getattr(self, "_p2p", None):
            self._p2p.broadcast_block(block)
        return None

    def rpc_getmininginfo(self) -> dict:
        target = bits_to_target(self.bc.tip.header.bits)
        max_t  = bits_to_target(INITIAL_BITS)
        return {
            "blocks"           : self.bc.height,
            "currentblockweight": 0,
            "currentblocktx"   : 0,
            "difficulty"       : max_t / target if target else 0,
            "networkhashps"    : 0,
            "pooledtx"         : self.bc.mempool.size(),
            "chain"            : CHAIN_NAME,
            "blocksubsidy"     : mining_reward(self.bc.height + 1) / 10**DECIMALS,
        }

