    def rpc_fundrawtransaction(self, hexstring: str,
                                options: dict = None) -> dict:
        return {"hex": hexstring, "fee": 0, "changepos": -1}

    def rpc_signmessage(self, address: str, message: str) -> str:
        import base64
        msg_hash = hashlib.sha256(
            b"\x18NEBULA Signed Message:\n" +
            bytes([len(message)]) + message.encode()
        ).digest()
        return base64.b64encode(msg_hash).decode()

