    def start(self):
        NEBULARPCHandler.server_instance = self
        self._server = HTTPServer((self.host, self.port), NEBULARPCHandler)
        self._running = True
        self._thread  = threading.Thread(
            target=self._server.serve_forever,
            daemon=True, name="JsonRPC-HTTP")
        self._thread.start()
        print(f"🔌 JSON-RPC Server : http://{self.host}:{self.port}")
        print(f"   Methods         : {self.registry.method_count()}")
        print(f"   Auth            : {'enabled' if self.rpc_password else 'disabled'}")

    def stop(self):
        self._running = False
        if self._server:
            self._server.shutdown()

    def is_running(self) -> bool:
        return self._running

