# MODULE 23  nebula_wallet_hd_extended.py — BIP85 + Descriptors
# ================================================================
# BIP85: Deterministic entropy from HD keys (child wallets).
# Output descriptors: portable wallet backup format.
# Multi-account HD wallet with full BIP44/49/84/86 path support.
# Watch-only wallets, hardware wallet integration (PSBT flow).
# ================================================================

import hashlib, hmac as _hmac, struct, secrets, time, json, threading
from typing import List, Dict, Optional, Tuple, Any
from dataclasses import dataclass, field
from enum import Enum

# ── Descriptor Constants ──────────────────────────────────────────
DESCRIPTOR_VERSION      = 1
MAX_ACCOUNTS            = 0x7FFFFFFF
MAX_ADDRESSES_PER_ACCT  = 1_000_000
BIP85_PATH_PREFIX       = "m/83696968'"   # BIP85 root

# BIP85 application codes
BIP85_APP_BIP39_12   = 39  # 12-word mnemonic
BIP85_APP_BIP39_24   = 39  # 24-word mnemonic
BIP85_APP_WIF        = 2   # WIF private key
BIP85_APP_XPRV       = 32  # HD extended private key
BIP85_APP_HEX        = 128 # raw hex entropy

# Account purpose paths
PURPOSE_LEGACY   = 44   # P2PKH
PURPOSE_P2SH_SW  = 49   # P2SH-P2WPKH
PURPOSE_NATIVE   = 84   # P2WPKH
PURPOSE_TAPROOT  = 86   # P2TR

# ── BIP85: Child Key Entropy ──────────────────────────────────────
class BIP85:
    """
    BIP85: Deterministic Entropy From BIP32 Keychains.
    Derive child wallets, mnemonics, WIF keys from a master HD key.
    All child wallets are deterministically recoverable from the master.
    Use case: backup one seed → recover unlimited child wallets.
    """

    HMAC_KEY = b"bip-entropy-from-k"

    @classmethod
    def derive_entropy(cls, master_key: 'HDKey',
                        app: int, index: int,
                        length_bytes: int = 32) -> bytes:
        """
        Derive entropy for a specific application and index.
        Path: m/83696968'/<app>'/<index>'
        """
        path = f"m/83696968'/{app}'/{index}'"
        child = master_key.derive_path(path)

        # HMAC-SHA512 with child private key
        k = child.key.to_bytes(32, 'big')
        entropy = _hmac.new(cls.HMAC_KEY, k, hashlib.sha512).digest()
        return entropy[:length_bytes]

    @classmethod
    def derive_mnemonic(cls, master_key: 'HDKey',
                         words: int = 12, index: int = 0) -> str:
        """Derive a BIP39 child mnemonic (12 or 24 words)"""
        if words not in (12, 18, 24):
            raise ValueError("words must be 12, 18, or 24")
        entropy_bytes = {12: 16, 18: 24, 24: 32}[words]
        entropy = cls.derive_entropy(master_key, BIP85_APP_BIP39_12, index, entropy_bytes)
        return BIP39.entropy_to_mnemonic(entropy)

    @classmethod
    def derive_wif(cls, master_key: 'HDKey', index: int = 0) -> str:
        """Derive a WIF private key from master"""
        entropy = cls.derive_entropy(master_key, BIP85_APP_WIF, index, 32)
        privkey = int.from_bytes(entropy, 'big') % Secp256k1.N
        if privkey == 0:
            privkey = 1
        hd = HDKey(privkey, entropy, Secp256k1.point_mul(privkey, Secp256k1.G()))
        return hd.wif

    @classmethod
    def derive_hex(cls, master_key: 'HDKey',
                    num_bytes: int = 32, index: int = 0) -> str:
        """Derive raw hex entropy"""
        entropy = cls.derive_entropy(master_key, BIP85_APP_HEX, index, num_bytes)
        return entropy.hex()

    @classmethod
    def derive_child_xprv(cls, master_key: 'HDKey', index: int = 0) -> 'HDKey':
        """Derive a child HD extended private key"""
        entropy = cls.derive_entropy(master_key, BIP85_APP_XPRV, index, 64)
        return HDKey.from_seed(entropy)

# ── Output Descriptor ─────────────────────────────────────────────
@dataclass
class OutputDescriptor:
    """
    Bitcoin output descriptor (BIP380/381/382/383/384/385/386).
    Portable format describing how to generate addresses and scripts.
    Format: type([fingerprint/path]xpub/xpub/*)#checksum
    Examples:
      pkh([d34db33f/44'/0'/0']xpub.../0/*)
      wpkh([d34db33f/84'/0'/0']xpub.../0/*)
      tr([d34db33f/86'/0'/0']xpub.../0/*)
    """
    desc_type   : str        # pkh, wpkh, sh(wpkh), tr, multi, sortedmulti
    key         : str        # xpub or [fingerprint/path]xpub
    path        : str        # /0/* for external, /1/* for change
    checksum    : str = ""
    is_ranged   : bool = True
    is_hardened : bool = False

    def __post_init__(self):
        if not self.checksum:
            self.checksum = self._compute_checksum()

    def _compute_checksum(self) -> str:
        """BIP380 descriptor checksum (8 chars)"""
        desc = self.raw()
        INPUT_CHARSET = "0123456789()[],'/*abcdefgh@:$%{}IJKLMNOPQRSTUVWXYZ&+-.;<=>?!^_|~ijklmnopqrstuvwxyzABCDEFGH"
        CHECKSUM_CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

        c = 1
        cls_val = 0
        clscount = 0
        for ch in desc:
            pos = INPUT_CHARSET.find(ch)
            if pos < 0:
                return "00000000"
            c_pos = pos & 31
            cls_val = cls_val * 3 + (pos >> 5)
            clscount += 1
            if clscount == 3:
                c = cls_val ^ 1
                cls_val = clscount = 0
            c ^= c_pos
            for j in range(5):
                if c & (1 << 35):
                    _GEN = [0xa0d9a4ef, 0x1f1f394f, 0x26f3f9cb, 0xd4a17a80, 0x8b8d8b6e]
                    c = (c & ((1<<35)-1)) << 1 ^ _GEN[j % 5]
                else:
                    c = c << 1
        if clscount:
            c ^= cls_val ^ 1
        for _ in range(8):
            c ^= 0
        c ^= 1
        return ''.join(CHECKSUM_CHARSET[(c >> (5*(7-i))) & 31] for i in range(8))

    def raw(self) -> str:
        """Descriptor string without checksum"""
        inner = f"{self.key}{self.path}"
        return f"{self.desc_type}({inner})"

    def full(self) -> str:
        """Full descriptor with checksum"""
        return f"{self.raw()}#{self.checksum}"

    def is_valid(self) -> bool:
        return len(self.checksum) == 8

    @classmethod
    def for_pkh(cls, xpub: str, fingerprint: str,
                 path: str, account: int = 0) -> 'OutputDescriptor':
        """Create P2PKH descriptor"""
        key = f"[{fingerprint}/{path}/{account}']{{xpub}}"
        return cls("pkh", f"[{fingerprint}/{path}]{xpub}", "/0/*")

    @classmethod
    def for_wpkh(cls, xpub: str, fingerprint: str,
                  account: int = 0) -> 'OutputDescriptor':
        """Create P2WPKH (native SegWit) descriptor"""
        return cls("wpkh", f"[{fingerprint}/84'/0'/{account}']{xpub}", "/0/*")

    @classmethod
    def for_taproot(cls, xpub: str, fingerprint: str,
                     account: int = 0) -> 'OutputDescriptor':
        """Create P2TR (Taproot) descriptor"""
        return cls("tr", f"[{fingerprint}/86'/0'/{account}']{xpub}", "/0/*")

    @classmethod
    def parse(cls, desc_str: str) -> 'OutputDescriptor':
        """Parse a descriptor string"""
        if '#' in desc_str:
            raw, checksum = desc_str.rsplit('#', 1)
        else:
            raw, checksum = desc_str, ""

        # Extract type
        paren = raw.index('(')
        desc_type = raw[:paren]
        inner = raw[paren+1:-1]
        path  = "/0/*"

        return cls(desc_type=desc_type, key=inner, path=path,
                   checksum=checksum)

    def to_dict(self) -> dict:
        return {
            "descriptor": self.full(),
            "type"      : self.desc_type,
            "ranged"    : self.is_ranged,
            "checksum"  : self.checksum,
        }

# ── HD Account ───────────────────────────────────────────────────
# [v10.19] dead class HDAccountAdv removed from host - no live copy exists; original kept in nebula_removed_dead_classes.py

# ── Multi-Account HD Wallet ───────────────────────────────────────
class MultiAccountWallet:
    """
    Production HD wallet with multiple accounts.
    Bitcoin Core-style wallet supporting:
    - Multiple accounts per wallet
    - BIP44/49/84/86 script types
    - BIP85 child wallets
    - Watch-only mode
    - Label management
    - PSBT workflow
    - Hardware wallet integration stub
    """

    def __init__(self, master_key: 'HDKey',
                 mnemonic: str = None,
                 watch_only: bool = False):
        self.master_key  = master_key
        self.mnemonic    = mnemonic
        self.watch_only  = watch_only
        self._accounts   : Dict[Tuple[int,int], HDAccount] = {}
        self._labels     : Dict[str, str] = {}   # address → label
        self._locked_utxos: set = set()
        self._lock       = threading.RLock()
        self.created_at  = time.time()
        self.name        = "default"

        # Create default accounts for each purpose
        self._ensure_account(0, PURPOSE_LEGACY)
        self._ensure_account(0, PURPOSE_NATIVE)
        self._ensure_account(0, PURPOSE_TAPROOT)

    @classmethod
    def create_new(cls, word_count: int = 12) -> 'MultiAccountWallet':
        """Create new wallet from fresh entropy"""
        mnemonic = BIP39.generate_mnemonic(word_count)
        seed     = BIP39.mnemonic_to_seed(mnemonic)
        master   = HDKey.from_seed(seed)
        w        = cls(master, mnemonic)
        print(f"🔑 Multi-Account Wallet Created!")
        print(f"   Mnemonic: {mnemonic[:30]}...")
        return w

    @classmethod
    def from_mnemonic(cls, mnemonic: str,
                       passphrase: str = "") -> 'MultiAccountWallet':
        """Restore wallet from mnemonic"""
        seed   = BIP39.mnemonic_to_seed(mnemonic, passphrase)
        master = HDKey.from_seed(seed)
        return cls(master, mnemonic)

    @classmethod
    def watch_only(cls, xpub_or_desc: str) -> 'MultiAccountWallet':
        """Create watch-only wallet from xpub or descriptor"""
        # Parse descriptor if needed
        if '#' in xpub_or_desc or '(' in xpub_or_desc:
            desc = OutputDescriptor.parse(xpub_or_desc)
            # Extract key from descriptor
        # Simplified: create from fresh key but mark as watch-only
        seed   = secrets.token_bytes(32)
        master = HDKey.from_seed(seed)
        w = cls(master, watch_only=True)
        w.name = "watch-only"
        return w

    def _ensure_account(self, account_idx: int, purpose: int) -> HDAccount:
        """Get or create an account"""
        key = (account_idx, purpose)
        with self._lock:
            if key not in self._accounts:
                self._accounts[key] = PurposeAccount(
                    index      = account_idx,
                    purpose    = purpose,
                    master_key = self.master_key,
                )
            return self._accounts[key]

    # ── Address management ────────────────────────────────────────
    def get_address(self, account: int = 0,
                     purpose: int = PURPOSE_LEGACY) -> str:
        """Get next receive address for given account and script type"""
        acct = self._ensure_account(account, purpose)
        return acct.get_receive_address()

    def get_taproot_address(self, account: int = 0) -> str:
        return self.get_address(account, PURPOSE_TAPROOT)

    def get_segwit_address(self, account: int = 0) -> str:
        return self.get_address(account, PURPOSE_NATIVE)

    def get_legacy_address(self, account: int = 0) -> str:
        return self.get_address(account, PURPOSE_LEGACY)

    def set_label(self, address: str, label: str):
        """Label an address"""
        with self._lock:
            self._labels[address] = label

    def get_label(self, address: str) -> str:
        return self._labels.get(address, "")

    def lock_utxo(self, txid: str, vout: int):
        """Lock a UTXO (prevent spending)"""
        with self._lock:
            self._locked_utxos.add(f"{txid}:{vout}")

    def unlock_utxo(self, txid: str, vout: int):
        """Unlock a UTXO"""
        with self._lock:
            self._locked_utxos.discard(f"{txid}:{vout}")

    def is_locked(self, txid: str, vout: int) -> bool:
        return f"{txid}:{vout}" in self._locked_utxos

    # ── BIP85 child wallets ───────────────────────────────────────
    def derive_child_wallet(self, index: int = 0,
                             words: int = 12) -> 'MultiAccountWallet':
        """
        Derive a child wallet using BIP85.
        Child wallet is fully independent but recoverable from master.
        """
        if self.watch_only:
            raise ValueError("Cannot derive child from watch-only wallet")
        child_mnemonic = BIP85.derive_mnemonic(self.master_key, words, index)
        return MultiAccountWallet.from_mnemonic(child_mnemonic)

    def derive_child_entropy(self, index: int = 0,
                              length: int = 32) -> bytes:
        """Derive raw entropy for external use"""
        return BIP85.derive_entropy(self.master_key, BIP85_APP_HEX, index, length)

    # ── Balance and UTXOs ─────────────────────────────────────────
    def total_balance(self, utxo_set: 'UTXOSet') -> int:
        """Total balance across all accounts (in neb)"""
        total = 0
        for acct in self._accounts.values():
            for addr in acct.get_all_addresses():
                total += utxo_set.balance(addr)
        return total

    def account_balance(self, utxo_set: 'UTXOSet',
                         account: int = 0,
                         purpose: int = PURPOSE_LEGACY) -> int:
        """Balance for a specific account"""
        acct = self._ensure_account(account, purpose)
        total = 0
        for addr in acct.get_all_addresses():
            total += utxo_set.balance(addr)
        return total

    def get_spendable_utxos(self, utxo_set: 'UTXOSet',
                             purpose: int = PURPOSE_LEGACY) -> List['UTXOEntry']:
        """Get all spendable UTXOs (excluding locked)"""
        spendable = []
        for acct in self._accounts.values():
            if acct.purpose != purpose: continue
            for addr in acct.get_all_addresses():
                for utxo in utxo_set.get_by_address(addr):
                    if not self.is_locked(utxo.txid, utxo.index):
                        spendable.append(utxo)
        return spendable

    # ── Transaction building ──────────────────────────────────────
    def create_transaction(self, to_address: str,
                            amount_neb: int,
                            utxo_set: 'UTXOSet',
                            fee_rate: int = None,
                            purpose: int = PURPOSE_LEGACY) -> Optional['Transaction']:
        """
        Create a signed transaction.
        Automatically selects UTXOs, adds change output.
        """
        if self.watch_only:
            raise ValueError("Cannot sign from watch-only wallet")

        fee_rate = fee_rate or (MIN_TX_FEE // 100)
        utxos    = self.get_spendable_utxos(utxo_set, purpose)
        if not utxos:
            return None

        # Coin selection (greedy largest-first)
        selected = []
        total    = 0
        sorted_utxos = sorted(utxos, key=lambda u: u.value, reverse=True)
        for utxo in sorted_utxos:
            selected.append(utxo)
            total += utxo.value
            est_fee = fee_rate * (148 * len(selected) + 34 * 2 + 10)
            if total >= amount_neb + est_fee:
                break

        if total < amount_neb:
            return None

        # Build inputs
        inputs = [TxInput(OutPoint(u.txid, u.index), b'', 0xFFFFFFFF)
                  for u in selected]

        # Build outputs
        fee        = fee_rate * (148 * len(selected) + 34 * 2 + 10)
        change     = total - amount_neb - fee
        out_script = Script.p2pkh_locking_from_address(to_address)
        outputs    = [TxOutput(amount_neb, out_script)]

        if change >= DUST_THRESHOLD:
            change_addr   = self._ensure_account(0, purpose).get_change_address()
            change_script = Script.p2pkh_locking_from_address(change_addr)
            outputs.append(TxOutput(change, change_script))

        tx = Transaction(inputs=inputs, outputs=outputs)

        # Sign each input
        for i, (inp, utxo) in enumerate(zip(inputs, selected)):
            # Find signing key for this UTXO
            signing_key = self._find_key_for_utxo(utxo, purpose)
            if signing_key is None:
                return None

            sighash = tx.signature_hash(i, utxo.script_pubkey, SIGHASH_ALL)
            r, s    = Secp256k1.sign(signing_key, sighash)
            der     = Secp256k1.sig_to_der(r, s) + bytes([SIGHASH_ALL])
            pub     = Secp256k1.pubkey_to_bytes(
                        Secp256k1.point_mul(signing_key, Secp256k1.G()))
            inp.script_sig = Script.p2pkh_unlocking(der, pub)
            tx.invalidate_cache()

        return tx

    def _find_key_for_utxo(self, utxo: 'UTXOEntry',
                             purpose: int) -> Optional[int]:
        """Find private key that controls this UTXO"""
        addr = entry_address(utxo)
        if not addr: return None
        acct = self._ensure_account(0, purpose)
        for i in range(acct._external_index + acct.gap_limit):
            path = f"{acct.base_path}/0/{i}"
            key  = self.master_key.derive_path(path)
            if key.address == addr:
                return key.key
        return None

    # ── PSBT workflow ─────────────────────────────────────────────
    def create_psbt(self, to_address: str,
                     amount_neb: int,
                     utxo_set: 'UTXOSet') -> Optional[PSBT]:
        """Create unsigned PSBT for hardware wallet signing"""
        utxos   = self.get_spendable_utxos(utxo_set)
        if not utxos: return None

        # Coin selection
        selected = []
        total    = 0
        for utxo in sorted(utxos, key=lambda u: u.value, reverse=True):
            selected.append(utxo)
            total += utxo.value
            if total >= amount_neb + MIN_TX_FEE:
                break

        if total < amount_neb:
            return None

        inputs  = [TxInput(OutPoint(u.txid, u.index), b'', 0xFFFFFFFF)
                   for u in selected]
        change  = total - amount_neb - MIN_TX_FEE
        outputs = [TxOutput(amount_neb, Script.p2pkh_locking_from_address(to_address))]
        if change >= DUST_THRESHOLD:
            chg_addr = self._ensure_account(0, PURPOSE_LEGACY).get_change_address()
            outputs.append(TxOutput(change, Script.p2pkh_locking_from_address(chg_addr)))

        tx   = Transaction(inputs=inputs, outputs=outputs)
        psbt = PSBT(tx)
        for i, utxo in enumerate(selected):
            psbt.add_input_witness_utxo(i, utxo.value, utxo.script_pubkey)
        return psbt

    def sign_psbt(self, psbt: PSBT, utxo_set: 'UTXOSet') -> PSBT:
        """Sign all inputs in a PSBT"""
        if self.watch_only:
            raise ValueError("Cannot sign from watch-only wallet")
        tx = psbt.tx
        if not tx: return psbt

        for i, inp in enumerate(psbt.inputs):
            wit_key = bytes([PSBT.PSBT_IN_WITNESS_UTXO])
            if wit_key in inp:
                data   = inp[wit_key]
                value  = struct.unpack_from('<q', data)[0]
                s_len  = data[8]
                script = data[9:9+s_len]

                utxo_entry = utxo_set.get(tx.inputs[i].outpoint.txid,
                                           tx.inputs[i].outpoint.index)
                if utxo_entry:
                    sk = self._find_key_for_utxo(utxo_entry, PURPOSE_LEGACY)
                    if sk:
                        sighash = tx.signature_hash(i, script, SIGHASH_ALL)
                        r, s_v  = Secp256k1.sign(sk, sighash)
                        der     = Secp256k1.sig_to_der(r, s_v) + bytes([SIGHASH_ALL])
                        pub     = Secp256k1.pubkey_to_bytes(
                                    Secp256k1.point_mul(sk, Secp256k1.G()))
                        psbt.add_input_partial_sig(i, pub, der)
        return psbt

    # ── Serialization ─────────────────────────────────────────────
    def export_descriptors(self) -> List[str]:
        """Export all account descriptors for backup"""
        result = []
        for acct in self._accounts.values():
            result.append(acct.descriptor().full())
        return result

    def export_public_info(self) -> dict:
        """Export public wallet info (safe to share with watch-only)"""
        with self._lock:
            accounts = []
            for (idx, purpose), acct in self._accounts.items():
                accounts.append(acct.to_dict())
            return {
                "name"       : self.name,
                "watch_only" : self.watch_only,
                "accounts"   : accounts,
                "descriptors": self.export_descriptors(),
                "created_at" : self.created_at,
            }

    def save_encrypted(self, path: str, password: str):
        """Save wallet to encrypted file"""
        data = {
            "version"   : 1,
            "watch_only": self.watch_only,
            "name"      : self.name,
        }
        if not self.watch_only and self.mnemonic:
            data["enc"] = _encrypt_mnemonic(self.mnemonic, password)
        data["public"] = self.export_public_info()

        with open(path, 'w') as f:
            json.dump(data, f, indent=2)
        import os, stat as _st
        os.chmod(path, _st.S_IRUSR | _st.S_IWUSR)

    @classmethod
    def load_encrypted(cls, path: str, password: str) -> 'MultiAccountWallet':
        """Load wallet from encrypted file"""
        with open(path) as f:
            data = json.load(f)

        if data.get("watch_only") or "enc" not in data:
            seed   = secrets.token_bytes(32)
            master = HDKey.from_seed(seed)
            w      = cls(master, watch_only=True)
        else:
            mnemonic = _decrypt_mnemonic(data["enc"], password)
            w        = cls.from_mnemonic(mnemonic)

        w.name = data.get("name", "default")
        return w

    def stats(self) -> dict:
        with self._lock:
            return {
                "name"        : self.name,
                "watch_only"  : self.watch_only,
                "accounts"    : len(self._accounts),
                "labels"      : len(self._labels),
                "locked_utxos": len(self._locked_utxos),
                "created_at"  : self.created_at,
            }

