import threading, time, hashlib, struct, queue
from typing import List, Dict, Optional, Tuple, Set
from dataclasses import dataclass, field
from enum import Enum

# ── Sync Constants ────────────────────────────────────────────────
IBD_HEADERS_BATCH    = 2000     # headers per getheaders message
IBD_BLOCKS_PARALLEL  = 8        # parallel block download workers
IBD_BLOCK_TIMEOUT    = 30       # seconds to wait for block
IBD_STALL_TIMEOUT    = 60       # seconds before marking peer stalled
MIN_CHAIN_WORK_BITS  = 60       # minimum accumulated work
SYNC_CHECKPOINT_FREQ = 1000     # verify checkpoint every N blocks

# ── Hard-coded Checkpoints ────────────────────────────────────────
CHECKPOINTS = {
    0: GENESIS_HASH_HEX,
    # Future checkpoints added as network grows
    # 10000: "...",
    # 50000: "...",
}

# ── Sync State ────────────────────────────────────────────────────
class SyncState(Enum):
    IDLE             = "idle"
    HEADERS_SYNC     = "headers_sync"
    BLOCK_DOWNLOAD   = "block_download"
    VALIDATING       = "validating"
    SYNCED           = "synced"
    STALLED          = "stalled"
    ERROR            = "error"

@dataclass
class SyncProgress:
    """Current sync progress metrics"""
    state            : SyncState = SyncState.IDLE
    headers_height   : int       = 0
    blocks_height    : int       = 0
    target_height    : int       = 0
    blocks_per_second: float     = 0.0
    headers_per_second: float    = 0.0
    start_time       : float     = field(default_factory=time.time)
    last_update      : float     = field(default_factory=time.time)
    bytes_downloaded : int       = 0
    peers_syncing    : int       = 0
    best_peer        : str       = ""

    @property
    def pct_complete(self) -> float:
        if self.target_height == 0:
            return 0.0
        return min(100.0, self.blocks_height / self.target_height * 100)

    @property
    def blocks_remaining(self) -> int:
        return max(0, self.target_height - self.blocks_height)

    @property
    def eta_seconds(self) -> float:
        if self.blocks_per_second <= 0:
            return float('inf')
        return self.blocks_remaining / self.blocks_per_second

    def to_dict(self) -> dict:
        return {
            "state"             : self.state.value,
            "headers_height"    : self.headers_height,
            "blocks_height"     : self.blocks_height,
            "target_height"     : self.target_height,
            "pct_complete"      : f"{self.pct_complete:.2f}%",
            "blocks_remaining"  : self.blocks_remaining,
            "blocks_per_sec"    : round(self.blocks_per_second, 1),
            "eta_seconds"       : round(self.eta_seconds, 0) if self.eta_seconds != float('inf') else "unknown",
            "bytes_downloaded_mb": round(self.bytes_downloaded / 1024 / 1024, 2),
            "peers_syncing"     : self.peers_syncing,
        }

# ── Header Chain ─────────────────────────────────────────────────
class HeaderChain:
    """
    In-memory header chain for headers-first sync.
    Stores only headers (80 bytes each) before full block download.
    Enables fast initial header sync then parallel block download.
    """

    def __init__(self):
        self._headers  : List['BlockHeader'] = []
        self._hash_idx : Dict[str, int] = {}
        self._lock     = threading.RLock()

    def add_header(self, hdr: 'BlockHeader') -> Tuple[bool, str]:
        """Validate and add a block header"""
        with self._lock:
            # PoW check
            if not hdr.meets_target():
                return False, "PoW insufficient"
            # Chain linkage
            if self._headers:
                tip = self._headers[-1]
                if hdr.prev_hash != tip.hash():
                    return False, "Prev hash mismatch"
                if hdr.height != tip.height + 1:
                    return False, "Height not sequential"
            # Timestamp check
            if hdr.timestamp > time.time() + 7200:
                return False, "Timestamp too far in future"
            # Checkpoint
            if hdr.height in CHECKPOINTS:
                if hdr.hash() != CHECKPOINTS[hdr.height]:
                    return False, f"Checkpoint mismatch at height {hdr.height}"

            self._headers.append(hdr)
            self._hash_idx[hdr.hash()] = hdr.height
            return True, "OK"

    def add_batch(self, headers: List['BlockHeader']) -> Tuple[int, str]:
        """Add a batch of headers. Returns (count_added, reason)"""
        added = 0
        for hdr in headers:
            ok, reason = self.add_header(hdr)
            if not ok:
                return added, reason
            added += 1
        return added, "OK"

    def get_locator(self) -> List[str]:
        """Generate block locator for sync"""
        with self._lock:
            if not self._headers:
                return [CHECKPOINTS.get(0, '0'*64)]
            locator = []
            step = 1
            idx  = len(self._headers) - 1
            while idx >= 0:
                locator.append(self._headers[idx].hash())
                if len(locator) >= 10:
                    step *= 2
                idx -= step
                if idx < 0 and not locator:
                    locator.append(self._headers[0].hash())
            return locator

    @property
    def height(self) -> int:
        with self._lock:
            return len(self._headers) - 1

    @property
    def tip_hash(self) -> Optional[str]:
        with self._lock:
            return self._headers[-1].hash() if self._headers else None

    def get_header(self, height: int) -> Optional['BlockHeader']:
        with self._lock:
            if 0 <= height < len(self._headers):
                return self._headers[height]
            return None

    def get_range(self, start: int, end: int) -> List['BlockHeader']:
        with self._lock:
            return self._headers[start:end]

# ── Block Request Manager ─────────────────────────────────────────
class BlockRequestManager:
    """
    Manages parallel block download requests during IBD.
    Tracks in-flight requests, handles timeouts and retries.
    Assigns block requests to peers based on availability.
    """

    @dataclass
    class Request:
        block_hash  : str
        height      : int
        peer_id     : str
        requested_at: float = field(default_factory=time.time)
        attempts    : int   = 0

    def __init__(self, max_inflight: int = IBD_BLOCKS_PARALLEL):
        self._max_inflight = max_inflight
        self._inflight  : Dict[str, 'BlockRequestManager.Request'] = {}
        self._queue     : List[Tuple[int, str]] = []   # (height, hash) sorted
        self._received  : Set[str] = set()
        self._lock      = threading.RLock()

    def queue_block(self, height: int, block_hash: str):
        """Add a block to the download queue"""
        with self._lock:
            if block_hash not in self._received and block_hash not in self._inflight:
                self._queue.append((height, block_hash))
                self._queue.sort(key=lambda x: x[0])

    def get_next_request(self, peer_id: str) -> Optional[Tuple[int, str]]:
        """Get next block to request from a peer"""
        with self._lock:
            if len(self._inflight) >= self._max_inflight:
                return None
            if not self._queue:
                return None
            height, block_hash = self._queue.pop(0)
            req = self.Request(block_hash, height, peer_id)
            self._inflight[block_hash] = req
            return height, block_hash

    def mark_received(self, block_hash: str) -> bool:
        """Mark a block as received"""
        with self._lock:
            self._inflight.pop(block_hash, None)
            self._received.add(block_hash)
            return True

    def get_stalled(self, timeout: float = IBD_BLOCK_TIMEOUT) -> List['BlockRequestManager.Request']:
        """Get requests that have timed out"""
        now = time.time()
        with self._lock:
            return [r for r in self._inflight.values()
                    if now - r.requested_at > timeout]

    def retry(self, block_hash: str, new_peer: str):
        """Re-queue a failed request"""
        with self._lock:
            req = self._inflight.pop(block_hash, None)
            if req:
                req.attempts   += 1
                req.peer_id     = new_peer
                req.requested_at= time.time()
                self._inflight[block_hash] = req

    @property
    def inflight_count(self) -> int:
        return len(self._inflight)

    @property
    def queued_count(self) -> int:
        return len(self._queue)

# ── Reorg Manager ─────────────────────────────────────────────────
class ReorgManager:
    """
    Handles blockchain reorganizations.
    When a longer chain is found, disconnects current tip
    and connects the new chain.
    Maximum reorg depth configurable to prevent deep reorgs.
    """

    MAX_REORG_DEPTH = 100   # reject reorgs deeper than this

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc    = blockchain
        self._lock = threading.RLock()
        self._reorg_count = 0
        self._deepest_reorg = 0

    def find_fork_point(self, new_chain_headers: List['BlockHeader']) -> int:
        """
        Find the common ancestor between current chain and new chain.
        Returns the fork height, or -1 if no common ancestor found.
        """
        with self._lock:
            new_hashes = {h.hash() for h in new_chain_headers}
            # Walk back from tip
            for height in range(self.bc.height, max(0, self.bc.height - self.MAX_REORG_DEPTH), -1):
                blk = self.bc.get_block(height)
                if blk and blk.hash in new_hashes:
                    return height
            return -1

    def reorg_to(self, new_blocks: List['Block']) -> Tuple[bool, str]:
        """
        Perform a chain reorganization.
        Disconnects blocks from current tip back to fork point,
        then connects new blocks.
        """
        with self._lock:
            if not new_blocks:
                return False, "Empty new chain"

            # Find fork
            new_headers = [b.header for b in new_blocks]
            fork_height = self.find_fork_point(new_headers)

            if fork_height < 0:
                return False, "No common ancestor found"

            reorg_depth = self.bc.height - fork_height
            if reorg_depth > self.MAX_REORG_DEPTH:
                return False, f"Reorg too deep: {reorg_depth} > {self.MAX_REORG_DEPTH}"

            # New chain must be longer
            new_tip_height = new_blocks[-1].height
            if new_tip_height <= self.bc.height:
                return False, f"New chain not longer: {new_tip_height} <= {self.bc.height}"

            # FIX Disconnect current blocks back to fork with UTXO rollback
            disconnected = []
            while self.bc.height > fork_height:
                blk = self.bc.tip
                self.bc._chain.pop()
                self.bc._hash_idx.pop(blk.hash, None)
                # FIX actually rollback UTXO changes using undo data
                self.bc.utxo.undo_block(blk)
                disconnected.append(blk)

            # Connect new blocks
            connected = 0
            for blk in new_blocks:
                if blk.height <= fork_height:
                    continue
                ok, msg = self.bc.add_block(blk)
                if not ok:
                    # Rollback failed — restore original chain + re-apply UTXOs
                    for d_blk in reversed(disconnected):
                        self.bc._chain.append(d_blk)
                        self.bc._hash_idx[d_blk.hash] = d_blk.height
                        self.bc.utxo.apply_block(d_blk)  # FIX re-apply
                    return False, f"Failed to connect block at {blk.height}: {msg}"
                connected += 1

            self._reorg_count += 1
            self._deepest_reorg = max(self._deepest_reorg, reorg_depth)

            return True, f"Reorg complete: depth={reorg_depth}, connected={connected}"

    def stats(self) -> dict:
        return {
            "reorg_count"   : self._reorg_count,
            "deepest_reorg" : self._deepest_reorg,
            "max_allowed"   : self.MAX_REORG_DEPTH,
        }

# ── Chain Selector ────────────────────────────────────────────────
class ChainSelector:
    """
    Nakamoto consensus: always follow the chain with most work.
    Compares chains by accumulated PoW, not just length.
    Prevents longest-chain attacks that ignore difficulty.
    """

    @staticmethod
    def chain_work(headers: List['BlockHeader']) -> int:
        """
        Calculate total accumulated work for a chain of headers.
        work = sum(2^256 / target_i) for each block i.
        """
        total = 0
        for hdr in headers:
            target = bits_to_target(hdr.bits)
            if target > 0:
                total += (2**256) // target
        return total

    @staticmethod
    def best_chain(candidates: List[List['BlockHeader']]) -> Optional[int]:
        """
        Select the best chain from candidates.
        Returns index of the chain with most accumulated work.
        """
        if not candidates:
            return None
        works = [ChainSelector.chain_work(c) for c in candidates]
        return works.index(max(works))

    @staticmethod
    def compare(chain_a: List['BlockHeader'],
                chain_b: List['BlockHeader']) -> int:
        """
        Compare two chains.
        Returns: 1 if A > B, -1 if A < B, 0 if equal.
        """
        work_a = ChainSelector.chain_work(chain_a)
        work_b = ChainSelector.chain_work(chain_b)
        if work_a > work_b: return 1
        if work_a < work_b: return -1
        return 0

# ── IBD Coordinator ───────────────────────────────────────────────
class IBDCoordinator:
    """
    Initial Block Download coordinator.
    Phase 1: Headers-first sync (fast, parallel header validation).
    Phase 2: Block download (parallel, 8 blocks at a time).
    Phase 3: Full validation.
    Estimated sync time: depends on network speed and chain height.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 header_chain: HeaderChain = None):
        self.bc           = blockchain
        self.header_chain = header_chain or HeaderChain()
        self.reorg_mgr    = ReorgManager(blockchain)
        self.chain_sel    = ChainSelector()
        self.req_mgr      = BlockRequestManager()
        self.progress     = SyncProgress()
        self._running     = False
        self._lock        = threading.RLock()
        self._block_queue : queue.Queue = queue.Queue(maxsize=100)
        self._on_synced   = None

    def start(self, on_synced=None):
        """Start IBD process"""
        self._running  = True
        self._on_synced = on_synced
        self.progress.state      = SyncState.HEADERS_SYNC
        self.progress.start_time = time.time()
        threading.Thread(target=self._sync_loop,
                         daemon=True, name="IBD-Sync").start()
        threading.Thread(target=self._validation_loop,
                         daemon=True, name="IBD-Validate").start()
        print(f"⚡ IBD started — current height: {self.bc.height}")

    def stop(self):
        self._running = False

    def _sync_loop(self):
        """Main sync coordination loop"""
        while self._running:
            try:
                self._update_progress()
                time.sleep(1)
            except Exception as e:
                self.progress.state = SyncState.ERROR
                time.sleep(5)

    def _validation_loop(self):
        """Validate and connect downloaded blocks"""
        while self._running:
            try:
                block = self._block_queue.get(timeout=1)
                ok, msg = self.bc.add_block(block)
                if ok:
                    self.progress.blocks_height = self.bc.height
                    if self.bc.height % 1000 == 0:
                        print(f"⛓️  Block #{self.bc.height} validated")
            except queue.Empty:
                pass
            except Exception:
                _NB_SWALLOW_LOG.warning("swallowed Exception in IBDCoordinator._validation_loop", exc_info=True)

    def _update_progress(self):
        """Update progress metrics"""
        now      = self.progress.last_update
        elapsed  = time.time() - self.progress.start_time
        if elapsed > 0:
            self.progress.blocks_per_second  = self.bc.height / elapsed
            self.progress.headers_per_second = self.header_chain.height / elapsed
        self.progress.blocks_height  = self.bc.height
        self.progress.headers_height = self.header_chain.height
        self.progress.last_update    = time.time()

        if self.bc.height >= self.progress.target_height > 0:
            self.progress.state = SyncState.SYNCED
            if self._on_synced:
                self._on_synced()

    def submit_block(self, block: 'Block'):
        """Submit a downloaded block for validation"""
        try:
            self._block_queue.put_nowait(block)
        except queue.Full:
            pass

    def set_target_height(self, height: int, peer_id: str = ""):
        """Update sync target from peer announcement"""
        with self._lock:
            if height > self.progress.target_height:
                self.progress.target_height = height
                self.progress.best_peer     = peer_id

    def queue_block_request(self, height: int, block_hash: str):
        """Queue a block for download"""
        self.req_mgr.queue_block(height, block_hash)

    @property
    def is_synced(self) -> bool:
        return self.progress.state == SyncState.SYNCED

    @property
    def is_ibd(self) -> bool:
        """True if we're still in initial block download"""
        return (self.bc.height < self.progress.target_height * 0.99 and
                self.progress.target_height > 10)

    def get_progress(self) -> dict:
        return self.progress.to_dict()

    def get_stats(self) -> dict:
        return {
            "progress"    : self.progress.to_dict(),
            "reorg"       : self.reorg_mgr.stats(),
            "inflight"    : self.req_mgr.inflight_count,
            "queued"      : self.req_mgr.queued_count,
            "header_height": self.header_chain.height,
        }

