# ── Alert System ─────────────────────────────────────────────────
class AlertSeverity(Enum):
    INFO     = "info"
    WARNING  = "warning"
    CRITICAL = "critical"
    EMERGENCY= "emergency"

@dataclass
class NetworkAlert:
    """
    Network-wide alert system (like Bitcoin Core's alert system).
    Used for: protocol upgrades, security notices, chain forks.
    """
    alert_id   : int
    message    : str
    severity   : AlertSeverity
    min_version: int = 0
    max_version: int = 999999
    set_cancel : int = 0
    expiry     : float = 0.0
    created_at : float = field(default_factory=time.time)
    signature  : bytes = b''

    def is_expired(self) -> bool:
        return self.expiry > 0 and time.time() > self.expiry

    def is_applicable(self, version: int) -> bool:
        return (self.min_version <= version <= self.max_version
                and not self.is_expired()
                and self.set_cancel == 0)

    def to_dict(self) -> dict:
        return {
            "alert_id"  : self.alert_id,
            "message"   : self.message,
            "severity"  : self.severity.value,
            "expiry"    : self.expiry,
            "expired"   : self.is_expired(),
        }

class AlertManager:
    """Manages network alerts"""

    def __init__(self):
        self._alerts  : Dict[int, NetworkAlert] = {}
        self._lock    = threading.RLock()
        self._handlers: List[Callable] = []

    def add_alert(self, alert: NetworkAlert):
        with self._lock:
            self._alerts[alert.alert_id] = alert
            for handler in self._handlers:
                try:
                    handler(alert)
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in AlertManager.add_alert", exc_info=True)

    def cancel(self, alert_id: int):
        with self._lock:
            self._alerts.pop(alert_id, None)

    def on_alert(self, handler: Callable):
        """Register alert handler"""
        self._handlers.append(handler)

    def get_active(self) -> List[NetworkAlert]:
        with self._lock:
            return [a for a in self._alerts.values()
                    if not a.is_expired()]

    def get_critical(self) -> List[NetworkAlert]:
        return [a for a in self.get_active()
                if a.severity in (AlertSeverity.CRITICAL, AlertSeverity.EMERGENCY)]

# ── BIP9 Soft Fork Deployment ─────────────────────────────────────
class BIP9State(Enum):
    DEFINED   = "DEFINED"
    STARTED   = "STARTED"
    LOCKED_IN = "LOCKED_IN"
    ACTIVE    = "ACTIVE"
    FAILED    = "FAILED"

@dataclass
class BIP9Deployment:
    """
    BIP9 version bits soft fork deployment tracking.
    Each soft fork has a bit position in the block version field.
    Activates when 95% of blocks in a 2016-block window signal.
    """
    name       : str
    bit        : int         # version bit (0-28)
    start_time : int         # Unix timestamp to start signaling
    timeout    : int         # Unix timestamp when deployment fails
    threshold  : float = 0.95
    period     : int   = DIFFICULTY_WINDOW   # 2016 blocks
    state      : BIP9State = BIP9State.DEFINED
    signal_count: int  = 0
    locked_in_height: Optional[int] = None

    def version_bit_mask(self) -> int:
        return 1 << self.bit

    def signals(self, version: int) -> bool:
        """True if block version signals for this deployment"""
        return bool(version & self.version_bit_mask())

class SoftForkManager:
    """
    Manages all soft fork deployments.
    Tracks signaling, handles state transitions.
    Currently defined NEBULA soft forks:
    """

    # NEBULA soft fork deployments
    DEPLOYMENTS = {
        "segwit"  : BIP9Deployment("segwit",   1, 0, 9999999999, state=BIP9State.ACTIVE),
        "taproot" : BIP9Deployment("taproot",  2, 0, 9999999999, state=BIP9State.ACTIVE),
        "musig2"  : BIP9Deployment("musig2",   3, 1742083200, 1900000000),
        "lightning": BIP9Deployment("lightning",4, 1742083200, 1900000000),
    }

    def __init__(self):
        self._deployments = dict(self.DEPLOYMENTS)
        self._lock        = threading.RLock()

    def process_block(self, block: 'Block'):
        """Process a block for soft fork signaling"""
        version = block.header.version
        with self._lock:
            for dep in self._deployments.values():
                if dep.state not in (BIP9State.STARTED, BIP9State.LOCKED_IN):
                    continue
                if dep.signals(version):
                    dep.signal_count += 1

    def get_state(self, name: str) -> Optional[BIP9State]:
        dep = self._deployments.get(name)
        return dep.state if dep else None

    def is_active(self, name: str) -> bool:
        return self.get_state(name) == BIP9State.ACTIVE

    def get_all_states(self) -> dict:
        with self._lock:
            return {
                name: {
                    "state"     : dep.state.value,
                    "bit"       : dep.bit,
                    "signal_pct": f"{dep.signal_count / max(1, DIFFICULTY_WINDOW) * 100:.1f}%",
                }
                for name, dep in self._deployments.items()
            }

# ── Peer Scoring ─────────────────────────────────────────────────
class PeerScorer:
    """
    Peer quality scoring system.
    Peers are ranked by: uptime, latency, block contribution,
    valid message ratio, bandwidth.
    High-score peers preferred for block requests.
    Low-score peers disconnected.
    """

    SCORE_MAX     = 1000
    SCORE_MIN     = 0
    SCORE_INITIAL = 500
    EVICT_BELOW   = 100

    @dataclass
    class PeerScore:
        peer_id         : str
        score           : int   = 500
        valid_blocks    : int   = 0
        invalid_blocks  : int   = 0
        valid_txs       : int   = 0
        invalid_txs     : int   = 0
        avg_latency_ms  : float = 0.0
        uptime_secs     : float = 0.0
        bytes_useful    : int   = 0

        def adjustment(self, event: str) -> int:
            adjustments = {
                "valid_block"    : +10,
                "invalid_block"  : -50,
                "valid_tx"       : +1,
                "invalid_tx"     : -5,
                "timeout"        : -20,
                "reconnect"      : -10,
                "stale_data"     : -5,
                "helpful_headers": +3,
            }
            return adjustments.get(event, 0)

    def __init__(self):
        self._scores : Dict[str, 'PeerScorer.PeerScore'] = {}
        self._lock   = threading.RLock()

    def register(self, peer_id: str):
        with self._lock:
            if peer_id not in self._scores:
                self._scores[peer_id] = self.PeerScore(peer_id)

    def event(self, peer_id: str, event_type: str):
        """Record a peer event and update score"""
        with self._lock:
            score = self._scores.get(peer_id)
            if not score:
                self.register(peer_id)
                score = self._scores[peer_id]

            delta = score.adjustment(event_type)
            score.score = max(self.SCORE_MIN,
                              min(self.SCORE_MAX, score.score + delta))

            # Update event counters
            if event_type == "valid_block":   score.valid_blocks += 1
            elif event_type == "invalid_block": score.invalid_blocks += 1
            elif event_type == "valid_tx":    score.valid_txs += 1
            elif event_type == "invalid_tx":  score.invalid_txs += 1

    def get_score(self, peer_id: str) -> int:
        with self._lock:
            s = self._scores.get(peer_id)
            return s.score if s else self.SCORE_INITIAL

    def best_peers(self, n: int = 5) -> List[str]:
        """Return top N peers by score"""
        with self._lock:
            sorted_peers = sorted(self._scores.items(),
                                  key=lambda x: x[1].score, reverse=True)
            return [pid for pid, _ in sorted_peers[:n]]

    def peers_to_evict(self) -> List[str]:
        """Return peers with score below eviction threshold"""
        with self._lock:
            return [pid for pid, s in self._scores.items()
                    if s.score < self.EVICT_BELOW]

    def remove(self, peer_id: str):
        with self._lock:
            self._scores.pop(peer_id, None)

    def stats(self) -> dict:
        with self._lock:
            if not self._scores:
                return {"count": 0}
            scores = [s.score for s in self._scores.values()]
            return {
                "count"   : len(self._scores),
                "avg"     : sum(scores) / len(scores),
                "min"     : min(scores),
                "max"     : max(scores),
                "evictable": len(self.peers_to_evict()),
            }

# ── Node Health Monitor ───────────────────────────────────────────
class NodeHealthMonitor:
    """
    Continuous node health monitoring.
    Tracks: CPU, memory, disk, network, chain quality.
    Emits alerts when thresholds exceeded.
    Auto-restarts stalled components.
    """

    CHECK_INTERVAL = 30   # seconds

    @dataclass
    class HealthSnapshot:
        timestamp     : float = field(default_factory=time.time)
        chain_height  : int   = 0
        utxo_size     : int   = 0
        mempool_size  : int   = 0
        peer_count    : int   = 0
        disk_mb       : float = 0.0
        memory_mb     : float = 0.0
        last_block_age: float = 0.0   # seconds since last block
        is_mining     : bool  = False
        hash_rate_mhs : float = 0.0

        def is_healthy(self) -> bool:
            return (self.peer_count > 0 and
                    self.last_block_age < 7200 and
                    self.disk_mb < 100_000)

        def to_dict(self) -> dict:
            return {
                "timestamp"     : self.timestamp,
                "chain_height"  : self.chain_height,
                "utxo_size"     : self.utxo_size,
                "mempool_size"  : self.mempool_size,
                "peer_count"    : self.peer_count,
                "disk_mb"       : round(self.disk_mb, 1),
                "memory_mb"     : round(self.memory_mb, 1),
                "last_block_age": round(self.last_block_age, 0),
                "is_mining"     : self.is_mining,
                "hash_rate_mhs" : round(self.hash_rate_mhs, 2),
                "healthy"       : self.is_healthy(),
            }

    def __init__(self, blockchain: 'NEBULABlockchain',
                 data_dir: str = "./nebula_data"):
        self.bc        = blockchain
        self.data_dir  = Path(data_dir)
        self._history  : List['NodeHealthMonitor.HealthSnapshot'] = []
        self._running  = False
        self._lock     = threading.RLock()
        self._miner    : Optional['NEBULAMiner'] = None
        self._p2p      : Optional['P2PNode']    = None
        self._alert_mgr: Optional[AlertManager] = None

    def attach_miner(self, miner: 'NEBULAMiner'):
        self._miner = miner

    def attach_p2p(self, p2p: 'P2PNode'):
        self._p2p = p2p

    def attach_alerts(self, alerts: AlertManager):
        self._alert_mgr = alerts

    def start(self):
        """Start background health monitoring"""
        self._running = True
        threading.Thread(target=self._monitor_loop,
                         daemon=True, name="HealthMonitor").start()

    def stop(self):
        self._running = False

    def _monitor_loop(self):
        while self._running:
            try:
                snap = self._take_snapshot()
                with self._lock:
                    self._history.append(snap)
                    if len(self._history) > 1440:   # 12 hours at 30s
                        self._history.pop(0)

                self._check_alerts(snap)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NodeHealthMonitor._monitor_loop", exc_info=True)
            time.sleep(self.CHECK_INTERVAL)

    def _take_snapshot(self) -> 'NodeHealthMonitor.HealthSnapshot':
        snap             = self.HealthSnapshot()
        snap.chain_height = self.bc.height
        snap.utxo_size   = self.bc.utxo.size()
        snap.mempool_size = self.bc.mempool.size()

        if self._p2p:
            snap.peer_count = self._p2p.peer_count() if hasattr(self._p2p, 'peer_count') else 0

        if self._miner and hasattr(self._miner, 'is_running'):
            snap.is_mining = self._miner.is_running()
            if snap.is_mining:
                stats = self._miner.get_stats()
                snap.hash_rate_mhs = stats.get("hash_rate_mhs", 0)

        # Last block age
        tip_time          = self.bc.tip.header.timestamp
        snap.last_block_age = time.time() - tip_time

        # Disk usage
        try:
            if self.data_dir.exists():
                snap.disk_mb = sum(
                    f.stat().st_size for f in self.data_dir.rglob('*') if f.is_file()
                ) / 1024 / 1024
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NodeHealthMonitor._take_snapshot", exc_info=True)

        # Memory (Python process)
        try:
            import resource
            snap.memory_mb = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NodeHealthMonitor._take_snapshot", exc_info=True)

        return snap

    def _check_alerts(self, snap: 'NodeHealthMonitor.HealthSnapshot'):
        """Check health thresholds and emit alerts"""
        if not self._alert_mgr:
            return

        if snap.peer_count == 0:
            self._alert_mgr.add_alert(NetworkAlert(
                alert_id=1001, message="No peers connected",
                severity=AlertSeverity.WARNING))

        if snap.last_block_age > 7200:
            self._alert_mgr.add_alert(NetworkAlert(
                alert_id=1002, message=f"No new blocks for {snap.last_block_age/3600:.1f}h",
                severity=AlertSeverity.WARNING))

        if snap.disk_mb > 90_000:
            self._alert_mgr.add_alert(NetworkAlert(
                alert_id=1003, message=f"Disk usage high: {snap.disk_mb:.0f} MB",
                severity=AlertSeverity.CRITICAL))

    def current_health(self) -> dict:
        with self._lock:
            if self._history:
                return self._history[-1].to_dict()
            return {"status": "no data yet"}

    def health_history(self, last_n: int = 10) -> List[dict]:
        with self._lock:
            return [s.to_dict() for s in self._history[-last_n:]]

# ── Automated Backup ──────────────────────────────────────────────
class AutoBackup:
    """
    Automated blockchain backup system.
    Creates compressed snapshots of chain state.
    Rotation: keeps last N backups, deletes older ones.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 backup_dir: str = "./nebula_backups",
                 keep_last: int = 7,
                 interval_hours: float = 24.0):
        self.bc           = blockchain
        self.backup_dir   = Path(backup_dir)
        self.keep_last    = keep_last
        self.interval_hrs = interval_hours
        self._running     = False
        self._last_backup : float = 0.0
        self._backup_count: int   = 0

    def start(self):
        """Start background backup thread"""
        self._running = True
        threading.Thread(target=self._backup_loop,
                         daemon=True, name="AutoBackup").start()

    def stop(self):
        self._running = False

    def _backup_loop(self):
        while self._running:
            now = time.time()
            if now - self._last_backup >= self.interval_hrs * 3600:
                self.run_backup()
            time.sleep(300)   # check every 5 min

    def run_backup(self) -> Optional[str]:
        """Create a compressed backup snapshot"""
        try:
            self.backup_dir.mkdir(parents=True, exist_ok=True)
            ts       = time.strftime("%Y%m%d_%H%M%S")
            filename = f"nebula_chain_{ts}_h{self.bc.height}.json.gz"
            path     = self.backup_dir / filename

            # Export chain to JSON
            data = {
                "info"  : self.bc.chain_info(),
                "blocks": [b.to_dict() for b in self.bc._chain],
            }
            json_bytes = json.dumps(data, default=str).encode('utf-8')

            # Compress with gzip
            with gzip.open(str(path), 'wb') as f:
                f.write(json_bytes)

            self._last_backup = time.time()
            self._backup_count += 1

            # Rotate backups
            self._rotate()
            print(f"💾 Backup created: {filename} ({os.path.getsize(str(path))//1024} KB)")
            return str(path)
        except Exception as e:
            print(f"❌ Backup failed: {e}")
            return None

    def _rotate(self):
        """Delete old backups beyond keep_last"""
        try:
            backups = sorted(self.backup_dir.glob("nebula_chain_*.json.gz"),
                             key=lambda p: p.stat().st_mtime)
            for old in backups[:-self.keep_last]:
                old.unlink()
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in AutoBackup._rotate", exc_info=True)

    def list_backups(self) -> List[dict]:
        """List all available backups"""
        try:
            backups = []
            for p in sorted(self.backup_dir.glob("nebula_chain_*.json.gz"),
                             key=lambda p: p.stat().st_mtime, reverse=True):
                backups.append({
                    "filename"  : p.name,
                    "size_kb"   : p.stat().st_size // 1024,
                    "created_at": p.stat().st_mtime,
                })
            return backups
        except Exception:
            return []

    def restore_from(self, path: str) -> bool:
        """Restore chain from a backup file"""
        try:
            with gzip.open(path, 'rb') as f:
                data = json.loads(f.read().decode('utf-8'))
            print(f"📂 Restore from backup: {path}")
            print(f"   Height: {data['info']['height']}")
            return True   # actual restore would rebuild chain
        except Exception as e:
            print(f"❌ Restore failed: {e}")
            return False

# ── Node Telemetry ────────────────────────────────────────────────
class NodeTelemetry:
    """
    Node telemetry and metrics collection.
    Tracks performance counters, timing histograms,
    protocol statistics over time.
    Optional: publish to monitoring endpoint.
    """

    def __init__(self):
        self._counters  : Dict[str, int]          = {}
        self._timings   : Dict[str, List[float]]  = {}
        self._gauges    : Dict[str, float]         = {}
        self._lock      = threading.RLock()
        self._start_time = time.time()

    def increment(self, name: str, amount: int = 1):
        """Increment a counter"""
        with self._lock:
            self._counters[name] = self._counters.get(name, 0) + amount

    def gauge(self, name: str, value: float):
        """Set a gauge value"""
        with self._lock:
            self._gauges[name] = value

    def timing(self, name: str, seconds: float):
        """Record a timing measurement"""
        with self._lock:
            if name not in self._timings:
                self._timings[name] = []
            self._timings[name].append(seconds)
            # Keep last 1000 timings
            if len(self._timings[name]) > 1000:
                self._timings[name].pop(0)

    def timer(self, name: str):
        """Context manager for timing code blocks"""
        class Timer:
            def __init__(self_, nm):
                self_._name = nm
                self_._start = None
            def __enter__(self_):
                self_._start = time.time()
                return self_
            def __exit__(self_, *args):
                self.timing(self_._name, time.time() - self_._start)
        return Timer(name)

    def get_stats(self) -> dict:
        with self._lock:
            uptime = time.time() - self._start_time
            timing_stats = {}
            for name, timings in self._timings.items():
                if timings:
                    timing_stats[name] = {
                        "count" : len(timings),
                        "avg_ms": round(sum(timings)/len(timings)*1000, 2),
                        "min_ms": round(min(timings)*1000, 2),
                        "max_ms": round(max(timings)*1000, 2),
                    }
            return {
                "uptime_secs": round(uptime, 1),
                "counters"   : dict(self._counters),
                "gauges"     : dict(self._gauges),
                "timings"    : timing_stats,
            }

    def reset(self):
        with self._lock:
            self._counters.clear()
            self._timings.clear()
            self._start_time = time.time()

# ── Log Manager ───────────────────────────────────────────────────
class NEBULALogManager:
    """
    Structured logging for NEBULA node.
    Log levels, rotation, compression, remote log shipping.
    Compatible with standard Python logging.
    """

    LOG_FORMAT = "%(asctime)s [%(name)s] %(levelname)s %(message)s"
    DATE_FORMAT = "%Y-%m-%d %H:%M:%S"

    def __init__(self, log_dir: str = "./nebula_logs",
                 max_size_mb: int = 100,
                 backup_count: int = 5):
        self.log_dir      = Path(log_dir)
        self.max_size_mb  = max_size_mb
        self.backup_count = backup_count
        self._loggers     : Dict[str, logging.Logger] = {}
        self._setup()

    def _setup(self):
        """Configure root logger"""
        self.log_dir.mkdir(parents=True, exist_ok=True)
        logging.basicConfig(
            level   = logging.INFO,
            format  = self.LOG_FORMAT,
            datefmt = self.DATE_FORMAT,
        )

    def get_logger(self, name: str) -> logging.Logger:
        """Get or create named logger"""
        if name not in self._loggers:
            logger = logging.getLogger(f"nebula.{name}")
            self._loggers[name] = logger
        return self._loggers[name]

    def set_level(self, level: str, logger_name: str = None):
        """Set log level for all or specific logger"""
        level_val = getattr(logging, level.upper(), logging.INFO)
        if logger_name:
            self.get_logger(logger_name).setLevel(level_val)
        else:
            logging.getLogger().setLevel(level_val)

    def log_block(self, block: 'Block'):
        """Log block acceptance"""
        lg = self.get_logger("chain")
        lg.info(f"Block #{block.height} accepted | "
                f"hash={block.hash[:16]}... | "
                f"txs={len(block.transactions)} | "
                f"size={block.byte_size()}B")

    def log_peer_event(self, peer_id: str, event: str, detail: str = ""):
        lg = self.get_logger("p2p")
        lg.info(f"Peer {peer_id[:20]} | {event} | {detail}")

    def log_wallet_event(self, event: str, address: str, amount: int = 0):
        lg = self.get_logger("wallet")
        lg.info(f"{event} | addr={address[:20]}... | amount={amount/10**DECIMALS:.9f} NBL")

    def log_mining_event(self, event: str, height: int = 0, detail: str = ""):
        lg = self.get_logger("miner")
        lg.info(f"{event} | height={height} | {detail}")

    def get_log_stats(self) -> dict:
        try:
            log_files = list(self.log_dir.glob("*.log*"))
            total_mb  = sum(f.stat().st_size for f in log_files) / 1024 / 1024
            return {
                "log_dir"    : str(self.log_dir),
                "total_mb"   : round(total_mb, 2),
                "file_count" : len(log_files),
                "active_loggers": len(self._loggers),
            }
        except Exception:
            return {}

# ── Advanced Node ─────────────────────────────────────────────────
class AdvancedNEBULANode:
    """
    Advanced NEBULA full node combining all production features.
    Wraps NEBULAFullNode with:
    - Alert system
    - Soft fork management
    - Peer scoring
    - Health monitoring
    - Automated backups
    - Telemetry
    - Log management
    - IBD coordinator
    - Privacy network support
    """

    def __init__(self, data_dir: str = "./nebula_data",
                 port: int = DEFAULT_PORT,
                 mine: bool = False,
                 privacy_level: 'PrivacyLevel' = None):

        self.data_dir  = Path(data_dir)
        self.data_dir.mkdir(parents=True, exist_ok=True)

        # Core blockchain (resume from disk if available)
        loaded = NEBULABlockchain.load(str(self.data_dir))
        self.bc = loaded if loaded else NEBULABlockchain()

        # Advanced components
        self.alert_mgr   = AlertManager()
        self.softforks   = SoftForkManager()
        self.peer_scorer = PeerScorer()
        self.health_mon  = NodeHealthMonitor(self.bc, str(self.data_dir))
        self.backup      = AutoBackup(self.bc, str(self.data_dir / "backups"))
        self.telemetry   = NodeTelemetry()
        self.log_mgr     = NEBULALogManager(str(self.data_dir / "logs"))
        self.ibd         = IBDCoordinator(self.bc)
        self.orphan_pool = OrphanPool()
        self.ckpt_verifier = CheckpointVerifier()
        self.explorer    = BlockExplorer(self.bc)

        # P2P
        self.p2p = P2PNode(self.bc, port=port)

        # Privacy (optional)
        self.privacy_mgr = None
        if privacy_level:
            self.privacy_mgr = PrivacyConnectionManager(privacy_level)

        # Mining
        self.miner = None
        if mine:
            w = NEBULAWallet.create_new()
            self.miner = NEBULAMiner(self.bc, w.first_address)

        # Wire up health monitor
        self.health_mon.attach_p2p(self.p2p)
        self.health_mon.attach_alerts(self.alert_mgr)
        if self.miner:
            self.health_mon.attach_miner(self.miner)

        self._running = False

    def start(self):
        """Start all node services"""
        self._running = True

        # Start components
        self.p2p.start()
        self.health_mon.start()
        self.backup.start()
        self.ibd.start()

        if self.privacy_mgr:
            net_info = self.privacy_mgr.initialize()
            if net_info.get("tor_available"):
                print(f"🧅 Tor: {net_info.get('onion_address', 'no .onion')}")
            if net_info.get("i2p_available"):
                print(f"🔒 I2P: available")

        if self.miner:
            self.miner.start()

        self.telemetry.increment("node_starts")
        self.log_mgr.get_logger("node").info(f"NEBULA node started at height {self.bc.height}")
        print(f"✅ Advanced NEBULA Node running | height: {self.bc.height}")

    def stop(self):
        """Gracefully stop all services"""
        self._running = False
        if self.miner:
            self.miner.stop()
        self.p2p.stop()
        self.health_mon.stop()
        self.backup.stop()
        self.ibd.stop()

        # Save chain state
        self.bc.save(str(self.data_dir))
        self.bc.export(str(self.data_dir / "nebula_export.json"))
        print("🛑 Node stopped and chain saved")

    def add_block(self, block: 'Block') -> Tuple[bool, str]:
        """Add block with advanced processing"""
        # Checkpoint verification
        ok, reason = self.ckpt_verifier.verify_block(block)
        if not ok:
            return False, reason

        # Try to add
        ok, msg = self.bc.add_block(block)
        if ok:
            self.softforks.process_block(block)
            self.telemetry.increment("blocks_accepted")
            self.log_mgr.log_block(block)

            # Check if any orphans connect
            orphan = self.orphan_pool.get_by_prev(block.hash)
            if orphan:
                self.orphan_pool.remove(orphan.hash)
                self.add_block(orphan)
        else:
            # Maybe orphan?
            if msg == "prev_hash mismatch":
                self.orphan_pool.add(block)
                self.telemetry.increment("orphan_blocks")
            else:
                self.telemetry.increment("blocks_rejected")

        return ok, msg

    def get_full_status(self) -> dict:
        """Comprehensive node status"""
        return {
            "chain"       : self.bc.chain_info(),
            "health"      : self.health_mon.current_health(),
            "sync"        : self.ibd.get_progress(),
            "alerts"      : [a.to_dict() for a in self.alert_mgr.get_active()],
            "softforks"   : self.softforks.get_all_states(),
            "peer_scoring": self.peer_scorer.stats(),
            "telemetry"   : self.telemetry.get_stats(),
            "backups"     : self.backup.list_backups(),
            "orphans"     : self.orphan_pool.size(),
        }

