# ── Advanced Script Opcodes ───────────────────────────────────────
class AdvancedOP(IntEnum):
    """
    Extended opcode set for NEBULA smart contracts.
    Includes Bitcoin opcodes + NEBULA-specific extensions.
    """
    # Control
    OP_NOP          = 0x61
    OP_VER          = 0x62
    OP_IF           = 0x63
    OP_NOTIF        = 0x64
    OP_ELSE         = 0x67
    OP_ENDIF        = 0x68
    OP_VERIFY       = 0x69
    OP_RETURN       = 0x6a
    OP_TOALTSTACK   = 0x6b
    OP_FROMALTSTACK = 0x6c
    OP_IFDUP        = 0x73
    OP_DEPTH        = 0x74
    OP_DROP         = 0x75
    OP_DUP          = 0x76
    OP_NIP          = 0x77
    OP_OVER         = 0x79
    OP_PICK         = 0x79
    OP_ROLL         = 0x7a
    OP_ROT          = 0x7b
    OP_SWAP         = 0x7c
    OP_TUCK         = 0x7d
    OP_2DROP        = 0x6d
    OP_2DUP         = 0x6e
    OP_3DUP         = 0x6f
    OP_2OVER        = 0x70
    OP_2ROT         = 0x71
    OP_2SWAP        = 0x72

    # Arithmetic
    OP_1ADD         = 0x8b
    OP_1SUB         = 0x8c
    OP_NEGATE       = 0x8f
    OP_ABS          = 0x90
    OP_NOT          = 0x91
    OP_0NOTEQUAL    = 0x92
    OP_ADD          = 0x93
    OP_SUB          = 0x94
    OP_MUL          = 0x95
    OP_DIV          = 0x96
    OP_MOD          = 0x97
    OP_BOOLAND      = 0x9a
    OP_BOOLOR       = 0x9b
    OP_NUMEQUAL     = 0x9c
    OP_NUMEQUALVERIFY = 0x9d
    OP_NUMNOTEQUAL  = 0x9e
    OP_LESSTHAN     = 0x9f
    OP_GREATERTHAN  = 0xa0
    OP_LESSTHANOREQUAL = 0xa1
    OP_GREATERTHANOREQUAL = 0xa2
    OP_MIN          = 0xa3
    OP_MAX          = 0xa4
    OP_WITHIN       = 0xa5

    # Crypto
    OP_RIPEMD160    = 0xa6
    OP_SHA1         = 0xa7
    OP_SHA256       = 0xa8
    OP_HASH160      = 0xa9
    OP_HASH256      = 0xaa
    OP_CODESEPARATOR= 0xab
    OP_CHECKSIG     = 0xac
    OP_CHECKSIGVERIFY = 0xad
    OP_CHECKMULTISIG= 0xae
    OP_CHECKMULTISIGVERIFY = 0xaf

    # Tapscript (BIP342)
    OP_CHECKSIGADD  = 0xba

    # NEBULA Extensions
    OP_CHECKTEMPLATEVERIFY = 0xb3   # BIP119 CTV
    OP_CHECKSIGFROMSTACK   = 0xcc   # CSFS
    OP_CAT                 = 0x7e   # Re-enabled in NEBULA
    OP_SPLIT               = 0x7f   # Split byte array
    OP_NUM2BIN             = 0x80   # Number to bytes
    OP_BIN2NUM             = 0x81   # Bytes to number

# ── Covenant: CheckTemplateVerify (BIP119) ────────────────────────
class CTV:
    """
    BIP119 OP_CHECKTEMPLATEVERIFY (CTV).
    Commits to the template of a spending transaction:
    version, locktime, sequences, outputs.
    Enables: payment pools, congestion control, vaults.
    """

    @staticmethod
    def compute_template_hash(tx: 'Transaction',
                               input_index: int = 0) -> bytes:
        """
        Compute CTV template hash for a transaction.
        Hash commits to: version, locktime, n_inputs, sequences,
                         n_outputs, outputs, input_index.
        """
        def _varint(n):
            if n < 0xfd: return bytes([n])
            return b'\xfd' + struct.pack('<H', n)

        # Serialize outputs
        outputs_ser = b''.join(
            struct.pack('<q', out.value) +
            _varint(len(out.script_pubkey)) + out.script_pubkey
            for out in tx.outputs
        )

        # Serialize sequences
        sequences_ser = b''.join(
            struct.pack('<I', inp.sequence)
            for inp in tx.inputs
        )

        preimage = (
            struct.pack('<i', tx.version) +
            struct.pack('<I', tx.locktime) +
            hashlib.sha256(sequences_ser).digest() +
            _varint(len(tx.inputs)) +
            _varint(len(tx.outputs)) +
            hashlib.sha256(outputs_ser).digest() +
            struct.pack('<I', input_index)
        )
        return hashlib.sha256(preimage).digest()

    @staticmethod
    def build_ctv_script(template_hash: bytes) -> bytes:
        """
        Build CTV locking script.
        Script: <template_hash> OP_CHECKTEMPLATEVERIFY OP_DROP OP_TRUE
        """
        return (bytes([len(template_hash)]) + template_hash +
                bytes([AdvancedOP.OP_CHECKTEMPLATEVERIFY, 0x75, 0x51]))

    @staticmethod
    def verify_ctv(template_hash: bytes, tx: 'Transaction',
                    input_index: int = 0) -> bool:
        """Verify that tx matches the CTV template"""
        computed = CTV.compute_template_hash(tx, input_index)
        return computed == template_hash

# ── Payment Vault ─────────────────────────────────────────────────
class PaymentVault:
    """
    CTV-based payment vault.
    Funds locked in vault can only be spent to a pre-committed recovery
    address after a time delay, OR immediately to a hot wallet.
    Protects against theft: attacker must wait for recovery period.
    """

    def __init__(self, hot_key: int, recovery_key: int,
                 recovery_delay: int = 144):
        """
        hot_key:       immediate spending key (online)
        recovery_key:  recovery key (offline/hardware)
        recovery_delay: blocks before recovery is possible (default: 1 day)
        """
        self.hot_key        = hot_key
        self.recovery_key   = recovery_key
        self.recovery_delay = recovery_delay

        self.hot_pub      = Secp256k1.pubkey_to_bytes(
            Secp256k1.point_mul(hot_key, Secp256k1.G()))
        self.recovery_pub = Secp256k1.pubkey_to_bytes(
            Secp256k1.point_mul(recovery_key, Secp256k1.G()))
        self.hot_addr     = Script.p2pkh_address(self.hot_pub)
        self.recovery_addr= Script.p2pkh_address(self.recovery_pub)

    def vault_script(self) -> bytes:
        """
        Build vault locking script.
        Can spend immediately with hot key,
        OR after delay with recovery key.
        """
        hot_h160       = hash160(self.hot_pub)
        recovery_h160  = hash160(self.recovery_pub)
        delay_script   = struct.pack('<I', self.recovery_delay)[:3]

        # Script: IF OP_DUP OP_HASH160 <hot_h160> OP_EQUALVERIFY OP_CHECKSIG
        #         ELSE <delay> OP_CSV OP_DROP OP_DUP OP_HASH160 <rec_h160> OP_EQUALVERIFY OP_CHECKSIG
        #         ENDIF
        return (bytes([0x63]) +   # OP_IF
                bytes([0x76, 0xa9, 0x14]) + hot_h160 + bytes([0x88, 0xac]) +
                bytes([0x67]) +   # OP_ELSE
                bytes([len(delay_script)]) + delay_script +
                bytes([0xb2, 0x75]) +   # OP_CSV OP_DROP
                bytes([0x76, 0xa9, 0x14]) + recovery_h160 + bytes([0x88, 0xac]) +
                bytes([0x68]))    # OP_ENDIF

    def vault_address(self) -> str:
        """P2SH address for the vault"""
        script = self.vault_script()
        script_hash = hash160(script)
        return base58check_encode(script_hash, SCRIPT_ADDRESS_VERSION)

    def spend_hot(self, tx: 'Transaction', input_index: int,
                  utxo_value: int) -> 'Transaction':
        """Build and sign immediate hot wallet spend"""
        locking  = self.vault_script()
        sighash  = tx.signature_hash(input_index, locking, SIGHASH_ALL)
        r, s     = Secp256k1.sign(self.hot_key, sighash)
        der      = Secp256k1.sig_to_der(r, s) + bytes([SIGHASH_ALL])
        redeem   = self.vault_script()
        # scriptSig: <sig> <pubkey> <1 (hot path)> <redeemScript>
        sig_push = bytes([len(der)]) + der
        pub_push = bytes([len(self.hot_pub)]) + self.hot_pub
        rs_push  = bytes([len(redeem)]) + redeem
        tx.inputs[input_index].script_sig = sig_push + pub_push + bytes([0x51]) + rs_push
        tx.invalidate_cache()
        return tx

    def to_dict(self) -> dict:
        return {
            "vault_address"   : self.vault_address(),
            "hot_address"     : self.hot_addr,
            "recovery_address": self.recovery_addr,
            "recovery_delay"  : self.recovery_delay,
            "delay_hours"     : self.recovery_delay * 10 / 60,
        }

# ── Discreet Log Contract (DLC) ───────────────────────────────────
# [v10.19] dead class DLCOracle removed from host - no live copy exists; original kept in nebula_removed_dead_classes.py

@dataclass
class DLCContract:
    """
    Discreet Log Contract between two parties.
    Outcome determined by oracle attestation.
    All outcome scripts pre-computed — oracle doesn't know contract exists.
    """
    party_a_key   : int
    party_b_key   : int
    oracle_pubkey : bytes
    oracle_nonce  : bytes
    outcomes      : Dict[str, Tuple[int, int]]   # outcome -> (a_payout, b_payout) in neb
    collateral    : int                            # total locked amount
    funding_txid  : str = ""
    funding_vout  : int = 0
    maturity_time : int = 0

    @property
    def party_a_pub(self) -> bytes:
        return Secp256k1.pubkey_to_bytes(
            Secp256k1.point_mul(self.party_a_key, Secp256k1.G()))

    @property
    def party_b_pub(self) -> bytes:
        return Secp256k1.pubkey_to_bytes(
            Secp256k1.point_mul(self.party_b_key, Secp256k1.G()))

    def funding_script(self) -> bytes:
        """2-of-2 multisig funding script"""
        return (bytes([0x52]) +   # OP_2
                bytes([len(self.party_a_pub)]) + self.party_a_pub +
                bytes([len(self.party_b_pub)]) + self.party_b_pub +
                bytes([0x52, 0xae]))  # OP_2 OP_CHECKMULTISIG

    def outcome_script(self, winner_pub: bytes) -> bytes:
        """Script for a specific outcome winner"""
        h160 = hash160(winner_pub)
        return bytes([0x76, 0xa9, 0x14]) + h160 + bytes([0x88, 0xac])

    def compute_cet(self, outcome: str) -> Optional[dict]:
        """
        Compute Contract Execution Transaction (CET) for an outcome.
        Returns unsigned CET dict.
        """
        if outcome not in self.outcomes:
            return None
        a_payout, b_payout = self.outcomes[outcome]

        outputs = []
        if a_payout >= DUST_THRESHOLD:
            outputs.append({"value": a_payout, "script": self.outcome_script(self.party_a_pub).hex()})
        if b_payout >= DUST_THRESHOLD:
            outputs.append({"value": b_payout, "script": self.outcome_script(self.party_b_pub).hex()})

        return {
            "outcome" : outcome,
            "inputs"  : [{"txid": self.funding_txid, "vout": self.funding_vout}],
            "outputs" : outputs,
            "locktime": self.maturity_time,
        }

    def to_dict(self) -> dict:
        return {
            "party_a"       : Script.p2pkh_address(self.party_a_pub),
            "party_b"       : Script.p2pkh_address(self.party_b_pub),
            "oracle_pubkey" : self.oracle_pubkey.hex(),
            "collateral_nbl": f"{self.collateral/10**DECIMALS:.9f}",
            "outcomes"      : {k: {"a": v[0], "b": v[1]} for k, v in self.outcomes.items()},
            "funding_txid"  : self.funding_txid,
            "maturity"      : self.maturity_time,
        }

# ── Payment Pool (CTV-based) ──────────────────────────────────────
class PaymentPool:
    """
    CTV-based payment pool (congestion control).
    Multiple payments batched into a single on-chain transaction.
    Individual payments settled off-chain, only exceptions go on-chain.
    Scales: 1 on-chain tx can settle thousands of payments.
    """

    def __init__(self, participants: List[Tuple[str, int]]):
        """
        participants: [(address, initial_balance_neb), ...]
        """
        self._participants = dict(participants)
        self._pending      : List[Tuple[str,str,int]] = []
        self._lock         = threading.RLock()

    def queue_payment(self, from_addr: str,
                       to_addr: str, amount: int) -> bool:
        """Queue an off-chain payment within the pool"""
        with self._lock:
            if self._participants.get(from_addr, 0) < amount:
                return False
            self._participants[from_addr] = self._participants.get(from_addr, 0) - amount
            self._participants[to_addr]   = self._participants.get(to_addr, 0) + amount
            self._pending.append((from_addr, to_addr, amount))
            return True

    def build_settlement_tx(self, fee: int = MIN_TX_FEE) -> Optional['Transaction']:
        """
        Build on-chain settlement transaction for current pool state.
        Uses CTV to commit to the exact distribution of funds.
        """
        outputs = []
        for addr, balance in self._participants.items():
            if balance >= DUST_THRESHOLD:
                script = Script.p2pkh_locking_from_address(addr)
                outputs.append(TxOutput(balance, script))

        if not outputs:
            return None

        # Adjust for fee (deduct from largest output)
        outputs.sort(key=lambda o: o.value, reverse=True)
        if outputs[0].value > fee:
            outputs[0] = TxOutput(outputs[0].value - fee, outputs[0].script_pubkey)

        return Transaction(outputs=outputs)

    def get_balances(self) -> Dict[str, float]:
        """Get current pool balances"""
        return {addr: bal / 10**DECIMALS
                for addr, bal in self._participants.items()}

    def pending_count(self) -> int:
        return len(self._pending)

    def to_dict(self) -> dict:
        return {
            "participants" : len(self._participants),
            "pending_txs"  : len(self._pending),
            "total_value"  : sum(self._participants.values()) / 10**DECIMALS,
        }

# ── Contract Registry ─────────────────────────────────────────────
class AdvancedContractRegistry:
    """
    Registry for all deployed advanced contracts.
    Tracks: vaults, DLCs, payment pools, CTV covenants.
    """

    def __init__(self):
        self._vaults  : Dict[str, PaymentVault]  = {}
        self._dlcs    : Dict[str, DLCContract]   = {}
        self._pools   : Dict[str, PaymentPool]   = {}
        self._covenants: Dict[str, bytes]         = {}
        self._lock    = threading.RLock()

    def register_vault(self, vault: PaymentVault) -> str:
        addr = vault.vault_address()
        with self._lock:
            self._vaults[addr] = vault
        return addr

    def register_dlc(self, dlc: DLCContract) -> str:
        cid = hashlib.sha256(
            dlc.party_a_pub + dlc.party_b_pub + dlc.oracle_pubkey
        ).hexdigest()[:32]
        with self._lock:
            self._dlcs[cid] = dlc
        return cid

    def register_pool(self, pool: PaymentPool) -> str:
        pid = hashlib.sha256(
            str(id(pool)).encode() + secrets.token_bytes(8)
        ).hexdigest()[:16]
        with self._lock:
            self._pools[pid] = pool
        return pid

    def get_vault(self, addr: str) -> Optional[PaymentVault]:
        return self._vaults.get(addr)

    def get_dlc(self, contract_id: str) -> Optional[DLCContract]:
        return self._dlcs.get(contract_id)

    def get_pool(self, pool_id: str) -> Optional[PaymentPool]:
        return self._pools.get(pool_id)

    def stats(self) -> dict:
        with self._lock:
            return {
                "vaults"    : len(self._vaults),
                "dlcs"      : len(self._dlcs),
                "pools"     : len(self._pools),
                "covenants" : len(self._covenants),
            }

