import threading, time, json, hashlib, secrets
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
from pathlib import Path

# ── Contact Types ─────────────────────────────────────────────────
class ContactType(Enum):
    PERSONAL   = "personal"
    BUSINESS   = "business"
    EXCHANGE   = "exchange"
    MINING     = "mining"
    FOUNDATION = "foundation"
    UNKNOWN    = "unknown"

# ── Contact ───────────────────────────────────────────────────────
@dataclass
class Contact:
    """A named contact with one or more NEBULA addresses"""
    name        : str
    addresses   : List[str] = field(default_factory=list)
    contact_type: ContactType = ContactType.UNKNOWN
    notes       : str = ""
    email       : str = ""
    website     : str = ""
    created_at  : float = field(default_factory=time.time)
    last_used   : float = 0.0
    tx_count    : int   = 0
    total_sent  : int   = 0    # neb
    total_recv  : int   = 0    # neb
    is_favorite : bool  = False
    tags        : List[str] = field(default_factory=list)
    avatar_hash : str   = ""    # SHA256 of contact name for identicon

    def __post_init__(self):
        if not self.avatar_hash:
            self.avatar_hash = hashlib.sha256(self.name.encode()).hexdigest()[:8]

    def add_address(self, address: str):
        if address not in self.addresses:
            self.addresses.append(address)
            self.last_used = time.time()

    def primary_address(self) -> Optional[str]:
        return self.addresses[0] if self.addresses else None

    def matches(self, query: str) -> bool:
        """Fuzzy search across all fields"""
        q = query.lower()
        return (q in self.name.lower() or
                q in self.notes.lower() or
                q in self.email.lower() or
                any(q in addr.lower() for addr in self.addresses) or
                any(q in tag.lower() for tag in self.tags))

    def to_dict(self) -> dict:
        return {
            "name"         : self.name,
            "addresses"    : self.addresses,
            "type"         : self.contact_type.value,
            "notes"        : self.notes,
            "email"        : self.email,
            "website"      : self.website,
            "created_at"   : self.created_at,
            "last_used"    : self.last_used,
            "tx_count"     : self.tx_count,
            "total_sent"   : self.total_sent,
            "total_recv"   : self.total_recv,
            "is_favorite"  : self.is_favorite,
            "tags"         : self.tags,
            "avatar_hash"  : self.avatar_hash,
        }

    @classmethod
    def from_dict(cls, d: dict) -> 'Contact':
        c = cls(
            name         = d.get("name", ""),
            addresses    = d.get("addresses", []),
            notes        = d.get("notes", ""),
            email        = d.get("email", ""),
            website      = d.get("website", ""),
            created_at   = d.get("created_at", time.time()),
            last_used    = d.get("last_used", 0.0),
            tx_count     = d.get("tx_count", 0),
            total_sent   = d.get("total_sent", 0),
            total_recv   = d.get("total_recv", 0),
            is_favorite  = d.get("is_favorite", False),
            tags         = d.get("tags", []),
        )
        try:
            c.contact_type = ContactType(d.get("type", "unknown"))
        except ValueError:
            c.contact_type = ContactType.UNKNOWN
        return c

# ── Address Book ─────────────────────────────────────────────────
class AddressBook:
    """
    Full-featured address book for NEBULA wallet.
    Features:
    - Contact management with tags and notes
    - Address search and filtering
    - Transaction history per contact
    - Import/export (CSV, JSON)
    - Address reuse warnings
    - Duplicate detection
    """

    def __init__(self, data_dir: str = "./nebula_data"):
        self._contacts : Dict[str, Contact] = {}   # name -> Contact
        self._addr_idx : Dict[str, str]     = {}   # address -> name
        self._lock     = threading.RLock()
        self._path     = Path(data_dir) / "address_book.json"
        self._used_addrs: set = set()   # track address reuse
        self._load()

        # Add foundation as default contact
        self._ensure_foundation_contact()

    def _ensure_foundation_contact(self):
        """Add NEBULA Foundation as built-in contact"""
        if "NEBULA Foundation" not in self._contacts:
            c = Contact(
                name         = "NEBULA Foundation",
                addresses    = [FOUNDATION_ADDRESS],
                contact_type = ContactType.FOUNDATION,
                notes        = "NEBULA Development Foundation — 2% block reward",
                is_favorite  = True,
                tags         = ["foundation", "developer", "official"],
            )
            self.add_contact(c)

    # ── CRUD ─────────────────────────────────────────────────────
    def add_contact(self, contact: Contact) -> bool:
        """Add or update a contact"""
        with self._lock:
            # Check for duplicate addresses
            for addr in contact.addresses:
                existing = self._addr_idx.get(addr)
                if existing and existing != contact.name:
                    return False   # address belongs to different contact

            self._contacts[contact.name] = contact
            for addr in contact.addresses:
                self._addr_idx[addr] = contact.name

            self._save()
            return True

    def remove_contact(self, name: str) -> bool:
        """Remove a contact"""
        with self._lock:
            contact = self._contacts.pop(name, None)
            if contact:
                for addr in contact.addresses:
                    self._addr_idx.pop(addr, None)
                self._save()
                return True
            return False

    def get_contact(self, name: str) -> Optional[Contact]:
        return self._contacts.get(name)

    def get_by_address(self, address: str) -> Optional[Contact]:
        name = self._addr_idx.get(address)
        return self._contacts.get(name) if name else None

    def add_address_to_contact(self, name: str, address: str) -> bool:
        """Add an address to existing contact"""
        with self._lock:
            contact = self._contacts.get(name)
            if not contact:
                return False
            if address in self._addr_idx:
                return False   # already assigned
            contact.add_address(address)
            self._addr_idx[address] = name
            self._save()
            return True

    # ── Search ────────────────────────────────────────────────────
    def search(self, query: str) -> List[Contact]:
        """Search contacts by name, address, notes, tags"""
        with self._lock:
            return [c for c in self._contacts.values() if c.matches(query)]

    def list_all(self, sort_by: str = "name") -> List[Contact]:
        """List all contacts sorted by field"""
        with self._lock:
            contacts = list(self._contacts.values())
            if sort_by == "name":
                contacts.sort(key=lambda c: c.name.lower())
            elif sort_by == "last_used":
                contacts.sort(key=lambda c: c.last_used, reverse=True)
            elif sort_by == "tx_count":
                contacts.sort(key=lambda c: c.tx_count, reverse=True)
            return contacts

    def get_favorites(self) -> List[Contact]:
        with self._lock:
            return [c for c in self._contacts.values() if c.is_favorite]

    def get_by_tag(self, tag: str) -> List[Contact]:
        with self._lock:
            return [c for c in self._contacts.values() if tag in c.tags]

    def get_by_type(self, ctype: ContactType) -> List[Contact]:
        with self._lock:
            return [c for c in self._contacts.values()
                    if c.contact_type == ctype]

    # ── Address reuse detection ───────────────────────────────────
    def check_reuse(self, address: str) -> Tuple[bool, str]:
        """
        Check if address has been used before (reuse warning).
        Returns (is_reused, reason).
        """
        if address in self._used_addrs:
            contact = self.get_by_address(address)
            name    = contact.name if contact else "unknown"
            return True, f"Address previously used by '{name}'"
        return False, "Fresh address"

    def mark_used(self, address: str):
        """Mark address as used"""
        self._used_addrs.add(address)
        import time as _t
        entry = self.get_contact(address)
        if entry:
            entry.last_used = _t.time()
            entry.use_count = getattr(entry, 'use_count', 0) + 1

    # ── Transaction recording ─────────────────────────────────────
    def record_transaction(self, address: str,
                            txid: str, amount: int,
                            direction: str = "sent"):
        """Record a transaction against a contact"""
        with self._lock:
            contact = self.get_by_address(address)
            if contact:
                contact.tx_count += 1
                contact.last_used = time.time()
                if direction == "sent":
                    contact.total_sent += amount
                else:
                    contact.total_recv += amount
                self.mark_used(address)
                self._save()

    # ── Import / Export ───────────────────────────────────────────
    def export_json(self) -> str:
        with self._lock:
            data = [c.to_dict() for c in self._contacts.values()]
            return json.dumps(data, indent=2)

    def export_csv(self) -> str:
        """Export as CSV (compatible with most wallet apps)"""
        lines = ["Name,Address,Type,Notes,Tags"]
        with self._lock:
            for contact in self._contacts.values():
                for addr in contact.addresses:
                    tags = "|".join(contact.tags)
                    lines.append(f'"{contact.name}","{addr}","{contact.contact_type.value}","{contact.notes}","{tags}"')
        return "\n".join(lines)

    def import_csv(self, csv_data: str) -> int:
        """Import contacts from CSV. Returns count imported."""
        imported = 0
        for line in csv_data.strip().split("\n")[1:]:
            try:
                parts = [p.strip('"') for p in line.split('",')]
                if len(parts) < 2:
                    continue
                name, addr = parts[0], parts[1]
                if not name or not addr:
                    continue
                contact = self._contacts.get(name) or Contact(name=name)
                contact.add_address(addr)
                self.add_contact(contact)
                imported += 1
            except Exception:
                continue
        return imported

    def import_json(self, json_data: str) -> int:
        """Import contacts from JSON."""
        imported = 0
        try:
            data = json.loads(json_data)
            for d in data:
                try:
                    c = Contact.from_dict(d)
                    if self.add_contact(c):
                        imported += 1
                except Exception:
                    continue
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in AddressBook.import_json", exc_info=True)
        return imported

    # ── Persistence ───────────────────────────────────────────────
    def _save(self):
        try:
            data = {
                "contacts": [c.to_dict() for c in self._contacts.values()],
                "used_addrs": list(self._used_addrs),
            }
            self._path.parent.mkdir(parents=True, exist_ok=True)
            self._path.write_text(json.dumps(data, indent=2))
        except Exception:
            _NB_SWALLOW_LOG.warning("swallowed Exception in AddressBook._save", exc_info=True)

    def _load(self):
        try:
            if self._path.exists():
                data = json.loads(self._path.read_text())
                for cd in data.get("contacts", []):
                    c = Contact.from_dict(cd)
                    self._contacts[c.name] = c
                    for addr in c.addresses:
                        self._addr_idx[addr] = c.name
                self._used_addrs = set(data.get("used_addrs", []))
        except Exception:
            _NB_SWALLOW_LOG.warning("swallowed Exception in AddressBook._load", exc_info=True)

    def stats(self) -> dict:
        with self._lock:
            return {
                "total_contacts" : len(self._contacts),
                "total_addresses": len(self._addr_idx),
                "used_addresses" : len(self._used_addrs),
                "favorites"      : len(self.get_favorites()),
                "by_type"        : {
                    ct.value: len(self.get_by_type(ct))
                    for ct in ContactType
                },
            }

# ── BIP47 Payment Code ────────────────────────────────────────────

    # ── Compatibility aliases ────────────────────────────────────
    def add(self, address: str, label: str,
             category: str = "personal", note: str = "",
             tags: list = None) -> bool:
        """Add address with label — creates a Contact internally"""
        # Store in simple index for fast retrieval
        with self._lock:
            if not hasattr(self, '_simple_entries'):
                self._simple_entries = {}
            self._simple_entries[address] = type('_Entry', (), {
                'address'  : address,
                'label'    : label,
                'category' : category,
                'note'     : note,
                'tags'     : tags or [],
                'last_used': 0.0,
                'use_count': 0,
            })()
            # Also add to main address index
            self._addr_idx[address] = label
        # Try to create a proper Contact too
        try:
            c = Contact(name=label or address[:20],
                        addresses=[address], notes=note)
            self._contacts[c.name] = c
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in AddressBook.add", exc_info=True)
        return True

    def get(self, address: str):
        """Get entry for address"""
        if hasattr(self, '_simple_entries') and address in self._simple_entries:
            return self._simple_entries[address]
        # Fallback: look up in contacts
        with self._lock:
            name = self._addr_idx.get(address)
            if name:
                return type('_Entry', (), {
                    'address': address, 'label': name,
                    'category': 'personal', 'note': '',
                    'tags': [], 'last_used': 0.0, 'use_count': 0,
                })()
        return None

    def remove(self, address: str) -> bool:
        """Remove address entry"""
        return self.remove_contact(address)

    def add_tx_note(self, txid: str, note: str,
                     amount_nbl: float = 0.0,
                     direction: str = "received",
                     tags: list = None):
        """Record a transaction note"""
        if not hasattr(self, '_tx_notes'):
            self._tx_notes = {}
        import time as _t
        self._tx_notes[txid] = {
            'txid': txid, 'note': note,
            'amount_nbl': amount_nbl,
            'direction': direction,
            'tags': tags or [],
            'timestamp': _t.time(),
        }

    def get_tx_note(self, txid: str):
        """Get a transaction note"""
        if not hasattr(self, '_tx_notes'):
            return None
        d = self._tx_notes.get(txid)
        if d is None:
            return None
        # Return as object with .note attribute
        return type('TxNote', (), d)()

    def label(self, address: str) -> str:
        """Get label for address"""
        entry = self.get_contact(address)
        if entry:
            return getattr(entry, 'label', getattr(entry, 'name', address[:16]+'...'))
        return address[:16] + '...'



