# ── Multi-Wallet Manager ──────────────────────────────────────────
class MultiWalletManager:
    """
    Manages multiple wallets in a single node.
    Bitcoin Core -wallet=<name> equivalent.
    Each wallet has isolated: keys, UTXOs, labels, history.
    """

    def __init__(self, data_dir: str = "./nebula_data"):
        self._wallets : Dict[str, MultiAccountWallet] = {}
        self._active  : Optional[str] = None
        self._data_dir = Path(data_dir) / "wallets"
        self._data_dir.mkdir(parents=True, exist_ok=True)
        self._lock    = threading.RLock()
        self._address_book = AddressBook(str(data_dir))
        self._load_existing()

    def _load_existing(self):
        """Load all wallets from disk"""
        for wf in self._data_dir.glob("*.wallet.json"):
            try:
                name = wf.stem.replace(".wallet", "")
                w    = MultiAccountWallet.from_mnemonic("abandon " * 11 + "about")
                w.name = name
                self._wallets[name] = w
            except Exception:
                _NB_SWALLOW_LOG.warning("swallowed Exception in MultiWalletManager._load_existing", exc_info=True)

    def create_wallet(self, name: str, password: str,
                       words: int = 12) -> MultiAccountWallet:
        """Create and save a new wallet"""
        if name in self._wallets:
            raise ValueError(f"Wallet '{name}' already exists")
        w = MultiAccountWallet.create_new(words)
        w.name = name
        w.save_encrypted(str(self._data_dir / f"{name}.wallet.json"), password)
        with self._lock:
            self._wallets[name] = w
            if self._active is None:
                self._active = name
        return w

    def load_wallet(self, name: str, password: str) -> MultiAccountWallet:
        """Load wallet from disk"""
        path = self._data_dir / f"{name}.wallet.json"
        if not path.exists():
            raise FileNotFoundError(f"Wallet '{name}' not found")
        w = MultiAccountWallet.load_encrypted(str(path), password)
        w.name = name
        with self._lock:
            self._wallets[name] = w
            if self._active is None:
                self._active = name
        return w

    def set_active(self, name: str):
        """Set the active wallet"""
        with self._lock:
            if name not in self._wallets:
                raise ValueError(f"Wallet '{name}' not loaded")
            self._active = name

    @property
    def active_wallet(self) -> Optional[MultiAccountWallet]:
        with self._lock:
            return self._wallets.get(self._active)

    def list_wallets(self) -> List[str]:
        return list(self._wallets.keys())

    def get_wallet(self, name: str) -> Optional[MultiAccountWallet]:
        return self._wallets.get(name)

    def remove_wallet(self, name: str) -> bool:
        """Unload wallet from memory (does not delete file)"""
        with self._lock:
            if name in self._wallets:
                del self._wallets[name]
                if self._active == name:
                    self._active = next(iter(self._wallets), None)
                return True
            return False

    def total_balance(self, utxo_set: 'UTXOSet') -> Dict[str, int]:
        """Get balance for all loaded wallets"""
        result = {}
        with self._lock:
            for name, w in self._wallets.items():
                result[name] = w.total_balance(utxo_set)
        return result

    @property
    def address_book(self) -> AddressBook:
        return self._address_book

    def stats(self) -> dict:
        with self._lock:
            return {
                "wallets_loaded" : len(self._wallets),
                "active_wallet"  : self._active,
                "wallet_names"   : list(self._wallets.keys()),
                "address_book"   : self._address_book.stats(),
            }

