# ── UTXO Age Analysis ─────────────────────────────────────────────
@dataclass
class UTXOAgeBand:
    """UTXO age band for UTXO age analysis (HODL waves)"""
    label       : str
    min_blocks  : int
    max_blocks  : int
    count       : int   = 0
    value_neb   : int   = 0

    @property
    def value_nbl(self) -> float:
        return self.value_neb / 10**DECIMALS

    def to_dict(self) -> dict:
        return {
            "label"      : self.label,
            "min_blocks" : self.min_blocks,
            "max_blocks" : self.max_blocks,
            "count"      : self.count,
            "value_nbl"  : round(self.value_nbl, 6),
        }

def build_utxo_age_bands() -> List[UTXOAgeBand]:
    """Standard UTXO age bands (similar to Glassnode)"""
    return [
        UTXOAgeBand("< 1 day",       0,    144),
        UTXOAgeBand("1d - 1w",       144,  1008),
        UTXOAgeBand("1w - 1m",       1008, 4320),
        UTXOAgeBand("1m - 3m",       4320, 12960),
        UTXOAgeBand("3m - 6m",       12960,25920),
        UTXOAgeBand("6m - 1y",       25920,52560),
        UTXOAgeBand("1y - 2y",       52560,105120),
        UTXOAgeBand("2y - 3y",       105120,157680),
        UTXOAgeBand("3y - 5y",       157680,262800),
        UTXOAgeBand("5y+",           262800,999999999),
    ]

# ── Coin Distribution ─────────────────────────────────────────────
class CoinDistributionAnalyzer:
    """
    Analyze coin distribution (wealth concentration).
    Computes Gini coefficient, top-N address concentration,
    whale addresses, dust addresses.
    """

    WHALE_THRESHOLD_NBL = 1000   # NBL needed to be a "whale"
    DUST_THRESHOLD_NBL  = 0.001

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def gini_coefficient(self) -> float:
        """
        Gini coefficient of coin distribution.
        0 = perfectly equal, 1 = one person owns everything.
        """
        balances = self._get_all_balances()
        if not balances:
            return 0.0
        n    = len(balances)
        s    = sorted(balances)
        total= sum(s)
        if total == 0:
            return 0.0
        cum  = 0
        for i, b in enumerate(s):
            cum += b
        # Gini = 1 - 2 * (area under Lorenz curve)
        lorenz_area = sum((i+1) * b for i, b in enumerate(s)) / (n * total)
        return round(1 - 2 * lorenz_area / n * n, 4)

    def _get_all_balances(self) -> List[int]:
        """Get all non-zero address balances"""
        addr_balances: Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_balances[addr] += entry.value
        return [v for v in addr_balances.values() if v > 0]

    def top_addresses(self, n: int = 100) -> List[dict]:
        """Top N addresses by balance"""
        addr_balances: Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_balances[addr] += entry.value

        sorted_addrs = sorted(addr_balances.items(),
                              key=lambda x: x[1], reverse=True)[:n]
        total = self.bc.utxo.total_supply()
        result = []
        for i, (addr, bal) in enumerate(sorted_addrs):
            result.append({
                "rank"      : i + 1,
                "address"   : addr,
                "balance_nbl": f"{bal/10**DECIMALS:.9f}",
                "pct_supply": f"{bal/max(1,total)*100:.4f}%",
                "is_foundation": addr == FOUNDATION_ADDRESS,
            })
        return result

    def whale_count(self) -> int:
        """Count addresses holding >= WHALE_THRESHOLD_NBL"""
        threshold = int(self.WHALE_THRESHOLD_NBL * 10**DECIMALS)
        addr_balances: Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_balances[addr] += entry.value
        return sum(1 for b in addr_balances.values() if b >= threshold)

    def dust_count(self) -> int:
        """Count UTXOs below dust threshold"""
        threshold = int(self.DUST_THRESHOLD_NBL * 10**DECIMALS)
        return sum(1 for e in self.bc.utxo._utxos.values()
                   if e.value < threshold)

    def concentration_stats(self) -> dict:
        """Compute supply concentration statistics"""
        balances = sorted(self._get_all_balances(), reverse=True)
        total    = sum(balances)
        if not balances or total == 0:
            return {}

        def top_n_pct(n):
            return sum(balances[:n]) / total * 100

        return {
            "unique_addresses" : len(balances),
            "total_supply_nbl" : f"{total/10**DECIMALS:.9f}",
            "gini_coefficient" : self.gini_coefficient(),
            "top_1_pct"        : f"{top_n_pct(max(1, len(balances)//100)):.2f}%",
            "top_10_pct"       : f"{top_n_pct(max(1, len(balances)//10)):.2f}%",
            "whale_count"      : self.whale_count(),
            "dust_utxos"       : self.dust_count(),
            "foundation_bal"   : f"{self.bc.utxo.balance(FOUNDATION_ADDRESS)/10**DECIMALS:.9f}",
        }

# ── UTXO Age Analysis ─────────────────────────────────────────────
class UTXOAgeAnalyzer:
    """HODL Wave analysis — UTXO age distribution"""

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def analyze(self) -> List[UTXOAgeBand]:
        """Classify all UTXOs by age"""
        current_height = self.bc.height
        bands          = build_utxo_age_bands()

        for entry in self.bc.utxo._utxos.values():
            age_blocks = current_height - entry.height
            for band in bands:
                if band.min_blocks <= age_blocks < band.max_blocks:
                    band.count     += 1
                    band.value_neb += entry.value
                    break

        return bands

    def to_dict(self) -> dict:
        bands   = self.analyze()
        total   = sum(b.value_neb for b in bands)
        result  = []
        for b in bands:
            d = b.to_dict()
            d["pct_supply"] = f"{b.value_neb/max(1,total)*100:.2f}%"
            result.append(d)
        return {
            "current_height" : self.bc.height,
            "utxo_count"     : sum(b.count for b in bands),
            "bands"          : result,
        }

# ── Transaction Volume Tracker ────────────────────────────────────
class TxVolumeTracker:
    """
    Tracks on-chain transaction volume over time.
    Daily, weekly, monthly volume in NBL.
    Distinguishes coinbase vs regular transactions.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def daily_volume(self, days: int = 30) -> List[dict]:
        """Get daily transaction volume for last N days"""
        cutoff_ts = time.time() - days * 86400
        daily: Dict[str, int] = defaultdict(int)
        daily_coinbase: Dict[str, int] = defaultdict(int)
        daily_txcount: Dict[str, int] = defaultdict(int)

        for blk in self.bc._chain:
            if blk.header.timestamp < cutoff_ts:
                continue
            day_key = time.strftime("%Y-%m-%d",
                                     time.gmtime(blk.header.timestamp))
            for tx in blk.transactions:
                if tx.is_coinbase:
                    daily_coinbase[day_key] += tx.total_output()
                else:
                    daily[day_key]     += tx.total_output()
                    daily_txcount[day_key] += 1

        result = []
        all_days = sorted(set(list(daily.keys()) + list(daily_coinbase.keys())))
        for day in all_days:
            result.append({
                "date"          : day,
                "volume_nbl"    : round(daily[day] / 10**DECIMALS, 6),
                "coinbase_nbl"  : round(daily_coinbase[day] / 10**DECIMALS, 6),
                "tx_count"      : daily_txcount[day],
            })
        return result

    def total_volume(self) -> dict:
        """Total on-chain volume since genesis"""
        total_vol  = 0
        total_cb   = 0
        total_txs  = 0
        for blk in self.bc._chain:
            for tx in blk.transactions:
                if tx.is_coinbase:
                    total_cb += tx.total_output()
                else:
                    total_vol += tx.total_output()
                    total_txs += 1
        return {
            "total_volume_nbl"  : f"{total_vol/10**DECIMALS:.9f}",
            "total_coinbase_nbl": f"{total_cb/10**DECIMALS:.9f}",
            "total_regular_txs" : total_txs,
            "avg_tx_value_nbl"  : f"{total_vol/max(1,total_txs)/10**DECIMALS:.9f}",
        }

# ── Block Utilization ─────────────────────────────────────────────
class BlockUtilizationAnalyzer:
    """
    Analyzes block space utilization.
    Average block size, fullness ratio, fee density.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def recent_blocks_stats(self, last_n: int = 144) -> dict:
        """Statistics for last N blocks"""
        blocks = self.bc._chain[-last_n:]
        if not blocks:
            return {}

        sizes       = [b.byte_size() for b in blocks]
        tx_counts   = [len(b.transactions) for b in blocks]
        utilization = [s / MAX_BLOCK_SIZE_BYTES * 100 for s in sizes]

        return {
            "sample_blocks"     : len(blocks),
            "avg_size_bytes"    : round(sum(sizes) / len(sizes), 0),
            "max_size_bytes"    : max(sizes),
            "avg_tx_count"      : round(sum(tx_counts) / len(tx_counts), 2),
            "avg_utilization"   : f"{sum(utilization)/len(utilization):.2f}%",
            "max_block_size"    : MAX_BLOCK_SIZE_BYTES,
        }

    def fee_density(self, last_n: int = 100) -> dict:
        """Average fee density (sat/byte) over last N blocks"""
        total_fees = 0
        total_size = 0
        for blk in self.bc._chain[-last_n:]:
            for tx in blk.transactions[1:]:   # skip coinbase
                total_fees += tx.total_output()
                total_size += tx.byte_size()
        if total_size == 0:
            return {"avg_fee_rate_sat_byte": 0}
        return {
            "avg_fee_rate_sat_byte": round(total_fees / total_size, 2),
            "avg_fee_nbl"          : f"{total_fees/max(1,len(self.bc._chain[-last_n:]))/10**DECIMALS:.9f}",
        }

# ── Supply Emission ───────────────────────────────────────────────
class SupplyEmissionTracker:
    """
    Tracks NBL supply emission over time.
    Compares actual vs theoretical emission.
    Calculates remaining supply and emission schedule.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def theoretical_supply(self, at_height: int) -> int:
        """Theoretical supply if all blocks found on schedule"""
        total = 0
        for era in range(64):
            era_start = era * HALVING_INTERVAL
            era_end   = (era + 1) * HALVING_INTERVAL
            reward    = INITIAL_BLOCK_REWARD >> era
            if reward == 0:
                break
            blocks = max(0, min(at_height, era_end) - era_start)
            total  += reward * blocks
        return total

    def actual_supply(self) -> int:
        """Actual circulating supply from UTXO set"""
        return self.bc.utxo.total_supply()

    def emission_progress(self) -> dict:
        """Current emission progress"""
        actual    = self.actual_supply()
        theo      = self.theoretical_supply(self.bc.height)
        remaining = MAX_SUPPLY - actual

        # Estimate years to full emission
        current_reward = mining_reward(self.bc.height)
        if current_reward > 0:
            blocks_to_emit = remaining // current_reward
            years_to_emit  = blocks_to_emit * TARGET_BLOCK_TIME / 3600 / 24 / 365
        else:
            years_to_emit = 0

        return {
            "actual_supply_nbl"     : f"{actual/10**DECIMALS:.9f}",
            "theoretical_supply_nbl": f"{theo/10**DECIMALS:.9f}",
            "max_supply_nbl"        : f"{MAX_SUPPLY/10**DECIMALS:.0f}",
            "remaining_nbl"         : f"{remaining/10**DECIMALS:.9f}",
            "pct_emitted"           : f"{actual/MAX_SUPPLY*100:.4f}%",
            "pct_remaining"         : f"{remaining/MAX_SUPPLY*100:.4f}%",
            "current_reward_nbl"    : f"{current_reward/10**DECIMALS:.9f}",
            "est_years_to_full"     : round(years_to_emit, 1),
            "foundation_pct"        : f"{FOUNDATION_RATE*100:.0f}%",
            "miner_pct"             : f"{(1-FOUNDATION_RATE)*100:.0f}%",
        }

    def emission_schedule(self) -> List[dict]:
        """Full emission schedule by era"""
        schedule = []
        cumulative = 0
        for era in range(64):
            reward = INITIAL_BLOCK_REWARD >> era
            if reward == 0:
                break
            era_blocks  = HALVING_INTERVAL
            era_total   = reward * era_blocks
            cumulative += era_total
            schedule.append({
                "era"             : era + 1,
                "start_height"    : era * HALVING_INTERVAL,
                "reward_nbl"      : f"{reward/10**DECIMALS:.9f}",
                "era_total_nbl"   : f"{era_total/10**DECIMALS:.9f}",
                "cumulative_nbl"  : f"{cumulative/10**DECIMALS:.9f}",
                "year"            : 2025 + era * 4,
                "complete"        : era * HALVING_INTERVAL < self.bc.height,
            })
        return schedule

# ── On-Chain Metrics ─────────────────────────────────────────────
class OnChainMetrics:
    """
    Key on-chain metrics (Glassnode-style).
    NVT ratio, realized cap, SOPR, active addresses.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def active_addresses(self, blocks: int = 144) -> int:
        """Count unique active addresses in last N blocks"""
        active = set()
        for blk in self.bc._chain[-blocks:]:
            for tx in blk.transactions:
                for out in tx.outputs:
                    if out.address:
                        active.add(out.address)
        return len(active)

    def transaction_count(self, blocks: int = 144) -> int:
        """Total transactions in last N blocks"""
        return sum(len(b.transactions) for b in self.bc._chain[-blocks:])

    def avg_fee_nbl(self, blocks: int = 10) -> float:
        """Average transaction fee in last N blocks"""
        fees   = []
        for blk in self.bc._chain[-blocks:]:
            for tx in blk.transactions[1:]:
                fee = tx.total_output()
                if fee > 0:
                    fees.append(fee)
        return (sum(fees) / len(fees) / 10**DECIMALS) if fees else 0.0

    def utxo_set_growth(self, blocks: int = 144) -> dict:
        """UTXO set growth rate"""
        current = self.bc.utxo.size()
        return {
            "current_size"    : current,
            "estimate_growth" : "not available without history",
        }

    def all_metrics(self) -> dict:
        """Return all key on-chain metrics"""
        return {
            "block_height"    : self.bc.height,
            "active_addresses": self.active_addresses(),
            "tx_count_24h"    : self.transaction_count(144),
            "avg_fee_nbl"     : round(self.avg_fee_nbl(), 9),
            "utxo_count"      : self.bc.utxo.size(),
            "mempool_txs"     : self.bc.mempool.size(),
            "supply_emission" : SupplyEmissionTracker(self.bc).emission_progress(),
        }

# ── Analytics Engine ──────────────────────────────────────────────
class ChainAnalyticsEngine:
    """
    Main analytics engine combining all analyzers.
    Provides comprehensive blockchain analytics in one call.
    Cached results for performance.
    """

    CACHE_TTL = 60   # seconds

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc              = blockchain
        self.coin_dist       = CoinDistributionAnalyzer(blockchain)
        self.utxo_age        = UTXOAgeAnalyzer(blockchain)
        self.tx_volume       = TxVolumeTracker(blockchain)
        self.block_util      = BlockUtilizationAnalyzer(blockchain)
        self.supply_emission = SupplyEmissionTracker(blockchain)
        self.on_chain        = OnChainMetrics(blockchain)
        self._cache          : dict = {}
        self._cache_time     : float = 0
        self._lock           = threading.RLock()

    def full_report(self, use_cache: bool = True) -> dict:
        """Generate full analytics report"""
        with self._lock:
            if (use_cache and self._cache and
                    time.time() - self._cache_time < self.CACHE_TTL):
                return self._cache

            report = {
                "timestamp"          : time.time(),
                "block_height"       : self.bc.height,
                "coin_distribution"  : self.coin_dist.concentration_stats(),
                "utxo_age_analysis"  : self.utxo_age.to_dict(),
                "volume"             : self.tx_volume.total_volume(),
                "block_utilization"  : self.block_util.recent_blocks_stats(),
                "fee_density"        : self.block_util.fee_density(),
                "supply_emission"    : self.supply_emission.emission_progress(),
                "on_chain_metrics"   : self.on_chain.all_metrics(),
            }
            self._cache      = report
            self._cache_time = time.time()
            return report

    def top_holders(self, n: int = 20) -> List[dict]:
        """Top N NBL holders"""
        return self.coin_dist.top_addresses(n)

    def emission_schedule(self) -> List[dict]:
        """Full emission schedule"""
        return self.supply_emission.emission_schedule()

    def daily_chart(self, days: int = 30) -> List[dict]:
        """Daily volume chart data"""
        return self.tx_volume.daily_volume(days)

