# ── Network Topology ─────────────────────────────────────────────
class NetworkTopologyAnalyzer:
    """
    Analyzes the local view of the P2P network topology.
    Tracks peer graph, identifies well-connected peers,
    estimates network-wide health.
    """

    def __init__(self):
        self._peers      : Dict[str, dict] = {}
        self._edges      : Set[Tuple[str,str]] = set()
        self._lock       = threading.RLock()

    def add_peer(self, peer_id: str, info: dict):
        with self._lock:
            self._peers[peer_id] = {
                "id"           : peer_id,
                "height"       : info.get("height", 0),
                "services"     : info.get("services", 0),
                "connected_at" : time.time(),
                "latency_ms"   : info.get("latency_ms", 0),
                "subversion"   : info.get("subversion", ""),
            }

    def remove_peer(self, peer_id: str):
        with self._lock:
            self._peers.pop(peer_id, None)
            self._edges = {(a,b) for a,b in self._edges
                           if a != peer_id and b != peer_id}

    def record_introduction(self, peer_a: str, peer_b: str):
        """Record that peer_a knows peer_b (addr message)"""
        with self._lock:
            edge = tuple(sorted([peer_a, peer_b]))
            self._edges.add(edge)

    def best_height(self) -> int:
        with self._lock:
            if not self._peers:
                return 0
            return max(p["height"] for p in self._peers.values())

    def lowest_latency_peer(self) -> Optional[str]:
        with self._lock:
            if not self._peers:
                return None
            return min(self._peers.items(),
                       key=lambda x: x[1].get("latency_ms", 9999))[0]

    def topology_stats(self) -> dict:
        with self._lock:
            if not self._peers:
                return {"peer_count": 0}
            latencies = [p["latency_ms"] for p in self._peers.values()
                         if p["latency_ms"] > 0]
            heights   = [p["height"] for p in self._peers.values()]
            return {
                "peer_count"   : len(self._peers),
                "avg_latency"  : round(sum(latencies)/max(1,len(latencies)), 1),
                "min_latency"  : min(latencies) if latencies else 0,
                "max_latency"  : max(latencies) if latencies else 0,
                "best_height"  : max(heights) if heights else 0,
                "known_edges"  : len(self._edges),
            }

