# ================================================================
# Dynamic fee market, package relay, RBF policies,
# fee bumping strategies, CPFP analysis.
# ================================================================

class FeeMarket:
    """
    Dynamic fee market for NEBULA.
    Tracks fee rate distribution, computes percentiles,
    provides recommendations for different confirmation targets.
    """

    BUCKETS = [1, 2, 3, 5, 8, 10, 15, 20, 30, 50,
               100, 200, 500, 1000, 2000, 5000, 10000]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc          = blockchain
        self._confirmed  : List[Tuple[int, float]] = []  # (block, fee_rate)
        self._lock       = threading.RLock()

    def record_block_fees(self, block: 'Block'):
        """Record fee rates from confirmed transactions"""
        with self._lock:
            for tx in block.transactions[1:]:
                fee = tx.fee(self.bc.utxo)
                size = tx.byte_size()
                if size > 0:
                    rate = fee / size
                    self._confirmed.append((block.height, rate))
            # Keep last 2016 blocks (one difficulty window)
            if len(self._confirmed) > 2016 * 100:
                self._confirmed = self._confirmed[-2016*50:]

    def percentile(self, pct: float) -> float:
        """Get fee rate at given percentile (0-100)"""
        with self._lock:
            if not self._confirmed:
                return MIN_TX_FEE / 100
            rates = sorted(r for _, r in self._confirmed)
            idx   = int(len(rates) * pct / 100)
            return rates[min(idx, len(rates)-1)]

    def smart_recommend(self) -> dict:
        """Smart fee recommendations"""
        with self._lock:
            return {
                "next_block"   : max(1, round(self.percentile(90))),
                "3_blocks"     : max(1, round(self.percentile(70))),
                "6_blocks"     : max(1, round(self.percentile(50))),
                "eco"          : max(1, round(self.percentile(30))),
                "minimum"      : MIN_TX_FEE // 100,
                "unit"         : "neb_per_byte",
            }

    def histogram(self) -> List[dict]:
        """Fee rate distribution histogram"""
        with self._lock:
            if not self._confirmed:
                return []
            counts = {b: 0 for b in self.BUCKETS}
            for _, rate in self._confirmed:
                for bucket in reversed(self.BUCKETS):
                    if rate >= bucket:
                        counts[bucket] += 1
                        break
            total = len(self._confirmed)
            return [{"fee_rate": b, "count": c,
                     "pct": f"{c/max(1,total)*100:.1f}%"}
                    for b, c in counts.items() if c > 0]

