class GovernanceSystem:
    """
    NEBULA on-chain governance.
    Token holders vote on: fee changes, parameter updates,
    foundation wallet changes, soft fork activations.
    Foundation address has veto power on foundation changes.
    """

    VOTING_PERIOD_BLOCKS  = 2016   # 2 weeks
    QUORUM_THRESHOLD      = 100    # minimum votes
    APPROVAL_THRESHOLD    = 67.0   # % yes needed

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc          = blockchain
        self._proposals  : Dict[str, GovernanceProposal] = {}
        self._votes      : Dict[str, Dict[str, str]] = {}  # proposal -> {address: vote}
        self._lock       = threading.RLock()

    def create_proposal(self, title: str, description: str,
                         proposer: str, parameter: str,
                         new_value: str) -> GovernanceProposal:
        """Create a new governance proposal"""
        proposal_id = hashlib.sha256(
            f"{title}{proposer}{time.time()}".encode()
        ).hexdigest()[:16]

        p = GovernanceProposalC(
            proposal_id  = proposal_id,
            title        = title,
            description  = description,
            proposer     = proposer,
            parameter    = parameter,
            new_value    = new_value,
            start_height = self.bc.height,
            end_height   = self.bc.height + self.VOTING_PERIOD_BLOCKS,
        )
        with self._lock:
            self._proposals[proposal_id] = p
            self._votes[proposal_id]     = {}
        return p

    def vote(self, proposal_id: str, voter: str,
              vote: str, stake: int = 1) -> Tuple[bool, str]:
        """
        Cast a vote on a proposal.
        vote: "yes" | "no" | "abstain"
        stake: voter's NBL balance (weighted voting)
        """
        with self._lock:
            p = self._proposals.get(proposal_id)
            if not p:
                return False, "Proposal not found"
            if p.is_expired(self.bc.height):
                return False, "Voting period ended"
            if p.status != "active":
                return False, f"Proposal is {p.status}"

            # Check if already voted
            if voter in self._votes[proposal_id]:
                return False, "Already voted"

            # Verify voter has stake
            bal = self.bc.utxo.balance(voter)
            if bal == 0:
                return False, "No stake — cannot vote"

            self._votes[proposal_id][voter] = vote
            vote_weight = max(1, bal // (10 ** DECIMALS))  # 1 vote per NBL

            if vote == "yes":
                p.yes_votes += vote_weight
            elif vote == "no":
                p.no_votes += vote_weight
            else:
                p.abstain += vote_weight

            return True, f"Vote recorded: {vote} with weight {vote_weight}"

    def finalize(self, proposal_id: str) -> Tuple[bool, str]:
        """Finalize a proposal after voting period"""
        with self._lock:
            p = self._proposals.get(proposal_id)
            if not p:
                return False, "Not found"
            if not p.is_expired(self.bc.height):
                return False, "Still voting"

            if p.is_passed(self.APPROVAL_THRESHOLD):
                p.status = "passed"
                return True, f"PASSED — {p.approval_pct:.1f}% approval"
            else:
                p.status = "failed"
                return False, f"FAILED — {p.approval_pct:.1f}% approval"

    def list_proposals(self, status: str = None) -> List[dict]:
        with self._lock:
            proposals = list(self._proposals.values())
            if status:
                proposals = [p for p in proposals if p.status == status]
            return [p.to_dict() for p in proposals]

    def active_proposals(self) -> List[GovernanceProposal]:
        with self._lock:
            return [p for p in self._proposals.values()
                    if p.status == "active" and not p.is_expired(self.bc.height)]

    def stats(self) -> dict:
        with self._lock:
            return {
                "total_proposals" : len(self._proposals),
                "active"          : sum(1 for p in self._proposals.values() if p.status == "active"),
                "passed"          : sum(1 for p in self._proposals.values() if p.status == "passed"),
                "failed"          : sum(1 for p in self._proposals.values() if p.status == "failed"),
            }

