class NEBULASystem:
    """
    Master coordinator for all NEBULA modules.
    Single entry point to access every feature.
    """

    def __init__(self, data_dir: str = "./nebula_data",
                 port: int = DEFAULT_PORT):
        self.data_dir    = data_dir

        # Core
        loaded           = NEBULABlockchain.load(data_dir)
        self.blockchain  = loaded if loaded else NEBULABlockchain()

        # Advanced components
        self.adv_node    = AdvancedNEBULANode(data_dir=data_dir, port=port)
        self.blockchain  = self.adv_node.bc
        self.adv_mempool = AdvancedMempool(self.blockchain.utxo)
        self.chain_db    = None   # ChainDatabase(data_dir)  — optional heavy storage
        self.analytics   = ChainAnalyticsEngine(self.blockchain)
        self.governance  = GovernanceSystem(self.blockchain)
        self.fee_market  = FeeMarket(self.blockchain)
        self.multi_wallet= MultiWalletManager(data_dir)
        self.jsonrpc     = NEBULAJSONRPCServerLegacy(self.blockchain, port=8332)
        self.explorer    = NEBULAExplorer(self.blockchain, port=EXPLORER_DEFAULT_PORT)
        self.mining_dash = MiningDashboard(self.blockchain)
        self.privacy_mgr = PrivacyConnectionManager(PrivacyLevel.MIXED)
        self.alert_mgr   = AlertManager()
        self.softforks   = SoftForkManager()
        self.backup      = AutoBackup(self.blockchain, data_dir + "/backups")
        self.telemetry   = NodeTelemetry()
        self.log_mgr     = NEBULALogManager(data_dir + "/logs")
        self.health_mon  = NodeHealthMonitor(self.blockchain, data_dir)
        self.ibd         = IBDCoordinator(self.blockchain)
        self.orphan_pool = OrphanPool()
        self.contract_registry = AdvancedContractRegistry()
        self.pool_manager= None   # MiningPoolManager — start manually

    def start(self, with_mining: bool = False):
        """Start all node services"""
        self.adv_node.start()
        self.health_mon.start()
        self.backup.start()
        self.jsonrpc.start()
        self.explorer.start()
        self.mining_dash.start()
        self.ibd.start()
        self.telemetry.increment("system_starts")

        if with_mining:
            wallet = NEBULAWallet.create_new()
            miner  = NEBULAMiner(self.blockchain, wallet.first_address)
            miner.start()
            self.mining_dash.miner = miner
            self.health_mon.attach_miner(miner)

        print(f"\n{'='*60}")
        print(f"  🌌 NEBULA Blockchain System — All 32 Modules Active")
        print(f"  Height     : {self.blockchain.height}")
        print(f"  RPC        : http://127.0.0.1:8332")
        print(f"  Explorer   : http://0.0.0.0:{EXPLORER_DEFAULT_PORT}")
        print(f"  P2P        : {self.adv_node.port}")
        print(f"  Chain ID   : {CHAIN_ID}")
        print(f"{'='*60}\n")

    def stop(self):
        """Gracefully stop all services"""
        self.adv_node.stop()
        self.health_mon.stop()
        self.backup.stop()
        self.jsonrpc.stop()
        self.explorer.stop()
        self.mining_dash.stop()
        self.ibd.stop()
        self.blockchain.save(self.data_dir)
        print("✅ NEBULA System stopped — all data saved")

    def full_status(self) -> dict:
        """Complete system status"""
        return {
            "blockchain"   : self.blockchain.chain_info(),
            "health"       : self.health_mon.current_health(),
            "analytics"    : {
                "top_holders": self.analytics.top_holders(5),
                "supply"     : self.analytics.supply_emission.emission_progress(),
            },
            "governance"   : self.governance.stats(),
            "fee_market"   : self.fee_market.smart_recommend(),
            "wallets"      : self.multi_wallet.stats(),
            "rpc_methods"  : self.jsonrpc.registry.method_count(),
            "softforks"    : self.softforks.get_all_states(),
            "alerts"       : len(self.alert_mgr.get_active()),
            "orphans"      : self.orphan_pool.size(),
            "modules"      : 32,
        }

