# ── Descriptor Constants ──────────────────────────────────────────
DESCRIPTOR_CHECKSUM_CHARS = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
DESCRIPTOR_INPUT_CHARSET  = "0123456789()[],'/\\!@#$%^&*ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz"

# ── Descriptor Types ──────────────────────────────────────────────
# [v10.19] dead class DescriptorType removed from host - no live copy exists; original kept in nebula_removed_dead_classes.py

# ── Descriptor Checksum ───────────────────────────────────────────
class DescriptorChecksum:
    """BIP380 descriptor checksum computation"""

    @staticmethod
    def _poly_mod(c: int, val: int) -> int:
        c0 = c >> 35
        c  = ((c & 0x7ffffffff) << 5) ^ val
        if c0 & 1:  c ^= 0xf5dee51989
        if c0 & 2:  c ^= 0xa9fdca3312
        if c0 & 4:  c ^= 0x1bab10e32d
        if c0 & 8:  c ^= 0x3706b1677a
        if c0 & 16: c ^= 0x644d626ffd
        return c

    @classmethod
    def compute(cls, desc: str) -> str:
        """Compute 8-character checksum for descriptor string"""
        INPUT_CHARSET = "0123456789()[],'/*abcdefgh@:$%{}IJKLMNOPQRSTUVWXYZ&+-.;<=>?!^_|~ijklmnopqrstuvwxyz"
        CHECKSUM_CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
        c  = 1
        cls_val = 0
        for ch in desc:
            pos = INPUT_CHARSET.find(ch)
            if pos < 0:
                return ""
            c = cls._poly_mod(c, pos & 31)
            cls_val = (cls_val << 3) | (pos >> 5)
        for ch_val in [cls_val, 0, 0, 0, 0, 0, 0, 0]:
            if ch_val:
                c = cls._poly_mod(c, ch_val)
        for _ in range(8):
            c = cls._poly_mod(c, 0)
        c ^= 1
        checksum = ""
        for i in range(7, -1, -1):
            checksum += CHECKSUM_CHARSET[(c >> (5*i)) & 31]
        return checksum

    @classmethod
    def add_checksum(cls, desc: str) -> str:
        """Add checksum to descriptor"""
        if '#' in desc:
            return desc
        chk = cls.compute(desc.split('#')[0])
        return f"{desc}#{chk}"

    @classmethod
    def verify(cls, desc: str) -> bool:
        """Verify descriptor checksum"""
        if '#' not in desc:
            return False
        parts = desc.split('#')
        if len(parts) != 2 or len(parts[1]) != 8:
            return False
        return cls.compute(parts[0]) == parts[1]

