STALL_TIMEOUT_SECS      = 30      # block download stall timeout
MAX_PARALLEL_DOWNLOADS  = 8       # concurrent block downloads
SYNC_CHECKPOINT_INTERVAL= 1000    # validate checkpoint every N blocks

