# ── Header Cache ─────────────────────────────────────────────────
class HeaderCache:
    """
    In-memory header cache for IBD.
    Stores headers before full block validation.
    Used in headers-first sync (more efficient than full-block-first).
    """

    def __init__(self, max_size: int = 50_000):
        self._headers : Dict[str, 'BlockHeader'] = {}
        self._by_height: Dict[int, str] = {}   # height → hash
        self._max_size = max_size
        self._lock     = threading.RLock()

    def add(self, header: 'BlockHeader') -> bool:
        """Add header to cache"""
        with self._lock:
            if len(self._headers) >= self._max_size:
                return False
            h = header.hash()
            self._headers[h] = header
            self._by_height[header.height] = h
            return True

    def get(self, block_hash: str) -> Optional['BlockHeader']:
        return self._headers.get(block_hash)

    def get_at_height(self, height: int) -> Optional['BlockHeader']:
        h = self._by_height.get(height)
        return self._headers.get(h) if h else None

    def has(self, block_hash: str) -> bool:
        return block_hash in self._headers

    def tip(self) -> Optional['BlockHeader']:
        if not self._by_height:
            return None
        max_h = max(self._by_height.keys())
        return self.get_at_height(max_h)

    def validate_chain(self, from_height: int = 0) -> Tuple[bool, str]:
        """Validate header chain linkage"""
        with self._lock:
            prev_hash = None
            for h in range(from_height, max(self._by_height.keys(), default=-1) + 1):
                hdr = self.get_at_height(h)
                if hdr is None:
                    return False, f"Missing header at height {h}"
                if prev_hash and hdr.prev_hash != prev_hash:
                    return False, f"Chain break at height {h}"
                if not hdr.meets_target():
                    return False, f"Invalid PoW at height {h}"
                prev_hash = hdr.hash()
            return True, "OK"

    def size(self) -> int:
        return len(self._headers)

    def clear(self):
        with self._lock:
            self._headers.clear()
            self._by_height.clear()

# ── Orphan Block Manager ──────────────────────────────────────────
class OrphanManager:
    """
    Manages orphan blocks: blocks received before their parents.
    Resolves orphans when parent arrives (chain stitching).
    Expires old orphans to prevent memory exhaustion.
    """

    def __init__(self):
        self._orphans      : Dict[str, 'Block'] = {}
        self._by_prev      : Dict[str, Set[str]] = {}   # prev_hash → {orphan_hashes}  # FIX set (not list) so .discard() works
        self._times        : Dict[str, float] = {}
        self._lock         = threading.RLock()

    def add(self, block: 'Block') -> bool:
        """Add orphan block"""
        with self._lock:
            if len(self._orphans) >= MAX_ORPHAN_BLOCKS:
                self._expire_oldest()
            h = block.hash
            if h in self._orphans:
                return False
            self._orphans[h]    = block
            self._times[h]      = time.time()
            prev = block.header.prev_hash
            self._by_prev.setdefault(prev, set()).add(h)  # FIX set().add() instead of [].append()
            return True

    def has(self, block_hash: str) -> bool:
        return block_hash in self._orphans

    def resolve(self, parent_hash: str) -> List['Block']:
        """
        Get orphans whose parent just arrived.
        Returns list of orphans to process (may be recursive).
        """
        with self._lock:
            result   = []
            to_check = [parent_hash]
            while to_check:
                ph       = to_check.pop()
                children = self._by_prev.pop(ph, set())  # FIX set default
                for ch in children:
                    blk = self._orphans.pop(ch, None)
                    if blk:
                        self._times.pop(ch, None)
                        result.append(blk)
                        to_check.append(ch)
            return result

    def _expire_oldest(self):
        """Remove oldest orphan to make room"""
        if not self._times:
            return
        oldest = min(self._times, key=self._times.get)
        blk    = self._orphans.pop(oldest, None)
        self._times.pop(oldest, None)
        if blk:
            prev = blk.header.prev_hash
            self._by_prev.get(prev, []).discard(oldest)
            if not self._by_prev.get(prev):
                self._by_prev.pop(prev, None)

    def expire_old(self):
        """Remove orphans older than MAX_ORPHAN_AGE_SECS"""
        cutoff = time.time() - MAX_ORPHAN_AGE_SECS
        with self._lock:
            old = [h for h, t in self._times.items() if t < cutoff]
            for h in old:
                blk = self._orphans.pop(h, None)
                self._times.pop(h, None)
                if blk:
                    self._by_prev.get(blk.header.prev_hash, []).discard(h)

    def size(self) -> int:
        return len(self._orphans)

# ── Reorg Handler ─────────────────────────────────────────────────
class ReorgHandler:
    """
    Handles blockchain reorganizations (chain reorgs).
    When a longer chain is discovered, disconnects current tip
    and reconnects blocks from the new chain.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def find_fork(self, new_headers: List['BlockHeader']) -> Optional[int]:
        """
        Find the fork point (last common block) between current chain
        and the new (potentially longer) chain.
        Returns fork height or None if no common ancestor found.
        """
        for i, hdr in enumerate(reversed(new_headers)):
            if hdr.height <= self.bc.height:
                existing = self.bc.get_block(hdr.height)
                if existing and existing.hash == hdr.hash():
                    return hdr.height
        return None

    def should_reorg(self, new_tip_work: int) -> bool:
        """
        Decide whether to reorg to the new chain.
        Always prefer chain with more cumulative PoW work.
        FIX use sum(2^256 / target_i) instead of height x initial_target
        """
        # FIX correct cumulative work = sum(2^256 / target) per block
        current_work = sum(
            (2**256) // max(1, bits_to_target(blk.header.bits))
            for blk in self.bc._chain
        )
        return new_tip_work > current_work

    def get_reorg_depth(self, fork_height: int) -> int:
        """How many blocks need to be disconnected"""
        return max(0, self.bc.height - fork_height)

    def stats(self) -> dict:
        return {
            "current_height": self.bc.height,
            "current_tip"   : self.bc.tip.hash[:20] + "...",
        }

# ── Download Manager ──────────────────────────────────────────────
@dataclass
class DownloadRequest:
    """Pending block download request"""
    block_hash : str
    height     : int
    peer_id    : str
    requested_at: float = field(default_factory=time.time)
    attempts   : int = 0

    def is_stalled(self) -> bool:
        return time.time() - self.requested_at > STALL_TIMEOUT_SECS

class DownloadManager:
    """
    Parallel block download manager.
    Assigns block download requests to peers.
    Handles retries, stalls, and peer scoring.
    """

    def __init__(self):
        self._in_flight  : Dict[str, DownloadRequest] = {}
        self._pending    : List[str] = []   # hashes to download
        self._lock       = threading.RLock()
        self._peer_scores: Dict[str, float] = {}

    def add_pending(self, block_hashes: List[str], heights: List[int]):
        """Queue block hashes for download"""
        with self._lock:
            for h, height in zip(block_hashes, heights):
                if h not in self._in_flight:
                    self._pending.append(h)

    def assign_to_peer(self, peer_id: str,
                        max_count: int = MAX_PARALLEL_DOWNLOADS) -> List[str]:
        """Assign pending downloads to a peer"""
        with self._lock:
            assigned = []
            in_flight_for_peer = sum(1 for r in self._in_flight.values()
                                     if r.peer_id == peer_id)
            available = max_count - in_flight_for_peer
            for _ in range(min(available, len(self._pending))):
                if not self._pending:
                    break
                h = self._pending.pop(0)
                req = DownloadRequest(block_hash=h, height=0, peer_id=peer_id)
                self._in_flight[h] = req
                assigned.append(h)
            return assigned

    def complete(self, block_hash: str, success: bool, peer_id: str = ""):
        """Mark download as complete"""
        with self._lock:
            req = self._in_flight.pop(block_hash, None)
            if req and success:
                self._peer_scores[peer_id] = (
                    self._peer_scores.get(peer_id, 1.0) * 1.01)
            elif req and not success:
                self._peer_scores[peer_id] = (
                    self._peer_scores.get(peer_id, 1.0) * 0.9)
                # Re-queue for retry
                if req.attempts < 3:
                    req.attempts += 1
                    req.requested_at = time.time()
                    self._in_flight[block_hash] = req

    def check_stalls(self) -> List[str]:
        """Find stalled downloads and re-queue them"""
        with self._lock:
            stalled = []
            for h, req in list(self._in_flight.items()):
                if req.is_stalled():
                    del self._in_flight[h]
                    self._pending.insert(0, h)   # priority re-queue
                    stalled.append(h)
            return stalled

    def pending_count(self) -> int:
        return len(self._pending)

    def in_flight_count(self) -> int:
        return len(self._in_flight)

    def stats(self) -> dict:
        return {
            "pending"   : self.pending_count(),
            "in_flight" : self.in_flight_count(),
            "peers"     : len(self._peer_scores),
        }

# ── IBD Manager ──────────────────────────────────────────────────
class IBDManager:
    """
    Initial Block Download Manager.
    Coordinates full blockchain sync from peers.
    Uses headers-first approach (more efficient):
      1. Sync all headers first (fast, small data)
      2. Download and validate full blocks
      3. Handle reorgs and orphans
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 on_progress: Callable = None):
        self.bc          = blockchain
        self.on_progress = on_progress
        self.state       = SyncState.IDLE
        self.header_cache = HeaderCache()
        self.orphans     = OrphanManager()
        self.reorg       = ReorgHandler(blockchain)
        self.downloads   = DownloadManager()
        self._lock       = threading.RLock()
        self._best_height_seen  = blockchain.height
        self._sync_start        = 0.0
        self._blocks_downloaded = 0
        self._headers_synced    = 0

    def start_sync(self, peer_heights: Dict[str, int]):
        """Begin IBD with known peer heights"""
        best_peer_height = max(peer_heights.values(), default=0)
        if best_peer_height <= self.bc.height:
            self.state = SyncState.SYNCED
            return

        self._best_height_seen = best_peer_height
        self._sync_start       = time.time()
        self.state             = SyncState.HEADERS_SYNC
        print(f"📥 IBD: syncing {self.bc.height} → {best_peer_height} "
              f"({best_peer_height - self.bc.height} blocks)")

    def process_headers(self, headers: List['BlockHeader'],
                         peer_id: str) -> Tuple[bool, str]:
        """
        Process a batch of headers from a peer.
        Validates PoW, chain linkage, checkpoints.
        Returns (success, reason).
        """
        if not headers:
            return False, "Empty headers"

        with self._lock:
            prev_hash = (self.bc.tip.hash if not self.header_cache.tip()
                         else self.header_cache.tip().hash())

            added = 0
            for hdr in headers:
                # PoW check
                if not hdr.meets_target():
                    return False, f"Invalid PoW at height {hdr.height}"

                # Chain linkage
                if hdr.prev_hash != prev_hash:
                    return False, f"Chain break at height {hdr.height}"

                # Checkpoint validation
                if hdr.height in NEBULA_CHECKPOINTS:
                    expected = NEBULA_CHECKPOINTS[hdr.height]
                    if hdr.hash() != expected:
                        return False, f"Checkpoint mismatch at {hdr.height}"

                self.header_cache.add(hdr)
                prev_hash = hdr.hash()
                added    += 1

            self._headers_synced += added

            # Queue blocks for download
            block_hashes  = [h.hash() for h in headers]
            block_heights = [h.height for h in headers]
            self.downloads.add_pending(block_hashes, block_heights)

            # Switch to block sync if we caught up on headers
            if self.header_cache.tip().height >= self._best_height_seen:
                self.state = SyncState.BLOCK_SYNC

            if self.on_progress:
                pct = self._headers_synced / max(1, self._best_height_seen) * 100
                self.on_progress("headers", self._headers_synced,
                                 self._best_height_seen, pct)

            return True, f"Added {added} headers"

    def process_block(self, block: 'Block',
                       peer_id: str) -> Tuple[bool, str]:
        """
        Process a downloaded block.
        Handles: orphans, reorgs, UTXO update, mempool cleanup.
        """
        with self._lock:
            # Check if parent is known
            if (block.header.prev_hash != self.bc.tip.hash and
                    not self.bc.get_block_by_hash(block.header.prev_hash)):
                # Orphan
                self.orphans.add(block)
                return True, "Stored as orphan"

            # Add to chain
            ok, msg = self.bc.add_block(block)
            self.downloads.complete(block.hash, ok, peer_id)

            if ok:
                self._blocks_downloaded += 1
                # Resolve any orphans waiting for this block
                orphan_blocks = self.orphans.resolve(block.hash)
                for orphan in orphan_blocks:
                    self.bc.add_block(orphan)
                    self._blocks_downloaded += 1

                # Check if sync complete
                if self.bc.height >= self._best_height_seen:
                    self.state = SyncState.SYNCED
                    elapsed    = time.time() - self._sync_start
                    if elapsed > 0:
                        rate = self._blocks_downloaded / elapsed
                        print(f"✅ IBD complete: height {self.bc.height} "
                              f"({rate:.1f} blocks/sec)")

                if self.on_progress:
                    pct = self.bc.height / max(1, self._best_height_seen) * 100
                    self.on_progress("blocks", self.bc.height,
                                     self._best_height_seen, pct)

            return ok, msg

    def build_locator(self) -> List[str]:
        """
        Build block locator for getblocks/getheaders message.
        Exponential step-back (same as Bitcoin Core).
        """
        return self.bc.get_locator()

    def is_synced(self) -> bool:
        return (self.state == SyncState.SYNCED or
                self.bc.height >= self._best_height_seen)

    def sync_progress(self) -> float:
        """Returns sync progress 0.0–1.0"""
        if self._best_height_seen == 0:
            return 1.0
        return min(1.0, self.bc.height / self._best_height_seen)

    def stats(self) -> dict:
        elapsed = time.time() - self._sync_start if self._sync_start else 0
        return {
            "state"            : self.state.value,
            "current_height"   : self.bc.height,
            "best_seen_height" : self._best_height_seen,
            "headers_cached"   : self.header_cache.size(),
            "orphan_count"     : self.orphans.size(),
            "blocks_downloaded": self._blocks_downloaded,
            "headers_synced"   : self._headers_synced,
            "sync_progress_pct": f"{self.sync_progress()*100:.1f}%",
            "elapsed_secs"     : round(elapsed, 1),
            "blocks_per_sec"   : round(self._blocks_downloaded / max(1, elapsed), 2),
            "downloads"        : self.downloads.stats(),
        }

# ── Checkpoint Validator ──────────────────────────────────────────
class CheckpointValidator:
    """
    Hard-coded checkpoint validation.
    Prevents historical chain rewriting attacks.
    Checkpoints are conservative — only a few key heights.
    """

    def __init__(self, checkpoints: Dict[int, str] = None):
        self._checkpoints = checkpoints or NEBULA_CHECKPOINTS

    def validate(self, block: 'Block') -> Tuple[bool, str]:
        """Validate block against checkpoint if applicable"""
        height = block.height
        if height in self._checkpoints:
            expected = self._checkpoints[height]
            if block.hash != expected:
                return False, (f"Checkpoint validation failed at height {height}: "
                               f"got {block.hash[:16]}, expected {expected[:16]}")
        return True, "OK"

    def is_before_checkpoint(self, height: int) -> bool:
        """True if height is before the latest checkpoint"""
        if not self._checkpoints:
            return False
        return height <= max(self._checkpoints.keys())

    def latest_checkpoint(self) -> Optional[Tuple[int, str]]:
        if not self._checkpoints:
            return None
        h = max(self._checkpoints.keys())
        return h, self._checkpoints[h]

    def add_checkpoint(self, height: int, block_hash: str):
        """Add a new checkpoint"""
        self._checkpoints[height] = block_hash

    def to_dict(self) -> dict:
        return {
            "checkpoints"     : len(self._checkpoints),
            "latest_height"   : max(self._checkpoints.keys(), default=0),
            "latest_hash"     : (self._checkpoints.get(
                                  max(self._checkpoints.keys(), default=0), "")[:20] + "..."
                                  if self._checkpoints else ""),
        }

