# ── Extended Key (BIP32) ──────────────────────────────────────────
@dataclass
class ExtendedKey:
    """BIP32 extended key with full derivation info"""
    key         : bytes          # 32 bytes private or 33 bytes public
    chain_code  : bytes          # 32 bytes
    depth       : int = 0
    parent_fp   : bytes = b'\x00\x00\x00\x00'
    child_index : int = 0
    is_private  : bool = True
    network     : str = "mainnet"

    @property
    def is_hardened(self) -> bool:
        return self.child_index >= HARDENED_OFFSET

    @property
    def fingerprint(self) -> bytes:
        """HASH160 of public key, first 4 bytes"""
        pub = self.public_key_bytes
        h   = hashlib.new('ripemd160', hashlib.sha256(pub).digest()).digest()
        return h[:4]

    @property
    def public_key_bytes(self) -> bytes:
        if not self.is_private:
            return self.key
        sk = int.from_bytes(self.key, 'big')
        P  = Schnorr._point_mul(sk, Schnorr._G())
        x, y = P
        prefix = b'\x02' if y % 2 == 0 else b'\x03'
        return prefix + x.to_bytes(32, 'big')

    @property
    def private_key_int(self) -> Optional[int]:
        if not self.is_private: return None
        return int.from_bytes(self.key, 'big')

    @property
    def wif(self) -> str:
        if not self.is_private:
            raise ValueError("Public key has no WIF")
        raw = bytes([0x80]) + self.key + b'\x01'
        return base58check_encode(self.key + b'\x01', 0x80)

    @property
    def address(self) -> str:
        """Default P2PKH address"""
        pub   = self.public_key_bytes
        h160  = hashlib.new('ripemd160', hashlib.sha256(pub).digest()).digest()
        return base58check_encode(h160, PUBKEY_ADDRESS_VERSION)

    def derive_child(self, index: int) -> 'ExtendedKey':
        """Derive child key at given index"""
        hardened = index >= HARDENED_OFFSET

        if hardened and not self.is_private:
            raise ValueError("Cannot derive hardened child from public key")

        if hardened:
            data = b'\x00' + self.key + struct.pack('>I', index)
        else:
            data = self.public_key_bytes + struct.pack('>I', index)

        I = hmac.new(self.chain_code, data, hashlib.sha512).digest()
        IL, IR = I[:32], I[32:]

        il_int = int.from_bytes(IL, 'big')
        N      = Schnorr.N

        if il_int >= N:
            raise ValueError("Derived key invalid — try next index")

        if self.is_private:
            ki = (il_int + int.from_bytes(self.key, 'big')) % N
            if ki == 0:
                raise ValueError("Derived key is zero — try next index")
            child_key = ki.to_bytes(32, 'big')
        else:
            # Public child derivation
            # P_child = point(IL) + P_parent
            P_il     = Schnorr._point_mul(il_int, Schnorr._G())
            x        = int.from_bytes(self.key[1:], 'big')
            P_       = Schnorr.P
            ys       = (pow(x,3,P_)+7)%P_
            y        = pow(ys,(P_+1)//4,P_)
            if (y%2==0) != (self.key[0]==0x02): y=P_-y
            P_parent = (x, y)
            P_child  = Schnorr._point_add(P_il, P_parent)
            if P_child is None:
                raise ValueError("Derived public key is infinity")
            cx, cy = P_child
            prefix  = b'\x02' if cy%2==0 else b'\x03'
            child_key = prefix + cx.to_bytes(32, 'big')

        return ExtendedKey(
            key         = child_key,
            chain_code  = IR,
            depth       = self.depth + 1,
            parent_fp   = self.fingerprint,
            child_index = index,
            is_private  = self.is_private,
            network     = self.network,
        )

    def derive_path(self, path: str) -> 'ExtendedKey':
        """Derive key from path string like m/44'/2025'/0'/0/0"""
        current = self
        parts   = path.strip().lstrip('m').lstrip('/').split('/')
        for part in parts:
            if not part: continue
            hardened = part.endswith("'") or part.endswith("h")
            idx      = int(part.rstrip("'h"))
            if hardened: idx += HARDENED_OFFSET
            current = current.derive_child(idx)
        return current

    def to_xpub(self) -> str:
        """Serialize as xpub (BIP32 public extended key)"""
        pub   = self.public_key_bytes
        data  = (bytes([0x04,0x88,0xB2,0x1E]) +   # xpub version
                 bytes([self.depth]) +
                 self.parent_fp +
                 struct.pack('>I', self.child_index) +
                 self.chain_code +
                 pub)
        cs    = hashlib.sha256(hashlib.sha256(data).digest()).digest()[:4]
        return base58_encode(data + cs)

    def to_xprv(self) -> str:
        """Serialize as xprv (BIP32 private extended key)"""
        if not self.is_private:
            raise ValueError("Public key has no xprv")
        data  = (bytes([0x04,0x88,0xAD,0xE4]) +   # xprv version
                 bytes([self.depth]) +
                 self.parent_fp +
                 struct.pack('>I', self.child_index) +
                 self.chain_code +
                 b'\x00' + self.key)
        cs    = hashlib.sha256(hashlib.sha256(data).digest()).digest()[:4]
        return base58_encode(data + cs)

    @classmethod
    def from_seed(cls, seed: bytes) -> 'ExtendedKey':
        """Derive master key from BIP39 seed"""
        I  = hmac.new(b"NEBULA seed", seed, hashlib.sha512).digest()
        IL, IR = I[:32], I[32:]
        return cls(key=IL, chain_code=IR, depth=0,
                   parent_fp=b'\x00\x00\x00\x00', child_index=0,
                   is_private=True)

    def to_dict(self) -> dict:
        return {
            "depth"       : self.depth,
            "child_index" : self.child_index,
            "is_hardened" : self.is_hardened,
            "fingerprint" : self.fingerprint.hex(),
            "public_key"  : self.public_key_bytes.hex(),
            "address"     : self.address,
        }

