# ── Multi-Account Wallet ──────────────────────────────────────────
@dataclass
class WalletAccount:
    """Single BIP44 account within an HD wallet"""
    account_index  : int
    addr_type      : AddressType
    xpub           : str
    external_keys  : List[ExtendedKey] = field(default_factory=list)
    internal_keys  : List[ExtendedKey] = field(default_factory=list)
    label          : str = ""
    created_at     : float = field(default_factory=time.time)
    last_used_ext  : int = 0
    last_used_int  : int = 0

    def get_receive_address(self, index: int = None) -> str:
        idx = index if index is not None else self.last_used_ext
        if idx < len(self.external_keys):
            return self.external_keys[idx].address
        return ""

    def get_change_address(self, index: int = None) -> str:
        idx = index if index is not None else self.last_used_int
        if idx < len(self.internal_keys):
            return self.internal_keys[idx].address
        return ""

    def all_addresses(self) -> List[str]:
        return ([k.address for k in self.external_keys] +
                [k.address for k in self.internal_keys])

    def to_dict(self) -> dict:
        return {
            "account"      : self.account_index,
            "type"         : self.addr_type.value,
            "label"        : self.label,
            "addresses"    : len(self.external_keys) + len(self.internal_keys),
            "xpub"         : self.xpub,
        }

