import hashlib, hmac as _hmac, struct, unicodedata
from typing import List, Optional, Tuple

# ── BIP85 Constants ───────────────────────────────────────────────
BIP85_PURPOSE         = 83696968   # 0x4FA7 (BIP85 purpose value)
BIP85_COIN_BTC        = 0
BIP85_COIN_NBL        = 2025
BIP85_HMAC_KEY        = b"bip-entropy-from-k"

# ── BIP85 Application Types ───────────────────────────────────────
