# ── BIP85 Deriver ────────────────────────────────────────────────
class BIP85Deriver:
    """
    BIP85 Deterministic Entropy Derivation.
    All child wallets, keys, passwords derived from a single master key.
    Losing master seed = losing everything. Backing up master = backing up all.
    """

    def __init__(self, master_key: 'HDKey'):
        self.master = master_key

    def _derive_entropy(self, path: str) -> bytes:
        """
        Derive 64 bytes of entropy from derivation path.
        Uses HMAC-SHA512 with BIP85 key.
        """
        child = self.master.derive_path(path)
        # child.key is the private key integer
        privkey_bytes = child.privkey.to_bytes(32, 'big')
        entropy = _hmac.new(BIP85_HMAC_KEY, privkey_bytes, hashlib.sha512).digest()
        return entropy

    def derive_entropy(self, index: int, length: int = 32) -> bytes:
        """Derive raw entropy bytes"""
        path    = f"m/{BIP85_PURPOSE}'/{BIP85_COIN_NBL}'/0'/{index}'"
        entropy = self._derive_entropy(path)
        return entropy[:length]

    def derive_mnemonic(self, words: int = 12, index: int = 0) -> str:
        """
        Derive a BIP39 mnemonic from master key.
        Same index always gives same mnemonic.
        words: 12, 18, or 24
        """
        if words not in (12, 18, 24):
            raise ValueError("words must be 12, 18, or 24")

        # entropy size: 12w=16B, 18w=24B, 24w=32B
        entropy_bytes = {12: 16, 18: 24, 24: 32}[words]
        path     = f"m/{BIP85_PURPOSE}'/{BIP85_App_code(words)}'/{words}'/{index}'"
        raw      = self._derive_entropy(
            f"m/{BIP85_PURPOSE}'/{BIP85_COIN_NBL}'/{words}'/{index}'"
        )[:entropy_bytes]
        return BIP39.entropy_to_mnemonic(raw)

    def derive_wif(self, index: int = 0) -> str:
        """Derive a WIF private key"""
        entropy  = self.derive_entropy(index, 32)
        privkey  = int.from_bytes(entropy[:32], 'big') % Secp256k1.N
        hd       = HDKey(privkey, b'\x00'*32, Secp256k1.point_mul(privkey, Secp256k1.G()))
        return hd.wif

    def derive_xprv(self, index: int = 0) -> str:
        """Derive a child extended private key"""
        entropy = self.derive_entropy(index, 64)
        seed    = entropy[:32]
        child   = HDKey.from_seed(seed)
        return child.to_xprv() if hasattr(child, 'to_xprv') else "xprv_not_implemented"

    def derive_hex(self, num_bytes: int, index: int = 0) -> str:
        """Derive hex entropy string"""
        entropy = self.derive_entropy(index, min(num_bytes, 64))
        return entropy[:num_bytes].hex()

    def derive_password_base64(self, length: int = 20,
                                index: int = 0) -> str:
        """
        Derive a base64 password.
        length: password characters (12–86)
        """
        import base64
        length   = max(12, min(86, length))
        entropy  = self.derive_entropy(index, 64)
        pwd      = base64.b64encode(entropy).decode('ascii')
        return pwd[:length]

    def derive_password(self, length: int = 16, charset: str = None,
                         index: int = 0) -> str:
        """
        Derive a secure password using custom charset.
        Default: letters + digits + symbols.
        """
        if charset is None:
            charset = ("abcdefghijklmnopqrstuvwxyz"
                       "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                       "0123456789!@#$%^&*")
        entropy = self.derive_entropy(index, 64)
        pwd     = ""
        for byte in entropy:
            if len(pwd) >= length:
                break
            idx = byte % len(charset)
            pwd += charset[idx]
        return pwd[:length]

    def derive_child_wallet(self, index: int = 0,
                             word_count: int = 12) -> 'NEBULAWallet':
        """
        Derive a complete child wallet.
        Each index produces a unique, recoverable wallet.
        """
        mnemonic = self.derive_mnemonic(word_count, index)
        return NEBULAWallet.from_mnemonic(mnemonic)

    def derive_dice_seed(self, index: int = 0, num_dice: int = 100) -> List[int]:
        """
        Derive dice roll results (1-6 each).
        Useful for offline key generation verification.
        """
        entropy = self.derive_entropy(index, 64)
        results = []
        for byte in entropy:
            if len(results) >= num_dice:
                break
            val = byte % 6 + 1
            results.append(val)
        return results[:num_dice]

    def backup_info(self) -> dict:
        """
        Show what this master key controls.
        One master = unlimited children.
        """
        return {
            "master_fingerprint": self.master.fingerprint(),
            "derivable_wallets" : "unlimited (2^31 per index)",
            "derivable_wifs"    : "unlimited",
            "derivable_passwords": "unlimited",
            "backup_requirement" : "ONLY the master mnemonic",
            "warning"           : "Lose master → lose ALL derived wallets",
        }

def BIP85_App_code(words: int) -> int:
    """Return BIP85 application code for mnemonic word count"""
    return {12: 12, 18: 18, 24: 24}.get(words, 12)

# ── HD Wallet Extended ────────────────────────────────────────────
class HDWalletExtended(NEBULAWallet):
    """
    Extended HD wallet with BIP85, multi-account, address gap limit.
    Adds: BIP85 child derivation, account management, gap limit scanning.
    """

    GAP_LIMIT = 20   # standard gap limit for address scanning

    def __init__(self, mnemonic: str, passphrase: str = "",
                 utxo_set: 'UTXOSet' = None):
        super().__init__(mnemonic=mnemonic, passphrase=passphrase,
                          utxo_set=utxo_set)
        self._bip85     = BIP85Deriver(self.master)
        self._accounts  : Dict[int, dict] = {0: {"name": "Default", "index": 0}}
        self._gap_limit = self.GAP_LIMIT

    def get_bip85(self) -> BIP85Deriver:
        return self._bip85

    def derive_child_wallet(self, index: int = 0) -> 'HDWalletExtended':
        """Derive child wallet at BIP85 index"""
        mnemonic = self._bip85.derive_mnemonic(12, index)
        return HDWalletExtended(mnemonic)

    def create_account(self, name: str, index: int = None) -> int:
        """Create a new account"""
        idx = index or (max(self._accounts.keys()) + 1)
        self._accounts[idx] = {"name": name, "index": idx}
        return idx

    def get_account_addresses(self, account: int = 0,
                               change: bool = False,
                               count: int = 20) -> List[str]:
        """Get addresses for account/chain"""
        chain = 1 if change else 0
        addrs = []
        for i in range(count):
            path = f"{NBL_BIP44_PATH}/{account}'/{chain}/{i}"
            try:
                key  = self.master.derive_path(path)
                addr = key.address
                addrs.append(addr)
            except Exception:
                break
        return addrs

    def scan_accounts(self, utxo_set: 'UTXOSet',
                       max_accounts: int = 5) -> List[dict]:
        """
        BIP44 account discovery: scan accounts until GAP_LIMIT
        consecutive empty accounts found.
        """
        results   = []
        empty_run = 0

        for acc in range(max_accounts):
            addrs    = self.get_account_addresses(acc, False, self._gap_limit)
            has_used = any(utxo_set.balance(a) > 0 for a in addrs)

            if has_used:
                empty_run = 0
                bal = sum(utxo_set.balance(a) for a in addrs)
                results.append({
                    "account"   : acc,
                    "name"      : self._accounts.get(acc, {}).get("name", f"Account {acc}"),
                    "addresses" : len(addrs),
                    "balance"   : bal / 10**DECIMALS,
                    "has_funds" : True,
                })
            else:
                empty_run += 1
                if empty_run >= 2:
                    break
                results.append({
                    "account"   : acc,
                    "name"      : f"Account {acc}",
                    "balance"   : 0.0,
                    "has_funds" : False,
                })

        return results

    def next_unused_address(self, utxo_set: 'UTXOSet',
                             account: int = 0) -> str:
        """Find next unused address (gap limit scan)"""
        addrs = self.get_account_addresses(account, False, self._gap_limit * 2)
        for addr in addrs:
            if utxo_set.balance(addr) == 0:
                return addr
        # All used — return one past current
        return addrs[-1] if addrs else self.first_address

    def accounts_summary(self) -> List[dict]:
        return [{"index": idx, **info}
                for idx, info in self._accounts.items()]

