import threading, time, hashlib, statistics
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from collections import defaultdict

# ── Rich List ─────────────────────────────────────────────────────
@dataclass
class RichListEntry:
    rank    : int
    address : str
    balance : int     # in Neb
    pct     : float   # % of total supply
    utxos   : int
    label   : str = ""

    @property
    def balance_nbl(self) -> float:
        return self.balance / 10**DECIMALS

    def to_dict(self) -> dict:
        return {
            "rank"       : self.rank,
            "address"    : self.address,
            "balance_nbl": f"{self.balance_nbl:.9f}",
            "pct_supply" : f"{self.pct:.4f}%",
            "utxos"      : self.utxos,
            "label"      : self.label or self.address[:20] + "...",
        }

class RichList:
    """Top-N addresses by balance"""

    def __init__(self, blockchain: 'NEBULABlockchain', top_n: int = 100):
        self.bc     = blockchain
        self.top_n  = top_n
        self._cache : List[RichListEntry] = []
        self._built_at = 0.0
        self._lock  = threading.Lock()

    def build(self) -> List[RichListEntry]:
        """Build rich list from UTXO set"""
        with self._lock:
            addr_bal : Dict[str, int] = defaultdict(int)
            addr_cnt : Dict[str, int] = defaultdict(int)

            for entry in self.bc.utxo._utxos.values():
                addr = entry_address(entry)
                if addr:
                    addr_bal[addr] += entry.value
                    addr_cnt[addr] += 1

            total = sum(addr_bal.values())
            sorted_addrs = sorted(addr_bal.items(),
                                   key=lambda x: x[1], reverse=True)

            self._cache = []
            for rank, (addr, bal) in enumerate(sorted_addrs[:self.top_n], 1):
                pct = bal / total * 100 if total > 0 else 0
                label = "Foundation" if addr == FOUNDATION_ADDRESS else ""
                self._cache.append(RichListEntry(
                    rank=rank, address=addr, balance=bal,
                    pct=pct, utxos=addr_cnt[addr], label=label))

            self._built_at = time.time()
            return self._cache

    def get(self, rebuild_if_stale_secs: float = 300) -> List[RichListEntry]:
        """Get cached rich list, rebuilding if stale"""
        if not self._cache or time.time() - self._built_at > rebuild_if_stale_secs:
            self.build()
        return self._cache

    def to_dict(self) -> dict:
        entries = self.get()
        return {
            "built_at"   : self._built_at,
            "top_n"      : self.top_n,
            "total_addrs": len(entries),
            "entries"    : [e.to_dict() for e in entries[:20]],
        }

# ── UTXO Age Bands ────────────────────────────────────────────────
class UTXOAgeBands:
    """
    Analyse UTXO set by age (HODL waves).
    Groups UTXOs by time since last moved.
    Indicates holder behavior: long-term vs short-term.
    """

    BANDS = [
        ("< 1 day",   0,      1),
        ("1-7 days",  1,      7),
        ("7-30 days", 7,     30),
        ("1-3 months",30,    90),
        ("3-",90,   180),
        ("6-12 months",180, 365),
        ("1-2 years", 365,  730),
        ("2-5 years", 730, 1825),
        ("> 5 years", 1825, 999999),
    ]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def compute(self) -> List[dict]:
        """Compute UTXO age distribution"""
        current_height = self.bc.height
        bands          = defaultdict(lambda: {"count": 0, "value": 0})

        for entry in self.bc.utxo._utxos.values():
            age_blocks = current_height - entry.height
            # Convert blocks to days (approx)
            age_days   = age_blocks * TARGET_BLOCK_TIME / 86400

            for label, min_d, max_d in self.BANDS:
                if min_d <= age_days < max_d:
                    bands[label]["count"] += 1
                    bands[label]["value"] += entry.value
                    break

        total_value = sum(b["value"] for b in bands.values())
        result = []
        for label, min_d, max_d in self.BANDS:
            b   = bands[label]
            pct = b["value"] / total_value * 100 if total_value > 0 else 0
            result.append({
                "band"      : label,
                "utxo_count": b["count"],
                "value_nbl" : f"{b['value']/10**DECIMALS:.2f}",
                "pct_supply": f"{pct:.2f}%",
            })
        return result

# ── Supply Distribution ───────────────────────────────────────────
class SupplyDistribution:
    """Gini coefficient and wealth distribution metrics"""

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def gini_coefficient(self) -> float:
        """
        Compute Gini coefficient for NBL distribution.
        0 = perfect equality, 1 = perfect inequality.
        """
        balances = []
        addr_bal : Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_bal[addr] += entry.value

        balances = sorted(addr_bal.values())
        n        = len(balances)
        if n == 0:
            return 0.0

        total = sum(balances)
        if total == 0:
            return 0.0

        # Gini = 1 - 2*sum((n-i)*b_i) / (n * sum(b_i))
        weighted_sum = sum((n - i) * b for i, b in enumerate(balances))
        gini = 1 - 2 * weighted_sum / (n * total)
        return round(gini, 4)

    def top_n_concentration(self, n: int = 10) -> float:
        """% of supply held by top N addresses"""
        addr_bal : Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_bal[addr] += entry.value

        total   = sum(addr_bal.values())
        top_n   = sorted(addr_bal.values(), reverse=True)[:n]
        top_sum = sum(top_n)
        return top_sum / total * 100 if total > 0 else 0.0

    def percentile_distribution(self) -> dict:
        """Wealth distribution by percentile"""
        addr_bal : Dict[str, int] = defaultdict(int)
        for entry in self.bc.utxo._utxos.values():
            addr = entry_address(entry)
            if addr:
                addr_bal[addr] += entry.value

        balances = sorted(addr_bal.values())
        n        = len(balances)
        total    = sum(balances)

        def percentile_share(pct):
            idx = int(n * pct / 100)
            return sum(balances[idx:]) / total * 100 if total > 0 else 0

        return {
            "gini"           : self.gini_coefficient(),
            "top_1pct_share" : f"{percentile_share(99):.2f}%",
            "top_10pct_share": f"{percentile_share(90):.2f}%",
            "top_50pct_share": f"{percentile_share(50):.2f}%",
            "bottom_50_share": f"{100-percentile_share(50):.2f}%",
            "total_addresses": n,
        }

# ── Fee Market Analyzer ───────────────────────────────────────────
class FeeMarketAnalyzer:
    """Analyze fee market trends from recent blocks"""

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def recent_fee_stats(self, blocks: int = 10) -> dict:
        """Fee statistics for last N blocks"""
        all_rates = []
        chain = self.bc._chain
        start = max(1, len(chain) - blocks)

        for blk in chain[start:]:
            for tx in blk.transactions[1:]:   # skip coinbase
                size = tx.byte_size()
                if size > 0:
                    fee = tx.total_output()   # simplified: no input tracking
                    rate = fee / size
                    if rate > 0:
                        all_rates.append(rate)

        if not all_rates:
            return {"no_data": True}

        return {
            "blocks_analyzed": blocks,
            "tx_count"       : len(all_rates),
            "min_fee_rate"   : round(min(all_rates), 2),
            "max_fee_rate"   : round(max(all_rates), 2),
            "median_fee_rate": round(statistics.median(all_rates), 2),
            "mean_fee_rate"  : round(statistics.mean(all_rates), 2),
        }

    def fee_histogram(self, blocks: int = 100) -> List[dict]:
        """Fee rate histogram (10 buckets)"""
        rates   = []
        chain   = self.bc._chain
        start   = max(1, len(chain) - blocks)

        for blk in chain[start:]:
            for tx in blk.transactions[1:]:
                size = tx.byte_size()
                if size > 0:
                    rates.append(tx.total_output() / size)

        if not rates:
            return []

        mn, mx = min(rates), max(rates)
        if mn == mx:
            return [{"bucket": f"{mn:.0f}", "count": len(rates)}]

        bucket_size = (mx - mn) / 10
        buckets     = [0] * 10
        for r in rates:
            idx = min(9, int((r - mn) / bucket_size))
            buckets[idx] += 1

        return [
            {"bucket": f"{mn + i*bucket_size:.0f}-{mn + (i+1)*bucket_size:.0f}",
             "count" : buckets[i]}
            for i in range(10)
        ]

# ── Mining Pool Detector ─────────────────────────────────────────
class MiningPoolDetector:
    """
    Detect mining pools by analyzing coinbase script patterns.
    Common pools include text tags in coinbase scripts.
    """

    KNOWN_TAGS = {
        b'NEBULA/'     : "NEBULA Solo",
        b'ZaynQuantum' : "NEBULA Core Team",
        b'/pool/'      : "Generic Pool",
        b'FounderPool' : "NEBULA Founder Pool",
    }

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def detect_miner(self, block: 'Block') -> str:
        """Detect miner/pool from coinbase script"""
        if not block.transactions:
            return "unknown"
        cb   = block.transactions[0]
        if not cb.inputs:
            return "unknown"
        script = cb.inputs[0].script_sig
        for tag, name in self.KNOWN_TAGS.items():
            if tag in script:
                return name
        # Use coinbase output address as identifier
        if cb.outputs:
            addr = cb.outputs[0].address
            if addr == FOUNDATION_ADDRESS:
                return "NEBULA Foundation"
            return addr[:16] + "..."
        return "unknown"

    def pool_distribution(self, last_n: int = 100) -> List[dict]:
        """Distribution of blocks by miner/pool"""
        pools : Dict[str, int] = defaultdict(int)
        chain  = self.bc._chain
        start  = max(0, len(chain) - last_n)

        for blk in chain[start:]:
            miner = self.detect_miner(blk)
            pools[miner] += 1

        total  = sum(pools.values())
        result = []
        for miner, count in sorted(pools.items(),
                                    key=lambda x: x[1], reverse=True):
            result.append({
                "miner"  : miner,
                "blocks" : count,
                "pct"    : f"{count/total*100:.1f}%",
            })
        return result

# ── Network Health Monitor ────────────────────────────────────────
class NetworkHealthMonitor:
    """
    Real-time network health metrics.
    Monitors: block times, hashrate estimates, difficulty changes.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def block_time_stats(self, last_n: int = 144) -> dict:
        """Block time statistics for last N blocks"""
        chain = self.bc._chain
        if len(chain) < 2:
            return {"insufficient_data": True}

        start  = max(1, len(chain) - last_n)
        times  = [chain[i].header.timestamp - chain[i-1].header.timestamp
                  for i in range(start, len(chain))]

        if not times:
            return {"insufficient_data": True}

        return {
            "blocks_analyzed"  : len(times),
            "mean_secs"        : round(statistics.mean(times), 1),
            "median_secs"      : round(statistics.median(times), 1),
            "min_secs"         : min(times),
            "max_secs"         : max(times),
            "stdev_secs"       : round(statistics.stdev(times), 1) if len(times) > 1 else 0,
            "target_secs"      : TARGET_BLOCK_TIME,
            "deviation_pct"    : round((statistics.mean(times) - TARGET_BLOCK_TIME)
                                       / TARGET_BLOCK_TIME * 100, 1),
        }

    def estimated_hashrate(self, last_n: int = 144) -> float:
        """
        Estimate network hashrate from recent blocks.
        hashrate = difficulty * 2^32 / block_time
        """
        stats = self.block_time_stats(last_n)
        if "insufficient_data" in stats:
            return 0.0
        mean_time = stats.get("mean_secs", TARGET_BLOCK_TIME)
        target    = bits_to_target(self.bc.tip.header.bits)
        max_t     = bits_to_target(INITIAL_BITS)
        difficulty = max_t / max(1, target)
        return difficulty * (2**32) / max(1, mean_time)

    def difficulty_change_history(self, last_retargets: int = 5) -> List[dict]:
        """History of difficulty adjustments"""
        changes = []
        chain   = self.bc._chain
        for i in range(0, len(chain), DIFFICULTY_WINDOW):
            blk = chain[i] if i < len(chain) else None
            if blk:
                target = bits_to_target(blk.header.bits)
                max_t  = bits_to_target(INITIAL_BITS)
                diff   = max_t / max(1, target)
                changes.append({
                    "height"    : blk.height,
                    "bits"      : hex(blk.header.bits),
                    "difficulty": round(diff, 4),
                })
        return changes[-last_retargets:]

    def health_score(self) -> int:
        """Overall network health score 0-100"""
        score = 100
        stats = self.block_time_stats(144)
        if "insufficient_data" not in stats:
            dev = abs(stats.get("deviation_pct", 0))
            if dev > 50:  score -= 30
            elif dev > 20: score -= 15
            elif dev > 10: score -= 5
        # Check chain height
        if self.bc.height < 1:
            score -= 20
        return max(0, min(100, score))

