# MODULE 28  nebula_p2sh_multisig.py  — P2SH / P2WSH Multisig
# ================================================================
# Full P2SH and P2WSH multisig: m-of-n address creation, signing,
# redeem script management, PSBT multisig coordination.
# ================================================================

import hashlib, threading
from typing import List, Optional, Dict, Tuple

class MultisigWallet:
    """
    m-of-n multisig wallet using P2SH or P2WSH.
    Supports: 2-of-3 cold storage, corporate treasuries, escrow.
    """

    def __init__(self, m: int, pubkeys: List[bytes],
                 use_segwit: bool = True):
        if not (1 <= m <= len(pubkeys) <= 15):
            raise ValueError(f"Invalid m-of-n: {m}-of-{len(pubkeys)}")
        self.m          = m
        self.n          = len(pubkeys)
        self.pubkeys    = sorted(pubkeys)   # BIP67: sorted lexicographically
        self.use_segwit = use_segwit
        self._sigs      : Dict[str, Dict[int, bytes]] = {}   # txid → {key_idx: sig}
        self._lock      = threading.RLock()

    def redeem_script(self) -> bytes:
        """
        Build m-of-n redeem script.
        OP_m <pubkey1> ... <pubkeyn> OP_n OP_CHECKMULTISIG
        """
        OP_M = 0x50 + self.m    # OP_1 through OP_16
        OP_N = 0x50 + self.n
        script = bytes([OP_M])
        for pk in self.pubkeys:
            script += bytes([len(pk)]) + pk
        script += bytes([OP_N, OP_CHECKMULTISIG])
        return script

    def witness_script(self) -> bytes:
        """Same as redeem_script — used in P2WSH"""
        return self.redeem_script()

    def address(self, hrp: str = "nbl") -> str:
        """Get multisig address"""
        rs = self.redeem_script()
        if self.use_segwit:
            # P2WSH address (bech32)
            script = SegWitScript.p2wsh(rs)
            wit_prog = script[2:]   # 32-byte SHA256 hash
            return Bech32.encode(hrp, 0, wit_prog)
        else:
            # P2SH address
            h160   = hashlib.new('ripemd160', hashlib.sha256(rs).digest()).digest()
            return base58check_encode(h160, SCRIPT_ADDRESS_VERSION)

    def locking_script(self) -> bytes:
        """Output locking script (P2SH or P2WSH)"""
        rs = self.redeem_script()
        if self.use_segwit:
            return SegWitScript.p2wsh(rs)
        else:
            h160 = hashlib.new('ripemd160', hashlib.sha256(rs).digest()).digest()
            return bytes([OP_HASH160, len(h160)]) + h160 + bytes([OP_EQUAL])

    def sign(self, tx: 'Transaction', input_index: int,
              privkey: int, value: int = 0) -> bytes:
        """Sign an input spending this multisig"""
        rs = self.redeem_script()
        if self.use_segwit:
            sighash = SighashSegWitV0.compute(
                tx, input_index, rs, value, SIGHASH_ALL)
        else:
            sighash = tx.signature_hash(input_index, rs, SIGHASH_ALL)
        r, s    = Secp256k1.sign(privkey, sighash)
        sig_der = Secp256k1.sig_to_der(r, s) + bytes([SIGHASH_ALL])
        # Store partial sig
        txid    = tx.txid
        pub     = Secp256k1.pubkey_to_bytes(
                      Secp256k1.point_mul(privkey, Secp256k1.G()))
        key_idx = next((i for i,pk in enumerate(self.pubkeys) if pk == pub), -1)
        with self._lock:
            self._sigs.setdefault(txid, {})[key_idx] = sig_der
        return sig_der

    def collect_signatures(self, txid: str) -> List[bytes]:
        """Get collected signatures for a transaction"""
        with self._lock:
            sigs = self._sigs.get(txid, {})
            return [sigs[i] for i in sorted(sigs.keys())]

    def is_ready(self, txid: str) -> bool:
        """True if we have enough signatures"""
        with self._lock:
            return len(self._sigs.get(txid, {})) >= self.m

    def build_witness(self, txid: str) -> List[bytes]:
        """Build witness stack for P2WSH spending"""
        sigs    = self.collect_signatures(txid)
        rs      = self.redeem_script()
        # OP_CHECKMULTISIG needs a dummy OP_0
        return [b''] + sigs[:self.m] + [rs]

    def build_scriptsig(self, txid: str) -> bytes:
        """Build scriptSig for P2SH spending"""
        sigs = self.collect_signatures(txid)
        rs   = self.redeem_script()
        # OP_0 <sig1> ... <sigm> <redeem_script>
        script = bytes([0x00])   # OP_0 (dummy for CHECKMULTISIG bug)
        for sig in sigs[:self.m]:
            script += bytes([len(sig)]) + sig
        script += bytes([0x4c, len(rs)]) + rs   # OP_PUSHDATA1
        return script

    def info(self) -> dict:
        return {
            "type"        : f"P2WSH" if self.use_segwit else "P2SH",
            "threshold"   : f"{self.m}-of-{self.n}",
            "address"     : self.address(),
            "pubkeys"     : [pk.hex() for pk in self.pubkeys],
            "redeem_script": self.redeem_script().hex(),
        }


