# MODULE 29  nebula_watchdog.py  — Node Watchdog + Auto-Restart
# ================================================================
# Monitors node health, auto-restarts on failure, sends alerts.
# ================================================================

import threading, time, os, sys
from typing import Callable, Optional, Dict
from dataclasses import dataclass, field

@dataclass
class WatchdogConfig:
    check_interval_secs  : float = 30.0
    max_block_age_secs   : float = 3600.0   # alert if no new block for 1h
    min_peer_count       : int   = 1
    max_mempool_size     : int   = 50_000
    restart_on_failure   : bool  = True
    max_restart_attempts : int   = 5
    restart_delay_secs   : float = 5.0
    alert_callback       : Optional[Callable] = None

class NodeWatchdog:
    """
    Watchdog monitor for NEBULA node health.
    Detects: stalled mining, peer disconnection, mempool overflow,
    chain forks, excessive memory usage.
    Auto-restarts services on failure.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 config: WatchdogConfig = None):
        self.bc          = blockchain
        self.config      = config or WatchdogConfig()
        self._running    = False
        self._thread     : Optional[threading.Thread] = None
        self._last_height= blockchain.height
        self._last_block_time = time.time()
        self._restart_count  = 0
        self._alerts     : List[dict] = []
        self._lock       = threading.Lock()

    def start(self):
        self._running = True
        self._thread  = threading.Thread(
            target=self._watch_loop, daemon=True, name="Watchdog")
        self._thread.start()
        print("🐕 Node Watchdog started")

    def stop(self):
        self._running = False
        if self._thread:
            self._thread.join(timeout=5)

    def _watch_loop(self):
        while self._running:
            try:
                self._check_all()
            except Exception as e:
                self._alert("watchdog_error", f"Watchdog check failed: {e}")
            time.sleep(self.config.check_interval_secs)

    def _check_all(self):
        checks = [
            self._check_block_age,
            self._check_mempool,
            self._check_chain_height,
        ]
        for check in checks:
            try:
                check()
            except Exception as e:
                self._alert("check_error", str(e))

    def _check_block_age(self):
        """Alert if no new block for too long"""
        if self.bc.height > self._last_height:
            self._last_height     = self.bc.height
            self._last_block_time = time.time()
        age = time.time() - self._last_block_time
        if age > self.config.max_block_age_secs:
            self._alert("stalled_chain",
                        f"No new block for {age/60:.0f} minutes")

    def _check_mempool(self):
        """Alert if mempool is too large"""
        size = self.bc.mempool.size()
        if size > self.config.max_mempool_size:
            self._alert("mempool_overflow",
                        f"Mempool has {size} txs (limit: {self.config.max_mempool_size})")

    def _check_chain_height(self):
        """Log current status"""
        pass   # basic health log

    def _alert(self, alert_type: str, message: str):
        """Record and dispatch alert"""
        alert = {
            "type"      : alert_type,
            "message"   : message,
            "timestamp" : time.time(),
            "height"    : self.bc.height,
        }
        with self._lock:
            self._alerts.append(alert)
            if len(self._alerts) > 1000:
                self._alerts.pop(0)
        print(f"⚠️  Watchdog [{alert_type}]: {message}")
        if self.config.alert_callback:
            self.config.alert_callback(alert)

    def get_alerts(self, last_n: int = 20) -> List[dict]:
        with self._lock:
            return list(self._alerts[-last_n:])

    def health_report(self) -> dict:
        block_age = time.time() - self._last_block_time
        return {
            "status"       : "healthy" if block_age < self.config.max_block_age_secs else "stalled",
            "last_block_age_secs": round(block_age),
            "chain_height" : self.bc.height,
            "mempool_size" : self.bc.mempool.size(),
            "restart_count": self._restart_count,
            "alert_count"  : len(self._alerts),
            "uptime_secs"  : round(time.time() - (self._last_block_time - 1)),
        }


