# ── ASN Diversity Manager ─────────────────────────────────────────
class ASNDiversityManager:
    """
    Ensure connection diversity across Autonomous Systems (ASNs).
    Prevents eclipse attacks where attacker controls all connections
    from same network (same ISP/ASN).
    """

    MAX_PER_ASN = 2   # max connections from same ASN

    def __init__(self):
        self._asn_counts : Dict[str, int] = defaultdict(int)
        self._ip_to_asn  : Dict[str, str] = {}
        self._lock       = threading.RLock()

    def _lookup_asn(self, ip: str) -> str:
        """
        Look up ASN for IP address.
        Simplified: uses first two octets as proxy for /16 subnet.
        Production: use GeoIP database or whois.
        """
        parts = ip.split('.')
        if len(parts) >= 2:
            return f"AS{parts[0]}.{parts[1]}"
        return "AS_unknown"

    def can_connect(self, ip: str) -> bool:
        """True if we should accept connection from this IP"""
        asn = self._lookup_asn(ip)
        with self._lock:
            return self._asn_counts.get(asn, 0) < self.MAX_PER_ASN

    def register(self, ip: str):
        """Register new connection"""
        asn = self._lookup_asn(ip)
        with self._lock:
            self._asn_counts[asn] += 1
            self._ip_to_asn[ip]    = asn

    def unregister(self, ip: str):
        """Unregister disconnected peer"""
        with self._lock:
            asn = self._ip_to_asn.pop(ip, None)
            if asn and self._asn_counts.get(asn, 0) > 0:
                self._asn_counts[asn] -= 1

    def diversity_score(self) -> float:
        """0.0 = all same ASN, 1.0 = all different ASNs"""
        with self._lock:
            if not self._ip_to_asn:
                return 1.0
            unique_asns  = len(self._asn_counts)
            total_peers  = len(self._ip_to_asn)
            return unique_asns / total_peers if total_peers > 0 else 1.0

    def stats(self) -> dict:
        with self._lock:
            return {
                "unique_asns"    : len(self._asn_counts),
                "total_peers"    : len(self._ip_to_asn),
                "diversity_score": round(self.diversity_score(), 3),
                "top_asns"       : sorted(
                    [(asn, count) for asn, count in self._asn_counts.items()],
                    key=lambda x: x[1], reverse=True)[:5],
            }

