# ── Fee Market Analytics ──────────────────────────────────────────
class FeeMarketAnalytics:
    """
    Analyzes fee market: median fees, fee distribution,
    fee rate percentiles, block fullness.
    """

    def __init__(self, window: int = 144):   # 144 blocks ~ 1 day
        self.window       = window
        self._block_fees  : List[dict] = []
        self._lock        = threading.Lock()

    def add_block(self, block: 'Block', utxo: 'UTXOSet'):
        fees = []
        for tx in block.transactions[1:]:   # skip coinbase
            in_val  = sum(
                utxo.get(i.outpoint.txid, i.outpoint.index).value
                for i in tx.inputs
                if utxo.get(i.outpoint.txid, i.outpoint.index)
            )
            out_val = sum(o.value for o in tx.outputs)
            fee = max(0, in_val - out_val)
            vsize = max(1, tx.byte_size())
            fees.append({
                "fee"       : fee,
                "vsize"     : vsize,
                "fee_rate"  : fee / vsize,
            })

        with self._lock:
            self._block_fees.append({
                "height"     : block.height,
                "time"       : block.header.timestamp,
                "tx_count"   : len(block.transactions),
                "total_fees" : sum(f["fee"] for f in fees),
                "median_rate": sorted([f["fee_rate"] for f in fees])[len(fees)//2]
                               if fees else 0,
                "fullness"   : block.byte_size() / MAX_BLOCK_SIZE_BYTES,
                "fees"       : fees,
            })
            if len(self._block_fees) > self.window:
                self._block_fees.pop(0)

    def percentiles(self) -> dict:
        all_rates = []
        with self._lock:
            for bf in self._block_fees:
                all_rates.extend(f["fee_rate"] for f in bf.get("fees",[]))

        if not all_rates:
            return {}
        all_rates.sort()
        n = len(all_rates)
        return {
            "p10" : all_rates[n//10],
            "p25" : all_rates[n//4],
            "p50" : all_rates[n//2],
            "p75" : all_rates[3*n//4],
            "p90" : all_rates[9*n//10],
            "p99" : all_rates[min(n-1, 99*n//100)],
        }

    def summary(self) -> dict:
        with self._lock:
            if not self._block_fees:
                return {}
            recent  = self._block_fees[-1] if self._block_fees else {}
            avg_full= sum(b["fullness"] for b in self._block_fees) / max(1, len(self._block_fees))
            return {
                "window_blocks"   : len(self._block_fees),
                "latest_height"   : recent.get("height", 0),
                "latest_median_rate": recent.get("median_rate", 0),
                "avg_block_fullness": f"{avg_full*100:.1f}%",
                "fee_percentiles" : self.percentiles(),
            }

