# ── Contract Address Generation ───────────────────────────────────
def contract_address(creator: str, nonce: int) -> str:
    """Generate contract address from creator address and nonce"""
    data   = creator.encode() + nonce.to_bytes(8, 'big')
    h256   = hashlib.sha256(data).digest()
    h160   = hashlib.new('ripemd160', h256).digest()
    return base58check_encode(h160, 0x05)   # P2SH prefix for contracts

