# ── ABI Encoder / Decoder ─────────────────────────────────────────
class ABICodec:
    """
    Solidity-compatible ABI encoding/decoding.
    Supports: uint256, int256, address, bool, bytes, string, arrays.
    """

    WORD = 32   # ABI word size

    @staticmethod
    def encode_uint(value: int) -> bytes:
        return value.to_bytes(32, 'big')

    @staticmethod
    def encode_int(value: int) -> bytes:
        return value.to_bytes(32, 'big', signed=True)

    @staticmethod
    def encode_address(address: str) -> bytes:
        try:
            _, h160 = base58check_decode(address)
            return b'\x00' * 12 + h160
        except Exception:
            return b'\x00' * 32

    @staticmethod
    def encode_bool(value: bool) -> bytes:
        return (1 if value else 0).to_bytes(32, 'big')

    @staticmethod
    def encode_bytes(data: bytes) -> bytes:
        length = len(data)
        padded = data + b'\x00' * ((-length) % 32)
        return length.to_bytes(32, 'big') + padded

    @staticmethod
    def encode_string(value: str) -> bytes:
        return ABICodec.encode_bytes(value.encode('utf-8'))

    @staticmethod
    def function_selector(signature: str) -> bytes:
        """keccak256 first 4 bytes of function signature"""
        h = hashlib.sha256(signature.encode()).digest()
        return h[:4]   # simplified (should be keccak256)

    @staticmethod
    def encode_call(func_sig: str, args: List[Any]) -> bytes:
        selector = ABICodec.function_selector(func_sig)
        encoded  = b''
        for arg in args:
            if isinstance(arg, int):
                encoded += ABICodec.encode_uint(arg)
            elif isinstance(arg, bool):
                encoded += ABICodec.encode_bool(arg)
            elif isinstance(arg, str) and len(arg) > 10:
                encoded += ABICodec.encode_string(arg)
            elif isinstance(arg, bytes):
                encoded += ABICodec.encode_bytes(arg)
            else:
                encoded += ABICodec.encode_uint(int(arg) if arg else 0)
        return selector + encoded

    @staticmethod
    def decode_uint(data: bytes, offset: int = 0) -> int:
        return int.from_bytes(data[offset:offset+32], 'big')

    @staticmethod
    def decode_address(data: bytes, offset: int = 0) -> str:
        h160 = data[offset+12:offset+32]
        return base58check_encode(h160, PUBKEY_ADDRESS_VERSION)

