# ── Contract Storage ──────────────────────────────────────────────
class ContractStorage:
    """Per-contract key-value storage with journaling for rollback"""

    def __init__(self):
        self._data    : Dict[bytes, bytes] = {}
        self._journal : List[Tuple[bytes, Optional[bytes]]] = []
        self._lock    = threading.Lock()

    def get(self, key: bytes) -> bytes:
        return self._data.get(key, b'\x00' * 32)

    def set(self, key: bytes, value: bytes):
        with self._lock:
            old = self._data.get(key)
            self._journal.append((key, old))
            if value == b'\x00' * 32:
                self._data.pop(key, None)
            else:
                self._data[key] = value

    def checkpoint(self) -> int:
        return len(self._journal)

    def revert_to(self, checkpoint: int):
        with self._lock:
            while len(self._journal) > checkpoint:
                key, old = self._journal.pop()
                if old is None:
                    self._data.pop(key, None)
                else:
                    self._data[key] = old

    def commit(self):
        self._journal.clear()

    def __len__(self) -> int:
        return len(self._data)

# ── Smart Contract ────────────────────────────────────────────────
@dataclass
class SmartContract:
    """A deployed NEBULA smart contract"""
    address      : str
    bytecode     : bytes
    creator      : str
    created_at   : int         # block height
    abi          : List[dict]  = field(default_factory=list)
    storage      : ContractStorage = field(default_factory=ContractStorage)
    balance      : int          = 0
    nonce        : int          = 0
    name         : str          = ""
    version      : str          = "1.0"
    is_erc20     : bool         = False
    is_erc721    : bool         = False
    is_erc1155   : bool         = False

    def code_hash(self) -> bytes:
        return hashlib.sha256(self.bytecode).digest()

    def to_dict(self) -> dict:
        return {
            "address"    : self.address,
            "creator"    : self.creator,
            "created_at" : self.created_at,
            "code_size"  : len(self.bytecode),
            "code_hash"  : self.code_hash().hex(),
            "balance_nbl": self.balance / 10**DECIMALS,
            "nonce"      : self.nonce,
            "storage_slots": len(self.storage),
            "name"       : self.name,
            "is_erc20"   : self.is_erc20,
        }

# ── NBL-20 Token Standard ─────────────────────────────────────────
class NBL20TokenAdv:
    """
    NBL-20 fungible token standard (like ERC-20).
    Full implementation: mint, burn, transfer, approve, allowance.
    """

    def __init__(self, name: str, symbol: str,
                 decimals: int, total_supply: int,
                 owner: str, contract_addr: str = ""):
        self.name          = name
        self.symbol        = symbol
        self.decimals      = decimals
        self.total_supply  = total_supply
        self.owner         = owner
        self.address       = contract_addr or contract_address(owner, 0)
        self._balances     : Dict[str, int] = {owner: total_supply}
        self._allowances   : Dict[str, Dict[str, int]] = {}
        self._events       : List[ContractEvent] = []
        self._lock         = threading.Lock()

    def balance_of(self, account: str) -> int:
        return self._balances.get(account, 0)

    def allowance(self, owner: str, spender: str) -> int:
        return self._allowances.get(owner, {}).get(spender, 0)

    def transfer(self, from_addr: str, to_addr: str,
                 amount: int, height: int = 0) -> Tuple[bool, str]:
        with self._lock:
            if from_addr == to_addr:
                return False, "Cannot transfer to self"
            if amount <= 0:
                return False, "Amount must be positive"
            if self._balances.get(from_addr, 0) < amount:
                return False, f"Insufficient balance: {self._balances.get(from_addr, 0)} < {amount}"
            self._balances[from_addr] = self._balances.get(from_addr, 0) - amount
            self._balances[to_addr]   = self._balances.get(to_addr, 0) + amount
            self._emit("Transfer", [from_addr, to_addr, amount], height)
            return True, "OK"

    def approve(self, owner: str, spender: str,
                amount: int, height: int = 0) -> bool:
        with self._lock:
            self._allowances.setdefault(owner, {})[spender] = amount
            self._emit("Approval", [owner, spender, amount], height)
            return True

    def transfer_from(self, caller: str, from_addr: str,
                       to_addr: str, amount: int,
                       height: int = 0) -> Tuple[bool, str]:
        with self._lock:
            allowed = self._allowances.get(from_addr, {}).get(caller, 0)
            if allowed < amount:
                return False, f"Insufficient allowance: {allowed} < {amount}"
            self._allowances[from_addr][caller] -= amount
        return self.transfer(from_addr, to_addr, amount, height)

    def mint(self, to_addr: str, amount: int,
             caller: str = "", height: int = 0) -> Tuple[bool, str]:
        if caller and caller != self.owner:
            return False, "Only owner can mint"
        if self.total_supply + amount > MAX_SUPPLY:
            return False, "Exceeds max supply"
        with self._lock:
            self._balances[to_addr]  = self._balances.get(to_addr, 0) + amount
            self.total_supply       += amount
            self._emit("Mint", [to_addr, amount], height)
        return True, "OK"

    def burn(self, from_addr: str, amount: int,
             height: int = 0) -> Tuple[bool, str]:
        with self._lock:
            if self._balances.get(from_addr, 0) < amount:
                return False, "Insufficient balance"
            self._balances[from_addr] -= amount
            self.total_supply         -= amount
            self._emit("Burn", [from_addr, amount], height)
        return True, "OK"

    def _emit(self, event: str, args: List[Any], height: int):
        self._events.append(ContractEventC(
            contract_addr = self.address,
            event_name    = event,
            topics        = [ABICodec.function_selector(event)],
            data          = b''.join(
                ABICodec.encode_uint(a) if isinstance(a,int)
                else ABICodec.encode_address(a) for a in args),
            block_height  = height,
            tx_index      = 0,
            log_index     = len(self._events),
        ))

    def holders(self) -> int:
        return sum(1 for b in self._balances.values() if b > 0)

    def events(self, n: int = 20) -> List[dict]:
        return [e.to_dict() for e in self._events[-n:]]

    def to_dict(self) -> dict:
        return {
            "address"      : self.address,
            "name"         : self.name,
            "symbol"       : self.symbol,
            "decimals"     : self.decimals,
            "total_supply" : self.total_supply,
            "holders"      : self.holders(),
            "owner"        : self.owner,
            "type"         : "NBL-20",
        }

# ── NBL-721 NFT Standard ──────────────────────────────────────────
class NBL721Token:
    """
    NBL-721 Non-Fungible Token standard (like ERC-721).
    Each token is unique with a unique tokenId.
    """

    def __init__(self, name: str, symbol: str,
                 base_uri: str, owner: str):
        self.name       = name
        self.symbol     = symbol
        self.base_uri   = base_uri
        self.owner      = owner
        self.address    = contract_address(owner, 721)
        self._owners    : Dict[int, str] = {}       # tokenId -> owner
        self._balances  : Dict[str, int] = {}       # owner -> count
        self._approvals : Dict[int, str] = {}       # tokenId -> approved
        self._operators : Dict[str, Set[str]] = {}  # owner -> operators
        self._metadata  : Dict[int, dict] = {}      # tokenId -> metadata
        self._token_count = 0
        self._events    : List[ContractEvent] = []
        self._lock      = threading.Lock()

    def mint(self, to_addr: str, token_id: int = None,
             metadata: dict = None, height: int = 0) -> Tuple[bool, int]:
        """Mint a new NFT. Returns (success, token_id)"""
        with self._lock:
            if token_id is None:
                self._token_count += 1
                token_id = self._token_count
            if token_id in self._owners:
                return False, -1
            self._owners[token_id]   = to_addr
            self._balances[to_addr]  = self._balances.get(to_addr, 0) + 1
            if metadata:
                self._metadata[token_id] = metadata
            self._emit("Transfer", [None, to_addr, token_id], height)
        return True, token_id

    def transfer(self, from_addr: str, to_addr: str,
                 token_id: int, height: int = 0) -> Tuple[bool, str]:
        with self._lock:
            if self._owners.get(token_id) != from_addr:
                return False, "Not owner"
            self._owners[token_id]    = to_addr
            self._balances[from_addr] = max(0, self._balances.get(from_addr,0) - 1)
            self._balances[to_addr]   = self._balances.get(to_addr,0) + 1
            self._approvals.pop(token_id, None)
            self._emit("Transfer", [from_addr, to_addr, token_id], height)
        return True, "OK"

    def approve(self, owner: str, approved: str, token_id: int) -> bool:
        with self._lock:
            if self._owners.get(token_id) != owner:
                return False
            self._approvals[token_id] = approved
        return True

    def set_approval_for_all(self, owner: str, operator: str,
                              approved: bool) -> bool:
        with self._lock:
            ops = self._operators.setdefault(owner, set())
            if approved: ops.add(operator)
            else: ops.discard(operator)
        return True

    def owner_of(self, token_id: int) -> Optional[str]:
        return self._owners.get(token_id)

    def balance_of(self, owner: str) -> int:
        return self._balances.get(owner, 0)

    def token_uri(self, token_id: int) -> str:
        return f"{self.base_uri}/{token_id}"

    def tokens_of_owner(self, owner: str) -> List[int]:
        return [tid for tid, o in self._owners.items() if o == owner]

    def _emit(self, event: str, args: List[Any], height: int):
        self._events.append(ContractEventC(
            contract_addr = self.address,
            event_name    = event,
            topics        = [ABICodec.function_selector(event)],
            data          = b'',
            block_height  = height,
            tx_index      = 0,
            log_index     = len(self._events),
        ))

    def total_supply(self) -> int:
        return len(self._owners)

    def to_dict(self) -> dict:
        return {
            "address"     : self.address,
            "name"        : self.name,
            "symbol"      : self.symbol,
            "total_supply": self.total_supply(),
            "owner"       : self.owner,
            "type"        : "NBL-721",
            "base_uri"    : self.base_uri,
        }

# ── Contract Registry ─────────────────────────────────────────────
class ContractRegistry:
    """
    Global registry of all deployed contracts.
    Tracks NBL-20 tokens, NBL-721 NFTs, and raw contracts.
    """

    def __init__(self):
        self._contracts : Dict[str, SmartContract]  = {}
        self._nbl20     : Dict[str, NBL20Token]     = {}
        self._nbl721    : Dict[str, NBL721Token]    = {}
        self._nonces    : Dict[str, int] = {}
        self._events    : List[ContractEvent]        = []
        self._lock      = threading.RLock()

    def deploy_nbl20(self, name: str, symbol: str, decimals: int,
                      supply: int, owner: str,
                      height: int = 0) -> NBL20Token:
        """Deploy NBL-20 token"""
        token = NBL20Token(name, symbol, decimals, supply, owner)
        with self._lock:
            self._nbl20[token.address] = token
            self._nonces[owner] = self._nonces.get(owner, 0) + 1
        return token

    def deploy_nbl721(self, name: str, symbol: str,
                       base_uri: str, owner: str) -> NBL721Token:
        """Deploy NBL-721 NFT collection"""
        token = NBL721Token(name, symbol, base_uri, owner)
        with self._lock:
            self._nbl721[token.address] = token
            self._nonces[owner] = self._nonces.get(owner, 0) + 1
        return token

    def get_nbl20(self, addr: str) -> Optional[NBL20Token]:
        return self._nbl20.get(addr)

    def get_nbl721(self, addr: str) -> Optional[NBL721Token]:
        return self._nbl721.get(addr)

    def is_contract(self, addr: str) -> bool:
        return addr in self._contracts or addr in self._nbl20 or addr in self._nbl721

    def all_tokens(self) -> List[dict]:
        result = []
        for t in self._nbl20.values():
            result.append(t.to_dict())
        for t in self._nbl721.values():
            result.append(t.to_dict())
        return result

    def stats(self) -> dict:
        return {
            "total_contracts" : len(self._contracts),
            "nbl20_tokens"    : len(self._nbl20),
            "nbl721_nfts"     : len(self._nbl721),
            "deployers"       : len(self._nonces),
        }

    def get_events(self, contract_addr: str = None,
                    event_name: str = None,
                    limit: int = 100) -> List[dict]:
        events = self._events
        if contract_addr:
            events = [e for e in events if e.contract_addr == contract_addr]
        if event_name:
            events = [e for e in events if e.event_name == event_name]
        return [e.to_dict() for e in events[-limit:]]

