# MODULE 32  nebula_rpc_batch.py  — JSON-RPC Batch + Async Client
# ================================================================

import json, socket, threading, time
from typing import List, Dict, Any, Optional, Callable

class RPCBatchClient:
    """
    Async JSON-RPC batch client for NEBULA node.
    Supports: batch requests, connection pooling, retry logic.
    """

    def __init__(self, host: str = "127.0.0.1",
                 port: int = RPC_DEFAULT_PORT,
                 user: str = "nebula",
                 password: str = "nebula_rpc_pass",
                 timeout: float = 30.0):
        self.host     = host
        self.port     = port
        self.auth     = (user, password)
        self.timeout  = timeout
        self._id      = 0
        self._lock    = threading.Lock()

    def _next_id(self) -> int:
        with self._lock:
            self._id += 1
            return self._id

    def call(self, method: str, params: list = None) -> Any:
        """Single RPC call"""
        return self.batch([{"method": method, "params": params or []}])[0]

    def batch(self, requests: List[dict]) -> List[Any]:
        """
        Batch RPC call — send multiple requests in one HTTP call.
        More efficient than individual calls.
        """
        import urllib.request, base64
        payload = [
            {"jsonrpc": "2.0", "method": r["method"],
             "params": r.get("params", []),
             "id": self._next_id()}
            for r in requests
        ]
        data    = json.dumps(payload).encode()
        url     = f"http://{self.host}:{self.port}/"
        req     = urllib.request.Request(url, data=data,
                    headers={"Content-Type": "application/json"})

        # Basic auth
        creds = base64.b64encode(
            f"{self.auth[0]}:{self.auth[1]}".encode()).decode()
        req.add_header("Authorization", f"Basic {creds}")

        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                responses = json.loads(resp.read())
                if isinstance(responses, list):
                    return [r.get("result") for r in responses]
                return [responses.get("result")]
        except Exception as e:
            return [None] * len(requests)

    def get_chain_info(self) -> dict:
        return self.call("getblockchaininfo") or {}

    def get_balance(self, address: str) -> float:
        return self.call("getbalance", [address]) or 0.0

    def get_block(self, height: int) -> Optional[dict]:
        hash_val = self.call("getblockhash", [height])
        if not hash_val:
            return None
        return self.call("getblock", [hash_val, 1])

    def send_to_address(self, address: str, amount: float) -> Optional[str]:
        return self.call("sendtoaddress", [address, amount])

    def batch_get_balances(self, addresses: List[str]) -> Dict[str, float]:
        """Get balances for multiple addresses in one batch request"""
        requests = [{"method": "getbalance", "params": [addr]}
                    for addr in addresses]
        results = self.batch(requests)
        return {addr: (bal or 0.0)
                for addr, bal in zip(addresses, results)}

    def batch_get_blocks(self, heights: List[int]) -> List[Optional[dict]]:
        """Get multiple blocks in two round trips"""
        hash_reqs = [{"method": "getblockhash", "params": [h]}
                     for h in heights]
        hashes    = self.batch(hash_reqs)

        block_reqs = [{"method": "getblock", "params": [h, 1]}
                      for h in hashes if h]
        return self.batch(block_reqs)

    def monitor(self, callback: Callable, interval: float = 10.0):
        """
        Continuously monitor chain and call callback on new blocks.
        """
        last_height = -1
        while True:
            try:
                info = self.get_chain_info()
                height = info.get("blocks", -1)
                if height > last_height:
                    last_height = height
                    callback(height, info)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in RPCBatchClient.monitor", exc_info=True)
            time.sleep(interval)


