# ================================================================
# BIP/NEP proposals, voting, timelock, DAO treasury,
# parameter updates, emergency multisig.
# ================================================================

import time, threading, hashlib
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum

# ── Governance Constants ──────────────────────────────────────────
PROPOSAL_DURATION      = 201_600  # blocks (~2 weeks)
TIMELOCK_DELAY         = 14_400   # blocks (~1 day)
QUORUM_PERCENT         = 4        # 4% of circulating supply
MAJORITY_PERCENT       = 51       # 51% yes votes to pass
MAX_ACTIVE_PROPOSALS   = 20
PROPOSAL_BOND          = 100 * 10**DECIMALS  # 100 NBL bond
EMERGENCY_THRESHOLD    = 3        # 3-of-5 multisig for emergency

class ProposalState(Enum):
    PENDING   = "pending"
    ACTIVE    = "active"
    CANCELLED = "cancelled"
    DEFEATED  = "defeated"
    SUCCEEDED = "succeeded"
    QUEUED    = "queued"
    EXECUTED  = "executed"
    EXPIRED   = "expired"

class ProposalType(Enum):
    PARAMETER_CHANGE = "parameter_change"
    UPGRADE          = "upgrade"
    TREASURY_SPEND   = "treasury_spend"
    TEXT             = "text"
    EMERGENCY        = "emergency"

class VoteChoice(Enum):
    AGAINST = 0
    FOR     = 1
    ABSTAIN = 2

# ── Governance Proposal ───────────────────────────────────────────
@dataclass
class Proposal:
    proposal_id   : int
    proposer      : str
    title         : str
    description   : str
    proposal_type : ProposalType
    calldata      : bytes         # encoded action
    start_block   : int
    end_block     : int
    bond          : int = PROPOSAL_BOND
    state         : ProposalState = ProposalState.PENDING
    votes_for     : int = 0
    votes_against : int = 0
    votes_abstain : int = 0
    eta           : int = 0       # timelock ETA (block height)
    executed_at   : float = 0.0
    created_at    : float = field(default_factory=time.time)
    canceller     : str = ""
    _voters       : Dict[str, VoteChoice] = field(default_factory=dict)

    @property
    def total_votes(self) -> int:
        return self.votes_for + self.votes_against + self.votes_abstain

    @property
    def approval_pct(self) -> float:
        v = self.votes_for + self.votes_against
        return self.votes_for / max(1, v) * 100

    def has_voted(self, voter: str) -> bool:
        return voter in self._voters

    def record_vote(self, voter: str, choice: VoteChoice, weight: int):
        self._voters[voter] = choice
        if choice == VoteChoice.FOR:
            self.votes_for     += weight
        elif choice == VoteChoice.AGAINST:
            self.votes_against += weight
        else:
            self.votes_abstain += weight

    def to_dict(self) -> dict:
        return {
            "id"           : self.proposal_id,
            "proposer"     : self.proposer,
            "title"        : self.title,
            "type"         : self.proposal_type.value,
            "state"        : self.state.value,
            "start_block"  : self.start_block,
            "end_block"    : self.end_block,
            "votes_for"    : self.votes_for,
            "votes_against": self.votes_against,
            "votes_abstain": self.votes_abstain,
            "total_votes"  : self.total_votes,
            "approval_pct" : round(self.approval_pct, 2),
            "voters"       : len(self._voters),
            "eta"          : self.eta,
        }

# ── Timelock ──────────────────────────────────────────────────────
class Timelock:
    """
    On-chain timelock for governance actions.
    All parameter changes must wait TIMELOCK_DELAY blocks.
    Prevents immediate execution of passed proposals.
    """

    def __init__(self, delay: int = TIMELOCK_DELAY):
        self.delay      = delay
        self._queue     : Dict[bytes, dict] = {}
        self._executed  : set = set()
        self._lock      = threading.Lock()

    def queue_tx(self, tx_hash: bytes, target: str,
                  calldata: bytes, eta: int) -> bool:
        with self._lock:
            if tx_hash in self._queue:
                return False
            self._queue[tx_hash] = {
                "target"   : target,
                "calldata" : calldata,
                "eta"      : eta,
                "queued_at": time.time(),
            }
        return True

    def execute_tx(self, tx_hash: bytes,
                    current_height: int) -> Tuple[bool, str]:
        with self._lock:
            if tx_hash not in self._queue:
                return False, "Not queued"
            entry = self._queue[tx_hash]
            if current_height < entry["eta"]:
                return False, f"Timelock: {entry['eta'] - current_height} blocks remaining"
            if current_height > entry["eta"] + 14_400:  # grace period
                del self._queue[tx_hash]
                return False, "Expired"
            del self._queue[tx_hash]
            self._executed.add(tx_hash)
        return True, "Executed"

    def cancel_tx(self, tx_hash: bytes) -> bool:
        with self._lock:
            return bool(self._queue.pop(tx_hash, None))

    def pending(self) -> List[dict]:
        return list(self._queue.values())

