# ── Staking Pool ──────────────────────────────────────────────────
class StakingPool:
    """
    Manages staking for a single validator.
    Handles delegations, undelegations, reward distribution.
    """

    def __init__(self, validator: Validator):
        self.validator    = validator
        self._rewards     : Dict[str, int] = {}  # delegator -> pending rewards
        self._lock        = threading.Lock()

    def distribute_rewards(self, epoch_reward: int, epoch: int):
        """Distribute epoch rewards to delegators proportionally"""
        with self._lock:
            if self.validator.stake == 0: return

            # Commission to validator
            commission  = epoch_reward * self.validator.commission_rate
            val_share   = int(commission + epoch_reward * self.validator.self_stake /
                              max(1, self.validator.stake))
            self._rewards[self.validator.address] = (
                self._rewards.get(self.validator.address, 0) + val_share)

            # Delegator shares
            remaining = epoch_reward - val_share
            for delegator, del_amount in self.validator._delegators.items():
                if delegator == self.validator.address: continue
                share = remaining * del_amount // max(1, self.validator.delegated)
                self._rewards[delegator] = self._rewards.get(delegator, 0) + share

    def claim_rewards(self, delegator: str) -> int:
        with self._lock:
            amount = self._rewards.pop(delegator, 0)
            return amount

    def pending_rewards(self, delegator: str) -> int:
        return self._rewards.get(delegator, 0)

    def total_pending(self) -> int:
        return sum(self._rewards.values())

