# ── Compact Block Relay ───────────────────────────────────────────
class CompactBlockRelayLegacy:
    """[v10.17] OLD implementation kept ONLY for old stand-alone callers (their API differs from the live CompactBlockRelay)."""
    """
    BIP152 compact block relay.
    Sends short TXIDs instead of full transactions.
    Receiver reconstructs block from mempool.
    Fallback: request missing transactions.
    """

    def __init__(self, mempool: 'AdvancedMempool' = None):
        self.mempool  = mempool
        self._prefill : Dict[str, bytes] = {}   # txid -> tx bytes
        self._lock    = threading.Lock()

    def create_compact_block(self, block: 'Block',
                              mode: int = 1) -> dict:
        """
        Create compact block message.
        mode 0: send to peers who share mempool
        mode 1: include most likely missing txs as prefill
        """
        nonce     = random.randint(0, 2**64 - 1)
        short_ids = []

        for tx in block.transactions[1:]:   # skip coinbase
            txid  = tx.txid
            # SipHash-based short ID (6 bytes)
            h = hashlib.sha256(txid.encode() + nonce.to_bytes(8,'big')).digest()
            short_ids.append(int.from_bytes(h[:6], 'little'))

        # Prefill coinbase
        prefill = [{"index": 0, "tx": block.transactions[0].txid}]

        return {
            "header"    : block.header.to_dict(),
            "nonce"     : nonce,
            "short_ids" : short_ids,
            "prefill"   : prefill,
            "tx_count"  : len(block.transactions),
        }

    def reconstruct_block(self, compact: dict,
                           mempool_txs: Dict[str, 'Transaction']) -> Tuple[List['Transaction'], List[int]]:
        """
        Reconstruct block from compact block message.
        Returns (found_txs, missing_indices).
        """
        short_ids  = compact.get("short_ids", [])
        nonce      = compact.get("nonce", 0)
        found      = []
        missing    = []

        for i, short_id in enumerate(short_ids):
            found_tx = None
            # Match against mempool
            for txid, tx in mempool_txs.items():
                h = hashlib.sha256(txid.encode() + nonce.to_bytes(8,'big')).digest()
                if int.from_bytes(h[:6], 'little') == short_id:
                    found_tx = tx
                    break

            if found_tx:
                found.append(found_tx)
            else:
                missing.append(i + 1)  # +1 for coinbase offset

        return found, missing

    def bandwidth_saved(self, block_size: int, compact_size: int) -> str:
        if block_size == 0: return "0%"
        saved = (block_size - compact_size) / block_size * 100
        return f"{saved:.1f}%"


