def _script_int_to_bytes(n: int) -> bytes:
    if n == 0: return b''
    neg = n < 0
    n   = abs(n)
    result = []
    while n:
        result.append(n & 0xff)
        n >>= 8
    if result[-1] & 0x80:
        result.append(0x80 if neg else 0x00)
    elif neg:
        result[-1] |= 0x80
    return bytes(result)

def _bytes_to_script_int(b: bytes) -> int:
    if not b: return 0
    neg = bool(b[-1] & 0x80)
    result = int.from_bytes(bytes([b[-1] & 0x7f]) + b[:-1][::-1], 'big')
    return -result if neg else result

