import threading
from typing import List, Optional, Tuple, Dict
from dataclasses import dataclass, field

# ── Coin Selection Algorithms ─────────────────────────────────────
class CoinSelector:
    """
    Multiple coin selection algorithms.
    Goal: minimize fees + privacy + avoid change when possible.
    """

    @staticmethod
    def largest_first(utxos: List['UTXOEntry'],
                       target: int,
                       fee_rate: int = 1) -> Optional[List['UTXOEntry']]:
        """
        Select largest UTXOs first.
        Simple, predictable, may overshoot.
        """
        sorted_utxos = sorted(utxos, key=lambda u: u.value, reverse=True)
        selected = []
        total    = 0
        for u in sorted_utxos:
            selected.append(u)
            total += u.value
            est_fee = (len(selected) * 148 + 2 * 34 + 10) * fee_rate
            if total >= target + est_fee:
                return selected
        return None

    @staticmethod
    def smallest_first(utxos: List['UTXOEntry'],
                        target: int,
                        fee_rate: int = 1) -> Optional[List['UTXOEntry']]:
        """
        Select smallest UTXOs first (FIFO approximation).
        Consolidates dust, may use many inputs.
        """
        sorted_utxos = sorted(utxos, key=lambda u: u.value)
        selected = []
        total    = 0
        for u in sorted_utxos:
            selected.append(u)
            total += u.value
            est_fee = (len(selected) * 148 + 2 * 34 + 10) * fee_rate
            if total >= target + est_fee:
                return selected
        return None

    @staticmethod
    def branch_and_bound(utxos: List['UTXOEntry'],
                          target: int,
                          fee_rate: int = 1,
                          max_iters: int = 1000) -> Optional[List['UTXOEntry']]:
        """
        Branch-and-Bound coin selection (Bitcoin Core default).
        Tries to find exact match (no change output needed).
        Privacy-preserving: no change = no change address leakage.
        """
        target_with_fee = target + (148 + 34 + 10) * fee_rate
        utxos_sorted    = sorted(utxos, key=lambda u: u.value, reverse=True)
        n               = len(utxos_sorted)
        best            = None
        best_waste      = float('inf')

        def bnb(index: int, selected: List, current: int, iters: List):
            nonlocal best, best_waste
            if iters[0] > max_iters:
                return
            iters[0] += 1

            if current >= target_with_fee:
                waste = current - target_with_fee
                if waste < best_waste:
                    best_waste = waste
                    best       = selected[:]
                if waste == 0:
                    return  # exact match

            if index >= n:
                return

            # Include current UTXO
            selected.append(utxos_sorted[index])
            bnb(index + 1, selected, current + utxos_sorted[index].value, iters)
            selected.pop()

            # Skip current UTXO
            bnb(index + 1, selected, current, iters)

        bnb(0, [], 0, [0])
        return best

    @staticmethod
    def select(utxos: List['UTXOEntry'],
                target: int,
                fee_rate: int = 1,
                algorithm: str = "bnb") -> Optional[List['UTXOEntry']]:
        """Select UTXOs using chosen algorithm"""
        if algorithm == "bnb":
            result = CoinSelector.branch_and_bound(utxos, target, fee_rate)
            if result:
                return result
            # Fallback to largest-first
        if algorithm in ("bnb", "largest"):
            return CoinSelector.largest_first(utxos, target, fee_rate)
        if algorithm == "smallest":
            return CoinSelector.smallest_first(utxos, target, fee_rate)
        return CoinSelector.largest_first(utxos, target, fee_rate)


# ── Transaction Builder ───────────────────────────────────────────
@dataclass
class TxOutput_Planned:
    """Planned output for transaction builder"""
    address : str
    amount  : int   # in Neb
    script  : Optional[bytes] = None
    is_change: bool = False

class TxBuilder:
    """
    High-level transaction builder.
    Handles: UTXO selection, fee estimation, change address,
    input signing, dust avoidance.
    """

    DUST_LIMIT       = 546    # satoshis (dust threshold)
    DEFAULT_FEE_RATE = 10     # neb per byte

    def __init__(self, utxo_set: 'UTXOSet',
                 fee_estimator: 'FeeEstimator' = None):
        self.utxo_set      = utxo_set
        self.fee_estimator = fee_estimator
        self._inputs       : List['UTXOEntry'] = []
        self._outputs      : List[TxOutput_Planned] = []
        self._change_addr  : Optional[str] = None
        self._fee_rate     = self.DEFAULT_FEE_RATE
        self._locktime     = 0
        self._rbf          = True

    def add_output(self, address: str, amount_nbl: float) -> 'TxBuilder':
        """Add recipient output"""
        amount = int(amount_nbl * 10**DECIMALS)
        if amount < self.DUST_LIMIT:
            raise ValueError(f"Amount {amount} below dust limit {self.DUST_LIMIT}")
        self._outputs.append(TxOutput_Planned(address=address, amount=amount))
        return self

    def set_change_address(self, address: str) -> 'TxBuilder':
        self._change_addr = address
        return self

    def set_fee_rate(self, rate: int) -> 'TxBuilder':
        """Set fee rate in neb per byte"""
        self._fee_rate = max(1, rate)
        return self

    def set_locktime(self, locktime: int) -> 'TxBuilder':
        self._locktime = locktime
        return self

    def enable_rbf(self, enable: bool = True) -> 'TxBuilder':
        self._rbf = enable
        return self

    def estimate_size(self, n_inputs: int, n_outputs: int) -> int:
        """Estimate transaction size in bytes"""
        # Overhead: 10 bytes
        # Input: ~148 bytes (P2PKH)
        # Output: ~34 bytes
        return 10 + n_inputs * 148 + n_outputs * 34

    def estimate_fee(self, n_inputs: int, n_outputs: int) -> int:
        """Estimate fee for given input/output count"""
        size = self.estimate_size(n_inputs, n_outputs)
        return size * self._fee_rate

    def _select_inputs(self, target: int,
                        from_address: str) -> Tuple[List['UTXOEntry'], int]:
        """
        Select UTXOs to fund the transaction.
        Returns (selected_utxos, total_value).
        """
        available = self.utxo_set.get_by_address(from_address)
        # Filter out immature coinbase
        ch = getattr(self.utxo_set, '_chain_height', None)
        available = [u for u in available
                     if not u.is_coinbase or ch is None or
                     ch - u.height >= COINBASE_MATURITY]

        selected = CoinSelector.select(available, target, self._fee_rate)
        if not selected:
            return [], 0
        return selected, sum(u.value for u in selected)

    def build(self, from_address: str,
               privkey: int) -> Optional['Transaction']:
        """
        Build and sign transaction.
        Auto-selects UTXOs, computes fee, adds change output.
        """
        if not self._outputs:
            raise ValueError("No outputs specified")
        if not self._change_addr:
            self._change_addr = from_address

        total_out = sum(o.amount for o in self._outputs)

        # Estimate fee with 1 change output
        est_fee     = self.estimate_fee(2, len(self._outputs) + 1)
        target      = total_out + est_fee

        selected, total_in = self._select_inputs(target, from_address)
        if not selected:
            return None   # Insufficient funds

        # Recompute exact fee
        n_inputs   = len(selected)
        n_outputs  = len(self._outputs) + 1   # +1 for change
        exact_fee  = self.estimate_fee(n_inputs, n_outputs)
        change_val = total_in - total_out - exact_fee

        # If change is dust, add to fee instead
        if change_val < self.DUST_LIMIT:
            change_val = 0
            exact_fee  = total_in - total_out

        # Build inputs
        seq     = 0xFFFFFFFD if self._rbf else 0xFFFFFFFF
        inputs  = [
            TxInput(OutPoint(u.txid, u.index), b'', sequence=seq)
            for u in selected
        ]

        # Build outputs
        outputs = []
        for o in self._outputs:
            script = Script.p2pkh_locking_from_address(o.address)
            outputs.append(TxOutput(o.amount, script))

        # Add change output
        if change_val > 0:
            change_script = Script.p2pkh_locking_from_address(self._change_addr)
            outputs.append(TxOutput(change_val, change_script))

        tx = Transaction(inputs=inputs, outputs=outputs,
                          locktime=self._locktime)

        # Sign each input
        for i, utxo in enumerate(selected):
            locking = utxo.script_pubkey
            sighash = tx.signature_hash(i, locking, SIGHASH_ALL)
            r, s    = Secp256k1.sign(privkey, sighash)
            sig_der = Secp256k1.sig_to_der(r, s) + bytes([SIGHASH_ALL])
            pub     = Secp256k1.pubkey_to_bytes(
                          Secp256k1.point_mul(privkey, Secp256k1.G()))
            tx.inputs[i].script_sig = (
                bytes([len(sig_der)]) + sig_der +
                bytes([len(pub)]) + pub
            )

        return tx

    def summary(self, from_address: str) -> dict:
        """Preview transaction without building"""
        total_out    = sum(o.amount for o in self._outputs)
        est_fee      = self.estimate_fee(2, len(self._outputs) + 1)
        available    = self.utxo_set.balance(from_address)
        return {
            "from"           : from_address,
            "total_out_nbl"  : total_out / 10**DECIMALS,
            "estimated_fee"  : est_fee / 10**DECIMALS,
            "total_cost_nbl" : (total_out + est_fee) / 10**DECIMALS,
            "available_nbl"  : available / 10**DECIMALS,
            "can_afford"     : available >= total_out + est_fee,
            "fee_rate"       : self._fee_rate,
            "rbf_enabled"    : self._rbf,
            "outputs"        : [{"to": o.address, "nbl": o.amount/10**DECIMALS}
                                 for o in self._outputs],
        }

    @classmethod
    def simple_send(cls, from_addr: str, privkey: int,
                     to_addr: str, amount_nbl: float,
                     utxo_set: 'UTXOSet') -> Optional['Transaction']:
        """One-call simple send"""
        builder = cls(utxo_set)
        builder.add_output(to_addr, amount_nbl)
        builder.set_change_address(from_addr)
        return builder.build(from_addr, privkey)


