# ================================================================
# CLTV (OP_CHECKLOCKTIMEVERIFY) and CSV (OP_CHECKSEQUENCEVERIFY).
# Enables: vaults, escrow, payment channels, inheritance wallets.
# ================================================================

import time, threading
from typing import Optional, List, Tuple
from dataclasses import dataclass

# [v10.19] dead class TimelockParams removed from host - no live copy exists; original kept in nebula_removed_dead_classes.py

class TimelockScript:
    """
    Build timelocked scripts using CLTV and CSV.
    """

    @staticmethod
    def cltv_p2pkh(pubkey: bytes, locktime: int) -> bytes:
        """
        P2PKH with CLTV (absolute timelock).
        Script: <locktime> OP_CHECKLOCKTIMEVERIFY OP_DROP
                OP_DUP OP_HASH160 <pubkey_hash> OP_EQUALVERIFY OP_CHECKSIG
        """
        lt_bytes = _script_int_to_bytes(locktime)
        h160     = hashlib.new('ripemd160', hashlib.sha256(pubkey).digest()).digest()
        script   = (bytes([len(lt_bytes)]) + lt_bytes +
                    bytes([ScriptOpcode.OP_CHECKLOCKTIMEVERIFY,
                           ScriptOpcode.OP_DROP,
                           ScriptOpcode.OP_DUP,
                           ScriptOpcode.OP_HASH160,
                           len(h160)]) + h160 +
                    bytes([ScriptOpcode.OP_EQUALVERIFY,
                           ScriptOpcode.OP_CHECKSIG]))
        return script

    @staticmethod
    def csv_p2pkh(pubkey: bytes, sequence: int) -> bytes:
        """
        P2PKH with CSV (relative timelock).
        Script: <sequence> OP_CHECKSEQUENCEVERIFY OP_DROP ...
        """
        seq_bytes = _script_int_to_bytes(sequence)
        h160      = hashlib.new('ripemd160', hashlib.sha256(pubkey).digest()).digest()
        script    = (bytes([len(seq_bytes)]) + seq_bytes +
                     bytes([ScriptOpcode.OP_CHECKSEQUENCEVERIFY,
                            ScriptOpcode.OP_DROP,
                            ScriptOpcode.OP_DUP,
                            ScriptOpcode.OP_HASH160,
                            len(h160)]) + h160 +
                     bytes([ScriptOpcode.OP_EQUALVERIFY,
                            ScriptOpcode.OP_CHECKSIG]))
        return script

    @staticmethod
    def vault_script(owner_pk: bytes, heir_pk: bytes,
                      delay_blocks: int) -> bytes:
        """
        Inheritance vault: owner can spend anytime,
        heir can spend after delay_blocks CSV.
        Two spending paths:
          Path 1 (owner): OP_IF <owner_sig>
          Path 2 (heir):  OP_ELSE <delay> CSV <heir_sig>
        """
        delay_bytes = _script_int_to_bytes(delay_blocks)
        h160_owner  = hashlib.new('ripemd160', hashlib.sha256(owner_pk).digest()).digest()
        h160_heir   = hashlib.new('ripemd160', hashlib.sha256(heir_pk).digest()).digest()
        script = (
            bytes([ScriptOpcode.OP_IF,
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160,
                   len(h160_owner)]) + h160_owner +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ELSE,
                   len(delay_bytes)]) + delay_bytes +
            bytes([ScriptOpcode.OP_CHECKSEQUENCEVERIFY, ScriptOpcode.OP_DROP,
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160,
                   len(h160_heir)]) + h160_heir +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ENDIF])
        )
        return script

    @staticmethod
    def htlc_script(sender_pk: bytes, receiver_pk: bytes,
                     hash_preimage: bytes, timeout_blocks: int) -> bytes:
        """
        HTLC (Hash Time Lock Contract).
        Receiver can claim with: preimage + signature
        Sender can refund after: timeout_blocks
        Core primitive for Lightning Network channels.
        """
        payment_hash = hashlib.sha256(hash_preimage).digest()
        timeout_bytes = _script_int_to_bytes(timeout_blocks)
        h160_recv    = hashlib.new('ripemd160', hashlib.sha256(receiver_pk).digest()).digest()
        h160_send    = hashlib.new('ripemd160', hashlib.sha256(sender_pk).digest()).digest()

        script = (
            bytes([ScriptOpcode.OP_IF,
                   # Receiver path: OP_HASH256 <payment_hash> OP_EQUALVERIFY <sig>
                   ScriptOpcode.OP_HASH256,
                   len(payment_hash)]) + payment_hash +
            bytes([ScriptOpcode.OP_EQUALVERIFY,
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160,
                   len(h160_recv)]) + h160_recv +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ELSE,
                   # Sender refund path: <timeout> CSV <sig>
                   len(timeout_bytes)]) + timeout_bytes +
            bytes([ScriptOpcode.OP_CHECKSEQUENCEVERIFY, ScriptOpcode.OP_DROP,
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160,
                   len(h160_send)]) + h160_send +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ENDIF])
        )
        return script

