# ================================================================
# MODULE 39  nebula_protocol_upgrade.py  — Soft Fork + Version Bits
# ================================================================
# BIP9 version bits signaling, soft fork deployment tracking,
# activation logic, grace periods, taproot-style activation.
# ================================================================

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum

class DeploymentState(Enum):
    DEFINED   = "DEFINED"
    STARTED   = "STARTED"
    LOCKED_IN = "LOCKED_IN"
    ACTIVE    = "ACTIVE"
    FAILED    = "FAILED"

@dataclass
class SoftForkDeployment:
    """BIP9 soft fork deployment descriptor"""
    name            : str
    bit             : int       # version bit (0-28)
    start_time      : int       # Unix timestamp to start signaling
    timeout         : int       # Unix timestamp to timeout
    min_activation_height: int = 0
    threshold_pct   : float = 0.95    # 95% of blocks in window must signal
    window_size     : int   = 2016    # blocks per retarget period

    state           : DeploymentState = DeploymentState.DEFINED
    activation_height: Optional[int]  = None
    locked_in_height : Optional[int]  = None
    signal_count    : int = 0

    def signals(self, block_version: int) -> bool:
        return bool(block_version & (1 << self.bit))

    def threshold_count(self) -> int:
        return int(self.window_size * self.threshold_pct)

class VersionBitsState:
    """
    BIP9 version bits state machine.
    Tracks all soft fork deployments and their activation state.
    """

    def __init__(self):
        self._deployments : Dict[str, SoftForkDeployment] = {}
        self._lock        = threading.RLock()
        self._register_nebula_deployments()

    def _register_nebula_deployments(self):
        """Register all NEBULA protocol upgrades"""
        now = int(time.time())
        self._deployments = {
            "taproot": SoftForkDeployment(
                name="taproot", bit=2,
                start_time=now - 86400,
                timeout=now + 365*86400,
                state=DeploymentState.ACTIVE,
                activation_height=0,
            ),
            "segwit": SoftForkDeployment(
                name="segwit", bit=1,
                start_time=now - 86400,
                timeout=now + 365*86400,
                state=DeploymentState.ACTIVE,
                activation_height=0,
            ),
            "musig2": SoftForkDeployment(
                name="musig2", bit=3,
                start_time=now,
                timeout=now + 365*86400,
                state=DeploymentState.DEFINED,
            ),
            "graftroot": SoftForkDeployment(
                name="graftroot", bit=4,
                start_time=now + 30*86400,
                timeout=now + 365*86400,
                state=DeploymentState.DEFINED,
            ),
            "crossinput": SoftForkDeployment(
                name="crossinput", bit=5,
                start_time=now + 60*86400,
                timeout=now + 365*86400,
                state=DeploymentState.DEFINED,
            ),
        }

    def process_block(self, block: 'Block'):
        """Process block version bits for all deployments"""
        with self._lock:
            ts = block.header.timestamp
            for name, dep in self._deployments.items():
                if dep.state == DeploymentState.DEFINED:
                    if ts >= dep.start_time:
                        dep.state = DeploymentState.STARTED
                elif dep.state == DeploymentState.STARTED:
                    if ts >= dep.timeout:
                        dep.state = DeploymentState.FAILED
                    elif dep.signals(block.header.version):
                        dep.signal_count += 1
                        if dep.signal_count >= dep.threshold_count():
                            dep.state = DeploymentState.LOCKED_IN
                            dep.locked_in_height = block.height
                elif dep.state == DeploymentState.LOCKED_IN:
                    if (dep.locked_in_height and
                            block.height >= dep.locked_in_height + dep.window_size):
                        dep.state = DeploymentState.ACTIVE
                        dep.activation_height = block.height

    def is_active(self, name: str) -> bool:
        dep = self._deployments.get(name)
        return dep.state == DeploymentState.ACTIVE if dep else False

    def get_state(self, name: str) -> Optional[DeploymentState]:
        dep = self._deployments.get(name)
        return dep.state if dep else None

    def get_all_states(self) -> dict:
        with self._lock:
            return {
                name: {
                    "state"            : dep.state.value,
                    "bit"              : dep.bit,
                    "signal_count"     : dep.signal_count,
                    "threshold"        : dep.threshold_count(),
                    "activation_height": dep.activation_height,
                    "locked_in_height" : dep.locked_in_height,
                }
                for name, dep in self._deployments.items()
            }

    def compute_block_version(self) -> int:
        """Compute block version for new blocks"""
        version = 0x20000000  # BIP9 high bits
        with self._lock:
            for dep in self._deployments.values():
                if dep.state in (DeploymentState.STARTED,
                                  DeploymentState.LOCKED_IN):
                    version |= (1 << dep.bit)
        return version


# ================================================================
# MODULE 40  nebula_fee_bumper.py  — Fee Bumping (RBF + CPFP)
# ================================================================

class FeeBumper:
    """
    Automated fee bumping for stuck transactions.
    Two strategies: RBF (replace) or CPFP (child pays for parent).
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def rbf_bump(self, old_txid: str, privkey: int,
                  new_fee_rate: int, change_address: str = None) -> Optional['Transaction']:
        """
        Replace stuck transaction with higher fee (RBF).
        New tx spends same inputs with higher fee rate.
        """
        entry = (self.bc.mempool._txs.get(old_txid)
                 if hasattr(self.bc.mempool, '_txs') else None)
        if not entry:
            return None   # Not in mempool

        # v10.8: mempool._txs stores Transaction objects directly (no .tx wrapper)
        old_tx = entry.tx if hasattr(entry, 'tx') else entry
        if not old_tx or not old_tx.inputs:
            return None
        spent = [self.bc.utxo.get(i.outpoint.txid, i.outpoint.index) for i in old_tx.inputs]
        if any(u is None for u in spent):
            return None
        point   = Secp256k1.point_mul(privkey, Secp256k1.G())
        pub     = Secp256k1.pubkey_to_bytes(point)
        # the fee bump is taken from the CHANGE output: either the explicit change_address,
        # or (default) an output paying back to the signing key itself
        my_lock = Script.p2pkh_locking_from_address(
            change_address if change_address else Script.p2pkh_address(pub))
        size    = old_tx.byte_size()
        old_fee = old_tx.fee(self.bc.utxo)
        new_fee = max(int(new_fee_rate) * size, old_fee + size)   # BIP125: strictly higher
        extra   = new_fee - old_fee
        outs, paid = [], False
        for o in old_tx.outputs:
            if (not paid) and o.script_pubkey == my_lock:      # our change output pays the bump
                paid = True
                if o.value - extra >= DUST_THRESHOLD:
                    outs.append(TxOutput(value=o.value - extra, script_pubkey=o.script_pubkey))
                continue
            outs.append(TxOutput(value=o.value, script_pubkey=o.script_pubkey))
        if not paid:
            return None                                          # no change output to take the fee from
        ins = [TxInput(outpoint=OutPoint(i.outpoint.txid, i.outpoint.index),
                       script_sig=b'', sequence=i.sequence) for i in old_tx.inputs]
        new_tx = Transaction(version=old_tx.version, inputs=ins, outputs=outs)
        class _K:  # minimal key holder for the signing helper
            key, pubkey = privkey, point
        if not _v108_sign_p2pkh(new_tx, spent, [_K]):
            return None
        return new_tx

    def cpfp_bump(self, parent_txid: str, privkey: int,
                   child_fee_rate: int = 50) -> Optional['Transaction']:
        """
        Create child transaction to pay for stuck parent (CPFP).
        Child has high fee to pull parent above threshold.
        """
        # Find unspent output of parent tx we can spend
        for i in range(10):
            utxo = self.bc.utxo.get(parent_txid, i)
            if utxo:
                pub     = Secp256k1.pubkey_to_bytes(
                              Secp256k1.point_mul(privkey, Secp256k1.G()))
                addr    = Script.p2pkh_address(pub)
                builder = TxBuilder(self.bc.utxo)
                builder.set_fee_rate(child_fee_rate)
                # Send all to own address (just bumping fees)
                amt = (utxo.value - child_fee_rate * 300) / 10**DECIMALS
                if amt > 0:
                    builder.add_output(addr, amt)
                    builder.set_change_address(addr)
                    return builder.build(addr, privkey)
        return None

    def get_suggested_fee_rate(self, target_blocks: int = 3) -> int:
        """Get suggested fee rate to confirm in target_blocks"""
        if hasattr(self.bc.mempool, 'smart_fee'):
            return self.bc.mempool.smart_fee(target_blocks)
        return self.DEFAULT_FEE_RATE if hasattr(self, 'DEFAULT_FEE_RATE') else 10


