# ================================================================
# MODULE 42  nebula_covenant.py  — Output Covenants (OP_CTV)
# ================================================================
# OP_CHECKTEMPLATEVERIFY (BIP119): restrict how outputs can be spent.
# Enables: vaults, payment pools, inheritance, congestion control.

import hashlib, struct
from typing import List, Optional, Dict
from dataclasses import dataclass

class CheckTemplateVerify:
    """
    OP_CHECKTEMPLATEVERIFY (BIP119) implementation.
    Allows an output to restrict the template of the spending transaction.
    The "template hash" commits to: nVersion, nLocktime, vin count,
    sequences, vout count, outputs, input index.
    """

    @staticmethod
    def template_hash(tx: 'Transaction', input_index: int) -> bytes:
        """
        Compute CTV template hash for tx at input_index.
        This hash commits to everything in the tx EXCEPT scriptSigs/witnesses.
        """
        import struct
        h = hashlib.sha256()
        # nVersion
        h.update(struct.pack('<I', tx.version))
        # nLocktime
        h.update(struct.pack('<I', tx.locktime))
        # scriptSig hash (all empty for CTV)
        scriptsig_hash = hashlib.sha256(b'').digest()
        h.update(scriptsig_hash)
        # vin count
        h.update(struct.pack('<I', len(tx.inputs)))
        # sequences hash
        seq_h = hashlib.sha256()
        for inp in tx.inputs:
            seq_h.update(struct.pack('<I', inp.sequence))
        h.update(seq_h.digest())
        # vout count
        h.update(struct.pack('<I', len(tx.outputs)))
        # outputs hash
        out_h = hashlib.sha256()
        for out in tx.outputs:
            out_h.update(struct.pack('<q', out.value))
            out_h.update(bytes([len(out.script_pubkey)]) + out.script_pubkey)
        h.update(out_h.digest())
        # input index
        h.update(struct.pack('<I', input_index))
        return h.digest()

    @staticmethod
    def ctv_script(template_hash: bytes) -> bytes:
        """
        Script that enforces a spending template.
        Script: <template_hash> OP_CHECKTEMPLATEVERIFY
        OP_CTV = OP_NOP4 (0xb3) pending activation
        """
        return bytes([len(template_hash)]) + template_hash + bytes([0xb3])

    @classmethod
    def create_covenant(cls, spending_tx: 'Transaction',
                         input_index: int = 0) -> bytes:
        """
        Create a covenant that enforces spending_tx as the template.
        Any UTXO locked with this script can ONLY be spent by spending_tx.
        """
        h = cls.template_hash(spending_tx, input_index)
        return cls.ctv_script(h)

    @classmethod
    def verify(cls, covenant_script: bytes,
                spending_tx: 'Transaction',
                input_index: int) -> bool:
        """Verify spending tx matches covenant template"""
        if len(covenant_script) < 34:
            return False
        expected_hash = covenant_script[1:33]
        actual_hash   = cls.template_hash(spending_tx, input_index)
        return expected_hash == actual_hash

