# ================================================================
# MODULE 43  nebula_staking.py  — NBL Staking + Delegation
# ================================================================
# Hybrid PoW/PoS staking layer: stake NBL to earn yield,
# validator delegation, slashing conditions, unbonding periods.
# ================================================================

import threading, time, hashlib, secrets
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum

# ── Staking Constants ─────────────────────────────────────────────
STAKING_MIN_AMOUNT       = 10 * 10**DECIMALS    # 10 NBL minimum staking
STAKING_LOCK_PERIOD      = 2_016                   # ~2 weeks in blocks
STAKING_ANNUAL_YIELD_PCT = 5.0                     # 5% APY
STAKING_SLASH_PCT        = 0.10                    # 10% slash for misbehavior
STAKING_UNBONDING_BLOCKS = 1_008                   # ~1 week unbonding
STAKING_EPOCH_BLOCKS     = 144                     # 1 epoch = 1 day
MAX_VALIDATORS           = 100

class StakeStatus(Enum):
    ACTIVE    = "active"
    UNBONDING = "unbonding"
    SLASHED   = "slashed"
    WITHDRAWN = "withdrawn"

@dataclass
class StakeEntry:
    """A single staking position"""
    staker_address : str
    validator_addr : str
    amount         : int     # in Neb
    start_height   : int
    lock_until     : int     # block height
    status         : StakeStatus = StakeStatus.ACTIVE
    rewards_earned : int = 0
    slash_amount   : int = 0
    unbond_height  : Optional[int] = None

    @property
    def amount_nbl(self) -> float:
        return self.amount / 10**DECIMALS

    def is_locked(self, current_height: int) -> bool:
        return current_height < self.lock_until

    def calculate_reward(self, current_height: int) -> int:
        """Calculate pending reward based on elapsed blocks"""
        if self.status != StakeStatus.ACTIVE:
            return 0
        elapsed     = current_height - self.start_height
        blocks_year = 365 * 24 * 6   # ~52,560 blocks/year at 10min
        annual_rate = STAKING_ANNUAL_YIELD_PCT / 100
        reward      = int(self.amount * annual_rate * elapsed / blocks_year)
        return reward

    def to_dict(self) -> dict:
        return {
            "staker"     : self.staker_address,
            "validator"  : self.validator_addr,
            "amount_nbl" : self.amount_nbl,
            "start_height": self.start_height,
            "lock_until" : self.lock_until,
            "status"     : self.status.value,
            "rewards_nbl": self.rewards_earned / 10**DECIMALS,
        }

@dataclass
class Validator:
    """A NEBULA staking validator"""
    address       : str
    name          : str
    commission_pct: float = 5.0    # 5% validator commission
    total_staked  : int   = 0
    total_delegators: int = 0
    is_active     : bool  = True
    uptime_pct    : float = 100.0
    slash_count   : int   = 0
    self_stake    : int   = 0      # validator's own stake

    @property
    def total_staked_nbl(self) -> float:
        return self.total_staked / 10**DECIMALS

    @property
    def is_jailed(self) -> bool:
        return self.slash_count >= 3

    def to_dict(self) -> dict:
        return {
            "address"       : self.address,
            "name"          : self.name,
            "commission"    : f"{self.commission_pct:.1f}%",
            "total_staked"  : self.total_staked_nbl,
            "delegators"    : self.total_delegators,
            "uptime"        : f"{self.uptime_pct:.1f}%",
            "is_jailed"     : self.is_jailed,
            "self_stake"    : self.self_stake / 10**DECIMALS,
        }

class StakingEngine:
    """
    NEBULA Hybrid Staking Engine.
    Manages staking positions, validator set, reward distribution,
    slashing, and unbonding.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc          = blockchain
        self._stakes     : Dict[str, List[StakeEntry]] = {}
        self._validators : Dict[str, Validator] = {}
        self._lock       = threading.RLock()
        self._total_staked = 0
        self._epoch_rewards = 0

        # Register foundation as genesis validator
        self._validators[FOUNDATION_ADDRESS] = Validator(
            address     = FOUNDATION_ADDRESS,
            name        = "NEBULA Foundation",
            commission_pct = 0.0,
            is_active   = True,
            self_stake  = STAKING_MIN_AMOUNT * 10,
        )

    def register_validator(self, address: str, name: str,
                            commission_pct: float = 5.0,
                            self_stake: int = 0) -> Tuple[bool, str]:
        """Register a new validator"""
        if commission_pct < 0 or commission_pct > 100:
            return False, "Invalid commission"
        if len(self._validators) >= MAX_VALIDATORS:
            return False, "Validator set full"
        with self._lock:
            self._validators[address] = Validator(
                address        = address,
                name           = name,
                commission_pct = commission_pct,
                self_stake     = self_stake,
            )
            return True, f"Validator {name} registered"

    def stake(self, staker_addr: str, validator_addr: str,
               amount: int, lock_blocks: int = STAKING_LOCK_PERIOD,
               current_height: int = 0) -> Tuple[bool, str]:
        """Create a staking position"""
        if amount < STAKING_MIN_AMOUNT:
            return False, f"Below minimum stake: {STAKING_MIN_AMOUNT/10**DECIMALS} NBL"

        # Check balance
        bal = self.bc.utxo.balance(staker_addr)
        if bal < amount:
            return False, f"Insufficient balance: {bal/10**DECIMALS} NBL"

        val = self._validators.get(validator_addr)
        if not val:
            return False, "Validator not found"
        if val.is_jailed:
            return False, "Validator is jailed"

        with self._lock:
            entry = StakeEntry(
                staker_address = staker_addr,
                validator_addr = validator_addr,
                amount         = amount,
                start_height   = current_height,
                lock_until     = current_height + lock_blocks,
            )
            self._stakes.setdefault(staker_addr, []).append(entry)
            val.total_staked    += amount
            val.total_delegators += 1
            self._total_staked  += amount

        return True, f"Staked {amount/10**DECIMALS:.9f} NBL"

    def unstake(self, staker_addr: str, stake_index: int,
                 current_height: int) -> Tuple[bool, str]:
        """Begin unbonding for a stake position"""
        with self._lock:
            positions = self._stakes.get(staker_addr, [])
            if stake_index >= len(positions):
                return False, "Stake not found"

            pos = positions[stake_index]
            if pos.status != StakeStatus.ACTIVE:
                return False, f"Stake is {pos.status.value}"
            if pos.is_locked(current_height):
                blocks_left = pos.lock_until - current_height
                return False, f"Locked for {blocks_left} more blocks"

            pos.status        = StakeStatus.UNBONDING
            pos.unbond_height = current_height + STAKING_UNBONDING_BLOCKS
            return True, f"Unbonding starts, available at height {pos.unbond_height}"

    def claim_rewards(self, staker_addr: str,
                       current_height: int) -> int:
        """Calculate and claim pending staking rewards"""
        total_rewards = 0
        with self._lock:
            for pos in self._stakes.get(staker_addr, []):
                if pos.status == StakeStatus.ACTIVE:
                    reward = pos.calculate_reward(current_height)
                    # Apply validator commission
                    val = self._validators.get(pos.validator_addr)
                    if val:
                        commission = int(reward * val.commission_pct / 100)
                        reward    -= commission
                    pos.rewards_earned += reward
                    pos.start_height   = current_height   # reset
                    total_rewards      += reward
        return total_rewards

    def slash_validator(self, validator_addr: str,
                         reason: str = "double_sign") -> Tuple[bool, str]:
        """Slash a misbehaving validator"""
        with self._lock:
            val = self._validators.get(validator_addr)
            if not val:
                return False, "Validator not found"

            val.slash_count += 1
            slash_pct = STAKING_SLASH_PCT

            # Slash all delegators of this validator
            total_slashed = 0
            for staker_positions in self._stakes.values():
                for pos in staker_positions:
                    if (pos.validator_addr == validator_addr and
                            pos.status == StakeStatus.ACTIVE):
                        slash_amount    = int(pos.amount * slash_pct)
                        pos.amount     -= slash_amount
                        pos.slash_amount += slash_amount
                        total_slashed  += slash_amount

            if val.is_jailed:
                val.is_active = False

            return True, (f"Slashed {total_slashed/10**DECIMALS:.9f} NBL "
                          f"from {val.name} ({reason})")

    def process_epoch(self, current_height: int):
        """Process end-of-epoch: distribute rewards, handle unbonding"""
        if current_height % STAKING_EPOCH_BLOCKS != 0:
            return

        with self._lock:
            # Handle unbonding completions
            for addr, positions in self._stakes.items():
                for pos in positions:
                    if (pos.status == StakeStatus.UNBONDING and
                            pos.unbond_height and
                            current_height >= pos.unbond_height):
                        pos.status = StakeStatus.WITHDRAWN
                        val = self._validators.get(pos.validator_addr)
                        if val:
                            val.total_staked    = max(0, val.total_staked - pos.amount)
                            val.total_delegators = max(0, val.total_delegators - 1)

    def get_staker_info(self, address: str,
                         current_height: int) -> dict:
        """Get full staking info for an address"""
        positions = self._stakes.get(address, [])
        total_staked  = sum(p.amount for p in positions
                            if p.status == StakeStatus.ACTIVE)
        total_rewards = sum(p.calculate_reward(current_height)
                            for p in positions if p.status == StakeStatus.ACTIVE)
        return {
            "address"      : address,
            "total_staked" : total_staked / 10**DECIMALS,
            "positions"    : len(positions),
            "active"       : sum(1 for p in positions if p.status == StakeStatus.ACTIVE),
            "pending_rewards": total_rewards / 10**DECIMALS,
            "positions_detail": [p.to_dict() for p in positions],
        }

    def network_stats(self) -> dict:
        total_supply = self.bc.utxo.total_supply()
        staked_pct   = self._total_staked / max(1, total_supply) * 100
        return {
            "total_staked_nbl"  : self._total_staked / 10**DECIMALS,
            "staked_pct_supply" : f"{staked_pct:.2f}%",
            "active_validators" : sum(1 for v in self._validators.values()
                                      if v.is_active and not v.is_jailed),
            "total_validators"  : len(self._validators),
            "annual_yield_pct"  : STAKING_ANNUAL_YIELD_PCT,
        }

    def validator_list(self) -> List[dict]:
        with self._lock:
            return sorted([v.to_dict() for v in self._validators.values()],
                           key=lambda x: x["total_staked"], reverse=True)


# ================================================================
# MODULE 44  nebula_crosschain.py  — Atomic Swaps + Bridges
# ================================================================
# Cross-chain atomic swaps (HTLC-based), bridge contracts,
# peg-in/peg-out for wrapped assets.

import threading, time, secrets, hashlib
from typing import Dict, Optional, Tuple, List
from dataclasses import dataclass, field
from enum import Enum

class SwapState(Enum):
    INITIATED  = "initiated"
    FUNDED     = "funded"
    CLAIMED    = "claimed"
    REFUNDED   = "refunded"
    EXPIRED    = "expired"

@dataclass
class AtomicSwap:
    """
    HTLC-based atomic swap between NBL and another chain.
    Either both parties get their funds or neither does.
    No trusted third party required.
    """
    swap_id         : str
    initiator_addr  : str
    counterparty_addr: str
    amount_nbl      : int
    counterparty_amount: int
    counterparty_chain : str    # "BTC", "ETH", etc.
    payment_hash    : bytes
    preimage        : Optional[bytes] = None
    timeout_blocks  : int = 144
    state           : SwapState = SwapState.INITIATED
    created_at      : float = field(default_factory=time.time)
    funded_at       : Optional[float] = None
    claimed_at      : Optional[float] = None
    htlc_address    : Optional[str]   = None

    @property
    def is_expired(self) -> bool:
        age = time.time() - self.created_at
        return age > self.timeout_blocks * TARGET_BLOCK_TIME

    def to_dict(self) -> dict:
        return {
            "swap_id"        : self.swap_id,
            "initiator"      : self.initiator_addr,
            "counterparty"   : self.counterparty_addr,
            "amount_nbl"     : self.amount_nbl / 10**DECIMALS,
            "counterparty_amount": self.counterparty_amount,
            "chain"          : self.counterparty_chain,
            "payment_hash"   : self.payment_hash.hex(),
            "state"          : self.state.value,
            "has_preimage"   : self.preimage is not None,
            "timeout_blocks" : self.timeout_blocks,
        }

class AtomicSwapEngine:
    """
    Manages atomic cross-chain swaps for NEBULA.
    Protocol:
      1. Alice initiates: commits to HTLC hash, locks NBL
      2. Bob sees hash: locks counterparty funds on their chain
      3. Alice reveals preimage: claims Bob's funds
      4. Bob uses preimage: claims Alice's NBL
    If either party doesn't act within timeout: both get refund.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc      = blockchain
        self._swaps  : Dict[str, AtomicSwap] = {}
        self._lock   = threading.RLock()

    def initiate_swap(self, initiator_addr: str,
                       counterparty_addr: str,
                       amount_nbl: int,
                       counterparty_amount: int,
                       counterparty_chain: str,
                       timeout_blocks: int = 144) -> AtomicSwap:
        """Initiate a new atomic swap"""
        preimage     = secrets.token_bytes(32)
        payment_hash = hashlib.sha256(preimage).digest()
        swap_id      = payment_hash.hex()

        # Build HTLC script (safe: handle both valid NBL addresses and plain strings)
        try:
            _is = Script.p2pkh_locking_from_address(initiator_addr)[:20]
            _cs = Script.p2pkh_locking_from_address(counterparty_addr)[:20]
        except Exception:
            _is = hashlib.sha256(initiator_addr.encode()).digest()[:20]
            _cs = hashlib.sha256(counterparty_addr.encode()).digest()[:20]
        htlc_script = TimelockScript.htlc_script(_is, _cs, preimage, timeout_blocks)
        htlc_addr   = base58check_encode(
            hashlib.new("ripemd160", hashlib.sha256(htlc_script).digest()).digest(),
            SCRIPT_ADDRESS_VERSION)


        swap = AtomicSwap(
            swap_id            = swap_id,
            initiator_addr     = initiator_addr,
            counterparty_addr  = counterparty_addr,
            amount_nbl         = amount_nbl,
            counterparty_amount= counterparty_amount,
            counterparty_chain = counterparty_chain,
            payment_hash       = payment_hash,
            preimage           = preimage,
            timeout_blocks     = timeout_blocks,
            htlc_address       = htlc_addr,
        )

        with self._lock:
            self._swaps[swap_id] = swap

        return swap

    def fund_swap(self, swap_id: str) -> Tuple[bool, str]:
        """Mark swap as funded (NBL locked in HTLC)"""
        with self._lock:
            swap = self._swaps.get(swap_id)
            if not swap:
                return False, "Swap not found"
            swap.state    = SwapState.FUNDED
            swap.funded_at = time.time()
            return True, f"Swap funded: {swap.amount_nbl/10**DECIMALS} NBL locked"

    def claim_swap(self, swap_id: str,
                    preimage: bytes) -> Tuple[bool, str]:
        """Claim swap by revealing preimage"""
        with self._lock:
            swap = self._swaps.get(swap_id)
            if not swap:
                return False, "Swap not found"
            if swap.is_expired:
                swap.state = SwapState.EXPIRED
                return False, "Swap expired"
            if hashlib.sha256(preimage).digest() != swap.payment_hash:
                return False, "Invalid preimage"
            swap.state      = SwapState.CLAIMED
            swap.claimed_at = time.time()
            return True, f"Swap claimed successfully"

    def refund_swap(self, swap_id: str) -> Tuple[bool, str]:
        """Refund expired swap"""
        with self._lock:
            swap = self._swaps.get(swap_id)
            if not swap:
                return False, "Swap not found"
            if not swap.is_expired:
                return False, "Swap not yet expired"
            swap.state = SwapState.REFUNDED
            return True, f"Swap refunded: {swap.amount_nbl/10**DECIMALS} NBL"

    def list_swaps(self, address: str = None) -> List[dict]:
        with self._lock:
            swaps = list(self._swaps.values())
            if address:
                swaps = [s for s in swaps
                         if s.initiator_addr == address or
                         s.counterparty_addr == address]
            return [s.to_dict() for s in swaps]

    def stats(self) -> dict:
        with self._lock:
            by_state = {}
            for s in self._swaps.values():
                by_state[s.state.value] = by_state.get(s.state.value, 0) + 1
            return {
                "total_swaps"  : len(self._swaps),
                "by_state"     : by_state,
                "chains"       : list(set(s.counterparty_chain
                                         for s in self._swaps.values())),
            }


# ================================================================
# MODULE 45  nebula_oracle.py  — On-Chain Price Oracle
# ================================================================
# Decentralized price oracle for NBL/USD, NBL/BTC,
# multi-source aggregation, median filtering, TWAP.

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from statistics import median

# ── Oracle Constants ──────────────────────────────────────────────
ORACLE_UPDATE_INTERVAL  = 600    # seconds
ORACLE_MIN_SOURCES      = 3      # minimum data sources for validity
ORACLE_MAX_AGE_SECS     = 3600   # max age of price data
ORACLE_DECIMALS         = 8      # price precision

@dataclass
class PriceFeed:
    """A single price data point from one oracle source"""
    source    : str
    pair      : str    # e.g. "NBL/USD"
    price     : int    # price * 10^ORACLE_DECIMALS
    timestamp : float  = field(default_factory=time.time)
    confidence: float  = 1.0     # 0-1 confidence score

    @property
    def price_float(self) -> float:
        return self.price / 10**ORACLE_DECIMALS

    @property
    def is_fresh(self) -> bool:
        return time.time() - self.timestamp < ORACLE_MAX_AGE_SECS

    def to_dict(self) -> dict:
        return {
            "source"    : self.source,
            "pair"      : self.pair,
            "price"     : self.price_float,
            "timestamp" : self.timestamp,
            "age_secs"  : round(time.time() - self.timestamp),
            "fresh"     : self.is_fresh,
        }

class PriceAggregator:
    """
    Aggregates price feeds from multiple sources.
    Uses median (not mean) to resist price manipulation.
    Implements TWAP (Time-Weighted Average Price) for stability.
    """

    def __init__(self):
        self._feeds   : Dict[str, Dict[str, PriceFeed]] = {}
        self._history : Dict[str, List[Tuple[float, int]]] = {}
        self._lock    = threading.RLock()

    def submit_price(self, source: str, pair: str, price: int,
                      confidence: float = 1.0):
        """Submit price from oracle source"""
        feed = PriceFeed(source=source, pair=pair, price=price,
                          confidence=confidence)
        with self._lock:
            self._feeds.setdefault(pair, {})[source] = feed
            hist = self._history.setdefault(pair, [])
            hist.append((time.time(), price))
            # Keep only last 24h
            cutoff = time.time() - 86400
            self._history[pair] = [(t,p) for t,p in hist if t > cutoff]

    def get_median_price(self, pair: str) -> Optional[int]:
        """Get median price from all fresh sources"""
        with self._lock:
            feeds = self._feeds.get(pair, {})
            fresh = [f.price for f in feeds.values()
                     if f.is_fresh and f.confidence >= 0.5]
            if len(fresh) < ORACLE_MIN_SOURCES:
                return None
            return int(median(fresh))

    def get_twap(self, pair: str,
                  window_secs: int = 3600) -> Optional[float]:
        """
        Time-Weighted Average Price over window_secs.
        More resistant to short-term manipulation than spot price.
        """
        with self._lock:
            hist = self._history.get(pair, [])
            cutoff = time.time() - window_secs
            window = [(t, p) for t, p in hist if t > cutoff]
            if not window:
                return None
            # Weighted by time between samples
            if len(window) == 1:
                return window[0][1] / 10**ORACLE_DECIMALS
            total_weight = 0.0
            weighted_sum = 0.0
            for i in range(1, len(window)):
                dt            = window[i][0] - window[i-1][0]
                weighted_sum += window[i-1][1] * dt
                total_weight += dt
            if total_weight == 0:
                return None
            return (weighted_sum / total_weight) / 10**ORACLE_DECIMALS

    def get_price_report(self, pair: str) -> dict:
        spot  = self.get_median_price(pair)
        twap  = self.get_twap(pair, 3600)
        with self._lock:
            sources = len(self._feeds.get(pair, {}))
        return {
            "pair"          : pair,
            "spot_price"    : spot / 10**ORACLE_DECIMALS if spot else None,
            "twap_1h"       : twap,
            "sources"       : sources,
            "valid"         : spot is not None,
            "timestamp"     : time.time(),
        }

class PriceOracle:
    """
    NEBULA on-chain price oracle.
    Aggregates prices from multiple DEX + CEX sources.
    """

    PAIRS = ["NBL/USD", "NBL/BTC", "NBL/ETH", "NBL/USDT"]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc          = blockchain
        self.aggregator  = PriceAggregator()
        self._running    = False
        self._thread     : Optional[threading.Thread] = None
        self._last_block_oracle_height = 0

        # Seed with initial prices
        self._seed_prices()

    # ── Real price feed sources ───────────────────────────────────
    # NBL is not yet listed on centralised exchanges.
    # We fetch BTC/ETH/USDT prices from CoinGecko (free, no key) to
    # anchor our USD oracle, and keep a configurable NBL/BTC seed rate
    # that operators update manually until CEX listing.
    # Set NEBULA_NBL_BTC_RATE env var to override (e.g. "0.0000030").

    _COINGECKO_URL = (
        "https://api.coingecko.com/api/v3/simple/price"
        "?ids=bitcoin,ethereum,tether"
        "&vs_currencies=usd"
    )

    def _fetch_reference_prices(self) -> dict:
        """
        Fetch BTC/ETH/USDT prices in USD from CoinGecko (free tier).
        Returns dict like {"btc_usd": 65000.0, "eth_usd": 3200.0}.
        Raises on network/parse error — caller handles gracefully.
        """
        import urllib.request, os
        req = urllib.request.Request(
            self._COINGECKO_URL,
            headers={"User-Agent": "NEBULA-Blockchain/1.0"},
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read())
        return {
            "btc_usd": float(data["bitcoin"]["usd"]),
            "eth_usd": float(data["ethereum"]["usd"]),
        }

    def _get_nbl_btc_rate(self) -> float:
        """
        Return NBL/BTC rate.
        Source priority:
          1. NEBULA_NBL_BTC_RATE env var  (operator-set)
          2. Internal DEX aggregator last known value
          3. Hard default 0.0000025 (pre-listing placeholder)
        """
        import os
        env_rate = os.environ.get("NEBULA_NBL_BTC_RATE", "")
        if env_rate:
            try:
                return float(env_rate)
            except ValueError:
                _NB_SWALLOW_LOG.debug("swallowed ValueError in PriceOracle._get_nbl_btc_rate", exc_info=True)
        # Try internal DEX price if available
        dex_price = self.aggregator.get_median_price("NBL/BTC")
        if dex_price:
            return dex_price / 10 ** ORACLE_DECIMALS
        return 0.0000025   # pre-listing default

    def _seed_prices(self):
        """
        Seed oracle with real reference prices on startup.
        Fetches BTC/ETH from CoinGecko; derives NBL pairs.
        Falls back to conservative static values if network unavailable.
        """
        nbl_btc = self._get_nbl_btc_rate()
        try:
            ref = self._fetch_reference_prices()
            btc_usd = ref["btc_usd"]
            eth_usd = ref["eth_usd"]
            log.info(f"PriceOracle seed: BTC=${btc_usd:,.0f} ETH=${eth_usd:,.0f}")
        except Exception as e:
            log.warning(f"PriceOracle CoinGecko seed failed ({e}), using static fallback")
            btc_usd = 65_000.0
            eth_usd = 3_200.0

        nbl_usd  = nbl_btc * btc_usd
        nbl_eth  = nbl_btc * (btc_usd / eth_usd) if eth_usd else 0.0
        nbl_usdt = nbl_usd   # USDT ≈ USD

        base_prices = {
            "NBL/USD" : int(nbl_usd  * 10 ** ORACLE_DECIMALS),
            "NBL/BTC" : int(nbl_btc  * 10 ** ORACLE_DECIMALS),
            "NBL/ETH" : int(nbl_eth  * 10 ** ORACLE_DECIMALS),
            "NBL/USDT": int(nbl_usdt * 10 ** ORACLE_DECIMALS),
        }
        for pair, price in base_prices.items():
            self.aggregator.submit_price("coingecko_derived", pair, price)
        log.info(f"PriceOracle seeded: NBL/USD≈${nbl_usd:.6f}")

    def update_prices(self):
        """
        Fetch live reference prices from CoinGecko and update oracle.
        Called by _update_loop every 60 s.
        On failure, logs warning and skips (keeps last known values).
        """
        import urllib.request
        nbl_btc = self._get_nbl_btc_rate()
        try:
            ref = self._fetch_reference_prices()
            btc_usd = ref["btc_usd"]
            eth_usd = ref["eth_usd"]
        except Exception as e:
            log.warning(f"PriceOracle update failed: {e} — keeping last values")
            return

        nbl_usd  = nbl_btc * btc_usd
        nbl_eth  = nbl_btc * (btc_usd / eth_usd) if eth_usd else 0.0

        updates = {
            "NBL/USD" : int(nbl_usd  * 10 ** ORACLE_DECIMALS),
            "NBL/BTC" : int(nbl_btc  * 10 ** ORACLE_DECIMALS),
            "NBL/ETH" : int(nbl_eth  * 10 ** ORACLE_DECIMALS),
            "NBL/USDT": int(nbl_usd  * 10 ** ORACLE_DECIMALS),
        }
        for pair, price in updates.items():
            self.aggregator.submit_price("coingecko_live", pair, price)
        log.debug(f"PriceOracle updated: NBL/USD≈${nbl_usd:.6f} (BTC=${btc_usd:,.0f})")

    def get_nbl_usd(self) -> Optional[float]:
        """Get NBL/USD spot price"""
        price = self.aggregator.get_median_price("NBL/USD")
        return price / 10**ORACLE_DECIMALS if price else None

    def get_nbl_btc(self) -> Optional[float]:
        price = self.aggregator.get_median_price("NBL/BTC")
        return price / 10**ORACLE_DECIMALS if price else None

    def nbl_to_usd(self, amount_nbl: float) -> Optional[float]:
        rate = self.get_nbl_usd()
        return amount_nbl * rate if rate else None

    def usd_to_nbl(self, amount_usd: float) -> Optional[float]:
        rate = self.get_nbl_usd()
        return amount_usd / rate if rate else None

    def price_summary(self) -> dict:
        self.update_prices()
        return {pair: self.aggregator.get_price_report(pair)
                for pair in self.PAIRS}

    def start(self):
        self._running = True
        self._thread  = threading.Thread(
            target=self._update_loop, daemon=True, name="Oracle")
        self._thread.start()

    def _update_loop(self):
        while self._running:
            try:
                self.update_prices()
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in PriceOracle._update_loop", exc_info=True)
            time.sleep(ORACLE_UPDATE_INTERVAL)

    def stop(self):
        self._running = False


# ================================================================
# MODULE 46  nebula_defi.py  — DeFi Primitives (AMM + Lending)
# ================================================================
# Automated Market Maker (Uniswap V2 style), lending protocol,
# liquidity pools, yield farming — fully on-chain NBL DeFi.

import threading, time, math
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field

# ── AMM Constants ─────────────────────────────────────────────────
AMM_FEE_NUMERATOR   = 3
AMM_FEE_DENOMINATOR = 1000   # 0.3% fee
MIN_LIQUIDITY       = 1000   # minimum LP tokens
LENDING_LTV_PCT     = 0.75   # 75% loan-to-value
LENDING_LIQD_PCT    = 0.80   # 80% liquidation threshold
LENDING_INTEREST_DAILY = 0.0005  # 0.05% daily rate

@dataclass
class LiquidityPool:
    """
    Constant-product AMM pool (x * y = k).
    Enables decentralized token swaps without order book.
    """
    token_a     : str    # address or "NBL"
    token_b     : str
    reserve_a   : int = 0
    reserve_b   : int = 0
    total_lp    : int = 0
    fee_a       : int = 0   # accumulated fees
    fee_b       : int = 0
    lp_holders  : Dict[str, int] = field(default_factory=dict)

    @property
    def k(self) -> int:
        """Invariant x * y = k"""
        return self.reserve_a * self.reserve_b

    @property
    def price_a_in_b(self) -> float:
        """Price of token_a in terms of token_b"""
        if self.reserve_a == 0:
            return 0.0
        return self.reserve_b / self.reserve_a

    @property
    def price_b_in_a(self) -> float:
        if self.reserve_b == 0:
            return 0.0
        return self.reserve_a / self.reserve_b

    def get_amount_out(self, amount_in: int, is_a_in: bool) -> int:
        """
        Constant product formula with fee.
        amount_out = (amount_in * (1-fee) * reserve_out) /
                     (reserve_in + amount_in * (1-fee))
        """
        if is_a_in:
            reserve_in, reserve_out = self.reserve_a, self.reserve_b
        else:
            reserve_in, reserve_out = self.reserve_b, self.reserve_a

        amount_in_with_fee = amount_in * (AMM_FEE_DENOMINATOR - AMM_FEE_NUMERATOR)
        numerator          = amount_in_with_fee * reserve_out
        denominator        = reserve_in * AMM_FEE_DENOMINATOR + amount_in_with_fee
        return numerator // denominator if denominator > 0 else 0

    def get_price_impact(self, amount_in: int, is_a_in: bool) -> float:
        """Price impact % of a swap"""
        amount_out = self.get_amount_out(amount_in, is_a_in)
        if amount_out == 0:
            return 100.0
        spot_out = (amount_in * (self.reserve_b if is_a_in else self.reserve_a)
                    // max(1, self.reserve_a if is_a_in else self.reserve_b))
        impact = (spot_out - amount_out) / max(1, spot_out) * 100
        return round(impact, 4)

    def quote_add_liquidity(self, amount_a: int) -> int:
        """How much token_b needed to add amount_a liquidity"""
        if self.reserve_a == 0:
            return amount_a
        return amount_a * self.reserve_b // self.reserve_a

    def lp_share(self, holder: str) -> float:
        """LP token share for holder"""
        held = self.lp_holders.get(holder, 0)
        return held / max(1, self.total_lp)

    def to_dict(self) -> dict:
        return {
            "pair"        : f"{self.token_a}/{self.token_b}",
            "reserve_a"   : self.reserve_a / 10**DECIMALS,
            "reserve_b"   : self.reserve_b / 10**DECIMALS,
            "price"       : round(self.price_a_in_b, 6),
            "total_lp"    : self.total_lp,
            "tvl_nbl"     : (self.reserve_a + self.reserve_b) / 10**DECIMALS,
        }

class AMMEngine:
    """
    NEBULA Automated Market Maker.
    Manages multiple liquidity pools and swap routing.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc     = blockchain
        self._pools : Dict[str, LiquidityPool] = {}
        self._lock  = threading.RLock()

    def _pool_id(self, token_a: str, token_b: str) -> str:
        tokens = sorted([token_a, token_b])
        return f"{tokens[0]}/{tokens[1]}"

    def create_pool(self, token_a: str, token_b: str) -> str:
        """Create a new liquidity pool"""
        pid = self._pool_id(token_a, token_b)
        with self._lock:
            if pid not in self._pools:
                self._pools[pid] = LiquidityPool(token_a=token_a, token_b=token_b)
        return pid

    def add_liquidity(self, provider: str, token_a: str, token_b: str,
                       amount_a: int, amount_b: int) -> Tuple[int, str]:
        """
        Add liquidity to a pool.
        Returns (LP tokens minted, pool_id).
        """
        pid  = self._pool_id(token_a, token_b)
        pool = self._pools.get(pid)
        if not pool:
            pid  = self.create_pool(token_a, token_b)
            pool = self._pools[pid]

        with self._lock:
            if pool.total_lp == 0:
                # Initial liquidity: LP = sqrt(a * b) - MIN_LIQUIDITY
                lp = max(0, int(math.sqrt(amount_a * amount_b)) - MIN_LIQUIDITY)
                pool.reserve_a = amount_a
                pool.reserve_b = amount_b
            else:
                # Proportional liquidity
                lp_from_a = amount_a * pool.total_lp // max(1, pool.reserve_a)
                lp_from_b = amount_b * pool.total_lp // max(1, pool.reserve_b)
                lp        = min(lp_from_a, lp_from_b)
                pool.reserve_a += amount_a
                pool.reserve_b += amount_b

            pool.total_lp                 += lp
            pool.lp_holders[provider]      = pool.lp_holders.get(provider, 0) + lp
            return lp, pid

    def remove_liquidity(self, provider: str, pool_id: str,
                          lp_amount: int) -> Tuple[int, int]:
        """
        Remove liquidity from pool.
        Returns (amount_a, amount_b) returned to provider.
        """
        pool = self._pools.get(pool_id)
        if not pool:
            return 0, 0

        with self._lock:
            held = pool.lp_holders.get(provider, 0)
            lp   = min(lp_amount, held)
            if lp == 0:
                return 0, 0

            share    = lp / max(1, pool.total_lp)
            amount_a = int(pool.reserve_a * share)
            amount_b = int(pool.reserve_b * share)

            pool.reserve_a        -= amount_a
            pool.reserve_b        -= amount_b
            pool.total_lp         -= lp
            pool.lp_holders[provider] = held - lp
            return amount_a, amount_b

    def swap(self, trader: str, token_in: str, token_out: str,
              amount_in: int, slippage_pct: float = 1.0) -> Tuple[int, str]:
        """
        Swap tokens through AMM.
        Returns (amount_out, pool_id).
        """
        pid  = self._pool_id(token_in, token_out)
        pool = self._pools.get(pid)
        if not pool:
            return 0, "Pool not found"

        is_a_in = token_in == pool.token_a
        amount_out = pool.get_amount_out(amount_in, is_a_in)

        min_out = int(amount_out * (1 - slippage_pct/100))
        if amount_out < min_out:
            return 0, "Slippage exceeded"

        with self._lock:
            fee = amount_in * AMM_FEE_NUMERATOR // AMM_FEE_DENOMINATOR
            if is_a_in:
                pool.reserve_a += amount_in
                pool.reserve_b -= amount_out
                pool.fee_a     += fee
            else:
                pool.reserve_b += amount_in
                pool.reserve_a -= amount_out
                pool.fee_b     += fee

        return amount_out, pid

    def get_quote(self, token_in: str, token_out: str,
                   amount_in: int) -> dict:
        """Get swap quote without executing"""
        pid  = self._pool_id(token_in, token_out)
        pool = self._pools.get(pid)
        if not pool:
            return {"error": "Pool not found"}
        is_a_in    = token_in == pool.token_a
        amount_out = pool.get_amount_out(amount_in, is_a_in)
        impact     = pool.get_price_impact(amount_in, is_a_in)
        return {
            "amount_in"    : amount_in / 10**DECIMALS,
            "amount_out"   : amount_out / 10**DECIMALS,
            "price_impact" : f"{impact:.4f}%",
            "fee"          : amount_in * AMM_FEE_NUMERATOR / AMM_FEE_DENOMINATOR / 10**DECIMALS,
            "pool"         : pid,
            "pool_data"    : pool.to_dict(),
        }

    def pools_summary(self) -> List[dict]:
        return [pool.to_dict() for pool in self._pools.values()]

    def total_tvl(self) -> float:
        """Total Value Locked in all pools"""
        return sum(
            (p.reserve_a + p.reserve_b) / 10**DECIMALS
            for p in self._pools.values()
            if "NBL" in (p.token_a, p.token_b)
        )

@dataclass
class LendingPosition:
    """A lending/borrowing position"""
    borrower     : str
    collateral   : int    # collateral in Neb
    loan_amount  : int    # borrowed amount
    interest_rate: float
    created_at   : float = field(default_factory=time.time)
    last_interest : float = field(default_factory=time.time)
    is_liquidated : bool = False

    @property
    def collateral_ratio(self) -> float:
        return self.collateral / max(1, self.loan_amount)

    @property
    def is_undercollateralized(self) -> bool:
        return self.collateral_ratio < LENDING_LIQD_PCT

    def accrue_interest(self) -> int:
        """Calculate interest since last accrual"""
        dt      = time.time() - self.last_interest
        days    = dt / 86400
        interest = int(self.loan_amount * self.interest_rate * days)
        self.loan_amount  += interest
        self.last_interest = time.time()
        return interest

class LendingProtocol:
    """
    NEBULA decentralized lending protocol.
    Borrow NBL against NBL collateral (or future token collateral).
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc        = blockchain
        self._positions: Dict[str, LendingPosition] = {}
        self._pool     = 0    # total lending pool
        self._borrowed = 0    # total borrowed
        self._lock     = threading.RLock()

    def deposit(self, lender: str, amount: int) -> bool:
        """Deposit NBL into lending pool"""
        bal = self.bc.utxo.balance(lender)
        if bal < amount:
            return False
        with self._lock:
            self._pool += amount
        return True

    def borrow(self, borrower: str, collateral: int,
                borrow_amount: int) -> Tuple[bool, str]:
        """Borrow NBL against collateral"""
        if collateral < borrow_amount / LENDING_LTV_PCT:
            return False, f"Insufficient collateral (need {borrow_amount/LENDING_LTV_PCT:.0f})"
        if borrow_amount > self._pool - self._borrowed:
            return False, "Insufficient pool liquidity"

        with self._lock:
            pos_id = f"{borrower}_{int(time.time())}"
            self._positions[pos_id] = LendingPosition(
                borrower     = borrower,
                collateral   = collateral,
                loan_amount  = borrow_amount,
                interest_rate= LENDING_INTEREST_DAILY,
            )
            self._borrowed += borrow_amount
        return True, pos_id

    def repay(self, pos_id: str, amount: int) -> Tuple[bool, int]:
        """Repay loan and recover collateral"""
        with self._lock:
            pos = self._positions.get(pos_id)
            if not pos:
                return False, 0
            pos.accrue_interest()
            actual_repay = min(amount, pos.loan_amount)
            pos.loan_amount  -= actual_repay
            self._borrowed   -= actual_repay
            if pos.loan_amount == 0:
                collateral_returned = pos.collateral
                del self._positions[pos_id]
                return True, collateral_returned
            return True, 0

    def liquidate(self, pos_id: str) -> Tuple[bool, str]:
        """Liquidate undercollateralized position"""
        with self._lock:
            pos = self._positions.get(pos_id)
            if not pos:
                return False, "Position not found"
            pos.accrue_interest()
            if not pos.is_undercollateralized:
                return False, "Position is adequately collateralized"
            # Liquidate: seize collateral, write off loan
            seized      = pos.collateral
            pos.is_liquidated = True
            del self._positions[pos_id]
            self._borrowed = max(0, self._borrowed - pos.loan_amount)
            return True, f"Liquidated: seized {seized/10**DECIMALS:.9f} NBL"

    def stats(self) -> dict:
        utilization = self._borrowed / max(1, self._pool) * 100
        return {
            "total_pool"   : self._pool / 10**DECIMALS,
            "total_borrowed": self._borrowed / 10**DECIMALS,
            "utilization"  : f"{utilization:.2f}%",
            "positions"    : len(self._positions),
            "daily_rate"   : f"{LENDING_INTEREST_DAILY*100:.4f}%",
            "ltv"          : f"{LENDING_LTV_PCT*100:.0f}%",
        }

