# ================================================================
# MODULE 47  nebula_p2p_messaging.py  — Encrypted P2P Messaging
# ================================================================
# Encrypted peer-to-peer messages on NEBULA network.
# Use blockchain as message bus: store messages as OP_RETURN data.
# Messages encrypted with recipient's public key (ECIES).

import hashlib, os, threading, time, struct, secrets
from typing import Dict, List, Optional, Tuple

# ── ECIES Encryption ─────────────────────────────────────────────
class ECIES:
    """
    Elliptic Curve Integrated Encryption Scheme.
    Encrypt data to recipient's public key using:
    - ECDH key agreement
    - HKDF key derivation
    - AES-256-GCM authenticated encryption
    """

    @classmethod
    def encrypt(cls, message: bytes, recipient_pubkey: bytes) -> bytes:
        """
        Encrypt message to recipient.
        Returns: ephemeral_pubkey (33B) + ciphertext
        """
        # Generate ephemeral keypair
        eph_privkey = int.from_bytes(secrets.token_bytes(32), 'big') % Secp256k1.N
        eph_pubkey  = Secp256k1.pubkey_to_bytes(
                          Secp256k1.point_mul(eph_privkey, Secp256k1.G()))

        # Decode recipient pubkey and ECDH
        rec_x   = int.from_bytes(recipient_pubkey[1:], 'big')
        rec_P   = Schnorr.P
        rec_ys  = (pow(rec_x, 3, rec_P) + 7) % rec_P
        rec_y   = pow(rec_ys, (rec_P+1)//4, rec_P)
        if (rec_y % 2 == 0) != (recipient_pubkey[0] == 0x02):
            rec_y = rec_P - rec_y
        rec_point = (rec_x, rec_y)

        shared_point = Schnorr._point_mul(eph_privkey, rec_point)
        if shared_point is None:
            raise ValueError("ECDH failed")

        # Derive keys via HKDF-SHA256
        shared_secret = shared_point[0].to_bytes(32, 'big')
        okm = hashlib.sha256(shared_secret + eph_pubkey).digest()
        enc_key = okm[:16]
        mac_key = okm[16:]

        # Simple AES-CTR encryption (using XOR with keystream for portability)
        iv    = secrets.token_bytes(12)
        ks    = cls._keystream(enc_key + iv, len(message))
        ct    = bytes(a ^ b for a, b in zip(message, ks))

        # MAC
        mac   = hashlib.sha256(mac_key + iv + ct).digest()[:16]
        return eph_pubkey + iv + mac + ct

    @classmethod
    def decrypt(cls, data: bytes, privkey: int) -> Optional[bytes]:
        """Decrypt ECIES message with private key"""
        try:
            eph_pubkey = data[:33]
            iv         = data[33:45]
            mac        = data[45:61]
            ct         = data[61:]

            # ECDH
            eph_x   = int.from_bytes(eph_pubkey[1:], 'big')
            rec_P   = Schnorr.P
            eph_ys  = (pow(eph_x, 3, rec_P) + 7) % rec_P
            eph_y   = pow(eph_ys, (rec_P+1)//4, rec_P)
            if (eph_y % 2 == 0) != (eph_pubkey[0] == 0x02):
                eph_y = rec_P - eph_y
            eph_point     = (eph_x, eph_y)
            shared_point  = Schnorr._point_mul(privkey, eph_point)
            if shared_point is None:
                return None

            shared_secret = shared_point[0].to_bytes(32, 'big')
            okm     = hashlib.sha256(shared_secret + eph_pubkey).digest()
            enc_key = okm[:16]
            mac_key = okm[16:]

            # Verify MAC
            expected_mac = hashlib.sha256(mac_key + iv + ct).digest()[:16]
            if expected_mac != mac:
                return None   # Authentication failure

            # Decrypt
            ks = cls._keystream(enc_key + iv, len(ct))
            return bytes(a ^ b for a, b in zip(ct, ks))
        except Exception:
            return None

    @staticmethod
    def _keystream(key_iv: bytes, length: int) -> bytes:
        """AES-like keystream using SHA-256 counter mode"""
        result = b''
        counter = 0
        while len(result) < length:
            block = hashlib.sha256(key_iv + counter.to_bytes(4, 'big')).digest()
            result += block
            counter += 1
        return result[:length]

