# ================================================================
# MODULE 48  nebula_governance.py  — On-Chain Governance
# ================================================================
# DAO-style on-chain governance: proposals, voting, execution.
# NBL holders vote with their stake weight.

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum

class ProposalStatus(Enum):
    DRAFT     = "draft"
    VOTING    = "voting"
    PASSED    = "passed"
    REJECTED  = "rejected"
    EXECUTED  = "executed"
    EXPIRED   = "expired"

class VoteType(Enum):
    YES       = "yes"
    NO        = "no"
    ABSTAIN   = "abstain"

# ── Governance Constants ──────────────────────────────────────────
GOV_VOTING_PERIOD_BLOCKS  = 1_008     # ~1 week
GOV_QUORUM_PCT            = 0.10      # 10% of staked supply must vote
GOV_PASS_THRESHOLD        = 0.67      # 67% yes to pass
GOV_MIN_DEPOSIT_NBL       = 100 * 10**DECIMALS  # 100 NBL deposit

@dataclass
class GovernanceProposal:
    """An on-chain governance proposal"""
    id              : int
    title           : str
    description     : str
    proposer        : str
    deposit         : int
    voting_start    : int     # block height
    voting_end      : int     # block height
    status          : ProposalStatus = ProposalStatus.DRAFT
    votes_yes       : int = 0
    votes_no        : int = 0
    votes_abstain   : int = 0
    voters          : Dict[str, VoteType] = field(default_factory=dict)
    changes         : Optional[dict] = None   # proposed parameter changes

    @property
    def total_votes(self) -> int:
        return self.votes_yes + self.votes_no + self.votes_abstain

    @property
    def yes_pct(self) -> float:
        voting = self.votes_yes + self.votes_no
        return self.votes_yes / max(1, voting) * 100

    def has_passed(self) -> bool:
        voting = self.votes_yes + self.votes_no
        return (voting > 0 and
                self.votes_yes / voting >= GOV_PASS_THRESHOLD)

    def to_dict(self) -> dict:
        return {
            "id"          : self.id,
            "title"       : self.title,
            "proposer"    : self.proposer,
            "status"      : self.status.value,
            "votes_yes"   : self.votes_yes / 10**DECIMALS,
            "votes_no"    : self.votes_no / 10**DECIMALS,
            "votes_abstain": self.votes_abstain / 10**DECIMALS,
            "yes_pct"     : f"{self.yes_pct:.1f}%",
            "total_votes" : self.total_votes / 10**DECIMALS,
            "voting_end"  : self.voting_end,
        }

class GovernanceEngine:
    """
    NEBULA On-Chain Governance.
    Allows NBL holders to propose and vote on protocol changes.
    Proposals: parameter changes, fund allocation, protocol upgrades.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 staking: 'StakingEngine' = None):
        self.bc          = blockchain
        self.staking     = staking
        self._proposals  : Dict[int, GovernanceProposal] = {}
        self._next_id    = 1
        self._lock       = threading.RLock()
        self._params     = self._default_params()

    def _default_params(self) -> dict:
        """Current governance-controlled parameters"""
        return {
            "MIN_TX_FEE"          : MIN_TX_FEE,
            "MAX_BLOCK_SIZE"      : MAX_BLOCK_SIZE_BYTES,
            "FOUNDATION_RATE"     : FOUNDATION_RATE,
            "STAKING_MIN_AMOUNT"  : STAKING_MIN_AMOUNT,
            "STAKING_ANNUAL_YIELD": STAKING_ANNUAL_YIELD_PCT,
        }

    def submit_proposal(self, proposer: str, title: str,
                         description: str, deposit: int,
                         changes: dict = None,
                         current_height: int = 0) -> Tuple[bool, int]:
        """Submit a governance proposal"""
        if deposit < GOV_MIN_DEPOSIT_NBL:
            return False, -1
        bal = self.bc.utxo.balance(proposer)
        if bal < deposit:
            return False, -1

        with self._lock:
            prop = GovernanceProposal(
                id           = self._next_id,
                title        = title,
                description  = description,
                proposer     = proposer,
                deposit      = deposit,
                voting_start = current_height,
                voting_end   = current_height + GOV_VOTING_PERIOD_BLOCKS,
                status       = ProposalStatus.VOTING,
                changes      = changes,
            )
            self._proposals[self._next_id] = prop
            pid = self._next_id
            self._next_id += 1
            return True, pid

    def vote(self, voter: str, proposal_id: int,
              vote_type: VoteType,
              current_height: int) -> Tuple[bool, str]:
        """Cast vote on a proposal"""
        with self._lock:
            prop = self._proposals.get(proposal_id)
            if not prop:
                return False, "Proposal not found"
            if prop.status != ProposalStatus.VOTING:
                return False, f"Proposal is {prop.status.value}"
            if current_height > prop.voting_end:
                prop.status = ProposalStatus.EXPIRED
                return False, "Voting period ended"
            if voter in prop.voters:
                return False, "Already voted"

            # Voting power = NBL balance
            power = self.bc.utxo.balance(voter)
            if power == 0:
                return False, "No voting power"

            prop.voters[voter] = vote_type
            if vote_type == VoteType.YES:
                prop.votes_yes     += power
            elif vote_type == VoteType.NO:
                prop.votes_no      += power
            else:
                prop.votes_abstain += power

            return True, f"Vote cast: {vote_type.value} ({power/10**DECIMALS:.2f} NBL)"

    def tally(self, proposal_id: int,
               current_height: int) -> Tuple[bool, str]:
        """Tally votes and finalize proposal"""
        with self._lock:
            prop = self._proposals.get(proposal_id)
            if not prop:
                return False, "Proposal not found"
            if current_height < prop.voting_end:
                return False, "Voting not ended"
            if prop.status != ProposalStatus.VOTING:
                return False, f"Already {prop.status.value}"

            # Check quorum
            total_supply  = self.bc.utxo.total_supply()
            quorum_needed = int(total_supply * GOV_QUORUM_PCT)
            if prop.total_votes < quorum_needed:
                prop.status = ProposalStatus.REJECTED
                return False, f"Quorum not met ({prop.total_votes} < {quorum_needed})"

            if prop.has_passed():
                prop.status = ProposalStatus.PASSED
                return True, "Proposal passed!"
            else:
                prop.status = ProposalStatus.REJECTED
                return False, f"Rejected ({prop.yes_pct:.1f}% yes, need {GOV_PASS_THRESHOLD*100:.0f}%)"

    def execute(self, proposal_id: int) -> Tuple[bool, str]:
        """Execute a passed proposal's changes"""
        with self._lock:
            prop = self._proposals.get(proposal_id)
            if not prop:
                return False, "Proposal not found"
            if prop.status != ProposalStatus.PASSED:
                return False, "Proposal not passed"

            if prop.changes:
                for key, value in prop.changes.items():
                    if key in self._params:
                        self._params[key] = value

            prop.status = ProposalStatus.EXECUTED
            return True, f"Executed: {len(prop.changes or {})} parameter changes"

    def list_proposals(self, status: str = None) -> List[dict]:
        with self._lock:
            props = list(self._proposals.values())
            if status:
                props = [p for p in props if p.status.value == status]
            return [p.to_dict() for p in props]

    def current_params(self) -> dict:
        return dict(self._params)

    def stats(self) -> dict:
        with self._lock:
            by_status = {}
            for p in self._proposals.values():
                by_status[p.status.value] = by_status.get(p.status.value, 0) + 1
            return {
                "total_proposals": len(self._proposals),
                "by_status"      : by_status,
                "params"         : self.current_params(),
            }


# ================================================================
# MODULE 49  nebula_zk_proofs.py  — Zero-Knowledge Proof Primitives
# ================================================================
# ZK proof primitives: Bulletproofs range proofs (simplified),
# commitment schemes, confidential transactions.

import hashlib, secrets
from typing import Tuple, List, Optional

# ── Pedersen Commitment ───────────────────────────────────────────
class PedersenCommitment:
    """
    Pedersen commitment scheme: C = r*G + v*H
    Hides a value v with blinding factor r.
    Used in confidential transactions (hide amounts).
    Properties: hiding + binding (computationally secure).
    """

    # H = HASH_TO_CURVE("NEBULA/PedersenH") — deterministic second generator
    @classmethod
    def _H(cls) -> Tuple[int, int]:
        """Second generator H (hash-to-curve)"""
        tag  = b"NEBULA/PedersenH"
        seed = hashlib.sha256(tag).digest()
        for i in range(1000):
            candidate = hashlib.sha256(seed + i.to_bytes(4,'big')).digest()
            x = int.from_bytes(candidate, 'big') % Secp256k1.P
            y_sq = (pow(x, 3, Secp256k1.P) + 7) % Secp256k1.P
            y    = pow(y_sq, (Secp256k1.P+1)//4, Secp256k1.P)
            if pow(y, 2, Secp256k1.P) == y_sq:
                return (x, y)
        raise ValueError("Could not find H")

    @classmethod
    def commit(cls, value: int,
               blinding: int = None) -> Tuple[bytes, int]:
        """
        Create commitment C = r*G + v*H
        Returns (commitment_bytes, blinding_factor)
        """
        if blinding is None:
            blinding = int.from_bytes(secrets.token_bytes(32), 'big') % Secp256k1.N

        G    = Secp256k1.G()
        H    = cls._H()
        rG   = Secp256k1.point_mul(blinding, G)
        vH   = Schnorr._point_mul(value, H)
        C    = Schnorr._point_add(rG, vH)
        if C is None:
            raise ValueError("Commitment is infinity")

        commitment = C[0].to_bytes(32, 'big') + C[1].to_bytes(32, 'big')
        return commitment, blinding

    @classmethod
    def add_commitments(cls, c1: bytes, c2: bytes) -> bytes:
        """Homomorphic addition: commit(a) + commit(b) = commit(a+b)"""
        x1 = int.from_bytes(c1[:32], 'big')
        y1 = int.from_bytes(c1[32:], 'big')
        x2 = int.from_bytes(c2[:32], 'big')
        y2 = int.from_bytes(c2[32:], 'big')
        C  = Schnorr._point_add((x1,y1), (x2,y2))
        if C is None:
            return b'\x00' * 64
        return C[0].to_bytes(32,'big') + C[1].to_bytes(32,'big')

    @classmethod
    def verify_sum(cls, inputs: List[bytes],
                    outputs: List[bytes],
                    excess_blinding: int) -> bool:
        """
        Verify that sum(input_commitments) = sum(output_commitments) + excess.
        Used to verify confidential transaction balance.
        """
        # Compute sum of inputs
        input_sum = None
        for c in inputs:
            x = int.from_bytes(c[:32],'big')
            y = int.from_bytes(c[32:],'big')
            input_sum = Schnorr._point_add(input_sum, (x,y))

        # Compute sum of outputs
        output_sum = None
        for c in outputs:
            x = int.from_bytes(c[:32],'big')
            y = int.from_bytes(c[32:],'big')
            output_sum = Schnorr._point_add(output_sum, (x,y))

        # Add excess commitment: excess_blinding * G
        excess_G = Secp256k1.point_mul(excess_blinding, Secp256k1.G)
        expected = Schnorr._point_add(output_sum, excess_G)

        return input_sum == expected

class RangeProof:
    """
    Simplified range proof: proves a value is in [0, 2^n) without revealing it.
    Full Bulletproofs (BIP341) are more complex.
    This is a simplified bit-decomposition proof for educational purposes.
    """

    def __init__(self, n_bits: int = 32):
        self.n_bits = n_bits

    def prove(self, value: int, blinding: int) -> dict:
        """
        Generate range proof for value in [0, 2^n_bits).
        Returns proof data (simplified).
        """
        if value < 0 or value >= 2**self.n_bits:
            raise ValueError(f"Value out of range [0, 2^{self.n_bits})")

        # Bit decomposition: v = sum(b_i * 2^i)
        bits = [(value >> i) & 1 for i in range(self.n_bits)]

        # Commit to each bit
        bit_commitments = []
        bit_blindings   = []
        for bit in bits:
            c, r = PedersenCommitment.commit(bit)
            bit_commitments.append(c.hex())
            bit_blindings.append(r)

        # Challenge
        challenge_data = b''.join(bytes.fromhex(c) for c in bit_commitments)
        challenge      = int.from_bytes(
            hashlib.sha256(challenge_data).digest(), 'big') % Secp256k1.N

        return {
            "commitment"      : PedersenCommitment.commit(value, blinding)[0].hex(),
            "n_bits"          : self.n_bits,
            "bit_commitments" : bit_commitments[:8],   # abbreviated
            "challenge"       : hex(challenge),
            "valid"           : True,
        }

    def verify(self, proof: dict, commitment: bytes) -> bool:
        """Verify range proof (simplified)"""
        return proof.get("valid", False) and proof.get("n_bits", 0) == self.n_bits

