# MODULE 51  nebula_network_stats.py  — Real-Time Network Stats
# ================================================================

import threading, time, statistics, collections
from typing import Dict, List, Optional
from dataclasses import dataclass, field

@dataclass
class NetworkSnapshot:
    timestamp     : float = field(default_factory=time.time)
    height        : int   = 0
    hashrate_mhs  : float = 0.0
    tx_count_24h  : int   = 0
    active_addrs  : int   = 0
    mempool_count : int   = 0
    avg_block_time: float = 0.0
    difficulty    : float = 0.0
    nbl_usd       : Optional[float] = None

    def to_dict(self) -> dict:
        return {
            "timestamp"    : self.timestamp,
            "height"       : self.height,
            "hashrate_mhs" : f"{self.hashrate_mhs:.2f} MH/s",
            "tx_24h"       : self.tx_count_24h,
            "active_addrs" : self.active_addrs,
            "mempool"      : self.mempool_count,
            "avg_block_time": f"{self.avg_block_time:.1f}s",
            "difficulty"   : self.difficulty,
            "nbl_usd"      : self.nbl_usd,
        }

class RealTimeNetworkStats:
    """
    Real-time network statistics collector.
    Collects and aggregates key blockchain metrics.
    """
    HISTORY_SIZE = 1440  # 24 hours worth of minute snapshots

    def __init__(self, blockchain: 'NEBULABlockchain',
                 oracle: 'PriceOracle' = None):
        self.bc       = blockchain
        self.oracle   = oracle
        self._history : collections.deque = collections.deque(maxlen=self.HISTORY_SIZE)
        self._lock    = threading.Lock()
        self._running = False

    def capture_snapshot(self) -> NetworkSnapshot:
        """Capture current network state"""
        chain   = self.bc._chain
        # 24h tx count
        cutoff  = time.time() - 86400
        tx_count = sum(
            len(blk.transactions)
            for blk in chain
            if blk.header.timestamp >= cutoff
        )
        # Active addresses
        addr_set = set()
        for blk in chain[-144:]:
            for tx in blk.transactions:
                for out in tx.outputs:
                    if out.address:
                        addr_set.add(out.address)

        # Avg block time (last 10 blocks)
        avg_bt = TARGET_BLOCK_TIME
        if len(chain) >= 2:
            recent = chain[-min(10, len(chain)):]
            if len(recent) >= 2:
                times = [recent[i].header.timestamp - recent[i-1].header.timestamp
                         for i in range(1, len(recent))]
                avg_bt = statistics.mean(times) if times else TARGET_BLOCK_TIME

        # Difficulty
        target = bits_to_target(self.bc.tip.header.bits)
        max_t  = bits_to_target(INITIAL_BITS)
        diff   = max_t / max(1, target)

        snap = NetworkSnapshot(
            height         = self.bc.height,
            tx_count_24h   = tx_count,
            active_addrs   = len(addr_set),
            mempool_count  = self.bc.mempool.size(),
            avg_block_time = avg_bt,
            difficulty     = round(diff, 6),
            nbl_usd        = self.oracle.get_nbl_usd() if self.oracle else None,
            hashrate_mhs   = diff * (2**32) / max(1, avg_bt) / 1e6,
        )
        with self._lock:
            self._history.append(snap)
        return snap

    def get_history(self, last_n: int = 60) -> List[dict]:
        with self._lock:
            snaps = list(self._history)[-last_n:]
        return [s.to_dict() for s in snaps]

    def trend_analysis(self) -> dict:
        with self._lock:
            if len(self._history) < 2:
                return {"insufficient_data": True}
            recent = list(self._history)
            heights   = [s.height for s in recent]
            avg_heights= statistics.mean(heights[-10:]) if len(heights) >= 10 else heights[-1]
            return {
                "snapshots"       : len(recent),
                "height_now"      : heights[-1],
                "mempool_trend"   : ("growing" if recent[-1].mempool_count > recent[0].mempool_count
                                     else "shrinking"),
                "avg_block_time"  : round(statistics.mean(
                    [s.avg_block_time for s in recent[-20:]]), 1),
                "current_hashrate": f"{recent[-1].hashrate_mhs:.2f} MH/s",
            }

    def start(self, interval: float = 60.0):
        self._running = True
        def _loop():
            while self._running:
                try: self.capture_snapshot()
                except Exception: _NB_SWALLOW_LOG.debug("swallowed Exception in RealTimeNetworkStats.start._loop", exc_info=True)
                time.sleep(interval)
        threading.Thread(target=_loop, daemon=True, name="NetStats").start()

    def stop(self): self._running = False


