# MODULE 52  nebula_block_pruning.py  — Block Pruning + Archive
# ================================================================

import threading, json
from typing import Optional, Set
from pathlib import Path

class BlockPruner:
    """
    Prune old blocks to reduce storage requirements.
    Keeps UTXO set + block headers (can verify chain).
    Discards full blocks older than prune_height.
    Like Bitcoin's -prune mode.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 keep_blocks: int = 1_000):
        self.bc          = blockchain
        self.keep_blocks = keep_blocks
        self._pruned_heights: Set[int] = set()
        self._lock       = threading.Lock()

    def prune(self) -> int:
        """Prune old blocks. Returns count pruned."""
        prune_below = self.bc.height - self.keep_blocks
        if prune_below <= 0:
            return 0

        pruned = 0
        with self._lock:
            for blk in self.bc._chain:
                if blk.height < prune_below and blk.height not in self._pruned_heights:
                    # Keep header, discard transactions
                    blk._pruned = True
                    blk.transactions = []
                    self._pruned_heights.add(blk.height)
                    pruned += 1
        return pruned

    def is_pruned(self, height: int) -> bool:
        return height in self._pruned_heights

    def storage_saved_mb(self) -> float:
        """Estimate storage saved by pruning"""
        avg_block_kb = 100   # ~100KB average
        return len(self._pruned_heights) * avg_block_kb / 1024

    def stats(self) -> dict:
        return {
            "mode"           : "pruned",
            "pruned_blocks"  : len(self._pruned_heights),
            "kept_blocks"    : self.keep_blocks,
            "storage_saved"  : f"{self.storage_saved_mb():.2f} MB",
            "prune_height"   : self.bc.height - self.keep_blocks,
        }

class BlockArchiver:
    """
    Archive old blocks to compressed files.
    Useful for full archival nodes and block explorers.
    """

    BLOCKS_PER_FILE = 1_000

    def __init__(self, archive_dir: str = "./nebula_archive"):
        self.archive_dir = Path(archive_dir)
        self.archive_dir.mkdir(parents=True, exist_ok=True)

    def archive_range(self, blockchain: 'NEBULABlockchain',
                       start: int, end: int) -> bool:
        """Archive a range of blocks"""
        try:
            blocks = []
            for h in range(start, min(end, blockchain.height + 1)):
                blk = blockchain.get_block(h)
                if blk:
                    blocks.append({
                        "height"  : blk.height,
                        "hash"    : blk.hash,
                        "header"  : blk.header.to_dict(),
                        "tx_count": len(blk.transactions),
                    })
            chunk = start // self.BLOCKS_PER_FILE
            path  = self.archive_dir / f"blk_{chunk:06d}.json"
            path.write_text(json.dumps({"blocks": blocks}, indent=2))
            return True
        except Exception:
            return False

    def get_archive_file(self, height: int) -> Optional[Path]:
        chunk = height // self.BLOCKS_PER_FILE
        path  = self.archive_dir / f"blk_{chunk:06d}.json"
        return path if path.exists() else None

    def stats(self) -> dict:
        files = list(self.archive_dir.glob("blk_*.json"))
        return {
            "archive_dir"  : str(self.archive_dir),
            "archive_files": len(files),
            "total_size_mb": sum(f.stat().st_size for f in files) / 1024 / 1024,
        }


# ================================================================
# MODULE 53  nebula_fee_reserve.py  — Fee Reserve + Subsidy Pool
# ================================================================

import threading
from typing import Dict
from dataclasses import dataclass, field

@dataclass
class FeeReserveEntry:
    height    : int
    total_fees: int
    subsidy   : int
    foundation: int
    miner     : int

class FeeReserveTracker:
    """
    Tracks mining fees and subsidy pool across all blocks.
    Provides detailed breakdown of where each satoshi went.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc     = blockchain
        self._entries: Dict[int, FeeReserveEntry] = {}
        self._lock  = threading.Lock()

    def process_block(self, block: 'Block'):
        """Record fee/subsidy breakdown for a block"""
        subsidy   = mining_reward(block.height)
        foundation= int(subsidy * FOUNDATION_RATE)
        miner_sub = subsidy - foundation

        # Calculate total fees
        total_fees = 0
        if len(block.transactions) > 1:
            for tx in block.transactions[1:]:
                total_fees += tx.total_output()

        with self._lock:
            self._entries[block.height] = FeeReserveEntry(
                height     = block.height,
                total_fees = total_fees,
                subsidy    = subsidy,
                foundation = foundation,
                miner      = miner_sub + total_fees,
            )

    def total_fees_earned(self) -> int:
        with self._lock:
            return sum(e.total_fees for e in self._entries.values())

    def total_subsidy_issued(self) -> int:
        with self._lock:
            return sum(e.subsidy for e in self._entries.values())

    def fee_trend(self, last_n: int = 144) -> dict:
        with self._lock:
            recent = sorted(self._entries.values(),
                             key=lambda x: x.height)[-last_n:]
        if not recent:
            return {}
        fees = [e.total_fees for e in recent]
        import statistics as _st
        return {
            "blocks_analyzed": len(fees),
            "avg_fee_nbl"    : _st.mean(fees) / 10**DECIMALS,
            "max_fee_nbl"    : max(fees) / 10**DECIMALS,
            "min_fee_nbl"    : min(fees) / 10**DECIMALS,
            "trend"          : "up" if fees[-1] > fees[0] else "down",
        }

    def stats(self) -> dict:
        return {
            "blocks_tracked"   : len(self._entries),
            "total_fees_nbl"   : self.total_fees_earned() / 10**DECIMALS,
            "total_subsidy_nbl": self.total_subsidy_issued() / 10**DECIMALS,
            "fee_trend"        : self.fee_trend(144),
        }


