# MODULE 54  nebula_wallet_connect.py  — WalletConnect Protocol
# ================================================================
# WalletConnect-style protocol for dApp ↔ wallet communication.
# Allows web dApps to request signatures from NEBULA wallet.

import threading, time, secrets, json
from typing import Dict, Callable, Optional

class WalletConnectSession:
    """Represents a dApp connection session"""
    def __init__(self, dapp_name: str, dapp_url: str):
        self.session_id = secrets.token_hex(16)
        self.dapp_name  = dapp_name
        self.dapp_url   = dapp_url
        self.created_at = time.time()
        self.approved   = False
        self.address    : Optional[str] = None
        self.pending_requests: Dict[str, dict] = {}

    def to_dict(self) -> dict:
        return {
            "session_id": self.session_id,
            "dapp"      : self.dapp_name,
            "url"       : self.dapp_url,
            "approved"  : self.approved,
            "address"   : self.address,
            "created"   : self.created_at,
        }

class WalletConnectHandler:
    """
    Handles WalletConnect sessions between dApps and NEBULA wallet.
    dApps can request: sign tx, sign message, get address.
    """

    def __init__(self, wallet: 'NEBULAWallet' = None):
        self.wallet   = wallet
        self._sessions: Dict[str, WalletConnectSession] = {}
        self._callbacks: Dict[str, Callable] = {}
        self._lock    = threading.Lock()

    def new_session(self, dapp_name: str, dapp_url: str) -> WalletConnectSession:
        """Create a new dApp connection request"""
        session = WalletConnectSession(dapp_name, dapp_url)
        with self._lock:
            self._sessions[session.session_id] = session
        return session

    def approve_session(self, session_id: str, address: str) -> bool:
        """User approves dApp connection"""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session:
                return False
            session.approved = True
            session.address  = address
        return True

    def reject_session(self, session_id: str):
        with self._lock:
            self._sessions.pop(session_id, None)

    def request_sign_tx(self, session_id: str,
                          tx: 'Transaction') -> Optional[str]:
        """dApp requests transaction signing"""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session or not session.approved:
                return None
        req_id = secrets.token_hex(8)
        with self._lock:
            session.pending_requests[req_id] = {
                "type"   : "sign_tx",
                "txid"   : tx.txid,
                "amount" : tx.total_output() / 10**DECIMALS,
                "status" : "pending",
            }
        return req_id

    def approve_request(self, session_id: str,
                         req_id: str) -> bool:
        """User approves a signing request"""
        with self._lock:
            session = self._sessions.get(session_id)
            if not session:
                return False
            req = session.pending_requests.get(req_id)
            if req:
                req["status"] = "approved"
                return True
        return False

    def list_sessions(self) -> List[dict]:
        with self._lock:
            return [s.to_dict() for s in self._sessions.values()
                    if s.approved]

    def pending_requests(self, session_id: str) -> List[dict]:
        with self._lock:
            session = self._sessions.get(session_id)
            if not session:
                return []
            return list(session.pending_requests.values())


