# ================================================================
# MODULE 56  nebula_mempool_visualizer.py  — Mempool Heatmap + Stats
# ================================================================

import threading, time, math
from typing import Dict, List, Tuple, Optional
from dataclasses import dataclass, field
from collections import defaultdict

@dataclass
class MempoolBucket:
    """Fee-rate bucket for mempool visualization"""
    fee_rate_min : float
    fee_rate_max : float
    tx_count     : int   = 0
    total_vbytes : int   = 0
    total_fees   : int   = 0

    @property
    def label(self) -> str:
        return f"{self.fee_rate_min:.0f}-{self.fee_rate_max:.0f}"

    @property
    def avg_fee_rate(self) -> float:
        return (self.fee_rate_min + self.fee_rate_max) / 2

    def to_dict(self) -> dict:
        return {
            "range"        : self.label,
            "tx_count"     : self.tx_count,
            "total_vbytes" : self.total_vbytes,
            "total_fees"   : self.total_fees / 10**DECIMALS,
            "avg_fee_rate" : self.avg_fee_rate,
        }

class MempoolVisualizer:
    """
    Mempool fee-rate heatmap and analytics.
    Groups transactions by fee rate for visualization.
    Shows: backlog, fee market depth, replacement zone.
    """

    FEE_BUCKETS = [
        (1, 2), (2, 3), (3, 5), (5, 10), (10, 20),
        (20, 50), (50, 100), (100, 200), (200, 500), (500, 9999)
    ]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc    = blockchain
        self._lock = threading.Lock()

    def compute_heatmap(self) -> List[MempoolBucket]:
        """Compute fee-rate distribution heatmap"""
        buckets = [MempoolBucket(lo, hi) for lo, hi in self.FEE_BUCKETS]
        pool    = getattr(self.bc.mempool, '_txs', {})

        for entry in pool.values():
            fee_rate = getattr(entry, 'fee_rate', 1.0)
            size     = entry.tx.byte_size() if hasattr(entry, 'tx') else 250
            fee      = getattr(entry, 'fee', 0)

            for bucket in buckets:
                if bucket.fee_rate_min <= fee_rate < bucket.fee_rate_max:
                    bucket.tx_count     += 1
                    bucket.total_vbytes += size
                    bucket.total_fees   += fee
                    break

        return buckets

    def ascii_heatmap(self) -> str:
        """Render ASCII heatmap of mempool fee buckets"""
        buckets  = self.compute_heatmap()
        max_count = max((b.tx_count for b in buckets), default=1)
        lines     = ["\n  📊 Mempool Fee Heatmap (sat/vB)\n"]
        lines.append(f"  {'Range':>10}  {'Count':>6}  Bar")
        lines.append("  " + "─" * 50)

        for b in buckets:
            if b.tx_count == 0:
                continue
            bar_len = int(b.tx_count / max_count * 30)
            bar     = "█" * bar_len
            lines.append(f"  {b.label:>10}  {b.tx_count:>6}  {bar}")

        total_txs   = sum(b.tx_count for b in buckets)
        total_vb    = sum(b.total_vbytes for b in buckets)
        lines.append("  " + "─" * 50)
        lines.append(f"  Total: {total_txs} txs | {total_vb//1024:.0f} KB")
        return "\n".join(lines)

    def next_block_estimate(self) -> dict:
        """Estimate contents of next block"""
        buckets = self.compute_heatmap()
        block_vbytes  = MAX_BLOCK_SIZE_BYTES
        included_txs  = 0
        included_fees = 0
        cutoff_rate   = 1.0

        # Take highest fee-rate buckets first
        for b in reversed(buckets):
            if block_vbytes <= 0:
                break
            take = min(b.tx_count, block_vbytes // max(1, b.total_vbytes // max(1, b.tx_count)))
            included_txs   += take
            included_fees  += int(b.total_fees * take / max(1, b.tx_count))
            block_vbytes   -= b.total_vbytes * take // max(1, b.tx_count)
            cutoff_rate     = b.avg_fee_rate

        return {
            "estimated_txs"      : included_txs,
            "estimated_fees_nbl" : included_fees / 10**DECIMALS,
            "min_fee_rate"       : cutoff_rate,
            "block_fullness_pct" : f"{(1 - block_vbytes/MAX_BLOCK_SIZE_BYTES)*100:.1f}%",
        }

    def congestion_level(self) -> str:
        """Return congestion level: low / medium / high / very_high"""
        size = self.bc.mempool.size()
        if size < 100:   return "low"
        if size < 1000:  return "medium"
        if size < 5000:  return "high"
        return "very_high"

    def full_report(self) -> dict:
        return {
            "heatmap"       : [b.to_dict() for b in self.compute_heatmap()],
            "next_block"    : self.next_block_estimate(),
            "congestion"    : self.congestion_level(),
            "total_txs"     : self.bc.mempool.size(),
        }


# ================================================================
# MODULE 57  nebula_chain_indexer.py  — Full Chain Indexer
# ================================================================
# Indexes: address → txids, txid → block, output scripts,
# token transfers, rich list cache. Enables fast queries.

import threading, time
from typing import Dict, List, Set, Optional, Tuple
from collections import defaultdict

class ChainIndexer:
    """
    Full blockchain indexer for fast queries.
    Indexes all transactions by address, type, and block.
    Required for block explorers and analytics.
    """

    def __init__(self):
        self._addr_txids     : Dict[str, Set[str]] = defaultdict(set)
        self._txid_block     : Dict[str, int]       = {}
        self._block_txids    : Dict[int, List[str]] = defaultdict(list)
        self._script_type_count: Dict[str, int]     = defaultdict(int)
        self._coinbase_addrs : Set[str]              = set()
        self._indexed_height : int                   = -1
        self._lock           = threading.RLock()

    def index_block(self, block: 'Block'):
        """Index all transactions in a block"""
        with self._lock:
            if block.height <= self._indexed_height:
                return

            for tx in block.transactions:
                self._txid_block[tx.txid] = block.height
                self._block_txids[block.height].append(tx.txid)

                # Index outputs (receiving)
                for out in tx.outputs:
                    if out.address:
                        self._addr_txids[out.address].add(tx.txid)
                    script_type = Script.classify(out.script_pubkey).value
                    self._script_type_count[script_type] += 1

                # Index inputs (spending)
                if not tx.is_coinbase:
                    for inp in tx.inputs:
                        # Mark input outpoint as spent
                        pass
                else:
                    for out in tx.outputs:
                        if out.address:
                            self._coinbase_addrs.add(out.address)

            self._indexed_height = block.height

    def index_chain(self, blockchain: 'NEBULABlockchain'):
        """Index entire blockchain"""
        for blk in blockchain._chain:
            self.index_block(blk)

    def get_address_txids(self, address: str) -> List[str]:
        with self._lock:
            return sorted(self._addr_txids.get(address, set()))

    def get_tx_block(self, txid: str) -> Optional[int]:
        return self._txid_block.get(txid)

    def get_block_txids(self, height: int) -> List[str]:
        with self._lock:
            return list(self._block_txids.get(height, []))

    def get_address_count(self) -> int:
        return len(self._addr_txids)

    def get_script_type_distribution(self) -> dict:
        with self._lock:
            total = sum(self._script_type_count.values())
            return {
                st: {"count": cnt, "pct": f"{cnt/max(1,total)*100:.1f}%"}
                for st, cnt in sorted(self._script_type_count.items(),
                                       key=lambda x: x[1], reverse=True)
            }

    def search_address(self, query: str) -> List[str]:
        """Find addresses matching prefix"""
        with self._lock:
            q = query.lower()
            return [addr for addr in self._addr_txids.keys()
                    if addr.lower().startswith(q)][:20]

    def stats(self) -> dict:
        with self._lock:
            return {
                "indexed_height"    : self._indexed_height,
                "unique_addresses"  : len(self._addr_txids),
                "indexed_txs"       : len(self._txid_block),
                "coinbase_addresses": len(self._coinbase_addrs),
                "script_types"      : dict(self._script_type_count),
            }


# ================================================================
# MODULE 58  nebula_tx_graph.py  — Transaction Graph Analysis
# ================================================================
# Build transaction graph for: cluster analysis, heuristics,
# change detection, entity clustering.

import threading
from typing import Dict, List, Set, Tuple, Optional
from collections import defaultdict, deque

class TxGraphNode:
    """Node in transaction graph"""
    def __init__(self, txid: str):
        self.txid      = txid
        self.inputs    : List[str] = []  # parent txids
        self.outputs   : List[str] = []  # child txids
        self.height    : int       = 0
        self.value_in  : int       = 0
        self.value_out : int       = 0
        self.fee       : int       = 0

class AddressCluster:
    """Group of addresses believed to belong to same entity"""
    def __init__(self, cluster_id: int):
        self.id        = cluster_id
        self.addresses : Set[str]  = set()
        self.tags      : List[str] = []
        self.label     : str       = ""

    def merge(self, other: 'AddressCluster'):
        self.addresses.update(other.addresses)

    def to_dict(self) -> dict:
        return {
            "cluster_id" : self.id,
            "size"       : len(self.addresses),
            "label"      : self.label or f"Cluster #{self.id}",
            "tags"       : self.tags,
        }

class TxGraphAnalyzer:
    """
    Transaction graph analysis for chain forensics.
    Implements: common input ownership heuristic,
    change address detection, entity clustering.
    """

    def __init__(self):
        self._nodes     : Dict[str, TxGraphNode] = {}
        self._clusters  : Dict[int, AddressCluster] = {}
        self._addr_cluster: Dict[str, int] = {}
        self._next_cluster= 1
        self._lock      = threading.RLock()

    def add_transaction(self, tx: 'Transaction', height: int = 0):
        """Add transaction to graph"""
        with self._lock:
            node = TxGraphNode(tx.txid)
            node.height = height
            for inp in tx.inputs:
                node.inputs.append(inp.outpoint.txid)
                parent = self._nodes.get(inp.outpoint.txid)
                if parent:
                    parent.outputs.append(tx.txid)
            self._nodes[tx.txid] = node

            # Common input ownership heuristic
            if not tx.is_coinbase and len(tx.inputs) > 1:
                input_addrs = []
                for inp in tx.inputs:
                    pass  # would lookup address from UTXO

    def build_from_blockchain(self, blockchain: 'NEBULABlockchain'):
        """Build graph from entire blockchain"""
        for blk in blockchain._chain:
            for tx in blk.transactions:
                self.add_transaction(tx, blk.height)

    def get_tx_chain(self, txid: str,
                      depth: int = 3) -> List[dict]:
        """Get ancestor/descendant chain for a tx"""
        chain   = []
        visited = set()
        queue   = deque([(txid, 0)])

        while queue:
            tid, d = queue.popleft()
            if tid in visited or d > depth:
                continue
            visited.add(tid)
            node = self._nodes.get(tid)
            if node:
                chain.append({
                    "txid"   : tid,
                    "depth"  : d,
                    "inputs" : node.inputs,
                    "outputs": node.outputs,
                })
                for parent in node.inputs:
                    queue.append((parent, d+1))

        return chain

    def find_path(self, from_txid: str, to_txid: str,
                   max_depth: int = 10) -> Optional[List[str]]:
        """Find shortest path between two transactions"""
        visited = {from_txid: None}
        queue   = deque([from_txid])

        while queue:
            current = queue.popleft()
            if current == to_txid:
                # Reconstruct path
                path = []
                while current:
                    path.append(current)
                    current = visited[current]
                return list(reversed(path))

            node = self._nodes.get(current)
            if not node:
                continue
            for child in node.outputs:
                if child not in visited:
                    visited[child] = current
                    queue.append(child)

        return None

    def stats(self) -> dict:
        with self._lock:
            return {
                "total_txs"    : len(self._nodes),
                "total_clusters": len(self._clusters),
                "clustered_addrs": len(self._addr_cluster),
            }


# ================================================================
# MODULE 59  nebula_mining_pool.py  — Pool Mining + Share Tracking
# ================================================================
# Full mining pool implementation: share submission, PPLNS reward,
# worker management, pool stats dashboard.

import threading, time, hashlib, secrets
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field

# ── Pool Constants ────────────────────────────────────────────────
POOL_NAME               = "NEBULA Pool"
POOL_FEE_PCT            = 1.0     # 1% pool fee
PPLNS_N_SHARES          = 10_000  # N for PPLNS
SHARE_DIFF_MULTIPLIER   = 0.01    # share difficulty = block_diff * 0.01
MIN_PAYOUT_NBL          = 0.01 * 10**DECIMALS
POOL_BLOCK_VERSION      = 0x20000007

@dataclass
class PoolShare:
    """A share submitted by a miner"""
    worker_id   : str
    miner_addr  : str
    nonce       : int
    hash_value  : bytes
    difficulty  : float
    timestamp   : float = field(default_factory=time.time)
    block_height: int   = 0
    is_block    : bool  = False   # True if this share also found a block

    def to_dict(self) -> dict:
        return {
            "worker"    : self.worker_id,
            "miner"     : self.miner_addr,
            "diff"      : round(self.difficulty, 4),
            "time"      : self.timestamp,
            "is_block"  : self.is_block,
        }

@dataclass
class PoolWorkerMini:
    """A worker connected to the pool"""
    worker_id    : str
    miner_addr   : str
    connected_at : float = field(default_factory=time.time)
    last_share   : float = 0.0
    shares_count : int   = 0
    valid_shares : int   = 0
    stale_shares : int   = 0
    hashrate_mhs : float = 0.0

    def update_hashrate(self, window_secs: float = 300.0):
        """Estimate hashrate from recent shares"""
        if self.last_share > 0:
            age = time.time() - self.connected_at
            self.hashrate_mhs = (self.valid_shares * SHARE_DIFF_MULTIPLIER
                                  / max(1, age) * 2**32 / 1e6)

    def to_dict(self) -> dict:
        self.update_hashrate()
        return {
            "worker_id"   : self.worker_id,
            "miner"       : self.miner_addr,
            "uptime_secs" : round(time.time() - self.connected_at),
            "shares"      : self.valid_shares,
            "hashrate_mhs": round(self.hashrate_mhs, 4),
            "efficiency"  : f"{self.valid_shares/max(1,self.shares_count)*100:.1f}%",
        }

class PPLNSCalculator:
    """
    Pay-Per-Last-N-Shares (PPLNS) reward calculator.
    More resistant to pool-hopping than PPS.
    """

    def __init__(self, n_shares: int = PPLNS_N_SHARES):
        self.n         = n_shares
        self._shares   : List[PoolShare] = []
        self._lock     = threading.Lock()

    def add_share(self, share: PoolShare):
        with self._lock:
            self._shares.append(share)
            if len(self._shares) > self.n * 2:
                self._shares = self._shares[-self.n:]

    def calculate_payouts(self, block_reward: int,
                           pool_fee_pct: float = POOL_FEE_PCT) -> Dict[str, int]:
        """
        Calculate miner payouts for a found block.
        Uses last N shares to determine each miner's share.
        """
        with self._lock:
            window = self._shares[-self.n:]

        if not window:
            return {}

        # Sum difficulty shares per miner
        miner_shares: Dict[str, float] = {}
        total_diff   = 0.0
        for share in window:
            miner_shares[share.miner_addr] = (
                miner_shares.get(share.miner_addr, 0) + share.difficulty)
            total_diff += share.difficulty

        if total_diff == 0:
            return {}

        # Subtract pool fee
        pool_cut = int(block_reward * pool_fee_pct / 100)
        net_reward = block_reward - pool_cut

        payouts = {}
        for addr, diff in miner_shares.items():
            payout = int(net_reward * diff / total_diff)
            if payout >= MIN_PAYOUT_NBL:
                payouts[addr] = payout

        return payouts

    def share_count(self) -> int:
        return len(self._shares)

class MiningPool:
    """
    Full NEBULA mining pool.
    Features: Stratum v1/v2, PPLNS payouts, worker dashboard,
    difficulty adjustment, DoS protection.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 pool_address: str = FOUNDATION_ADDRESS,
                 pool_fee_pct: float = POOL_FEE_PCT):
        self.bc            = blockchain
        self.pool_address  = pool_address
        self.pool_fee_pct  = pool_fee_pct
        self.pplns         = PPLNSCalculator()
        self._workers      : Dict[str, PoolWorker] = {}
        self._shares       : List[PoolShare] = []
        self._blocks_found : int   = 0
        self._total_paid   : int   = 0
        self._pending_payouts: Dict[str, int] = {}
        self._lock         = threading.RLock()
        self._start_time   = time.time()

    def register_worker(self, worker_id: str,
                         miner_addr: str) -> bool:
        """Register a new pool worker"""
        with self._lock:
            self._workers[worker_id] = PoolWorkerMini(
                worker_id  = worker_id,
                miner_addr = miner_addr,
            )
        return True

    def submit_share(self, worker_id: str, nonce: int,
                      hash_bytes: bytes) -> Tuple[bool, str]:
        """
        Submit a mining share.
        Validates difficulty and checks if it's a valid block.
        """
        worker = self._workers.get(worker_id)
        if not worker:
            return False, "Worker not registered"

        # Check share difficulty
        hash_int   = int.from_bytes(hash_bytes[:4], 'big')
        difficulty = (2**32) / max(1, hash_int)
        share_diff = bits_to_target(INITIAL_BITS) * SHARE_DIFF_MULTIPLIER

        if hash_int > share_diff:
            worker.stale_shares += 1
            return False, "Share below difficulty"

        # Is this a valid block?
        block_target = bits_to_target(self.bc.tip.header.bits)
        is_block     = int.from_bytes(hash_bytes, 'big') <= block_target

        share = PoolShare(
            worker_id    = worker_id,
            miner_addr   = worker.miner_addr,
            nonce        = nonce,
            hash_value   = hash_bytes,
            difficulty   = difficulty,
            block_height = self.bc.height,
            is_block     = is_block,
        )

        with self._lock:
            self._shares.append(share)
            worker.shares_count += 1
            worker.valid_shares += 1
            worker.last_share    = time.time()
        self.pplns.add_share(share)

        if is_block:
            self._on_block_found(share)
            return True, f"Block found! Height {self.bc.height}"

        return True, f"Share accepted (diff: {difficulty:.4f})"

    def _on_block_found(self, share: PoolShare):
        """Handle a found block: calculate and queue payouts"""
        with self._lock:
            reward  = mining_reward(self.bc.height)
            payouts = self.pplns.calculate_payouts(reward, self.pool_fee_pct)
            for addr, amount in payouts.items():
                self._pending_payouts[addr] = (
                    self._pending_payouts.get(addr, 0) + amount)
            self._blocks_found += 1
            self._total_paid   += sum(payouts.values())

    def get_worker_stats(self, worker_id: str) -> Optional[dict]:
        worker = self._workers.get(worker_id)
        return worker.to_dict() if worker else None

    def pool_hashrate_mhs(self) -> float:
        """Total pool hashrate"""
        return sum(w.hashrate_mhs for w in self._workers.values())

    def stats(self) -> dict:
        uptime = time.time() - self._start_time
        return {
            "pool_name"      : POOL_NAME,
            "pool_address"   : self.pool_address,
            "pool_fee_pct"   : self.pool_fee_pct,
            "workers"        : len(self._workers),
            "total_shares"   : len(self._shares),
            "blocks_found"   : self._blocks_found,
            "total_paid_nbl" : self._total_paid / 10**DECIMALS,
            "hashrate_mhs"   : round(self.pool_hashrate_mhs(), 4),
            "uptime_secs"    : round(uptime),
            "pplns_window"   : self.pplns.share_count(),
            "pending_payouts": {addr[:16]+"...": amt/10**DECIMALS
                                for addr, amt in self._pending_payouts.items()},
        }

    def worker_list(self) -> List[dict]:
        with self._lock:
            return [w.to_dict() for w in self._workers.values()]


# ================================================================
# MODULE 60  nebula_dex.py  — Decentralized Exchange (Order Book)
# ================================================================
# On-chain DEX with order book, limit orders, market orders,
# trade history, and price charts.

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
import bisect

class OrderType(Enum):
    LIMIT  = "limit"
    MARKET = "market"

class OrderSide(Enum):
    BUY  = "buy"
    SELL = "sell"

class OrderStatus(Enum):
    OPEN      = "open"
    FILLED    = "filled"
    PARTIAL   = "partial"
    CANCELLED = "cancelled"

@dataclass
class Order:
    """A DEX order"""
    order_id  : str
    trader    : str
    pair      : str
    side      : OrderSide
    order_type: OrderType
    price     : float    # price in quote token
    amount    : int      # in base token (Neb)
    filled    : int  = 0
    status    : OrderStatus = OrderStatus.OPEN
    created_at: float = field(default_factory=time.time)
    updated_at: float = field(default_factory=time.time)

    @property
    def remaining(self) -> int:
        return self.amount - self.filled

    @property
    def fill_pct(self) -> float:
        return self.filled / max(1, self.amount) * 100

    def to_dict(self) -> dict:
        return {
            "order_id"  : self.order_id,
            "trader"    : self.trader[:16] + "...",
            "pair"      : self.pair,
            "side"      : self.side.value,
            "type"      : self.order_type.value,
            "price"     : self.price,
            "amount"    : self.amount / 10**DECIMALS,
            "filled"    : self.filled / 10**DECIMALS,
            "remaining" : self.remaining / 10**DECIMALS,
            "status"    : self.status.value,
            "fill_pct"  : f"{self.fill_pct:.1f}%",
        }

@dataclass
class Trade:
    """A completed trade"""
    trade_id     : str
    pair         : str
    price        : float
    amount       : int
    buyer        : str
    seller       : str
    timestamp    : float = field(default_factory=time.time)
    maker_order  : str   = ""
    taker_order  : str   = ""

    def to_dict(self) -> dict:
        return {
            "trade_id"  : self.trade_id,
            "pair"      : self.pair,
            "price"     : self.price,
            "amount"    : self.amount / 10**DECIMALS,
            "buyer"     : self.buyer[:16] + "...",
            "seller"    : self.seller[:16] + "...",
            "timestamp" : self.timestamp,
        }

class OrderBook:
    """
    Price-time priority order book.
    Bids sorted descending, asks sorted ascending.
    """

    def __init__(self, pair: str):
        self.pair   = pair
        self._bids  : List[Order] = []   # sorted descending by price
        self._asks  : List[Order] = []   # sorted ascending by price
        self._lock  = threading.RLock()

    def add_order(self, order: Order) -> List[Trade]:
        """Add order and attempt matching. Returns list of trades."""
        trades = []
        with self._lock:
            if order.order_type == OrderType.MARKET:
                trades = self._match_market(order)
            else:
                trades = self._match_limit(order)
                if order.status == OrderStatus.OPEN:
                    self._insert_order(order)
        return trades

    def _match_limit(self, order: Order) -> List[Trade]:
        """Match a limit order against opposite side"""
        trades  = []
        book    = self._asks if order.side == OrderSide.BUY else self._bids

        while book and order.remaining > 0:
            best = book[0]
            if order.side == OrderSide.BUY and best.price > order.price:
                break
            if order.side == OrderSide.SELL and best.price < order.price:
                break

            fill = min(order.remaining, best.remaining)
            trade = Trade(
                trade_id   = secrets.token_hex(8),
                pair       = self.pair,
                price      = best.price,
                amount     = fill,
                buyer      = order.trader if order.side == OrderSide.BUY else best.trader,
                seller     = best.trader  if order.side == OrderSide.BUY else order.trader,
                maker_order= best.order_id,
                taker_order= order.order_id,
            )
            trades.append(trade)

            order.filled   += fill
            best.filled    += fill
            order.updated_at = best.updated_at = time.time()

            if best.remaining == 0:
                best.status = OrderStatus.FILLED
                book.pop(0)
            else:
                best.status = OrderStatus.PARTIAL

            order.status = (OrderStatus.FILLED if order.remaining == 0
                            else OrderStatus.PARTIAL)

        return trades

    def _match_market(self, order: Order) -> List[Trade]:
        """Match a market order at best available price"""
        order.price = (self._asks[0].price if self._asks and order.side == OrderSide.BUY
                       else self._bids[0].price if self._bids else 0)
        return self._match_limit(order)

    def _insert_order(self, order: Order):
        """Insert limit order into book maintaining sort order"""
        if order.side == OrderSide.BUY:
            # Insert descending
            idx = 0
            while idx < len(self._bids) and self._bids[idx].price > order.price:
                idx += 1
            self._bids.insert(idx, order)
        else:
            # Insert ascending
            idx = 0
            while idx < len(self._asks) and self._asks[idx].price < order.price:
                idx += 1
            self._asks.insert(idx, order)

    def cancel_order(self, order_id: str) -> bool:
        """Cancel an open order"""
        with self._lock:
            for book in (self._bids, self._asks):
                for i, o in enumerate(book):
                    if o.order_id == order_id:
                        o.status = OrderStatus.CANCELLED
                        book.pop(i)
                        return True
        return False

    def best_bid(self) -> Optional[float]:
        with self._lock:
            return self._bids[0].price if self._bids else None

    def best_ask(self) -> Optional[float]:
        with self._lock:
            return self._asks[0].price if self._asks else None

    def spread(self) -> Optional[float]:
        bid, ask = self.best_bid(), self.best_ask()
        return ask - bid if bid and ask else None

    def mid_price(self) -> Optional[float]:
        bid, ask = self.best_bid(), self.best_ask()
        return (bid + ask) / 2 if bid and ask else None

    def depth(self, levels: int = 5) -> dict:
        with self._lock:
            bids = [{"price": o.price, "amount": o.remaining/10**DECIMALS}
                    for o in self._bids[:levels]]
            asks = [{"price": o.price, "amount": o.remaining/10**DECIMALS}
                    for o in self._asks[:levels]]
        return {"bids": bids, "asks": asks,
                "spread": self.spread(), "mid": self.mid_price()}

class DEXEngine:
    """
    NEBULA Decentralized Exchange.
    Manages multiple order books and trade history.
    """

    DEFAULT_PAIRS = ["NBL/USDT", "NBL/BTC", "NBL/ETH"]

    def __init__(self):
        self._books      : Dict[str, OrderBook] = {}
        self._orders     : Dict[str, Order]     = {}
        self._trades     : List[Trade]          = []
        self._lock       = threading.RLock()
        self._total_volume= 0

        for pair in self.DEFAULT_PAIRS:
            self._books[pair] = OrderBook(pair)

    def place_order(self, trader: str, pair: str,
                     side: str, order_type: str,
                     price: float, amount: int) -> Tuple[str, List[Trade]]:
        """Place a new order"""
        book = self._books.get(pair)
        if not book:
            self._books[pair] = OrderBook(pair)
            book = self._books[pair]

        order = Order(
            order_id   = secrets.token_hex(8),
            trader     = trader,
            pair       = pair,
            side       = OrderSide(side),
            order_type = OrderType(order_type),
            price      = price,
            amount     = amount,
        )

        with self._lock:
            self._orders[order.order_id] = order

        trades = book.add_order(order)

        with self._lock:
            self._trades.extend(trades)
            for t in trades:
                self._total_volume += t.amount

        return order.order_id, trades

    def cancel_order(self, order_id: str) -> bool:
        order = self._orders.get(order_id)
        if not order:
            return False
        book = self._books.get(order.pair)
        return book.cancel_order(order_id) if book else False

    def get_order(self, order_id: str) -> Optional[dict]:
        order = self._orders.get(order_id)
        return order.to_dict() if order else None

    def get_order_book(self, pair: str,
                        levels: int = 10) -> dict:
        book = self._books.get(pair)
        return book.depth(levels) if book else {}

    def get_trades(self, pair: str = None,
                    limit: int = 50) -> List[dict]:
        trades = self._trades
        if pair:
            trades = [t for t in trades if t.pair == pair]
        return [t.to_dict() for t in reversed(trades[-limit:])]

    def get_ohlcv(self, pair: str,
                   window_secs: int = 3600) -> dict:
        """OHLCV candle data"""
        cutoff = time.time() - window_secs
        prices = [t.price for t in self._trades
                  if t.pair == pair and t.timestamp >= cutoff]
        if not prices:
            return {}
        return {
            "open"   : prices[0],
            "high"   : max(prices),
            "low"    : min(prices),
            "close"  : prices[-1],
            "volume" : sum(t.amount for t in self._trades
                          if t.pair == pair and t.timestamp >= cutoff) / 10**DECIMALS,
        }

    def market_summary(self) -> List[dict]:
        """Summary for all trading pairs"""
        summary = []
        for pair, book in self._books.items():
            ohlcv = self.get_ohlcv(pair, 86400)
            summary.append({
                "pair"     : pair,
                "mid_price": book.mid_price(),
                "spread"   : book.spread(),
                "24h"      : ohlcv,
                "open_orders": len([o for o in self._orders.values()
                                    if o.pair == pair and o.status == OrderStatus.OPEN]),
            })
        return summary

    def stats(self) -> dict:
        return {
            "pairs"        : len(self._books),
            "total_orders" : len(self._orders),
            "total_trades" : len(self._trades),
            "total_volume" : self._total_volume / 10**DECIMALS,
        }

