# MODULE 65  nebula_protocol_docs.py  — Protocol Documentation
# ================================================================
# Auto-generated protocol documentation and specification.
# Documents all constants, message types, RPC methods.

class ProtocolDocGenerator:
    """
    Generates protocol documentation for NEBULA.
    Documents: constants, message formats, RPC, wire protocol.
    """

    def chain_constants_doc(self) -> str:
        return f"""
NEBULA Blockchain Protocol Constants
=====================================
Chain Name      : {CHAIN_NAME}
Chain Symbol    : {CHAIN_SYMBOL}
Chain ID        : {CHAIN_ID}
Decimals        : {DECIMALS}
Max Supply      : {MAX_SUPPLY/10**DECIMALS:,} {CHAIN_SYMBOL}

Block Parameters
-----------------
Target Block Time    : {TARGET_BLOCK_TIME}s ({TARGET_BLOCK_TIME/60:.1f} min)
Difficulty Window    : {DIFFICULTY_WINDOW} blocks
Initial PoW Bits     : 0x{INITIAL_BITS:08x}
Max Block Size       : {MAX_BLOCK_SIZE_BYTES:,} bytes
Max Tx Per Block     : {MAX_TX_PER_BLOCK:,}
Coinbase Maturity    : {COINBASE_MATURITY} blocks

Mining Rewards
--------------
Initial Reward       : {INITIAL_BLOCK_REWARD/10**DECIMALS:.9f} {CHAIN_SYMBOL}
Halving Interval     : {HALVING_INTERVAL:,} blocks
Foundation Rate      : {FOUNDATION_RATE*100:.0f}%
Foundation Address   : {FOUNDATION_ADDRESS}

Addresses
---------
P2PKH Prefix         : {PUBKEY_ADDRESS_PREFIX}
Script Prefix        : {SCRIPT_ADDRESS_PREFIX if 'SCRIPT_ADDRESS_PREFIX' in dir() else 'N/A'}
Bech32 HRP           : nbl

Network
-------
Default Port         : {DEFAULT_PORT}
Protocol Version     : {PROTOCOL_VERSION}
Max Peers            : {MAX_PEERS}
DNS Seeds            : {', '.join(DNS_SEEDS[:2])}...

Wallet
------
BIP44 Coin Type      : 2025
BIP44 Path           : {NBL_BIP44_PATH}
HD Version (mainnet) : 0x0488B21E (xpub/xprv)
"""

    def rpc_methods_doc(self) -> str:
        """Generate RPC methods documentation"""
        categories = {
            "Blockchain"  : ["getblockchaininfo", "getblockcount", "getblockhash",
                              "getblock", "getbestblockhash", "getdifficulty",
                              "getmempoolinfo", "getrawmempool", "gettxout"],
            "Mining"      : ["getblocktemplate", "submitblock", "getmininginfo",
                              "getnetworkhashps"],
            "Wallet"      : ["getbalance", "getnewaddress", "sendtoaddress",
                              "listunspent", "getwalletinfo", "signmessage"],
            "Network"     : ["getnetworkinfo", "getpeerinfo", "addnode",
                              "getconnectioncount", "ping"],
            "NEBULA"      : ["getsupplyinfo", "getfoundationinfo", "geterainfo",
                              "getchainconstants", "getmoduleinfo"],
        }
        lines = ["NEBULA JSON-RPC API Reference", "="*40]
        for cat, methods in categories.items():
            lines.append(f"\n{cat}:")
            for m in methods:
                lines.append(f"  • {m}")
        lines.append(f"\nTotal: 200+ methods")
        return "\n".join(lines)

    def message_types_doc(self) -> str:
        """Document P2P wire protocol messages"""
        messages = [
            ("version",     "Handshake: send version info"),
            ("verack",      "Handshake: acknowledge version"),
            ("ping",        "Keepalive ping"),
            ("pong",        "Keepalive pong response"),
            ("addr",        "Send peer addresses (max 1000)"),
            ("addrv2",      "BIP155: send addresses with network type"),
            ("getblocks",   "Request block inventory"),
            ("inv",         "Announce inventory (blocks/txs)"),
            ("getdata",     "Request specific data"),
            ("block",       "Send full block"),
            ("tx",          "Send transaction"),
            ("headers",     "Send block headers (BIP130)"),
            ("getheaders",  "Request block headers"),
            ("filterload",  "BIP37: load bloom filter"),
            ("filteradd",   "BIP37: add to bloom filter"),
            ("filterclear", "BIP37: clear bloom filter"),
            ("merkleblock", "BIP37: merkle proof"),
            ("sendcmpct",   "BIP152: request compact blocks"),
            ("cmpctblock",  "BIP152: send compact block"),
            ("getblocktxn", "BIP152: request missing txs"),
            ("blocktxn",    "BIP152: send missing txs"),
            ("sendaddrv2",  "BIP155: request addrv2 format"),
        ]
        lines = ["\nNEBULA P2P Wire Protocol Messages", "="*40]
        for cmd, desc in messages:
            lines.append(f"  {cmd:20} {desc}")
        return "\n".join(lines)

    def generate_full_spec(self) -> str:
        """Generate complete protocol specification"""
        return "\n".join([
            self.chain_constants_doc(),
            self.rpc_methods_doc(),
            self.message_types_doc(),
        ])

    def save_spec(self, path: str = "./NEBULA_PROTOCOL.md"):
        """Save protocol specification to file"""
        spec = self.generate_full_spec()
        try:
            with open(path, 'w') as f:
                f.write(f"# NEBULA Protocol Specification\n\n")
                f.write(f"**Author:** NEBULA Core Team  \n")
                f.write(f"**Version:** 1.0.0  \n\n")
                f.write("```\n" + spec + "\n```\n")
            return True
        except Exception:
            return False

