# ================================================================
# MODULE 68  nebula_blockchain_api.py  — Public Blockchain API
# ================================================================
# RESTful blockchain API for third-party integrations.
# Returns JSON for: blocks, txs, addresses, supply, network.

import json, threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Dict, Optional
import urllib.parse

class BlockchainAPIHandler(BaseHTTPRequestHandler):
    """HTTP handler for public blockchain API"""

    api_server: 'BlockchainAPI' = None

    def log_message(self, fmt, *args): pass

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path   = parsed.path.rstrip('/')
        params = dict(urllib.parse.parse_qsl(parsed.query))

        routes = {
            '/api/v1/chain'              : self._chain_info,
            '/api/v1/block/latest'       : self._latest_block,
            '/api/v1/block/height'       : lambda: self._block_by_height(params),
            '/api/v1/block/hash'         : lambda: self._block_by_hash(params),
            '/api/v1/tx'                 : lambda: self._get_tx(params),
            '/api/v1/address'            : lambda: self._get_address(params),
            '/api/v1/mempool'            : self._mempool_info,
            '/api/v1/supply'             : self._supply_info,
            '/api/v1/network'            : self._network_info,
            '/api/v1/halving'            : self._halving_info,
            '/api/v1/richlist'           : self._rich_list,
            '/api/v1/fee'                : self._fee_info,
            '/api/v1/price'              : self._price_info,
        }

        handler = routes.get(path)
        if handler:
            try:
                result = handler()
                self._json_response(200, result)
            except Exception as e:
                self._json_response(500, {"error": str(e)})
        else:
            self._json_response(404, {"error": "Not found", "path": path})

    def _chain_info(self) -> dict:
        bc = self.api_server.bc
        return {
            "chain"         : CHAIN_NAME,
            "symbol"        : CHAIN_SYMBOL,
            "height"        : bc.height,
            "best_block"    : bc.tip.hash,
            "difficulty"    : bits_to_target(bc.tip.header.bits),
            "utxo_count"    : bc.utxo.size(),
            "mempool_count" : bc.mempool.size(),
        }

    def _latest_block(self) -> dict:
        bc  = self.api_server.bc
        blk = bc.tip
        return {
            "hash"      : blk.hash,
            "height"    : blk.height,
            "time"      : blk.header.timestamp,
            "tx_count"  : len(blk.transactions),
            "size"      : blk.byte_size(),
            "miner"     : (blk.transactions[0].outputs[0].address
                           if blk.transactions else ""),
            "reward"    : mining_reward(blk.height) / 10**DECIMALS,
        }

    def _block_by_height(self, params: dict) -> dict:
        height = int(params.get("n", 0))
        bc     = self.api_server.bc
        blk    = bc.get_block(height)
        if not blk:
            return {"error": f"Block {height} not found"}
        return blk.to_dict()

    def _block_by_hash(self, params: dict) -> dict:
        h   = params.get("hash", "")
        bc  = self.api_server.bc
        blk = bc.get_block_by_hash(h)
        if not blk:
            return {"error": "Block not found"}
        return blk.to_dict()

    def _get_tx(self, params: dict) -> dict:
        txid = params.get("txid", "")
        bc   = self.api_server.bc
        for blk in reversed(bc._chain):
            for tx in blk.transactions:
                if tx.txid == txid:
                    d = tx.to_dict()
                    d["block_hash"]     = blk.hash
                    d["block_height"]   = blk.height
                    d["confirmations"]  = bc.height - blk.height + 1
                    return d
        return {"error": f"Transaction {txid} not found"}

    def _get_address(self, params: dict) -> dict:
        addr = params.get("addr", "")
        bc   = self.api_server.bc
        info = bc.get_balance(addr)
        utxos = bc.utxo.get_by_address(addr)
        return {
            "address"    : addr,
            "balance_nbl": info["balance_nbl"],
            "utxo_count" : info["utxo_count"],
            "utxos"      : [{"txid": u.txid, "vout": u.index,
                              "value": u.value/10**DECIMALS,
                              "height": u.height}
                             for u in utxos[:20]],
        }

    def _mempool_info(self) -> dict:
        bc = self.api_server.bc
        return {
            "count"       : bc.mempool.size(),
            "total_fees"  : bc.mempool.total_fees() / 10**DECIMALS,
        }

    def _supply_info(self) -> dict:
        bc      = self.api_server.bc
        issued  = bc.utxo.total_supply()
        return {
            "max_supply"   : MAX_SUPPLY / 10**DECIMALS,
            "issued"       : issued / 10**DECIMALS,
            "pct_issued"   : f"{issued/MAX_SUPPLY*100:.4f}%",
            "remaining"    : (MAX_SUPPLY - issued) / 10**DECIMALS,
            "current_reward": mining_reward(bc.height) / 10**DECIMALS,
        }

    def _network_info(self) -> dict:
        return {
            "version"    : PROTOCOL_VERSION,
            "chain"      : CHAIN_NAME,
            "protocol"   : PROTOCOL_VERSION,
            "active"     : True,
        }

    def _halving_info(self) -> dict:
        bc = self.api_server.bc
        return halving_era(bc.height)

    def _rich_list(self) -> dict:
        rl = RichList(self.api_server.bc, top_n=20)
        return {"top20": [e.to_dict() for e in rl.build()]}

    def _fee_info(self) -> dict:
        bc = self.api_server.bc
        if hasattr(bc.mempool, 'fee_estimates'):
            return bc.mempool.fee_estimates()
        return {"1 block": MIN_TX_FEE // 10**DECIMALS}

    def _price_info(self) -> dict:
        oracle = getattr(self.api_server, 'oracle', None)
        if oracle:
            return {"NBL/USD": oracle.get_nbl_usd(),
                    "NBL/BTC": oracle.get_nbl_btc()}
        return {"error": "Oracle not available"}

    def _json_response(self, code: int, data: dict):
        body = json.dumps(data, default=str).encode()
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        self.wfile.write(body)

class BlockchainAPI:
    """
    Public REST API for NEBULA blockchain.
    Exposes: chain info, blocks, transactions, addresses, stats.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 oracle: 'PriceOracle' = None,
                 host: str = _nbl_default_bind(), port: int = 8080):
        self.bc      = blockchain
        self.oracle  = oracle
        self.host    = host
        self.port    = port
        self._server : Optional[HTTPServer] = None
        self._thread : Optional[threading.Thread] = None

    def start(self):
        BlockchainAPIHandler.api_server = self
        self._server = HTTPServer((self.host, self.port), BlockchainAPIHandler)
        self._thread = threading.Thread(
            target=self._server.serve_forever, daemon=True, name="BlockchainAPI")
        self._thread.start()
        print(f"🌐 Blockchain API: http://{self.host}:{self.port}/api/v1/chain")

    def stop(self):
        if self._server:
            self._server.shutdown()


