# ================================================================
# MODULE 70  nebula_full_system_test.py  — Full System Integration Test
# ================================================================
# End-to-end integration tests for all major features.

import time, threading

class FullSystemTester:
    """
    Full NEBULA system integration test.
    Tests all major subsystems in an end-to-end scenario.
    """

    def __init__(self):
        self.bc       = NEBULABlockchain()
        self.results  : List[dict] = []
        self._passed  = 0
        self._failed  = 0

    def _record(self, name: str, ok: bool, detail: str = ""):
        self.results.append({"test": name, "ok": ok, "detail": detail})
        if ok:
            self._passed += 1
        else:
            self._failed += 1

    def run_all(self) -> dict:
        """Run all integration tests"""
        start = time.time()

        # 1. Blockchain basics
        try:
            h = self.bc.height
            self._record("Blockchain genesis", h >= 0)
        except Exception as e:
            self._record("Blockchain genesis", False, str(e))

        # 2. Wallet creation
        try:
            wallet = NEBULAWallet.create_new(self.bc.utxo)
            ok     = wallet.first_address.startswith(PUBKEY_ADDRESS_PREFIX)
            self._record("HD Wallet creation", ok, wallet.first_address[:20])
        except Exception as e:
            self._record("HD Wallet creation", False, str(e))
            wallet = None

        # 3. Mining a block
        try:
            addr  = wallet.first_address if wallet else FOUNDATION_ADDRESS
            miner = NEBULAMiner(self.bc, addr)
            blk   = miner.mine_demo_block(easy_bits=0x1f7fffff, timeout_secs=15)
            ok    = blk is not None and self.bc.add_block(blk)[0]
            self._record("Mine + add block", ok,
                          f"Height={self.bc.height}")
        except Exception as e:
            self._record("Mine + add block", False, str(e))

        # 4. Balance check
        try:
            if wallet:
                bal = self.bc.utxo.balance(wallet.first_address)
                self._record("Balance after mining", bal > 0,
                              f"{bal/10**DECIMALS:.9f} NBL")
        except Exception as e:
            self._record("Balance after mining", False, str(e))

        # 5. Send transaction
        try:
            if wallet and self.bc.height > 0:
                wallet2 = NEBULAWallet.create_new(self.bc.utxo)
                tx      = wallet.build_transaction(
                              wallet2.first_address, 1.0)
                if tx:
                    ok, msg = self.bc.mempool.submit(tx)
                    self._record("Create + submit tx", ok, msg)
                else:
                    self._record("Create + submit tx", False, "build_transaction returned None")
        except Exception as e:
            self._record("Create + submit tx", False, str(e))

        # 6. AMM pool
        try:
            amm = AMMEngine(self.bc)
            amm.create_pool("NBL", "USDT")
            lp, _ = amm.add_liquidity("p1", "NBL", "USDT",
                                       10000*10**DECIMALS, 1000*10**DECIMALS)
            out, _ = amm.swap("trader", "NBL", "USDT", 100*10**DECIMALS)
            self._record("AMM add liquidity + swap", lp > 0 and out > 0,
                          f"LP={lp}, Out={out/10**DECIMALS:.4f}")
        except Exception as e:
            self._record("AMM add liquidity + swap", False, str(e))

        # 7. Staking
        try:
            staking = StakingEngine(self.bc)
            ok, msg = staking.stake(
                FOUNDATION_ADDRESS, FOUNDATION_ADDRESS,
                STAKING_MIN_AMOUNT, current_height=self.bc.height)
            self._record("Stake NBL", ok, msg)
        except Exception as e:
            self._record("Stake NBL", False, str(e))

        # 8. Oracle price
        try:
            oracle = PriceOracle(self.bc)
            price  = oracle.get_nbl_usd()
            self._record("Oracle price feed", price is not None and price > 0,
                          f"NBL/USD = ${price:.4f}")
        except Exception as e:
            self._record("Oracle price feed", False, str(e))

        # 9. NFT mint
        try:
            nfts  = NFTEngine(self.bc)
            col   = nfts.create_collection(FOUNDATION_ADDRESS, "Genesis", "GEN", 100)
            meta  = NFTMetadata("Genesis #1", "First NFT", "ipfs://QmXxx")
            ok, nft = nfts.mint(col.address, FOUNDATION_ADDRESS, meta,
                                  current_height=self.bc.height)
            self._record("NFT mint", ok, f"Token #{nft.token_id if nft else '?'}")
        except Exception as e:
            self._record("NFT mint", False, str(e))

        # 10. DEX order
        try:
            dex = DEXEngine()
            oid, trades = dex.place_order(
                FOUNDATION_ADDRESS, "NBL/USDT",
                "sell", "limit", 0.10, 100*10**DECIMALS)
            self._record("DEX place order", bool(oid), f"Order {oid[:8]}...")
        except Exception as e:
            self._record("DEX place order", False, str(e))

        # 11. Governance proposal
        try:
            gov  = GovernanceEngine(self.bc)
            ok, pid = gov.submit_proposal(
                FOUNDATION_ADDRESS, "Test",
                "Integration test proposal", GOV_MIN_DEPOSIT_NBL)
            self._record("Governance proposal", ok, f"Proposal #{pid}")
        except Exception as e:
            self._record("Governance proposal", False, str(e))

        # 12. ECIES messaging
        try:
            privkey = 0xdeadbeef12345678
            pubkey  = Secp256k1.pubkey_to_bytes(
                          Secp256k1.point_mul(privkey, Secp256k1.G()))
            enc = ECIES.encrypt(b"Hello NEBULA!", pubkey)
            dec = ECIES.decrypt(enc, privkey)
            self._record("ECIES messaging", dec == b"Hello NEBULA!")
        except Exception as e:
            self._record("ECIES messaging", False, str(e))

        # 13. Atomic swap
        try:
            engine = AtomicSwapEngine(self.bc)
            swap   = engine.initiate_swap("alice", "bob",
                                           5*10**DECIMALS, 50000, "BTC")
            ok, _  = engine.claim_swap(swap.swap_id,
                                        bytes.fromhex(swap.preimage.hex()))
            self._record("Atomic swap claim", ok)
        except Exception as e:
            self._record("Atomic swap claim", False, str(e))

        # 14. Block reward simulation
        try:
            sim = BlockRewardSimulator()
            sch = sim.full_emission_schedule()
            self._record("Reward simulator", len(sch) > 0,
                          f"{len(sch)} eras total")
        except Exception as e:
            self._record("Reward simulator", False, str(e))

        elapsed = time.time() - start
        return {
            "passed"  : self._passed,
            "failed"  : self._failed,
            "total"   : len(self.results),
            "pct"     : f"{self._passed/max(1,len(self.results))*100:.0f}%",
            "elapsed" : f"{elapsed:.2f}s",
            "results" : self.results,
        }

    def print_report(self):
        """Print formatted test report"""
        result = self.run_all()
        print("\n" + "="*60)
        print("  🔧 NEBULA Full System Integration Test")
        print("="*60)
        for r in result["results"]:
            icon = "✅" if r["ok"] else "❌"
            print(f"  {icon} {r['test']:40} {r.get('detail', '')[:20]}")
        print("="*60)
        print(f"  TOTAL: {result['passed']}/{result['total']} "
              f"({result['pct']}) in {result['elapsed']}")
        print("="*60)

