# ================================================================
# MODULE 71  nebula_security_audit.py  — Security Audit Framework
# ================================================================
# Security audit tools: vulnerability scanner, crypto parameter
# checker, consensus rule verifier, network attack detector.

import threading, time, hashlib
from typing import Dict, List, Tuple, Optional
from dataclasses import dataclass, field
from enum import Enum

class Severity(Enum):
    CRITICAL = "critical"
    HIGH     = "high"
    MEDIUM   = "medium"
    LOW      = "low"
    INFO     = "info"

@dataclass
class Finding:
    """A security audit finding"""
    severity    : Severity
    category    : str
    title       : str
    description : str
    location    : str = ""
    remediation : str = ""
    timestamp   : float = field(default_factory=time.time)

    def to_dict(self) -> dict:
        return {
            "severity"    : self.severity.value,
            "category"    : self.category,
            "title"       : self.title,
            "description" : self.description,
            "remediation" : self.remediation,
        }

class SecurityAuditor:
    """
    Automated security audit framework for NEBULA node.
    Checks: cryptographic parameters, consensus rules,
    network security, wallet security, smart contract safety.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc       = blockchain
        self._findings: List[Finding] = []

    def _add(self, sev: Severity, cat: str, title: str,
              desc: str, remedy: str = ""):
        self._findings.append(Finding(
            severity=sev, category=cat, title=title,
            description=desc, remediation=remedy))

    def audit_crypto_params(self):
        """Verify cryptographic parameters"""
        # Check secp256k1 constants
        if Secp256k1.P != 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F:
            self._add(Severity.CRITICAL, "crypto",
                      "Invalid secp256k1 prime",
                      "P parameter does not match secp256k1 standard")
        else:
            self._add(Severity.INFO, "crypto",
                      "secp256k1 prime correct", "P = 0xFFFF...FC2F ✅")

        if Secp256k1.N != 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141:
            self._add(Severity.CRITICAL, "crypto",
                      "Invalid secp256k1 order",
                      "N parameter does not match standard")
        else:
            self._add(Severity.INFO, "crypto",
                      "secp256k1 order correct", "N verified ✅")

    def audit_consensus_rules(self):
        """Verify consensus parameters"""
        # Check MAX_SUPPLY math
        expected = INITIAL_BLOCK_REWARD * HALVING_INTERVAL * 2
        if expected != 21_000_000 * 10**DECIMALS:
            self._add(Severity.HIGH, "consensus",
                      "MAX_SUPPLY mismatch",
                      f"Expected {21_000_000 * 10**DECIMALS}, got {expected}")
        else:
            self._add(Severity.INFO, "consensus",
                      "MAX_SUPPLY formula correct", "21M NBL ✅")

        # Check Foundation rate
        if FOUNDATION_RATE > 0.10:
            self._add(Severity.HIGH, "economics",
                      "Foundation rate too high",
                      f"Rate {FOUNDATION_RATE*100}% exceeds 10% limit",
                      "Reduce FOUNDATION_RATE to ≤ 10%")
        else:
            self._add(Severity.INFO, "economics",
                      "Foundation rate within limits",
                      f"{FOUNDATION_RATE*100}% ≤ 10% ✅")

        # Check block time
        if TARGET_BLOCK_TIME < 60:
            self._add(Severity.MEDIUM, "consensus",
                      "Block time too short",
                      "Short block time increases orphan rate",
                      "Consider TARGET_BLOCK_TIME ≥ 60s")

    def audit_chain_integrity(self):
        """Verify chain integrity"""
        chain = self.bc._chain
        if len(chain) < 2:
            return

        errors = 0
        for i in range(1, len(chain)):
            blk  = chain[i]
            prev = chain[i-1]
            if blk.header.prev_hash != prev.hash:
                errors += 1
                self._add(Severity.CRITICAL, "chain",
                          f"Chain break at height {blk.height}",
                          f"Block {blk.height} prev_hash mismatch")
                if errors > 3:
                    break

        if errors == 0:
            self._add(Severity.INFO, "chain",
                      "Chain integrity verified",
                      f"All {len(chain)-1} links valid ✅")

    def audit_utxo_set(self):
        """Verify UTXO set consistency"""
        total   = self.bc.utxo.total_supply()
        issued  = sum(mining_reward(h) for h in range(self.bc.height + 1))

        if total > MAX_SUPPLY:
            self._add(Severity.CRITICAL, "utxo",
                      "Supply exceeds maximum",
                      f"UTXO supply {total/10**DECIMALS} > {MAX_SUPPLY/10**DECIMALS}")
        elif total > issued:
            self._add(Severity.HIGH, "utxo",
                      "UTXO supply exceeds issued",
                      f"Possible inflation bug: {total/10**DECIMALS} > {issued/10**DECIMALS}")
        else:
            self._add(Severity.INFO, "utxo",
                      "UTXO supply consistent",
                      f"{total/10**DECIMALS:.9f} NBL ≤ issued {issued/10**DECIMALS:.9f} ✅")

    def audit_mempool_policy(self):
        """Check mempool policy settings"""
        if MIN_TX_FEE == 0:
            self._add(Severity.HIGH, "mempool",
                      "Zero minimum fee",
                      "Zero fee allows DoS via mempool flooding",
                      "Set MIN_TX_FEE ≥ 1000 (1 neb/byte)")
        else:
            self._add(Severity.INFO, "mempool",
                      "Minimum fee set",
                      f"MIN_TX_FEE = {MIN_TX_FEE} ✅")

    def full_audit(self) -> dict:
        """Run complete security audit"""
        self._findings.clear()
        self.audit_crypto_params()
        self.audit_consensus_rules()
        self.audit_chain_integrity()
        self.audit_utxo_set()
        self.audit_mempool_policy()

        by_severity: Dict[str, int] = {}
        for f in self._findings:
            by_severity[f.severity.value] = by_severity.get(f.severity.value, 0) + 1

        return {
            "audit_time"  : time.time(),
            "chain_height": self.bc.height,
            "total"       : len(self._findings),
            "by_severity" : by_severity,
            "findings"    : [f.to_dict() for f in self._findings],
            "score"       : self._security_score(),
        }

    def _security_score(self) -> int:
        """0-100 security score"""
        score    = 100
        weights  = {Severity.CRITICAL: 25, Severity.HIGH: 10,
                    Severity.MEDIUM: 5,    Severity.LOW: 2}
        for f in self._findings:
            if f.severity != Severity.INFO:
                score -= weights.get(f.severity, 0)
        return max(0, score)

    def print_report(self):
        """Print audit report to console"""
        report = self.full_audit()
        print("\n" + "="*60)
        print("  🔒 NEBULA Security Audit Report")
        print("="*60)
        print(f"  Score: {report['score']}/100")
        print(f"  Findings: {report['total']} total")
        for sev, count in report['by_severity'].items():
            icons = {"critical":"🔴","high":"🟠","medium":"🟡","low":"🟢","info":"⚪"}
            print(f"  {icons.get(sev,'  ')} {sev.upper()}: {count}")
        print("\n  Findings:")
        for f in report['findings']:
            if f['severity'] != 'info':
                print(f"  [{f['severity'].upper()}] {f['title']}")
                print(f"         {f['description'][:60]}")
        print("="*60)


# ================================================================
# MODULE 72  nebula_performance.py  — Performance Benchmarks
# ================================================================
# Performance benchmarks: hash rate, signature speed,
# block validation, UTXO lookup, mempool throughput.

import time, threading
from typing import Dict, List, Callable, Optional

@dataclass
class BenchmarkResult:
    name       : str
    ops_per_sec: float
    avg_ms     : float
    total_ms   : float
    iterations : int

    def to_dict(self) -> dict:
        return {
            "name"        : self.name,
            "ops_per_sec" : f"{self.ops_per_sec:,.0f}",
            "avg_ms"      : f"{self.avg_ms:.3f}",
            "total_ms"    : f"{self.total_ms:.1f}",
            "iterations"  : self.iterations,
        }

class PerformanceBenchmark:
    """
    NEBULA performance benchmark suite.
    Measures: crypto ops, block validation, UTXO operations.
    """

    def __init__(self, blockchain: 'NEBULABlockchain' = None):
        self.bc = blockchain

    def _bench(self, name: str, fn: Callable,
               iterations: int = 100) -> BenchmarkResult:
        """Run benchmark and return result"""
        start = time.time()
        for _ in range(iterations):
            fn()
        elapsed  = (time.time() - start) * 1000
        avg_ms   = elapsed / iterations
        ops_s    = iterations / (elapsed / 1000)
        return BenchmarkResult(name, ops_s, avg_ms, elapsed, iterations)

    def bench_sha256(self, iters: int = 10_000) -> BenchmarkResult:
        """SHA-256 hash performance"""
        data = b"A" * 256
        return self._bench("SHA-256",
                            lambda: hashlib.sha256(data).digest(), iters)

    def bench_sha256d(self, iters: int = 5_000) -> BenchmarkResult:
        """Double SHA-256 (PoW) performance"""
        data = b"B" * 80
        return self._bench("SHA-256d (PoW)",
                            lambda: hashlib.sha256(hashlib.sha256(data).digest()).digest(),
                            iters)

    def bench_ecdsa_sign(self, iters: int = 100) -> BenchmarkResult:
        """ECDSA signature performance"""
        privkey = 0xdeadbeef12345678
        msg     = hashlib.sha256(b"bench").digest()
        return self._bench("ECDSA sign",
                            lambda: Secp256k1.sign(privkey, msg), iters)

    def bench_ecdsa_verify(self, iters: int = 50) -> BenchmarkResult:
        """ECDSA verification performance"""
        privkey = 0xdeadbeef12345678
        msg     = hashlib.sha256(b"bench").digest()
        r, s    = Secp256k1.sign(privkey, msg)
        pubkey  = Secp256k1.pubkey_to_bytes(
                      Secp256k1.point_mul(privkey, Secp256k1.G()))
        return self._bench("ECDSA verify",
                            lambda: Secp256k1.verify(pubkey, msg, r, s), iters)

    def bench_address_generation(self, iters: int = 200) -> BenchmarkResult:
        """Address generation performance"""
        privkey = 0xdeadbeef12345678
        return self._bench("Address gen",
                            lambda: Script.p2pkh_address(
                                Secp256k1.pubkey_to_bytes(
                                    Secp256k1.point_mul(privkey, Secp256k1.G()))),
                            iters)

    def bench_bip39_derivation(self, iters: int = 5) -> BenchmarkResult:
        """BIP39 seed derivation performance"""
        mnemonic = "abandon " * 11 + "about"
        return self._bench("BIP39 seed derive",
                            lambda: BIP39.mnemonic_to_seed(mnemonic), iters)

    def bench_base58check(self, iters: int = 1_000) -> BenchmarkResult:
        """Base58Check encode/decode performance"""
        data = bytes(20)
        return self._bench("Base58Check encode",
                            lambda: base58check_encode(data, PUBKEY_ADDRESS_VERSION),
                            iters)

    def bench_utxo_lookup(self, iters: int = 1_000) -> BenchmarkResult:
        """UTXO set lookup performance"""
        bc   = self.bc or NEBULABlockchain()
        txid = bc.tip.hash if bc.height >= 0 else "a" * 64
        return self._bench("UTXO lookup",
                            lambda: bc.utxo.get(txid, 0), iters)

    def run_all(self) -> dict:
        """Run all benchmarks"""
        benchmarks = [
            self.bench_sha256,
            self.bench_sha256d,
            self.bench_ecdsa_sign,
            self.bench_ecdsa_verify,
            self.bench_address_generation,
            self.bench_base58check,
            self.bench_utxo_lookup,
        ]
        results = []
        for bench in benchmarks:
            try:
                r = bench()
                results.append(r.to_dict())
            except Exception as e:
                results.append({"name": bench.__name__, "error": str(e)})

        return {
            "platform"   : "Python (mobile)",
            "timestamp"  : time.time(),
            "benchmarks" : results,
        }

    def print_report(self):
        """Print formatted benchmark report"""
        data = self.run_all()
        print("\n" + "="*60)
        print("  ⚡ NEBULA Performance Benchmarks")
        print("="*60)
        print(f"  {'Benchmark':35} {'ops/sec':>12} {'avg ms':>8}")
        print("  " + "─"*60)
        for r in data["benchmarks"]:
            if "error" not in r:
                print(f"  {r['name']:35} {r['ops_per_sec']:>12} {r['avg_ms']:>8}")
            else:
                print(f"  {r['name']:35} ERROR: {r['error'][:20]}")
        print("="*60)


