# MODULE 73  nebula_historical_data.py  — Historical Data Manager
# ================================================================
# Store and query historical on-chain data: price history,
# hash rate history, tx volume, active addresses.

import threading, time
from typing import Dict, List, Optional, Tuple
from collections import deque
from dataclasses import dataclass, field

@dataclass
class HistoricalPoint:
    """A single historical data point"""
    timestamp : float
    height    : int
    value     : float
    extra     : dict = field(default_factory=dict)

class HistoricalTimeSeries:
    """Time series for historical blockchain metrics"""

    def __init__(self, name: str, max_points: int = 10_000):
        self.name       = name
        self.max_points = max_points
        self._data      : deque = deque(maxlen=max_points)
        self._lock      = threading.Lock()

    def append(self, value: float, height: int = 0,
                extra: dict = None):
        with self._lock:
            self._data.append(HistoricalPoint(
                timestamp = time.time(),
                height    = height,
                value     = value,
                extra     = extra or {},
            ))

    def get_range(self, start_ts: float = 0,
                   end_ts: float = None) -> List[HistoricalPoint]:
        end_ts = end_ts or time.time()
        with self._lock:
            return [p for p in self._data
                    if start_ts <= p.timestamp <= end_ts]

    def last_n(self, n: int) -> List[HistoricalPoint]:
        with self._lock:
            return list(self._data)[-n:]

    def aggregate_hourly(self) -> List[dict]:
        """Aggregate into hourly candles"""
        points = list(self._data)
        if not points:
            return []
        buckets: Dict[int, List[float]] = {}
        for p in points:
            hour = int(p.timestamp // 3600) * 3600
            buckets.setdefault(hour, []).append(p.value)

        candles = []
        for ts in sorted(buckets):
            vals = buckets[ts]
            candles.append({
                "timestamp": ts,
                "open"     : vals[0],
                "high"     : max(vals),
                "low"      : min(vals),
                "close"    : vals[-1],
                "avg"      : sum(vals)/len(vals),
                "count"    : len(vals),
            })
        return candles

    def stats(self) -> dict:
        with self._lock:
            vals = [p.value for p in self._data]
        if not vals:
            return {"empty": True}
        import statistics as _s
        return {
            "name"    : self.name,
            "count"   : len(vals),
            "latest"  : vals[-1],
            "min"     : min(vals),
            "max"     : max(vals),
            "avg"     : round(_s.mean(vals), 4),
            "stdev"   : round(_s.stdev(vals), 4) if len(vals) > 1 else 0,
        }

class HistoricalDataManager:
    """
    Manages all historical data series for NEBULA.
    Tracks: price, hashrate, tx volume, fees, active addresses.
    """

    SERIES = ["nbl_usd", "hashrate_mhs", "tx_count", "avg_fee",
              "active_addrs", "block_time", "mempool_size",
              "staked_nbl", "amm_tvl", "difficulty"]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc      = blockchain
        self._series : Dict[str, HistoricalTimeSeries] = {
            name: HistoricalTimeSeries(name)
            for name in self.SERIES
        }
        self._lock   = threading.Lock()
        self._running= False

    def record_point(self, series_name: str, value: float,
                      height: int = 0):
        """Record a data point"""
        if series_name in self._series:
            self._series[series_name].append(value, height)

    def get_series(self, name: str,
                    last_n: int = 100) -> List[dict]:
        """Get last N points from a series"""
        ts = self._series.get(name)
        if not ts:
            return []
        return [{"ts": p.timestamp, "v": p.value, "h": p.height}
                for p in ts.last_n(last_n)]

    def get_all_stats(self) -> dict:
        """Get stats for all series"""
        return {name: ts.stats() for name, ts in self._series.items()}

    def snapshot(self, oracle: 'PriceOracle' = None):
        """Take a full snapshot of current state"""
        h = self.bc.height
        self.record_point("mempool_size", self.bc.mempool.size(), h)
        chain = self.bc._chain
        if len(chain) >= 2:
            bt = (chain[-1].header.timestamp - chain[-2].header.timestamp)
            self.record_point("block_time", bt, h)
        if oracle:
            price = oracle.get_nbl_usd()
            if price:
                self.record_point("nbl_usd", price, h)

    def start_collection(self, interval: float = 60.0,
                          oracle: 'PriceOracle' = None):
        """Start background data collection"""
        self._running = True
        def _collect():
            while self._running:
                try:
                    self.snapshot(oracle)
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in HistoricalDataManager.start_collection._collect", exc_info=True)
                time.sleep(interval)
        threading.Thread(target=_collect, daemon=True,
                          name="HistData").start()

    def stop(self): self._running = False

    def export_csv(self, series_name: str) -> str:
        """Export series as CSV"""
        ts     = self._series.get(series_name)
        if not ts:
            return ""
        header = "timestamp,height,value\n"
        rows   = "\n".join(f"{p.timestamp:.0f},{p.height},{p.value}"
                           for p in ts._data)
        return header + rows


