# MODULE 74  nebula_advanced_mining.py  — Advanced Mining Features
# ================================================================
# Advanced mining: getwork, template caching, vardiff,
# merged mining, mining profitability calculator.

import threading, time, hashlib, struct, secrets
from typing import Dict, List, Optional, Tuple

class MiningDifficulty:
    """
    Variable difficulty (vardiff) for mining pools.
    Adjusts per-worker difficulty to maintain target share rate.
    """

    TARGET_SHARE_TIME = 15.0   # target seconds between shares
    RETARGET_INTERVAL = 10     # retarget every N shares
    MIN_DIFF          = 0.001
    MAX_DIFF          = 1000.0

    def __init__(self, initial_diff: float = 1.0):
        self._diffs      : Dict[str, float] = {}
        self._last_share : Dict[str, float] = {}
        self._share_count: Dict[str, int]   = {}
        self._lock       = threading.Lock()
        self.initial_diff = initial_diff

    def get_difficulty(self, worker_id: str) -> float:
        with self._lock:
            return self._diffs.get(worker_id, self.initial_diff)

    def record_share(self, worker_id: str):
        """Record a share and adjust difficulty"""
        with self._lock:
            now       = time.time()
            last      = self._last_share.get(worker_id, now)
            count     = self._share_count.get(worker_id, 0) + 1
            self._last_share[worker_id]  = now
            self._share_count[worker_id] = count

            if count % self.RETARGET_INTERVAL == 0 and count > 0:
                elapsed   = now - last
                avg_time  = elapsed / self.RETARGET_INTERVAL
                current   = self._diffs.get(worker_id, self.initial_diff)
                new_diff  = current * avg_time / self.TARGET_SHARE_TIME
                new_diff  = max(self.MIN_DIFF, min(self.MAX_DIFF, new_diff))
                self._diffs[worker_id] = new_diff
                return new_diff
        return None

    def get_bits(self, worker_id: str) -> int:
        """Get difficulty as bits value for the worker"""
        diff    = self.get_difficulty(worker_id)
        target  = int(bits_to_target(INITIAL_BITS) / max(0.0001, diff))
        # Convert target back to bits
        nbytes  = (target.bit_length() + 7) // 8
        mantissa= target >> (8 * (nbytes - 3))
        return (nbytes << 24) | mantissa


class GetWorkServer:
    """
    Legacy getwork protocol server.
    Older miners use getwork; newer use stratum.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 miner_address: str = FOUNDATION_ADDRESS):
        self.bc      = blockchain
        self.address = miner_address
        self._cache  : Optional[dict] = None
        self._cache_height = -1
        self._lock   = threading.Lock()

    def get_work(self) -> dict:
        """Return current work for miner"""
        with self._lock:
            if self._cache_height != self.bc.height:
                self._cache        = self._build_work()
                self._cache_height = self.bc.height
            return dict(self._cache)

    def _build_work(self) -> dict:
        """Build work from current block template"""
        prev_hash = self.bc.tip.hash
        ts        = int(time.time())
        bits      = self.bc.get_next_bits()
        cb_hash   = hashlib.sha256(b"coinbase").hexdigest()
        return {
            "data"         : prev_hash + "0" * 128,
            "target"       : f"{bits_to_target(bits):064x}",
            "hash1"        : "0" * 64 + "0100" + "0" * 120,
            "midstate"     : "0" * 64,
            "height"       : self.bc.height + 1,
            "bits"         : f"{bits:08x}",
            "timestamp"    : ts,
        }

    def submit_work(self, data: str) -> bool:
        """Process submitted work"""
        try:
            nonce = int(data[-8:], 16)
            header_hex = data[:160]
            hash_val = hashlib.sha256(
                hashlib.sha256(
                    bytes.fromhex(header_hex)).digest()).hexdigest()
            target = bits_to_target(self.bc.get_next_bits())
            return int(hash_val, 16) <= target
        except Exception:
            return False


class MiningProfitCalc:
    """
    Mining profitability calculator.
    Estimates daily/monthly earnings based on hashrate.
    """

    def __init__(self, oracle: 'PriceOracle' = None):
        self.oracle = oracle

    def calculate(self, hashrate_mhs: float,
                   power_watts: float = 0,
                   electricity_cost_usd: float = 0.10,
                   blockchain: 'NEBULABlockchain' = None) -> dict:
        """
        Calculate mining profitability.
        hashrate_mhs: miner's hashrate in MH/s
        power_watts: power consumption
        electricity_cost_usd: cost per kWh in USD
        """
        bc              = blockchain or NEBULABlockchain()
        network_hash    = 1.0   # MH/s (estimated)
        block_reward    = mining_reward(bc.height) / 10**DECIMALS

        # Your share of network hashrate
        hash_share      = hashrate_mhs / max(0.001, network_hash)

        # Blocks per day (144 blocks at 10 min)
        blocks_per_day  = 86400 / TARGET_BLOCK_TIME
        daily_nbl       = hash_share * blocks_per_day * block_reward

        # Daily power cost
        daily_kwh       = power_watts * 24 / 1000
        daily_power_usd = daily_kwh * electricity_cost_usd

        # Get NBL price
        nbl_usd         = (self.oracle.get_nbl_usd()
                           if self.oracle else 0.10)
        daily_revenue   = daily_nbl * (nbl_usd or 0.10)
        daily_profit    = daily_revenue - daily_power_usd

        return {
            "hashrate_mhs"      : hashrate_mhs,
            "network_share"     : f"{hash_share*100:.6f}%",
            "daily_nbl"         : round(daily_nbl, 9),
            "monthly_nbl"       : round(daily_nbl * 30, 9),
            "nbl_usd_price"     : nbl_usd,
            "daily_revenue_usd" : round(daily_revenue, 4),
            "daily_power_usd"   : round(daily_power_usd, 4),
            "daily_profit_usd"  : round(daily_profit, 4),
            "monthly_profit_usd": round(daily_profit * 30, 4),
            "break_even_nbl_usd": (daily_power_usd / max(0.001, daily_nbl)
                                    if daily_nbl > 0 else float('inf')),
        }


