# MODULE 75  nebula_final_integration.py  — Final Integration Layer
# ================================================================
# The final integration module that ties all 75 modules together.
# Creates the unified NEBULA ecosystem object.

import threading, time
from typing import Optional, Dict

class NEBULAEcosystem:
    """
    The NEBULA Ecosystem — all 75 modules integrated.
    One object to rule them all.
    Author: NEBULA Core Team
    """

    VERSION         = "1.0.0"
    MODULE_COUNT    = 75
    TOTAL_LINES     = 50_000

    BANNER = """
╔══════════════════════════════════════════════════════════════════╗
║                                                                  ║
║          🌌  N E B U L A  B L O C K C H A I N  v1.0.0          ║
║                                                                  ║
║          Author    : NEBULA Core Team                                ║
║          Modules   : 75                                          ║
║          Language  : Pure Python                                 ║
║          Platform : Python 3                                ║
║          Symbol    : NBL                                         ║
║          Max Supply: 21,000,000 NBL                              ║
║                                                                  ║
╚══════════════════════════════════════════════════════════════════╝
"""

    def __init__(self):
        # Core
        self.blockchain     = NEBULABlockchain()

        # Financial
        self.oracle         = PriceOracle(self.blockchain)
        self.amm            = AMMEngine(self.blockchain)
        self.dex            = DEXEngine()
        self.staking        = StakingEngine(self.blockchain)

        # Governance & DeFi
        self.governance     = GovernanceEngine(self.blockchain, self.staking)
        self.lending        = LendingProtocol(self.blockchain)
        self.bridge         = TokenBridge(self.blockchain)

        # Analytics & Monitoring
        self.analytics      = AnalyticsDashboard(self.blockchain)
        self.historical     = HistoricalDataManager(self.blockchain)
        self.auditor        = SecurityAuditor(self.blockchain)
        self.benchmarks     = PerformanceBenchmark(self.blockchain)
        self.mempool_viz    = MempoolVisualizer(self.blockchain)
        self.indexer        = ChainIndexer()
        self.net_stats      = RealTimeNetworkStats(self.blockchain, self.oracle)
        self.reward_sim     = BlockRewardSimulator()

        # Infrastructure
        self.rpc            = NEBULAJSONRPCServerLegacy(self.blockchain)
        self.api            = BlockchainAPI(self.blockchain, self.oracle)
        self.pool           = MiningPool(self.blockchain)
        self.watchdog       = NodeWatchdog(self.blockchain)

        # NFT & Tokens
        self.nft_engine     = NFTEngine(self.blockchain)

        # Mining
        self.profit_calc    = MiningProfitCalc(self.oracle)
        self.vardiff        = MiningDifficulty()

        # Wallet tools
        self.address_book   = AddressBook()
        self.wallet_connect = WalletConnectHandler()
        self.tx_graph       = TxGraphAnalyzer()
        self.fee_bumper     = FeeBumper(self.blockchain)

        # Protocol
        self.version_bits   = VersionBitsState()
        self.checkpoint_val = CheckpointValidator()
        self.protocol_docs  = ProtocolDocGenerator()
        self.pruner         = BlockPruner(self.blockchain)

        self._start_time    = time.time()

    def start(self, mine: bool = False,
               miner_address: str = None,
               start_rpc: bool = True,
               start_api: bool = True):
        """Start the full NEBULA ecosystem"""
        print(self.BANNER)

        # Start background services
        self.oracle.start()
        self.watchdog.start()
        self.historical.start_collection(60, self.oracle)
        self.net_stats.start()

        if start_rpc:
            try: self.rpc.start()
            except Exception as e: print(f"  ⚠️  RPC: {e}")

        if start_api:
            try: self.api.start()
            except Exception as e: print(f"  ⚠️  API: {e}")

        if mine and miner_address:
            self._start_background_miner(miner_address)

        # Initialize AMM default pools
        self._init_defi()

        print(f"  ✅ NEBULA Ecosystem started!")
        print(f"  Modules   : {self.MODULE_COUNT}")
        print(f"  Height    : {self.blockchain.height}")
        print(f"  UTXOs     : {self.blockchain.utxo.size():,}")

    def _init_defi(self):
        """Initialize default DeFi pools"""
        try:
            pairs = [("NBL", "USDT"), ("NBL", "BTC"), ("NBL", "ETH")]
            for a, b in pairs:
                self.amm.create_pool(a, b)
            for pair in ["NBL/USDT", "NBL/BTC", "NBL/ETH"]:
                if pair not in self.dex._books:
                    self.dex._books[pair] = OrderBook(pair)
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULAEcosystem._init_defi", exc_info=True)

    def _start_background_miner(self, address: str):
        """Start background solo miner"""
        def _mine():
            miner = NEBULAMiner(self.blockchain, address)
            while True:
                try:
                    miner.mine_one_block()
                except Exception:
                    time.sleep(1)
        threading.Thread(target=_mine, daemon=True, name="Miner").start()
        print(f"  ⛏️  Mining to: {address[:20]}...")

    def stop(self):
        """Graceful shutdown"""
        self.oracle.stop()
        self.watchdog.stop()
        self.historical.stop()
        self.net_stats.stop()
        try:
            self.rpc.stop()
            self.api.stop()
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in NEBULAEcosystem.stop", exc_info=True)
        print("  👋 NEBULA stopped")

    def quick_status(self) -> dict:
        """Quick status snapshot"""
        price = self.oracle.get_nbl_usd()
        return {
            "version"       : self.VERSION,
            "modules"       : self.MODULE_COUNT,
            "height"        : self.blockchain.height,
            "utxos"         : self.blockchain.utxo.size(),
            "supply_nbl"    : self.blockchain.utxo.total_supply() / 10**DECIMALS,
            "mempool"       : self.blockchain.mempool.size(),
            "amm_pools"     : len(self.amm._pools),
            "stakers"       : len(self.staking._stakes),
            "validators"    : len(self.staking._validators),
            "nfts_minted"   : sum(c.minted_count for c in self.nft_engine._collections.values()),
            "nbl_usd"       : price,
            "uptime"        : round(time.time() - self._start_time),
            "security_score": self.auditor._security_score(),
        }

    def run_system_test(self) -> dict:
        """Run full system integration test"""
        tester = FullSystemTester()
        result = tester.run_all()
        print(f"\n  System Test: {result['passed']}/{result['total']} "
              f"({result['pct']}) in {result['elapsed']}")
        return result

    def run_benchmark(self) -> dict:
        """Run performance benchmarks"""
        return self.benchmarks.run_all()

    def run_security_audit(self) -> dict:
        """Run security audit"""
        return self.auditor.full_audit()

    def print_emission_schedule(self):
        """Print NBL emission schedule"""
        self.reward_sim.print_schedule()

    def __repr__(self) -> str:
        return (f"<NEBULAEcosystem v{self.VERSION} "
                f"modules={self.MODULE_COUNT} "
                f"height={self.blockchain.height}>")


# ── Final entrypoint upgrade ──────────────────────────────────────
def _nebula_main_v2():
    """Enhanced main entrypoint with all 75 modules"""
    import sys
    args = sys.argv[1:]
    cmd  = args[0] if args else "info"

    if cmd == "ecosystem":
        eco = NEBULAEcosystem()
        eco.start(mine=False)
        print(eco.quick_status())
    elif cmd == "audit":
        bc  = NEBULABlockchain()
        aud = SecurityAuditor(bc)
        aud.print_report()
    elif cmd == "benchmark":
        bench = PerformanceBenchmark()
        bench.print_report()
