# ================================================================
# MODULE 76  nebula_p2p_gossip.py  — Gossip Protocol + Peer Routing
# ================================================================
# Epidemic gossip broadcast, Kademlia-style routing, peer scoring,
# message deduplication, flood fill with TTL.

import threading, time, hashlib, secrets
from typing import Dict, List, Set, Optional, Tuple, Callable
from dataclasses import dataclass, field
from collections import deque, defaultdict

# ── Gossip Constants ──────────────────────────────────────────────
GOSSIP_FAN_OUT          = 8      # forward to N peers
GOSSIP_TTL              = 5      # max hops
GOSSIP_DEDUPE_WINDOW    = 3600   # seconds to remember seen msgs
GOSSIP_MAX_QUEUE        = 10_000
KADEMLIA_K              = 20     # k-bucket size
KADEMLIA_ALPHA          = 3      # parallel lookups

@dataclass
class GossipMessage:
    """A message propagated via gossip"""
    msg_id      : str
    msg_type    : str   # "tx", "block", "addr", "custom"
    payload     : bytes
    sender      : str
    ttl         : int  = GOSSIP_TTL
    hops        : int  = 0
    created_at  : float = field(default_factory=time.time)

    def forward(self, new_sender: str) -> 'GossipMessage':
        """Create forwarded copy with decremented TTL"""
        return GossipMessage(
            msg_id   = self.msg_id,
            msg_type = self.msg_type,
            payload  = self.payload,
            sender   = new_sender,
            ttl      = self.ttl - 1,
            hops     = self.hops + 1,
            created_at = self.created_at,
        )

    @property
    def is_expired(self) -> bool:
        return self.ttl <= 0

    def to_dict(self) -> dict:
        return {
            "msg_id"  : self.msg_id,
            "type"    : self.msg_type,
            "ttl"     : self.ttl,
            "hops"    : self.hops,
            "size"    : len(self.payload),
        }

class MessageCache:
    """Deduplication cache for gossip messages"""

    def __init__(self, window_secs: float = GOSSIP_DEDUPE_WINDOW):
        self._seen     : Dict[str, float] = {}
        self._window   = window_secs
        self._lock     = threading.Lock()

    def is_seen(self, msg_id: str) -> bool:
        with self._lock:
            return msg_id in self._seen

    def mark_seen(self, msg_id: str):
        with self._lock:
            self._seen[msg_id] = time.time()

    def expire_old(self):
        cutoff = time.time() - self._window
        with self._lock:
            old = [k for k, t in self._seen.items() if t < cutoff]
            for k in old:
                del self._seen[k]

    def size(self) -> int:
        return len(self._seen)

class GossipRouter:
    """
    Gossip protocol router.
    Implements: fan-out gossip, TTL-limited flood fill,
    message deduplication, peer selection strategies.
    """

    def __init__(self, node_id: str,
                 send_fn: Callable = None):
        self.node_id    = node_id
        self._send      = send_fn or (lambda peer, msg: None)
        self._peers     : List[str] = []
        self._cache     = MessageCache()
        self._queue     : deque = deque(maxlen=GOSSIP_MAX_QUEUE)
        self._handlers  : Dict[str, List[Callable]] = defaultdict(list)
        self._lock      = threading.RLock()
        self._stats     = {"sent": 0, "received": 0, "dropped": 0, "duplicates": 0}

    def add_peer(self, peer_id: str):
        with self._lock:
            if peer_id not in self._peers:
                self._peers.append(peer_id)

    def remove_peer(self, peer_id: str):
        with self._lock:
            if peer_id in self._peers:
                self._peers.remove(peer_id)

    def register_handler(self, msg_type: str, fn: Callable):
        """Register handler for message type"""
        self._handlers[msg_type].append(fn)

    def broadcast(self, msg_type: str, payload: bytes) -> str:
        """Broadcast a new message to the network"""
        msg_id = hashlib.sha256(
            payload + self.node_id.encode() +
            str(time.time()).encode()).hexdigest()[:16]
        msg = GossipMessage(
            msg_id   = msg_id,
            msg_type = msg_type,
            payload  = payload,
            sender   = self.node_id,
        )
        self._cache.mark_seen(msg_id)
        self._forward(msg)
        return msg_id

    def receive(self, msg: GossipMessage) -> bool:
        """Process a received gossip message"""
        self._stats["received"] += 1

        # Deduplication
        if self._cache.is_seen(msg.msg_id):
            self._stats["duplicates"] += 1
            return False

        if msg.is_expired:
            self._stats["dropped"] += 1
            return False

        self._cache.mark_seen(msg.msg_id)

        # Dispatch to handlers
        for handler in self._handlers.get(msg.msg_type, []):
            try:
                handler(msg)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in GossipRouter.receive", exc_info=True)

        # Forward to peers
        self._forward(msg.forward(self.node_id))
        return True

    def _forward(self, msg: GossipMessage):
        """Forward message to fan-out peers"""
        with self._lock:
            peers = list(self._peers)

        import random
        selected = random.sample(peers, min(GOSSIP_FAN_OUT, len(peers)))
        for peer in selected:
            if peer != msg.sender:
                try:
                    self._send(peer, msg)
                    self._stats["sent"] += 1
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in GossipRouter._forward", exc_info=True)

    def stats(self) -> dict:
        self._cache.expire_old()
        return {
            "node_id"   : self.node_id,
            "peers"     : len(self._peers),
            "cache_size": self._cache.size(),
            **self._stats,
        }

class KademliaNode:
    """
    Kademlia DHT for peer discovery and routing.
    Used for: finding peers, storing/retrieving values,
    NAT traversal, bootstrap node lookup.
    """

    def __init__(self, node_id: bytes = None):
        self.node_id = node_id or secrets.token_bytes(32)
        self._buckets: List[List[Tuple[bytes, str]]] = [
            [] for _ in range(256)
        ]
        self._values : Dict[bytes, bytes] = {}
        self._lock   = threading.RLock()

    def _distance(self, a: bytes, b: bytes) -> int:
        """XOR distance between two node IDs"""
        return int.from_bytes(
            bytes(x ^ y for x, y in zip(a, b)), 'big')

    def _bucket_index(self, node_id: bytes) -> int:
        """Which k-bucket for this node ID"""
        dist = self._distance(self.node_id, node_id)
        if dist == 0:
            return 0
        return min(255, dist.bit_length() - 1)

    def add_node(self, node_id: bytes, address: str):
        """Add node to routing table"""
        idx = self._bucket_index(node_id)
        with self._lock:
            bucket = self._buckets[idx]
            # Remove if already present
            bucket[:] = [(nid, addr) for nid, addr in bucket
                         if nid != node_id]
            # Add to front
            bucket.insert(0, (node_id, address))
            # Trim to K
            if len(bucket) > KADEMLIA_K:
                bucket[:] = bucket[:KADEMLIA_K]

    def find_closest(self, target: bytes,
                      k: int = KADEMLIA_K) -> List[Tuple[bytes, str]]:
        """Find k closest nodes to target"""
        with self._lock:
            all_nodes = [(nid, addr)
                         for bucket in self._buckets
                         for nid, addr in bucket]
        all_nodes.sort(key=lambda x: self._distance(x[0], target))
        return all_nodes[:k]

    def store(self, key: bytes, value: bytes):
        """Store key-value in DHT"""
        with self._lock:
            self._values[key] = value

    def retrieve(self, key: bytes) -> Optional[bytes]:
        """Retrieve value from DHT"""
        return self._values.get(key)

    def routing_table_size(self) -> int:
        return sum(len(b) for b in self._buckets)

    def stats(self) -> dict:
        return {
            "node_id"      : self.node_id.hex()[:16] + "...",
            "routing_size" : self.routing_table_size(),
            "values_stored": len(self._values),
            "buckets_used" : sum(1 for b in self._buckets if b),
        }


