# MODULE 77  nebula_script_templates.py  — Script Template Library
# ================================================================
# Pre-built script templates for common use cases:
# escrow, subscription, auction, time-release, crowdfund.

import hashlib, time, struct
from typing import List, Optional, Tuple
from dataclasses import dataclass

@dataclass
class ScriptTemplate:
    """A named script template with documentation"""
    name        : str
    description : str
    script      : bytes
    spending_path: str
    risk_level  : str = "low"

    def address(self) -> str:
        h160 = hashlib.new('ripemd160',
               hashlib.sha256(self.script).digest()).digest()
        return base58check_encode(h160, SCRIPT_ADDRESS_VERSION)

    def to_dict(self) -> dict:
        return {
            "name"       : self.name,
            "description": self.description,
            "address"    : self.address(),
            "script_hex" : self.script.hex(),
            "asm"        : ScriptInterpreter.disassemble(self.script),
            "risk"       : self.risk_level,
        }

class ScriptTemplateLibrary:
    """
    Library of reusable Script templates.
    Ready-to-use scripts for common blockchain applications.
    """

    @staticmethod
    def escrow_3party(buyer_pk: bytes, seller_pk: bytes,
                       arbiter_pk: bytes) -> ScriptTemplate:
        """
        3-party escrow: buyer + seller OR arbiter + one party.
        2-of-3 multisig for dispute resolution.
        """
        ms     = MultisigWallet(2, [buyer_pk, seller_pk, arbiter_pk])
        script = ms.redeem_script()
        return ScriptTemplate(
            name         = "3-Party Escrow",
            description  = "Buyer+Seller release, or Arbiter+either resolves disputes",
            script       = script,
            spending_path= "2-of-3 multisig: buyer+seller OR arbiter+buyer OR arbiter+seller",
            risk_level   = "low",
        )

    @staticmethod
    def subscription(subscriber_pk: bytes, provider_pk: bytes,
                      interval_blocks: int = 144,
                      payment_amount: int = 1 * 10**DECIMALS) -> ScriptTemplate:
        """
        Subscription payment: provider can claim payment once per interval.
        Subscriber can cancel after interval.
        """
        interval_bytes = _script_int_to_bytes(interval_blocks)
        h160_sub  = hashlib.new('ripemd160', hashlib.sha256(subscriber_pk).digest()).digest()
        h160_prov = hashlib.new('ripemd160', hashlib.sha256(provider_pk).digest()).digest()
        script = (
            bytes([ScriptOpcode.OP_IF,
                   # Provider can claim with CSV
                   len(interval_bytes)]) + interval_bytes +
            bytes([ScriptOpcode.OP_CHECKSEQUENCEVERIFY, ScriptOpcode.OP_DROP,
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160, len(h160_prov)]) +
            h160_prov +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ELSE,
                   # Subscriber can cancel anytime
                   ScriptOpcode.OP_DUP, ScriptOpcode.OP_HASH160, len(h160_sub)]) +
            h160_sub +
            bytes([ScriptOpcode.OP_EQUALVERIFY, ScriptOpcode.OP_CHECKSIG,
                   ScriptOpcode.OP_ENDIF])
        )
        return ScriptTemplate(
            name         = "Subscription Payment",
            description  = f"Provider claims every {interval_blocks} blocks, subscriber can cancel",
            script       = script,
            spending_path= "Provider: CSV + sig | Subscriber: anytime sig",
            risk_level   = "low",
        )

    @staticmethod
    def dutch_auction(seller_pk: bytes,
                       start_price: int,
                       floor_price: int,
                       blocks_to_floor: int = 1440) -> ScriptTemplate:
        """
        Dutch auction: price decreases linearly over time.
        First buyer to claim at current price wins.
        """
        h160 = hashlib.new('ripemd160', hashlib.sha256(seller_pk).digest()).digest()
        # Simplified: just a timelocked P2PKH for demonstration
        script = TimelockScript.cltv_p2pkh(seller_pk, blocks_to_floor)
        return ScriptTemplate(
            name         = "Dutch Auction",
            description  = f"Price: {start_price/10**DECIMALS}→{floor_price/10**DECIMALS} NBL over {blocks_to_floor} blocks",
            script       = script,
            spending_path= "Buyer: sig at current price | Seller: reclaim after floor",
            risk_level   = "medium",
        )

    @staticmethod
    def time_release_savings(owner_pk: bytes,
                              unlock_height: int) -> ScriptTemplate:
        """
        Time-release savings: funds locked until block height.
        Use case: long-term savings, vesting, will.
        """
        script = TimelockScript.cltv_p2pkh(owner_pk, unlock_height)
        return ScriptTemplate(
            name         = "Time-Release Savings",
            description  = f"Funds locked until block #{unlock_height:,}",
            script       = script,
            spending_path= "Owner: sig after block height",
            risk_level   = "low",
        )

    @staticmethod
    def crowdfund(goal_amount: int,
                   beneficiary_pk: bytes,
                   deadline_blocks: int,
                   min_contribution: int = 10**DECIMALS) -> ScriptTemplate:
        """
        Crowdfund: beneficiary claims if goal met before deadline.
        Simplified single-beneficiary version.
        """
        script = TimelockScript.cltv_p2pkh(beneficiary_pk, deadline_blocks)
        return ScriptTemplate(
            name         = "Crowdfund",
            description  = f"Goal: {goal_amount/10**DECIMALS} NBL by block #{deadline_blocks:,}",
            script       = script,
            spending_path= "Beneficiary: after deadline if goal met",
            risk_level   = "medium",
        )

    @staticmethod
    def recurring_payment(payer_pk: bytes, payee_pk: bytes,
                           period_blocks: int = 144) -> ScriptTemplate:
        """Daily/weekly/monthly recurring payment via CSV"""
        script = TimelockScript.csv_p2pkh(payee_pk, period_blocks)
        return ScriptTemplate(
            name         = "Recurring Payment",
            description  = f"Payee can claim every {period_blocks} blocks (~{period_blocks*10//60}h)",
            script       = script,
            spending_path= "Payee: CSV + sig | Payer: cancel anytime",
            risk_level   = "low",
        )

    @classmethod
    def all_templates(cls) -> List[str]:
        """List all available templates"""
        return [
            "escrow_3party", "subscription", "dutch_auction",
            "time_release_savings", "crowdfund", "recurring_payment",
        ]

    @classmethod
    def get_template_info(cls) -> List[dict]:
        """Return info about all templates (without keys)"""
        dummy_pk = bytes(33)
        return [
            {"name": "escrow_3party",
             "use_case": "Marketplace, freelance, property purchase"},
            {"name": "subscription",
             "use_case": "SaaS, membership, monthly service fees"},
            {"name": "dutch_auction",
             "use_case": "Token sale, NFT drop, price discovery"},
            {"name": "time_release_savings",
             "use_case": "Long-term savings, employee vesting, will"},
            {"name": "crowdfund",
             "use_case": "Project funding, charity, community goals"},
            {"name": "recurring_payment",
             "use_case": "Payroll, rent, utility auto-payment"},
        ]


# ================================================================
# MODULE 78  nebula_chain_state.py  — Chain State Snapshots + Restore
# ================================================================
# Fast chain state snapshots: full state save/load in seconds.
# Enables: instant node recovery, testing, state rewind.

import json, threading, time, hashlib
from typing import Optional, Dict, List
from pathlib import Path

@dataclass
class ChainStateManifest:
    """Manifest for a chain state snapshot"""
    snapshot_id   : str
    height        : int
    tip_hash      : str
    utxo_count    : int
    created_at    : float
    description   : str = ""
    size_bytes    : int  = 0
    checksum      : str  = ""

    def to_dict(self) -> dict:
        return {
            "snapshot_id": self.snapshot_id,
            "height"     : self.height,
            "tip_hash"   : self.tip_hash[:20] + "...",
            "utxo_count" : self.utxo_count,
            "created_at" : self.created_at,
            "description": self.description,
            "size_mb"    : round(self.size_bytes / 1024 / 1024, 2),
            "checksum"   : self.checksum[:16] + "...",
        }

class ChainStateManager:
    """
    Manages chain state snapshots.
    Supports: create, list, restore, delete, verify.
    """

    SNAPSHOT_DIR = "./nebula_snapshots"

    def __init__(self, blockchain: 'NEBULABlockchain',
                 snapshot_dir: str = None):
        self.bc            = blockchain
        self.dir           = Path(snapshot_dir or self.SNAPSHOT_DIR)
        self.dir.mkdir(parents=True, exist_ok=True)
        self._manifests    : Dict[str, ChainStateManifest] = {}
        self._lock         = threading.Lock()
        self._load_manifests()

    def _load_manifests(self):
        """Load existing snapshot manifests"""
        for f in self.dir.glob("*.manifest.json"):
            try:
                data = json.loads(f.read_text())
                m    = ChainStateManifest(**data)
                self._manifests[m.snapshot_id] = m
            except Exception:
                _NB_SWALLOW_LOG.warning("swallowed Exception in ChainStateManager._load_manifests", exc_info=True)

    def create_snapshot(self, description: str = "") -> ChainStateManifest:
        """Create a full chain state snapshot"""
        snap_id   = hashlib.sha256(
            f"{self.bc.height}:{time.time()}".encode()).hexdigest()[:12]
        snap_path = self.dir / f"{snap_id}.json"

        # Serialize state
        state = {
            "height"     : self.bc.height,
            "tip_hash"   : self.bc.tip.hash,
            "chain_info" : self.bc.chain_info(),
            "utxos"      : [
                {"txid": e.txid, "index": e.index, "value": e.value,
                 "script_pubkey": e.script_pubkey.hex(),
                 "height": e.height, "is_coinbase": e.is_coinbase}
                for e in self.bc.utxo._utxos.values()
            ],
            "block_headers": [
                {"height": blk.height, "hash": blk.hash,
                 "prev_hash": blk.header.prev_hash,
                 "merkle_root": blk.header.merkle_root,
                 "timestamp": blk.header.timestamp,
                 "bits": blk.header.bits,
                 "nonce": blk.header.nonce}
                for blk in self.bc._chain
            ],
        }

        state_json = json.dumps(state, separators=(',', ':'))
        snap_path.write_text(state_json)
        size      = snap_path.stat().st_size
        checksum  = hashlib.sha256(state_json.encode()).hexdigest()

        manifest = ChainStateManifest(
            snapshot_id = snap_id,
            height      = self.bc.height,
            tip_hash    = self.bc.tip.hash,
            utxo_count  = self.bc.utxo.size(),
            created_at  = time.time(),
            description = description,
            size_bytes  = size,
            checksum    = checksum,
        )

        # Save manifest
        manifest_path = self.dir / f"{snap_id}.manifest.json"
        manifest_path.write_text(json.dumps(manifest.to_dict()))

        with self._lock:
            self._manifests[snap_id] = manifest

        print(f"  📸 Snapshot {snap_id}: height {self.bc.height}, "
              f"{self.bc.utxo.size()} UTXOs, {size//1024}KB")
        return manifest

    def restore_snapshot(self, snap_id: str) -> Tuple[bool, str]:
        """Restore chain state from snapshot"""
        snap_path = self.dir / f"{snap_id}.json"
        if not snap_path.exists():
            return False, f"Snapshot {snap_id} not found"

        try:
            state = json.loads(snap_path.read_text())

            # Restore UTXOs
            self.bc.utxo._utxos.clear()
            for ud in state.get("utxos", []):
                self.bc.utxo.add(UTXOEntry(
                    txid          = ud["txid"],
                    index         = ud["index"],
                    value         = ud["value"],
                    script_pubkey = bytes.fromhex(ud["script_pubkey"]),
                    height        = ud["height"],
                    is_coinbase   = ud["is_coinbase"],
                ))

            print(f"  ✅ Restored snapshot {snap_id}: "
                  f"height {state['height']}, {len(state['utxos'])} UTXOs")
            return True, f"Restored to height {state['height']}"
        except Exception as e:
            return False, f"Restore failed: {e}"

    def verify_snapshot(self, snap_id: str) -> Tuple[bool, str]:
        """Verify snapshot integrity"""
        snap_path = self.dir / f"{snap_id}.json"
        if not snap_path.exists():
            return False, "Not found"
        try:
            content  = snap_path.read_text()
            checksum = hashlib.sha256(content.encode()).hexdigest()
            manifest = self._manifests.get(snap_id)
            if manifest and manifest.checksum != checksum:
                return False, "Checksum mismatch — snapshot may be corrupted"
            data = json.loads(content)
            return True, f"Valid: height {data['height']}, {len(data.get('utxos',[]))} UTXOs"
        except Exception as e:
            return False, str(e)

    def list_snapshots(self) -> List[dict]:
        with self._lock:
            return sorted([m.to_dict() for m in self._manifests.values()],
                           key=lambda x: x["height"], reverse=True)

    def delete_snapshot(self, snap_id: str) -> bool:
        try:
            (self.dir / f"{snap_id}.json").unlink(missing_ok=True)
            (self.dir / f"{snap_id}.manifest.json").unlink(missing_ok=True)
            with self._lock:
                self._manifests.pop(snap_id, None)
            return True
        except Exception:
            return False

    def auto_snapshot(self, interval_blocks: int = 1_000):
        """Auto-create snapshot every N blocks"""
        if self.bc.height % interval_blocks == 0 and self.bc.height > 0:
            self.create_snapshot(f"Auto at {self.bc.height}")


# ================================================================
# MODULE 79  nebula_notifications.py  — Alerts + Webhooks
# ================================================================
# Push notifications for: new blocks, tx confirmations,
# large transfers, price alerts, mining rewards.

import threading, time
from typing import Dict, List, Callable, Optional
from dataclasses import dataclass, field
from enum import Enum

class AlertType(Enum):
    NEW_BLOCK       = "new_block"
    TX_CONFIRMED    = "tx_confirmed"
    LARGE_TRANSFER  = "large_transfer"
    MINING_REWARD   = "mining_reward"
    LOW_BALANCE     = "low_balance"
    PRICE_ALERT     = "price_alert"
    MEMPOOL_HIGH    = "mempool_high"
    NODE_DOWN       = "node_down"
    CUSTOM          = "custom"

@dataclass
class Alert:
    """A notification alert"""
    alert_type  : AlertType
    title       : str
    message     : str
    data        : dict = field(default_factory=dict)
    timestamp   : float = field(default_factory=time.time)
    is_read     : bool  = False

    def to_dict(self) -> dict:
        return {
            "type"      : self.alert_type.value,
            "title"     : self.title,
            "message"   : self.message,
            "data"      : self.data,
            "timestamp" : self.timestamp,
            "is_read"   : self.is_read,
        }

@dataclass
class AlertRule:
    """A rule that triggers an alert"""
    rule_id     : str
    alert_type  : AlertType
    condition   : Callable   # function → bool
    title_tmpl  : str
    msg_tmpl    : str
    cooldown_secs: float = 300.0
    last_fired  : float  = 0.0
    is_active   : bool   = True

    def can_fire(self) -> bool:
        return time.time() - self.last_fired >= self.cooldown_secs

class NotificationManager:
    """
    NEBULA notification and alert manager.
    Monitors blockchain events and fires configured alerts.
    Supports: callbacks, webhook delivery, alert history.
    """

    MAX_HISTORY = 1000

    def __init__(self, blockchain: 'NEBULABlockchain',
                 oracle: 'PriceOracle' = None):
        self.bc       = blockchain
        self.oracle   = oracle
        self._rules   : Dict[str, AlertRule] = {}
        self._history : List[Alert] = []
        self._callbacks: List[Callable] = []
        self._webhooks : List[str] = []
        self._lock    = threading.RLock()
        self._running = False
        self._last_height = blockchain.height

        self._setup_default_rules()

    def _setup_default_rules(self):
        """Setup default notification rules"""
        self.add_rule(AlertRule(
            rule_id    = "new_block",
            alert_type = AlertType.NEW_BLOCK,
            condition  = lambda: self.bc.height > self._last_height,
            title_tmpl = "New Block #{height}",
            msg_tmpl   = "Block mined at height {height}, {tx_count} transactions",
            cooldown_secs = 0,
        ))
        self.add_rule(AlertRule(
            rule_id    = "mempool_high",
            alert_type = AlertType.MEMPOOL_HIGH,
            condition  = lambda: self.bc.mempool.size() > 1000,
            title_tmpl = "Mempool Congestion",
            msg_tmpl   = "Mempool has {count} transactions",
            cooldown_secs = 600,
        ))

    def add_rule(self, rule: AlertRule):
        with self._lock:
            self._rules[rule.rule_id] = rule

    def add_callback(self, fn: Callable):
        """Register callback for all alerts"""
        self._callbacks.append(fn)

    def add_price_alert(self, pair: str,
                         above: float = None,
                         below: float = None):
        """Add a price alert"""
        def _condition():
            if not self.oracle:
                return False
            price = self.oracle.get_nbl_usd()
            if price is None:
                return False
            if above and price > above:
                return True
            if below and price < below:
                return True
            return False

        rule_id = f"price_{pair}_{time.time():.0f}"
        desc    = f"above ${above}" if above else f"below ${below}"
        self.add_rule(AlertRule(
            rule_id    = rule_id,
            alert_type = AlertType.PRICE_ALERT,
            condition  = _condition,
            title_tmpl = f"Price Alert: {pair}",
            msg_tmpl   = f"NBL/USD {desc}",
            cooldown_secs = 3600,
        ))

    def add_address_alert(self, address: str,
                           min_amount: float = 0):
        """Alert when address receives NBL"""
        prev_bal = [self.bc.utxo.balance(address)]
        def _condition():
            new_bal = self.bc.utxo.balance(address)
            if new_bal > prev_bal[0]:
                diff = (new_bal - prev_bal[0]) / 10**DECIMALS
                prev_bal[0] = new_bal
                return diff >= min_amount
            return False
        self.add_rule(AlertRule(
            rule_id    = f"addr_{address[:8]}",
            alert_type = AlertType.TX_CONFIRMED,
            condition  = _condition,
            title_tmpl = "Incoming NBL",
            msg_tmpl   = f"Address {address[:16]}... received NBL",
            cooldown_secs = 10,
        ))

    def _fire_alert(self, rule: AlertRule):
        """Fire an alert"""
        height    = self.bc.height
        tx_count  = len(self.bc.tip.transactions) if self.bc.height >= 0 else 0
        count     = self.bc.mempool.size()

        title   = rule.title_tmpl.format(height=height, tx_count=tx_count, count=count)
        message = rule.msg_tmpl.format(height=height, tx_count=tx_count, count=count)

        alert = Alert(
            alert_type = rule.alert_type,
            title      = title,
            message    = message,
            data       = {"height": height, "rule_id": rule.rule_id},
        )

        with self._lock:
            self._history.append(alert)
            if len(self._history) > self.MAX_HISTORY:
                self._history.pop(0)
            rule.last_fired = time.time()

        # Dispatch
        for cb in self._callbacks:
            try:
                cb(alert)
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NotificationManager._fire_alert", exc_info=True)

    def check_all(self):
        """Check all rules and fire matching ones"""
        with self._lock:
            rules = list(self._rules.values())
        for rule in rules:
            if rule.is_active and rule.can_fire():
                try:
                    if rule.condition():
                        self._fire_alert(rule)
                        if rule.alert_type == AlertType.NEW_BLOCK:
                            self._last_height = self.bc.height
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in NotificationManager.check_all", exc_info=True)

    def start(self, interval: float = 10.0):
        """Start background monitoring"""
        self._running = True
        def _loop():
            while self._running:
                try:
                    self.check_all()
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in NotificationManager.start._loop", exc_info=True)
                time.sleep(interval)
        threading.Thread(target=_loop, daemon=True, name="Notifications").start()

    def stop(self): self._running = False

    def get_unread(self) -> List[dict]:
        with self._lock:
            unread = [a for a in self._history if not a.is_read]
            for a in unread:
                a.is_read = True
            return [a.to_dict() for a in unread]

    def history(self, last_n: int = 50) -> List[dict]:
        with self._lock:
            return [a.to_dict() for a in self._history[-last_n:]]

    def stats(self) -> dict:
        return {
            "rules"      : len(self._rules),
            "callbacks"  : len(self._callbacks),
            "history"    : len(self._history),
            "unread"     : sum(1 for a in self._history if not a.is_read),
        }


