import time, threading, hashlib
from typing import Any, Dict, List, Optional

class MockBlockchain:
    """
    Mock blockchain for testing.
    Same API as NEBULABlockchain but uses in-memory data.
    Perfect for unit testing without mining.
    """

    def __init__(self, initial_balances: Dict[str, int] = None):
        self._balances  : Dict[str, int] = initial_balances or {}
        self._txs       : Dict[str, dict] = {}
        self._height    = 0
        self._lock      = threading.Lock()

    def fund_address(self, address: str, amount_nbl: float):
        """Fund an address for testing"""
        with self._lock:
            self._balances[address] = (
                self._balances.get(address, 0) +
                int(amount_nbl * 10**DECIMALS))

    def get_balance_nbl(self, address: str) -> float:
        return self._balances.get(address, 0) / 10**DECIMALS

    def mock_send(self, from_addr: str, to_addr: str,
                   amount_nbl: float) -> Tuple[bool, str]:
        """Mock sending NBL"""
        amount = int(amount_nbl * 10**DECIMALS)
        with self._lock:
            if self._balances.get(from_addr, 0) < amount:
                return False, "Insufficient balance"
            self._balances[from_addr] -= amount
            self._balances[to_addr]    = self._balances.get(to_addr, 0) + amount
            txid = hashlib.sha256(
                f"{from_addr}{to_addr}{amount}{time.time()}".encode()).hexdigest()
            self._txs[txid] = {
                "from": from_addr, "to": to_addr, "amount": amount_nbl}
            self._height += 1
            return True, txid

    def balances(self) -> dict:
        return {addr: bal/10**DECIMALS
                for addr, bal in self._balances.items()}

class TransactionDebugger:
    """
    Debug transaction validation step by step.
    Shows exactly what's happening in script execution.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc = blockchain

    def debug_tx(self, tx: 'Transaction') -> dict:
        """Debug a transaction"""
        issues   = []
        info     = {}

        # Basic checks
        if not tx.inputs:
            issues.append("No inputs")
        if not tx.outputs:
            issues.append("No outputs")

        # Check inputs
        for i, inp in enumerate(tx.inputs):
            utxo = self.bc.utxo.get(inp.outpoint.txid, inp.outpoint.index)
            if not utxo and not tx.is_coinbase:
                issues.append(f"Input {i}: UTXO not found ({inp.outpoint.txid[:16]}...)")
            elif utxo:
                info[f"input_{i}"] = {
                    "value"   : utxo.value / 10**DECIMALS,
                    "height"  : utxo.height,
                    "coinbase": utxo.is_coinbase,
                }

        # Check outputs
        total_out = sum(o.value for o in tx.outputs)
        info["total_out_nbl"] = total_out / 10**DECIMALS
        info["output_count"]  = len(tx.outputs)
        info["is_coinbase"]   = tx.is_coinbase
        info["txid"]          = tx.txid
        info["size_bytes"]    = tx.byte_size()

        return {
            "txid"    : tx.txid,
            "valid"   : len(issues) == 0,
            "issues"  : issues,
            "details" : info,
        }

    def trace_script(self, script: bytes) -> List[dict]:
        """Trace script execution step by step"""
        interp = ScriptInterpreter()
        trace  = []

        # Manually step through script
        i = 0
        while i < len(script):
            op   = script[i]
            name = {v.value: v.name for v in ScriptOpcode}.get(op, f"0x{op:02x}")
            stack_before = list(interp.stack)
            # Execute just this opcode
            sub_script = script[i:i+1]
            i += 1
            trace.append({
                "op"          : name,
                "stack_before": [s.hex() for s in stack_before],
                "stack_after" : [],  # simplified
            })

        return trace

    def explain_tx(self, tx: 'Transaction') -> str:
        """Human-readable transaction explanation"""
        lines = [f"Transaction: {tx.txid[:20]}..."]
        lines.append(f"  {'Coinbase' if tx.is_coinbase else 'Regular'} | "
                     f"{len(tx.inputs)} inputs → {len(tx.outputs)} outputs")
        for i, inp in enumerate(tx.inputs):
            if tx.is_coinbase:
                lines.append(f"  Input  {i}: COINBASE")
            else:
                lines.append(f"  Input  {i}: {inp.outpoint.txid[:16]}...:{inp.outpoint.index}")
        for i, out in enumerate(tx.outputs):
            lines.append(f"  Output {i}: {out.value/10**DECIMALS:.9f} NBL → "
                         f"{out.address[:20] if out.address else 'script'}...")
        return "\n".join(lines)

class ScriptSandbox:
    """
    Interactive script sandbox for testing Script programs.
    Test custom scripts without broadcasting.
    """

    def __init__(self):
        self._scripts     : Dict[str, bytes] = {}
        self._results     : Dict[str, dict]  = {}

    def add_script(self, name: str, script_hex: str):
        """Add a script to the sandbox"""
        self._scripts[name] = bytes.fromhex(script_hex)

    def run(self, name: str, stack_items: List[bytes] = None) -> dict:
        """Run a named script"""
        script = self._scripts.get(name)
        if not script:
            return {"error": f"Script '{name}' not found"}

        interp = ScriptInterpreter()
        if stack_items:
            interp.stack = list(stack_items)

        ok, err  = interp.execute(script)
        asm      = ScriptInterpreter.disassemble(script)

        result = {
            "name"   : name,
            "ok"     : ok,
            "error"  : err,
            "stack"  : [s.hex() for s in interp.stack],
            "asm"    : asm,
        }
        self._results[name] = result
        return result

    def test_p2pkh(self, address: str) -> dict:
        """Test P2PKH script for address"""
        script = Script.p2pkh_locking_from_address(address)
        asm    = ScriptInterpreter.disassemble(script)
        return {
            "address": address,
            "script" : script.hex(),
            "asm"    : asm,
            "type"   : "P2PKH",
        }

    def list_scripts(self) -> List[str]:
        return list(self._scripts.keys())

class DeveloperToolkit:
    """
    Complete developer toolkit for NEBULA development.
    Bundles: mock, debugger, sandbox, test fixtures.
    """

    def __init__(self, blockchain: 'NEBULABlockchain' = None):
        self.bc       = blockchain or NEBULABlockchain()
        self.mock     = MockBlockchain()
        self.debugger = TransactionDebugger(self.bc)
        self.sandbox  = ScriptSandbox()
        self._fixtures: Dict[str, Any] = {}

    def create_test_wallets(self, count: int = 3) -> List['NEBULAWallet']:
        """Create test wallets with funded balances"""
        wallets = []
        for i in range(count):
            w = NEBULAWallet.create_new(self.bc.utxo)
            self.mock.fund_address(w.first_address, 100.0 * (i + 1))
            wallets.append(w)
        return wallets

    def quick_test_transaction(self, from_nbl: float = 10.0) -> Optional['Transaction']:
        """Create a quick test transaction"""
        w1 = NEBULAWallet.create_new(self.bc.utxo)
        w2 = NEBULAWallet.create_new(self.bc.utxo)
        # Fund w1 directly in UTXO
        fake_txid = hashlib.sha256(b"test").hexdigest()
        script    = Script.p2pkh_locking_from_address(w1.first_address)
        self.bc.utxo.add(UTXOEntry(
            txid=fake_txid, index=0,
            value=int(from_nbl * 10**DECIMALS),
            script_pubkey=script, height=1))
        tx = w1.build_transaction(w2.first_address, from_nbl * 0.5)
        if tx:
            debug = self.debugger.debug_tx(tx)
            return tx
        return None

    def generate_test_block(self, n_txs: int = 5) -> Optional['Block']:
        """Generate a test block with N transactions"""
        addr  = FOUNDATION_ADDRESS
        miner = NEBULAMiner(self.bc, addr)
        blk   = miner.mine_demo_block(easy_bits=0x1f7fffff, timeout_secs=5)
        return blk

    def repl(self):
        """Interactive NEBULA developer REPL"""
        print("\n  🔧 NEBULA Developer REPL")
        print("  Commands: balance, send, block, tx, quit")
        while True:
            try:
                cmd = input("  nebula> ").strip().split()
                if not cmd:
                    continue
                if cmd[0] == "quit":
                    break
                elif cmd[0] == "balance" and len(cmd) > 1:
                    bal = self.bc.utxo.balance(cmd[1])
                    print(f"  {cmd[1][:20]}: {bal/10**DECIMALS:.9f} NBL")
                elif cmd[0] == "height":
                    print(f"  Height: {self.bc.height}")
                elif cmd[0] == "mempool":
                    print(f"  Mempool: {self.bc.mempool.size()} txs")
                elif cmd[0] == "help":
                    print("  balance <addr> | height | mempool | quit")
                else:
                    print(f"  Unknown: {cmd[0]}")
            except (KeyboardInterrupt, EOFError):
                break

    def toolkit_info(self) -> dict:
        return {
            "blockchain"  : "NEBULABlockchain",
            "mock"        : "MockBlockchain",
            "debugger"    : "TransactionDebugger",
            "sandbox"     : "ScriptSandbox",
            "fixtures"    : list(self._fixtures.keys()),
            "help"        : "nebula.dev.repl() for interactive session",
        }



# ================================================================
# MODULE 81  nebula_block_explorer_api.py  — Full Block Explorer API
# ================================================================
# Complete block explorer backend: paginated blocks, search,
# stats, charts data, rich address pages.

import json, threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Dict, List, Optional
import urllib.parse

class ExplorerAPIHandler(BaseHTTPRequestHandler):
    """Block Explorer HTTP API handler"""
    explorer: 'BlockExplorerAPI' = None

    def log_message(self, fmt, *args): pass

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        path   = parsed.path.rstrip('/')
        params = dict(urllib.parse.parse_qsl(parsed.query))

        routes = {
            '/explorer/blocks'          : lambda: self._blocks(params),
            '/explorer/block'           : lambda: self._block(params),
            '/explorer/tx'              : lambda: self._tx(params),
            '/explorer/address'         : lambda: self._address(params),
            '/explorer/search'          : lambda: self._search(params),
            '/explorer/stats'           : self._stats,
            '/explorer/richlist'        : lambda: self._richlist(params),
            '/explorer/supply'          : self._supply,
            '/explorer/halvings'        : self._halvings,
            '/explorer/mempool/txs'     : lambda: self._mempool_txs(params),
            '/explorer/mempool/fees'    : self._mempool_fees,
            '/explorer/mining/stats'    : self._mining_stats,
            '/explorer/chart/price'     : self._price_chart,
            '/explorer/chart/hashrate'  : self._hashrate_chart,
            '/explorer/chart/txvolume'  : self._txvolume_chart,
        }

        handler = routes.get(path)
        if handler:
            try:
                result = handler()
                self._json(200, result)
            except Exception as e:
                self._json(500, {"error": str(e)})
        else:
            self._json(404, {"error": "Endpoint not found"})

    def _blocks(self, p: dict) -> dict:
        bc      = self.explorer.bc
        page    = int(p.get("page", 1))
        per_page= int(p.get("per_page", 10))
        start   = max(0, bc.height - (page * per_page) + 1)
        end     = bc.height - ((page - 1) * per_page)
        blocks  = []
        for h in range(max(0, end), min(bc.height + 1, end + per_page)):
            blk = bc.get_block(h)
            if blk:
                blocks.append({
                    "height"  : blk.height,
                    "hash"    : blk.hash,
                    "time"    : blk.header.timestamp,
                    "tx_count": len(blk.transactions),
                    "size"    : blk.byte_size(),
                    "miner"   : (blk.transactions[0].outputs[0].address
                                 if blk.transactions and blk.transactions[0].outputs
                                 else ""),
                    "reward"  : mining_reward(blk.height) / 10**DECIMALS,
                })
        return {
            "page"       : page,
            "per_page"   : per_page,
            "total"      : bc.height + 1,
            "blocks"     : blocks,
        }

    def _block(self, p: dict) -> dict:
        bc  = self.explorer.bc
        if "hash" in p:
            blk = bc.get_block_by_hash(p["hash"])
        else:
            blk = bc.get_block(int(p.get("height", 0)))
        if not blk:
            return {"error": "Block not found"}
        d = blk.to_dict()
        d["confirmations"] = bc.height - blk.height + 1
        return d

    def _tx(self, p: dict) -> dict:
        txid = p.get("txid", "")
        bc   = self.explorer.bc
        for blk in reversed(bc._chain):
            for tx in blk.transactions:
                if tx.txid == txid:
                    d = tx.to_dict()
                    d["block_hash"]    = blk.hash
                    d["block_height"]  = blk.height
                    d["confirmations"] = bc.height - blk.height + 1
                    return d
        return {"error": "Transaction not found"}

    def _address(self, p: dict) -> dict:
        addr = p.get("addr", "")
        bc   = self.explorer.bc
        bal  = bc.get_balance(addr)
        utxos = bc.utxo.get_by_address(addr)
        page  = int(p.get("page", 1))
        return {
            "address"    : addr,
            "balance_nbl": bal["balance_nbl"],
            "utxo_count" : bal["utxo_count"],
            "utxos"      : [
                {"txid": u.txid, "vout": u.index,
                 "value": u.value/10**DECIMALS,
                 "height": u.height,
                 "matured": bc.height - u.height >= COINBASE_MATURITY
                             if u.is_coinbase else True}
                for u in utxos[:20]
            ],
        }

    def _search(self, p: dict) -> dict:
        q  = p.get("q", "").strip()
        bc = self.explorer.bc
        # Try block height
        if q.isdigit():
            blk = bc.get_block(int(q))
            if blk:
                return {"type": "block", "result": blk.to_dict()}
        # Try block hash
        if len(q) == 64:
            blk = bc.get_block_by_hash(q)
            if blk:
                return {"type": "block", "result": blk.to_dict()}
            # Try as txid
            for blk in reversed(bc._chain[-100:]):
                for tx in blk.transactions:
                    if tx.txid == q:
                        return {"type": "tx", "result": tx.to_dict()}
        # Try address
        if q.startswith(PUBKEY_ADDRESS_PREFIX):
            bal = bc.get_balance(q)
            return {"type": "address", "result": bal}
        return {"type": "not_found", "query": q}

    def _stats(self) -> dict:
        bc   = self.explorer.bc
        chain = bc._chain
        avg_bt = TARGET_BLOCK_TIME
        if len(chain) >= 2:
            times = [chain[i].header.timestamp - chain[i-1].header.timestamp
                     for i in range(max(1, len(chain)-10), len(chain))]
            avg_bt = sum(times)/len(times) if times else TARGET_BLOCK_TIME
        return {
            "height"         : bc.height,
            "total_txs"      : sum(len(b.transactions) for b in chain),
            "total_addresses": len(set(
                out.address for b in chain for tx in b.transactions
                for out in tx.outputs if out.address)),
            "avg_block_time" : round(avg_bt, 1),
            "utxo_count"     : bc.utxo.size(),
            "mempool_count"  : bc.mempool.size(),
        }

    def _richlist(self, p: dict) -> dict:
        n  = int(p.get("n", 20))
        rl = RichList(self.explorer.bc, min(n, 100))
        return {"entries": [e.to_dict() for e in rl.build()]}

    def _supply(self) -> dict:
        bc     = self.explorer.bc
        issued = bc.utxo.total_supply()
        sch    = BlockRewardSimulator().full_emission_schedule()
        return {
            "max_supply"    : MAX_SUPPLY / 10**DECIMALS,
            "issued"        : issued / 10**DECIMALS,
            "pct_issued"    : f"{issued/MAX_SUPPLY*100:.4f}%",
            "current_reward": mining_reward(bc.height) / 10**DECIMALS,
            "emission_schedule": sch[:5],
        }

    def _halvings(self) -> dict:
        bc  = self.explorer.bc
        era = bc.height // HALVING_INTERVAL
        return {
            "current_era"    : era,
            "current_reward" : mining_reward(bc.height) / 10**DECIMALS,
            "next_halving"   : (era + 1) * HALVING_INTERVAL,
            "blocks_to_halving": (era + 1) * HALVING_INTERVAL - bc.height,
        }

    def _mempool_txs(self, p: dict) -> dict:
        pool = getattr(self.explorer.bc.mempool, '_txs', {})
        return {
            "count"  : len(pool),
            "txids"  : list(pool.keys())[:20],
        }

    def _mempool_fees(self) -> dict:
        bc = self.explorer.bc
        if hasattr(bc.mempool, 'fee_estimates'):
            return bc.mempool.fee_estimates()
        return {"error": "Fee estimator not available"}

    def _mining_stats(self) -> dict:
        bc    = self.explorer.bc
        chain = bc._chain
        total_blocks = len(chain)
        total_reward = sum(mining_reward(b.height) for b in chain)
        return {
            "total_blocks"  : total_blocks,
            "total_reward"  : total_reward / 10**DECIMALS,
            "foundation_total": total_reward * FOUNDATION_RATE / 10**DECIMALS,
        }

    def _price_chart(self) -> dict:
        explorer = self.explorer
        if explorer.historical:
            pts = explorer.historical.get_series("nbl_usd", 100)
            return {"series": "NBL/USD", "points": pts}
        return {"series": "NBL/USD", "points": []}

    def _hashrate_chart(self) -> dict:
        explorer = self.explorer
        if explorer.historical:
            pts = explorer.historical.get_series("hashrate_mhs", 100)
            return {"series": "Hashrate MH/s", "points": pts}
        return {"series": "Hashrate", "points": []}

    def _txvolume_chart(self) -> dict:
        bc    = self.explorer.bc
        chain = bc._chain
        daily : Dict[int, int] = {}
        for blk in chain:
            day = blk.header.timestamp // 86400 * 86400
            daily[day] = daily.get(day, 0) + len(blk.transactions)
        return {"series": "Daily Txs",
                "points": [{"ts": k, "v": v} for k, v in sorted(daily.items())[-30:]]}

    def _json(self, code: int, data: dict):
        body = json.dumps(data, default=str).encode()
        self.send_response(code)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.end_headers()
        self.wfile.write(body)

class BlockExplorerAPI:
    """Full Block Explorer backend API"""

    def __init__(self, blockchain: 'NEBULABlockchain',
                 historical: 'HistoricalDataManager' = None,
                 host: str = _nbl_default_bind(), port: int = 8081):
        self.bc         = blockchain
        self.historical = historical
        self.host       = host
        self.port       = port
        self._server    = None

    def start(self):
        ExplorerAPIHandler.explorer = self
        self._server = HTTPServer((self.host, self.port), ExplorerAPIHandler)
        threading.Thread(target=self._server.serve_forever,
                          daemon=True, name="ExplorerAPI").start()
        print(f"🔍 Block Explorer API: http://{self.host}:{self.port}/explorer/stats")

    def stop(self):
        if self._server:
            self._server.shutdown()


# ================================================================
# MODULE 82  nebula_mobile_sync.py  — Mobile-Optimized Sync
# ================================================================
# Lightweight sync protocol for mobile nodes.
# Uses: headers-only, compact blocks, state channels.

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field

class MobileNodeConfig:
    """Configuration for mobile NEBULA node"""
    MAX_BLOCK_DOWNLOAD  = 10     # max blocks to download at once
    SYNC_BATCH_HEADERS  = 100    # headers per batch
    PRUNE_KEEP_DAYS     = 7      # keep last 7 days of data
    BACKGROUND_SYNC     = True   # sync when idle
    WIFI_ONLY           = False  # only sync on WiFi
    MAX_STORAGE_MB      = 100    # max storage used
    NOTIFICATION_ENABLED= True

@dataclass
class MobileNodeState:
    """State of mobile NEBULA node"""
    synced_height   : int   = 0
    last_sync       : float = 0.0
    sync_mode       : str   = "headers"   # "headers", "compact", "full"
    network_type    : str   = "unknown"   # "wifi", "mobile", "offline"
    storage_used_mb : float = 0.0
    battery_mode    : str   = "normal"    # "normal", "power_save"
    is_syncing      : bool  = False

    def to_dict(self) -> dict:
        return {
            "synced_height" : self.synced_height,
            "last_sync"     : self.last_sync,
            "sync_mode"     : self.sync_mode,
            "network"       : self.network_type,
            "storage_mb"    : self.storage_used_mb,
            "battery_mode"  : self.battery_mode,
            "is_syncing"    : self.is_syncing,
        }

class MobileSyncManager:
    """
    Mobile-optimized blockchain sync manager.
    Intelligently manages sync based on: battery, storage, network.
    Supports: background sync, selective block download, pruning.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 config: MobileNodeConfig = None):
        self.bc      = blockchain
        self.config  = config or MobileNodeConfig()
        self.state   = MobileNodeState()
        self._ibd    = IBDManager(blockchain)
        self._pruner = BlockPruner(blockchain, keep_blocks=1008)  # 1 week
        self._bloom  : Optional[BloomFilter] = None
        self._lock   = threading.Lock()

    def set_watched_addresses(self, addresses: List[str]):
        """Set addresses to watch — only download relevant blocks"""
        n        = max(10, len(addresses))
        self._bloom = BloomFilterLegacy(n, fp_rate=0.0001)
        for addr in addresses:
            self._bloom.insert_address(addr)

    def sync_headers_only(self, headers: List['BlockHeader']) -> int:
        """Process only block headers (fastest sync mode)"""
        self.state.is_syncing = True
        self.state.sync_mode  = "headers"
        added = self._ibd.process_headers(headers, "mobile")
        self.state.synced_height = self.bc.height
        self.state.last_sync     = time.time()
        self.state.is_syncing    = False
        return added

    def should_download_block(self, block_filter: 'CompactBlockFilter') -> bool:
        """Use bloom filter to determine if block is relevant"""
        if self._bloom is None:
            return True   # no filter = download all
        # Check if any watched address appears in block filter
        return True   # simplified: always True without real filter match

    def prune_old_blocks(self) -> int:
        """Prune blocks to save storage"""
        return self._pruner.prune()

    def estimate_sync_time(self, target_height: int) -> float:
        """Estimate time to sync to target height"""
        blocks_needed = target_height - self.bc.height
        if self.state.sync_mode == "headers":
            rate = 1000   # headers/sec
        elif self.state.sync_mode == "compact":
            rate = 50     # blocks/sec via compact
        else:
            rate = 5      # full blocks/sec
        return blocks_needed / max(1, rate)

    def mobile_status(self) -> dict:
        return {
            **self.state.to_dict(),
            "bloom_filter"   : self._bloom.stats() if self._bloom else None,
            "pruned_blocks"  : self._pruner.stats()["pruned_blocks"],
            "sync_progress"  : self._ibd.sync_progress(),
            "est_sync_secs"  : self.estimate_sync_time(
                                    self._ibd._best_height_seen),
        }


