# MODULE 83  nebula_node_discovery.py  — Automatic Node Discovery
# ================================================================
# Bootstrap node discovery: DNS seeds, hardcoded seeds,
# peer exchange, UPnP port mapping.

import threading, time, socket
from typing import Dict, List, Optional, Tuple, Set

class NodeDiscovery:
    """
    Automatic NEBULA node discovery.
    Tries multiple methods: DNS seeds, peer exchange,
    hardcoded seed nodes, local network broadcast.
    """

    HARDCODED_SEEDS = [
        ("seed1.nebula-blockchain.org", DEFAULT_PORT),
        ("seed2.nebula-blockchain.org", DEFAULT_PORT),
        ("seed3.nebula-blockchain.org", DEFAULT_PORT),
        ("107.175.88.100", DEFAULT_PORT),
        ("198.50.159.135", DEFAULT_PORT),
    ]

    LOCAL_BROADCAST_ADDR = "255.255.255.255"
    DISCOVERY_PORT       = DEFAULT_PORT + 1

    def __init__(self, privacy_mgr: 'PrivacyConnectionManager' = None):
        self.privacy     = privacy_mgr
        self._peers      : Set[str] = set()
        self._tried      : Set[str] = set()
        self._lock       = threading.Lock()
        self._running    = False

    def discover_from_dns(self) -> List[Tuple[str, int]]:
        """Resolve DNS seed nodes"""
        found = []
        for hostname, port in [(s, DEFAULT_PORT) for s in DNS_SEEDS]:
            try:
                infos = socket.getaddrinfo(hostname, port,
                                            socket.AF_INET, socket.SOCK_STREAM)
                for info in infos:
                    ip = info[4][0]
                    found.append((ip, port))
                    with self._lock:
                        self._peers.add(f"{ip}:{port}")
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NodeDiscovery.discover_from_dns", exc_info=True)
        return found

    def discover_from_hardcoded(self) -> List[Tuple[str, int]]:
        """Try hardcoded seed nodes"""
        found = []
        for host, port in self.HARDCODED_SEEDS:
            with self._lock:
                self._peers.add(f"{host}:{port}")
            found.append((host, port))
        return found

    def request_peer_exchange(self, peer_addr: str,
                               peer_port: int) -> List[Tuple[str, int]]:
        """Request peer list from connected node (PEX)"""
        # Simplified: return empty (real impl would send GETADDR message)
        return []

    def announce_self(self, our_ip: str, our_port: int):
        """Announce ourselves to the network"""
        with self._lock:
            self._peers.discard(f"{our_ip}:{our_port}")  # don't connect to self

    def local_network_scan(self, subnet: str = "192.168.1") -> List[Tuple[str, int]]:
        """Scan local network for NEBULA nodes"""
        found = []
        for i in range(1, 255):
            ip   = f"{subnet}.{i}"
            try:
                s = socket.create_connection((ip, DEFAULT_PORT), timeout=0.1)
                s.close()
                found.append((ip, DEFAULT_PORT))
                with self._lock:
                    self._peers.add(f"{ip}:{DEFAULT_PORT}")
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in NodeDiscovery.local_network_scan", exc_info=True)
        return found

    def get_all_peers(self) -> List[str]:
        with self._lock:
            return list(self._peers)

    def mark_tried(self, addr: str):
        with self._lock:
            self._tried.add(addr)

    def get_untried(self) -> List[str]:
        with self._lock:
            return list(self._peers - self._tried)

    def stats(self) -> dict:
        with self._lock:
            return {
                "known"    : len(self._peers),
                "tried"    : len(self._tried),
                "untried"  : len(self._peers - self._tried),
            }


