# MODULE 85  nebula_monitoring_dashboard.py  — System Monitor
# ================================================================
# Real-time terminal monitoring dashboard.
# Shows: node health, chain stats, mempool, network, resources.

import time, threading
from typing import Optional

class MonitoringDashboard:
    """
    Terminal-based real-time monitoring dashboard.
    Shows live node metrics in a formatted display.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                 oracle: 'PriceOracle' = None,
                 pool: 'MiningPool' = None,
                 staking: 'StakingEngine' = None):
        self.bc      = blockchain
        self.oracle  = oracle
        self.pool    = pool
        self.staking = staking
        self._running= False

    def render(self) -> str:
        """Render full dashboard as string"""
        bc     = self.bc
        price  = self.oracle.get_nbl_usd() if self.oracle else None
        height = bc.height

        # Block stats
        tip     = bc.tip
        tx_count= len(tip.transactions)
        reward  = mining_reward(height) / 10**DECIMALS
        target  = bits_to_target(tip.header.bits)
        max_t   = bits_to_target(INITIAL_BITS)
        diff    = max_t / max(1, target)

        # Supply
        issued  = bc.utxo.total_supply()
        supply_pct = issued / MAX_SUPPLY * 100

        # Pool
        pool_workers = len(self.pool._workers) if self.pool else 0
        pool_hashrate= self.pool.pool_hashrate_mhs() if self.pool else 0

        lines = [
            "═" * 65,
            f"  🌌 NEBULA Node Monitor  |  {time.strftime('%Y-%m-%d %H:%M:%S')}",
            "═" * 65,
            f"  Chain  : {CHAIN_NAME} ({CHAIN_SYMBOL})   Height: {height:,}",
            f"  Tip    : {tip.hash[:32]}...",
            f"  Diff   : {diff:.6f}   Reward: {reward:.9f} NBL",
            f"  Supply : {issued/10**DECIMALS:,.2f} / {MAX_SUPPLY/10**DECIMALS:,.0f} NBL ({supply_pct:.3f}%)",
            "─" * 65,
            f"  Mempool: {bc.mempool.size():,} txs",
            f"  UTXOs  : {bc.utxo.size():,}",
            f"  Tip Txs: {tx_count}",
            "─" * 65,
        ]
        if price:
            lines.append(f"  NBL/USD: ${price:.6f}")
        if self.pool:
            lines.append(f"  Pool   : {pool_workers} workers | {pool_hashrate:.2f} MH/s")
        if self.staking:
            net = self.staking.network_stats()
            lines.append(f"  Staking: {net['total_staked_nbl']:.2f} NBL | {net['active_validators']} validators")
        lines.append("═" * 65)
        return "\n".join(lines)

    def start_live(self, interval: float = 5.0):
        """Start live dashboard (refreshes every N seconds)"""
        self._running = True
        def _loop():
            while self._running:
                import os
                try:
                    os.system('clear' if os.name != 'nt' else 'cls')
                except Exception:
                    _NB_SWALLOW_LOG.debug("swallowed Exception in MonitoringDashboard.start_live._loop", exc_info=True)
                print(self.render())
                time.sleep(interval)
        threading.Thread(target=_loop, daemon=True, name="Monitor").start()

    def stop(self): self._running = False

    def snapshot_dict(self) -> dict:
        """Machine-readable snapshot"""
        price = self.oracle.get_nbl_usd() if self.oracle else None
        bc    = self.bc
        return {
            "timestamp"    : time.time(),
            "height"       : bc.height,
            "tip_hash"     : bc.tip.hash[:20],
            "mempool"      : bc.mempool.size(),
            "utxos"        : bc.utxo.size(),
            "supply_pct"   : bc.utxo.total_supply() / MAX_SUPPLY * 100,
            "nbl_usd"      : price,
            "pool_workers" : len(self.pool._workers) if self.pool else 0,
            "staked_nbl"   : (self.staking._total_staked / 10**DECIMALS
                              if self.staking else 0),
        }

