# ================================================================
# MODULE 86  nebula_chain_fork_manager.py  — Fork Detection + Handling
# ================================================================

import threading, time
from typing import Dict, List, Optional, Set, Tuple
from dataclasses import dataclass, field

@dataclass
class ForkCandidate:
    """A candidate fork chain"""
    fork_height  : int
    tip_hash     : str
    tip_height   : int
    chain_work   : int
    source_peer  : str
    headers      : List['BlockHeader'] = field(default_factory=list)
    created_at   : float = field(default_factory=time.time)

    @property
    def fork_depth(self) -> int:
        return self.tip_height - self.fork_height

    def to_dict(self) -> dict:
        return {
            "fork_height"  : self.fork_height,
            "tip_height"   : self.tip_height,
            "fork_depth"   : self.fork_depth,
            "chain_work"   : self.chain_work,
            "source_peer"  : self.source_peer,
            "header_count" : len(self.headers),
        }

class ChainForkManager:
    """
    Manages chain fork detection and resolution.
    Detects: orphan blocks, chain splits, potential 51% attacks.
    Selects: longest chain (most PoW work).
    """

    MAX_FORK_AGE_SECS   = 3600     # discard forks older than 1h
    MAX_FORKS           = 20
    ALARM_DEPTH         = 6        # alert if fork ≥ 6 deep

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc      = blockchain
        self._forks  : Dict[str, ForkCandidate] = {}
        self._lock   = threading.RLock()
        self._alarms : List[str] = []

    def report_fork(self, fork_height: int, tip_hash: str,
                     tip_height: int, source_peer: str) -> str:
        """Report a potential fork chain"""
        fork_id   = f"{tip_hash[:8]}_{fork_height}"
        # FIX approximate fork chain work using ChainSelector
        chain_work = tip_height * ((2**256) // max(1, bits_to_target(INITIAL_BITS)))  # conservative estimate until full headers available
        fc = ForkCandidate(
            fork_height = fork_height,
            tip_hash    = tip_hash,
            tip_height  = tip_height,
            chain_work  = chain_work,
            source_peer = source_peer,
        )
        with self._lock:
            if len(self._forks) >= self.MAX_FORKS:
                # Remove oldest
                oldest = min(self._forks.items(), key=lambda x: x[1].created_at)
                del self._forks[oldest[0]]
            self._forks[fork_id] = fc

            if fc.fork_depth >= self.ALARM_DEPTH:
                alarm = f"Deep fork detected: {fc.fork_depth} blocks from {source_peer}"
                self._alarms.append(alarm)
                print(f"  ⚠️  {alarm}")

        return fork_id

    def get_best_fork(self) -> Optional[ForkCandidate]:
        """Get the fork with most chain work"""
        with self._lock:
            forks = list(self._forks.values())
        if not forks:
            return None
        current_work = self.bc.height * bits_to_target(INITIAL_BITS)
        better = [f for f in forks if f.chain_work > current_work]
        if not better:
            return None
        return max(better, key=lambda f: f.chain_work)

    def should_reorg(self, fork: ForkCandidate) -> bool:
        """Determine if we should reorganize to this fork"""
        current_work = self.bc.height * bits_to_target(INITIAL_BITS)
        return fork.chain_work > current_work

    def expire_old_forks(self):
        """Remove stale fork candidates"""
        cutoff = time.time() - self.MAX_FORK_AGE_SECS
        with self._lock:
            old = [k for k, f in self._forks.items()
                   if f.created_at < cutoff]
            for k in old:
                del self._forks[k]

    def stats(self) -> dict:
        with self._lock:
            return {
                "active_forks" : len(self._forks),
                "alarms"       : len(self._alarms),
                "deepest_fork" : max((f.fork_depth for f in self._forks.values()),
                                      default=0),
                "best_fork"    : self.get_best_fork().to_dict() if self.get_best_fork() else None,
            }


