# MODULE 87  nebula_token_registry.py  — NBL-20 Token Registry
# ================================================================

import threading, time
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field

@dataclass
class TokenInfo:
    """Registered NBL-20 token"""
    contract_addr : str
    name          : str
    symbol        : str
    decimals      : int
    total_supply  : int
    creator       : str
    created_height: int
    icon_url      : str = ""
    website       : str = ""
    description   : str = ""
    is_verified   : bool = False
    is_scam       : bool = False

    @property
    def supply_human(self) -> float:
        return self.total_supply / 10**self.decimals

    def to_dict(self) -> dict:
        return {
            "contract"    : self.contract_addr,
            "name"        : self.name,
            "symbol"      : self.symbol,
            "decimals"    : self.decimals,
            "total_supply": self.supply_human,
            "creator"     : self.creator,
            "verified"    : self.is_verified,
            "description" : self.description,
        }

class TokenRegistry:
    """
    Registry for all NBL-20 tokens on NEBULA.
    Tracks: token metadata, balances, transfers, approvals.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc      = blockchain
        self._tokens : Dict[str, TokenInfo] = {}
        self._lock   = threading.RLock()
        self._register_native()

    def _register_native(self):
        """Register NBL as the native token"""
        self._tokens["NBL"] = TokenInfo(
            contract_addr  = "native",
            name           = CHAIN_NAME,
            symbol         = CHAIN_SYMBOL,
            decimals       = DECIMALS,
            total_supply   = self.bc.utxo.total_supply(),
            creator        = FOUNDATION_ADDRESS,
            created_height = 0,
            is_verified    = True,
            description    = "Native NEBULA blockchain token",
        )

    def register_token(self, contract_addr: str, name: str,
                        symbol: str, decimals: int,
                        total_supply: int, creator: str,
                        created_height: int,
                        description: str = "") -> TokenInfo:
        """Register a new token"""
        token = TokenInfo(
            contract_addr  = contract_addr,
            name           = name,
            symbol         = symbol,
            decimals       = decimals,
            total_supply   = total_supply,
            creator        = creator,
            created_height = created_height,
            description    = description,
        )
        with self._lock:
            self._tokens[contract_addr] = token
        return token

    def get_token(self, addr_or_symbol: str) -> Optional[TokenInfo]:
        with self._lock:
            if addr_or_symbol in self._tokens:
                return self._tokens[addr_or_symbol]
            for t in self._tokens.values():
                if t.symbol == addr_or_symbol:
                    return t
        return None

    def list_tokens(self, verified_only: bool = False) -> List[dict]:
        with self._lock:
            tokens = list(self._tokens.values())
        if verified_only:
            tokens = [t for t in tokens if t.is_verified]
        return [t.to_dict() for t in tokens]

    def verify_token(self, contract_addr: str) -> bool:
        with self._lock:
            token = self._tokens.get(contract_addr)
            if token:
                token.is_verified = True
                return True
        return False

    def flag_scam(self, contract_addr: str) -> bool:
        with self._lock:
            token = self._tokens.get(contract_addr)
            if token:
                token.is_scam = True
                return True
        return False

    def search(self, query: str) -> List[dict]:
        q = query.lower()
        with self._lock:
            return [t.to_dict() for t in self._tokens.values()
                    if q in t.name.lower() or q in t.symbol.lower()
                    or q in t.contract_addr.lower()]

    def stats(self) -> dict:
        with self._lock:
            return {
                "total"    : len(self._tokens),
                "verified" : sum(1 for t in self._tokens.values() if t.is_verified),
                "scam"     : sum(1 for t in self._tokens.values() if t.is_scam),
            }


