import threading, time, json
from typing import Dict, List, Optional
from dataclasses import dataclass, field

@dataclass
class ProtocolUpgrade:
    """A protocol upgrade proposal"""
    upgrade_id      : str
    title           : str
    description     : str
    activation_height: int
    changes         : Dict
    status          : str = "proposed"   # proposed/activated/failed
    activated_at    : Optional[int] = None

    def is_active(self, height: int) -> bool:
        return (self.status == "activated" and
                height >= self.activation_height)

    def to_dict(self) -> dict:
        return {
            "id"              : self.upgrade_id,
            "title"           : self.title,
            "activation_height": self.activation_height,
            "status"          : self.status,
            "changes"         : self.changes,
        }

class UpgradeManager:
    """
    Manages protocol upgrades for NEBULA.
    Tracks: pending, active, historical upgrades.
    Auto-activates at specified block heights.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self.bc       = blockchain
        self._upgrades: Dict[str, ProtocolUpgrade] = {}
        self._lock    = threading.RLock()
        self._register_initial_upgrades()

    def _register_initial_upgrades(self):
        """Register historical and future upgrades"""
        upgrades = [
            ProtocolUpgrade(
                upgrade_id       = "genesis",
                title            = "NEBULA Genesis",
                description      = "Initial blockchain launch",
                activation_height= 0,
                status           = "activated",
                activated_at     = 0,
                changes          = {"version": "1.0.0"},
            ),
            ProtocolUpgrade(
                upgrade_id       = "segwit",
                title            = "SegWit Activation",
                description      = "Segregated Witness (BIP141/143/144)",
                activation_height= 0,
                status           = "activated",
                activated_at     = 0,
                changes          = {"segwit": True},
            ),
            ProtocolUpgrade(
                upgrade_id       = "taproot",
                title            = "Taproot Activation",
                description      = "Taproot + Schnorr (BIP340/341/342)",
                activation_height= 0,
                status           = "activated",
                activated_at     = 0,
                changes          = {"taproot": True, "schnorr": True},
            ),
            ProtocolUpgrade(
                upgrade_id       = "musig2",
                title            = "MuSig2 Activation",
                description      = "BIP327 MuSig2 N-of-N threshold signatures",
                activation_height= 1_000,
                status           = "proposed",
                changes          = {"musig2": True},
            ),
            ProtocolUpgrade(
                upgrade_id       = "ctv",
                title            = "CTV Activation",
                description      = "OP_CHECKTEMPLATEVERIFY (BIP119)",
                activation_height= 5_000,
                status           = "proposed",
                changes          = {"ctv": True, "covenants": True},
            ),
        ]
        for u in upgrades:
            self._upgrades[u.upgrade_id] = u

    def check_activations(self, height: int):
        """Activate upgrades that have reached their height"""
        with self._lock:
            for upgrade in self._upgrades.values():
                if (upgrade.status == "proposed" and
                        height >= upgrade.activation_height):
                    upgrade.status      = "activated"
                    upgrade.activated_at = height
                    print(f"  ✅ Upgrade '{upgrade.title}' activated at height {height}")

    def is_active(self, upgrade_id: str, height: int = None) -> bool:
        h = height or self.bc.height
        upgrade = self._upgrades.get(upgrade_id)
        return upgrade.is_active(h) if upgrade else False

    def list_upgrades(self) -> List[dict]:
        with self._lock:
            return [u.to_dict() for u in self._upgrades.values()]

    def pending_upgrades(self) -> List[dict]:
        with self._lock:
            return [u.to_dict() for u in self._upgrades.values()
                    if u.status == "proposed"]

    def next_upgrade(self) -> Optional[dict]:
        """Next upcoming upgrade by activation height"""
        with self._lock:
            pending = [u for u in self._upgrades.values()
                       if u.status == "proposed"]
        if not pending:
            return None
        return min(pending, key=lambda u: u.activation_height).to_dict()


