@dataclass
class Cluster:
    """A group of addresses believed to belong to the same entity"""
    cluster_id  : int
    addresses   : Set[str] = field(default_factory=set)
    label       : str      = ""
    entity_type : str      = "unknown"   # exchange/miner/whale/personal/contract
