    def size(self) -> int:
        return len(self.addresses)

    def to_dict(self) -> dict:
        return {
            "id"          : self.cluster_id,
            "size"        : self.size(),
            "label"       : self.label or f"Cluster #{self.cluster_id}",
            "entity_type" : self.entity_type,
            "balance_nbl" : self.balance / 10**DECIMALS,
            "tx_count"    : self.tx_count,
            "tags"        : self.tags,
        }

