# MODULE 118  nebula_regression_tests.py  — Regression Tests
# ================================================================
# Regression test suite to ensure nothing breaks across versions.

import time, hashlib

def run_regression_tests(blockchain: 'NEBULABlockchain' = None) -> dict:
    """Run regression tests for all major subsystems"""
    bc      = blockchain or NEBULABlockchain()
    passed  = 0
    total   = 0
    errors  = []

    def _t(name, fn):
        nonlocal passed, total
        total += 1
        try:
            result = fn()
            if result is not False:
                passed += 1
            else:
                errors.append(f"FAIL: {name}")
        except Exception as e:
            errors.append(f"ERROR: {name}: {str(e)[:50]}")

    # Wallet
    _t("wallet_create",       lambda: NEBULAWallet.create_new(bc.utxo).first_address.startswith(PUBKEY_ADDRESS_PREFIX))
    _t("wallet_from_mnemonic",lambda: len(NEBULAWallet.create_new(bc.utxo).mnemonic.split()) == 12)
    _t("address_valid",       lambda: bool(base58check_decode(FOUNDATION_ADDRESS)))

    # Cryptography
    _t("secp256k1_sign_verify",lambda: Secp256k1.verify(
        Secp256k1.pubkey_to_bytes(Secp256k1.point_mul(12345, Secp256k1.G())),
        hashlib.sha256(b"test").digest(),
        *Secp256k1.sign(12345, hashlib.sha256(b"test").digest())))
    _t("schnorr_sign_verify",  lambda: Schnorr.verify(
        Secp256k1.pubkey_to_bytes(Secp256k1.point_mul(99999, Secp256k1.G()))[1:],
        hashlib.sha256(b"schnorr").digest(),
        Schnorr.sign(99999, hashlib.sha256(b"schnorr").digest())))
    _t("bip39_roundtrip",      lambda: len(BIP39.mnemonic_to_seed("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about")) == 64)
    _t("base58check_roundtrip",lambda: base58check_decode(base58check_encode(bytes(20), PUBKEY_ADDRESS_VERSION))[1] == bytes(20))

    # Blockchain
    _t("genesis_block_exists", lambda: bc.height >= 0)
    _t("mining_reward_correct",lambda: mining_reward(0) == INITIAL_BLOCK_REWARD)
    _t("halving_works",        lambda: mining_reward(HALVING_INTERVAL) == INITIAL_BLOCK_REWARD // 2)
    _t("utxo_balance_zero",   lambda: bc.utxo.balance("nonexistent_address_xyz") == 0)

    # Script
    _t("script_op_dup",        lambda: _test_script_dup())
    _t("script_arithmetic",    lambda: _test_script_arith())

    # DeFi
    _t("amm_creates_pool",     lambda: bool(AMMEngine(bc).create_pool("NBL", "TEST")))
    _t("staking_init",         lambda: len(StakingEngine(bc)._validators) >= 1)
    _t("oracle_has_price",     lambda: (PriceOracle(bc).get_nbl_usd() or 0) > 0)

    # NFT
    _t("nft_engine_init",      lambda: NFTEngine(bc).stats()["collections"] >= 0)

    # Advanced crypto
    _t("bls_keygen",           lambda: len(BLSSignature.keygen()[1]) == 33)
    _t("pedersen_commit",      lambda: len(PedersenCommitment.commit(100)[0]) == 64)

    return {
        "passed" : passed,
        "total"  : total,
        "pct"    : f"{passed/max(1,total)*100:.0f}%",
        "errors" : errors[:5],
        "suite"  : "regression",
    }

def _test_script_dup() -> bool:
    script = bytes([ScriptOpcode.OP_1, ScriptOpcode.OP_DUP,
                    ScriptOpcode.OP_EQUAL])
    interp = ScriptInterpreter()
    ok, _  = interp.execute(script)
    return ok and len(interp.stack) >= 1

def _test_script_arith() -> bool:
    a = _script_int_to_bytes(3)
    b = _script_int_to_bytes(7)
    r = _script_int_to_bytes(10)
    script = (bytes([len(a)]) + a + bytes([len(b)]) + b +
              bytes([ScriptOpcode.OP_ADD, len(r)]) + r +
              bytes([ScriptOpcode.OP_EQUAL]))
    interp = ScriptInterpreter()
    ok, _  = interp.execute(script)
    return ok


