def nbl_to_neb(nbl: float) -> int:
    """Convert NBL to smallest unit (neb)"""
    return int(nbl * 10**DECIMALS)

def neb_to_nbl(neb: int) -> float:
    """Convert neb to NBL"""
    return neb / 10**DECIMALS

def format_nbl(neb: int, decimals: int = 9) -> str:
    """Format neb amount as NBL string"""
    return f"{neb_to_nbl(neb):.{decimals}f} {CHAIN_SYMBOL}"

def format_nbl_compact(neb: int) -> str:
    """Format NBL with appropriate unit"""
    nbl = neb_to_nbl(neb)
    if nbl >= 1_000_000: return f"{nbl/1_000_000:.2f}M NBL"
    if nbl >= 1_000:     return f"{nbl/1_000:.2f}K NBL"
    return f"{nbl:.4f} NBL"


