# ── Final validation function ─────────────────────────────────────
def validate_nebula_installation() -> dict:
    """Validate that NEBULA is correctly installed and operational"""
    checks = {}

    # Check 1: Core blockchain
    try:
        bc = NEBULABlockchain()
        checks["blockchain"] = bc.height >= 0
    except Exception as e:
        checks["blockchain"] = False

    # Check 2: Wallet creation
    try:
        w = NEBULAWallet.create_new()
        checks["wallet"] = w.first_address.startswith(PUBKEY_ADDRESS_PREFIX)
    except Exception:
        checks["wallet"] = False

    # Check 3: Cryptography
    try:
        msg = hashlib.sha256(b"nebula_check").digest()
        r, s = Secp256k1.sign(0xdeadbeef, msg)
        pub  = Secp256k1.pubkey_to_bytes(Secp256k1.point_mul(0xdeadbeef, Secp256k1.G()))
        checks["crypto"] = Secp256k1.verify(pub, msg, r, s)
    except Exception:
        checks["crypto"] = False

    # Check 4: Script interpreter
    try:
        interp = ScriptInterpreter()
        ok, _  = interp.execute(bytes([ScriptOpcode.OP_1]))
        checks["script"] = ok
    except Exception:
        checks["script"] = False

    # Check 5: DeFi
    try:
        bc2   = NEBULABlockchain()
        amm   = AMMEngine(bc2)
        amm.create_pool("NBL", "USDT")
        checks["defi"] = True
    except Exception:
        checks["defi"] = False

    passed = sum(1 for v in checks.values() if v)
    return {
        "checks"     : checks,
        "passed"     : passed,
        "total"      : len(checks),
        "ready"      : passed == len(checks),
        "version"    : "1.0.0",
    }


