@dataclass
class PeerAddressBook:
    """
    Manages known peer addresses.
    Persists between restarts. Gossips addresses to peers.
    v10.11: wired into P2PNode (ADDR/GETADDR, reconnect after restart, peers.json). Fixes: add() no longer
    erases a known address's history, the book can no longer grow past MAX_ADDRS, eviction used a
    non-existent code path when full, gossiped addresses are validated.
    """

    MAX_ADDRS    = 20_000
    EVICT_AFTER  = 30 * 86400   # 30 days
    MAX_FAILS    = 5            # a never-successful address is dropped after this many failed attempts
    GOOD_WINDOW  = 3 * 86400    # only addresses that worked within 3 days are gossiped

    def __init__(self, allow_private: bool = None):
        self._addrs: Dict[str, PeerAddress] = {}
        self._lock  = threading.RLock()
        if allow_private is None:
            allow_private = os.environ.get("NEBULA_ALLOW_PRIVATE_PEERS") == "1"
        self.allow_private = bool(allow_private)

    # -- validation ---------------------------------------------------
    def valid(self, host, port, trusted: bool = False) -> bool:
        """Sane host/port. Gossiped (untrusted) addresses must also be public-routable unless
        NEBULA_ALLOW_PRIVATE_PEERS=1 (LAN testnets) - a peer must not be able to make this node
        connect to its own loopback / private network."""
        if not isinstance(host, str) or isinstance(port, bool) or not isinstance(port, int):
            return False
        if not (1 <= port <= 65535) or not (1 <= len(host) <= 253):
            return False
        try:
            ip = ipaddress.ip_address(host)
        except ValueError:
            if host.lower() == "localhost" or not all(c.isalnum() or c in ".-" for c in host) \
                    or host.startswith((".", "-")) or ".." in host:
                return False
            return True                                   # DNS name
        if ip.is_unspecified or ip.is_multicast or ip.is_reserved:
            return False
        if not (trusted or self.allow_private):
            if ip.is_private or ip.is_loopback or ip.is_link_local:
                return False
        return True

    # -- mutation -----------------------------------------------------
    def add(self, ip: str, port: int = DEFAULT_PORT,
             services: int = 1, source: str = "manual", trusted: bool = False) -> bool:
        """Remember an address. True only if it is NEW (so callers can connect once); a known address
        just gets its time_seen refreshed and keeps its attempts/last_success."""
        if not self.valid(ip, port, trusted):
            return False
        with self._lock:
            key = f"{ip}:{port}"
            cur = self._addrs.get(key)
            if cur is not None:
                cur.time_seen = time.time()
                return False
            if len(self._addrs) >= self.MAX_ADDRS:
                self._evict()
                if len(self._addrs) >= self.MAX_ADDRS:
                    self._drop_worst()
            self._addrs[key] = PeerAddressC(
                ip=ip, port=port, services=services, source=source)
            return True

    def _evict(self):
        cutoff = time.time() - self.EVICT_AFTER
        stale  = [k for k, a in self._addrs.items()
                  if max(a.time_seen, a.last_success) < cutoff]
        for k in stale[:max(1, len(stale)//2)]:
            del self._addrs[k]

    def _drop_worst(self):
        if self._addrs:
            k = min(self._addrs, key=lambda k: (self._addrs[k].last_success,
                                                -self._addrs[k].attempts,
                                                self._addrs[k].time_seen))
            del self._addrs[k]

    def mark_attempt(self, ip: str, port: int):
        """A connection attempt failed."""
        with self._lock:
            key = f"{ip}:{port}"
            a = self._addrs.get(key)
            if a is None:
                return
            a.attempts += 1
            if a.last_success == 0.0 and a.attempts >= self.MAX_FAILS:
                del self._addrs[key]

    def mark_good(self, ip: str, port: int):
        """Handshake completed (right chain) on an outbound connection."""
        with self._lock:
            a = self._addrs.get(f"{ip}:{port}")
            if a is not None:
                a.last_success = time.time()
                a.attempts = 0

    def remove(self, ip: str, port: int):
        with self._lock:
            self._addrs.pop(f"{ip}:{port}", None)

    # -- queries ------------------------------------------------------
    def get_random(self, n: int = 10) -> List[PeerAddress]:
        with self._lock:
            addrs = list(self._addrs.values())
        import random
        random.shuffle(addrs)
        return addrs[:n]

    def size(self) -> int:
        return len(self._addrs)

    def to_addr_message(self, n: int = 1000) -> List[dict]:
        return [a.to_dict() for a in self.get_random(n)]

    def candidates(self, n: int = 8, exclude=()) -> List[Tuple[str, int]]:
        """Best addresses to try: recently successful first, then newest; skips `exclude`
        ("host:port" strings) and addresses with too many failures."""
        ex = set(exclude)
        with self._lock:
            pool = [a for k, a in self._addrs.items()
                    if k not in ex and a.attempts < self.MAX_FAILS]
        pool.sort(key=lambda a: (a.last_success, a.time_seen), reverse=True)
        return [(a.host, a.port) for a in pool[:n]]

    def gossip_list(self, n: int = 100) -> List[dict]:
        """Addresses WE reached successfully recently (never unverified gossip)."""
        now = time.time()
        with self._lock:
            good = [a for a in self._addrs.values()
                    if a.last_success and now - a.last_success <= self.GOOD_WINDOW]
        good.sort(key=lambda a: a.last_success, reverse=True)
        return [{"host": a.host, "port": a.port} for a in good[:n]]

    def stats(self) -> dict:
        with self._lock:
            vals = list(self._addrs.values())
        return {"known": len(vals),
                "verified": sum(1 for a in vals if a.last_success),
                "gossip_sourced": sum(1 for a in vals if a.source == "gossip")}

    # -- persistence --------------------------------------------------
    def save(self, path: str) -> bool:
        """Atomic write (tmp + rename). Never raises."""
        try:
            with self._lock:
                rows = [{"host": a.host, "port": a.port, "services": a.services,
                         "time_seen": a.time_seen, "attempts": a.attempts,
                         "last_success": a.last_success, "source": a.source}
                        for a in self._addrs.values()]
            tmp = f"{path}.tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"version": 1, "addrs": rows}, f)
            os.replace(tmp, path)
            return True
        except Exception as e:
            log.warning("peers.json save failed: %s", e)
            return False

    def load(self, path: str) -> int:
        """Load saved addresses; a missing/corrupt file or bad rows are ignored. Returns rows loaded."""
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            rows = data.get("addrs", []) if isinstance(data, dict) else []
        except Exception:
            return 0
        n = 0
        for r in rows[:self.MAX_ADDRS]:
            try:
                if not isinstance(r, dict):
                    continue
                host, port = r.get("host"), r.get("port")
                if not self.add(host, port, int(r.get("services", 1)),
                                source=str(r.get("source", "saved"))[:20], trusted=True):
                    continue
                a = self._addrs[f"{host}:{port}"]
                a.time_seen    = float(r.get("time_seen", a.time_seen))
                a.attempts     = int(r.get("attempts", 0))
                a.last_success = float(r.get("last_success", 0.0))
                n += 1
            except Exception:
                continue
        return n


