class TransactionIndex:
    """
    Full transaction index for fast lookups.
    Maps txid → block height + position.
    Also indexes by address for wallet queries.

    v10.10: now WIRED to the chain through TxIndexLayer (below). Added unindex_block() (reorg),
    index_address() (spender side) and an O(1) duplicate check (the old list scan was quadratic
    for busy addresses such as the miner address).
    """

    def __init__(self):
        self._txid_to_block:  Dict[str, Tuple[int, int]] = {}  # txid -> (height, pos)
        self._addr_to_txids:  Dict[str, List[str]]       = {}  # addr -> [txid]
        self._addr_seen:      Dict[str, set]             = {}  # addr -> {txid}  (v10.10)
        self._lock            = threading.RLock()

    def index_address(self, addr: str, txid: str):
        """v10.10: attach txid to an address history (no-op if already there)."""
        if not addr:
            return
        with self._lock:
            seen = self._addr_seen.setdefault(addr, set())
            if txid in seen:
                return
            seen.add(txid)
            self._addr_to_txids.setdefault(addr, []).append(txid)

    def index_block(self, block: 'Block'):
        with self._lock:
            for pos, tx in enumerate(block.transactions):
                self._txid_to_block[tx.txid] = (block.height, pos)
                for out in tx.outputs:
                    addr = out.address
                    if addr:
                        self.index_address(addr, tx.txid)

    def unindex_block(self, block: 'Block', extra_addrs=None):
        """v10.10: undo index_block() for a block that left the main chain (reorg).
        extra_addrs: optional {txid: [addr, ...]} of spender-side addresses to drop as well."""
        with self._lock:
            for tx in block.transactions:
                loc = self._txid_to_block.get(tx.txid)
                if loc is not None and loc[0] == block.height:
                    del self._txid_to_block[tx.txid]
                addrs = {o.address for o in tx.outputs if o.address}
                if extra_addrs:
                    addrs.update(extra_addrs.get(tx.txid, ()))
                for addr in addrs:
                    seen = self._addr_seen.get(addr)
                    if seen is None or tx.txid not in seen:
                        continue
                    seen.discard(tx.txid)
                    lst = self._addr_to_txids.get(addr, [])
                    if lst and lst[-1] == tx.txid:
                        lst.pop()
                    elif tx.txid in lst:
                        lst.remove(tx.txid)
                    if not lst:
                        self._addr_to_txids.pop(addr, None)
                        self._addr_seen.pop(addr, None)

    def get_tx_location(self, txid: str) -> Optional[Tuple[int, int]]:
        return self._txid_to_block.get(txid)

    def get_address_txids(self, address: str,
                           limit: int = 100) -> List[str]:
        return self._addr_to_txids.get(address, [])[-limit:]

    def address_tx_count(self, address: str) -> int:
        """v10.10: number of distinct transactions that touch the address."""
        return len(self._addr_to_txids.get(address, ()))

    def tx_count(self) -> int:
        return len(self._txid_to_block)

    def indexed_addresses(self) -> int:
        return len(self._addr_to_txids)

    def stats(self) -> dict:
        return {
            "indexed_txs":     self.tx_count(),
            "indexed_addrs":   self.indexed_addresses(),
        }


class TxIndexLayer:
    """v10.10: connects TransactionIndex to the REAL chain.

    It is a chain listener (like NEBULAStateLayer): on_connect() indexes every new main-chain block,
    on_reorg() un-indexes the blocks that left the chain and indexes the new ones, and any doubt
    (gap, error) marks it stale so the next query rebuilds it by replaying the chain. A listener error
    can never reject a block. It registers itself as `blockchain._tx_index`, which is exactly what the
    REST API (/api/tx/<txid>) and BlockExplorer already looked for but nothing ever provided
    (before v10.10 a confirmed transaction could never be found through the API, and BlockExplorer
    only searched the last 100 blocks).

    Address history = outputs paid to the address (P2PKH) + inputs it signed (address derived from the
    pubkey in a P2PKH script_sig; that pubkey must hash to the spent output, so it is exact).
    P2SH outputs have no `.address` in TxOutput and are therefore not indexed."""

    _create_lock = threading.Lock()

    def __init__(self, blockchain):
        self.bc = blockchain
        self.index = TransactionIndex()
        self._lock = threading.RLock()
        self._height = -1
        self._stale = False
        self._senders: Dict[str, List[str]] = {}    # txid -> spender addresses (for exact undo)

    # ── wiring ───────────────────────────────────────────────────
    @classmethod
    def for_chain(cls, blockchain):
        """The index of this chain; created + attached on first use (idempotent, thread-safe)."""
        with cls._create_lock:
            cur = getattr(blockchain, "_tx_index", None)
            if isinstance(cur, cls):
                return cur
            return cls(blockchain).attach()

    def attach(self):
        with self.bc._lock:
            self.bc.add_listener(self)
            self.bc._tx_index = self
            self.rebuild()
        return self

    def detach(self):
        with self.bc._lock:
            if self in self.bc._listeners:
                self.bc._listeners.remove(self)
            if getattr(self.bc, "_tx_index", None) is self:
                self.bc._tx_index = None

    def rebuild(self):
        with self._lock:
            self.index = TransactionIndex()
            self._senders = {}
            self._height = -1
            self._stale = False
            for blk in list(self.bc._chain):
                self._add(blk)

    def _fresh(self):
        if self._stale:
            with self.bc._lock:
                if self._stale:
                    self.rebuild()

    # ── indexing ────────────────────────────────────────────────
    @staticmethod
    def _input_address(txin) -> Optional[str]:
        ss = txin.script_sig
        try:
            sl = ss[0]
            if sl == 0 or sl > 75:
                return None
            pl = ss[1 + sl]
            if pl != 33 or len(ss) != 2 + sl + pl:
                return None
            return pubkey_to_address(bytes(ss[2 + sl:2 + sl + pl]))
        except Exception:
            return None

    def _add(self, blk):
        self.index.index_block(blk)
        for tx in blk.transactions:
            if tx.is_coinbase:
                continue
            addrs = []
            for txin in tx.inputs:
                a = self._input_address(txin)
                if a and a not in addrs:
                    addrs.append(a)
                    self.index.index_address(a, tx.txid)
            if addrs:
                self._senders[tx.txid] = addrs
        self._height = blk.height

    def _remove(self, blk):
        extra = {tx.txid: self._senders.pop(tx.txid, []) for tx in blk.transactions}
        self.index.unindex_block(blk, extra)
        self._height = blk.height - 1

    def on_connect(self, block):
        with self._lock:
            if self._stale:
                return
            if block.height != self._height + 1:
                self._stale = True
                return
            self._add(block)

    def on_reorg(self, old_blocks, new_blocks, ancestor_height):
        with self._lock:
            if self._stale:
                return
            if (not new_blocks or self._height != (old_blocks[-1].height if old_blocks else ancestor_height)
                    or (old_blocks and old_blocks[0].height != ancestor_height + 1)
                    or new_blocks[0].height != ancestor_height + 1):
                self._stale = True
                return
            for blk in reversed(list(old_blocks)):
                self._remove(blk)
            for blk in new_blocks:
                self._add(blk)

    # ── queries ─────────────────────────────────────────────────
    def locate(self, txid: str):
        """(height, position) of a CONFIRMED transaction, or None."""
        self._fresh()
        with self._lock:
            return self.index.get_tx_location(txid)

    def get(self, txid: str):
        """The confirmed Transaction object, or None."""
        loc = self.locate(txid)
        if not loc:
            return None
        blk = self.bc.get_block(loc[0])
        if blk and loc[1] < len(blk.transactions) and blk.transactions[loc[1]].txid == txid:
            return blk.transactions[loc[1]]
        return None

    def address_txids(self, address: str, limit: int = 100) -> List[str]:
        self._fresh()
        with self._lock:
            return list(self.index.get_address_txids(address, limit))

    def address_tx_count(self, address: str) -> int:
        self._fresh()
        with self._lock:
            return self.index.address_tx_count(address)

    def stats(self) -> dict:
        self._fresh()
        with self._lock:
            d = dict(self.index.stats())
            d["indexed_height"] = self._height
            return d


from collections import OrderedDict as _FeeOD


class FeeLayer:
    """v10.11: connects FeeEstimator to the REAL chain.

    A chain listener (same pattern as TxIndexLayer / NEBULAStateLayer): on every connected block it
      1. reads the exact fee of every confirmed transaction (inputs come from the block's undo data,
         so it works even for transactions this node never saw in its mempool),
      2. records how many blocks each one waited (first-seen height, stamped from per-block snapshots
         of the real Mempool; a tx never seen before its block waited exactly 1 block),
      3. records every transaction that is still waiting after the block (a miss for the target it
         has now reached),
      4. decays old observations.
    Fee rate = fee // byte_size  (neb per byte - the same definition Mempool.submit uses).
    A listener error can never reject a block. Reorgs: new-chain blocks are recorded, transactions that
    were already counted are skipped (txid memory), old observations are not undone (statistics only).
    Not persisted: after a restart the estimator warms up from the last blocks that still carry undo data
    (normally none) and from new blocks; until enough data exists estimates say source="default"."""

    _create_lock = threading.Lock()
    SNAPSHOT_CAP = 20_000
    RECORDED_CAP = 50_000
    WARMUP_BLOCKS = 144

    def __init__(self, blockchain):
        self.bc = blockchain
        self.estimator = FeeEstimator()
        self._lock = threading.RLock()
        self._height = -1
        self._first_seen: Dict[str, int] = {}
        self._recorded = _FeeOD()
        self._st = {"blocks": 0, "txs_recorded": 0, "blocks_skipped": 0, "gaps": 0, "reorgs": 0}

    # -- wiring ------------------------------------------------------
    @classmethod
    def for_chain(cls, blockchain):
        """The fee layer of this chain; created + attached on first use (idempotent, thread-safe)."""
        with cls._create_lock:
            cur = getattr(blockchain, "_fee_layer", None)
            if isinstance(cur, cls):
                return cur
            return cls(blockchain).attach()

    def attach(self):
        with self.bc._lock:
            self.bc.add_listener(self)
            self.bc._fee_layer = self
            # Mempool consumers (APIHandler/BlockExplorer fee endpoints) look for mempool.fee_estimates()
            try:
                self.bc.mempool.fee_estimates = self.simple_table
            except Exception:
                _NB_SWALLOW_LOG.debug("swallowed Exception in FeeLayer.attach", exc_info=True)
            chain = list(self.bc._chain)
            for blk in chain[-self.WARMUP_BLOCKS:]:
                self._process(blk, snapshot=False)
            self._height = self.bc.height
            self._stamp_pending(self.bc.height)
        return self

    def detach(self):
        with self.bc._lock:
            if self in self.bc._listeners:
                self.bc._listeners.remove(self)
            if getattr(self.bc, "_fee_layer", None) is self:
                self.bc._fee_layer = None

    # -- core --------------------------------------------------------
    @staticmethod
    def _block_fees(blk):
        """[(txid, fee_rate, fee, size)] for the non-coinbase txs of a block, or None if the exact
        fees cannot be proven (no undo data / misaligned / negative fee)."""
        txs = [t for t in blk.transactions if not t.is_coinbase]
        if not txs:
            return []
        spent = getattr(blk, "_undo_spent", None)
        if not spent or len(spent) != sum(len(t.inputs) for t in txs):
            return None
        out, pos = [], 0
        for t in txs:
            total_in = 0
            for inp in t.inputs:
                e = spent[pos]
                pos += 1
                if e.txid != inp.outpoint.txid or e.index != inp.outpoint.index:
                    return None
                total_in += e.value
            fee = total_in - sum(o.value for o in t.outputs)
            if fee < 0:
                return None
            size = max(1, t.byte_size())
            out.append((t.txid, float(fee // size), fee, size))
        return out

    def _process(self, blk, snapshot=True):
        h = blk.height
        fees = self._block_fees(blk)
        if fees is None:
            self._st["blocks_skipped"] += 1
        else:
            for txid, rate, _fee, _size in fees:
                if txid in self._recorded:
                    continue
                first = self._first_seen.get(txid, h - 1)     # never seen before its block -> waited 1
                self.estimator.record_confirmed(rate, max(1, h - first))
                self._recorded[txid] = None
                if len(self._recorded) > self.RECORDED_CAP:
                    self._recorded.popitem(last=False)
                self._st["txs_recorded"] += 1
        for t in blk.transactions:
            self._first_seen.pop(t.txid, None)
        self.estimator.decay_all()
        self._st["blocks"] += 1
        self._height = h
        if snapshot:
            self._snapshot(h)

    def _pending(self):
        mp = self.bc.mempool
        with mp._lock:
            return list(mp._meta.items())[:self.SNAPSHOT_CAP]

    def _stamp_pending(self, h):
        for txid, _m in self._pending():
            self._first_seen.setdefault(txid, h)

    def _snapshot(self, h):
        live = set()
        for txid, (rate, _size) in self._pending():
            first = self._first_seen.get(txid)
            if first is None:
                first = h - 1                                  # arrived after the previous block
                self._first_seen[txid] = first
            self.estimator.record_unconfirmed(float(rate), h - first)
            live.add(txid)
        for k in [k for k in self._first_seen if k not in live]:
            del self._first_seen[k]                            # left the pool unconfirmed (evicted)

    # -- listener interface -----------------------------------------
    def on_connect(self, block):
        with self._lock:
            if block.height != self._height + 1:
                self._st["gaps"] += 1
                self._first_seen.clear()
            self._process(block)

    def on_reorg(self, old_blocks, new_blocks, ancestor_height):
        with self._lock:
            self._st["reorgs"] += 1
            self._first_seen.clear()
            for blk in new_blocks:
                self._process(blk, snapshot=False)
            self._height = new_blocks[-1].height if new_blocks else ancestor_height
            self._snapshot(self._height)

    # -- queries -----------------------------------------------------
    def estimate(self, target_blocks: int = 6, tx_size: int = 250, conservative: bool = False) -> dict:
        target_blocks = max(1, int(target_blocks))
        tx_size = max(1, int(tx_size))
        with self._lock:
            rate = self.estimator.estimate_fee(target_blocks)
            samples = self.estimator.samples(target_blocks)
        source = "data" if rate is not None else "default"
        r = float(rate or 0.0)
        if conservative and r:
            r *= 1.2
        fee = max(MIN_TX_FEE, int(math.ceil(r * tx_size)))     # the mempool rejects fee < MIN_TX_FEE
        return {"target_blocks": target_blocks, "tx_size": tx_size, "fee_rate": r, "fee": fee,
                "fee_nbl": fee / 10 ** DECIMALS, "source": source, "samples": round(samples, 1)}

    def table(self, tx_size: int = 250) -> dict:
        return {f"{t} blocks": self.estimate(t, tx_size) for t in FEE_ESTIMATION_BLOCKS}

    def simple_table(self) -> dict:
        """{"N blocks": neb/byte (int)} - the shape the old mempool.fee_estimates() consumers expect."""
        return {k: max(1, int(math.ceil(v["fee_rate"] or MIN_TX_FEE / 250)))
                for k, v in self.table().items()}

    def stats(self) -> dict:
        with self._lock:
            d = dict(self._st)
            d["height"] = self._height
            d["pending_tracked"] = len(self._first_seen)
            return d


