class MarginPosition:
    """A leveraged trading position."""

    def __init__(self, pos_id: str, trader: str,
                  pair: str, side: str, size: float,
                  leverage: float, entry_price: float,
                  collateral: float):
        self.pos_id      = pos_id
        self.trader      = trader
        self.pair        = pair
        self.side        = side       # "long" or "short"
        self.size        = size
        self.leverage    = leverage
        self.entry_price = entry_price
        self.collateral  = collateral
        self.margin_used = size / leverage
        self.liquidation_price = self._calc_liq_price()
        self.open        = True
        self.pnl         = 0.0

    def _calc_liq_price(self) -> float:
        if self.side == "long":
            return self.entry_price * (1 - 1/self.leverage + 0.005)
        else:
            return self.entry_price * (1 + 1/self.leverage - 0.005)

    def update_pnl(self, current_price: float):
        if self.side == "long":
            self.pnl = (current_price - self.entry_price) * self.size
        else:
            self.pnl = (self.entry_price - current_price) * self.size

    def is_liquidatable(self, current_price: float) -> bool:
        if self.side == "long":
            return current_price <= self.liquidation_price
        return current_price >= self.liquidation_price

    def to_dict(self, current_price: float = 0) -> dict:
        if current_price:
            self.update_pnl(current_price)
        return {
            "pos_id":      self.pos_id,
            "trader":      self.trader,
            "pair":        self.pair,
            "side":        self.side,
            "size":        f"{self.size:.4f}",
            "leverage":    f"{self.leverage}x",
            "entry":       f"{self.entry_price:.4f}",
            "liq_price":   f"{self.liquidation_price:.4f}",
            "pnl":         f"{self.pnl:.4f}",
            "open":        self.open,
        }

class MarginTradingEngine:
    """
    Margin trading with up to 10x leverage on NEBULA DEX.
    Long/short positions with automatic liquidation.
    """

    MAX_LEVERAGE     = 10
    MAINTENANCE_MARGIN = 0.05   # 5% maintenance margin
    LIQUIDATION_FEE  = 0.015    # 1.5% liquidation fee

    def __init__(self, blockchain: 'NEBULABlockchain',
                  oracle: 'OracleV2' = None):
        self._bc         = blockchain
        self._oracle     = oracle
        self._positions: Dict[str, MarginPosition] = {}
        self._lock       = threading.RLock()

    def open_position(self, trader: str, pair: str,
                       side: str, size_nbl: float,
                       leverage: float) -> Tuple[bool, str]:
        with self._lock:
            if leverage > self.MAX_LEVERAGE:
                return False, f"Max leverage: {self.MAX_LEVERAGE}x"
            if side not in ("long", "short"):
                return False, "Side must be 'long' or 'short'"
            collateral = size_nbl / leverage
            if self._bc.utxo.balance(trader) < int(collateral * 10**DECIMALS):
                return False, "Insufficient collateral"
            price = (self._oracle.price(pair) if self._oracle else 1.0) or 1.0
            pid   = hashlib.sha256(
                f"MARGIN:{trader}:{pair}:{side}:{time.time()}".encode()
            ).hexdigest()[:16]
            self._positions[pid] = MarginPosition(
                pos_id      = pid,
                trader      = trader,
                pair        = pair,
                side        = side,
                size        = size_nbl,
                leverage    = leverage,
                entry_price = price,
                collateral  = collateral,
            )
            return True, pid

    def close_position(self, pos_id: str,
                        trader: str) -> Tuple[bool, float]:
        with self._lock:
            pos = self._positions.get(pos_id)
            if not pos or pos.trader != trader or not pos.open:
                return False, 0.0
            price = (self._oracle.price(pos.pair)
                     if self._oracle else pos.entry_price) or pos.entry_price
            pos.update_pnl(price)
            pos.open = False
            return True, pos.pnl

    def check_liquidations(self) -> List[str]:
        liquidated = []
        with self._lock:
            for pid, pos in list(self._positions.items()):
                if not pos.open:
                    continue
                price = (self._oracle.price(pos.pair)
                         if self._oracle else pos.entry_price) or pos.entry_price
                if pos.is_liquidatable(price):
                    pos.open = False
                    liquidated.append(pid)
        return liquidated

    def trader_positions(self, trader: str) -> List[dict]:
        price_fn = lambda p: (self._oracle.price(p.pair)
                               if self._oracle else 0) or 0
        return [p.to_dict(price_fn(p)) for p in self._positions.values()
                if p.trader == trader and p.open]

    def margin_stats(self) -> dict:
        with self._lock:
            open_pos    = sum(1 for p in self._positions.values() if p.open)
            total_size  = sum(p.size for p in self._positions.values() if p.open)
        return {
            "open_positions":  open_pos,
            "total_size_nbl":  f"{total_size:.3f}",
            "max_leverage":    f"{self.MAX_LEVERAGE}x",
        }


# ================================================================
# MODULE 235  nebula_options.py — Options Trading
# ================================================================

class OptionType(_enum.Enum):
    CALL = "call"
    PUT  = "put"

@dataclass
class OptionsContract:
    contract_id:  str
    underlying:   str       # e.g. "NBL/USD"
    option_type:  OptionType
    strike_price: float
    expiry_block: int
    premium:      float
    size:         float     # contract size in NBL
    writer:       str
    buyer:        str = ""
    exercised:    bool = False
    expired:      bool = False

    def is_in_the_money(self, current_price: float) -> bool:
        if self.option_type == OptionType.CALL:
            return current_price > self.strike_price
        else:
            return current_price < self.strike_price

    def intrinsic_value(self, current_price: float) -> float:
        if self.option_type == OptionType.CALL:
            return max(0, current_price - self.strike_price) * self.size
        else:
            return max(0, self.strike_price - current_price) * self.size

    def to_dict(self) -> dict:
        return {
            "contract_id":  self.contract_id,
            "underlying":   self.underlying,
            "type":         self.option_type.value,
            "strike":       f"{self.strike_price:.4f}",
            "expiry_block": self.expiry_block,
            "premium":      f"{self.premium:.6f} NBL",
            "size":         f"{self.size:.4f} NBL",
            "writer":       self.writer,
            "buyer":        self.buyer,
            "exercised":    self.exercised,
        }

class OptionsMarket:
    """
    Decentralized options market for NEBULA.
    European-style options on NBL and other assets.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                  oracle: 'OracleV2' = None):
        self._bc        = blockchain
        self._oracle    = oracle
        self._contracts: Dict[str, OptionsContract] = {}
        self._lock      = threading.RLock()

    def write_option(self, writer: str, underlying: str,
                      option_type: OptionType,
                      strike: float, expiry_days: int,
                      premium: float, size: float) -> Tuple[bool, str]:
        with self._lock:
            collateral = int(size * 10**DECIMALS)
            if self._bc.utxo.balance(writer) < collateral:
                return False, "Insufficient collateral"
            expiry_block = self._bc.height + expiry_days * 144
            cid = hashlib.sha256(
                f"OPT:{writer}:{underlying}:{strike}:{time.time()}".encode()
            ).hexdigest()[:16]
            self._contracts[cid] = OptionsContract(
                contract_id  = cid,
                underlying   = underlying,
                option_type  = option_type,
                strike_price = strike,
                expiry_block = expiry_block,
                premium      = premium,
                size         = size,
                writer       = writer,
            )
            return True, cid

    def buy_option(self, buyer: str,
                    contract_id: str) -> Tuple[bool, str]:
        with self._lock:
            opt = self._contracts.get(contract_id)
            if not opt or opt.buyer:
                return False, "Not available"
            if self._bc.height >= opt.expiry_block:
                opt.expired = True
                return False, "Option expired"
            premium_raw = int(opt.premium * 10**DECIMALS)
            if self._bc.utxo.balance(buyer) < premium_raw:
                return False, "Insufficient premium"
            opt.buyer = buyer
            return True, f"Bought {opt.option_type.value} option on {opt.underlying}"

    def exercise(self, buyer: str,
                  contract_id: str) -> Tuple[bool, float]:
        with self._lock:
            opt = self._contracts.get(contract_id)
            if not opt or opt.buyer != buyer:
                return False, 0.0
            if opt.exercised or opt.expired:
                return False, 0.0
            if self._bc.height >= opt.expiry_block:
                opt.expired = True
                return False, 0.0
            price = (self._oracle.price(opt.underlying)
                     if self._oracle else opt.strike_price) or opt.strike_price
            if not opt.is_in_the_money(price):
                return False, 0.0
            payout = opt.intrinsic_value(price)
            opt.exercised = True
            return True, payout

    def expire_contracts(self) -> int:
        cur     = self._bc.height
        expired = 0
        with self._lock:
            for opt in self._contracts.values():
                if not opt.expired and not opt.exercised and cur >= opt.expiry_block:
                    opt.expired = True
                    expired    += 1
        return expired

    def open_contracts(self) -> List[dict]:
        cur = self._bc.height
        return [opt.to_dict() for opt in self._contracts.values()
                if not opt.expired and not opt.exercised
                and cur < opt.expiry_block]

    def options_stats(self) -> dict:
        with self._lock:
            total     = len(self._contracts)
            open_c    = sum(1 for o in self._contracts.values()
                            if not o.expired and not o.exercised)
            exercised = sum(1 for o in self._contracts.values() if o.exercised)
        return {
            "total_contracts": total,
            "open":            open_c,
            "exercised":       exercised,
            "expired":         total - open_c - exercised,
        }


