# ================================================================
# MODULE 239  nebula_defi_utils.py — DeFi Utility Functions
# ================================================================

def impermanent_loss(initial_price: float,
                      current_price: float) -> float:
    """
    Calculate impermanent loss for a 50/50 AMM LP position.
    Returns IL as a percentage (negative means loss).
    """
    ratio = current_price / initial_price
    il    = 2 * ratio**0.5 / (1 + ratio) - 1
    return il * 100

def apy_to_apr(apy: float, compounding_periods: int = 365) -> float:
    """Convert APY to APR."""
    return ((1 + apy) ** (1 / compounding_periods) - 1) * compounding_periods

def apr_to_apy(apr: float, compounding_periods: int = 365) -> float:
    """Convert APR to APY."""
    return (1 + apr / compounding_periods) ** compounding_periods - 1

def price_impact(amount_in: float, reserve_in: float,
                  reserve_out: float, fee: float = 0.003) -> float:
    """Calculate price impact for an AMM swap."""
    amount_with_fee = amount_in * (1 - fee)
    new_reserve_in  = reserve_in + amount_with_fee
    new_reserve_out = reserve_in * reserve_out / new_reserve_in
    amount_out      = reserve_out - new_reserve_out
    old_price       = reserve_out / reserve_in
    new_price       = (reserve_out - amount_out) / new_reserve_in
    return abs(new_price - old_price) / old_price * 100

def optimal_swap_amount(reserve_a: float, reserve_b: float,
                          pool_fee: float = 0.003) -> float:
    """
    Optimal swap amount for single-asset LP provision.
    Calculates how much to swap before adding liquidity.
    """
    fee_factor = 1 - pool_fee
    return (reserve_a * ((reserve_a * fee_factor**2 +
            4 * fee_factor * reserve_a)**0.5 - reserve_a * fee_factor)) / \
           (2 * fee_factor * reserve_a)

def health_factor(collateral_value: float, debt_value: float,
                   liquidation_threshold: float = 0.80) -> float:
    """Calculate lending health factor."""
    if debt_value == 0:
        return float('inf')
    return collateral_value * liquidation_threshold / debt_value

def liquidation_price_long(entry: float, leverage: float,
                             maintenance_margin: float = 0.05) -> float:
    """Calculate liquidation price for a long position."""
    return entry * (1 - (1 / leverage) + maintenance_margin)

def liquidation_price_short(entry: float, leverage: float,
                              maintenance_margin: float = 0.05) -> float:
    """Calculate liquidation price for a short position."""
    return entry * (1 + (1 / leverage) - maintenance_margin)

def compound_interest(principal: float, apy: float,
                        years: float) -> float:
    """Calculate compound interest earnings."""
    return principal * ((1 + apy) ** years - 1)

def calculate_fees_earned(liquidity: float, volume: float,
                            fee_tier: float = 0.003) -> float:
    """Estimate fees earned as LP given liquidity share."""
    return volume * fee_tier * liquidity

def nbbl_to_usd(amount: float, price: float) -> float:
    """Convert NBL amount to USD."""
    return amount * price

def usd_to_nbl(amount: float, price: float) -> float:
    """Convert USD amount to NBL."""
    return amount / price if price > 0 else 0

def parse_nbl(amount_str: str) -> int:
    """Parse NBL amount string to raw integer."""
    clean = amount_str.replace(" NBL", "").replace(",", "")
    return int(float(clean) * 10**DECIMALS)

DEFI_UTILS = {
    "impermanent_loss":        impermanent_loss,
    "apy_to_apr":              apy_to_apr,
    "apr_to_apy":              apr_to_apy,
    "price_impact":            price_impact,
    "optimal_swap_amount":     optimal_swap_amount,
    "health_factor":           health_factor,
    "liquidation_price_long":  liquidation_price_long,
    "liquidation_price_short": liquidation_price_short,
    "compound_interest":       compound_interest,
    "format_nbl":              format_nbl,
    "parse_nbl":               parse_nbl,
}


