        factory = ContractFactory(self._bc)
        if contract_type == "erc20":
            cid = factory.deploy_erc20(
                deployer, "TestToken", "TEST", 18, 1_000_000)
            return {"contract_id": cid, "type": "ERC20"}
        return {"error": "Unknown contract type"}

