        """Generate sample transactions for testing."""
        w = NEBULAWallet.generate()
        self._bc.fund_address(w.first_address, n * 100)
        txids = []
        for _ in range(n):
            dest = NEBULAWallet.generate().first_address
            txid = "test_" + secrets.token_hex(16)
            txids.append(txid)
