# MODULE 431  nebula_chain_indexer_v2.py — Chain Indexer v2
# ================================================================

class ChainIndexerV2:
    """Enhanced blockchain indexer with full event indexing."""

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc          = blockchain
        self._tx_by_addr:  Dict[str, List[str]]  = {}
        self._events:      List[dict]             = []
        self._token_txs:   Dict[str, List[dict]]  = {}
        self._lock         = threading.RLock()

    def index_transaction(self, tx: 'Transaction', height: int):
        with self._lock:
            for out in tx.outputs:
                if out.address:
                    if out.address not in self._tx_by_addr:
                        self._tx_by_addr[out.address] = []
                    if tx.txid not in self._tx_by_addr[out.address]:
                        self._tx_by_addr[out.address].append(tx.txid)

    def index_event(self, event_type: str, data: dict,
                     contract_id: str = ""):
        with self._lock:
            self._events.append({
                "type":     event_type,
                "data":     data,
                "contract": contract_id,
                "block":    self._bc.height,
                "ts":       time.time(),
            })

    def get_address_txs(self, address: str,
                         limit: int = 50) -> List[str]:
        return self._tx_by_addr.get(address, [])[-limit:]

    def get_events(self, event_type: str = None,
                    n: int = 100) -> List[dict]:
        events = list(self._events)
        if event_type:
            events = [e for e in events if e["type"] == event_type]
        return events[-n:]

    def indexer_v2_stats(self) -> dict:
        with self._lock:
            total_txs = sum(len(v) for v in self._tx_by_addr.values())
        return {
            "addresses_indexed": len(self._tx_by_addr),
            "total_txs":         total_txs,
            "events_indexed":    len(self._events),
        }


# ================================================================
# MODULE 432  nebula_reward_booster.py — Reward Booster
# ================================================================

class RewardBooster:
    """
    Reward booster for NEBULA — multiplies rewards based on activity.
    """

    BOOST_TIERS = [
        (0,     1.00),   # no boost
        (1_000, 1.10),   # 10%
        (10_000, 1.25),
        (100_000, 1.50),
        (1_000_000, 2.0),
    ]

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc     = blockchain
        self._boosts: Dict[str, float] = {}

    def compute_boost(self, address: str) -> float:
        bal = self._bc.utxo.balance(address) / 10**DECIMALS
        boost = 1.0
        for threshold, mult in self.BOOST_TIERS:
            if bal >= threshold:
                boost = mult
        self._boosts[address] = boost
        return boost

    def boosted_reward(self, address: str, base: int) -> int:
        boost = self.compute_boost(address)
        return int(base * boost)

    def boost_summary(self, address: str) -> dict:
        boost = self.compute_boost(address)
        bal   = self._bc.utxo.balance(address) / 10**DECIMALS
        nxt   = next(
            ((t, m) for t, m in self.BOOST_TIERS if t > bal),
            None
        )
        return {
            "address":    address,
            "balance":    f"{bal:.3f} NBL",
            "boost":      f"{boost:.2f}x",
            "next_tier":  f"{nxt[0]:,} NBL → {nxt[1]}x" if nxt else "Max tier",
        }


# ================================================================
# MODULE 433  nebula_liquidity_depth.py — Liquidity Depth
# ================================================================

class LiquidityDepthAnalyzer:
    """Analyzes liquidity depth across NEBULA DEX pools."""

    def __init__(self, dex: 'NEBULADex'):
        self._dex = dex

    def depth_at_price(self, pair: str,
                        slippage_pct: float = 0.01) -> dict:
        """How much can be bought/sold within slippage?"""
        a, b = pair.split("/") if "/" in pair else (pair, "USDT")
        for pool in self._dex._pools.values():
            if pool.token_a == a and pool.token_b == b:
                if pool.reserve_a > 0 and pool.reserve_b > 0:
                    spot = pool.reserve_b / pool.reserve_a
                    max_buy_r  = pool.reserve_b * slippage_pct
                    max_sell_r = pool.reserve_a * slippage_pct
                    return {
                        "pair":        pair,
                        "spot_price":  f"{spot:.6f}",
                        "slippage":    f"{slippage_pct*100:.1f}%",
                        "buy_depth":   f"{max_buy_r/10**DECIMALS:.3f} {b}",
                        "sell_depth":  f"{max_sell_r/10**DECIMALS:.3f} {a}",
                        "reserve_a":   f"{pool.reserve_a/10**DECIMALS:.3f}",
                        "reserve_b":   f"{pool.reserve_b/10**DECIMALS:.3f}",
                    }
        return {"pair": pair, "depth": "No liquidity"}

    def all_pools_depth(self) -> List[dict]:
        results = []
        for pool in self._dex._pools.values():
            pair = f"{pool.token_a}/{pool.token_b}"
            results.append(self.depth_at_price(pair, 0.01))
        return results

    def most_liquid_pools(self, n: int = 5) -> List[dict]:
        pools = []
        for pool in self._dex._pools.values():
            tvl = pool.reserve_a + pool.reserve_b
            pools.append({
                "pair": f"{pool.token_a}/{pool.token_b}",
                "tvl":  tvl,
                "fee":  pool.fee_bps,
            })
        return sorted(pools, key=lambda p: -p["tvl"])[:n]


# ================================================================
# MODULE 434  nebula_security_audit_v2.py — Security Audit v2
# ================================================================

class SecurityAuditV2:
    """Automated security audit for NEBULA protocols."""

    VULNERABILITY_DB = {
        "reentrancy":          "Contract calls external contract before updating state",
        "integer_overflow":    "Arithmetic operation may overflow",
        "access_control":      "Missing access control on privileged function",
        "front_running":       "Transaction order dependency vulnerability",
        "price_manipulation":  "Oracle price can be manipulated",
        "flash_loan_attack":   "State changes vulnerable to flash loans",
        "signature_replay":    "Missing nonce in signed messages",
    }

    def audit_protocol(self, protocol_name: str,
                        code_size: int,
                        has_oracle: bool = True,
                        has_flash_loans: bool = False) -> dict:
        findings = []
        risk_score = 0
        if has_oracle:
            findings.append({
                "type":     "price_manipulation",
                "severity": "medium",
                "message":  "Consider TWAP oracle instead of spot price",
            })
            risk_score += 10
        if has_flash_loans:
            findings.append({
                "type":     "flash_loan_attack",
                "severity": "high",
                "message":  "Add reentrancy guard and checks-effects-interactions",
            })
            risk_score += 20
        if code_size > 10_000:
            findings.append({
                "type":     "complexity",
                "severity": "low",
                "message":  "Large codebase increases attack surface",
            })
            risk_score += 5
        overall = "CRITICAL" if risk_score >= 50 else \
                  "HIGH" if risk_score >= 30 else \
                  "MEDIUM" if risk_score >= 15 else "LOW"
        return {
            "protocol":    protocol_name,
            "risk_score":  risk_score,
            "risk_level":  overall,
            "findings":    findings,
            "code_size":   code_size,
            "audited_at":  time.strftime('%Y-%m-%d'),
        }

    def nebula_full_audit(self) -> dict:
        protocols = [
            ("NEBULA Core",     50_000, False, False),
            ("NEBULA DEX",      5_000,  True,  True),
            ("NEBULA Staking",  3_000,  False, False),
            ("NEBULA Lending",  4_000,  True,  True),
            ("NEBULA Bridge",   6_000,  True,  False),
            ("NEBULA Governance", 3_000, False, False),
        ]
        results = [self.audit_protocol(*p) for p in protocols]
        overall = max(r["risk_score"] for r in results)
        return {
            "ecosystem_risk":    overall,
            "protocols_audited": len(results),
            "results":           results,
        }


# ================================================================
# MODULE 435  nebula_nft_provenance.py — NFT Provenance
# ================================================================

class NFTProvenanceTracker:
    """
    Tracks the complete provenance history of NFTs.
    Records every transfer, sale, and transformation.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc     = blockchain
        self._history: Dict[str, List[dict]] = {}
        self._lock   = threading.RLock()

    def record_mint(self, collection_id: str, token_id: int,
                     creator: str):
        with self._lock:
            key = f"{collection_id}:{token_id}"
            self._history[key] = [{
                "event":  "mint",
                "from":   None,
                "to":     creator,
                "price":  0,
                "block":  self._bc.height,
                "ts":     time.time(),
            }]

    def record_transfer(self, collection_id: str, token_id: int,
                          from_addr: str, to_addr: str,
                          price: float = 0):
        with self._lock:
            key = f"{collection_id}:{token_id}"
            if key not in self._history:
                self._history[key] = []
            self._history[key].append({
                "event":  "transfer" if price == 0 else "sale",
                "from":   from_addr,
                "to":     to_addr,
                "price":  price,
                "block":  self._bc.height,
                "ts":     time.time(),
            })

    def get_provenance(self, collection_id: str,
                        token_id: int) -> List[dict]:
        return self._history.get(f"{collection_id}:{token_id}", [])

    def ownership_chain(self, collection_id: str,
                         token_id: int) -> List[str]:
        history  = self.get_provenance(collection_id, token_id)
        owners   = [h["to"] for h in history if h.get("to")]
        return list(dict.fromkeys(owners))

    def provenance_stats(self) -> dict:
        total_events = sum(len(h) for h in self._history.values())
        return {
            "nfts_tracked":   len(self._history),
            "total_events":   total_events,
        }


# ================================================================
# MODULE 436  nebula_liquid_democracy.py — Liquid Democracy
# ================================================================

class LiquidDemocracy:
    """
    Liquid democracy for NEBULA governance.
    Delegate votes to experts, or vote directly.
    """

    def __init__(self, blockchain: 'NEBULABlockchain',
                  governance: 'GovernanceEngine'):
        self._bc         = blockchain
        self._gov        = governance
        self._delegations: Dict[str, str] = {}   # delegator -> delegate
        self._topics:    Dict[str, Dict[str, str]] = {}  # topic -> {delegator: delegate}
        self._lock       = threading.RLock()

    def delegate(self, delegator: str,
                  delegate_to: str,
                  topic: str = "all") -> Tuple[bool, str]:
        with self._lock:
            if delegator == delegate_to:
                return False, "Cannot delegate to self"
            if topic == "all":
                self._delegations[delegator] = delegate_to
            else:
                if topic not in self._topics:
                    self._topics[topic] = {}
                self._topics[topic][delegator] = delegate_to
            return True, f"Delegated to {delegate_to[:8]} for topic '{topic}'"

    def undelegate(self, delegator: str,
                    topic: str = "all") -> bool:
        with self._lock:
            if topic == "all":
                return self._delegations.pop(delegator, None) is not None
            return self._topics.get(topic, {}).pop(delegator, None) is not None

    def resolve_vote(self, voter: str,
                      proposal_id: str) -> str:
        """Resolve who actually votes (may be a delegate)."""
        topic = "governance"
        if voter in self._topics.get(topic, {}):
            return self._topics[topic][voter]
        if voter in self._delegations:
            return self._delegations[voter]
        return voter

    def voting_power(self, address: str) -> dict:
        direct    = self._bc.utxo.balance(address)
        delegated = sum(
            self._bc.utxo.balance(d)
            for d, del_to in self._delegations.items()
            if del_to == address
        )
        return {
            "address":          address,
            "direct_nbl":       f"{direct/10**DECIMALS:.3f}",
            "delegated_nbl":    f"{delegated/10**DECIMALS:.3f}",
            "total_voting_nbl": f"{(direct+delegated)/10**DECIMALS:.3f}",
        }

    def democracy_stats(self) -> dict:
        return {
            "total_delegations":   len(self._delegations),
            "topic_delegations":   sum(len(v) for v in self._topics.values()),
            "active_delegates":    len(set(self._delegations.values())),
        }


# ================================================================
# MODULE 437  nebula_transaction_coalescing.py — TX Coalescing
# ================================================================

class TransactionCoalescer:
    """
    Coalesces multiple small transactions into batches.
    Reduces UTXO fragmentation and lowers fees.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc     = blockchain
        self._queue: Dict[str, List[dict]] = {}
        self._lock   = threading.RLock()

    def queue_transfer(self, sender: str, to: str,
                        amount: int) -> str:
        with self._lock:
            if sender not in self._queue:
                self._queue[sender] = []
            qid = hashlib.sha256(
                f"COAL:{sender}:{to}:{amount}:{time.time()}".encode()
            ).hexdigest()[:8]
            self._queue[sender].append({
                "qid":    qid,
                "to":     to,
                "amount": amount,
            })
            return qid

    def flush_queue(self, sender: str) -> Tuple[int, int]:
        """Flush all queued transfers for sender into one batch."""
        with self._lock:
            transfers = self._queue.pop(sender, [])
        if not transfers:
            return 0, 0
        total     = sum(t["amount"] for t in transfers)
        count     = len(transfers)
        return count, total

    def queue_stats(self) -> dict:
        with self._lock:
            total = sum(len(q) for q in self._queue.values())
        return {
            "senders":   len(self._queue),
            "total_queued": total,
        }


# ================================================================
# MODULE 438  nebula_chain_snapshot.py — Chain Snapshot
# ================================================================

class ChainSnapshotManager:
    """
    Manages chain snapshots for fast node sync and state backups.
    """

    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc         = blockchain
        self._snapshots: Dict[int, dict] = {}
        self._lock       = threading.RLock()

    def take_snapshot(self) -> dict:
        with self._lock:
            h   = self._bc.height
            utxo_data = {}
            for addr in list(self._bc.utxo._addr_idx.keys())[:500]:
                bal = self._bc.utxo.balance(addr)
                if bal > 0:
                    utxo_data[addr] = bal
            snap = {
                "height":    h,
                "utxo_count": self._bc.utxo.size(),
                "supply":    self._bc.utxo.total_supply(),
                "top_utxos": utxo_data,
                "hash":      hashlib.sha256(
                    json.dumps(utxo_data, sort_keys=True).encode()
                ).hexdigest(),
                "ts":        time.time(),
            }
            self._snapshots[h] = snap
            return snap

    def restore_from(self, height: int) -> bool:
        return height in self._snapshots

    def list_snapshots(self) -> List[dict]:
        return [
            {"height": h, "hash": s["hash"][:16], "ts": s["ts"]}
            for h, s in sorted(self._snapshots.items())
        ]

    def snapshot_stats(self) -> dict:
        return {
            "snapshots":   len(self._snapshots),
            "latest":      max(self._snapshots.keys()) if self._snapshots else 0,
        }


