def nebula_weekly_report(blockchain: 'NEBULABlockchain',
                          oracle: 'OracleV2' = None) -> dict:
    """Generate weekly protocol report."""
    h     = blockchain.height
    weeks = h // (144 * 7)
    return {
        "week":         weeks,
        "blocks":       min(144 * 7, h),
        "supply":       f"{blockchain.utxo.total_supply()/10**DECIMALS:.3f}",
        "reward":       f"{mining_reward(h)/10**DECIMALS:.9f}",
        "price":        f"${(oracle.price('NBL/USD') or 0.001):.6f}" if oracle else "N/A",
    }

def nebula_monthly_report(blockchain: 'NEBULABlockchain') -> dict:
    return {
        "month":        time.strftime('%Y-%m'),
        "blocks":       blockchain.height,
        "supply":       f"{blockchain.utxo.total_supply()/10**DECIMALS:.3f}",
        "utxo_count":   blockchain.utxo.size(),
    }

def nebula_yearly_projection(blockchain: 'NEBULABlockchain',
                              years: int = 5) -> List[dict]:
    h   = blockchain.height
    cur_supply = blockchain.utxo.total_supply()
    projections = []
    for yr in range(1, years + 1):
        future_h = h + yr * 365 * 144
        future_r = mining_reward(future_h)
        new_supply = cur_supply + future_r * 365 * 144
        projections.append({
            "year":    yr,
            "height":  future_h,
            "supply":  f"{min(new_supply, MAX_SUPPLY)/10**DECIMALS:.3f}",
            "reward":  f"{future_r/10**DECIMALS:.9f}",
        })
    return projections

def nebula_protocol_kpis(blockchain: 'NEBULABlockchain') -> dict:
    return {
        "chain_id":         CHAIN_ID,
        "height":           blockchain.height,
        "supply_pct":       f"{blockchain.utxo.total_supply()/MAX_SUPPLY*100:.4f}%",
        "utxo_count":       blockchain.utxo.size(),
        "halving_progress": f"{(blockchain.height % HALVING_INTERVAL)/HALVING_INTERVAL*100:.1f}%",
    }

class DailyMetricsCollector:
    """Collects daily on-chain metrics."""
    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc   = blockchain
        self._data: List[dict] = []

    def collect(self) -> dict:
        data = {
            "date":    time.strftime('%Y-%m-%d'),
            "height":  self._bc.height,
            "supply":  self._bc.utxo.total_supply(),
            "mempool": self._bc.mempool.size(),
            "utxos":   self._bc.utxo.size(),
        }
        self._data.append(data)
        return data

    def trend(self, metric: str, days: int = 7) -> Optional[float]:
        if len(self._data) < 2:
            return None
        recent = self._data[-days:]
        if len(recent) < 2:
            return None
        first = recent[0].get(metric, 0)
        last  = recent[-1].get(metric, 0)
        return (last - first) / max(1, first) * 100

class ProtocolKPITracker:
    """Tracks key performance indicators over time."""
    def __init__(self, blockchain: 'NEBULABlockchain'):
        self._bc   = blockchain
        self._kpis: Dict[str, List[float]] = {}

    def record(self, kpi: str, value: float):
        if kpi not in self._kpis:
            self._kpis[kpi] = []
        self._kpis[kpi].append(value)
        if len(self._kpis[kpi]) > 365:
            self._kpis[kpi].pop(0)

    def avg(self, kpi: str) -> Optional[float]:
        vals = self._kpis.get(kpi, [])
        return sum(vals) / len(vals) if vals else None

    def summary(self) -> dict:
        return {k: f"{self.avg(k):.4f}" for k in self._kpis}

