def run_all_nebula_tests() -> dict:
    """Run all NEBULA test suites."""
    results = {}
    print("\n🧪 Running all NEBULA test suites...")
    try:
        results["core"]        = NEBULATestSuite().run_all()
    except Exception as e:
        results["core"]        = {"error": str(e)}
    try:
        results["extended"]    = ExtendedTestSuite().run_all()
    except Exception as e:
        results["extended"]    = {"error": str(e)}
    try:
        results["extended_v2"] = ExtendedTestSuiteV2().run_all()
    except Exception as e:
        results["extended_v2"] = {"error": str(e)}
    try:
        results["final"]       = FinalTestSuite().run_all()
    except Exception as e:
        results["final"]       = {"error": str(e)}
    total_p = sum(r.get("passed", 0) for r in results.values()
                  if isinstance(r, dict))
    total_f = sum(r.get("failed", 0) for r in results.values()
                  if isinstance(r, dict))
    print(f"\n{'═'*60}")
    print(f"  🎯 GRAND TOTAL: {total_p} passed, {total_f} failed")
    print(f"{'═'*60}\n")
    return results

