def nebula_main():
    """Main entry point for the complete NEBULA system."""
    import sys
    args = sys.argv[1:] if len(sys.argv) > 1 else ["info"]
    cmd  = args[0] if args else "info"

    if cmd == "info":
        print_final_celebration()
    elif cmd == "test":
        run_all_nebula_tests()
    elif cmd == "node":
        system = create_full_nebula()
        print(json.dumps(system.status(), indent=2))
    elif cmd == "wallet":
        w = NEBULAWallet.generate()
        print(f"\n🔑 New NEBULA Wallet")
        print(f"   Address:  {w.first_address}")
        print(f"   Mnemonic: {w.mnemonic}")
        print(f"\n⚠️  Save your mnemonic securely!\n")
    elif cmd == "benchmark":
        bc  = NEBULABlockchain()
        bench = ProtocolBenchmark(bc)
        bench.run_all_benchmarks()
    elif cmd == "celebrate":
        print(nebula_100k_celebration())
    else:
        print(f"Commands: info | test | node | wallet | benchmark | celebrate")

