def run_nebula_full_demo():
    """Run a full demonstration of NEBULA capabilities."""
    print(nebula_100k_celebration())
    print("\n📊 Running quick demo...")
    bc = NEBULABlockchain()
    bc._dev_mode = True  # enable fund_address for demo
    bc.fund_address(FOUNDATION_ADDRESS, 10_000_000)
    w  = NEBULAWallet.generate()
    bc.fund_address(w.first_address, 100_000)
    print(f"  Wallet: {w.first_address}")
    print(f"  Balance: {bc.utxo.balance(w.first_address)/10**DECIMALS:.3f} NBL")
    stk = StakingEngine(bc)
    ok, msg = stk.stake(w.first_address, 50_000 * 10**DECIMALS)
    print(f"  Stake: {msg}")
    dex = NEBULADex(bc)
    pid = dex.create_pool("NBL", "USDT", fee_bps=30)
    print(f"  DEX Pool: {pid}")
    nft = NBL721Registry()
    cid = nft.create_collection(w.first_address, "Demo", "DEMO", "Demo", 100, 0.05)
    print(f"  NFT Collection: {cid}")
    print(f"\n✅ NEBULA demo complete!")
    return {"wallet": w.first_address, "pool": pid, "nft": cid}


