# MODULE 704  nebula_node_cli.py — Full Node CLI
# ================================================================
# Command-line interface for the NEBULA full node
# ================================================================

def run_full_node_cli():
    """
    Parse command-line arguments and run NEBULA full node.

    Usage examples:
        # Run a full node (no mining)
        python3 nebula_blockchain_fixed.py node

        # Run with mining enabled
        python3 nebula_blockchain_fixed.py node --mine --addr NbL...

        # Run on testnet
        python3 nebula_blockchain_fixed.py node --network testnet

        # Custom port
        python3 nebula_blockchain_fixed.py node --port 8334

        # 8 mining threads
        python3 nebula_blockchain_fixed.py node --mine --threads 8

        # Connect to specific peers
        python3 nebula_blockchain_fixed.py node --peers 1.2.3.4:8333,5.6.7.8:8333
    """
    import argparse

    parser = argparse.ArgumentParser(
        description="NEBULA Blockchain Full Node v3.0.0",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python3 nebula_blockchain_fixed.py node
  python3 nebula_blockchain_fixed.py node --mine --addr NbLYourAddress
  python3 nebula_blockchain_fixed.py node --network testnet --port 18333
  python3 nebula_blockchain_fixed.py node --mine --threads 8 --verbose
        """
    )
    parser.add_argument("command",         nargs="?", default="node")
    parser.add_argument("--network",       default="mainnet",
                        choices=["mainnet","testnet","regtest"])
    parser.add_argument("--port",          type=int, default=8333)
    parser.add_argument("--api-port",      type=int, default=8080, dest="api_port")
    parser.add_argument("--datadir",       default="~/.nebula")
    parser.add_argument("--mine",          action="store_true")
    parser.add_argument("--addr",          default=FOUNDATION_ADDRESS,
                        help="Mining reward address")
    parser.add_argument("--threads",       type=int, default=None,
                        help="Mining threads (default: CPU count)")
    parser.add_argument("--peers",         default="",
                        help="Comma-separated peer list: host:port,...")
    parser.add_argument("--verbose", "-v", action="store_true")

    # Handle both direct call and sys.argv parsing
    import sys
    args_list = sys.argv[1:]
    if args_list and args_list[0] in ("node", "node-mine"):
        args = parser.parse_args(args_list)
    else:
        args = parser.parse_args([])

    # Adjust port for testnet
    if args.network == "testnet" and args.port == 8333:
        args.port = 18333
    datadir = os.path.join(
        os.path.expanduser(args.datadir), args.network)

    seed_nodes = [p.strip() for p in args.peers.split(",")
                  if p.strip()] if args.peers else []

    node = NEBULAFullNode(
        datadir    = datadir,
        port       = args.port,
        api_port   = args.api_port,
        network    = args.network,
        mine       = args.mine,
        miner_addr = args.addr,
        threads    = args.threads,
        seed_nodes = seed_nodes,
        verbose    = args.verbose,
    )
    node.run()


