# ── Self-test ─────────────────────────────────────────────────────
def _test_blkstore():
    import tempfile
    print("💾 BlockFileStore self-test...")
    with tempfile.TemporaryDirectory() as tmp:
        store = BlockFileStore(tmp)

        # Write 5 fake blocks
        hashes = []
        for i in range(5):
            bdict = {
                'hash'      : f'{"0"*63}{i}',
                'height'    : i,
                'prev_hash' : f'{"0"*63}{max(0,i-1)}',
                'timestamp' : 1742083200 + i * 600,
                'bits'      : 0x1d00ffff,
                'nonce'     : i * 12345,
                'tx_count'  : 1,
            }
            fn, off, ln = store.write_block(bdict)
            hashes.append(bdict['hash'])
            print(f"  Wrote block {i}: file={fn} offset={off} len={ln}")

        # Read back
        for h in hashes:
            b = store.read_block(h)
            assert b is not None, f"Block {h} not found"
            print(f"  Read block height={b['height']} ✅")

        # Integrity check
        chk = store.integrity_check()
        print(f"  Integrity: ok={chk['ok']} bad={chk['bad']}")
        assert chk['bad'] == 0

        # Tip
        store.set_tip(hashes[-1], 4)
        tip_hash, tip_height = store.tip()
        assert tip_height == 4
        print(f"  Tip: height={tip_height} hash={tip_hash[:16]}...")

        info = store.storage_info()
        print(f"  Storage: {info['blocks']} blocks, {info['total_mb']} MB")
        print("  ✅ BlockFileStore OK\n")


# ================================================================
# MODULE 709  nebula_mempool_eviction.py — Mempool Eviction Policy
# ================================================================
#
#  When the mempool is full, low-fee transactions must be evicted
#  to make room for higher-paying ones.
#
#  Policy:
#    • MAX_MEMPOOL_BYTES  = 300 MB  (configurable)
#    • Eviction metric    = fee_rate (sat/vbyte) — lowest evicted first
#    • Descendant package size caps (anti-pinning)
#    • Minimum relay fee  (dynamic floor, rises when pool is full)
#    • Age-based expiry   (default 336 hours = 2 weeks)
#    • RBF (Replace-By-Fee): new tx may replace lower-fee tx if fee
#      is > old_fee + MIN_RELAY_FEE * size
#
# ================================================================

import time   as _time2
import heapq  as _hq
from dataclasses import dataclass as _dc, field as _fld
from typing import Dict as _D2, List as _L2, Optional as _O2, Set as _S2

