MAX_MEMPOOL_ANCESTORS   = 25
MAX_MEMPOOL_DESCENDANTS = 25
MAX_ANCESTOR_SIZE       = 101_000             # bytes
DEFAULT_EXPIRY_HOURS    = 336                 # 2 weeks (Bitcoin default)
MIN_RELAY_FEE_SAT_VBYTE = 1                   # 1 sat/vbyte floor
EVICTION_CHUNK          = 10                  # evict N txs at a time

