# ================================================================
# MODULE 710  nebula_bip9.py — BIP9 Soft Fork Version Bits
# ================================================================
#
#  BIP9 allows multiple soft forks to be deployed simultaneously
#  using version bits in the block header's nVersion field.
#
#  State machine per deployment, per period:
#    DEFINED  → STARTED  (at startheight)
#    STARTED  → LOCKED_IN (if threshold% of blocks signal in window)
#    STARTED  → FAILED    (if timeout reached without lock-in)
#    LOCKED_IN → ACTIVE   (after one more retarget period)
#    ACTIVE   → ACTIVE    (forever)
#
#  Block nVersion:
#    Bits 0-28: deployment bits (1 = signaling)
#    Bits 29-31: must be 0b001
#
# ================================================================

from enum      import Enum   as _Enum2
from dataclasses import dataclass as _dc2, field as _fld2
from typing    import Dict as _D3, List as _L3, Optional as _O3

# ── BIP9 state ────────────────────────────────────────────────────
class Bip9State(_Enum2):
    DEFINED   = "DEFINED"
    STARTED   = "STARTED"
    LOCKED_IN = "LOCKED_IN"
    ACTIVE    = "ACTIVE"
    FAILED    = "FAILED"

# ── Deployment definition ─────────────────────────────────────────
@_dc2
class Bip9Deployment:
    name         : str
    bit          : int          # 0–28
    start_time   : int          # Unix timestamp (or START_ALWAYS = -1)
    timeout      : int          # Unix timestamp (or NEVER_EXPIRE = 0x7fffffff)
    threshold_pct: float = 95.0 # % of blocks in window that must signal
    min_activation_height: int = 0

    START_ALWAYS  = -1
    NEVER_EXPIRE  = 0x7fffffff

    @property
    def mask(self) -> int:
        return 1 << self.bit


# ── NEBULA built-in deployments ───────────────────────────────────
NEBULA_DEPLOYMENTS = [
    Bip9Deployment("segwit",    bit=1,
                   start_time=1742083200, timeout=0x7fffffff,
                   threshold_pct=95.0),
    Bip9Deployment("taproot",   bit=2,
                   start_time=1742083200, timeout=0x7fffffff,
                   threshold_pct=90.0,   min_activation_height=10),
    Bip9Deployment("csv",       bit=0,
                   start_time=Bip9Deployment.START_ALWAYS,
                   timeout=Bip9Deployment.NEVER_EXPIRE,
                   threshold_pct=95.0),
    Bip9Deployment("nebula_v2", bit=3,
                   start_time=1800000000, timeout=0x7fffffff,
                   threshold_pct=80.0),
]

# ── Per-period cache entry ────────────────────────────────────────
# [v10.19] dead class Bip9PeriodCache removed from host - live copy is wired by group 62 (nebula_group62.py)


# ── Version Bits State Machine ────────────────────────────────────
class VersionBitsStateMachineLegacy:
    """[v10.17] OLD implementation kept ONLY for old stand-alone callers (their API differs from the live VersionBitsStateMachine)."""
    """
    Tracks BIP9 deployment states across retarget periods.

    Usage:
        vsm = VersionBitsStateMachine()
        # For each new block:
        vsm.process_block(height, nversion, median_time_past)
        # Query state:
        state = vsm.get_state("taproot")
        # Check if block should signal:
        should = vsm.should_signal("taproot", height, median_time_past)
    """

    RETARGET_PERIOD = DIFFICULTY_WINDOW  # 2016 blocks (reuse existing constant)
    NVERSION_TOP_BITS = 0x20000000       # top 3 bits must be 001

    def __init__(self, deployments: list = None):
        self._deps    = {d.name: d for d in (deployments or NEBULA_DEPLOYMENTS)}
        # state[name][period] = Bip9State
        self._state   : _D3[str, _D3[int, Bip9State]] = {
            n: {} for n in self._deps
        }
        # signal_count[name][period] = int
        self._signals : _D3[str, _D3[int, int]] = {
            n: {} for n in self._deps
        }

    def process_block(self, height: int, nversion: int,
                       median_time_past: int):
        """
        Process one block. Call for every block in order.
        """
        period = height // self.RETARGET_PERIOD

        for name, dep in self._deps.items():
            # Init period if needed
            if period not in self._signals[name]:
                self._signals[name][period] = 0
            if period not in self._state[name]:
                prev_state = self._state[name].get(period - 1, Bip9State.DEFINED)
                self._state[name][period] = self._transition(
                    dep, prev_state, period, median_time_past
                )

            cur_state = self._state[name][period]

            # Count signals only in STARTED state
            if cur_state == Bip9State.STARTED:
                if (nversion & self.NVERSION_TOP_BITS == self.NVERSION_TOP_BITS
                        and (nversion & dep.mask)):
                    self._signals[name][period] += 1

        # At end of period, finalize states
        if (height + 1) % self.RETARGET_PERIOD == 0:
            self._finalize_period(period, median_time_past)

    def _transition(self, dep: Bip9Deployment, prev: Bip9State,
                     period: int, mtp: int) -> Bip9State:
        """Calculate state for a new period given previous period state."""
        if prev in (Bip9State.ACTIVE, Bip9State.FAILED):
            return prev
        if prev == Bip9State.LOCKED_IN:
            height = period * self.RETARGET_PERIOD
            if height >= dep.min_activation_height:
                return Bip9State.ACTIVE
            return Bip9State.LOCKED_IN
        if prev == Bip9State.DEFINED:
            if dep.start_time == Bip9Deployment.START_ALWAYS:
                return Bip9State.STARTED
            if mtp >= dep.start_time:
                return Bip9State.STARTED
            return Bip9State.DEFINED
        if prev == Bip9State.STARTED:
            if mtp >= dep.timeout:
                return Bip9State.FAILED
            return Bip9State.STARTED
        return prev

    def _finalize_period(self, period: int, mtp: int):
        """At retarget boundary: check thresholds and advance states."""
        for name, dep in self._deps.items():
            cur = self._state[name].get(period, Bip9State.DEFINED)
            if cur != Bip9State.STARTED:
                continue
            count   = self._signals[name].get(period, 0)
            needed  = int(dep.threshold_pct / 100 * self.RETARGET_PERIOD)
            if count >= needed:
                self._state[name][period + 1] = Bip9State.LOCKED_IN
            elif mtp >= dep.timeout:
                self._state[name][period + 1] = Bip9State.FAILED
            else:
                self._state[name][period + 1] = Bip9State.STARTED

    def get_state(self, name: str, height: int = None) -> Bip9State:
        """Get current state of a deployment."""
        if name not in self._state:
            return Bip9State.DEFINED
        if not self._state[name]:
            return Bip9State.DEFINED
        if height is not None:
            period = height // self.RETARGET_PERIOD
            return self._state[name].get(period, Bip9State.DEFINED)
        period = max(self._state[name].keys(), default=0)
        return self._state[name].get(period, Bip9State.DEFINED)

    def is_active(self, name: str, height: int = None) -> bool:
        return self.get_state(name, height) == Bip9State.ACTIVE

    def should_signal(self, name: str, height: int,
                       median_time_past: int) -> bool:
        """Should a miner signal this deployment in the given block?"""
        dep = self._deps.get(name)
        if dep is None:
            return False
        state = self.get_state(name, height)
        if state != Bip9State.STARTED:
            return False
        if (dep.start_time != Bip9Deployment.START_ALWAYS
                and median_time_past < dep.start_time):
            return False
        if median_time_past >= dep.timeout:
            return False
        return True

    def compute_nversion(self, height: int, mtp: int,
                          extra_bits: int = 0) -> int:
        """
        Compute the nVersion value a miner should use for a block.
        Sets bits for all STARTED deployments + BIP9 top bits.
        """
        nv = self.NVERSION_TOP_BITS | extra_bits
        for name in self._deps:
            if self.should_signal(name, height, mtp):
                nv |= self._deps[name].mask
        return nv

    def all_states(self, height: int = None) -> dict:
        """Return dict of {name: state_str} for all deployments."""
        return {n: self.get_state(n, height).value for n in self._deps}

    def statistics(self, period: int) -> dict:
        """Signaling statistics for a given period."""
        result = {}
        for name, dep in self._deps.items():
            count  = self._signals[name].get(period, 0)
            needed = int(dep.threshold_pct / 100 * self.RETARGET_PERIOD)
            result[name] = {
                'state'   : self.get_state(name).value,
                'signals' : count,
                'needed'  : needed,
                'pct'     : round(100 * count / max(self.RETARGET_PERIOD, 1), 1),
                'bit'     : dep.bit,
            }
        return result


# ── Singleton for NEBULABlockchain ────────────────────────────────
_version_bits = VersionBitsStateMachineLegacy()

def get_version_bits() -> VersionBitsStateMachine:
    return _version_bits


