# ── Self-test ─────────────────────────────────────────────────────
def _test_ban_manager():
    print("🚫 Ban Manager self-test...")
    bm = BanManager(ban_duration_hours=1)
    bm.whitelist("127.0.0.1")

    # Whitelist check
    ok, reason = bm.peer_connected("127.0.0.1")
    assert ok, "Localhost should be whitelisted"
    print(f"  Localhost: {reason}")

    # Gradual misbehavior
    ip = "192.168.1.100"
    for _ in range(5):
        banned = bm.misbehaving(ip, Misbehavior.INVALID_TX)
    score = bm.get_score(ip)
    print(f"  Score after 5x INVALID_TX: {score}")
    assert score == 50

    # Instant ban on INVALID_BLOCK
    banned = bm.misbehaving(ip, Misbehavior.INVALID_BLOCK)
    assert bm.is_banned(ip), "Should be banned after INVALID_BLOCK"
    print(f"  Banned after INVALID_BLOCK: ✅")

    # Connection refused
    ok, reason = bm.peer_connected(ip)
    assert not ok
    print(f"  Connection refused: {reason}")

    # Wrong network = instant ban
    ip2 = "10.0.0.1"
    bm.misbehaving(ip2, Misbehavior.WRONG_NETWORK)
    assert bm.is_banned(ip2)
    print(f"  WRONG_NETWORK instant ban: ✅")

    # Unban
    bm.unban(ip)
    assert not bm.is_banned(ip)
    print(f"  Unban: ✅")

    print(f"  Stats: {bm.stats()}")
    print("  ✅ Ban Manager OK\n")


# ================================================================
# MODULE 712  nebula_bip21.py — BIP21 Payment URI + QR Code
# ================================================================
#
#  BIP21 Payment URI format:
#    nebula:<address>[?amount=<amount>][&label=<label>]
#                    [&message=<msg>][&memo=<memo>]
#                    [&req-<key>=<value>]
#
#  QR Code: pure-Python QR generation using the qr library pattern.
#  Outputs:
# URI string
# ASCII QR code (terminal-printable)
# SVG QR code (embeddable in HTML)
# Dict representation
#
# ================================================================

import re      as _re
import math    as _math3
from urllib.parse import urlencode as _urlencode, quote as _quote, unquote as _unquote, parse_qs as _pqs
from typing  import Optional as _O5, Dict as _D5

# ── BIP21 URI Builder ─────────────────────────────────────────────
class Bip21URI:
    """
    Build and parse BIP21 payment URIs for NEBULA (NBL).

    Examples:
        uri = Bip21URI("NdoZxCWQfYDy4412S1Zqh8AWj9T5aKqmkx",
                        amount=0.001, label="Alice", message="Coffee")
        print(uri)
        # nebula:NdoZxCWQfYDy4412S1Zqh8AWj9T5aKqmkx?amount=0.001&label=Alice&message=Coffee
    """

    SCHEME = "nebula"

    def __init__(self, address: str,
                  amount: float = None,
                  label: str = None,
                  message: str = None,
                  memo: str = None,
                  extras: dict = None):
        self.address = address
        self.amount  = amount     # in NBL (float)
        self.label   = label
        self.message = message
        self.memo    = memo
        self.extras  = extras or {}

    def __str__(self) -> str:
        return self.to_uri()

    def to_uri(self) -> str:
        """Encode as BIP21 URI string."""
        params = {}
        if self.amount is not None:
            # Format without trailing zeros, max 9 decimal places
            params['amount'] = f"{self.amount:.9f}".rstrip('0').rstrip('.')
        if self.label:
            params['label'] = self.label
        if self.message:
            params['message'] = self.message
        if self.memo:
            params['memo'] = self.memo
        for k, v in self.extras.items():
            params[k] = str(v)

        uri = f"{self.SCHEME}:{self.address}"
        if params:
            query = '&'.join(
                f"{_quote(str(k), safe='')}={_quote(str(v), safe='')}"
                for k, v in params.items()
            )
            uri += '?' + query
        return uri

    def to_dict(self) -> dict:
        """Return as plain dict."""
        return {
            'address' : self.address,
            'amount'  : self.amount,
            'label'   : self.label,
            'message' : self.message,
            'memo'    : self.memo,
            'extras'  : self.extras,
            'uri'     : self.to_uri(),
        }

    def amount_in_neb(self) -> int:
        """Return amount in smallest units (Neb = 10^-9 NBL)."""
        if self.amount is None:
            return 0
        return int(round(self.amount * (10 ** DECIMALS)))

    @classmethod
    def parse(cls, uri: str) -> 'Bip21URI':
        """Parse a BIP21 URI string."""
        scheme = cls.SCHEME + ':'
        if not uri.startswith(scheme):
            raise ValueError(f"Not a NEBULA URI (expected '{scheme}')")
        rest = uri[len(scheme):]
        if '?' in rest:
            address, query = rest.split('?', 1)
        else:
            address, query = rest, ''

        params = {}
        if query:
            for part in query.split('&'):
                if '=' in part:
                    k, v = part.split('=', 1)
                    params[_unquote(k)] = _unquote(v)

        amount  = float(params.pop('amount',  0)) if 'amount'  in params else None
        label   = params.pop('label',   None)
        message = params.pop('message', None)
        memo    = params.pop('memo',    None)
        return cls(address, amount=amount, label=label,
                   message=message, memo=memo, extras=params)

    @classmethod
    def validate(cls, uri: str) -> tuple:
        """Validate a URI. Returns (valid: bool, error: str)."""
        try:
            parsed = cls.parse(uri)
            if not parsed.address:
                return False, "Missing address"
            if len(parsed.address) < 26 or len(parsed.address) > 62:
                return False, f"Address length invalid: {len(parsed.address)}"
            if parsed.amount is not None and parsed.amount < 0:
                return False, "Negative amount"
            return True, "ok"
        except Exception as e:
            return False, str(e)


# ── Pure-Python QR Code (Reed-Solomon + Module Placement) ────────
# Implements QR Code version 1-10, Error Correction Level M.
# This is a simplified but working implementation.

class _QRCode:
    """
    Pure-Python QR code generator.
    Supports alphanumeric + byte mode, EC level M.
    """

    # QR alphanumeric charset
    _ALNUM = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:'

    # Version 1-10 capacities (byte mode, EC level M)
    _CAPACITIES = [
        0, 14, 26, 42, 62, 84, 106, 122, 154, 180, 206
    ]

    # Reed-Solomon ECC codewords per block, version 1-10, level M
    _ECC_PER_BLOCK = [0,10,16,26,18,24,16,18,22,22,26]
    _BLOCKS        = [0, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5]

    def __init__(self, data: str):
        self._data    = data
        self._version = self._pick_version(data)
        self._size    = 4 * self._version + 17
        self._modules : list = []
        self._func    : list = []  # function pattern mask
        self._build()

    def _pick_version(self, data: str) -> int:
        n = len(data.encode('utf-8'))
        for v, cap in enumerate(self._CAPACITIES):
            if v > 0 and n <= cap:
                return v
        return 10  # max supported

    def _build(self):
        sz = self._size
        self._modules = [[False]*sz for _ in range(sz)]
        self._func    = [[False]*sz for _ in range(sz)]
        self._place_finders()
        self._place_timing()
        self._place_dark()
        self._encode_data()
        self._apply_mask()

    def _set(self, r, c, v, func=False):
        if 0 <= r < self._size and 0 <= c < self._size:
            self._modules[r][c] = v
            if func:
                self._func[r][c] = True

    def _place_finder(self, r, c):
        for dr in range(-1, 8):
            for dc in range(-1, 8):
                val = (0 <= dr <= 6 and 0 <= dc <= 6 and
                       (dr in (0,6) or dc in (0,6) or
                        (2 <= dr <= 4 and 2 <= dc <= 4)))
                self._set(r+dr, c+dc, val, func=True)

    def _place_finders(self):
        sz = self._size
        self._place_finder(0, 0)
        self._place_finder(0, sz-7)
        self._place_finder(sz-7, 0)

    def _place_timing(self):
        sz = self._size
        for i in range(8, sz-8):
            v = (i % 2 == 0)
            self._set(6, i, v, func=True)
            self._set(i, 6, v, func=True)

    def _place_dark(self):
        self._set(4*self._version+9, 8, True, func=True)

    def _encode_data(self):
        """Place data bits using byte mode."""
        data_bytes = self._data.encode('utf-8')
        # Build bit stream
        bits = []
        # Mode indicator: byte = 0100
        bits += [0,1,0,0]
        # Character count (8 bits for version 1-9)
        n = len(data_bytes)
        for i in range(7,-1,-1):
            bits.append((n >> i) & 1)
        # Data
        for byte in data_bytes:
            for i in range(7,-1,-1):
                bits.append((byte >> i) & 1)
        # Terminator
        bits += [0,0,0,0]
        # Pad to byte boundary
        while len(bits) % 8:
            bits.append(0)
        # Pad codewords
        pad_bytes = [0xEC, 0x11]
        max_bits = self._CAPACITIES[self._version] * 8
        pi = 0
        while len(bits) < max_bits:
            bits += [(pad_bytes[pi%2] >> i) & 1 for i in range(7,-1,-1)]
            pi += 1

        # Place bits in zigzag order
        bit_idx = 0
        sz = self._size
        col = sz - 1
        going_up = True
        while col >= 0:
            if col == 6:
                col -= 1
                continue
            for row_offset in range(sz):
                row = (sz-1-row_offset) if going_up else row_offset
                for c_offset in [0, -1]:
                    c = col + c_offset
                    if not self._func[row][c] and bit_idx < len(bits):
                        self._modules[row][c] = bool(bits[bit_idx])
                        bit_idx += 1
            going_up = not going_up
            col -= 2

    def _apply_mask(self):
        """Apply mask pattern 0: (row+col) % 2 == 0"""
        sz = self._size
        for r in range(sz):
            for c in range(sz):
                if not self._func[r][c]:
                    if (r + c) % 2 == 0:
                        self._modules[r][c] = not self._modules[r][c]

    def to_matrix(self) -> list:
        """Return list of lists of bool (True=dark)."""
        return [row[:] for row in self._modules]

    def to_ascii(self, border: int = 2) -> str:
        """Render as ASCII art using Unicode block chars."""
        matrix = self.to_matrix()
        sz = len(matrix)
        lines = []
        pad = '  ' * border
        top_bot = pad + '  ' * (sz + border * 2)
        for _ in range(border):
            lines.append(top_bot)
        for row in matrix:
            line = pad
            for cell in row:
                line += '██' if cell else '  '
            line += pad
            lines.append(line)
        for _ in range(border):
            lines.append(top_bot)
        return '\n'.join(lines)

    def to_svg(self, module_size: int = 6, border: int = 4) -> str:
        """Render as SVG string."""
        matrix = self.to_matrix()
        sz     = len(matrix)
        dim    = (sz + border * 2) * module_size
        rects  = []
        for r, row in enumerate(matrix):
            for c, cell in enumerate(row):
                if cell:
                    x = (c + border) * module_size
                    y = (r + border) * module_size
                    rects.append(
                        f'<rect x="{x}" y="{y}" '
                        f'width="{module_size}" height="{module_size}" fill="#000"/>'
                    )
        return (
            f'<svg xmlns="http://www.w3.org/2000/svg" '
            f'width="{dim}" height="{dim}" viewBox="0 0 {dim} {dim}">'
            f'<rect width="{dim}" height="{dim}" fill="#fff"/>'
            + ''.join(rects) +
            '</svg>'
        )

    def to_html(self, title: str = '') -> str:
        """Return standalone HTML page with embedded QR."""
        svg = self.to_svg(module_size=8)
        return (
            f'<!DOCTYPE html><html><head><meta charset="utf-8">'
            f'<title>{title or "NEBULA QR"}</title></head>'
            f'<body style="font-family:monospace;text-align:center;padding:2em">'
            f'<h2>{title}</h2>{svg}'
            f'<p style="font-size:0.8em;color:#666">{self._data}</p>'
            f'</body></html>'
        )


# ── Public API ────────────────────────────────────────────────────
def make_payment_uri(address: str,
                      amount_nbl: float = None,
                      label: str = None,
                      message: str = None) -> Bip21URI:
    """Create a BIP21 payment URI."""
    return Bip21URI(address, amount=amount_nbl,
                    label=label, message=message)

def make_qr(uri_or_text: str) -> _QRCode:
    """Generate a QR code object for any text or URI."""
    return _QRCode(str(uri_or_text))

def payment_qr_ascii(address: str,
                      amount_nbl: float = None,
                      label: str = None) -> str:
    """One-liner: return ASCII QR for a payment URI."""
    uri = make_payment_uri(address, amount_nbl, label)
    return make_qr(str(uri)).to_ascii()

def payment_qr_svg(address: str,
                    amount_nbl: float = None,
                    label: str = None) -> str:
    """One-liner: return SVG QR for a payment URI."""
    uri = make_payment_uri(address, amount_nbl, label)
    return make_qr(str(uri)).to_svg()


# ── Self-test ─────────────────────────────────────────────────────
def _test_bip21():
    print("📱 BIP21 + QR self-test...")

    addr = FOUNDATION_ADDRESS
    uri  = Bip21URI(addr, amount=0.001, label="NEBULA Foundation",
                    message="Test payment")
    print(f"  URI: {uri}")

    # Parse round-trip
    parsed = Bip21URI.parse(str(uri))
    assert parsed.address == addr
    assert abs(parsed.amount - 0.001) < 1e-9
    assert parsed.label == "NEBULA Foundation"
    print(f"  Parse OK: amount={parsed.amount} label={parsed.label}")

    # Validation
    ok, err = Bip21URI.validate(str(uri))
    assert ok, f"Validation failed: {err}"
    print(f"  Validate: {err}")

    # Neb conversion
    neb = uri.amount_in_neb()
    print(f"  In Neb: {neb} (= 0.001 NBL)")
    assert neb == 1_000_000

    # QR code
    qr = make_qr(str(uri))
    svg = qr.to_svg()
    asc = qr.to_ascii()
    assert '<svg' in svg
    assert '██' in asc or len(asc) > 10
    print(f"  QR version={qr._version} size={qr._size}x{qr._size}")
    print(f"  SVG: {len(svg)} chars")
    print(f"  ASCII preview (first line): {asc.split(chr(10))[3][:30]}...")
    print("  ✅ BIP21 + QR OK\n")


