def _test_testnet():
    print("🌐 Testnet Config self-test...")
    for net_name in ['mainnet', 'testnet3', 'regtest', 'signet']:
        cfg = NetworkConfig(net_name)
        s   = cfg.summary()
        print(f"  {net_name:10s} port={s['port']:5d} "
              f"magic={s['magic']} "
              f"addr={s['addr_version']} "
              f"pow={'OFF' if s['no_pow'] else 'ON'}")

    # Faucet test
    faucet = TestnetFaucet(network='regtest')
    result = faucet.request(FOUNDATION_ADDRESS, 1000)
    assert result['success'], f"Faucet failed: {result}"
    print(f"  Faucet: gave {result['amount_nbl']} NBL to {result['address'][:20]}...")

    # Genesis block dicts
    for name, net in ALL_NETWORKS.items():
        cfg = NetworkConfig(name)
        gb  = cfg.genesis_block_dict()
        assert gb['height'] == 0
        assert gb['network'] == name

    print("  ✅ Testnet Config OK\n")


