def _test_silent_payments():
    print("🔇 Silent Payments (BIP352) self-test...")

    # 1. Receiver key generation
    recv = SilentPaymentReceiver()
    assert recv.B_scan is not None
    assert recv.B_spend is not None
    print(f"  scan pubkey  : {recv.scan_pubkey_hex[:20]}...")
    print(f"  spend pubkey : {recv.spend_pubkey_hex[:20]}...")

    # 2. Address generation
    addr = recv.address(network='mainnet')
    assert addr.startswith('sp1')
    print(f"  SP address   : {addr[:30]}...")

    # 3. Sender creates output
    curve  = Secp256k1
    G      = (curve.Gx, curve.Gy)
    a_priv = int.from_bytes(secrets.token_bytes(32), 'big') % curve.N
    outpoint = ('a' * 64, 0)
    out    = SilentPaymentSender.create_output(
        receiver_scan_pubkey_hex  = recv.scan_pubkey_hex,
        receiver_spend_pubkey_hex = recv.spend_pubkey_hex,
        sender_input_privkeys     = [a_priv],
        sender_outpoints          = [outpoint],
        k                         = 0,
    )
    assert 'output_pubkey_hex' in out
    assert len(out['output_pubkey_hex']) == 64   # 32 bytes x-only
    assert out['p2tr_script'][0] == 0x51         # OP_1
    print(f"  sender output: {out['output_pubkey_hex'][:20]}...")
    print(f"  P2TR script  : {out['p2tr_script_hex'][:20]}...")

    # 4. Receiver scans and finds the output
    sender_pub = _sp_compress(curve.point_mul(a_priv, G))
    found = recv.scan(
        tx_input_pubkeys = [sender_pub],
        tx_outpoints     = [outpoint],
        outputs          = [out['output_pubkey_hex']],
    )
    assert len(found) == 1, f"Expected 1 found, got {len(found)}"
    idx, privkey = found[0]
    assert idx == 0
    # Verify privkey produces correct pubkey
    P_derived = curve.point_mul(privkey, G)
    x_only    = P_derived[0].to_bytes(32, 'big').hex()
    assert x_only == out['output_pubkey_hex'], "Derived pubkey mismatch"
    print(f"  receiver found output at index {idx} ✅")

    # 5. Full wallet round-trip
    wallet = SilentPaymentWallet(label='test')
    sp_addr = wallet.address
    assert sp_addr.startswith('sp1')
    # Simulate send
    a2     = int.from_bytes(secrets.token_bytes(32), 'big') % curve.N
    outp2  = ('b' * 64, 1)
    result = wallet.send(
        receiver_address = recv.address(),
        sender_privkeys  = [a2],
        sender_outpoints = [outp2],
    )
    assert 'p2tr_script' in result
    print(f"  wallet.send  : {result['p2tr_address'][:30]}...")

    # 6. Multiple outputs (k=0,1)
    outs = []
    for k in range(3):
        o = SilentPaymentSender.create_output(
            receiver_scan_pubkey_hex  = recv.scan_pubkey_hex,
            receiver_spend_pubkey_hex = recv.spend_pubkey_hex,
            sender_input_privkeys     = [a_priv],
            sender_outpoints          = [outpoint],
            k                         = k,
        )
        outs.append(o['output_pubkey_hex'])
    # All outputs should be distinct
    assert len(set(outs)) == 3, "Duplicate outputs for different k values"
    print(f"  multiple outputs (k=0,1,2): all distinct ✅")

    print("  ✅ Silent Payments (BIP352) OK\n")


