class PurposeAccount:
    """BIP44/49/84/86-style account used by MultiAccountWallet."""
    def __init__(self, index, purpose, master_key):
        self.index = index
        self.purpose = purpose
        self.master_key = master_key
        self._ext = 0
        self._int = 0
        self._node = master_key.derive_path(f"m/{purpose}'/2025'/{index}'")
        self.addresses = {}

    def get_receive_address(self):
        node = self._node.derive_child(0).derive_child(self._ext)
        self._ext += 1
        self.addresses[node.address] = node
        return node.address

    def get_change_address(self):
        node = self._node.derive_child(1).derive_child(self._int)
        self._int += 1
        self.addresses[node.address] = node
        return node.address

    receive_address = get_receive_address
    change_address = get_change_address


def _v108_sign_p2pkh(tx, selected_utxos, keys):
    """Sign every input of `tx` (P2PKH) using the key whose hash160 matches the
    spent output. `keys` = iterable of objects with .key (int) and .pubkey (point)."""
    by_h160 = {hash160(Secp256k1.pubkey_to_bytes(k.pubkey)): k for k in keys}
    for i, u in enumerate(selected_utxos):
        k = by_h160.get(u.script_pubkey[3:23])
        if k is None:
            return False
        sighash = tx.signature_hash(i, u.script_pubkey, SIGHASH_ALL)
        r, s_ = Secp256k1.sign(k.key, sighash)
        der = Secp256k1.sig_to_der(r, s_) + bytes([SIGHASH_ALL])
        tx.inputs[i].script_sig = Script.p2pkh_unlocking(der, Secp256k1.pubkey_to_bytes(k.pubkey))
        tx.invalidate_cache()
    return True


# ================================================================
#  v10.9  ON-CHAIN STATE LAYER
#  Tokens (NBL-20) · NFT (NBL-721) · DEX (AMM) · Governance · Staking
# ================================================================
#  HOW IT IS CONNECTED TO THE CHAIN
#  --------------------------------
#  Every action is a normal, signed NBL transaction that carries ONE
#  OP_RETURN output (<= 80 bytes):  b'NB' + opcode + packed fields.
#  The sender is the address of the FIRST input's public key (proved by the
#  signature that consensus already verified).  Miners/nodes do nothing
#  special: blocks stay valid or invalid exactly as before (this layer never
#  changes block validity, like Omni/Counterparty on Bitcoin).  Each node
#  derives the SAME state by replaying confirmed blocks.
#    * connect  : NEBULABlockchain.add_block  -> layer.on_connect(block)
#    * reorg    : NEBULABlockchain._execute_reorg -> layer.on_reorg(...)
#    * restart  : layer.attach() replays the saved chain
#  The state is a pure function of the chain (integers only, no clocks, no
#  random, no UTXO-set reads), so two honest nodes always get the same
#  `state_hash()` for the same tip.
#  An invalid action (bad balance, wrong owner...) is simply ignored; the
#  transaction still pays its fee and the block stays valid.
#
#  Honest limits: staked tokens are *layer tokens* (not native NBL);
#  governance is signalling only (it does not change chain parameters);
#  there is no slashing.  Native NBL is never moved or created by this layer.
# ================================================================
import copy as _v109_copy
import copyreg as _v109_copyreg
from math import isqrt as _v109_isqrt

# allow copy.deepcopy() of objects that own a lock (the revived NBL-20 / NBL-721
# classes do); the copy simply gets a fresh, unlocked lock
_v109_copyreg.pickle(type(threading.Lock()), lambda _l: (threading.Lock, ()))
_v109_copyreg.pickle(type(threading.RLock()), lambda _l: (threading.RLock, ()))

SL_MAGIC             = b'NB'
SL_MAX_AMOUNT        = 2 ** 63 - 1
SL_MIN_LIQUIDITY     = 1000            # LP units locked forever in every pool
SL_SNAPSHOT_KEEP     = 160             # > NEBULABlockchain.MAX_FORK_DEPTH
SL_EVENT_KEEP        = 500
SL_BLOCKS_PER_YEAR   = 365 * 24 * 3600 // TARGET_BLOCK_TIME
SL_STAKE_REWARD_PCT  = 5               # yearly, paid ONLY from the funded reward pool
SL_MAX_DELEGATORS    = 1000
SL_GOV_VOTING_PERIOD = 2016
SL_GOV_QUORUM_BP     = 1000            # 10% of snapshot weight must vote
SL_GOV_PASS_PCT      = 67              # yes / (yes+no) in percent
SL_GOV_PROPOSE_MIN_BP = 100            # proposer needs 1% of the token supply
SL_STAKE_EPOCH       = 100
SL_UNBONDING         = 50_400


class SLOp:
    TOKEN_CREATE = 0x01; TOKEN_TRANSFER = 0x02; TOKEN_MINT = 0x03
    TOKEN_BURN = 0x04; TOKEN_APPROVE = 0x05; TOKEN_TRANSFER_FROM = 0x06
    NFT_COLLECTION = 0x10; NFT_MINT = 0x11; NFT_TRANSFER = 0x12
    DEX_CREATE = 0x20; DEX_ADD = 0x21; DEX_REMOVE = 0x22; DEX_SWAP = 0x23
    GOV_PROPOSE = 0x30; GOV_VOTE = 0x31
    STAKE_REGISTER = 0x40; STAKE_DELEGATE = 0x41; STAKE_UNDELEGATE = 0x42
    STAKE_CLAIM = 0x43; STAKE_FUND = 0x44

_SL_FORMATS = {
    SLOp.TOKEN_CREATE: '>8sBQ',        SLOp.TOKEN_TRANSFER: '>I20sQ',
    SLOp.TOKEN_MINT: '>I20sQ',         SLOp.TOKEN_BURN: '>IQ',
    SLOp.TOKEN_APPROVE: '>I20sQ',      SLOp.TOKEN_TRANSFER_FROM: '>I20s20sQ',
    SLOp.NFT_COLLECTION: '>8s',        SLOp.NFT_MINT: '>I20s32s',
    SLOp.NFT_TRANSFER: '>IQ20s',
    SLOp.DEX_CREATE: '>IIQQ',          SLOp.DEX_ADD: '>IQQQ',
    SLOp.DEX_REMOVE: '>IQQQ',          SLOp.DEX_SWAP: '>IBQQ',
    SLOp.GOV_PROPOSE: '>I16sQ32s',     SLOp.GOV_VOTE: '>IB',
    SLOp.STAKE_REGISTER: '>IBQ16s',    SLOp.STAKE_DELEGATE: '>I20sQ',
    SLOp.STAKE_UNDELEGATE: '>I20sQ',   SLOp.STAKE_CLAIM: '>I',
    SLOp.STAKE_FUND: '>IQ',
}
_SL_NAMES = {v: k for k, v in vars(SLOp).items() if not k.startswith('_')}


def _sl_to_h160(address: str) -> bytes:
    ver, payload = base58check_decode(address)
    if ver != PUBKEY_ADDRESS_VERSION or len(payload) != 20:
        raise ValueError("not a NBL P2PKH address")
    return payload


def _sl_to_addr(h160: bytes) -> str:
    return base58check_encode(bytes(h160), PUBKEY_ADDRESS_VERSION)


def _sl_text(raw: bytes, max_len: int, upper_alnum: bool = False) -> Optional[str]:
    s = raw.rstrip(b'\x00')
    if not s or len(s) > max_len:
        return None
    try:
        t = s.decode('ascii')
    except UnicodeDecodeError:
        return None
    if upper_alnum:
        if not all(c.isdigit() or ('A' <= c <= 'Z') for c in t):
            return None
    elif not all(32 <= ord(c) < 127 for c in t):
        return None
    return t


class StateActions:
    """Builders for the OP_RETURN payloads (<= 80 bytes)."""

    @staticmethod
    def _pack(op: int, *fields) -> bytes:
        data = SL_MAGIC + bytes([op]) + struct.pack(_SL_FORMATS[op], *fields)
        if len(data) > 80:
            raise ValueError("payload too large")
        return data

    @staticmethod
    def _t(s: str, n: int) -> bytes:
        b = s.encode('ascii')
        if not (0 < len(b) <= n):
            raise ValueError(f"text must be 1..{n} ascii chars")
        return b.ljust(n, b'\x00')

    @classmethod
    def token_create(cls, symbol, decimals, supply):
        return cls._pack(SLOp.TOKEN_CREATE, cls._t(symbol.upper(), 8), decimals, supply)
    @classmethod
    def token_transfer(cls, tid, to, amount):
        return cls._pack(SLOp.TOKEN_TRANSFER, tid, _sl_to_h160(to), amount)
    @classmethod
    def token_mint(cls, tid, to, amount):
        return cls._pack(SLOp.TOKEN_MINT, tid, _sl_to_h160(to), amount)
    @classmethod
    def token_burn(cls, tid, amount):
        return cls._pack(SLOp.TOKEN_BURN, tid, amount)
    @classmethod
    def token_approve(cls, tid, spender, amount):
        return cls._pack(SLOp.TOKEN_APPROVE, tid, _sl_to_h160(spender), amount)
    @classmethod
    def token_transfer_from(cls, tid, owner, to, amount):
        return cls._pack(SLOp.TOKEN_TRANSFER_FROM, tid, _sl_to_h160(owner), _sl_to_h160(to), amount)
    @classmethod
    def nft_collection(cls, symbol):
        return cls._pack(SLOp.NFT_COLLECTION, cls._t(symbol.upper(), 8))
    @classmethod
    def nft_mint(cls, coll, to, meta_hash32: bytes):
        if len(meta_hash32) != 32:
            raise ValueError("metadata hash must be 32 bytes")
        return cls._pack(SLOp.NFT_MINT, coll, _sl_to_h160(to), meta_hash32)
    @classmethod
    def nft_transfer(cls, coll, token_id, to):
        return cls._pack(SLOp.NFT_TRANSFER, coll, token_id, _sl_to_h160(to))
    @classmethod
    def dex_create(cls, tok_a, tok_b, amt_a, amt_b):
        return cls._pack(SLOp.DEX_CREATE, tok_a, tok_b, amt_a, amt_b)
    @classmethod
    def dex_add(cls, pool, amt_a, amt_b, min_lp=0):
        return cls._pack(SLOp.DEX_ADD, pool, amt_a, amt_b, min_lp)
    @classmethod
    def dex_remove(cls, pool, lp, min_a=0, min_b=0):
        return cls._pack(SLOp.DEX_REMOVE, pool, lp, min_a, min_b)
    @classmethod
    def dex_swap(cls, pool, a_to_b: bool, amount_in, min_out=0):
        return cls._pack(SLOp.DEX_SWAP, pool, 1 if a_to_b else 0, amount_in, min_out)
    @classmethod
    def gov_propose(cls, tid, param, value, desc_hash32: bytes = b'\x00' * 32):
        return cls._pack(SLOp.GOV_PROPOSE, tid, cls._t(param, 16), value, desc_hash32)
    @classmethod
    def gov_vote(cls, proposal, choice):          # 1 yes, 2 no, 3 abstain
        return cls._pack(SLOp.GOV_VOTE, proposal, choice)
    @classmethod
    def stake_register(cls, tid, commission_pct, amount, moniker):
        return cls._pack(SLOp.STAKE_REGISTER, tid, commission_pct, amount, cls._t(moniker, 16))
    @classmethod
    def stake_delegate(cls, tid, validator, amount):
        return cls._pack(SLOp.STAKE_DELEGATE, tid, _sl_to_h160(validator), amount)
    @classmethod
    def stake_undelegate(cls, tid, validator, amount):
        return cls._pack(SLOp.STAKE_UNDELEGATE, tid, _sl_to_h160(validator), amount)
    @classmethod
    def stake_claim(cls, tid):
        return cls._pack(SLOp.STAKE_CLAIM, tid)
    @classmethod
    def stake_fund(cls, tid, amount):
        return cls._pack(SLOp.STAKE_FUND, tid, amount)

    @staticmethod
    def decode(payload: bytes):
        """-> (op, fields tuple) or None when not a valid layer payload."""
        if len(payload) < 3 or payload[:2] != SL_MAGIC:
            return None
        fmt = _SL_FORMATS.get(payload[2])
        if fmt is None or len(payload) - 3 != struct.calcsize(fmt):
            return None
        return payload[2], struct.unpack(fmt, payload[3:])


# [v10.19] dead class StateTxBuilder removed from host - live copy is wired by group 63 (nebula_group63.py)


# ── engines built on the revived classes (made deterministic / exact) ────
class _Tok20(NBL20TokenAdv):
    """NBL20TokenAdv with the event log switched off (state stays small and
    copyable) and with atomic transfer_from + its own supply cap."""
    def _emit(self, event, args, height):
        pass

    def mint(self, to_addr, amount, caller="", height=0):
        if amount <= 0:
            return False, "Amount must be positive"
        if caller and caller != self.owner:
            return False, "Only owner can mint"
        if self.total_supply + amount > SL_MAX_AMOUNT:
            return False, "Exceeds max token supply"
        self._balances[to_addr] = self._balances.get(to_addr, 0) + amount
        self.total_supply += amount
        return True, "OK"

    def transfer_from(self, caller, from_addr, to_addr, amount, height=0):
        if amount <= 0:
            return False, "Amount must be positive"
        if from_addr == to_addr:
            return False, "Cannot transfer to self"
        if self._allowances.get(from_addr, {}).get(caller, 0) < amount:
            return False, "Insufficient allowance"
        if self._balances.get(from_addr, 0) < amount:
            return False, "Insufficient balance"
        self._allowances[from_addr][caller] -= amount
        return self.transfer(from_addr, to_addr, amount, height)


class _Nft721(NBL721Token):
    def _emit(self, event, args, height):
        pass


class AMMPoolExact(AMMPool):
    """AMMPool with exact integer liquidity maths (the original used floats +
    math.sqrt, which can leak value through rounding)."""

    def add_liquidity(self, amount_a: int, amount_b: int):
        p = self.pool
        if amount_a <= 0 or amount_b <= 0:
            return 0, 0, 0
        if p.reserve_a == 0 or p.reserve_b == 0 or p.lp_supply == 0:
            lp = _v109_isqrt(amount_a * amount_b)
            p.reserve_a += amount_a; p.reserve_b += amount_b; p.lp_supply += lp
            return amount_a, amount_b, lp
        b_opt = amount_a * p.reserve_b // p.reserve_a
        if b_opt <= amount_b:
            use_a, use_b = amount_a, b_opt
        else:
            use_a, use_b = amount_b * p.reserve_a // p.reserve_b, amount_b
        lp = min(use_a * p.lp_supply // p.reserve_a, use_b * p.lp_supply // p.reserve_b)
        if lp <= 0 or use_a <= 0 or use_b <= 0:
            return 0, 0, 0
        p.reserve_a += use_a; p.reserve_b += use_b; p.lp_supply += lp
        return use_a, use_b, lp

    def remove_liquidity(self, lp_amount: int):
        p = self.pool
        if lp_amount <= 0 or lp_amount > p.lp_supply:
            return 0, 0
        out_a = p.reserve_a * lp_amount // p.lp_supply
        out_b = p.reserve_b * lp_amount // p.lp_supply
        p.reserve_a -= out_a; p.reserve_b -= out_b; p.lp_supply -= lp_amount
        return out_a, out_b


class _SLProposal:
    def __init__(self, pid, tid, proposer, param, value, desc, start, end, snapshot):
        self.pid, self.tid, self.proposer = pid, tid, proposer
        self.param, self.value, self.desc = param, value, desc
        self.start, self.end = start, end
        self.snapshot = snapshot
        self.total_weight = sum(snapshot.values())
        self.yes = self.no = self.abstain = 0
        self.voters: Dict[str, int] = {}
        self.status = 'active'

    def finalize(self):
        cast = self.yes + self.no + self.abstain
        quorum = cast * 10_000 >= SL_GOV_QUORUM_BP * self.total_weight
        passed = (quorum and self.yes > 0 and
                  self.yes * 100 >= SL_GOV_PASS_PCT * (self.yes + self.no))
        self.status = 'passed' if passed else 'failed'

    def to_dict(self):
        return {'id': self.pid, 'token': self.tid, 'proposer': self.proposer,
                'param': self.param, 'value': self.value, 'status': self.status,
                'start': self.start, 'end': self.end, 'yes': self.yes, 'no': self.no,
                'abstain': self.abstain, 'total_weight': self.total_weight,
                'voters': len(self.voters)}


class _SLStaking:
    """Token staking for one layer token (all integer maths)."""
    def __init__(self, tid):
        self.tid = tid
        self.validators: Dict[str, dict] = {}
        self.unbonding: List[dict] = []
        self.pending: Dict[str, int] = {}
        self.reward_pool = 0
        self.total_staked = 0
        self.epoch = 0


class _SLState:
    def __init__(self):
        self.tokens: Dict[int, _Tok20] = {}
        self.token_creator: Dict[int, str] = {}
        self.symbols: Dict[str, int] = {}
        self.next_token = 1
        self.colls: Dict[int, _Nft721] = {}
        self.coll_symbols: Dict[str, int] = {}
        self.next_coll = 1
        self.pools: Dict[int, Any] = {}
        self.pool_pairs: Dict[Tuple[int, int], int] = {}
        self.next_pool = 1
        self.props: Dict[int, _SLProposal] = {}
        self.next_prop = 1
        self.stakes: Dict[int, _SLStaking] = {}
        self.processed_height = 0
        self.events: List[tuple] = []


class NEBULAStateLayer:
    """Consensus-connected state layer. See the module header."""

    def __init__(self, blockchain, voting_period: int = SL_GOV_VOTING_PERIOD,
                 epoch_length: int = SL_STAKE_EPOCH, unbonding: int = SL_UNBONDING):
        self.bc = blockchain
        self.voting_period = voting_period
        self.epoch_length = epoch_length
        self.unbonding = unbonding
        self._lock = threading.RLock()
        self._st = _SLState()
        self._snaps: Dict[int, _SLState] = {}
        self._floor = -1            # snapshots <= floor were pruned
        self._stale = False
        self.actions_applied = 0
        self.actions_ignored = 0

    # ── wiring ───────────────────────────────────────────────────
    def attach(self):
        """Register with the blockchain and replay the existing chain."""
        with self.bc._lock:
            if self not in self.bc._listeners:
                self.bc._listeners.append(self)
            self.rebuild()
        return self

    def detach(self):
        with self.bc._lock:
            if self in self.bc._listeners:
                self.bc._listeners.remove(self)

    def rebuild(self):
        """Throw the state away and replay the whole main chain."""
        with self._lock:
            self._st = _SLState()
            self._snaps = {}
            self._floor = -1
            self._stale = False
            self.actions_applied = self.actions_ignored = 0
            for blk in list(self.bc._chain[1:]):
                self._apply_block(blk)

    def _fresh(self):
        if self._stale:
            with self.bc._lock:
                self.rebuild()

    def on_connect(self, block):
        with self._lock:
            if self._stale:
                return
            if block.height != self._st.processed_height + 1:
                self._stale = True
                return
            self._apply_block(block)

    def on_reorg(self, old_blocks, new_blocks, ancestor_height):
        with self._lock:
            if self._stale:
                return
            if ancestor_height < self._floor or self._st.processed_height < ancestor_height:
                self._stale = True
                return
            self._rollback_to(ancestor_height)
            for blk in new_blocks:
                self._apply_block(blk)

    # ── snapshots / undo ─────────────────────────────────────────
    def _remember(self, height):
        if height not in self._snaps:
            self._snaps[height] = _v109_copy.deepcopy(self._st)
            for h in sorted(self._snaps):
                if h <= height - SL_SNAPSHOT_KEEP:
                    del self._snaps[h]
                    self._floor = max(self._floor, h)

    def _rollback_to(self, ancestor):
        later = sorted(h for h in self._snaps if h > ancestor)
        if later:
            self._st = self._snaps[later[0]]
            for h in later:
                del self._snaps[h]
        self._st.processed_height = ancestor

    # ── block processing ────────────────────────────────────────
    def _extract(self, tx):
        """-> (sender, pubkey_bytes, op, fields) or None."""
        data_outs = [o.script_pubkey for o in tx.outputs
                     if o.script_pubkey and o.script_pubkey[0] == OP_RETURN]
        if len(data_outs) != 1:
            return None
        sc = data_outs[0]
        if len(sc) < 2 or sc[1] != len(sc) - 2:
            return None
        dec = StateActions.decode(sc[2:])
        if dec is None or not tx.inputs:
            return None
        ss = tx.inputs[0].script_sig
        try:
            sl = ss[0]
            pl = ss[1 + sl]
            pub = bytes(ss[2 + sl:2 + sl + pl])
            if pl != 33 or len(ss) != 2 + sl + pl:
                return None
        except Exception:
            return None
        return pubkey_to_address(pub), pub, dec[0], dec[1]

    def _apply_block(self, block):
        h = block.height
        acts = []
        for tx in block.transactions:
            if tx.is_coinbase:
                continue
            a = self._extract(tx)
            if a:
                acts.append((tx.txid, a))
        if acts or self._st.stakes or any(p.status == 'active' for p in self._st.props.values()):
            self._remember(h)
        for txid, (sender, pub, op, f) in acts:
            before = _v109_copy.deepcopy(self._st)
            try:
                ok, msg = self._dispatch(sender, pub, op, f, h)
            except Exception as e:           # deterministic: same input -> same failure
                self._st = before
                ok, msg = False, f"internal error: {type(e).__name__}"
            if not ok:
                self._st = before
                self.actions_ignored += 1
            else:
                self.actions_applied += 1
            self._st.events.append((h, txid[:16], _SL_NAMES.get(op, str(op)), ok, msg[:60]))
        del self._st.events[:-SL_EVENT_KEEP]
        self._tick(h)
        self._st.processed_height = h

    def _tick(self, h):
        st = self._st
        for sysm in st.stakes.values():
            tok = st.tokens[sysm.tid]
            done = [e for e in sysm.unbonding if e['done'] <= h]
            if done:
                sysm.unbonding = [e for e in sysm.unbonding if e['done'] > h]
                for e in done:
                    tok.transfer(f"stake:{sysm.tid}", e['who'], e['amount'], h)
            if self.epoch_length and h % self.epoch_length == 0 and sysm.total_staked > 0:
                self._epoch(sysm)
        for p in st.props.values():
            if p.status == 'active' and h >= p.end:
                p.finalize()

    def _epoch(self, s: _SLStaking):
        s.epoch += 1
        reward = min(s.reward_pool,
                     s.total_staked * SL_STAKE_REWARD_PCT * self.epoch_length
                     // (100 * SL_BLOCKS_PER_YEAR))
        if reward <= 0:
            return
        paid = 0
        for vaddr in sorted(s.validators):
            v = s.validators[vaddr]
            if v['total'] <= 0:
                continue
            share = reward * v['total'] // s.total_staked
            cut = share * v['commission'] // 100
            rest = share - cut
            dist = 0
            for d in sorted(v['del']):
                part = rest * v['del'][d] // v['total']
                if part:
                    s.pending[d] = s.pending.get(d, 0) + part
                    dist += part
            s.pending[vaddr] = s.pending.get(vaddr, 0) + cut
            paid += cut + dist
        s.reward_pool -= paid

    # ── action handlers ──────────────────────────────────────────
    def _dispatch(self, s, pub, op, f, h):
        st = self._st
        # ---------------- tokens ----------------
        if op == SLOp.TOKEN_CREATE:
            sym = _sl_text(f[0], 8, upper_alnum=True)
            dec, supply = f[1], f[2]
            if not sym or dec > 18 or not (0 < supply <= SL_MAX_AMOUNT):
                return False, "bad token parameters"
            if sym in st.symbols:
                return False, "symbol already exists"
            tid = st.next_token; st.next_token += 1
            st.tokens[tid] = _Tok20(sym, sym, dec, supply, s, contract_addr=f"tok{tid}")
            st.token_creator[tid] = s
            st.symbols[sym] = tid
            return True, f"token {sym} id={tid}"
        if op in (SLOp.TOKEN_TRANSFER, SLOp.TOKEN_MINT, SLOp.TOKEN_BURN, SLOp.TOKEN_APPROVE,
                  SLOp.TOKEN_TRANSFER_FROM):
            tok = st.tokens.get(f[0])
            if tok is None:
                return False, "unknown token"
            if op == SLOp.TOKEN_TRANSFER:
                return tok.transfer(s, _sl_to_addr(f[1]), f[2], h)
            if op == SLOp.TOKEN_MINT:
                return tok.mint(_sl_to_addr(f[1]), f[2], caller=s or "x", height=h)
            if op == SLOp.TOKEN_BURN:
                if f[1] <= 0:
                    return False, "Amount must be positive"
                return tok.burn(s, f[1], h)
            if op == SLOp.TOKEN_APPROVE:
                tok.approve(s, _sl_to_addr(f[1]), f[2], h)
                return True, "OK"
            return tok.transfer_from(s, _sl_to_addr(f[1]), _sl_to_addr(f[2]), f[3], h)
        # ---------------- NFT ----------------
        if op == SLOp.NFT_COLLECTION:
            sym = _sl_text(f[0], 8, upper_alnum=True)
            if not sym or sym in st.coll_symbols:
                return False, "bad or duplicate collection symbol"
            cid = st.next_coll; st.next_coll += 1
            st.colls[cid] = _Nft721(sym, sym, "", s)
            st.coll_symbols[sym] = cid
            return True, f"collection {sym} id={cid}"
        if op == SLOp.NFT_MINT:
            c = st.colls.get(f[0])
            if c is None:
                return False, "unknown collection"
            if c.owner != s:
                return False, "Only collection owner can mint"
            ok, tid = c.mint(_sl_to_addr(f[1]), None, {'meta': f[2].hex()}, h)
            return ok, f"nft {tid}"
        if op == SLOp.NFT_TRANSFER:
            c = st.colls.get(f[0])
            if c is None:
                return False, "unknown collection"
            return c.transfer(s, _sl_to_addr(f[2]), f[1], h)
        # ---------------- DEX ----------------
        if op in (SLOp.DEX_CREATE, SLOp.DEX_ADD, SLOp.DEX_REMOVE, SLOp.DEX_SWAP):
            return self._dex(s, op, f, h)
        # ---------------- governance ----------------
        if op == SLOp.GOV_PROPOSE:
            tok = st.tokens.get(f[0])
            param = _sl_text(f[1], 16)
            if tok is None or param is None:
                return False, "bad proposal"
            if tok.balance_of(s) * 10_000 < SL_GOV_PROPOSE_MIN_BP * tok.total_supply or tok.balance_of(s) == 0:
                return False, "proposer holds too little of the token"
            snap = {a: b for a, b in tok._balances.items() if b > 0 and ':' not in a}
            pid = st.next_prop; st.next_prop += 1
            st.props[pid] = _SLProposal(pid, f[0], s, param, f[2], f[3].hex(),
                                        h, h + self.voting_period, snap)
            return True, f"proposal {pid}"
        if op == SLOp.GOV_VOTE:
            p = st.props.get(f[0])
            if p is None or p.status != 'active' or h >= p.end:
                return False, "proposal not open"
            if s in p.voters:
                return False, "already voted"
            w = p.snapshot.get(s, 0)
            if w <= 0 or f[1] not in (1, 2, 3):
                return False, "no weight / bad choice"
            p.voters[s] = f[1]
            if f[1] == 1: p.yes += w
            elif f[1] == 2: p.no += w
            else: p.abstain += w
            return True, "vote counted"
        # ---------------- staking ----------------
        return self._stake(s, pub, op, f, h)

    def _pool_acct(self, pid):
        return f"pool:{pid}"

    def _dex(self, s, op, f, h):
        st = self._st
        if op == SLOp.DEX_CREATE:
            ta, tb, a, b = f
            if ta == tb or ta not in st.tokens or tb not in st.tokens:
                return False, "bad token pair"
            if not (0 < a <= SL_MAX_AMOUNT and 0 < b <= SL_MAX_AMOUNT):
                return False, "bad amounts"
            if ta > tb:
                ta, tb, a, b = tb, ta, b, a
            if (ta, tb) in st.pool_pairs:
                return False, "pool already exists"
            lp0 = _v109_isqrt(a * b)
            if lp0 <= SL_MIN_LIQUIDITY:
                return False, "initial liquidity too small"
            A, B = st.tokens[ta], st.tokens[tb]
            if A.balance_of(s) < a or B.balance_of(s) < b:
                return False, "insufficient balance"
            pid = st.next_pool; st.next_pool += 1
            acct = self._pool_acct(pid)
            A.transfer(s, acct, a, h); B.transfer(s, acct, b, h)
            pool = LiquidityPoolC(str(ta), str(tb), pool_id=pid, fee_bps=30)
            pool.reserve_a, pool.reserve_b, pool.lp_supply = a, b, lp0
            pool.lp_holders = {'burn:': SL_MIN_LIQUIDITY, s: lp0 - SL_MIN_LIQUIDITY}
            pool.tid_a, pool.tid_b = ta, tb
            st.pools[pid] = pool; st.pool_pairs[(ta, tb)] = pid
            return True, f"pool {pid}"
        pool = st.pools.get(f[0])
        if pool is None:
            return False, "unknown pool"
        A, B = st.tokens[pool.tid_a], st.tokens[pool.tid_b]
        amm = AMMPoolExact(pool)
        acct = self._pool_acct(pool.pool_id)
        if op == SLOp.DEX_ADD:
            _, a, b, min_lp = f
            ua, ub, lp = AMMPoolExact(_v109_copy.deepcopy(pool)).add_liquidity(a, b)
            if lp <= 0 or lp < min_lp:
                return False, "liquidity too small / slippage"
            if A.balance_of(s) < ua or B.balance_of(s) < ub:
                return False, "insufficient balance"
            amm.add_liquidity(a, b)
            A.transfer(s, acct, ua, h); B.transfer(s, acct, ub, h)
            pool.lp_holders[s] = pool.lp_holders.get(s, 0) + lp
            return True, f"added lp={lp}"
        if op == SLOp.DEX_REMOVE:
            _, lp, min_a, min_b = f
            if lp <= 0 or pool.lp_holders.get(s, 0) < lp:
                return False, "not enough LP"
            oa, ob = AMMPoolExact(_v109_copy.deepcopy(pool)).remove_liquidity(lp)
            if oa < min_a or ob < min_b or (oa == 0 and ob == 0):
                return False, "slippage / dust"
            amm.remove_liquidity(lp)
            pool.lp_holders[s] -= lp
            if pool.lp_holders[s] == 0:
                del pool.lp_holders[s]
            if oa: A.transfer(acct, s, oa, h)
            if ob: B.transfer(acct, s, ob, h)
            return True, f"removed {oa}/{ob}"
        # swap
        _, direction, amt_in, min_out = f
        a_to_b = direction == 1
        tin, tout = (A, B) if a_to_b else (B, A)
        if amt_in <= 0 or tin.balance_of(s) < amt_in:
            return False, "bad amount / insufficient balance"
        out = amm.get_amount_out(amt_in, a_to_b)
        if out <= 0 or out < min_out:
            return False, "slippage / zero output"
        amm.swap(amt_in, a_to_b)
        tin.transfer(s, acct, amt_in, h)
        tout.transfer(acct, s, out, h)
        return True, f"swapped out={out}"

    def _stake(self, s, pub, op, f, h):
        st = self._st
        tid = f[0]
        tok = st.tokens.get(tid)
        if tok is None:
            return False, "unknown token"
        unit = 10 ** tok.decimals
        cust, rew = f"stake:{tid}", f"srew:{tid}"
        if op == SLOp.STAKE_REGISTER:
            _, comm, amt, mon = f
            moniker = _sl_text(mon, 16)
            if moniker is None or comm > 100 or amt < 100 * unit:
                return False, "bad validator parameters (min 100 units)"
            sysm = st.stakes.get(tid)
            if sysm and s in sysm.validators:
                return False, "already registered"
            if tok.balance_of(s) < amt:
                return False, "insufficient balance"
            if sysm is None:
                sysm = st.stakes[tid] = _SLStaking(tid)
            tok.transfer(s, cust, amt, h)
            sysm.validators[s] = {'moniker': moniker, 'commission': comm,
                                  'pubkey': pub.hex(), 'del': {s: amt}, 'total': amt}
            sysm.total_staked += amt
            return True, "validator registered"
        sysm = st.stakes.get(tid)
        if op == SLOp.STAKE_FUND:
            amt = f[1]
            if sysm is None or amt <= 0 or tok.balance_of(s) < amt:
                return False, "no staking system / bad amount"
            tok.transfer(s, rew, amt, h)
            sysm.reward_pool += amt
            return True, "reward pool funded"
        if sysm is None:
            return False, "no staking system for this token"
        if op == SLOp.STAKE_CLAIM:
            amt = sysm.pending.get(s, 0)
            if amt <= 0:
                return False, "nothing to claim"
            del sysm.pending[s]
            tok.transfer(rew, s, amt, h)
            return True, f"claimed {amt}"
        v = sysm.validators.get(_sl_to_addr(f[1]))
        amt = f[2]
        if v is None or amt <= 0:
            return False, "unknown validator / bad amount"
        va = _sl_to_addr(f[1])
        if op == SLOp.STAKE_DELEGATE:
            if amt < unit or tok.balance_of(s) < amt:
                return False, "below minimum / insufficient balance"
            if s not in v['del'] and len(v['del']) >= SL_MAX_DELEGATORS:
                return False, "validator full"
            tok.transfer(s, cust, amt, h)
            v['del'][s] = v['del'].get(s, 0) + amt
            v['total'] += amt; sysm.total_staked += amt
            return True, "delegated"
        # undelegate
        have = v['del'].get(s, 0)
        if have < amt:
            return False, "insufficient delegation"
        if s == va and 0 < have - amt < 100 * unit:
            return False, "validator self-stake must stay >= 100 units (or 0)"
        v['del'][s] = have - amt
        if v['del'][s] == 0:
            del v['del'][s]
        v['total'] -= amt; sysm.total_staked -= amt
        sysm.unbonding.append({'who': s, 'val': va, 'amount': amt, 'done': h + self.unbonding})
        return True, f"unbonding until block {h + self.unbonding}"

    # ── read API ─────────────────────────────────────────────────
    def token_info(self, tid):
        self._fresh()
        with self._lock:
            t = self._st.tokens.get(tid)
            return None if t is None else {'id': tid, 'symbol': t.symbol, 'decimals': t.decimals,
                                           'total_supply': t.total_supply, 'owner': t.owner,
                                           'holders': t.holders()}

    def balance_of(self, tid, address):
        self._fresh()
        with self._lock:
            t = self._st.tokens.get(tid)
            return 0 if t is None else t.balance_of(address)

    def token_id(self, symbol):
        self._fresh()
        with self._lock:
            return self._st.symbols.get(symbol.upper())

    def nft_owner(self, coll, token_id):
        self._fresh()
        with self._lock:
            c = self._st.colls.get(coll)
            return None if c is None else c.owner_of(token_id)

    def nft_collection_id(self, symbol):
        self._fresh()
        with self._lock:
            return self._st.coll_symbols.get(symbol.upper())

    def pool_info(self, pid):
        self._fresh()
        with self._lock:
            p = self._st.pools.get(pid)
            if p is None:
                return None
            return {'id': pid, 'token_a': p.tid_a, 'token_b': p.tid_b, 'reserve_a': p.reserve_a,
                    'reserve_b': p.reserve_b, 'lp_supply': p.lp_supply, 'swaps': p.swaps_count,
                    'fee_bps': p.fee_bps}

    def pool_id(self, tok_a, tok_b):
        self._fresh()
        with self._lock:
            return self._st.pool_pairs.get((min(tok_a, tok_b), max(tok_a, tok_b)))

    def lp_balance(self, pid, address):
        self._fresh()
        with self._lock:
            p = self._st.pools.get(pid)
            return 0 if p is None else p.lp_holders.get(address, 0)

    def quote_swap(self, pid, a_to_b, amount_in):
        self._fresh()
        with self._lock:
            p = self._st.pools.get(pid)
            return 0 if p is None else AMMPoolExact(p).get_amount_out(amount_in, a_to_b)

    def proposal(self, pid):
        self._fresh()
        with self._lock:
            p = self._st.props.get(pid)
            return None if p is None else p.to_dict()

    def validators(self, tid):
        self._fresh()
        with self._lock:
            s = self._st.stakes.get(tid)
            if s is None:
                return []
            return [{'address': a, 'moniker': v['moniker'], 'commission': v['commission'],
                     'total': v['total'], 'delegators': len(v['del'])}
                    for a, v in sorted(s.validators.items())]

    def staking_info(self, tid):
        self._fresh()
        with self._lock:
            s = self._st.stakes.get(tid)
            return None if s is None else {'total_staked': s.total_staked, 'reward_pool': s.reward_pool,
                                           'epoch': s.epoch, 'unbonding': len(s.unbonding),
                                           'pending_total': sum(s.pending.values())}

    def pending_rewards(self, tid, address):
        self._fresh()
        with self._lock:
            s = self._st.stakes.get(tid)
            return 0 if s is None else s.pending.get(address, 0)

    def events(self, n=20):
        self._fresh()
        with self._lock:
            return list(self._st.events[-n:])

    def stats(self):
        self._fresh()
        with self._lock:
            st = self._st
            return {'height': st.processed_height, 'tokens': len(st.tokens),
                    'nft_collections': len(st.colls), 'pools': len(st.pools),
                    'proposals': len(st.props), 'staking_systems': len(st.stakes),
                    'actions_applied': self.actions_applied,
                    'actions_ignored': self.actions_ignored,
                    'state_hash': self._hash_locked()}

    def _hash_locked(self):
        st = self._st
        doc = {
            'tok': {str(i): [t.symbol, t.decimals, t.total_supply, t.owner,
                             sorted((a, b) for a, b in t._balances.items() if b),
                             sorted((o, sorted((sp, v) for sp, v in d.items() if v))
                                    for o, d in t._allowances.items() if d)]
                    for i, t in st.tokens.items()},
            'nft': {str(i): [c.symbol, c.owner, sorted(c._owners.items()),
                             sorted((k, sorted(m.items())) for k, m in c._metadata.items())]
                    for i, c in st.colls.items()},
            'pool': {str(i): [p.tid_a, p.tid_b, p.reserve_a, p.reserve_b, p.lp_supply,
                              sorted(p.lp_holders.items()), p.swaps_count]
                     for i, p in st.pools.items()},
            'gov': {str(i): [p.tid, p.proposer, p.param, p.value, p.desc, p.start, p.end,
                             p.yes, p.no, p.abstain, p.status, sorted(p.voters.items()),
                             sorted(p.snapshot.items())]
                    for i, p in st.props.items()},
            'stk': {str(t): [s.total_staked, s.reward_pool, s.epoch, sorted(s.pending.items()),
                             sorted((a, v['commission'], v['total'], sorted(v['del'].items()))
                                    for a, v in s.validators.items()),
                             sorted((e['who'], e['val'], e['amount'], e['done']) for e in s.unbonding)]
                    for t, s in st.stakes.items()},
            'next': [st.next_token, st.next_coll, st.next_pool, st.next_prop],
        }
        return hashlib.sha256(json.dumps(doc, sort_keys=True, default=str).encode()).hexdigest()

    def state_hash(self):
        self._fresh()
        with self._lock:
            return self._hash_locked()

    def check_invariants(self):
        """Self-audit: custody accounts must exactly match the engines' books.
        Returns a list of problems (empty list = consistent)."""
        self._fresh()
        problems = []
        with self._lock:
            st = self._st
            for pid, p in st.pools.items():
                a, b = st.tokens[p.tid_a], st.tokens[p.tid_b]
                acct = self._pool_acct(pid)
                if a.balance_of(acct) != p.reserve_a or b.balance_of(acct) != p.reserve_b:
                    problems.append(f"pool {pid}: reserves != custody balance")
                if sum(p.lp_holders.values()) != p.lp_supply:
                    problems.append(f"pool {pid}: LP holders != LP supply")
            for tid, s in st.stakes.items():
                t = st.tokens[tid]
                bonded = s.total_staked + sum(e['amount'] for e in s.unbonding)
                if t.balance_of(f"stake:{tid}") != bonded:
                    problems.append(f"staking {tid}: custody != staked+unbonding")
                if t.balance_of(f"srew:{tid}") != s.reward_pool + sum(s.pending.values()):
                    problems.append(f"staking {tid}: reward custody != pool+pending")
            for tid, t in st.tokens.items():
                if sum(t._balances.values()) != t.total_supply:
                    problems.append(f"token {tid}: balances != supply")
        return problems


# ================================================================
#  v10.9  GENESIS MINER  (choose the launch difficulty)
# ================================================================
def mine_genesis(bits: int = None, progress: bool = True):
    """Search the nonce for a genesis block with the given compact `bits`.
    Prints/returns the constants to paste into the file. Changing GENESIS_BITS changes the
    genesis hash = a NEW chain identity (do it BEFORE launch, never after)."""
    bits = GENESIS_BITS if bits is None else bits
    cb = build_genesis_coinbase()   # [v10.25] same transaction the node builds (includes the premine output)
    root = MerkleTree.compute_root([cb.txid])
    hdr = BlockHeader(CHAIN_VERSION, '0' * 64, root, GENESIS_TIMESTAMP, bits, 0, 0)
    if bits_to_target(bits) > MAX_TARGET:
        raise ValueError("bits easier than the allowed minimum difficulty (INITIAL_BITS)")
    t0 = time.time()
    if _NBL_ACCEL_OK:
        h76, tgt = hdr.serialize()[:76], bits_to_target(bits).to_bytes(32, 'big')
        found = _ctypes.c_uint32(0); hashes = _ctypes.c_uint64(0)
        n = 0
        while n <= 0xFFFFFFFF:
            end = min(n + 0xFFFFF, 0xFFFFFFFF)
            if _NBL_C_MINE(h76, tgt, _ctypes.c_uint32(n), _ctypes.c_uint32(end),
                           _ctypes.byref(found), _ctypes.byref(hashes)) == 1:
                hdr.nonce = found.value
                break
            n = end + 1
            if progress and (n >> 20) % 256 == 0:
                print(f"   ... {n:,} nonces tried", flush=True)
        else:
            raise RuntimeError("no nonce in 32-bit range: change GENESIS_TIMESTAMP and retry")
    else:
        while not hdr.meets_target():
            hdr.nonce += 1
            if hdr.nonce > 0xFFFFFFFF:
                raise RuntimeError("no nonce in 32-bit range")
    assert hdr.meets_target()
    print(f"\n  Genesis mined in {time.time() - t0:.1f}s\n"
          f"  GENESIS_BITS  = {hex(bits)}\n  GENESIS_NONCE = {hdr.nonce}\n"
          f"  genesis hash  = {hdr.hash()}\n"
          f"  expected blocks/hour at 1 MH/s: {3600 * 1e6 * bits_to_target(bits) / 2 ** 256:.2f}")
    return hdr.nonce, hdr.hash()


# ============================================================================
#  NEBULA v10.19 - live chain bootstrap (groups 27..63)
#  The dead classes that used to sit in this file now live in the group modules
#  nebula_group27 .. nebula_group63 (next to this file). They are attached to
#  every NEBULAFullNode by nebula_chain.install_all(). A missing or broken group
#  never stops the node (same rule as group 5).
# ============================================================================
CHAIN_REPORT = {}


def _nebula_chain_bootstrap():
    """Install groups 27..63 + hardening on this module. Never raises."""
    import importlib, os as _os, sys as _sys
    here = _os.path.dirname(_os.path.abspath(__file__))
    if here not in _sys.path:
        _sys.path.insert(0, here)
    me = _sys.modules.get(__name__)
    # the group modules import the host under this historical name
    _sys.modules.setdefault("nebula_v10_11", me)
    if __name__ != "__main__":
        _sys.modules.setdefault("nebula_v10_19", me)
        _sys.modules.setdefault("nebula_v10_20", me)
        _sys.modules.setdefault("nebula_v10_21", me)
        _sys.modules.setdefault("nebula_v10_22", me)
    if _os.environ.get("NEBULA_DISABLE_CHAIN") == "1":
        CHAIN_REPORT["state"] = "disabled by NEBULA_DISABLE_CHAIN=1"
        return CHAIN_REPORT
    try:
        chain = importlib.import_module("nebula_chain")
    except Exception as exc:                    # chain files not next to this file
        CHAIN_REPORT["state"] = "chain not loaded: %s: %s" % (type(exc).__name__, exc)
        try:
            log.warning("NEBULA chain not loaded: %s", CHAIN_REPORT["state"])
        except Exception:
            _NB_SWALLOW_LOG.debug("swallowed Exception in _nebula_chain_bootstrap", exc_info=True)
        return CHAIN_REPORT
    try:
        CHAIN_REPORT["pre"] = chain.preflight(me)
        CHAIN_REPORT["install"] = chain.install_all(me)
        CHAIN_REPORT["state"] = "installed"
    except Exception as exc:
        CHAIN_REPORT["state"] = "chain install failed: %s: %s" % (type(exc).__name__, exc)
    try:
        CHAIN_REPORT["bound"] = _nebula_bind_live_classes(me, here)
    except Exception as exc:
        CHAIN_REPORT["bound_error"] = "%s: %s" % (type(exc).__name__, exc)
    return CHAIN_REPORT


def _nebula_bind_live_classes(me, here):
    """Publish every live group class on this module under its own name, so that
    code that still says NEBULA.<ClassName> (tests, scripts, plugins) finds the
    SAME object the chain layers use. Never overwrites a name this file defines."""
    import glob as _glob, importlib as _il, inspect as _inspect, os as _os
    bound = {}
    stems = sorted(_os.path.splitext(_os.path.basename(p))[0]
                   for p in _glob.glob(_os.path.join(here, "nebula_group[0-9]*.py")))
    for stem in stems:
        if stem.endswith("_install") or stem.endswith("_chain"):
            continue
        try:
            mod = _il.import_module(stem)
        except Exception:
            continue                       # a broken group never blocks the others
        for k, v in vars(mod).items():
            if (not k.startswith("_") and _inspect.isclass(v)
                    and v.__module__ == mod.__name__ and not hasattr(me, k)):
                setattr(me, k, v)
                bound[k] = stem
    return bound


_nebula_chain_bootstrap()


if __name__ == '__main__':
    _nebula_main()
